pub fn errorCode(err: anyerror) []const u8 {
    return switch (err) {
        error.Parse => "parse",
        error.Name => "name",
        error.Type => "type",
        error.Arity => "arity",
        error.Unsupported => "nyi",
        else => "internal",
    };
}

