fn hostCompareSummaryMetadata(summary: HostCompareSummary) BitDenseMetadata {
    return .{
        .flags = host_dense_flag_normalized | orderFlagsFromMonotonic(summary.asc != 0, summary.dsc != 0),
        .range = .{
            .min = if (summary.saw_one == 0) 0 else if (summary.saw_zero != 0) 0 else 1,
            .max = if (summary.saw_one != 0) 1 else 0,
        },
    };
}

fn hostCompareSummaryEmpty() HostCompareSummary {
    return .{
        .saw_one = 0,
        .saw_zero = 0,
        .asc = 1,
        .dsc = 1,
        .has_prev = 0,
        .first = 0,
        .prev_last = 0,
    };
}

fn hostCompareSummaryNoteWord(summary: *HostCompareSummary, raw_word: u64, active: usize) void {
    if (active == 0) return;
    const active_mask = bitLowMask(active);
    const word = raw_word & active_mask;
    if (word != 0) summary.saw_one = 1;
    if (word != active_mask) summary.saw_zero = 1;

    if (summary.asc != 0 or summary.dsc != 0) {
        const first: u8 = @intCast(word & 1);
        if (summary.has_prev != 0) {
            if (summary.prev_last > first) summary.asc = 0;
            if (summary.prev_last < first) summary.dsc = 0;
        } else {
            summary.has_prev = 1;
            summary.first = first;
        }
    } else if (summary.has_prev == 0) {
        summary.has_prev = 1;
        summary.first = @intCast(word & 1);
    }

    if (active > 1 and (summary.asc != 0 or summary.dsc != 0) and word != 0 and word != active_mask) {
        const transition_mask = bitLowMask(active - 1);
        if (((word & ~(word >> 1)) & transition_mask) != 0) summary.asc = 0;
        if ((((~word) & (word >> 1)) & transition_mask) != 0) summary.dsc = 0;
    }
    summary.prev_last = @intCast((word >> @intCast(active - 1)) & 1);
}

fn hostCompareScalarValueOp(comptime T: type, comptime op: BuiltinId, left: T, right: T) bool {
    return switch (op) {
        .equal => left == right,
        .less => left < right,
        .more => left > right,
        else => unreachable,
    };
}

fn hostCompareVectorMaskOp(
    comptime T: type,
    comptime lane_count: usize,
    comptime op: BuiltinId,
    left: @Vector(lane_count, T),
    right: @Vector(lane_count, T),
) @Int(.unsigned, lane_count) {
    const matches = switch (op) {
        .equal => left == right,
        .less => left < right,
        .more => left > right,
        else => unreachable,
    };
    return @bitCast(matches);
}

fn hostCompareIntWideType(comptime LeftT: type, comptime RightT: type) type {
    const size = @max(@sizeOf(LeftT), @sizeOf(RightT));
    return switch (size) {
        1 => i8,
        2 => i16,
        4 => i32,
        8 => i64,
        else => @compileError("unsupported compare integer width"),
    };
}

fn hostCompareIntLoadAs(comptime InT: type, comptime OutT: type, comptime lane_count: usize, items: []const InT, start: usize) @Vector(lane_count, OutT) {
    const InVec = @Vector(lane_count, InT);
    const in_vec: InVec = items[start..][0..lane_count].*;
    return @intCast(in_vec);
}

fn denseIntLoadAsFloatVec(comptime T: type, comptime FloatT: type, comptime lane_count: usize, items: []const T, start: usize) @Vector(lane_count, FloatT) {
    if (comptime @sizeOf(T) <= @sizeOf(i32)) {
        const IntVec = @Vector(lane_count, T);
        const WideVec = @Vector(lane_count, i32);
        const FloatVec = @Vector(lane_count, FloatT);
        const narrow: IntVec = items[start..][0..lane_count].*;
        const wide: WideVec = @intCast(narrow);
        return @as(FloatVec, @floatFromInt(wide));
    }
    var values: [lane_count]FloatT = undefined;
    inline for (0..lane_count) |lane| {
        values[lane] = @floatFromInt(items[start + lane]);
    }
    return values;
}

fn hostCompareIntFloatVec(comptime T: type, comptime lane_count: usize, items: []const T, start: usize) @Vector(lane_count, f64) {
    return denseIntLoadAsFloatVec(T, f64, lane_count, items, start);
}

fn hostCompareIntFloatVecFast(comptime T: type, comptime lane_count: usize, items: []const T, start: usize) @Vector(lane_count, f64) {
    return hostCompareIntFloatVec(T, lane_count, items, start);
}

fn fillZigHostCompareMixedIntArraysTypedOp(comptime LeftT: type, comptime RightT: type, comptime op: BuiltinId, out: *HostBitAlloc, left: []const LeftT, right: []const RightT) HostCompareSummary {
    return fillDenseMixedIntCompareSources(LeftT, RightT, out, op, .{ .array = left }, .{ .array = right }, left.len) orelse unreachable;
}

fn fillZigHostCompareIntArraysOp(comptime op: BuiltinId, out: *HostBitAlloc, left: HostIntArrayView, right: HostIntArrayView) ?HostCompareSummary {
    if (hostIntArrayViewLen(left) != hostIntArrayViewLen(right)) return null;
    return switch (left) {
        .int8 => |left_items| switch (right) {
            .int8 => |right_items| fillDenseIntCompareSources(i8, out, op, .{ .array = left_items }, .{ .array = right_items }, left_items.len),
            .int16 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i8, i16, op, out, left_items, right_items),
            .int32 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i8, i32, op, out, left_items, right_items),
            .int64 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i8, i64, op, out, left_items, right_items),
            .bit => null,
        },
        .int16 => |left_items| switch (right) {
            .int8 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i16, i8, op, out, left_items, right_items),
            .int16 => |right_items| fillDenseIntCompareSources(i16, out, op, .{ .array = left_items }, .{ .array = right_items }, left_items.len),
            .int32 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i16, i32, op, out, left_items, right_items),
            .int64 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i16, i64, op, out, left_items, right_items),
            .bit => null,
        },
        .int32 => |left_items| switch (right) {
            .int8 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i32, i8, op, out, left_items, right_items),
            .int16 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i32, i16, op, out, left_items, right_items),
            .int32 => |right_items| fillDenseIntCompareSources(i32, out, op, .{ .array = left_items }, .{ .array = right_items }, left_items.len),
            .int64 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i32, i64, op, out, left_items, right_items),
            .bit => null,
        },
        .int64 => |left_items| switch (right) {
            .int8 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i64, i8, op, out, left_items, right_items),
            .int16 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i64, i16, op, out, left_items, right_items),
            .int32 => |right_items| fillZigHostCompareMixedIntArraysTypedOp(i64, i32, op, out, left_items, right_items),
            .int64 => |right_items| fillDenseIntCompareSources(i64, out, op, .{ .array = left_items }, .{ .array = right_items }, left_items.len),
            .bit => null,
        },
        .bit => null,
    };
}

fn fillZigHostCompareIntScalarOp(comptime op: BuiltinId, comptime scalar_left: bool, out: *HostBitAlloc, items: HostIntArrayView, scalar: i64) ?HostCompareSummary {
    return switch (items) {
        .int8 => |view| blk: {
            const scalar_source = DenseResolvedSource(i8){ .scalar = std.math.cast(i8, scalar) orelse return null };
            const item_source = DenseResolvedSource(i8){ .array = view };
            break :blk fillDenseIntCompareSources(i8, out, op, if (scalar_left) scalar_source else item_source, if (scalar_left) item_source else scalar_source, view.len);
        },
        .int16 => |view| blk: {
            const scalar_source = DenseResolvedSource(i16){ .scalar = std.math.cast(i16, scalar) orelse return null };
            const item_source = DenseResolvedSource(i16){ .array = view };
            break :blk fillDenseIntCompareSources(i16, out, op, if (scalar_left) scalar_source else item_source, if (scalar_left) item_source else scalar_source, view.len);
        },
        .int32 => |view| blk: {
            const scalar_source = DenseResolvedSource(i32){ .scalar = std.math.cast(i32, scalar) orelse return null };
            const item_source = DenseResolvedSource(i32){ .array = view };
            break :blk fillDenseIntCompareSources(i32, out, op, if (scalar_left) scalar_source else item_source, if (scalar_left) item_source else scalar_source, view.len);
        },
        .int64 => |view| blk: {
            const scalar_source = DenseResolvedSource(i64){ .scalar = scalar };
            const item_source = DenseResolvedSource(i64){ .array = view };
            break :blk fillDenseIntCompareSources(i64, out, op, if (scalar_left) scalar_source else item_source, if (scalar_left) item_source else scalar_source, view.len);
        },
        .bit => null,
    };
}

fn fillZigHostCompareIntFloatArrayOp(comptime op: BuiltinId, comptime int_left: bool, out: *HostBitAlloc, int_items: HostIntArrayView, float_items: []const f64) ?HostCompareSummary {
    if (hostIntArrayViewLen(int_items) != float_items.len) return null;
    const float_source = DenseFloat64PromotedSource{ .array64 = float_items };
    return switch (int_items) {
        .int8 => |items| fillDenseIntFloatCompareSources(i8, int_left, out, op, .{ .array = items }, float_source, items.len),
        .int16 => |items| fillDenseIntFloatCompareSources(i16, int_left, out, op, .{ .array = items }, float_source, items.len),
        .int32 => |items| fillDenseIntFloatCompareSources(i32, int_left, out, op, .{ .array = items }, float_source, items.len),
        .int64 => |items| fillDenseIntFloatCompareSources(i64, int_left, out, op, .{ .array = items }, float_source, items.len),
        .bit => null,
    };
}

fn fillZigHostCompareFloatArraysOp(comptime T: type, comptime op: BuiltinId, out: *HostBitAlloc, left: []const T, right: []const T) ?HostCompareSummary {
    if (left.len != right.len) return null;
    return fillDenseFloatCompareSources(T, out, op, .{ .array = left }, .{ .array = right }, left.len);
}

fn initByteMaskSelectTable() [256]ByteMaskSelect {
    @setEvalBranchQuota(4_000);
    var table: [256]ByteMaskSelect = undefined;
    for (0..table.len) |mask| {
        var offsets = @as([8]u8, @splat(0));
        var count: u8 = 0;
        for (0..8) |bit_idx| {
            if (((mask >> bit_idx) & 1) != 0) {
                offsets[@as(usize, count)] = @intCast(bit_idx);
                count += 1;
            }
        }
        table[mask] = .{
            .count = count,
            .offsets = offsets,
        };
    }
    return table;
}

const byte_mask_select_table = initByteMaskSelectTable();

fn copyStringMaskByteInBounds(out: []u8, out_idx: *usize, bytes: []const u8, source_base: usize, mask_byte: u8) void {
    const entry = byte_mask_select_table[mask_byte];
    if (entry.count == 0) return;

    const dst_base = out_idx.*;
    const dst: [*]u8 = out.ptr + dst_base;
    const src: [*]const u8 = bytes.ptr + source_base;
    const offsets = entry.offsets;
    switch (entry.count) {
        1 => dst[0] = src[@as(usize, offsets[0])],
        2 => {
            dst[0] = src[@as(usize, offsets[0])];
            dst[1] = src[@as(usize, offsets[1])];
        },
        3 => {
            dst[0] = src[@as(usize, offsets[0])];
            dst[1] = src[@as(usize, offsets[1])];
            dst[2] = src[@as(usize, offsets[2])];
        },
        4 => {
            dst[0] = src[@as(usize, offsets[0])];
            dst[1] = src[@as(usize, offsets[1])];
            dst[2] = src[@as(usize, offsets[2])];
            dst[3] = src[@as(usize, offsets[3])];
        },
        5 => {
            dst[0] = src[@as(usize, offsets[0])];
            dst[1] = src[@as(usize, offsets[1])];
            dst[2] = src[@as(usize, offsets[2])];
            dst[3] = src[@as(usize, offsets[3])];
            dst[4] = src[@as(usize, offsets[4])];
        },
        6 => {
            dst[0] = src[@as(usize, offsets[0])];
            dst[1] = src[@as(usize, offsets[1])];
            dst[2] = src[@as(usize, offsets[2])];
            dst[3] = src[@as(usize, offsets[3])];
            dst[4] = src[@as(usize, offsets[4])];
            dst[5] = src[@as(usize, offsets[5])];
        },
        7 => {
            dst[0] = src[@as(usize, offsets[0])];
            dst[1] = src[@as(usize, offsets[1])];
            dst[2] = src[@as(usize, offsets[2])];
            dst[3] = src[@as(usize, offsets[3])];
            dst[4] = src[@as(usize, offsets[4])];
            dst[5] = src[@as(usize, offsets[5])];
            dst[6] = src[@as(usize, offsets[6])];
        },
        8 => @memcpy(out[dst_base..][0..8], bytes[source_base..][0..8]),
        else => unreachable,
    }
    out_idx.* = dst_base + @as(usize, entry.count);
}

fn copyStringWhereBitMaskBytesInBounds(out: []u8, bytes: []const u8, mask: HostBitSlice) void {
    var out_idx: usize = 0;
    for (mask.words, 0..) |_, word_idx| {
        const word_base = word_idx * host_bit_word_bits;
        const active = bitWordActiveLen(mask.len, word_idx, mask.words.len);
        const word = bitWordMasked(mask.words, mask.len, word_idx);
        var bit_idx: usize = 0;
        while (bit_idx + 8 <= active) : (bit_idx += 8) {
            const mask_byte: u8 = @truncate((word >> @intCast(bit_idx)) & 0xff);
            copyStringMaskByteInBounds(out, &out_idx, bytes, word_base + bit_idx, mask_byte);
        }
        if (bit_idx < active) {
            const tail_bits = active - bit_idx;
            const mask_byte: u8 = @truncate((word >> @intCast(bit_idx)) & bitLowMask(tail_bits));
            copyStringMaskByteInBounds(out, &out_idx, bytes, word_base + bit_idx, mask_byte);
        }
    }
    std.debug.assert(out_idx == out.len);
}

fn copyStringWhereBitMaskScalarPadded(out: []u8, bytes: []const u8, mask: HostBitSlice) void {
    var out_idx: usize = 0;
    for (mask.words, 0..) |_, word_idx| {
        const word_base = word_idx * host_bit_word_bits;
        var selected = bitWordMasked(mask.words, mask.len, word_idx);
        while (selected != 0) {
            const bit_idx: usize = @intCast(@ctz(selected));
            const source_idx = word_base + bit_idx;
            out[out_idx] = if (source_idx < bytes.len) bytes[source_idx] else ' ';
            out_idx += 1;
            selected &= selected - 1;
        }
    }
    std.debug.assert(out_idx == out.len);
}

fn stringByteEqMask32(
    comptime left_scalar: bool,
    comptime right_scalar: bool,
    left_bytes: []const u8,
    right_bytes: []const u8,
    start: usize,
) u32 {
    const lane_count = dense_host_simd_bytes / @sizeOf(u8);
    comptime std.debug.assert(lane_count == 32);
    const Vec = @Vector(lane_count, u8);
    const lhs: Vec = if (left_scalar)
        @as(Vec, @splat(left_bytes[0]))
    else
        left_bytes[start..][0..lane_count].*;
    const rhs: Vec = if (right_scalar)
        @as(Vec, @splat(right_bytes[0]))
    else
        right_bytes[start..][0..lane_count].*;
    return @bitCast(lhs == rhs);
}

fn stringByteEqAt(
    comptime left_scalar: bool,
    comptime right_scalar: bool,
    left_bytes: []const u8,
    right_bytes: []const u8,
    idx: usize,
) bool {
    const lhs = if (left_scalar) left_bytes[0] else left_bytes[idx];
    const rhs = if (right_scalar) right_bytes[0] else right_bytes[idx];
    return lhs == rhs;
}

fn fillStringByteEqWordsShape(
    comptime left_scalar: bool,
    comptime right_scalar: bool,
    out: *HostBitAlloc,
    left_bytes: []const u8,
    right_bytes: []const u8,
) BitDenseMetadata {
    const len = out.len;
    var saw_one = false;
    var saw_zero = false;

    for (out.words, 0..) |*out_word, word_idx| {
        const active_len = bitWordActiveLen(len, word_idx, out.words.len);
        const word_base = word_idx * host_bit_word_bits;
        var bit_idx: usize = 0;
        var word: u64 = 0;

        if (comptime enable_string_byte_simd) {
            while (bit_idx + 32 <= active_len) : (bit_idx += 32) {
                const mask = stringByteEqMask32(left_scalar, right_scalar, left_bytes, right_bytes, word_base + bit_idx);
                word |= @as(u64, mask) << @intCast(bit_idx);
            }
        }
        while (bit_idx < active_len) : (bit_idx += 1) {
            if (stringByteEqAt(left_scalar, right_scalar, left_bytes, right_bytes, word_base + bit_idx)) {
                word |= @as(u64, 1) << @intCast(bit_idx);
            }
        }

        out_word.* = word;
        const active_mask = bitLowMask(active_len);
        const masked = word & active_mask;
        if (masked != 0) saw_one = true;
        if (masked != active_mask) saw_zero = true;
    }

    const constant = len <= 1 or !saw_one or !saw_zero;
    return .{
        .flags = host_dense_flag_normalized | if (constant) host_dense_flag_asc | host_dense_flag_dsc else 0,
        .range = .{
            .min = if (!saw_one) 0 else if (saw_zero) 0 else 1,
            .max = if (saw_one) 1 else 0,
        },
    };
}

fn fillStringByteEqWords(out: *HostBitAlloc, left_bytes: []const u8, right_bytes: []const u8) BitDenseMetadata {
    const left_scalar = left_bytes.len == 1;
    const right_scalar = right_bytes.len == 1;
    if (left_scalar and right_scalar) return fillStringByteEqWordsShape(true, true, out, left_bytes, right_bytes);
    if (left_scalar) return fillStringByteEqWordsShape(true, false, out, left_bytes, right_bytes);
    if (right_scalar) return fillStringByteEqWordsShape(false, true, out, left_bytes, right_bytes);
    return fillStringByteEqWordsShape(false, false, out, left_bytes, right_bytes);
}

fn fillBitNotWords(out: []u64, items: HostBitSlice) void {
    for (items.words, 0..) |word, word_idx| out[word_idx] = ~word;
    bitClearUnusedTail(out, items.len);
}

fn hostIntRangeFromWide(min_value: i128, max_value: i128) ?HostIntRange {
    if (min_value < std.math.minInt(i64) or max_value > std.math.maxInt(i64)) return null;
    return .{
        .min = @intCast(min_value),
        .max = @intCast(max_value),
    };
}

fn hostIntInitialResultKind(op: BuiltinId, left_kind: HostIntStorageKind, right_kind: HostIntStorageKind) HostIntStorageKind {
    return switch (op) {
        .add, .sub, .mul, .minimum, .maximum => maxHostIntStorageKind(left_kind, right_kind),
        .iota => .int64,
        .pow => .int64,
        .div => unreachable,
        else => unreachable,
    };
}

fn hostNegInitialResultKind(kind: HostIntStorageKind) HostIntStorageKind {
    return kind;
}

fn nextWiderHostIntStorageKind(kind: HostIntStorageKind) ?HostIntStorageKind {
    return switch (kind) {
        .bit => .int8,
        .int8 => .int16,
        .int16 => .int32,
        .int32 => .int64,
        .int64 => null,
    };
}

fn hostIntUncheckedSafeForOutput(left_kind: HostIntStorageKind, right_kind: HostIntStorageKind, out_kind: HostIntStorageKind) bool {
    return hostIntStorageRank(out_kind) > hostIntStorageRank(maxHostIntStorageKind(left_kind, right_kind));
}

fn hostNegUncheckedSafeForOutput(input_kind: HostIntStorageKind, out_kind: HostIntStorageKind) bool {
    return hostIntStorageRank(out_kind) > hostIntStorageRank(input_kind);
}

fn retryWiderHostIntKind(kind: *HostIntStorageKind) KError!void {
    kind.* = nextWiderHostIntStorageKind(kind.*) orelse return error.Unsupported;
}

fn hostIntNegRange(input: HostIntRange) ?HostIntRange {
    return hostIntRangeFromWide(-@as(i128, input.max), -@as(i128, input.min));
}

fn hostIntDyadRange(op: BuiltinId, left: HostIntRange, right: HostIntRange) ?HostIntRange {
    return switch (op) {
        .add => hostIntRangeFromWide(@as(i128, left.min) + @as(i128, right.min), @as(i128, left.max) + @as(i128, right.max)),
        .sub => hostIntRangeFromWide(@as(i128, left.min) - @as(i128, right.max), @as(i128, left.max) - @as(i128, right.min)),
        .iota => null,
        .minimum => .{
            .min = @min(left.min, right.min),
            .max = @min(left.max, right.max),
        },
        .maximum => .{
            .min = @max(left.min, right.min),
            .max = @max(left.max, right.max),
        },
        .mul => blk: {
            const products = [_]i128{
                @as(i128, left.min) * @as(i128, right.min),
                @as(i128, left.min) * @as(i128, right.max),
                @as(i128, left.max) * @as(i128, right.min),
                @as(i128, left.max) * @as(i128, right.max),
            };
            var min_value = products[0];
            var max_value = products[0];
            for (products[1..]) |product| {
                min_value = @min(min_value, product);
                max_value = @max(max_value, product);
            }
            break :blk hostIntRangeFromWide(min_value, max_value);
        },
        .pow => null,
        .div => null,
        else => null,
    };
}

fn intPowLikeMlx(base: i64, exponent: i64) KError!i64 {
    const value = std.math.pow(f64, @floatFromInt(base), @floatFromInt(exponent));
    if (!std.math.isFinite(value)) return error.Unsupported;
    const truncated = @trunc(value);
    if (truncated < @as(f64, @floatFromInt(std.math.minInt(i64))) or truncated > @as(f64, @floatFromInt(std.math.maxInt(i64)))) return error.Unsupported;
    return @intFromFloat(truncated);
}

fn hostIntDyadResultKindForRange(op: BuiltinId, left_kind: HostIntStorageKind, right_kind: HostIntStorageKind, range: HostIntRange) HostIntStorageKind {
    if (op == .mul and left_kind == .bit and right_kind == .bit and range.min >= 0 and range.max <= 1) {
        return .bit;
    }
    return hostIntStorageKindForRange(range.min, range.max);
}

