const NumericArray = struct {
    header: HeapHeader align(8),
    host: ?*HostDenseArray = null,
    mlx: ?*BackendArray = null,
    preferred: NumericArrayPreferred,
    rank: u8 = 0,
    tracked_in_session: bool = false,
    shape: [numeric_array_max_rank]i32 = @as([numeric_array_max_rank]i32, @splat(0)),
    structural: NumericStructural = .{ .materialized = {} },
    registry_prev: ?*NumericArray = null,
    registry_next: ?*NumericArray = null,
    last_host_touch: usize = 0,
    last_mlx_touch: usize = 0,

    fn activeAttachment(self: *const NumericArray) NumericArrayAttachment {
        return switch (self.preferred) {
            .host => if (self.host != null)
                .host
            else if (self.mlx != null)
                .mlx
            else
                .none,
            .mlx => if (self.mlx != null)
                .mlx
            else if (self.host != null)
                .host
            else
                .none,
        };
    }

    fn shapeSlice(self: *const NumericArray) []const i32 {
        return self.shape[0..self.rank];
    }
};

