fn normalizeMorselGrain(len: usize, requested_grain: usize) usize {
    const grain = if (requested_grain == 0) default_morsel_grain else requested_grain;
    return if (len == 0) grain else @min(grain, len);
}

fn countMorsels(len: usize, grain: usize) usize {
    if (len == 0) return 0;
    return (len + grain - 1) / grain;
}

const MorselKernelFn = *const fn (*anyopaque, MorselRange) anyerror!void;

fn callMorselKernel(ctx: anytype, range: MorselRange, comptime kernel: anytype) anyerror!void {
    const result = kernel(ctx, range);
    switch (@typeInfo(@TypeOf(result))) {
        .error_union => try result,
        else => {},
    }
}

fn MorselKernelAdapter(comptime Ctx: type, comptime kernel: anytype) type {
    return struct {
        fn run(raw_ctx: *anyopaque, range: MorselRange) anyerror!void {
            const ctx: *Ctx = @ptrCast(@alignCast(raw_ctx));
            try callMorselKernel(ctx.*, range, kernel);
        }
    };
}

const MorselPool = if (enable_morsel_thread_pool) struct {
    threads: []std.Thread,
    worker_contexts: []MorselWorkerContext,
    worker_count: usize,
    shutdown: std.atomic.Value(u32) = std.atomic.Value(u32).init(0),
    ready_count: std.atomic.Value(usize) = std.atomic.Value(usize).init(0),
    generation: std.atomic.Value(u32) = std.atomic.Value(u32).init(0),
    done_count: std.atomic.Value(usize) = std.atomic.Value(usize).init(0),
    next_morsel: std.atomic.Value(usize) = std.atomic.Value(usize).init(0),
    total_morsels: usize = 0,
    len: usize = 0,
    grain: usize = default_morsel_grain,
    job_ctx: ?*anyopaque = null,
    job_fn: ?MorselKernelFn = null,
    job_failed: std.atomic.Value(u32) = std.atomic.Value(u32).init(0),

    fn init(allocator: std.mem.Allocator, worker_count: usize) !*MorselPool {
        std.debug.assert(worker_count > 1);
        std.debug.assert(worker_count <= max_morsel_workers);
        const pool = try allocator.create(MorselPool);
        errdefer allocator.destroy(pool);
        pool.* = .{
            .threads = try allocator.alloc(std.Thread, worker_count),
            .worker_contexts = try allocator.alloc(MorselWorkerContext, worker_count),
            .worker_count = worker_count,
        };
        errdefer allocator.free(pool.threads);
        errdefer allocator.free(pool.worker_contexts);

        var spawned: usize = 0;
        errdefer {
            pool.shutdown.store(1, .release);
            _ = pool.generation.fetchAdd(1, .release);
            for (pool.threads[0..spawned]) |thread| thread.join();
        }
        while (spawned < worker_count) : (spawned += 1) {
            pool.worker_contexts[spawned] = .{ .pool = pool, .worker_id = spawned };
            pool.threads[spawned] = try std.Thread.spawn(.{}, morselPoolWorkerMain, .{&pool.worker_contexts[spawned]});
        }
        var spins: usize = 0;
        while (pool.ready_count.load(.acquire) < worker_count) {
            std.Thread.yield() catch {};
            spins += 1;
            if (spins >= morsel_pool_yield_spins) {
                spins = 0;
                platform.sleepNanos(morsel_pool_main_pause_ns);
            }
        }
        return pool;
    }

    fn deinit(self: *MorselPool, allocator: std.mem.Allocator) void {
        self.shutdown.store(1, .release);
        _ = self.generation.fetchAdd(1, .release);
        for (self.threads) |thread| thread.join();
        allocator.free(self.threads);
        allocator.free(self.worker_contexts);
        allocator.destroy(self);
    }

    fn run(self: *MorselPool, len: usize, grain: usize, job_ctx: *anyopaque, job_fn: MorselKernelFn) anyerror!void {
        std.debug.assert(len > 0);
        std.debug.assert(grain > 0);
        const total_morsels = countMorsels(len, grain);
        std.debug.assert(total_morsels > 1);

        self.job_ctx = job_ctx;
        self.job_fn = job_fn;
        self.len = len;
        self.grain = grain;
        self.total_morsels = total_morsels;
        self.next_morsel.store(0, .release);
        self.done_count.store(0, .release);
        self.job_failed.store(0, .release);
        _ = self.generation.fetchAdd(1, .release);

        var spins: usize = 0;
        while (self.done_count.load(.acquire) < self.worker_count) {
            std.Thread.yield() catch {};
            spins += 1;
            if (spins >= morsel_pool_yield_spins) {
                spins = 0;
                platform.sleepNanos(morsel_pool_main_pause_ns);
            }
        }
        if (self.job_failed.load(.acquire) != 0) return error.MorselWorkerFailed;
    }
} else struct {};

const MorselWorkerContext = if (enable_morsel_thread_pool) struct {
    pool: *MorselPool,
    worker_id: usize,
} else struct {};

fn morselPoolWorkerMain(ctx: *MorselWorkerContext) void {
    if (comptime !enable_morsel_thread_pool) unreachable;
    const pool = ctx.pool;
    var seen_generation = pool.generation.load(.acquire);
    _ = pool.ready_count.fetchAdd(1, .release);
    var spins: usize = 0;
    while (true) {
        const generation = pool.generation.load(.acquire);
        if (generation == seen_generation) {
            if (pool.shutdown.load(.acquire) != 0) return;
            std.Thread.yield() catch {};
            spins += 1;
            if (spins >= morsel_pool_yield_spins) {
                spins = 0;
                platform.sleepNanos(morsel_pool_idle_pause_ns);
            }
            continue;
        }
        seen_generation = generation;
        spins = 0;
        if (pool.shutdown.load(.acquire) != 0) return;
        const job_fn = pool.job_fn orelse {
            _ = pool.done_count.fetchAdd(1, .release);
            continue;
        };
        const job_ctx = pool.job_ctx orelse {
            _ = pool.done_count.fetchAdd(1, .release);
            continue;
        };
        while (true) {
            const morsel_idx = pool.next_morsel.fetchAdd(1, .monotonic);
            if (morsel_idx >= pool.total_morsels) break;
            const start = morsel_idx * pool.grain;
            const end = @min(pool.len, start + pool.grain);
            job_fn(job_ctx, .{ .start = start, .end = end }) catch {
                pool.job_failed.store(1, .release);
                break;
            };
        }
        _ = pool.done_count.fetchAdd(1, .release);
    }
}

const SamplingProfileScope = struct {
    session: ?*Session = null,
    previous_label: u8 = @backingInt(SamplingProfileLabel.idle),

    fn end(self: SamplingProfileScope) void {
        if (self.session) |session| {
            session.profile_current_label.store(self.previous_label, .unordered);
        }
    }
};

