    last_result: ?Value = null,
    last_error_text: ?[]u8 = null,
    morsel_pool: RuntimeMorselPoolPtr = if (enable_morsel_thread_pool) null else {},
    morsel_worker_request: usize = 0,
    morsel_i64_partials: std.ArrayListUnmanaged(i64) = .empty,
    morsel_f64_partials: std.ArrayListUnmanaged(f64) = .empty,
    morsel_f32_partials: std.ArrayListUnmanaged(f32) = .empty,
    morsel_int_range_partials: std.ArrayListUnmanaged(HostIntRange) = .empty,
    morsel_float_bounds_partials: std.ArrayListUnmanaged(HostFloatBounds) = .empty,
    debug: DebugRuntimeStats = .{},
    debug_dense_autodiff_reject_counts: [debug_dense_autodiff_lowering_count]usize = @as([debug_dense_autodiff_lowering_count]usize, @splat(0)),
    last_dense_plan_region: ?DenseRegionKind = null,
    last_dense_plan_backend: ?DenseExecBackend = null,
    last_dense_exec_backend: ?DenseExecBackend = null,
    last_dense_plan_reason: ?DensePlanReason = null,
    last_dense_plan_overridden: bool = false,
    last_dense_autodiff_exec_backend: ?DenseAutodiffExecBackend = null,
    managed_numeric_registry_head: ?*NumericArray = null,
    attachment_touch_clock: usize = 1,
    dense_backend_override: DenseBackendOverride = .auto,
    profile_sampling_enabled: std.atomic.Value(u8) = std.atomic.Value(u8).init(0),
    profile_current_label: std.atomic.Value(u8) = std.atomic.Value(u8).init(@backingInt(SamplingProfileLabel.idle)),
    profile_current_op: std.atomic.Value(u16) = std.atomic.Value(u16).init(sampling_profile_no_op),
    profile_current_code_id: std.atomic.Value(u16) = std.atomic.Value(u16).init(sampling_profile_no_code),
    profile_current_callable_slot: std.atomic.Value(u16) = std.atomic.Value(u16).init(sampling_profile_no_callable_slot),
    next_profile_code_id: u16 = sampling_profile_dynamic_code_id_base,
    profile_dynamic_code_infos: [sampling_profile_max_code_count]SamplingProfileCodeInfo = undefined,
    profile_dynamic_code_used: [sampling_profile_max_code_count]bool = @as([sampling_profile_max_code_count]bool, @splat(false)),

    pub fn init(allocator: std.mem.Allocator) !Session {
        var session: Session = undefined;
        try session.initInPlaceWithDevice(allocator, .cpu);
        return session;
    }

    pub fn initWithDevice(allocator: std.mem.Allocator, device_preference: device.DevicePreference) !Session {
        var session: Session = undefined;
        try session.initInPlaceWithDevice(allocator, device_preference);
        return session;
    }

    pub fn initInPlace(self: *Session, allocator: std.mem.Allocator) !void {
        try self.initInPlaceWithDevice(allocator, .cpu);
    }

    pub fn initInPlaceWithDevice(self: *Session, allocator: std.mem.Allocator, device_preference: device.DevicePreference) !void {
        @memset(std.mem.asBytes(self), 0);
        self.allocator = allocator;
        self.arena = std.heap.ArenaAllocator.init(allocator);
        self.scratch_arena = std.heap.ArenaAllocator.init(allocator);
        self.prng = Prng.initEntropy();
        self.device_preference = device_preference;
        self.global_slots = std.StringHashMap(u16).init(allocator);
        self.interned_strings = std.StringHashMap(*HostText).init(allocator);
        self.interned_symbols = std.StringHashMap(*HostText).init(allocator);
        if (comptime runtime_has_mlx) self.loaded_safetensors = std.StringHashMap(LoadedSafetensorsStore).init(allocator);
        if (comptime runtime_has_relations) self.loaded_relations = std.StringHashMap(LoadedRelationStore).init(allocator);
        if (comptime runtime_has_duckdb) self.registered_duckdb_tables = std.StringHashMap(RegisteredDuckDbTableStore).init(allocator);
        self.code_cache = std.StringHashMap(*const Code).init(allocator);
        self.dense_autodiff_cache = std.AutoHashMap(DenseAutodiffCacheKey, DenseAutodiffLowerResult).init(allocator);
        self.attachment_touch_clock = 1;
        self.dense_backend_override = .auto;
        self.profile_sampling_enabled = std.atomic.Value(u8).init(0);
        self.profile_current_label = std.atomic.Value(u8).init(@backingInt(SamplingProfileLabel.idle));
        self.profile_current_op = std.atomic.Value(u16).init(sampling_profile_no_op);
        self.profile_current_code_id = std.atomic.Value(u16).init(sampling_profile_no_code);
        self.profile_current_callable_slot = std.atomic.Value(u16).init(sampling_profile_no_callable_slot);
        self.next_profile_code_id = sampling_profile_dynamic_code_id_base;
    }

    pub fn deinit(self: *Session) void {
        self.clearLastErrorText();
        if (self.last_result) |value| self.releaseValue(value);
        self.last_result = null;
        for (self.global_cells.items) |cell| {
            if (cell.initialized) self.releaseValue(cell.value);
        }
        // Release cached tensor bundles before forcibly draining the numeric
        // registry so bundle-owned backend arrays can unregister themselves.
        if (comptime runtime_has_mlx) {
            var loaded_iter = self.loaded_safetensors.iterator();
            while (loaded_iter.next()) |entry| {
                self.releaseValue(entry.value_ptr.store);
                self.allocator.free(entry.key_ptr.*);
            }
            self.loaded_safetensors.deinit();
        }
        if (comptime runtime_has_relations) {
            var relation_iter = self.loaded_relations.iterator();
            while (relation_iter.next()) |entry| {
                self.releaseValue(entry.value_ptr.relation);
                self.allocator.free(entry.key_ptr.*);
            }
            self.loaded_relations.deinit();
        }
        if (comptime runtime_has_duckdb) {
            if (self.duckdb_conn) |*conn| conn.deinit();
            self.duckdb_conn = null;
            self.duckdb_kiwi_scan_registered = false;
            var registered_table_iter = self.registered_duckdb_tables.iterator();
            while (registered_table_iter.next()) |entry| {
                self.releaseValue(entry.value_ptr.table);
                self.allocator.free(entry.key_ptr.*);
            }
            self.registered_duckdb_tables.deinit();
        }
        while (self.managed_numeric_registry_head) |handle| self.recycleManagedNumericArray(handle);
        self.global_cells.deinit(self.allocator);
        self.global_slots.deinit();
        self.global_names.deinit(self.allocator);
        self.interned_strings.deinit();
        self.interned_symbols.deinit();
        self.code_cache.deinit();
        self.dense_autodiff_cache.deinit();
        if (comptime runtime_has_mlx) {
            if (self.mlx_ctx) |*ctx| ctx.deinit();
        }
        if (comptime enable_morsel_thread_pool) {
            if (self.morsel_pool) |pool| {
                pool.deinit(self.allocator);
                self.morsel_pool = null;
            }
        }
        self.morsel_i64_partials.deinit(self.allocator);
        self.morsel_f64_partials.deinit(self.allocator);
        self.morsel_f32_partials.deinit(self.allocator);
        self.morsel_int_range_partials.deinit(self.allocator);
        self.morsel_float_bounds_partials.deinit(self.allocator);
        while (self.free_boxed_int_len > 0) {
            self.free_boxed_int_len -= 1;
            self.allocator.destroy(self.free_boxed_ints[self.free_boxed_int_len].?);
        }
        while (self.free_closure_len > 0) {
            self.free_closure_len -= 1;
            self.allocator.destroy(self.free_closures[self.free_closure_len].?);
        }
        while (self.free_numeric_array_len > 0) {
            self.free_numeric_array_len -= 1;
            self.allocator.destroy(self.free_numeric_arrays[self.free_numeric_array_len].?);
        }
        while (self.free_host_array_len > 0) {
            self.free_host_array_len -= 1;
            self.allocator.destroy(self.free_host_arrays[self.free_host_array_len].?);
        }
        for (0..managed_host_dense_storage_kind_count) |pool_idx| {
            while (self.free_host_dense_buffer_len[pool_idx] > 0) {
                self.free_host_dense_buffer_len[pool_idx] -= 1;
                const entry = self.free_host_dense_buffers[pool_idx][self.free_host_dense_buffer_len[pool_idx]].?;
                self.free_host_dense_buffers[pool_idx][self.free_host_dense_buffer_len[pool_idx]] = null;
                self.freeManagedHostDenseBuffer(@fromBackingInt(@intCast(pool_idx)), entry);
            }
        }
        while (self.free_host_text_buffer_len > 0) {
            self.free_host_text_buffer_len -= 1;
            const entry = self.free_host_text_buffers[self.free_host_text_buffer_len].?;
            self.free_host_text_buffers[self.free_host_text_buffer_len] = null;
            self.freeManagedHostTextBuffer(entry);
        }
        while (self.free_host_boxed_array_len > 0) {
            self.free_host_boxed_array_len -= 1;
            self.allocator.destroy(self.free_host_boxed_arrays[self.free_host_boxed_array_len].?);
        }
        if (comptime runtime_has_mlx) {
            while (self.free_mlx_array_len > 0) {
                self.free_mlx_array_len -= 1;
                self.allocator.destroy(self.free_mlx_arrays[self.free_mlx_array_len].?);
            }
        }
        self.scratch_arena.deinit();
        self.arena.deinit();
    }

    pub fn lastErrorText(self: *const Session) ?[]const u8 {
        return self.last_error_text;
    }

    pub fn clearLastErrorText(self: *Session) void {
        if (self.last_error_text) |text| self.allocator.free(text);
        self.last_error_text = null;
    }

    fn setOwnedLastErrorText(self: *Session, text: ?[]u8) void {
        self.clearLastErrorText();
        self.last_error_text = text;
    }

    fn setOwnedDuckDbErrorText(self: *Session, detail: ?[]u8) void {
        const text = detail orelse {
            self.clearLastErrorText();
            return;
        };
        const prefixed = std.fmt.allocPrint(self.allocator, "duckdb: {s}", .{text}) catch {
            self.setOwnedLastErrorText(text);
            return;
        };
        self.allocator.free(text);
        self.setOwnedLastErrorText(prefixed);
    }

    pub fn setSamplingProfileEnabled(self: *Session, enabled: bool) void {
        if (comptime !enable_sampling_profile) {
            return;
        }
        self.profile_sampling_enabled.store(@intFromBool(enabled), .unordered);
        if (!enabled) {
            self.profile_current_label.store(@backingInt(SamplingProfileLabel.idle), .unordered);
            self.profile_current_op.store(sampling_profile_no_op, .unordered);
            self.profile_current_code_id.store(sampling_profile_no_code, .unordered);
            self.profile_current_callable_slot.store(sampling_profile_no_callable_slot, .unordered);
        }
    }

    pub fn samplingProfileState(self: *const Session) SamplingProfileState {
        if (comptime !enable_sampling_profile) {
            return .{
                .label = .idle,
                .op = null,
                .code_id = sampling_profile_no_code,
                .callable_slot = sampling_profile_no_callable_slot,
            };
        }
        const raw_label = self.profile_current_label.load(.unordered);
        const raw_op = self.profile_current_op.load(.unordered);
        return .{
            .label = std.enums.fromInt(SamplingProfileLabel, raw_label) orelse .idle,
            .op = if (raw_op == sampling_profile_no_op) null else std.math.cast(u8, raw_op),
            .code_id = self.profile_current_code_id.load(.unordered),
            .callable_slot = self.profile_current_callable_slot.load(.unordered),
        };
    }

    pub fn samplingProfileCodeKindName(kind: SamplingProfileCodeKind) []const u8 {
        return @tagName(kind);
    }

    pub fn samplingProfileCodeInfo(self: *const Session, id: u16) ?SamplingProfileCodeInfo {
        if (comptime !enable_sampling_profile) {
            return null;
        }
        if (staticSamplingProfileCodeInfo(id)) |info| return info;
        if (id == sampling_profile_no_code or id >= self.profile_dynamic_code_used.len) return null;
        if (!self.profile_dynamic_code_used[id]) return null;
        return self.profile_dynamic_code_infos[id];
    }

    pub fn samplingProfileCallableName(self: *const Session, slot: u16) ?[]const u8 {
        if (comptime !enable_sampling_profile) {
            return null;
        }
        if (slot == sampling_profile_no_callable_slot or slot >= self.global_names.items.len) return null;
        return self.global_names.items[slot];
    }

    pub fn cachedCodeCount(self: *Session) usize {
        return self.code_cache.count();
    }

    pub fn evalSource(self: *Session, source: []const u8) KError!Value {
        self.clearLastErrorText();
        const code = try self.compileCached(source);
        return try self.runCode(code, &[_]Value{});
    }

    pub fn evalSourceWarm(self: *Session, compile_arena: *std.heap.ArenaAllocator, source: []const u8) KError!Value {
        self.clearLastErrorText();
        const code = try self.compileScratch(compile_arena, source);
        return try self.runScratchCodeMode(code, &[_]Value{}, true);
    }

    pub fn evalSourceWarmEphemeral(self: *Session, compile_arena: *std.heap.ArenaAllocator, source: []const u8) KError!Value {
        self.clearLastErrorText();
        const code = try self.compileScratch(compile_arena, source);
        return try self.runScratchCodeMode(code, &[_]Value{}, false);
    }

    pub fn parseOnly(self: *Session, source: []const u8) KError!void {
        self.clearLastErrorText();
        var temp_arena = std.heap.ArenaAllocator.init(self.allocator);
        defer temp_arena.deinit();

        _ = try self.compileScratch(&temp_arena, source);
    }

    pub fn parseOnlyWarm(self: *Session, compile_arena: *std.heap.ArenaAllocator, source: []const u8) KError!void {
        self.clearLastErrorText();
        _ = try self.compileScratch(compile_arena, source);
    }

    pub fn lastDenseAutodiffExecPath(self: *const Session) ?[]const u8 {
        if (comptime !enable_probe_instrumentation) return null;
        return if (self.last_dense_autodiff_exec_backend) |backend| switch (backend) {
            .host => "host",
            .mlx => "mlx",
        } else null;
    }

    pub fn compile(self: *Session, source: []const u8) KError!*const Code {
        return try self.compileCached(source);
    }

    fn compilerAssignTopLevelProfile(self: *Session, code: *Code, source: []const u8, compile_mode: CompileMode) void {
        if (comptime !enable_sampling_profile) {
            code.profile_kind = .none;
            code.profile_source = "";
            code.profile_id = sampling_profile_no_code;
            self.noteCodeCompile(code);
            return;
        }
        code.profile_kind = .top_level;
        code.profile_source = std.mem.trim(u8, source, " \t\r\n");
        if (compile_mode != .frozen) {
            code.profile_id = sampling_profile_no_code;
            self.noteCodeCompile(code);
            return;
        }
        code.profile_id = self.nextSamplingProfileCodeId();
        self.noteCodeCompile(code);
        self.rememberSamplingProfileCodeInfo(code.profile_id, code.profile_kind, code.profile_source);
    }

    pub fn evalCode(self: *Session, code: *const Code) KError!Value {
        return try self.runCode(code, &[_]Value{});
    }

    pub fn evalCodeEphemeral(self: *Session, code: *const Code) KError!Value {
        return try self.runCodeMode(code, &[_]Value{}, false);
    }

    pub fn forceValue(self: *Session, value: Value) KError!void {
        _ = self;
        switch (value.tag()) {
            .float32 => {},
            .array => switch (value.arrayKind()) {
                .numeric_array => {
                    if (value.asNumericArray().mlx) |array| {
                        var owned = array.array.clone() catch |err| return mapMlxError(err);
                        defer owned.deinit();
                        owned.eval() catch |err| return mapMlxError(err);
                    }
                },
                .host_boxed_array, .host_string, .host_symbol, .host_string_list, .host_symbol_list, .host_string_view, .host_handle, .host_relation, .host_keyed_store, .host_table_scalar => {},
                else => return error.Internal,
            },
            .int, .float, .bool, .builtin, .closure => {},
        }
    }

    pub fn debugScratchHostDenseAllocCount(self: *Session) usize {
        if (comptime !enable_probe_instrumentation) return 0;
        return self.debug.scratch_host_array_alloc_count;
    }

    pub fn resetDebugHostDenseMemoryStats(self: *Session) void {
        if (comptime !enable_probe_instrumentation) return;
        self.noteDebugHostDenseScratchArenaReset();
        self.debug.host_dense_storage_alloc_count = 0;
        self.debug.host_dense_storage_reuse_count = 0;
        self.debug.host_dense_storage_free_count = 0;
        self.debug.host_dense_storage_recycle_count = 0;
        self.debug.host_dense_storage_alloc_bytes = 0;
        self.debug.host_dense_storage_reuse_bytes = 0;
        self.debug.host_dense_storage_free_bytes = 0;
        self.debug.host_dense_storage_recycle_bytes = 0;
        self.debug.host_dense_baseline_active_bytes = self.debug.host_dense_active_bytes;
        self.debug.host_dense_peak_active_bytes = self.debug.host_dense_active_bytes;
    }

    pub fn debugHostDenseMemoryStats(self: *const Session) DebugHostDenseMemoryStats {
        if (comptime !enable_probe_instrumentation) return .{};
        const peak_extra = if (self.debug.host_dense_peak_active_bytes > self.debug.host_dense_baseline_active_bytes)
            self.debug.host_dense_peak_active_bytes - self.debug.host_dense_baseline_active_bytes
        else
            0;
        return .{
            .storage_alloc_count = self.debug.host_dense_storage_alloc_count,
            .storage_reuse_count = self.debug.host_dense_storage_reuse_count,
            .storage_free_count = self.debug.host_dense_storage_free_count,
            .storage_recycle_count = self.debug.host_dense_storage_recycle_count,
            .storage_alloc_bytes = self.debug.host_dense_storage_alloc_bytes,
            .storage_reuse_bytes = self.debug.host_dense_storage_reuse_bytes,
            .storage_free_bytes = self.debug.host_dense_storage_free_bytes,
            .storage_recycle_bytes = self.debug.host_dense_storage_recycle_bytes,
            .baseline_active_bytes = self.debug.host_dense_baseline_active_bytes,
            .active_bytes = self.debug.host_dense_active_bytes,
            .peak_active_bytes = self.debug.host_dense_peak_active_bytes,
            .peak_extra_bytes = peak_extra,
            .pool_bytes = self.debugManagedHostDensePoolBytes(),
        };
    }

