    pub fn setMorselWorkerRequest(self: *Session, workers: usize) void {
        self.morsel_worker_request = std.math.clamp(workers, 1, max_morsel_workers);
    }

    fn resolveConfiguredMorselWorkers(self: *Session) usize {
        if (self.morsel_worker_request != 0) return self.morsel_worker_request;
        var resolved: usize = 1;
        if (comptime enable_morsel_thread_pool) {
            if (platform.getEnvVarOwned(self.allocator, "KIWI_WORKERS")) |raw| {
                defer self.allocator.free(raw);
                const trimmed = std.mem.trim(u8, raw, " \t\r\n");
                if (std.ascii.eqlIgnoreCase(trimmed, "auto")) {
                    resolved = std.Thread.getCpuCount() catch 1;
                } else if (std.fmt.parseInt(usize, trimmed, 10)) |count| {
                    resolved = count;
                } else |_| {
                    resolved = 1;
                }
            } else |_| {}
        }
        self.morsel_worker_request = std.math.clamp(resolved, 1, max_morsel_workers);
        return self.morsel_worker_request;
    }

    fn morselWorkersForDenseSink(self: *Session, len: usize, min_len: usize, worker_cap: usize) ?usize {
        if (len < min_len) return null;
        const workers = @min(self.resolveConfiguredMorselWorkers(), worker_cap);
        return if (workers > 1) workers else null;
    }

    fn morselWorkersForDenseMap(self: *Session, len: usize) ?usize {
        return self.morselWorkersForDenseSink(len, dense_map_morsel_min_len, dense_map_morsel_worker_cap);
    }

    fn morselWorkersForDenseReduction(self: *Session, len: usize) ?usize {
        return self.morselWorkersForDenseSink(len, dense_reduce_morsel_min_len, dense_reduce_morsel_worker_cap);
    }

    fn morselWorkersForDenseFusedReduction(self: *Session, len: usize) ?usize {
        return self.morselWorkersForDenseSink(len, dense_fused_reduce_morsel_min_len, dense_fused_reduce_morsel_worker_cap);
    }

    fn morselI64Partials(self: *Session, len: usize) ![]i64 {
        try self.morsel_i64_partials.ensureTotalCapacity(self.allocator, len);
        self.morsel_i64_partials.items.len = len;
        return self.morsel_i64_partials.items;
    }

    fn morselF64Partials(self: *Session, len: usize) ![]f64 {
        try self.morsel_f64_partials.ensureTotalCapacity(self.allocator, len);
        self.morsel_f64_partials.items.len = len;
        return self.morsel_f64_partials.items;
    }

    fn morselF32Partials(self: *Session, len: usize) ![]f32 {
        try self.morsel_f32_partials.ensureTotalCapacity(self.allocator, len);
        self.morsel_f32_partials.items.len = len;
        return self.morsel_f32_partials.items;
    }

    fn morselIntRangePartials(self: *Session, len: usize) ![]HostIntRange {
        try self.morsel_int_range_partials.ensureTotalCapacity(self.allocator, len);
        self.morsel_int_range_partials.items.len = len;
        return self.morsel_int_range_partials.items;
    }

    fn morselFloatBoundsPartials(self: *Session, len: usize) ![]HostFloatBounds {
        try self.morsel_float_bounds_partials.ensureTotalCapacity(self.allocator, len);
        self.morsel_float_bounds_partials.items.len = len;
        return self.morsel_float_bounds_partials.items;
    }

    fn ensureMorselPool(self: *Session, worker_count: usize) !?*MorselPool {
        if (comptime !enable_morsel_thread_pool) return null;
        if (worker_count <= 1) return null;
        if (self.morsel_pool) |pool| {
            if (pool.worker_count == worker_count) return pool;
            pool.deinit(self.allocator);
            self.morsel_pool = null;
        }
        const pool = try MorselPool.init(self.allocator, worker_count);
        self.morsel_pool = pool;
        return pool;
    }

    pub fn runMorselRange(self: *Session, config: MorselRunConfig, ctx: anytype, comptime kernel: anytype) !void {
        const grain = normalizeMorselGrain(config.len, config.grain);
        const morsels = countMorsels(config.len, grain);
        const workers_requested = @max(@as(usize, 1), config.workers_requested);
        if (comptime enable_morsel_thread_pool) {
            if (workers_requested > 1 and morsels > 1) {
                const workers_used = @min(workers_requested, morsels);
                if (try self.ensureMorselPool(workers_used)) |pool| {
                    self.noteDebugMorselPhase(.pool, workers_requested, workers_used, config.len, grain, morsels);
                    var context = ctx;
                    try pool.run(
                        config.len,
                        grain,
                        @ptrCast(&context),
                        MorselKernelAdapter(@TypeOf(context), kernel).run,
                    );
                    return;
                }
            }
        }

        const workers_used: usize = if (config.len == 0) 0 else 1;
        self.noteDebugMorselPhase(.serial, workers_requested, workers_used, config.len, grain, morsels);

        var start: usize = 0;
        while (start < config.len) {
            const end = start + @min(grain, config.len - start);
            try callMorselKernel(ctx, .{ .start = start, .end = end }, kernel);
            start = end;
        }
    }

    pub fn debugManagedNumericHandleCount(self: *const Session) usize {
        var count: usize = 0;
        var current = self.managed_numeric_registry_head;
        while (current) |handle| : (current = handle.registry_next) {
            if (handle.header.owner == .managed and handle.tracked_in_session) count += 1;
        }
        return count;
    }

    pub fn debugCodeOpcodeTopCounts(self: *const Session) [debug_top_opcode_count]DebugCodeOpCount {
        var top = @as([debug_top_opcode_count]DebugCodeOpCount, @splat(.{ .name = "", .opcode = 0, .count = 0 }));
        if (comptime !enable_probe_instrumentation) return top;
        for (self.debug.code_op_counts, 0..) |count, idx| {
            if (count == 0) continue;
            var insert_at: usize = 0;
            while (insert_at < top.len and top[insert_at].count >= count) : (insert_at += 1) {}
            if (insert_at >= top.len) continue;
            var move_idx = top.len - 1;
            while (move_idx > insert_at) : (move_idx -= 1) top[move_idx] = top[move_idx - 1];
            const raw: u8 = @intCast(idx);
            top[insert_at] = .{ .name = debugCodeOpName(raw), .opcode = raw, .count = count };
        }
        return top;
    }

    pub fn debugCodeOpcodeFamilyCounts(self: *const Session) [debug_opcode_family_count]DebugOpcodeFamilyCount {
        var out: [debug_opcode_family_count]DebugOpcodeFamilyCount = undefined;
        inline for (@typeInfo(DebugOpcodeFamily).@"enum".field_names, 0..) |field_name, idx| {
            const count = if (comptime enable_probe_instrumentation) self.debug.code_op_family_counts[idx] else 0;
            out[idx] = .{ .name = field_name, .count = count };
        }
        return out;
    }

    pub fn debugCodeCompileUnsupportedOpcodeTopCounts(self: *const Session) [debug_top_opcode_count]DebugNameCount {
        _ = self;
        return @as([debug_top_opcode_count]DebugNameCount, @splat(.{ .name = "", .count = 0 }));
    }

    pub fn debugDenseAutodiffRejectCount(self: *const Session, reason: DebugDenseAutodiffLowering) usize {
        if (comptime !enable_probe_instrumentation) return 0;
        return self.debug_dense_autodiff_reject_counts[@backingInt(reason)];
