    fn noteHostDenseDyadOp(self: *Session, op: BuiltinId) void {
        if (!self.debugDetailedProbeActive()) return;
        const tag: DebugHostDenseDyadOp = switch (op) {
            .add => .add,
            .sub => .sub,
            .mul => .mul,
            .div => .div,
            .less => .less,
            .more => .more,
            .equal => .equal,
            else => return,
        };
        self.debug.host_dense_dyad_host_op_counts[@backingInt(tag)] += 1;
    }

    fn noteHostDenseDyadHost(self: *Session, op: BuiltinId, left: Value, right: Value, result_len: usize, rowwise: bool) void {
        if (!self.debugDetailedProbeActive()) return;
        self.debug.host_dense_dyad_host_count += 1;
        self.debug.host_dense_dyad_host_element_count += result_len;
        self.noteHostDenseDyadOp(op);
        if (rowwise) self.debug.host_dense_dyad_host_rowwise_count += 1;
        if (hasBackendRealization(left) or hasBackendRealization(right)) {
            self.debug.host_dense_dyad_host_with_backend_input_count += 1;
        }
    }

    fn noteHostDenseDyadMiss(self: *Session, reason: DebugHostDenseDyadMiss) void {
        if (!self.debugDetailedProbeActive()) return;
        self.debug.host_dense_dyad_miss_counts[@backingInt(reason)] += 1;
    }

    fn noteCodeGlobalCallFallback(self: *Session, cell: *const GlobalCell, argc: u8) void {
        if (comptime !enable_probe_instrumentation) return;

        const reason: DebugCodeGlobalCallFallbackReason = if (cell.code) |code|
            if (code.arity != argc)
                .arity
            else
                .other
        else
            .no_code;
        self.debug.code_global_call_fallback_reason_counts[@backingInt(reason)] += 1;

        const kind: DebugCodeGlobalCallFallbackKind = switch (cell.value.tag()) {
            .builtin => .builtin,
            .closure => .closure,
            .array => .array,
            else => .other,
        };
        self.debug.code_global_call_fallback_kind_counts[@backingInt(kind)] += 1;
    }

    fn noteDenseEachMiss(self: *Session, reason: DebugDenseEachMiss) void {
        if (!self.debugDetailedProbeActive()) return;
        self.debug.apply_each_fast_dense_miss_counts[@backingInt(reason)] += 1;
    }

    fn noteDenseEachRightMiss(self: *Session, reason: DebugDenseEachRightMiss) void {
        if (!self.debugDetailedProbeActive()) return;
        self.debug.apply_each_right_fast_dense_miss_counts[@backingInt(reason)] += 1;
    }

    pub fn discardValue(self: *Session, value: Value) void {
        self.releaseValue(value);
    }

    fn beginSamplingProfileScope(self: *Session, label: SamplingProfileLabel) SamplingProfileScope {
        if (comptime !enable_sampling_profile) {
            return .{};
        }
        if (self.profile_sampling_enabled.load(.unordered) == 0) return .{};
        const previous_label = self.profile_current_label.load(.unordered);
        self.profile_current_label.store(@backingInt(label), .unordered);
        return .{
            .session = self,
            .previous_label = previous_label,
        };
    }

    pub fn wasmAcceleratorArrayInfo(self: *Session, value: Value) KError!?WasmArrayInfo {
        return runtime_backend_wasm.wasmAcceleratorArrayInfo(backend_wasm_api, self, value);
    }

    pub fn renderValue(self: *Session, value: Value) anyerror![]u8 {
        var profile_scope = self.beginSamplingProfileScope(.render);
        defer profile_scope.end();
        return self.renderValueMode(value, .top);
    }

    fn renderValueMode(self: *Session, value: Value, mode: RenderMode) anyerror![]u8 {
        return switch (value.tag()) {
            .int => if (isKiwiIntNull(value.asInt()))
                self.allocator.dupe(u8, "0N")
            else
                std.fmt.allocPrint(self.allocator, "{d}", .{value.asInt()}),
            .float32 => formatFloat32Scalar(self.allocator, value.asFloat32()),
            .float => formatFloat(self.allocator, value.asFloat()),
            .bool => std.fmt.allocPrint(self.allocator, "{d}b", .{@intFromBool(value.asBool())}),
            .builtin => std.fmt.allocPrint(self.allocator, "{c}", .{builtinChar(value.asBuiltin())}),
            .closure => self.renderClosure(value),
            .array => self.renderArrayMode(value, mode),
        };
    }

    fn renderClosure(self: *Session, value: Value) anyerror![]u8 {
        var out = std.ArrayList(u8).empty;
        var out_active = true;
        errdefer if (out_active) out.deinit(self.allocator);
        if (try self.appendCallableText(&out, value)) {
            const text = try out.toOwnedSlice(self.allocator);
            out_active = false;
            return text;
        }
        out.deinit(self.allocator);
        out_active = false;
        return try std.fmt.allocPrint(self.allocator, "{{...}}", .{});
    }

    fn renderArrayMode(self: *Session, value: Value, mode: RenderMode) anyerror![]u8 {
        if (valueNumericHandle(value)) |handle| return self.renderNumericArray(handle, mode);
        const kind = value.arrayKind();
        return switch (kind) {
            .host_boxed_array => self.renderHostBoxedArray(value.asHostBoxedArray(), mode),
            .host_string => self.renderHostString(value.asHostString()),
            .host_symbol => self.renderHostSymbol(value.asHostSymbol()),
            .host_string_list => self.renderHostStringList(value.asHostStringList(), mode),
            .host_symbol_list => self.renderHostSymbolList(value.asHostStringList()),
            .host_string_view => self.renderHostStringView(value.asHostStringView()),
            .host_handle => self.renderHostHandle(value.asHostHandle()),
            .host_relation => self.renderHostRelation(value.asHostRelation()),
            .host_keyed_store => self.renderHostKeyedStore(value.asHostKeyedStore()),
            .host_table_scalar => self.renderHostTableScalar(valueAsHostTableScalar(value)),
            else => error.Internal,
        };
    }

    fn appendRenderedFloat(out: *std.ArrayList(u8), allocator: std.mem.Allocator, value: f64) !void {
        const part = try formatFloat(allocator, value);
        defer allocator.free(part);
        try out.appendSlice(allocator, part);
    }

    fn appendRenderedInt(out: *std.ArrayList(u8), allocator: std.mem.Allocator, value: i64) !void {
        if (isKiwiIntNull(value)) {
            try out.appendSlice(allocator, "0N");
        } else {
            var buf: [32]u8 = undefined;
            const text = try std.fmt.bufPrint(&buf, "{d}", .{value});
            try out.appendSlice(allocator, text);
        }
    }

    fn appendRenderedNumericFlatItem(self: *Session, out: *std.ArrayList(u8), value: Value, idx: usize, mode: HostDenseElem) !void {
        switch (mode) {
            .int => try appendRenderedInt(out, self.allocator, try numericIntAt(value, idx)),
            .float => try appendRenderedFloat(out, self.allocator, try numericFloatAt(value, idx)),
        }
    }

    fn appendRenderedNumericFlatVector(self: *Session, out: *std.ArrayList(u8), value: Value, base: usize, len: usize, mode: HostDenseElem) !void {
        if (len == 0 and mode == .int) {
            try out.appendSlice(self.allocator, "!0");
            return;
        }
        if (len == 0 and mode == .float) {
            try out.appendSlice(self.allocator, "0#0n");
            return;
        }
        if (len == 1) try out.append(self.allocator, ',');
        for (0..len) |idx| {
            if (idx != 0) try out.append(self.allocator, ' ');
            try self.appendRenderedNumericFlatItem(out, value, base + idx, mode);
        }
    }

    fn appendRenderedNumericPrototypeFlatVector(self: *Session, out: *std.ArrayList(u8), len: usize, mode: HostDenseElem) !void {
        if (len == 0) {
            try out.appendSlice(self.allocator, if (mode == .float) "0#0n" else "!0");
            return;
        }
        if (len == 1) try out.append(self.allocator, ',');
        for (0..len) |idx| {
            if (idx != 0) try out.append(self.allocator, ' ');
            try out.appendSlice(self.allocator, if (mode == .float) "0n" else "0N");
        }
    }

    fn numericShapeDimsElementCount(dims: []const i32) anyerror!usize {
        var total: usize = 1;
        for (dims) |dim| {
            if (dim < 0) return error.Internal;
            total = std.math.mul(usize, total, @as(usize, @intCast(dim))) catch return error.Unsupported;
        }
        return total;
    }

    fn appendRenderedNumericPrototypeShape(self: *Session, out: *std.ArrayList(u8), shape: []const i32, elem_mode: HostDenseElem) anyerror!void {
        if (shape.len <= 1) {
            const len: usize = if (shape.len == 0) 1 else @intCast(shape[0]);
            try self.appendRenderedNumericPrototypeFlatVector(out, len, elem_mode);
            return;
        }

        const first: usize = @intCast(shape[0]);
        if (first == 0) {
            try out.appendSlice(self.allocator, "0#,");
            try self.appendRenderedNumericPrototypeShape(out, shape[1..], elem_mode);
            return;
        }
        if (first == 1) {
            try out.append(self.allocator, ',');
            try self.appendRenderedNumericPrototypeShape(out, shape[1..], elem_mode);
            return;
        }

        try out.append(self.allocator, '(');
        for (0..first) |idx| {
            if (idx != 0) try out.append(self.allocator, ';');
            try self.appendRenderedNumericPrototypeShape(out, shape[1..], elem_mode);
        }
        try out.append(self.allocator, ')');
    }

    fn appendRenderedNumericShape(
        self: *Session,
        out: *std.ArrayList(u8),
        value: Value,
        shape: []const i32,
        base: usize,
        elem_mode: HostDenseElem,
        render_mode: RenderMode,
    ) anyerror!void {
        if (shape.len <= 1) {
            const len: usize = if (shape.len == 0) 1 else @intCast(shape[0]);
            try self.appendRenderedNumericFlatVector(out, value, base, len, elem_mode);
            return;
        }

        const first: usize = @intCast(shape[0]);
        const block_len = try numericShapeDimsElementCount(shape[1..]);
        if (first == 0) {
            try out.appendSlice(self.allocator, "0#,");
            try self.appendRenderedNumericPrototypeShape(out, shape[1..], elem_mode);
            return;
        }
        if (first == 1) {
            try out.append(self.allocator, ',');
            try self.appendRenderedNumericShape(out, value, shape[1..], base, elem_mode, .nested);
            return;
        }

        try out.append(self.allocator, '(');
        for (0..first) |idx| {
            if (idx != 0) {
                if (render_mode == .top) {
                    try out.appendSlice(self.allocator, "\n ");
                } else {
                    try out.append(self.allocator, ';');
                }
            }
            try self.appendRenderedNumericShape(out, value, shape[1..], base + idx * block_len, elem_mode, .nested);
        }
        try out.append(self.allocator, ')');
    }

    fn renderNumericArrayShape(self: *Session, value: Value, shape: []const i32, elem_mode: HostDenseElem, render_mode: RenderMode) ![]u8 {
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);
        try self.appendRenderedNumericShape(&out, value, shape, 0, elem_mode, render_mode);
        return try out.toOwnedSlice(self.allocator);
    }

    fn appendRenderedHostBitVector(self: *Session, out: *std.ArrayList(u8), words: []const u64, base: usize, len: usize) !void {
        if (len == 0) {
            try out.appendSlice(self.allocator, "!0");
            return;
        }
        if (len == 1) try out.append(self.allocator, ',');
        for (0..len) |idx| try out.append(self.allocator, if (bitGet(words, base + idx)) '1' else '0');
        try out.append(self.allocator, 'b');
    }

    fn renderNumericArray(self: *Session, handle: *const NumericArray, render_mode: RenderMode) anyerror![]u8 {
        return switch (handle.activeAttachment()) {
            .host => self.renderHostNumericArray(handle, numericHostAttachment(handle) orelse return error.Internal, render_mode),
            .mlx => self.renderBackendArray(numericBackendAttachment(handle) orelse return error.Internal, render_mode),
            .none => blk: {
                const value = Value.numericArray(handle);
                if (!numericHasHostAttachment(handle) and hasBackendRealization(value)) {
                    _ = try tryEnsureHostRealizationForHandle(self, @constCast(handle)) orelse return error.Type;
                    break :blk try self.renderNumericArray(handle, render_mode);
                }
                const mode = valueNumericMode(Value.numericArray(handle)) orelse return error.Type;
                const len = numericFlatLen(value) orelse return error.Type;
                if (handle.rank == 0) return error.Internal;
                if (try numericShapeDimsElementCount(handle.shapeSlice()) != len) return error.Internal;
                break :blk try self.renderNumericArrayShape(value, handle.shapeSlice(), mode, render_mode);
            },
        };
    }

    fn renderHostNumericArray(self: *Session, handle: *const NumericArray, array: *const HostDenseArray, render_mode: RenderMode) anyerror![]u8 {
        const value = Value.numericArray(handle);
        const mode = valueNumericMode(value) orelse return error.Type;
        if (handle.rank <= 1) {
            if (array.storage == .bit) {
                var out = std.ArrayList(u8).empty;
                errdefer out.deinit(self.allocator);
                try self.appendRenderedHostBitVector(&out, array.storage.bit, 0, array.logical_len);
                return try out.toOwnedSlice(self.allocator);
            }
            var out = std.ArrayList(u8).empty;
            errdefer out.deinit(self.allocator);
            try self.appendRenderedNumericFlatVector(&out, value, 0, array.len(), mode);
            return try out.toOwnedSlice(self.allocator);
        }
        if (try numericShapeDimsElementCount(handle.shapeSlice()) != array.len()) return error.Internal;
        return try self.renderNumericArrayShape(value, handle.shapeSlice(), mode, render_mode);
    }

    fn appendRenderedHexBytes(self: *Session, out: *std.ArrayList(u8), bytes: []const u8) !void {
        const digits = "0123456789abcdef";
        try out.appendSlice(self.allocator, "0x");
        for (bytes) |byte| {
            try out.append(self.allocator, digits[byte >> 4]);
            try out.append(self.allocator, digits[byte & 0x0f]);
        }
    }

    fn bytesAreUtf8(bytes: []const u8) bool {
        _ = std.unicode.Utf8View.init(bytes) catch return false;
        return true;
    }

    fn appendRenderedHostStringBytes(self: *Session, out: *std.ArrayList(u8), bytes: []const u8) !void {
        if (!bytesAreUtf8(bytes)) {
            try self.appendRenderedHexBytes(out, bytes);
            return;
        }

        try out.append(self.allocator, '"');
        for (bytes) |byte| {
            if (byte == 0) {
                try out.appendSlice(self.allocator, "\\0");
            } else {
                try out.append(self.allocator, byte);
            }
        }
        try out.append(self.allocator, '"');
    }

    fn symbolBytesNeedQuotes(bytes: []const u8) bool {
        if (bytes.len == 0) return false;
        for (bytes) |byte| {
            if (std.ascii.isAlphanumeric(byte) or byte == '_') continue;
            return true;
        }
        return false;
    }

    fn appendRenderedHostSymbolBytes(self: *Session, out: *std.ArrayList(u8), bytes: []const u8) !void {
        try out.append(self.allocator, '`');
        if (!symbolBytesNeedQuotes(bytes)) {
            try out.appendSlice(self.allocator, bytes);
            return;
        }
        try out.append(self.allocator, '"');
        for (bytes) |byte| {
            if (byte == 0) {
                try out.appendSlice(self.allocator, "\\0");
            } else {
                try out.append(self.allocator, byte);
            }
        }
        try out.append(self.allocator, '"');
    }

    fn appendRenderedHostCharVectorBytes(self: *Session, out: *std.ArrayList(u8), bytes: []const u8) !void {
        if (bytes.len == 1) try out.append(self.allocator, ',');
        try self.appendRenderedHostStringBytes(out, bytes);
    }

    fn renderHostStringBytes(self: *Session, bytes: []const u8) anyerror![]u8 {
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);
        try self.appendRenderedHostStringBytes(&out, bytes);
        return try out.toOwnedSlice(self.allocator);
    }

    fn renderHostString(self: *Session, text: *const HostText) anyerror![]u8 {
        return self.renderHostStringBytes(hostTextBytes(text));
    }

    fn renderHostSymbol(self: *Session, text: *const HostText) anyerror![]u8 {
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);
        try self.appendRenderedHostSymbolBytes(&out, hostTextBytes(text));
        return try out.toOwnedSlice(self.allocator);
    }

    fn renderHostStringView(self: *Session, view: *const HostStringView) anyerror![]u8 {
        return self.renderHostStringBytes(hostStringViewBytes(view));
    }

    fn renderHostHandle(self: *Session, handle: *const HostHandle) anyerror![]u8 {
        return switch (handle.kind) {
            .duckdb => std.fmt.allocPrint(
                self.allocator,
                "handle[duckdb{s}]",
                .{if (handle.closed) ";closed" else ""},
            ),
            .file => if (handle.file_std_stream) |stream|
                std.fmt.allocPrint(
                    self.allocator,
                    "handle[{s}{s}]",
                    .{ @tagName(stream), if (handle.closed) ";closed" else "" },
                )
            else
                std.fmt.allocPrint(
                    self.allocator,
                    "handle[file;{s}{s}]",
                    .{ @tagName(handle.file_mode orelse .r), if (handle.closed) ";closed" else "" },
                ),
            .process => std.fmt.allocPrint(
                self.allocator,
                "handle[proc{s}]",
                .{if (handle.closed) ";closed" else ""},
            ),
            .tcp => std.fmt.allocPrint(
                self.allocator,
                "handle[tcp{s}]",
                .{if (handle.closed) ";closed" else ""},
            ),
        };
    }

    fn renderHostRelation(self: *Session, relation: *const HostRelation) anyerror![]u8 {
        return switch (relation.origin) {
            .file => |file| std.fmt.allocPrint(
                self.allocator,
                "relation[{s};\"{s}\"]",
                .{ file.source_kind.text(), file.path },
            ),
            .sql => |sql_info| std.fmt.allocPrint(
                self.allocator,
                "relation[sql;\"{s}\"]",
                .{sql_info.text},
            ),
        };
    }

    fn renderHostTableScalar(self: *Session, scalar: *const HostTableScalar) anyerror![]u8 {
        if (scalar.is_null) return try self.allocator.dupe(u8, "null");
        return switch (scalar.kind) {
            .boolean, .int, .float, .string => try self.renderValue(scalar.value),
            .date => try self.renderDateCell(scalar.value.asInt()),
            .time => try self.renderTimeCell(scalar.value.asInt()),
            .time_ns => try self.renderTimeNsCell(scalar.value.asInt()),
            .time_tz => try self.renderTimeTzCell(scalar.value.asInt()),
            .timestamp => try self.renderTimestampMicrosCell(scalar.value.asInt(), null),
            .timestamp_s => try self.renderTimestampScaledCell(scalar.value.asInt(), 1_000_000, null),
            .timestamp_ms => try self.renderTimestampScaledCell(scalar.value.asInt(), 1_000, null),
            .timestamp_ns => try self.renderTimestampNsCell(scalar.value.asInt(), null),
            .timestamp_tz => try self.renderTimestampMicrosCell(scalar.value.asInt(), "Z"),
        };
    }

    fn keyedStoreValues(store: *const HostKeyedStore) *const HostBoxedArray {
        std.debug.assert(store.values.tag() == .array and store.values.arrayKind() == .host_boxed_array);
        return store.values.asHostBoxedArray();
    }

    fn keyedStoreNameCount(store: *const HostKeyedStore) usize {
        return keyedStoreNamesValueCount(store.names);
    }

    fn keyedStoreNameValue(self: *Session, store: *const HostKeyedStore, idx: usize) KError!Value {
        if (stringSourceInfo(store.names)) |source| return try self.stringIndexScalarValue(source, @intCast(idx));
        return try self.derivedSequenceItemValue(store.names, idx);
    }

    fn keyedStoreUsesDenseValueFastPath(store: *const HostKeyedStore) bool {
        return store.layout == .dict and store.column_metadata == null;
    }

    fn keyedStoreTableMetadata(store: *const HostKeyedStore) []const HostKeyedColumnMetadata {
        std.debug.assert(store.layout == .table);
        return store.column_metadata orelse unreachable;
    }

    fn keyedStoreColumnNameBytes(store: *const HostKeyedStore, column_idx: usize) []const u8 {
        return switch (store.names.arrayKind()) {
            .host_boxed_array => blk: {
                const names = store.names.asHostBoxedArray().items;
                if (column_idx >= names.len) return "";
                break :blk symbolBytes(names[column_idx]) orelse stringBytes(names[column_idx]) orelse "";
            },
            .host_string_list, .host_symbol_list => hostStringListItemBytes(store.names.asHostStringList(), column_idx) catch "",
            else => "",
        };
    }

    fn tableColumnData(store: *const HostKeyedStore, column_idx: usize) Value {
        return keyedStoreValues(store).items[column_idx];
    }

    fn keyedStoreTableCellIsValid(store: *const HostKeyedStore, column_idx: usize, row: usize) bool {
        const validity = keyedStoreTableMetadata(store)[column_idx].validity orelse return true;
        return (numericIntAt(validity, @intCast(row)) catch 0) != 0;
    }

    fn nonFiniteTemporalText(self: *Session, raw: i64) ![]u8 {
        return try self.allocator.dupe(u8, if (raw < 0) "-inf" else "inf");
    }

    fn appendIsoYear(self: *Session, out: *std.ArrayList(u8), year: i32) !void {
        if (year < 0) {
            try out.append(self.allocator, '-');
            try out.print(self.allocator, "{d:0>4}", .{@as(u32, @intCast(-year))});
            return;
        }
        try out.print(self.allocator, "{d:0>4}", .{@as(u32, @intCast(year))});
    }

    fn appendTrimmedFractional(
        self: *Session,
        out: *std.ArrayList(u8),
        comptime width: comptime_int,
        value: u32,
    ) !void {
        if (value == 0) return;

        var buf: [width]u8 = undefined;
        const fmt = comptime std.fmt.comptimePrint("{{d:0>{}}}", .{width});
        const text = try std.fmt.bufPrint(&buf, fmt, .{value});

        var end = text.len;
        while (end > 0 and text[end - 1] == '0') : (end -= 1) {}
        if (end == 0) return;

        try out.append(self.allocator, '.');
        try out.appendSlice(self.allocator, text[0..end]);
    }

    const DivFloorResult = struct {
        quot: i64,
        rem: i64,
    };

    fn divFloorI64(value: i64, denom: i64) DivFloorResult {
        std.debug.assert(denom > 0);

        var quot = @divTrunc(value, denom);
        var rem = @rem(value, denom);
        if (rem < 0) {
            quot -= 1;
            rem += denom;
        }
        return .{ .quot = quot, .rem = rem };
    }

    fn renderDateCell(self: *Session, raw_days: i64) anyerror![]u8 {
        if (comptime !runtime_has_duckdb) return error.Unsupported;

        const days = std.math.cast(i32, raw_days) orelse return error.Unsupported;
        const date: duckdb_runtime.c.duckdb_date = .{ .days = days };
        if (!duckdb_runtime.c.duckdb_is_finite_date(date)) return try self.nonFiniteTemporalText(raw_days);

        const parts = duckdb_runtime.c.duckdb_from_date(date);
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);

        try self.appendIsoYear(&out, parts.year);
        try out.print(
            self.allocator,
            "-{d:0>2}-{d:0>2}",
            .{ @as(u32, @intCast(parts.month)), @as(u32, @intCast(parts.day)) },
        );
        return try out.toOwnedSlice(self.allocator);
    }

    fn renderTimeParts(self: *Session, parts: duckdb_runtime.c.duckdb_time_struct, fractional: ?u32, comptime width: comptime_int) anyerror![]u8 {
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);

        try out.print(
            self.allocator,
            "{d:0>2}:{d:0>2}:{d:0>2}",
            .{
                @as(u32, @intCast(parts.hour)),
                @as(u32, @intCast(parts.min)),
                @as(u32, @intCast(parts.sec)),
            },
        );
        if (fractional) |value| try self.appendTrimmedFractional(&out, width, value);
        return try out.toOwnedSlice(self.allocator);
    }

    fn renderTimeCell(self: *Session, raw_micros: i64) anyerror![]u8 {
        if (comptime !runtime_has_duckdb) return error.Unsupported;

        const parts = duckdb_runtime.c.duckdb_from_time(.{ .micros = raw_micros });
        return try self.renderTimeParts(parts, @intCast(parts.micros), 6);
    }

    fn renderTimeNsCell(self: *Session, raw_nanos: i64) anyerror![]u8 {
        if (comptime !runtime_has_duckdb) return error.Unsupported;

        const split = divFloorI64(raw_nanos, 1_000);
        const parts = duckdb_runtime.c.duckdb_from_time(.{ .micros = split.quot });
        const fractional = @as(u32, @intCast(parts.micros)) * 1_000 + @as(u32, @intCast(split.rem));
        return try self.renderTimeParts(parts, fractional, 9);
    }

    fn appendUtcOffset(self: *Session, out: *std.ArrayList(u8), raw_offset_seconds: i32) !void {
        const sign: u8 = if (raw_offset_seconds < 0) '-' else '+';
        const abs_seconds: u32 = @intCast(if (raw_offset_seconds < 0) -raw_offset_seconds else raw_offset_seconds);
        const hours = abs_seconds / 3_600;
        const minutes = (abs_seconds % 3_600) / 60;
        const seconds = abs_seconds % 60;

        try out.append(self.allocator, sign);
        try out.print(self.allocator, "{d:0>2}:{d:0>2}", .{ hours, minutes });
        if (seconds != 0) try out.print(self.allocator, ":{d:0>2}", .{seconds});
    }

    fn renderTimeTzCell(self: *Session, raw_bits: i64) anyerror![]u8 {
        if (comptime !runtime_has_duckdb) return error.Unsupported;

        const parts = duckdb_runtime.c.duckdb_from_time_tz(.{ .bits = @bitCast(raw_bits) });
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);

        try out.print(
            self.allocator,
            "{d:0>2}:{d:0>2}:{d:0>2}",
            .{
                @as(u32, @intCast(parts.time.hour)),
                @as(u32, @intCast(parts.time.min)),
                @as(u32, @intCast(parts.time.sec)),
            },
        );
        try self.appendTrimmedFractional(&out, 6, @intCast(parts.time.micros));
        try self.appendUtcOffset(&out, parts.offset);
        return try out.toOwnedSlice(self.allocator);
    }

    fn renderTimestampParts(
        self: *Session,
        parts: duckdb_runtime.c.duckdb_timestamp_struct,
        fractional: ?u32,
        comptime width: comptime_int,
        suffix: ?[]const u8,
    ) anyerror![]u8 {
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);

        try self.appendIsoYear(&out, parts.date.year);
        try out.print(
            self.allocator,
            "-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}",
            .{
                @as(u32, @intCast(parts.date.month)),
                @as(u32, @intCast(parts.date.day)),
                @as(u32, @intCast(parts.time.hour)),
                @as(u32, @intCast(parts.time.min)),
                @as(u32, @intCast(parts.time.sec)),
            },
        );
        if (fractional) |value| try self.appendTrimmedFractional(&out, width, value);
        if (suffix) |text| try out.appendSlice(self.allocator, text);
        return try out.toOwnedSlice(self.allocator);
    }

    fn renderTimestampMicrosCell(self: *Session, raw_micros: i64, suffix: ?[]const u8) anyerror![]u8 {
        if (comptime !runtime_has_duckdb) return error.Unsupported;

        const ts: duckdb_runtime.c.duckdb_timestamp = .{ .micros = raw_micros };
        if (!duckdb_runtime.c.duckdb_is_finite_timestamp(ts)) return try self.nonFiniteTemporalText(raw_micros);

        const parts = duckdb_runtime.c.duckdb_from_timestamp(ts);
        return try self.renderTimestampParts(parts, @intCast(parts.time.micros), 6, suffix);
    }

    fn renderTimestampScaledCell(
        self: *Session,
        raw_value: i64,
        scale_to_micros: i64,
        suffix: ?[]const u8,
    ) anyerror![]u8 {
        if (comptime !runtime_has_duckdb) return error.Unsupported;

        const micros = std.math.mul(i64, raw_value, scale_to_micros) catch return error.Unsupported;
        return try self.renderTimestampMicrosCell(micros, suffix);
    }

    fn renderTimestampNsCell(self: *Session, raw_nanos: i64, suffix: ?[]const u8) anyerror![]u8 {
        if (comptime !runtime_has_duckdb) return error.Unsupported;

        const split = divFloorI64(raw_nanos, 1_000);
        const ts: duckdb_runtime.c.duckdb_timestamp = .{ .micros = split.quot };
        if (!duckdb_runtime.c.duckdb_is_finite_timestamp(ts)) return try self.nonFiniteTemporalText(raw_nanos);

        const parts = duckdb_runtime.c.duckdb_from_timestamp(ts);
        const fractional = @as(u32, @intCast(parts.time.micros)) * 1_000 + @as(u32, @intCast(split.rem));
        return try self.renderTimestampParts(parts, fractional, 9, suffix);
    }

    fn renderTableCell(self: *Session, store: *const HostKeyedStore, column_idx: usize, row: usize) anyerror![]u8 {
        if (!keyedStoreTableCellIsValid(store, column_idx, row)) return try self.allocator.dupe(u8, "null");
        const kind = keyedStoreTableMetadata(store)[column_idx].kind;
        const data = tableColumnData(store, column_idx);
        return switch (kind) {
            .boolean => std.fmt.allocPrint(self.allocator, "{d}b", .{@intFromBool((try numericIntAt(data, @intCast(row))) != 0)}),
            .int => std.fmt.allocPrint(self.allocator, "{d}", .{try numericIntAt(data, @intCast(row))}),
            .float => formatFloat(self.allocator, try numericFloatAt(data, @intCast(row))),
            .string => blk: {
                const value = try self.hostTextListItemValue(data, row);
                defer self.releaseValue(value);
                break :blk try self.renderValue(value);
            },
            .date => try self.renderDateCell(try numericIntAt(data, @intCast(row))),
            .time => try self.renderTimeCell(try numericIntAt(data, @intCast(row))),
            .time_ns => try self.renderTimeNsCell(try numericIntAt(data, @intCast(row))),
            .time_tz => try self.renderTimeTzCell(try numericIntAt(data, @intCast(row))),
            .timestamp => try self.renderTimestampMicrosCell(try numericIntAt(data, @intCast(row)), null),
            .timestamp_s => try self.renderTimestampScaledCell(try numericIntAt(data, @intCast(row)), 1_000_000, null),
            .timestamp_ms => try self.renderTimestampScaledCell(try numericIntAt(data, @intCast(row)), 1_000, null),
            .timestamp_ns => try self.renderTimestampNsCell(try numericIntAt(data, @intCast(row)), null),
            .timestamp_tz => try self.renderTimestampMicrosCell(try numericIntAt(data, @intCast(row)), "Z"),
        };
    }

    fn renderTableStore(self: *Session, store: *const HostKeyedStore) anyerror![]u8 {
        std.debug.assert(store.layout == .table);
        const column_count = keyedStoreNameCount(store);
        var widths = try self.allocator.alloc(usize, column_count);
        defer self.allocator.free(widths);

        for (0..column_count) |idx| {
            widths[idx] = keyedStoreColumnNameBytes(store, idx).len;
        }
        for (0..store.row_count) |row| {
            for (0..column_count) |idx| {
                const cell = try self.renderTableCell(store, idx, row);
                defer self.allocator.free(cell);
                widths[idx] = @max(widths[idx], cell.len);
            }
        }

        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);

        for (0..column_count) |idx| {
            if (idx != 0) try out.append(self.allocator, ' ');
            const name = keyedStoreColumnNameBytes(store, idx);
            try out.appendSlice(self.allocator, name);
            if (idx + 1 != column_count and widths[idx] > name.len) {
                try out.appendNTimes(self.allocator, ' ', widths[idx] - name.len);
            }
        }

        if (column_count != 0) {
            try out.append(self.allocator, '\n');
            for (widths, 0..) |width, idx| {
                if (idx != 0) try out.append(self.allocator, ' ');
                try out.appendNTimes(self.allocator, '-', width);
            }
        }

        for (0..store.row_count) |row| {
            if (column_count != 0 or row != 0) try out.append(self.allocator, '\n');
            for (0..column_count) |idx| {
                if (idx != 0) try out.append(self.allocator, ' ');
                const cell = try self.renderTableCell(store, idx, row);
                defer self.allocator.free(cell);
                try out.appendSlice(self.allocator, cell);
                if (idx + 1 != column_count and widths[idx] > cell.len) {
                    try out.appendNTimes(self.allocator, ' ', widths[idx] - cell.len);
                }
            }
        }

        return try out.toOwnedSlice(self.allocator);
    }

    fn renderHostKeyedStore(self: *Session, store: *const HostKeyedStore) anyerror![]u8 {
        if (store.layout == .table) return try self.renderTableStore(store);
        const keys = try self.renderKeyedStoreKeySide(store.names);
        defer self.allocator.free(keys);
        const values = try self.renderValueMode(store.values, .nested);
        defer self.allocator.free(values);
        return try std.fmt.allocPrint(self.allocator, "{s}!{s}", .{ keys, values });
    }

    fn renderKeyedStoreKeySide(self: *Session, names: Value) anyerror![]u8 {
        const rendered = try self.renderValueMode(names, .nested);
        errdefer self.allocator.free(rendered);
        if (!keyedStoreKeySideNeedsParens(names)) return rendered;
        const wrapped = try std.fmt.allocPrint(self.allocator, "({s})", .{rendered});
        self.allocator.free(rendered);
        return wrapped;
    }

    fn keyedStoreKeySideNeedsParens(names: Value) bool {
        if (names.tag() != .array) return false;
        const len = derivedSequenceLen(names) orelse return false;
        return switch (names.arrayKind()) {
            .host_boxed_array, .host_string => len == 1,
            .host_string_list => names.asHostStringList().display != .list and len < 2,
            .host_symbol_list => len < 2,
            else => if (valueNumericHandle(names) != null) len < 2 else false,
        };
    }

    fn renderHostStringList(self: *Session, list: *const HostStringList, render_mode: RenderMode) anyerror![]u8 {
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);
        if (list.display == .list) {
            try out.append(self.allocator, '(');
            for (0..list.len) |idx| {
                if (idx != 0) try out.append(self.allocator, ';');
                try self.appendRenderedHostStringBytes(&out, try hostStringListItemBytes(list, idx));
            }
            try out.append(self.allocator, ')');
            return try out.toOwnedSlice(self.allocator);
        }

        if (list.len == 0) {
            try out.appendSlice(self.allocator, "()");
            return try out.toOwnedSlice(self.allocator);
        }
        if (list.len == 1) {
            try out.append(self.allocator, ',');
            try self.appendRenderedHostCharVectorBytes(&out, try hostStringListItemBytes(list, 0));
            return try out.toOwnedSlice(self.allocator);
        }

        try out.append(self.allocator, '(');
        for (0..list.len) |idx| {
            if (idx != 0) {
                if (render_mode == .top) {
                    try out.appendSlice(self.allocator, "\n ");
                } else {
                    try out.append(self.allocator, ';');
                }
            }
            try self.appendRenderedHostCharVectorBytes(&out, try hostStringListItemBytes(list, idx));
        }
        try out.append(self.allocator, ')');
        return try out.toOwnedSlice(self.allocator);
    }

    fn renderHostSymbolList(self: *Session, list: *const HostStringList) anyerror![]u8 {
        if (list.len == 0) return try self.allocator.dupe(u8, "0#`");

        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);
        if (list.len == 1) try out.append(self.allocator, ',');
        for (0..list.len) |idx| {
            try self.appendRenderedHostSymbolBytes(&out, try hostStringListItemBytes(list, idx));
        }
        return try out.toOwnedSlice(self.allocator);
    }

    fn hostBoxedArrayAllSymbols(array: *const HostBoxedArray) bool {
        const items = array.items[0..array.len()];
        if (items.len == 0) return false;
        for (items) |item| {
            if (symbolBytes(item) == null) return false;
        }
        return true;
    }

    fn hostBoxedArrayUsesTopLevelRows(array: *const HostBoxedArray) bool {
        const items = array.items[0..array.len()];
        if (items.len <= 1) return false;

        var has_numeric_vector = false;
        var has_string_rows = false;
        for (items) |item| {
            switch (item.tag()) {
                .int, .bool, .float => {},
                .array => {
                    if (symbolBytes(item) != null) continue;
                    if (item.arrayKind() == .host_string_list or item.arrayKind() == .host_symbol_list or item.arrayKind() == .host_boxed_array) {
                        has_string_rows = true;
                        continue;
                    }
                    if (valueNumericMode(item) != null and numericVectorLen(item) != null) {
                        has_numeric_vector = true;
                        continue;
                    }
                    return false;
                },
                else => return false,
            }
        }
        return has_numeric_vector or has_string_rows;
    }

    fn renderHostArray(self: *Session, array: *const HostDenseArray) anyerror![]u8 {
        if (array.logical_len == 0) switch (array.storage) {
            .bit, .int8, .int16, .int32, .int64 => return try self.allocator.dupe(u8, "!0"),
            .float32, .float64 => return try self.allocator.dupe(u8, "0#0n"),
        };

        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);

        switch (array.storage) {
            .bit => |words| {
                for (0..array.logical_len) |idx| try out.append(self.allocator, if (bitGet(words, idx)) '1' else '0');
                try out.append(self.allocator, 'b');
            },
            .int8 => |items| {
                for (hostDenseLogicalItems(i8, array, items), 0..) |item, idx| {
                    if (idx != 0) try out.append(self.allocator, ' ');
                    try appendRenderedInt(&out, self.allocator, item);
                }
            },
            .int16 => |items| {
                for (hostDenseLogicalItems(i16, array, items), 0..) |item, idx| {
                    if (idx != 0) try out.append(self.allocator, ' ');
                    try appendRenderedInt(&out, self.allocator, item);
                }
            },
            .int32 => |items| {
                for (hostDenseLogicalItems(i32, array, items), 0..) |item, idx| {
                    if (idx != 0) try out.append(self.allocator, ' ');
                    try appendRenderedInt(&out, self.allocator, item);
                }
            },
            .int64 => |items| {
                for (hostDenseLogicalItems(i64, array, items), 0..) |item, idx| {
                    if (idx != 0) try out.append(self.allocator, ' ');
                    try appendRenderedInt(&out, self.allocator, item);
                }
            },
            .float32 => |items| {
                for (hostDenseLogicalItems(f32, array, items), 0..) |item, idx| {
                    if (idx != 0) try out.append(self.allocator, ' ');
                    const part = try formatFloat(self.allocator, @as(f64, item));
                    defer self.allocator.free(part);
                    try out.appendSlice(self.allocator, part);
                }
            },
            .float64 => |items| {
                for (hostDenseLogicalItems(f64, array, items), 0..) |item, idx| {
                    if (idx != 0) try out.append(self.allocator, ' ');
                    const part = try formatFloat(self.allocator, item);
                    defer self.allocator.free(part);
                    try out.appendSlice(self.allocator, part);
                }
            },
        }

        return try out.toOwnedSlice(self.allocator);
    }

    fn renderHostBoxedArray(self: *Session, array: *const HostBoxedArray, render_mode: RenderMode) anyerror![]u8 {
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);
        const items = array.items[0..array.len()];

        if (items.len == 0) {
            if (array.prototype) |prototype| {
                if (stringBytes(prototype)) |bytes| {
                    if (bytes.len == 0) {
                        try out.appendSlice(self.allocator, "()");
                        return try out.toOwnedSlice(self.allocator);
                    }
                }
                try out.appendSlice(self.allocator, "0#,");
                const part = try self.renderValueMode(prototype, .nested);
                defer self.allocator.free(part);
                try out.appendSlice(self.allocator, part);
            } else {
                try out.appendSlice(self.allocator, "()");
            }
        } else if (items.len > 1 and hostBoxedArrayAllSymbols(array)) {
            for (items) |item| {
                const part = try self.renderValueMode(item, .nested);
                defer self.allocator.free(part);
                try out.appendSlice(self.allocator, part);
            }
        } else if (items.len == 1) {
            try out.append(self.allocator, ',');
            const item = items[0];
            const part = try self.renderValueMode(item, .nested);
            defer self.allocator.free(part);
            try out.appendSlice(self.allocator, part);
        } else if (isRenderableMatrix(items) or (render_mode == .top and hostBoxedArrayUsesTopLevelRows(array))) {
            const matrix_like = isRenderableMatrix(items);
            if (render_mode == .top or matrix_like) try out.append(self.allocator, '(');
            for (items, 0..) |item, idx| {
                if (idx != 0) {
                    if (render_mode == .top) {
                        try out.appendSlice(self.allocator, "\n ");
                    } else {
                        try out.append(self.allocator, ';');
                    }
                }
                const part = try self.renderValueMode(item, .nested);
                defer self.allocator.free(part);
                try out.appendSlice(self.allocator, part);
            }
            if (render_mode == .top or matrix_like) try out.append(self.allocator, ')');
        } else {
            try out.append(self.allocator, '(');
            for (items, 0..) |item, idx| {
                if (idx != 0) try out.append(self.allocator, ';');
                const part = try self.renderValueMode(item, .nested);
                defer self.allocator.free(part);
                try out.appendSlice(self.allocator, part);
            }
            try out.append(self.allocator, ')');
        }

        return try out.toOwnedSlice(self.allocator);
    }

    fn renderBackendArray(self: *Session, array: *const BackendArray, render_mode: RenderMode) anyerror![]u8 {
        return runtime_backend_render.renderBackendArray(backend_render_api, self, array, render_mode == .top);
    }

    fn managedFloat(self: *Session, value: f64) !Value {
        _ = self;
        return Value.float(value);
    }

    fn scratchFloat(self: *Session, value: f64) !Value {
        _ = self;
        return Value.float(value);
    }

    fn scratchFloat32(self: *Session, value: f32) !Value {
        _ = self;
        return Value.float32(value);
    }

    fn managedInt(self: *Session, value: i64) !Value {
        const box = if (self.free_boxed_int_len != 0) blk: {
            self.free_boxed_int_len -= 1;
            break :blk self.free_boxed_ints[self.free_boxed_int_len].?;
        } else try self.allocator.create(BoxedInt);
        box.* = .{
            .header = HeapHeader.init(.boxed_int, .managed),
            .value = value,
        };
        return Value.boxedInt(box);
    }

    fn enlistValue(self: *Session, value: Value) !Value {
        return switch (value.tag()) {
            .int => try self.createManagedHostIntArray(&[_]i64{value.asInt()}),
            .bool => try self.createManagedHostBitArray(&[_]bool{value.asBool()}),
            .float32 => try self.createManagedHostFloat32Array(&[_]f32{value.asFloat32()}),
            .float => try self.createManagedHostFloatArray(&[_]f64{value.asFloat()}),
            else => try self.createManagedHostBoxedArray(&.{value}),
        };
    }

    fn frozenEmptyHostBoxedArray(self: *Session) !Value {
        const array = try self.arena.allocator().create(HostBoxedArray);
        const items = try self.arena.allocator().alloc(Value, 0);
        array.* = .{
            .header = HeapHeader.init(.host_boxed_array, .frozen),
            .logical_len = 0,
            .items = items,
        };
        return Value.array(array);
    }

    fn scratchInt(self: *Session, value: i64) !Value {
        return try allocBoxedInt(self.scratch_arena.allocator(), .scratch, value);
    }

    fn allocManagedClosure(self: *Session, kind: ClosureKind, code: *const Code, captures: []const Value) !*Closure {
        const closure = if (self.free_closure_len != 0) blk: {
            self.free_closure_len -= 1;
            break :blk self.free_closures[self.free_closure_len].?;
        } else try self.allocator.create(Closure);
        closure.* = .{
            .header = HeapHeader.init(.closure, .managed),
            .kind = kind,
            .code = code,
            .captures = captures,
        };
        return closure;
    }

    fn allocManagedProjectionClosure(self: *Session, callee: Value, slot_count: u8, hole_mask: u64, slot_values: []const Value) !Value {
        std.debug.assert(slot_values.len == slot_count);
        const captures = try self.allocator.alloc(Value, 3 + slot_values.len);
        errdefer self.allocator.free(captures);
        var initialized: usize = 0;
        errdefer {
            while (initialized > 0) {
                initialized -= 1;
                self.releaseValue(captures[initialized]);
            }
        }

        captures[0] = try self.retainEscapedValue(callee);
        initialized += 1;
        captures[1] = try self.intValue(@intCast(slot_count));
        initialized += 1;
        captures[2] = try self.intValue(std.math.cast(i64, hole_mask) orelse return error.Unsupported);
        initialized += 1;
        for (slot_values, 0..) |value, idx| {
            captures[3 + idx] = try self.retainEscapedValue(value);
            initialized += 1;
        }

        if (comptime enable_probe_instrumentation) self.debug.projection_closure_alloc_count += 1;
        return Value.closure(try self.allocManagedClosure(.projection, &projection_code, captures));
    }

    fn allocFrozenProjectionClosure(self: *Session, callee: Value, slot_count: u8, hole_mask: u64, slot_values: []const Value) !Value {
        std.debug.assert(slot_values.len == slot_count);
        if (slot_count > 63) return error.Unsupported;
        const captures = try self.arena.allocator().alloc(Value, 3 + slot_values.len);
        captures[0] = try self.freezeConstantValue(callee);
        captures[1] = try self.freezeConstantValue(try self.intValue(@intCast(slot_count)));
        captures[2] = try self.freezeConstantValue(try self.intValue(std.math.cast(i64, hole_mask) orelse return error.Unsupported));
        for (slot_values, 0..) |value, idx| {
            captures[3 + idx] = try self.freezeConstantValue(value);
        }

        const closure = try self.arena.allocator().create(Closure);
        closure.* = .{
            .header = HeapHeader.init(.closure, .frozen),
            .kind = .projection,
            .code = &projection_code,
            .captures = captures,
        };
        return Value.closure(closure);
    }

    fn allocFrozenMonadicBuiltinClosure(self: *Session, builtin: BuiltinId) !Value {
        const captures = try self.arena.allocator().alloc(Value, 1);
        captures[0] = Value.builtin(builtin);
        const closure = try self.arena.allocator().create(Closure);
        closure.* = .{
            .header = HeapHeader.init(.closure, .frozen),
            .kind = .monadic_builtin,
            .code = &monadic_builtin_code,
            .captures = captures,
        };
        return Value.closure(closure);
    }

    fn allocFrozenDerivedClosure(self: *Session, kind: DerivedVerbKind, base: Value) !*Closure {
        const captures = try self.arena.allocator().alloc(Value, 1);
        captures[0] = try self.freezeConstantValue(base);
        const closure = try self.arena.allocator().create(Closure);
        closure.* = .{
            .header = HeapHeader.init(.closure, .frozen),
            .kind = ClosureKind.fromDerived(kind),
            .code = derivedCode(kind),
            .captures = captures,
        };
        return closure;
    }

    fn allocManagedDerivedClosure(self: *Session, kind: DerivedVerbKind, base: Value) !*Closure {
        const captures = try self.allocator.alloc(Value, 1);
        errdefer self.allocator.free(captures);
        captures[0] = try self.retainEscapedValue(base);
        errdefer self.releaseValue(captures[0]);
        return try self.allocManagedClosure(ClosureKind.fromDerived(kind), derivedCode(kind), captures);
    }

    fn adverbBaseCanStayFrozen(base: Value) bool {
        return switch (base.tag()) {
            .int, .bool, .float, .float32 => true,
            .builtin => true,
            .closure => base.asClosure().header.owner == .frozen or base.asClosure().captures.len == 0,
            .array => base.arrayOwner() == .frozen,
        };
    }

    fn allocDerivedClosure(self: *Session, kind: DerivedVerbKind, base: Value) !*Closure {
        if (adverbBaseCanStayFrozen(base)) return try self.allocFrozenDerivedClosure(kind, base);
        return try self.allocManagedDerivedClosure(kind, base);
    }

    fn allocFrozenInnerProductClosure(self: *Session, reduce: BuiltinId, map: BuiltinId) !*Closure {
        const captures = try self.arena.allocator().alloc(Value, 2);
        captures[0] = try self.freezeConstantValue(Value.builtin(reduce));
        captures[1] = try self.freezeConstantValue(Value.builtin(map));
        const closure = try self.arena.allocator().create(Closure);
        closure.* = .{
            .header = HeapHeader.init(.closure, .frozen),
            .kind = .inner_product,
            .code = &inner_product_code,
            .captures = captures,
        };
        return closure;
    }

    fn allocFrozenCompositionClosure(self: *Session, outer: Value, inner: Value) !*Closure {
        const captures = try self.arena.allocator().alloc(Value, 2);
        captures[0] = try self.freezeConstantValue(outer);
        captures[1] = try self.freezeConstantValue(inner);
        const closure = try self.arena.allocator().create(Closure);
        closure.* = .{
            .header = HeapHeader.init(.closure, .frozen),
            .kind = .composition,
            .code = &composition_code,
            .captures = captures,
        };
        return closure;
    }

    fn allocManagedCompositionClosure(self: *Session, outer: Value, inner: Value) !Value {
        const captures = try self.allocator.alloc(Value, 2);
        errdefer self.allocator.free(captures);
        captures[0] = try self.retainEscapedValue(outer);
        errdefer self.releaseValue(captures[0]);
        captures[1] = try self.retainEscapedValue(inner);
        errdefer self.releaseValue(captures[1]);
        return Value.closure(try self.allocManagedClosure(.composition, &composition_code, captures));
    }

    fn allocFrozenDerivedClosureWithCaptures(self: *Session, kind: DerivedVerbKind, captures_in: []const Value) !*Closure {
        const captures = try self.arena.allocator().alloc(Value, captures_in.len);
        for (captures_in, 0..) |capture, idx| {
            captures[idx] = try self.freezeConstantValue(capture);
        }
        const closure = try self.arena.allocator().create(Closure);
        closure.* = .{
            .header = HeapHeader.init(.closure, .frozen),
            .kind = ClosureKind.fromDerived(kind),
            .code = derivedCode(kind),
            .captures = captures,
        };
        return closure;
    }

    fn shouldPoolManagedHostTextBuffer(byte_len: usize) bool {
        return byte_len >= managed_host_text_pool_min_len and byte_len <= managed_host_text_pool_max_len;
    }

    fn freeManagedHostTextBuffer(self: *Session, entry: ManagedHostTextBufferEntry) void {
        const ptr: [*]align(@alignOf(HostText)) u8 = @ptrCast(@alignCast(entry.ptr));
        self.allocator.free(ptr[0..hostTextAllocLen(entry.len)]);
    }

    fn takeManagedHostTextBuffer(self: *Session, byte_len: usize) ?[]align(@alignOf(HostText)) u8 {
        if (!shouldPoolManagedHostTextBuffer(byte_len)) return null;
        const count = self.free_host_text_buffer_len;
        if (count == 0) return null;

        var idx = count;
        while (idx > 0) {
            idx -= 1;
            const entry = self.free_host_text_buffers[idx].?;
            if (entry.len != byte_len) continue;
            const last_idx = count - 1;
            self.free_host_text_buffers[idx] = self.free_host_text_buffers[last_idx];
            self.free_host_text_buffers[last_idx] = null;
            self.free_host_text_buffer_len = count - 1;
            const ptr: [*]align(@alignOf(HostText)) u8 = @ptrCast(@alignCast(entry.ptr));
            return ptr[0..hostTextAllocLen(byte_len)];
        }

        return null;
    }

    fn allocManagedHostTextBuffer(self: *Session, byte_len: usize) ![]align(@alignOf(HostText)) u8 {
        return self.takeManagedHostTextBuffer(byte_len) orelse try hostTextAllocSlice(self.allocator, byte_len);
    }

    fn recycleManagedHostText(self: *Session, text: *HostText) void {
        const byte_len = text.len;
        if (!shouldPoolManagedHostTextBuffer(byte_len) or self.free_host_text_buffer_len >= max_pooled_objects) {
            freeHostTextAlloc(self.allocator, text);
            return;
        }
        const count = self.free_host_text_buffer_len;
        self.free_host_text_buffers[count] = .{
            .ptr = @ptrCast(text),
            .len = byte_len,
        };
        self.free_host_text_buffer_len = count + 1;
    }

    fn managedHostDenseBufferByteLen(comptime T: type, len: usize) usize {
        return len * @sizeOf(T);
    }

    fn debugManagedHostDensePoolBytes(self: *const Session) usize {
        if (comptime !enable_probe_instrumentation) return 0;
        var total: usize = 0;
        inline for (@typeInfo(HostDenseStorageKind).@"enum".field_values) |field_value| {
            const kind: HostDenseStorageKind = @fromBackingInt(@intCast(field_value));
            const pool_idx = @backingInt(kind);
            const elem_bytes = hostDenseStorageElemBytes(kind);
            for (self.free_host_dense_buffers[pool_idx][0..self.free_host_dense_buffer_len[pool_idx]]) |maybe_entry| {
                const entry = maybe_entry orelse continue;
                total += entry.len * elem_bytes;
            }
        }
        return total;
    }

    fn noteDebugMorselPhase(self: *Session, executor: MorselExecutorKind, workers_requested: usize, workers_used: usize, len: usize, grain: usize, morsels: usize) void {
        if (comptime !enable_probe_instrumentation) return;
        if (self.debug.morsel_phase_count == 0) {
            self.debug.morsel_executor = executor;
        } else if (self.debug.morsel_executor != executor) {
            self.debug.morsel_executor = .mixed;
        }
        self.debug.morsel_workers_requested = @max(self.debug.morsel_workers_requested, workers_requested);
        self.debug.morsel_workers_used = @max(self.debug.morsel_workers_used, workers_used);
        self.debug.morsel_count += morsels;
        self.debug.morsel_grain_size = @max(self.debug.morsel_grain_size, grain);
        self.debug.morsel_phase_count += 1;
        if (workers_used > 1) self.debug.morsel_parallel_phase_count += 1;
        self.debug.morsel_element_count += len;
    }

    fn noteDebugManagedHostDenseAcquire(self: *Session, comptime T: type, len: usize, reused: bool) void {
        if (comptime !enable_probe_instrumentation) return;
        const bytes = managedHostDenseBufferByteLen(T, len);
        if (reused) {
            self.debug.host_dense_storage_reuse_count += 1;
            self.debug.host_dense_storage_reuse_bytes += bytes;
        } else {
            self.debug.host_dense_storage_alloc_count += 1;
            self.debug.host_dense_storage_alloc_bytes += bytes;
        }
        self.debug.host_dense_active_bytes += bytes;
        self.debug.host_dense_peak_active_bytes = @max(self.debug.host_dense_peak_active_bytes, self.debug.host_dense_active_bytes);
    }

    fn noteDebugScratchHostDenseAcquire(self: *Session, comptime T: type, len: usize) void {
        if (comptime !enable_probe_instrumentation) return;
        const bytes = managedHostDenseBufferByteLen(T, len);
        self.debug.host_dense_storage_alloc_count += 1;
        self.debug.host_dense_storage_alloc_bytes += bytes;
        self.debug.host_dense_active_bytes += bytes;
        self.debug.host_dense_scratch_active_bytes += bytes;
        self.debug.host_dense_peak_active_bytes = @max(self.debug.host_dense_peak_active_bytes, self.debug.host_dense_active_bytes);
    }

    fn noteDebugManagedHostDenseRelease(self: *Session, comptime T: type, len: usize, pooled: bool) void {
        if (comptime !enable_probe_instrumentation) return;
        const bytes = managedHostDenseBufferByteLen(T, len);
        if (pooled) {
            self.debug.host_dense_storage_recycle_count += 1;
            self.debug.host_dense_storage_recycle_bytes += bytes;
        } else {
            self.debug.host_dense_storage_free_count += 1;
            self.debug.host_dense_storage_free_bytes += bytes;
        }
        std.debug.assert(self.debug.host_dense_active_bytes >= bytes);
        self.debug.host_dense_active_bytes -= bytes;
    }

    fn noteDebugManagedHostDenseFreeInactive(self: *Session, comptime T: type, len: usize) void {
        if (comptime !enable_probe_instrumentation) return;
        const bytes = managedHostDenseBufferByteLen(T, len);
        self.debug.host_dense_storage_free_count += 1;
        self.debug.host_dense_storage_free_bytes += bytes;
    }

    fn noteDebugHostDenseScratchArenaReset(self: *Session) void {
        if (comptime !enable_probe_instrumentation) return;
        const bytes = self.debug.host_dense_scratch_active_bytes;
        if (bytes == 0) return;
        std.debug.assert(self.debug.host_dense_active_bytes >= bytes);
        self.debug.host_dense_storage_free_count += 1;
        self.debug.host_dense_storage_free_bytes += bytes;
        self.debug.host_dense_active_bytes -= bytes;
        self.debug.host_dense_scratch_active_bytes = 0;
    }

    fn resetScratchArenaRetainCapacity(self: *Session) void {
        _ = self.scratch_arena.reset(.retain_capacity);
        self.noteDebugHostDenseScratchArenaReset();
    }

    fn allocFreshManagedHostDenseBuffer(self: *Session, comptime T: type, len: usize) ![]T {
        const items = try self.allocator.alloc(T, len);
        self.noteDebugManagedHostDenseAcquire(T, len, false);
        return items;
    }

    fn allocManagedHostDenseBuffer(self: *Session, comptime T: type, comptime kind: HostDenseStorageKind, len: usize) ![]T {
        return self.takeManagedHostDenseBuffer(T, kind, len) orelse try self.allocFreshManagedHostDenseBuffer(T, len);
    }

    fn freeManagedHostDenseBuffer(self: *Session, kind: HostDenseStorageKind, entry: ManagedHostDenseBufferEntry) void {
        switch (kind) {
            .bit => {
                const ptr: [*]u64 = @ptrCast(@alignCast(entry.ptr));
                self.noteDebugManagedHostDenseFreeInactive(u64, entry.len);
                self.allocator.free(ptr[0..entry.len]);
            },
            .int8 => {
                const ptr: [*]i8 = @ptrCast(@alignCast(entry.ptr));
                self.noteDebugManagedHostDenseFreeInactive(i8, entry.len);
                self.allocator.free(ptr[0..entry.len]);
            },
            .int16 => {
                const ptr: [*]i16 = @ptrCast(@alignCast(entry.ptr));
                self.noteDebugManagedHostDenseFreeInactive(i16, entry.len);
                self.allocator.free(ptr[0..entry.len]);
            },
            .int32 => {
                const ptr: [*]i32 = @ptrCast(@alignCast(entry.ptr));
                self.noteDebugManagedHostDenseFreeInactive(i32, entry.len);
                self.allocator.free(ptr[0..entry.len]);
            },
            .int64 => {
                const ptr: [*]i64 = @ptrCast(@alignCast(entry.ptr));
                self.noteDebugManagedHostDenseFreeInactive(i64, entry.len);
                self.allocator.free(ptr[0..entry.len]);
            },
            .float32 => {
                const ptr: [*]f32 = @ptrCast(@alignCast(entry.ptr));
                self.noteDebugManagedHostDenseFreeInactive(f32, entry.len);
                self.allocator.free(ptr[0..entry.len]);
            },
            .float64 => {
                const ptr: [*]f64 = @ptrCast(@alignCast(entry.ptr));
                self.noteDebugManagedHostDenseFreeInactive(f64, entry.len);
                self.allocator.free(ptr[0..entry.len]);
            },
        }
    }

    fn takeManagedHostDenseBuffer(self: *Session, comptime T: type, comptime kind: HostDenseStorageKind, len: usize) ?[]T {
        if (len == 0) return null;
        const pool_idx = @backingInt(kind);
        const count = self.free_host_dense_buffer_len[pool_idx];
        if (count == 0) return null;

        var idx = count;
        while (idx > 0) {
            idx -= 1;
            const entry = self.free_host_dense_buffers[pool_idx][idx].?;
            if (entry.len != len) continue;
            const last_idx = count - 1;
            self.free_host_dense_buffers[pool_idx][idx] = self.free_host_dense_buffers[pool_idx][last_idx];
            self.free_host_dense_buffers[pool_idx][last_idx] = null;
            self.free_host_dense_buffer_len[pool_idx] -= 1;
            const ptr: [*]T = @ptrCast(@alignCast(entry.ptr));
            self.noteDebugManagedHostDenseAcquire(T, len, true);
            return ptr[0..len];
        }

        return null;
    }

    fn recycleManagedHostDenseBuffer(self: *Session, comptime T: type, comptime kind: HostDenseStorageKind, items: []T) void {
        if (items.len == 0) {
            self.noteDebugManagedHostDenseRelease(T, items.len, false);
            self.allocator.free(items);
            return;
        }
        const pool_idx = @backingInt(kind);
        const count = self.free_host_dense_buffer_len[pool_idx];
        if (count >= max_pooled_objects) {
            self.noteDebugManagedHostDenseRelease(T, items.len, false);
            self.allocator.free(items);
            return;
        }
        self.noteDebugManagedHostDenseRelease(T, items.len, true);
        self.free_host_dense_buffers[pool_idx][count] = .{
            .ptr = @ptrCast(items.ptr),
            .len = items.len,
        };
        self.free_host_dense_buffer_len[pool_idx] = count + 1;
    }

    fn recycleManagedHostDenseStorage(self: *Session, storage: HostDenseStorage) void {
        switch (storage) {
            .bit => |words| self.recycleManagedHostDenseBuffer(u64, .bit, words),
            .int8 => |items| self.recycleManagedHostDenseBuffer(i8, .int8, items),
            .int16 => |items| self.recycleManagedHostDenseBuffer(i16, .int16, items),
            .int32 => |items| self.recycleManagedHostDenseBuffer(i32, .int32, items),
            .int64 => |items| self.recycleManagedHostDenseBuffer(i64, .int64, items),
            .float32 => |items| self.recycleManagedHostDenseBuffer(f32, .float32, items),
            .float64 => |items| self.recycleManagedHostDenseBuffer(f64, .float64, items),
        }
    }

    fn allocManagedHostDenseStorage(self: *Session, kind: HostDenseStorageKind, capacity_len: usize) !HostDenseStorage {
        return switch (kind) {
            .bit => blk: {
                const word_count = bitWordCount(capacity_len);
                const words = try self.allocManagedHostDenseBuffer(u64, .bit, word_count);
                @memset(words, 0);
                break :blk .{ .bit = words };
            },
            .int8 => .{ .int8 = try self.allocManagedHostDenseBuffer(i8, .int8, capacity_len) },
            .int16 => .{ .int16 = try self.allocManagedHostDenseBuffer(i16, .int16, capacity_len) },
            .int32 => .{ .int32 = try self.allocManagedHostDenseBuffer(i32, .int32, capacity_len) },
            .int64 => .{ .int64 = try self.allocManagedHostDenseBuffer(i64, .int64, capacity_len) },
            .float32 => .{ .float32 = try self.allocManagedHostDenseBuffer(f32, .float32, capacity_len) },
            .float64 => .{ .float64 = try self.allocManagedHostDenseBuffer(f64, .float64, capacity_len) },
        };
    }

    fn copyHostDenseIntToStorage(array: *const HostDenseArray, storage: HostDenseStorage, len: usize) KError!void {
        switch (storage) {
            .bit => |words| {
                for (0..len) |idx| {
                    const value = try hostDenseIntAt(array, idx);
                    if (value != 0 and value != 1) return error.Unsupported;
                    bitSet(words, idx, value == 1);
                }
            },
            .int8 => |items| {
                for (0..len) |idx| items[idx] = std.math.cast(i8, try hostDenseIntAt(array, idx)) orelse return error.Unsupported;
            },
            .int16 => |items| {
                for (0..len) |idx| items[idx] = std.math.cast(i16, try hostDenseIntAt(array, idx)) orelse return error.Unsupported;
            },
            .int32 => |items| {
                for (0..len) |idx| items[idx] = std.math.cast(i32, try hostDenseIntAt(array, idx)) orelse return error.Unsupported;
            },
            .int64 => |items| {
                for (0..len) |idx| items[idx] = try hostDenseIntAt(array, idx);
            },
            .float32 => return error.Type,
            .float64 => return error.Type,
        }
    }

    fn ensureManagedHostDenseIntCapacity(self: *Session, array: *HostDenseArray, result_kind: HostIntStorageKind, required_len: usize) KError!void {
        const target_storage_kind = hostDenseStorageKindForIntKind(result_kind);
        const current_storage_kind = std.meta.activeTag(array.storage);
        if (current_storage_kind == target_storage_kind and hostDenseStorageCapacityLen(array) >= required_len) return;

        const old_len = array.logical_len;
        const new_capacity_len = hostDenseGrowCapacityLen(target_storage_kind, hostDenseStorageCapacityLen(array), required_len);
        const new_storage = try self.allocManagedHostDenseStorage(target_storage_kind, new_capacity_len);
        errdefer self.recycleManagedHostDenseStorage(new_storage);

        try copyHostDenseIntToStorage(array, new_storage, old_len);
        const old_storage = array.storage;
        array.storage = new_storage;
        self.recycleManagedHostDenseStorage(old_storage);
    }

    fn allocHostArrayAttachmentTypedCapacity(self: *Session, comptime T: type, comptime kind: HostDenseStorageKind, owner: HeapOwner, len: usize, capacity_len: usize) !HostDenseAttachmentAlloc(T) {
        std.debug.assert(capacity_len >= len);
        const allocator = switch (owner) {
            .managed => self.allocator,
            .scratch => self.scratch_arena.allocator(),
            .frozen => self.arena.allocator(),
        };
        if (comptime enable_probe_instrumentation) {
            if (owner == .scratch) self.debug.scratch_host_array_alloc_count += 1;
        }
        const array = if (owner == .managed and self.free_host_array_len != 0) blk: {
            self.free_host_array_len -= 1;
            break :blk self.free_host_arrays[self.free_host_array_len].?;
        } else try allocator.create(HostDenseArray);
        const storage_items = switch (owner) {
            .managed => try self.allocManagedHostDenseBuffer(T, kind, capacity_len),
            .scratch => blk: {
                const items = try allocator.alloc(T, capacity_len);
                self.noteDebugScratchHostDenseAcquire(T, capacity_len);
                break :blk items;
            },
            .frozen => try allocator.alloc(T, capacity_len),
        };
        array.logical_len = len;
        array.flags = 0;
        hostDenseClearCachedIntRange(array);
        hostDenseResetFindCacheState(array);
        array.storage = switch (kind) {
            .bit => unreachable,
            .int8 => .{ .int8 = storage_items },
            .int16 => .{ .int16 = storage_items },
            .int32 => .{ .int32 = storage_items },
            .int64 => .{ .int64 = storage_items },
            .float32 => .{ .float32 = storage_items },
            .float64 => .{ .float64 = storage_items },
        };
        return .{ .array = array, .items = storage_items[0..len] };
    }

    fn allocHostArrayAttachmentTyped(self: *Session, comptime T: type, comptime kind: HostDenseStorageKind, owner: HeapOwner, len: usize) !HostDenseAttachmentAlloc(T) {
        return self.allocHostArrayAttachmentTypedCapacity(T, kind, owner, len, len);
    }

    fn allocHostArrayTyped(self: *Session, comptime T: type, comptime kind: HostDenseStorageKind, owner: HeapOwner, len: usize) !HostDenseAlloc(T) {
        const out = try self.allocHostArrayAttachmentTyped(T, kind, owner, len);
        errdefer if (owner == .managed) self.recycleManagedHostArray(out.array);
        const value = try newNumericArrayValue(self, owner, .host, out.array, null);
        return .{ .result_value = value, .array = out.array, .items = out.items };
    }

    fn allocHostArrayTypedForHandle(self: *Session, comptime T: type, comptime kind: HostDenseStorageKind, owner: HeapOwner, handle: *const NumericArray, len: usize) !HostDenseAlloc(T) {
        const out = try self.allocHostArrayAttachmentTyped(T, kind, owner, len);
        return .{ .result_value = Value.numericArray(handle), .array = out.array, .items = out.items };
    }

    fn allocHostBitAttachmentWithInitCapacity(self: *Session, owner: HeapOwner, len: usize, capacity_len: usize, zero: bool) !HostBitAttachmentAlloc {
        std.debug.assert(capacity_len >= len);
        const allocator = switch (owner) {
            .managed => self.allocator,
            .scratch => self.scratch_arena.allocator(),
            .frozen => self.arena.allocator(),
        };
        if (comptime enable_probe_instrumentation) {
            if (owner == .scratch) self.debug.scratch_host_array_alloc_count += 1;
        }
        const array = if (owner == .managed and self.free_host_array_len != 0) blk: {
            self.free_host_array_len -= 1;
            break :blk self.free_host_arrays[self.free_host_array_len].?;
        } else try allocator.create(HostDenseArray);
        const word_count = bitWordCount(len);
        const storage_word_count = bitWordCount(capacity_len);
        const words = switch (owner) {
            .managed => try self.allocManagedHostDenseBuffer(u64, .bit, storage_word_count),
            .scratch => blk: {
                const items = try allocator.alloc(u64, storage_word_count);
                self.noteDebugScratchHostDenseAcquire(u64, storage_word_count);
                break :blk items;
            },
            .frozen => try allocator.alloc(u64, storage_word_count),
        };
        if (zero) @memset(words, 0);
        array.logical_len = len;
        array.flags = 0;
        hostDenseClearCachedIntRange(array);
        hostDenseResetFindCacheState(array);
        array.storage = .{ .bit = words };
        return .{ .array = array, .words = words[0..word_count], .len = len };
    }

    fn allocHostBitAttachmentWithInit(self: *Session, owner: HeapOwner, len: usize, zero: bool) !HostBitAttachmentAlloc {
        return self.allocHostBitAttachmentWithInitCapacity(owner, len, len, zero);
    }

    fn allocHostBitArrayWithInit(self: *Session, owner: HeapOwner, len: usize, zero: bool) !HostBitAlloc {
        const out = try self.allocHostBitAttachmentWithInit(owner, len, zero);
        errdefer if (owner == .managed) self.recycleManagedHostArray(out.array);
        const value = try newNumericArrayValue(self, owner, .host, out.array, null);
        return .{ .result_value = value, .array = out.array, .words = out.words, .len = out.len };
    }

    fn allocHostBitArrayForHandleWithInit(self: *Session, owner: HeapOwner, handle: *const NumericArray, len: usize, zero: bool) !HostBitAlloc {
        const out = try self.allocHostBitAttachmentWithInit(owner, len, zero);
        return .{ .result_value = Value.numericArray(handle), .array = out.array, .words = out.words, .len = out.len };
    }

    fn allocHostBitArray(self: *Session, owner: HeapOwner, len: usize) !HostBitAlloc {
        return try self.allocHostBitArrayWithInit(owner, len, true);
    }

    fn allocHostBitArrayUninitialized(self: *Session, owner: HeapOwner, len: usize) !HostBitAlloc {
        return try self.allocHostBitArrayWithInit(owner, len, false);
    }

    fn allocHostBitArrayForHandle(self: *Session, owner: HeapOwner, handle: *const NumericArray, len: usize) !HostBitAlloc {
        return try self.allocHostBitArrayForHandleWithInit(owner, handle, len, true);
    }

    fn allocHostBitArrayForHandleUninitialized(self: *Session, owner: HeapOwner, handle: *const NumericArray, len: usize) !HostBitAlloc {
        return try self.allocHostBitArrayForHandleWithInit(owner, handle, len, false);
    }

    fn allocManagedHostIntResult(self: *Session, kind: HostIntStorageKind, len: usize) !HostIntResult {
        return switch (kind) {
            .bit => .{ .bit = try self.allocHostBitArray(.managed, len) },
            .int8 => .{ .int8 = try self.allocHostArrayTyped(i8, .int8, .managed, len) },
            .int16 => .{ .int16 = try self.allocHostArrayTyped(i16, .int16, .managed, len) },
            .int32 => .{ .int32 = try self.allocHostArrayTyped(i32, .int32, .managed, len) },
