    fn runCode(self: *Session, code: *const Code, args: []const Value) KError!Value {
        return try self.runCodeMode(code, args, true);
    }

    fn runCodeMode(self: *Session, code: *const Code, args: []const Value, root_results: bool) KError!Value {
        if (!codeCanRunWithArgLen(code, args.len)) return error.Arity;
        self.resetScratchArenaRetainCapacity();
        return try self.runCodeModePrepared(code, args, root_results);
    }

    fn runScratchCodeMode(self: *Session, code: *const Code, args: []const Value, root_results: bool) KError!Value {
        if (!codeCanRunWithArgLen(code, args.len)) return error.Arity;
        return try self.runCodeModePrepared(code, args, root_results);
    }

    fn runCodeModePrepared(self: *Session, code: *const Code, args: []const Value, root_results: bool) KError!Value {
        const result = try self.runCodeBorrowed(code, args);
        if (!root_results) return result;
        const escaped = if (valueMayNeedRelease(result)) try self.retainEscapedValue(result) else result;
        if (valueMayNeedRelease(result)) self.releaseValue(result);
        return try self.finishResult(escaped);
    }

    fn runClosureMode(self: *Session, closure: *const Closure, args: []const Value, root_results: bool) KError!Value {
        if (codeForRunnablePlainClosureArgs(closure, args)) |compact| {
            const result = try self.runCodeBorrowed(compact, codeRunArgs(compact, args));
            return if (root_results) try self.finishResult(result) else result;
        }
        return error.Unsupported;
    }

    fn tryFastLocalConstDyadValue(self: *Session, left: Value, op: BuiltinId, rhs_const: i64, const_first: bool) KError!?Value {
        if (inlineIntBoolValue(left)) |left_value| {
            if (comptime enable_probe_instrumentation) self.debug.inline_scalar_dyad_attempt_count += 1;
            const lhs = if (const_first) rhs_const else left_value;
            const rhs = if (const_first) left_value else rhs_const;
            const result: ?Value = switch (op) {
                .add => blk: {
                    const added = @addWithOverflow(lhs, rhs);
                    if (added[1] != 0) break :blk null;
                    break :blk try self.intValue(added[0]);
                },
                .sub => blk: {
                    const subbed = @subWithOverflow(lhs, rhs);
                    if (subbed[1] != 0) break :blk null;
                    break :blk try self.intValue(subbed[0]);
                },
                .mul => blk: {
                    const multiplied = @mulWithOverflow(lhs, rhs);
                    if (multiplied[1] != 0) break :blk null;
                    break :blk try self.intValue(multiplied[0]);
                },
                .div => try self.floatValue(@as(f64, @floatFromInt(lhs)) / @as(f64, @floatFromInt(rhs))),
                .iota => try self.intValue(bangIntOp(lhs, rhs)),
                .minimum => try self.intValue(@min(lhs, rhs)),
                .maximum => try self.intValue(@max(lhs, rhs)),
                .less => Value.fromBool(lhs < rhs),
                .more => Value.fromBool(lhs > rhs),
                .equal => Value.fromBool(lhs == rhs),
                else => null,
            };
            if (comptime enable_probe_instrumentation) {
                if (result != null) self.debug.inline_scalar_dyad_hit_count += 1 else self.debug.inline_scalar_dyad_fallback_count += 1;
            }
            return result;
        }

        const left_float = inlineNumericFloatValue(left) orelse return null;
        if (comptime enable_probe_instrumentation) self.debug.inline_scalar_dyad_attempt_count += 1;
        const rhs_float: f64 = @floatFromInt(rhs_const);
        const lhs = if (const_first) rhs_float else left_float;
        const rhs = if (const_first) left_float else rhs_float;
        const result_kind = scalarFloatStorageKind(left) orelse .float64;
        const float_result = struct {
            fn value(session: *Session, kind: HostFloatStorageKind, raw: f64) KError!Value {
                return switch (kind) {
                    .float32 => try session.float32Value(@floatCast(raw)),
                    .float64 => try session.floatValue(raw),
                };
            }
        }.value;
        const result: ?Value = switch (op) {
            .add => try float_result(self, result_kind, lhs + rhs),
            .sub => try float_result(self, result_kind, lhs - rhs),
            .mul => try float_result(self, result_kind, lhs * rhs),
            .div => try float_result(self, result_kind, lhs / rhs),
            .iota => if (const_first) try float_result(self, result_kind, bangFloatOp(rhs_const, left_float)) else null,
            .minimum => try float_result(self, result_kind, @min(lhs, rhs)),
            .maximum => try float_result(self, result_kind, @max(lhs, rhs)),
            .less => Value.fromBool(lhs < rhs),
            .more => Value.fromBool(lhs > rhs),
            .equal => Value.fromBool(lhs == rhs),
            else => null,
        };
        if (comptime enable_probe_instrumentation) {
            if (result != null) self.debug.inline_scalar_dyad_hit_count += 1 else self.debug.inline_scalar_dyad_fallback_count += 1;
        }
        return result;
    }

    fn applyLocalConstOpValue(self: *Session, left: Value, op: BuiltinId, rhs: i64) KError!Value {
        if (try self.tryFastLocalConstDyadValue(left, op, rhs, false)) |result| return result;
        if (scalarIntLikeValue(left)) |lhs| {
            switch (op) {
                .add => {
                    const result = @addWithOverflow(lhs, rhs);
                    if (result[1] == 0) return try self.intValue(result[0]);
                },
                .sub => {
                    const result = @subWithOverflow(lhs, rhs);
                    if (result[1] == 0) return try self.intValue(result[0]);
                },
                .mul => {
                    const result = @mulWithOverflow(lhs, rhs);
                    if (result[1] == 0) return try self.intValue(result[0]);
                },
                else => return error.Unsupported,
            }
        }

        const right = try self.intValue(rhs);
        defer self.releaseValue(right);
        return switch (op) {
            .add => try self.addValues(left, right),
            .sub => try self.subValues(left, right),
            .mul => try self.mulValues(left, right),
            else => error.Unsupported,
        };
    }

    fn applyConstLocalOpValue(self: *Session, lhs: i64, op: BuiltinId, right: Value) KError!Value {
        if (try self.tryFastLocalConstDyadValue(right, op, lhs, true)) |result| return result;
        const left = try self.intValue(lhs);
        defer self.releaseValue(left);
        return switch (op) {
            .add => try self.addValues(left, right),
            .sub => try self.subValues(left, right),
            .mul => try self.mulValues(left, right),
            else => error.Unsupported,
        };
    }

    fn applyBorrowedDyadValue(self: *Session, op: BuiltinId, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(op, left, right)) |result| return result;
        return switch (op) {
            .add => try self.addValues(left, right),
            .sub => try self.subValues(left, right),
            .mul => try self.mulValues(left, right),
            .div => try self.divValues(left, right),
            .iota => try self.bangValues(left, right),
            .minimum => try self.minimumValues(left, right),
            .maximum => try self.maximumValues(left, right),
            .less => try self.lessValues(left, right),
            .more => try self.moreValues(left, right),
            .equal => try self.equalValues(left, right),
            else => error.Unsupported,
        };
    }

    fn applyShapedBorrowedDyadValue(self: *Session, op: BuiltinId, left: Value, right: Value) KError!Value {
        if (comptime enable_probe_instrumentation) self.debug.shaped_scalar_dyad_count += 1;
        return try self.applyBorrowedDyadValue(op, left, right);
    }

    fn applyLocalConstDyadValue(self: *Session, left: Value, op: BuiltinId, rhs: i64) KError!Value {
        if (comptime enable_probe_instrumentation) self.debug.shaped_scalar_dyad_count += 1;
        if (try self.tryFastLocalConstDyadValue(left, op, rhs, false)) |result| return result;
        const right = try self.intValue(rhs);
        defer self.releaseValue(right);
        return try self.applyBorrowedDyadValue(op, left, right);
    }

    fn applyConstLocalDyadValue(self: *Session, lhs: i64, op: BuiltinId, right: Value) KError!Value {
        if (comptime enable_probe_instrumentation) self.debug.shaped_scalar_dyad_count += 1;
        if (try self.tryFastLocalConstDyadValue(right, op, lhs, true)) |result| return result;
        const left = try self.intValue(lhs);
        defer self.releaseValue(left);
        return try self.applyBorrowedDyadValue(op, left, right);
    }

    inline fn directReadI64(bytes: []const u8, start: usize) ?i64 {
        const end = start + 8;
        if (end > bytes.len) return null;
        var value: u64 = 0;
        var idx: usize = 0;
        while (idx < 8) : (idx += 1) {
            value |= @as(u64, bytes[start + idx]) << @intCast(idx * 8);
        }
        return @bitCast(value);
    }

    inline fn directReadU16(bytes: []const u8, start: usize) ?u16 {
        const end = start + 2;
        if (end > bytes.len) return null;
        return @as(u16, bytes[start]) | (@as(u16, bytes[start + 1]) << 8);
    }

    fn valueIsBuiltin(value: Value, builtin: BuiltinId) bool {
        return value.tag() == .builtin and value.asBuiltin() == builtin;
    }

    fn compactBuiltinValueLen(bytes: []const u8, constants: []const Value, builtin: BuiltinId) ?usize {
        if (bytes.len >= 2 and bytes[0] == ck_const_builtin_u8) {
            const found: BuiltinId = @fromBackingInt(@intCast(bytes[1]));
            if (found == builtin) return 2;
        }
        if (bytes.len >= 1 and compactIsConstValueOpcode(bytes[0])) {
            const slot = bytes[0] - ck_const_value_base;
            if (slot < constants.len and valueIsBuiltin(constants[slot], builtin)) return 1;
        }
        if (bytes.len >= 2 and bytes[0] == ck_const_value_u8) {
            const slot = bytes[1];
            if (slot < constants.len and valueIsBuiltin(constants[slot], builtin)) return 2;
        }
        return null;
    }

    const DirectConditionalAtom = enum {
        arg0,
        arg1,
        zero,
    };

    const DirectConditionalCompare = struct {
        lhs: DirectConditionalAtom,
        rhs: DirectConditionalAtom,
        cmp: BuiltinId,
    };

    const DirectConditionalBranch = struct {
        compare: DirectConditionalCompare,
        false_target: usize,
    };

    const DenseElementwiseKind = union(enum) {
        dyad: struct {
            op: BuiltinId,
            swap: bool,
        },
        keep_left_if_more,
    };

    const DenseAddFoldProducerKind = enum {
        map,
        unary_map,
        squared_diff,
        compare_count,
    };

    const CompactDenseProducerSourceKind = enum {
        local,
        global_scalar,
        scalar,
    };

    const CompactDenseProducerSource = struct {
        kind: CompactDenseProducerSourceKind = .local,
        slot: u8 = 0,
        global_slot: u16 = 0,
        reverse: bool = false,
        scalar: Value = Value.fromBool(false),
    };

    const DenseAddFoldMapInfo = struct {
        kind: DenseAddFoldProducerKind = .map,
        map: BuiltinId = .add,
        left: CompactDenseProducerSource = .{ .slot = 0 },
        right: CompactDenseProducerSource = .{ .slot = 1 },
    };

    const compact_dense_producer_max_nodes: usize = 8;
    const CompactDenseProducerNodeRef = u8;

    const CompactDenseProducerNode = union(enum) {
        source: CompactDenseProducerSource,
        unary: struct {
            op: BuiltinId,
            child: CompactDenseProducerNodeRef,
        },
        binary: struct {
            op: BuiltinId,
            left: CompactDenseProducerNodeRef,
            right: CompactDenseProducerNodeRef,
        },
    };

    const CompactDenseProducerProgram = struct {
        nodes: [compact_dense_producer_max_nodes]CompactDenseProducerNode = undefined,
        len: usize = 0,
        root: CompactDenseProducerNodeRef = 0,

        fn push(self: *CompactDenseProducerProgram, node: CompactDenseProducerNode) ?CompactDenseProducerNodeRef {
            if (self.len >= compact_dense_producer_max_nodes) return null;
            const ref: CompactDenseProducerNodeRef = @intCast(self.len);
            self.nodes[self.len] = node;
            self.len += 1;
            return ref;
        }

        fn get(self: *const CompactDenseProducerProgram, ref: CompactDenseProducerNodeRef) ?CompactDenseProducerNode {
            const idx: usize = ref;
            if (idx >= self.len) return null;
            return self.nodes[idx];
        }
    };

    const CompactDenseProducerStackItem = union(enum) {
        node: CompactDenseProducerNodeRef,
        value: Value,
    };

    const CompactDenseProducerStack = struct {
        items: [compact_dense_producer_max_nodes]CompactDenseProducerStackItem = undefined,
        len: usize = 0,

        fn pushNode(self: *CompactDenseProducerStack, program: *CompactDenseProducerProgram, node: CompactDenseProducerNode) bool {
            if (self.len >= self.items.len) return false;
            const ref = program.push(node) orelse return false;
            self.items[self.len] = .{ .node = ref };
            self.len += 1;
            return true;
        }

        fn pushValue(self: *CompactDenseProducerStack, value: Value) bool {
            if (self.len >= self.items.len) return false;
            self.items[self.len] = .{ .value = value };
            self.len += 1;
            return true;
        }

        fn popNode(self: *CompactDenseProducerStack) ?CompactDenseProducerNodeRef {
            if (self.len == 0) return null;
            return switch (self.items[self.len - 1]) {
                .node => |ref| blk: {
                    self.len -= 1;
                    break :blk ref;
                },
                .value => null,
            };
        }

        fn popValue(self: *CompactDenseProducerStack) ?Value {
            if (self.len == 0) return null;
            return switch (self.items[self.len - 1]) {
                .value => |value| blk: {
                    self.len -= 1;
                    break :blk value;
                },
                .node => null,
            };
        }

        fn root(self: *const CompactDenseProducerStack) ?CompactDenseProducerNodeRef {
            if (self.len != 1) return null;
            return switch (self.items[0]) {
                .node => |ref| ref,
                .value => null,
            };
        }
    };

    fn valueIsAddFoldCallable(value: Value) bool {
        return isDerivedBuiltinClosure(value, .fold, .add);
    }

    fn compactAddFoldCallableLen(bytes: []const u8, constants: []const Value) ?usize {
        if (compactBuiltinValueLen(bytes, constants, .add)) |base_len| {
            if (bytes.len >= base_len + 2 and
                bytes[base_len] == ck_make_adverb_u8 and
                bytes[base_len + 1] == @backingInt(DerivedVerbKind.fold))
            {
                return base_len + 2;
            }
        }
        if (bytes.len >= 1 and compactIsConstValueOpcode(bytes[0])) {
            const slot = bytes[0] - ck_const_value_base;
            if (slot < constants.len and valueIsAddFoldCallable(constants[slot])) return 1;
        }
        if (bytes.len >= 2 and bytes[0] == ck_const_value_u8) {
            const slot = bytes[1];
            if (slot < constants.len and valueIsAddFoldCallable(constants[slot])) return 2;
        }
        return null;
    }

    fn compactDenseScalarSource(value: Value) ?CompactDenseProducerSource {
        return switch (value.tag()) {
            .float, .float32, .int, .bool => .{ .kind = .scalar, .scalar = value },
            else => null,
        };
    }

    fn compactReadConstantValue(bytes: []const u8, constants: []const Value, idx: *usize) ?Value {
        if (idx.* >= bytes.len) return null;
        const raw = bytes[idx.*];
        idx.* += 1;
        if (compactIsConstValueOpcode(raw)) {
            const slot = raw - ck_const_value_base;
            if (slot >= constants.len) return null;
            return constants[slot];
        }
        if (raw == ck_const_value_u8) {
            if (idx.* >= bytes.len) return null;
            const slot = bytes[idx.*];
            idx.* += 1;
            if (slot >= constants.len) return null;
            return constants[slot];
        }
        if (raw == ck_const_builtin_u8) {
            if (idx.* >= bytes.len) return null;
            const builtin: BuiltinId = @fromBackingInt(@intCast(bytes[idx.*]));
            idx.* += 1;
            return Value.builtin(builtin);
        }
        return null;
    }

    fn compactDenseReadProducerSource(bytes: []const u8, constants: []const Value, idx: *usize) ?CompactDenseProducerSource {
        if (idx.* >= bytes.len) return null;
        const raw = bytes[idx.*];
        if (compactLocalReadSlot(raw)) |slot| {
            idx.* += 1;
            var reverse = false;
            if (idx.* < bytes.len and bytes[idx.*] == ckMonad(ckm_reverse)) {
                reverse = true;
                idx.* += 1;
            }
            return .{ .slot = slot, .reverse = reverse };
        }

        idx.* += 1;
        if (raw == ck_load_global_u8) {
            if (idx.* >= bytes.len) return null;
            const slot = bytes[idx.*];
            idx.* += 1;
            return .{ .kind = .global_scalar, .global_slot = slot };
        }
        if (raw == ck_ext_u16) {
            if (idx.* >= bytes.len or bytes[idx.*] != ck_load_global_u8) return null;
            idx.* += 1;
            const slot = compactReadPayloadU16(bytes, idx) orelse return null;
            return .{ .kind = .global_scalar, .global_slot = slot };
        }
        if (compactIsConstValueOpcode(raw)) {
            const slot = raw - ck_const_value_base;
            if (slot >= constants.len) return null;
            return compactDenseScalarSource(constants[slot]);
        }
        switch (raw) {
            ck_const_i8 => {
                if (idx.* >= bytes.len) return null;
                const value: i8 = @bitCast(bytes[idx.*]);
                idx.* += 1;
                return compactDenseScalarSource(Value.int(value) catch return null);
            },
            ck_const_i64 => {
                const value = compactReadPayloadI64(bytes, idx) orelse return null;
                return compactDenseScalarSource(Value.int(value) catch return null);
            },
            ck_const_value_u8 => {
                if (idx.* >= bytes.len) return null;
                const slot = bytes[idx.*];
                idx.* += 1;
                if (slot >= constants.len) return null;
                return compactDenseScalarSource(constants[slot]);
            },
            ck_const_false => return compactDenseScalarSource(Value.fromBool(false)),
            ck_const_true => return compactDenseScalarSource(Value.fromBool(true)),
            else => return null,
        }
    }

    fn compactDenseSourceEqual(left: CompactDenseProducerSource, right: CompactDenseProducerSource) bool {
        if (left.kind != right.kind) return false;
        return switch (left.kind) {
            .local => left.slot == right.slot and left.reverse == right.reverse,
            .global_scalar => left.global_slot == right.global_slot,
            .scalar => left.scalar.raw == right.scalar.raw,
        };
    }

    fn compactDenseSourcesAreArgs01(left: CompactDenseProducerSource, right: CompactDenseProducerSource) bool {
        return left.kind == .local and right.kind == .local and
            ((left.slot == 0 and right.slot == 1) or (left.slot == 1 and right.slot == 0));
    }

    fn compactDenseSourcesAreSupportedInputs(left: CompactDenseProducerSource, right: CompactDenseProducerSource) bool {
        if (compactDenseSourcesAreArgs01(left, right)) return true;
        if (left.kind == .local and right.kind == .scalar) return left.slot == 0;
        if (left.kind == .scalar and right.kind == .local) return right.slot == 0;
        if (left.kind == .local and right.kind == .global_scalar) return left.slot == 0;
        if (left.kind == .global_scalar and right.kind == .local) return right.slot == 0;
        return false;
    }

    fn compactDensePlainArgs01Swap(left: CompactDenseProducerSource, right: CompactDenseProducerSource) ?bool {
        if (left.kind != .local or right.kind != .local or left.reverse or right.reverse) return null;
        if (left.slot == 0 and right.slot == 1) return false;
        if (left.slot == 1 and right.slot == 0) return true;
        return null;
    }

    fn compactDenseUnarySourceIsSupportedInput(source: CompactDenseProducerSource) bool {
        return source.kind == .local and source.slot == 0;
    }

    fn compactDenseUnaryBuiltinValue(value: Value) ?BuiltinId {
        if (value.tag() == .builtin) return value.asBuiltin();
        if (value.tag() != .closure) return null;
        const closure = value.asClosure();
        if (!closureIsMonadicBuiltin(closure)) return null;
        if (closure.captures.len != 1 or closure.captures[0].tag() != .builtin) return null;
        return closure.captures[0].asBuiltin();
    }

    fn compactDenseUnaryReverseCompositionOp(value: Value) ?BuiltinId {
        if (value.tag() != .closure) return null;
        const closure = value.asClosure();
        if (closure.kind != .composition or closure.captures.len != 2) return null;
        const outer = compactDenseUnaryBuiltinValue(closure.captures[0]) orelse return null;
        const inner = compactDenseUnaryBuiltinValue(closure.captures[1]) orelse return null;
        if (inner != .reverse and inner != .maximum) return null;
        if (!denseFloatUnarySimdSupported(outer)) return null;
        return outer;
    }

    fn compactDensePushFixedDyadProducer(
        program: *CompactDenseProducerProgram,
        stack: *CompactDenseProducerStack,
        op: BuiltinId,
        left_slot: u8,
        right_slot: u8,
    ) bool {
        const left = program.push(.{ .source = .{ .slot = left_slot } }) orelse return false;
        const right = program.push(.{ .source = .{ .slot = right_slot } }) orelse return false;
        return stack.pushNode(program, .{ .binary = .{
            .op = op,
            .left = left,
            .right = right,
        } });
    }

    fn compactDenseReadProducerProgram(bytes: []const u8, constants: []const Value) ?CompactDenseProducerProgram {
        var program = CompactDenseProducerProgram{};
        var stack = CompactDenseProducerStack{};
        var idx: usize = 0;
        while (idx < bytes.len) {
            const raw = bytes[idx];

            if (compactDenseFixedDyad(raw)) |op| {
                if (idx + 3 > bytes.len) return null;
                if (!compactDensePushFixedDyadProducer(&program, &stack, op, bytes[idx + 1], bytes[idx + 2])) return null;
                idx += 3;
                continue;
            }

            var source_idx = idx;
            if (compactDenseReadProducerSource(bytes, constants, &source_idx)) |source| {
                if (!stack.pushNode(&program, .{ .source = source })) return null;
                idx = source_idx;
                continue;
            }

            var value_idx = idx;
            if (compactReadConstantValue(bytes, constants, &value_idx)) |value| {
                if (!stack.pushValue(value)) return null;
                idx = value_idx;
                continue;
            }

            if (compactIsMonadOpcode(raw)) {
                const op = compactMonadBuiltin(raw - ck_monad_base) orelse return null;
                if (!denseFloatUnarySimdSupported(op)) return null;
                const child = stack.popNode() orelse return null;
                if (!stack.pushNode(&program, .{ .unary = .{ .op = op, .child = child } })) return null;
                idx += 1;
                continue;
            }

            if (compactDenseDyadRange(raw)) |op| {
                const left = stack.popNode() orelse return null;
                const right = stack.popNode() orelse return null;
                if (!stack.pushNode(&program, .{ .binary = .{
                    .op = op,
                    .left = left,
                    .right = right,
                } })) return null;
                idx += 1;
                continue;
            }

            if (raw == ck_call_stack_u8) {
                var call_idx = idx;
                if ((compactReadCallStackArgc(bytes, &call_idx) orelse return null) != 1) return null;
                const callee = stack.popValue() orelse return null;
                const arg = stack.popNode() orelse return null;
                const op = compactDenseUnaryReverseCompositionOp(callee) orelse return null;
                var source = compactDenseProducerSourceNode(&program, arg) orelse return null;
                source.reverse = !source.reverse;
                const source_ref = program.push(.{ .source = source }) orelse return null;
                if (!stack.pushNode(&program, .{ .unary = .{ .op = op, .child = source_ref } })) return null;
                idx = call_idx;
                continue;
            }

            return null;
        }

        program.root = stack.root() orelse return null;
        return program;
    }

    fn compactDenseProducerSourceNode(program: *const CompactDenseProducerProgram, ref: CompactDenseProducerNodeRef) ?CompactDenseProducerSource {
        const node = program.get(ref) orelse return null;
        return switch (node) {
            .source => |source| source,
            else => null,
        };
    }

    fn compactDenseProducerBinaryNode(program: *const CompactDenseProducerProgram, ref: CompactDenseProducerNodeRef) ?struct { op: BuiltinId, left: CompactDenseProducerNodeRef, right: CompactDenseProducerNodeRef } {
        const node = program.get(ref) orelse return null;
        return switch (node) {
            .binary => |binary| .{ .op = binary.op, .left = binary.left, .right = binary.right },
            else => null,
        };
    }

    fn compactDenseProducerBinarySources(program: *const CompactDenseProducerProgram, ref: CompactDenseProducerNodeRef) ?struct { op: BuiltinId, left: CompactDenseProducerSource, right: CompactDenseProducerSource } {
        const binary = compactDenseProducerBinaryNode(program, ref) orelse return null;
        return .{
            .op = binary.op,
            .left = compactDenseProducerSourceNode(program, binary.left) orelse return null,
            .right = compactDenseProducerSourceNode(program, binary.right) orelse return null,
        };
    }

    fn compactDenseSquaredDiffProducerInfo(program: *const CompactDenseProducerProgram, root: CompactDenseProducerNodeRef) ?DenseAddFoldMapInfo {
        const root_binary = compactDenseProducerBinaryNode(program, root) orelse return null;
        if (root_binary.op != .mul) return null;
        const left = compactDenseProducerBinarySources(program, root_binary.left) orelse return null;
        const right = compactDenseProducerBinarySources(program, root_binary.right) orelse return null;
        if (left.op != .sub or right.op != .sub) return null;
        if (!compactDenseSourceEqual(left.left, right.left) or !compactDenseSourceEqual(left.right, right.right)) return null;
        if (!compactDenseSourcesAreSupportedInputs(left.left, left.right)) return null;
        return .{ .kind = .squared_diff, .left = left.left, .right = left.right };
    }

    fn compactDenseProducerInfoFromProgram(program: *const CompactDenseProducerProgram) ?DenseAddFoldMapInfo {
        const root = program.get(program.root) orelse return null;
        return switch (root) {
            .source => null,
            .unary => |unary| blk: {
                const source = compactDenseProducerSourceNode(program, unary.child) orelse break :blk null;
                if (!compactDenseUnarySourceIsSupportedInput(source)) break :blk null;
                if (!denseFloatUnarySimdSupported(unary.op)) break :blk null;
                break :blk .{ .kind = .unary_map, .map = unary.op, .left = source };
            },
            .binary => blk: {
                if (compactDenseSquaredDiffProducerInfo(program, program.root)) |info| break :blk info;
                const binary = compactDenseProducerBinarySources(program, program.root) orelse break :blk null;
                if (!compactDenseSourcesAreSupportedInputs(binary.left, binary.right)) break :blk null;
                if (denseFloatSimdSupported(binary.op)) break :blk .{ .kind = .map, .map = binary.op, .left = binary.left, .right = binary.right };
                if (denseCompareSupported(binary.op)) break :blk .{ .kind = .compare_count, .map = binary.op, .left = binary.left, .right = binary.right };
                break :blk null;
            },
        };
    }

    fn compactDenseElementwiseProducerInfo(program: *const CompactDenseProducerProgram) ?DenseElementwiseKind {
        const binary = compactDenseProducerBinarySources(program, program.root) orelse return null;
        const swap = compactDensePlainArgs01Swap(binary.left, binary.right) orelse return null;
        _ = classifyDenseBuiltin(binary.op) orelse return null;
        return .{ .dyad = .{ .op = binary.op, .swap = swap } };
    }

    fn compactDenseAddFoldProducerInfo(bytes: []const u8, constants: []const Value) ?DenseAddFoldMapInfo {
        const program = compactDenseReadProducerProgram(bytes, constants) orelse return null;
        return compactDenseProducerInfoFromProgram(&program);
    }

    fn classifyCompactDenseAddFoldMapCode(code: *const Code) ?DenseAddFoldMapInfo {
        if (code.arity == 0 or code.arity > 2) return null;
        const bytes = code.bytes;
        if (bytes.len < 7 or bytes[bytes.len - 1] != ck_return) return null;
        var base_start: usize = 0;
        while (base_start < bytes.len - 1) {
            if (compactBuiltinValueLen(bytes[base_start..], code.constants, .add)) |base_len| {
                const call_start = base_start + base_len;
                if (call_start + 4 == bytes.len and bytes[call_start] == ck_call_adverb_stack_u8 and
                    bytes[call_start + 1] == @backingInt(DerivedVerbKind.fold) and bytes[call_start + 2] == 1)
                    return compactDenseAddFoldProducerInfo(bytes[0..base_start], code.constants);
            }
            if (compactAddFoldCallableLen(bytes[base_start..], code.constants)) |callable_len| {
                var call_idx = base_start + callable_len;
                if ((compactReadCallStackArgc(bytes, &call_idx) orelse 0) == 1 and call_idx == bytes.len - 1)
                    return compactDenseAddFoldProducerInfo(bytes[0..base_start], code.constants);
            }
            base_start += compactInstructionLen(bytes, base_start) orelse return null;
        }
        return null;
    }

    const NumericUnaryEachPlan = union(enum) {
        identity,
        int_scalar_dyad: struct {
            op: BuiltinId,
            scalar: i64,
            scalar_left: bool,
        },
    };

    fn numericUnaryEachDyadSupported(op: BuiltinId) bool {
        return switch (op) {
            .add, .sub, .mul, .div, .pow, .minimum, .maximum, .less, .more, .equal => true,
            else => false,
        };
    }

    fn compactLocalConstUnaryEachPlan(raw: u8, slot: u8, scalar: i64) ?NumericUnaryEachPlan {
        if (slot != 0) return null;
        const op: BuiltinId = switch (raw) {
            ck_add_local_const_i64 => .add,
            ck_sub_local_const_i64 => .sub,
            ck_mul_local_const_i64 => .mul,
            ck_minimum_local_const_i64 => .minimum,
            ck_maximum_local_const_i64 => .maximum,
            ck_less_local_const_i64 => .less,
            ck_more_local_const_i64 => .more,
            ck_equal_local_const_i64 => .equal,
            else => return null,
        };
        if (!numericUnaryEachDyadSupported(op)) return null;
        return .{ .int_scalar_dyad = .{ .op = op, .scalar = scalar, .scalar_left = false } };
    }

    fn compactConstLocalUnaryEachPlan(raw: u8, scalar: i64, slot: u8) ?NumericUnaryEachPlan {
        if (slot != 0) return null;
        const op: BuiltinId = switch (raw) {
            ck_add_const_local_i64 => .add,
            ck_sub_const_local_i64 => .sub,
            ck_minimum_const_local_i64 => .minimum,
            ck_maximum_const_local_i64 => .maximum,
            ck_less_const_local_i64 => .less,
            ck_more_const_local_i64 => .more,
            ck_equal_const_local_i64 => .equal,
            else => return null,
        };
        if (!numericUnaryEachDyadSupported(op)) return null;
        return .{ .int_scalar_dyad = .{ .op = op, .scalar = scalar, .scalar_left = true } };
    }

    fn classifyCompactNumericUnaryEachClosure(closure: *const Closure) ?NumericUnaryEachPlan {
        if (closure.captures.len != 0 or closure.code.arity != 1) return null;
        const bytes = closure.code.bytes;
        if (bytes.len == 2 and bytes[1] == ck_return) {
            if (compactLocalReadSlot(bytes[0])) |slot| {
                if (slot == 0) return .identity;
            }
            return null;
        }
        if (bytes.len != 11 or bytes[10] != ck_return) return null;
        const raw = bytes[0];
        switch (raw) {
            ck_add_local_const_i64,
            ck_sub_local_const_i64,
            ck_mul_local_const_i64,
            ck_minimum_local_const_i64,
            ck_maximum_local_const_i64,
            ck_less_local_const_i64,
            ck_more_local_const_i64,
            ck_equal_local_const_i64,
            => {
                const scalar = directReadI64(bytes, 2) orelse return null;
                return compactLocalConstUnaryEachPlan(raw, bytes[1], scalar);
            },
            ck_add_const_local_i64,
            ck_sub_const_local_i64,
            ck_minimum_const_local_i64,
            ck_maximum_const_local_i64,
            ck_less_const_local_i64,
            ck_more_const_local_i64,
            ck_equal_const_local_i64,
            => {
                const scalar = directReadI64(bytes, 1) orelse return null;
                return compactConstLocalUnaryEachPlan(raw, scalar, bytes[9]);
            },
            else => return null,
        }
    }

    fn classifyProjectionNumericUnaryEachPlan(self: *Session, closure: *const Closure) KError!?NumericUnaryEachPlan {
        const info = (try self.projectionInfoFromClosure(closure)) orelse return null;
        if (info.callee.tag() != .builtin or info.slot_count != 2 or @popCount(info.hole_mask) != 1) return null;
        const op = dyadicBuiltinForGenericCall(info.callee.asBuiltin());
        if (!numericUnaryEachDyadSupported(op)) return null;
        if ((info.hole_mask & 0b01) != 0) {
            const scalar = scalarIntLikeValue(info.slot_values[1]) orelse return null;
            return .{ .int_scalar_dyad = .{ .op = op, .scalar = scalar, .scalar_left = false } };
        }
        if ((info.hole_mask & 0b10) != 0) {
            const scalar = scalarIntLikeValue(info.slot_values[0]) orelse return null;
            return .{ .int_scalar_dyad = .{ .op = op, .scalar = scalar, .scalar_left = true } };
        }
        return null;
    }

    fn classifyNumericUnaryEachPlan(self: *Session, base: Value) KError!?NumericUnaryEachPlan {
        return switch (base.tag()) {
            .builtin => if (base.asBuiltin() == .identity) .identity else null,
            .closure => blk: {
                const closure = base.asClosure();
                if (try self.monadicBuiltinFromClosure(closure)) |op| {
                    if (op == .identity) break :blk .identity;
                }
                if (try self.classifyProjectionNumericUnaryEachPlan(closure)) |plan| break :blk plan;
                break :blk classifyCompactNumericUnaryEachClosure(closure);
            },
            else => null,
        };
    }

    fn applyNumericUnaryEachPlan(self: *Session, plan: NumericUnaryEachPlan, input: Value) KError!Value {
        return switch (plan) {
            .identity => self.shareValue(input),
            .int_scalar_dyad => |dyad| blk: {
                const scalar = try self.intValue(dyad.scalar);
                defer self.releaseValue(scalar);
                const left = if (dyad.scalar_left) scalar else input;
                const right = if (dyad.scalar_left) input else scalar;
                break :blk try self.applyDyad(dyad.op, left, right);
            },
        };
    }

    fn tryFastNumericUnaryEachDerived(self: *Session, base: Value, args: []const Value) KError!?Value {
        if (args.len != 1) return null;
        const input = args[0];
        if (numericVectorLen(input) == null or valueNumericMode(input) == null) return null;
        const plan = (try self.classifyNumericUnaryEachPlan(base)) orelse return null;
        if (comptime enable_probe_instrumentation) self.debug.apply_each_fast_numeric_unary_count += 1;
        return try self.applyNumericUnaryEachPlan(plan, input);
    }

    const NumericVectorCodeResultClass = enum {
        int,
        bool,
    };

    const NumericVectorCodeInstr = union(enum) {
        input,
        scalar: i64,
        monad_not,
        dyad: BuiltinId,
    };

    const max_numeric_vector_code_instrs = 32;

    const NumericVectorCodeProgram = struct {
        instrs: [max_numeric_vector_code_instrs]NumericVectorCodeInstr = undefined,
        len: usize = 0,
        result_class: NumericVectorCodeResultClass = .int,

        fn append(self: *NumericVectorCodeProgram, instr: NumericVectorCodeInstr) bool {
            if (self.len >= self.instrs.len) return false;
            self.instrs[self.len] = instr;
            self.len += 1;
            return true;
        }
    };

    fn numericVectorCodeDyadFromFixedLocalLocal(raw: u8) ?BuiltinId {
        return switch (raw) {
            ck_add_local_local => .add,
            ck_sub_local_local => .sub,
            ck_mul_local_local => .mul,
            ck_minimum_local_local => .minimum,
            ck_maximum_local_local => .maximum,
            ck_less_local_local => .less,
            ck_more_local_local => .more,
            ck_equal_local_local => .equal,
            else => null,
        };
    }

    fn numericVectorCodeDyadFromFixedLocalConst(raw: u8) ?BuiltinId {
        return switch (raw) {
            ck_add_local_const_i64 => .add,
            ck_sub_local_const_i64 => .sub,
            ck_mul_local_const_i64 => .mul,
            ck_minimum_local_const_i64 => .minimum,
            ck_maximum_local_const_i64 => .maximum,
            ck_less_local_const_i64 => .less,
            ck_more_local_const_i64 => .more,
            ck_equal_local_const_i64 => .equal,
            else => null,
        };
    }

    fn numericVectorCodeDyadFromFixedConstLocal(raw: u8) ?BuiltinId {
        return switch (raw) {
            ck_add_const_local_i64 => .add,
            ck_sub_const_local_i64 => .sub,
            ck_minimum_const_local_i64 => .minimum,
            ck_maximum_const_local_i64 => .maximum,
            ck_less_const_local_i64 => .less,
            ck_more_const_local_i64 => .more,
            ck_equal_const_local_i64 => .equal,
            else => null,
        };
    }

    fn numericVectorCodeDyadFromRange(raw: u8) ?BuiltinId {
        if (!compactIsDyadOpcode(raw)) return null;
        return switch (raw - ck_dyad_base) {
            ckd_add => .add,
            ckd_sub => .sub,
            ckd_mul => .mul,
            ckd_minimum => .minimum,
            ckd_maximum => .maximum,
            ckd_less => .less,
            ckd_more => .more,
            ckd_equal => .equal,
            else => null,
        };
    }

    fn numericVectorCodeDyadResultClass(op: BuiltinId, left: NumericVectorCodeResultClass, right: NumericVectorCodeResultClass) ?NumericVectorCodeResultClass {
        return switch (op) {
            .add, .sub, .mul => .int,
            .minimum, .maximum => if (left == .bool and right == .bool) .bool else .int,
            .less, .more, .equal => .bool,
            else => null,
        };
    }

    fn numericVectorCodeAppendInput(program: *NumericVectorCodeProgram, classes: *[max_code_frame_slots]NumericVectorCodeResultClass, depth: *usize) ?void {
        if (depth.* >= classes.len) return null;
        if (!program.append(.input)) return null;
        classes[depth.*] = .int;
        depth.* += 1;
    }

    fn numericVectorCodeAppendScalar(program: *NumericVectorCodeProgram, classes: *[max_code_frame_slots]NumericVectorCodeResultClass, depth: *usize, scalar: i64) ?void {
        if (depth.* >= classes.len) return null;
        if (!program.append(.{ .scalar = scalar })) return null;
        classes[depth.*] = .int;
        depth.* += 1;
    }

    fn numericVectorCodeAppendMonadNot(program: *NumericVectorCodeProgram, classes: *[max_code_frame_slots]NumericVectorCodeResultClass, depth: *usize) ?void {
        if (depth.* < 1) return null;
        if (!program.append(.monad_not)) return null;
        classes[depth.* - 1] = .bool;
    }

    fn numericVectorCodeAppendDyad(program: *NumericVectorCodeProgram, classes: *[max_code_frame_slots]NumericVectorCodeResultClass, depth: *usize, op: BuiltinId) ?void {
        if (depth.* < 2) return null;
        const left = classes[depth.* - 1];
        const right = classes[depth.* - 2];
        const result_class = numericVectorCodeDyadResultClass(op, left, right) orelse return null;
        if (!program.append(.{ .dyad = op })) return null;
        depth.* -= 1;
        classes[depth.* - 1] = result_class;
    }

    fn classifyNumericVectorCodeProgram(code: *const Code) ?NumericVectorCodeProgram {
        if (code.arity != 1 or code.references_globals or code.bytes.len < 2) return null;
        var program = NumericVectorCodeProgram{};
        var classes: [max_code_frame_slots]NumericVectorCodeResultClass = undefined;
        var depth: usize = 0;
        var idx: usize = 0;
        const bytes = code.bytes;

        while (idx < bytes.len) {
            const raw = bytes[idx];
            idx += 1;

            if (raw == ck_return) {
                if (idx != bytes.len or depth != 1) return null;
                program.result_class = classes[0];
                return program;
            }

            if (compactLocalReadSlot(raw)) |slot| {
                if (slot != 0) return null;
                numericVectorCodeAppendInput(&program, &classes, &depth) orelse return null;
                continue;
            }

            if (raw == ck_const_i8) {
                if (idx >= bytes.len) return null;
                const scalar: i64 = @as(i8, @bitCast(bytes[idx]));
                idx += 1;
                numericVectorCodeAppendScalar(&program, &classes, &depth, scalar) orelse return null;
                continue;
            }

            if (raw == ck_const_i64) {
                const scalar = directReadI64(bytes, idx) orelse return null;
                idx += 8;
                numericVectorCodeAppendScalar(&program, &classes, &depth, scalar) orelse return null;
                continue;
            }

            if (raw == ck_const_false or raw == ck_const_true) {
                numericVectorCodeAppendScalar(&program, &classes, &depth, if (raw == ck_const_true) 1 else 0) orelse return null;
                continue;
            }

            if (raw == ck_monad_base + ckm_not) {
                numericVectorCodeAppendMonadNot(&program, &classes, &depth) orelse return null;
                continue;
            }

            if (numericVectorCodeDyadFromRange(raw)) |op| {
                numericVectorCodeAppendDyad(&program, &classes, &depth, op) orelse return null;
                continue;
            }

            if (numericVectorCodeDyadFromFixedLocalLocal(raw)) |op| {
                if (idx + 2 > bytes.len) return null;
                const left_slot = bytes[idx];
                const right_slot = bytes[idx + 1];
                idx += 2;
                if (left_slot != 0 or right_slot != 0) return null;
                numericVectorCodeAppendInput(&program, &classes, &depth) orelse return null;
                numericVectorCodeAppendInput(&program, &classes, &depth) orelse return null;
                numericVectorCodeAppendDyad(&program, &classes, &depth, op) orelse return null;
                continue;
            }

            if (numericVectorCodeDyadFromFixedLocalConst(raw)) |op| {
                if (idx + 9 > bytes.len) return null;
                const slot = bytes[idx];
                const scalar = directReadI64(bytes, idx + 1) orelse return null;
                idx += 9;
                if (slot != 0) return null;
                numericVectorCodeAppendScalar(&program, &classes, &depth, scalar) orelse return null;
                numericVectorCodeAppendInput(&program, &classes, &depth) orelse return null;
                numericVectorCodeAppendDyad(&program, &classes, &depth, op) orelse return null;
                continue;
            }

            if (numericVectorCodeDyadFromFixedConstLocal(raw)) |op| {
                if (idx + 9 > bytes.len) return null;
                const scalar = directReadI64(bytes, idx) orelse return null;
                const slot = bytes[idx + 8];
                idx += 9;
                if (slot != 0) return null;
                numericVectorCodeAppendInput(&program, &classes, &depth) orelse return null;
                numericVectorCodeAppendScalar(&program, &classes, &depth, scalar) orelse return null;
                numericVectorCodeAppendDyad(&program, &classes, &depth, op) orelse return null;
                continue;
            }

            return null;
        }
        return null;
    }

    fn evalNumericVectorCodeDyad(op: BuiltinId, left: i64, right: i64) KError!i64 {
        return switch (op) {
            .add => blk: {
                const result = @addWithOverflow(left, right);
                if (result[1] != 0) return error.Unsupported;
                break :blk result[0];
            },
            .sub => blk: {
                const result = @subWithOverflow(left, right);
                if (result[1] != 0) return error.Unsupported;
                break :blk result[0];
            },
            .mul => blk: {
                const result = @mulWithOverflow(left, right);
                if (result[1] != 0) return error.Unsupported;
                break :blk result[0];
            },
            .minimum => @min(left, right),
            .maximum => @max(left, right),
            .less => @intFromBool(left < right),
            .more => @intFromBool(left > right),
            .equal => @intFromBool(left == right),
            else => return error.Internal,
        };
    }

    fn evalNumericVectorCodeProgramItem(program: *const NumericVectorCodeProgram, input: i64) KError!i64 {
        var stack: [max_code_frame_slots]i64 = undefined;
        var depth: usize = 0;
        for (program.instrs[0..program.len]) |instr| {
            switch (instr) {
                .input => {
                    if (depth >= stack.len) return error.Internal;
                    stack[depth] = input;
                    depth += 1;
                },
                .scalar => |scalar| {
                    if (depth >= stack.len) return error.Internal;
                    stack[depth] = scalar;
                    depth += 1;
                },
                .monad_not => {
                    if (depth < 1) return error.Internal;
                    stack[depth - 1] = @intFromBool(stack[depth - 1] == 0);
                },
                .dyad => |op| {
                    if (depth < 2) return error.Internal;
                    const left = stack[depth - 1];
                    const right = stack[depth - 2];
                    depth -= 1;
                    stack[depth - 1] = try evalNumericVectorCodeDyad(op, left, right);
                },
            }
        }
        if (depth != 1) return error.Internal;
        return stack[0];
    }

    fn applyNumericVectorCodeEach(self: *Session, program: *const NumericVectorCodeProgram, input_view: HostIntDenseView, out_len: usize) KError!Value {
        return switch (program.result_class) {
            .int => blk: {
                const out = try self.allocator.alloc(i64, out_len);
                defer self.allocator.free(out);
                for (0..out_len) |idx| {
                    const input = try hostIntDenseViewItem(input_view, idx);
                    out[idx] = try evalNumericVectorCodeProgramItem(program, input);
                }
                break :blk try self.createManagedHostIntArray(out);
            },
            .bool => blk: {
                const out = try self.allocator.alloc(bool, out_len);
                defer self.allocator.free(out);
                for (0..out_len) |idx| {
                    const input = try hostIntDenseViewItem(input_view, idx);
                    out[idx] = (try evalNumericVectorCodeProgramItem(program, input)) != 0;
                }
                break :blk try self.createManagedHostBitArray(out);
            },
        };
    }

    fn applyFastNumericClosureEach(self: *Session, code: *const Code, input_view: HostIntDenseView, out_len: usize) KError!Value {
        const int_items = try self.allocator.alloc(i64, out_len);
        defer self.allocator.free(int_items);

        var fallback_values: ?[]Value = null;
        var fallback_initialized: usize = 0;
        defer if (fallback_values) |values| {
            for (values[0..fallback_initialized]) |value| self.releaseValue(value);
            self.allocator.free(values);
        };

        for (0..out_len) |idx| {
            const item = try self.intValue(try hostIntDenseViewItem(input_view, idx));
            const step_args = [_]Value{item};
            const result = try self.runCodeOwned(code, &step_args);
            if (fallback_values) |values| {
                values[idx] = result;
                fallback_initialized += 1;
                continue;
            }
            if (result.tag() == .int) {
                int_items[idx] = result.asInt();
                self.releaseValue(result);
                continue;
            }

            const values = try self.allocator.alloc(Value, out_len);
            var initialized: usize = 0;
            errdefer {
                for (values[0..initialized]) |value| self.releaseValue(value);
                self.allocator.free(values);
                self.releaseValue(result);
            }
            for (int_items[0..idx], 0..) |int_item, existing_idx| {
                values[existing_idx] = try self.intValue(int_item);
                initialized += 1;
            }
            values[idx] = result;
            initialized += 1;
            fallback_values = values;
            fallback_initialized = initialized;
        }

        if (fallback_values) |values| return try self.createManagedArrayLikeFromValues(values);
        return try self.createManagedHostIntArray(int_items);
    }

    fn tryFastNumericClosureEachDerived(self: *Session, base: Value, args: []const Value) KError!?Value {
        if (args.len != 1 or base.tag() != .closure) return null;
        const input = args[0];
        const out_len = numericVectorLen(input) orelse return null;
        if ((valueNumericMode(input) orelse return null) != .int) return null;

        const code = codeForPlainClosure(base.asClosure(), 1) orelse return null;
        if (code.slot_count > max_code_frame_slots) return null;

        const dense = hostDenseView(self, input) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        const input_view = switch (dense) {
            .int_array => |view| view,
            else => return null,
        };

        if (classifyNumericVectorCodeProgram(code)) |program| {
            if (comptime enable_probe_instrumentation) self.debug.apply_each_fast_numeric_vector_code_count += 1;
            return try self.applyNumericVectorCodeEach(&program, input_view, out_len);
        }

        if (comptime enable_probe_instrumentation) self.debug.apply_each_fast_numeric_closure_count += 1;
        return try self.applyFastNumericClosureEach(code, input_view, out_len);
    }

    const CompactUnarySelfTransform = enum {
        grade_up,
        grade_down,
    };

    const CompactUnaryLiftedKind = struct {
        base: Value,
        transform: CompactUnarySelfTransform,
    };

    fn classifyDenseBuiltin(op: BuiltinId) ?DenseElementwiseKind {
        return switch (op) {
            .add, .sub, .mul, .div, .pow, .minimum, .maximum, .less, .more => .{ .dyad = .{ .op = op, .swap = false } },
            else => null,
        };
    }

    fn applyDenseElementwiseKind(self: *Session, kind: DenseElementwiseKind, arg0: Value, arg1: Value) KError!Value {
        return switch (kind) {
            .dyad => |dyad| blk: {
                const left = if (dyad.swap) arg1 else arg0;
                const right = if (dyad.swap) arg0 else arg1;
                break :blk switch (dyad.op) {
                    .add => try self.addValues(left, right),
                    .sub => try self.subValues(left, right),
                    .mul => try self.mulValues(left, right),
                    .div => try self.divValues(left, right),
                    .pow => try self.powValues(left, right),
                    .minimum => blk2: {
                        const mask = try self.lessValues(left, right);
                        defer self.releaseValue(mask);
                        const delta = try self.subValues(left, right);
                        defer self.releaseValue(delta);
                        const kept = try self.mulValues(mask, delta);
                        defer self.releaseValue(kept);
                        break :blk2 try self.addValues(right, kept);
                    },
                    .maximum => blk2: {
                        const mask = try self.moreValues(left, right);
                        defer self.releaseValue(mask);
                        const delta = try self.subValues(left, right);
                        defer self.releaseValue(delta);
                        const kept = try self.mulValues(mask, delta);
                        defer self.releaseValue(kept);
                        break :blk2 try self.addValues(right, kept);
                    },
                    .less => try self.lessValues(left, right),
                    .more => try self.moreValues(left, right),
                    else => return error.Internal,
                };
            },
            .keep_left_if_more => blk: {
                const mask = try self.moreValues(arg0, arg1);
                defer self.releaseValue(mask);
                break :blk try self.mulValues(arg0, mask);
            },
        };
    }

    fn compactLocalReadSlot(raw: u8) ?u8 {
        if (raw >= ck_load_local_base and raw < ck_load_local_base + ck_range_width) return raw - ck_load_local_base;
        if (raw >= ck_take_local_base and raw < ck_take_local_base + ck_range_width) return raw - ck_take_local_base;
        return null;
    }

    fn compactReadConditionalAtom(bytes: []const u8, idx: *usize) ?DirectConditionalAtom {
        if (idx.* >= bytes.len) return null;
        const raw = bytes[idx.*];
        if (compactLocalReadSlot(raw)) |slot| {
            idx.* += 1;
            return directConditionalAtomFromSlot(slot);
        }
        if (raw == ck_const_false) {
            idx.* += 1;
            return .zero;
        }
        if (raw == ck_const_i8 and idx.* + 1 < bytes.len and bytes[idx.* + 1] == 0) {
            idx.* += 2;
            return .zero;
        }
        return null;
    }

    fn compactReadConditionalCompare(bytes: []const u8, idx: *usize) ?DirectConditionalCompare {
        if (idx.* >= bytes.len) return null;
        const raw = bytes[idx.*];
        switch (raw) {
            ck_more_local_local, ck_less_local_local => {
                if (idx.* + 3 > bytes.len) return null;
                const lhs = directConditionalAtomFromSlot(bytes[idx.* + 1]) orelse return null;
                const rhs = directConditionalAtomFromSlot(bytes[idx.* + 2]) orelse return null;
                idx.* += 3;
                return .{
                    .lhs = lhs,
                    .rhs = rhs,
                    .cmp = if (raw == ck_more_local_local) BuiltinId.more else BuiltinId.less,
                };
            },
            else => {
                const rhs = compactReadConditionalAtom(bytes, idx) orelse return null;
                const lhs = compactReadConditionalAtom(bytes, idx) orelse return null;
                if (idx.* >= bytes.len or !compactIsDyadOpcode(bytes[idx.*])) return null;
                const cmp = switch (bytes[idx.*] - ck_dyad_base) {
                    ckd_more => BuiltinId.more,
                    ckd_less => BuiltinId.less,
                    else => return null,
                };
                idx.* += 1;
                return .{ .lhs = lhs, .rhs = rhs, .cmp = cmp };
            },
        }
    }

    fn compactReadDirectJumpTarget(bytes: []const u8, idx: *usize, op: u8) ?usize {
        if (idx.* >= bytes.len) return null;
        if (bytes[idx.*] == ck_ext_u16) {
            if (idx.* + 4 > bytes.len or bytes[idx.* + 1] != op) return null;
            const target = directReadU16(bytes, idx.* + 2) orelse return null;
            idx.* += 4;
            return target;
        }
        if (idx.* + 2 > bytes.len or bytes[idx.*] != op) return null;
        const target = bytes[idx.* + 1];
        idx.* += 2;
        return target;
    }

    fn compactReadConditionalCompareBranch(bytes: []const u8, idx: *usize) ?DirectConditionalBranch {
        if (idx.* >= bytes.len) return null;
        if (bytes[idx.*] == ck_ext_u16) {
            if (idx.* + 7 > bytes.len or bytes[idx.* + 1] != ck_jump_if_false_compare_local_local_i64) return null;
            const lhs = directConditionalAtomFromSlot(bytes[idx.* + 3]) orelse return null;
            const rhs = directConditionalAtomFromSlot(bytes[idx.* + 4]) orelse return null;
            const target = directReadU16(bytes, idx.* + 5) orelse return null;
            const cmp: BuiltinId = @fromBackingInt(@intCast(bytes[idx.* + 2]));
            switch (cmp) {
                .less, .more, .equal => {},
                else => return null,
            }
            idx.* += 7;
            return .{
                .compare = .{ .lhs = lhs, .rhs = rhs, .cmp = cmp },
                .false_target = target,
            };
        }
        if (bytes[idx.*] == ck_jump_if_false_compare_local_local_i64) {
            if (idx.* + 5 > bytes.len) return null;
            const lhs = directConditionalAtomFromSlot(bytes[idx.* + 2]) orelse return null;
            const rhs = directConditionalAtomFromSlot(bytes[idx.* + 3]) orelse return null;
            const cmp: BuiltinId = @fromBackingInt(@intCast(bytes[idx.* + 1]));
            switch (cmp) {
                .less, .more, .equal => {},
                else => return null,
            }
            const target = bytes[idx.* + 4];
            idx.* += 5;
            return .{
                .compare = .{ .lhs = lhs, .rhs = rhs, .cmp = cmp },
                .false_target = target,
            };
        }

        const compare = compactReadConditionalCompare(bytes, idx) orelse return null;
        const false_target = compactReadDirectJumpTarget(bytes, idx, ck_jump_if_false_u8) orelse return null;
        return .{ .compare = compare, .false_target = false_target };
    }

    fn classifyCompactDenseConditionalClosure2(bytes: []const u8) ?DenseElementwiseKind {
        if (bytes.len < 2 or bytes[bytes.len - 1] != ck_return) return null;

        var idx: usize = 0;
        const branch = compactReadConditionalCompareBranch(bytes, &idx) orelse return null;
        const compare = branch.compare;
        if (compare.lhs != .arg0 or compare.rhs != .arg1) return null;

        const when_true = compactReadConditionalAtom(bytes, &idx) orelse return null;
        const end_target = compactReadDirectJumpTarget(bytes, &idx, ck_jump_u8) orelse return null;
        if (branch.false_target != idx) return null;

        const when_false = compactReadConditionalAtom(bytes, &idx) orelse return null;
        if (end_target != idx or idx >= bytes.len or bytes[idx] != ck_return or idx + 1 != bytes.len) return null;

        return switch (when_true) {
            .arg0 => switch (when_false) {
                .arg1 => switch (compare.cmp) {
                    .more => .{ .dyad = .{ .op = .maximum, .swap = false } },
                    .less => .{ .dyad = .{ .op = .minimum, .swap = false } },
                    else => null,
                },
                .zero => if (compare.cmp == .more) .keep_left_if_more else null,
                else => null,
            },
            else => null,
        };
    }

    fn compactDenseFixedDyad(raw: u8) ?BuiltinId {
        return switch (raw) {
            ck_add_local_local => .add,
            ck_sub_local_local => .sub,
            ck_mul_local_local => .mul,
            ck_minimum_local_local => .minimum,
            ck_maximum_local_local => .maximum,
            ck_less_local_local => .less,
            ck_more_local_local => .more,
            else => null,
        };
    }

    fn compactDenseDyadRange(raw: u8) ?BuiltinId {
        if (!compactIsDyadOpcode(raw)) return null;
        return switch (raw - ck_dyad_base) {
            ckd_add => .add,
            ckd_sub => .sub,
            ckd_mul => .mul,
            ckd_div => .div,
            ckd_minimum => .minimum,
            ckd_maximum => .maximum,
            ckd_less => .less,
            ckd_more => .more,
            else => null,
        };
    }

    fn classifyCompactDenseElementwiseClosure(closure: *const Closure) ?DenseElementwiseKind {
        if (closure.header.owner != .frozen or closure.captures.len != 0) return null;
        const compact = closure.code;
        const bytes = compact.bytes;
        if (bytes.len < 2 or bytes[bytes.len - 1] != ck_return) return null;

        if (compactDenseReadProducerProgram(bytes[0 .. bytes.len - 1], compact.constants)) |program| {
            if (compactDenseElementwiseProducerInfo(&program)) |info| return info;
        }

        return classifyCompactDenseConditionalClosure2(bytes);
    }

    fn directConditionalAtomFromSlot(slot: u8) ?DirectConditionalAtom {
        return switch (slot) {
            0 => .arg0,
            1 => .arg1,
            else => null,
        };
    }

    fn compactReadClosureBaseValue(self: *Session, closure: *const Closure, bytes: []const u8, idx: *usize) KError!?Value {
        if (idx.* >= bytes.len) return null;
        const raw = bytes[idx.*];
        if (compactIsConstValueOpcode(raw)) {
            const slot: usize = raw - ck_const_value_base;
            if (slot >= closure.code.constants.len) return null;
            idx.* += 1;
            return closure.code.constants[slot];
        }
        return switch (raw) {
            ck_const_builtin_u8 => blk: {
                if (idx.* + 2 > bytes.len) return null;
                const builtin: BuiltinId = @fromBackingInt(@intCast(bytes[idx.* + 1]));
                idx.* += 2;
                break :blk Value.builtin(builtin);
            },
            ck_const_value_u8 => blk: {
                if (idx.* + 2 > bytes.len) return null;
                const slot = bytes[idx.* + 1];
                if (slot >= closure.code.constants.len) return null;
                idx.* += 2;
                break :blk closure.code.constants[slot];
            },
            ck_load_global_u8 => blk: {
                if (idx.* + 2 > bytes.len) return null;
                const slot = bytes[idx.* + 1];
                idx.* += 2;
                break :blk try self.loadGlobalSlot(slot);
            },
            else => null,
        };
    }

    fn classifyCompactDenseElementwiseWrapperClosure(self: *Session, closure: *const Closure) KError!?DenseElementwiseKind {
        if (closure.header.owner != .frozen or closure.captures.len != 0) return null;
        const bytes = closure.code.bytes;
        if (bytes.len < 6 or bytes[bytes.len - 1] != ck_return) return null;
        if ((compactLocalReadSlot(bytes[0]) orelse 255) != 1 or
            (compactLocalReadSlot(bytes[1]) orelse 255) != 0) return null;
        var idx: usize = 2;
        const base_value = (try self.compactReadClosureBaseValue(closure, bytes, &idx)) orelse return null;
        if (idx + 4 == bytes.len and bytes[idx] == ck_call_adverb_stack_u8 and
            bytes[idx + 1] == @backingInt(DerivedVerbKind.each) and bytes[idx + 2] == 2)
            return try self.classifyDenseElementwiseBaseRuntime(base_value);
        if (idx + 5 != bytes.len or bytes[idx] != ck_make_adverb_u8 or
            bytes[idx + 1] != @backingInt(DerivedVerbKind.each)) return null;
        idx += 2;
        if ((compactReadCallStackArgc(bytes, &idx) orelse return null) != 2) return null;
        return try self.classifyDenseElementwiseBaseRuntime(base_value);
    }

    fn classifyDenseElementwiseClosureRuntime(self: *Session, closure: *const Closure) KError!?DenseElementwiseKind {
        if (classifyCompactDenseElementwiseClosure(closure)) |kind| return kind;
        return try self.classifyCompactDenseElementwiseWrapperClosure(closure);
    }

    fn classifyDenseElementwiseBaseRuntime(self: *Session, base: Value) KError!?DenseElementwiseKind {
        return switch (base.tag()) {
            .builtin => classifyDenseBuiltin(base.asBuiltin()),
            .closure => try self.classifyDenseElementwiseClosureRuntime(base.asClosure()),
            else => null,
        };
    }

    fn compactReadUnarySelfTransform(bytes: []const u8, idx: *usize) ?CompactUnarySelfTransform {
        if (idx.* + 2 > bytes.len) return null;
        if ((compactLocalReadSlot(bytes[idx.*]) orelse return null) != 0) return null;
        const raw = bytes[idx.* + 1];
        if (!compactIsMonadOpcode(raw)) return null;
        idx.* += 2;
        return switch (raw - ck_monad_base) {
            ckm_grade_up => .grade_up,
            ckm_grade_down => .grade_down,
            else => null,
        };
    }

    fn compactReadCallStackArgc(bytes: []const u8, idx: *usize) ?u8 {
        if (idx.* + 2 > bytes.len or bytes[idx.*] != ck_call_stack_u8) return null;
        const flags = bytes[idx.* + 1];
        if (compactCallStoresLocal(flags)) return null;
        idx.* += 2;
        return compactCallArgc(flags);
    }

    fn classifyCompactUnaryLiftedClosure(self: *Session, closure: *const Closure) KError!?CompactUnaryLiftedKind {
        if (closure.header.owner != .frozen or closure.captures.len != 0) return null;
        const bytes = closure.code.bytes;
        if (bytes.len < 8 or bytes[bytes.len - 1] != ck_return) return null;
        var idx: usize = 0;
        const transform = compactReadUnarySelfTransform(bytes, &idx) orelse return null;
        const second = compactReadUnarySelfTransform(bytes, &idx) orelse return null;
        if (transform != second) return null;
        const base_value = (try self.compactReadClosureBaseValue(closure, bytes, &idx)) orelse return null;
        if (idx + 4 == bytes.len and bytes[idx] == ck_call_adverb_stack_u8 and
            bytes[idx + 1] == @backingInt(DerivedVerbKind.each_right) and bytes[idx + 2] == 2)
        {
            _ = try self.classifyDenseElementwiseBaseRuntime(base_value) orelse return null;
            return .{ .base = base_value, .transform = transform };
        }
        if (idx + 5 != bytes.len or bytes[idx] != ck_make_adverb_u8 or
            bytes[idx + 1] != @backingInt(DerivedVerbKind.each_right)) return null;
        idx += 2;
        if ((compactReadCallStackArgc(bytes, &idx) orelse return null) != 2) return null;
        _ = try self.classifyDenseElementwiseBaseRuntime(base_value) orelse return null;
        return .{ .base = base_value, .transform = transform };
    }

    fn applyCompactUnaryLiftedKind(self: *Session, kind: CompactUnaryLiftedKind, arg0: Value) KError!Value {
        const transformed = switch (kind.transform) {
            .grade_up => try self.gradeValue(arg0, true),
            .grade_down => try self.gradeValue(arg0, false),
        };
        defer self.releaseValue(transformed);
        return try self.applyEachRightDerived(kind.base, &[_]Value{ transformed, transformed });
    }

    fn hostStringListItemValue(self: *Session, list: *const HostStringList, idx: usize) KError!Value {
        if (idx >= list.len) return error.Type;
        if (comptime enable_probe_instrumentation) self.debug.host_string_list_item_value_count += 1;
        const item = switch (list.storage) {
            .eager => |items| switch (items[idx]) {
                .owned => |text| blk: {
                    if (comptime enable_probe_instrumentation) self.debug.host_string_list_item_eager_owned_count += 1;
                    break :blk try self.retainEscapedValue(Value.array(text));
                },
                .view => |view| blk: {
                    if (comptime enable_probe_instrumentation) self.debug.host_string_list_item_eager_view_count += 1;
                    const base = list.base orelse return error.Internal;
                    break :blk try self.managedHostStringViewWithReason(base, view, .string_list_eager_view);
                },
            },
            .split_scalar => |lazy| blk: {
                if (comptime enable_probe_instrumentation) self.debug.host_string_list_item_split_scalar_count += 1;
                const base = list.base orelse return error.Internal;
                const src = hostTextBytes(base);
                var piece_idx: usize = 0;
                var start: usize = 0;
                var scanned_bytes: usize = 0;
                var scanned_seps: usize = 0;
                while (std.mem.indexOfScalarPos(u8, src, start, lazy.sep)) |sep_idx| {
                    scanned_bytes += sep_idx - start + 1;
                    scanned_seps += 1;
                    if (piece_idx == idx) {
                        if (comptime enable_probe_instrumentation) {
                            self.debug.host_string_list_item_split_scalar_scan_byte_count += scanned_bytes;
                            self.debug.host_string_list_item_split_scalar_scan_sep_count += scanned_seps;
                        }
                        break :blk try self.managedHostStringViewWithReason(base, .{
                            .start = start,
                            .len = sep_idx - start,
                        }, .string_list_split_scalar);
                    }
                    piece_idx += 1;
                    start = sep_idx + 1;
                }
                if (piece_idx != idx) return error.Type;
                scanned_bytes += src.len - start;
                if (comptime enable_probe_instrumentation) {
                    self.debug.host_string_list_item_split_scalar_scan_byte_count += scanned_bytes;
                    self.debug.host_string_list_item_split_scalar_scan_sep_count += scanned_seps;
                }
                break :blk try self.managedHostStringViewWithReason(base, .{
                    .start = start,
                    .len = src.len - start,
                }, .string_list_split_scalar);
            },
        };
        if (list.display == .split_list) {
            if (stringBytes(item)) |bytes| {
                if (bytes.len == 1) {
                    const vector = try self.managedHostCharVector(bytes);
                    self.releaseValue(item);
                    return vector;
                }
            }
        }
        return item;
    }

    fn hostStringListPrototypeBytes(self: *Session, list: *const HostStringList) KError![]u8 {
        const len = if (list.len == 0) 0 else (try hostStringListItemBytes(list, 0)).len;
        const spaces = try self.allocator.alloc(u8, len);
        @memset(spaces, ' ');
        return spaces;
    }

    fn hostStringListPrototypeValue(self: *Session, list: *const HostStringList) KError!Value {
        const spaces = try self.hostStringListPrototypeBytes(list);
        defer self.allocator.free(spaces);
        return try self.managedHostString(spaces);
    }

    fn emptySequenceForHostStringList(self: *Session, list: *const HostStringList) KError!Value {
        const prototype = try self.hostStringListPrototypeValue(list);
        defer self.releaseValue(prototype);
        return try self.createManagedHostBoxedArrayWithPrototype(&.{}, prototype);
    }

    fn hostStringListIndexScalar(self: *Session, list: *const HostStringList, raw_index: i64) KError!Value {
        if (normalizeIndexOrNull(raw_index, list.len)) |idx| return try self.hostStringListItemValue(list, idx);
        return try self.hostStringListPrototypeValue(list);
    }

    fn hostSymbolListItemValue(self: *Session, list: *const HostStringList, idx: usize) KError!Value {
        return try self.managedHostSymbol(try hostStringListItemBytes(list, idx));
    }

    fn hostTextListItemValue(self: *Session, value: Value, idx: usize) KError!Value {
        if (stringSourceInfo(value)) |source| return try self.stringIndexScalarValue(source, @intCast(idx));
        if (value.tag() != .array) return error.Type;
        return switch (value.arrayKind()) {
            .host_string_list => try self.hostStringListItemValue(value.asHostStringList(), idx),
            .host_symbol_list => try self.hostSymbolListItemValue(value.asHostStringList(), idx),
            else => error.Type,
        };
    }

    fn derivedSequenceLen(value: Value) ?usize {
        if (value.tag() != .array) return null;
        if (value.arrayKind() == .host_keyed_store) return null;
        if (valueNumericHandle(value)) |handle| {
            if (handle.rank == 0) return null;
            return @intCast(handle.shape[0]);
        }
        if (numericVectorLen(value)) |len| return len;
        if (value.arraySubkind() == .host_string_list) return value.asHostStringList().len;
        if (value.arraySubkind() == .host_symbol_list) return value.asHostStringList().len;
        if (value.arraySubkind() == .host_boxed_array) {
            return value.asHostBoxedArray().len();
        }
        return null;
    }

    fn derivedSequenceItemValue(self: *Session, value: Value, idx: usize) KError!Value {
        if (value.tag() != .array) return error.Type;
        if (value.arrayKind() == .host_keyed_store) return error.Type;
        if (valueNumericHandle(value)) |handle| {
            if (handle.rank > 1) {
                return (try numericValueScalarIndexValue(self, value, @intCast(idx))) orelse error.Type;
            }
        }
        if (valueNumericMatrixShape(value) != null) {
            return (try numericValueScalarIndexValue(self, value, @intCast(idx))) orelse error.Type;
        }
        if (numericVectorLen(value) != null) {
            return try self.derivedDenseVectorItemValue(value, idx);
        }
        if (value.arraySubkind() == .host_string_list) {
            return try self.hostStringListItemValue(value.asHostStringList(), idx);
        }
        if (value.arraySubkind() == .host_symbol_list) {
            return try self.hostSymbolListItemValue(value.asHostStringList(), idx);
        }
        if (value.arraySubkind() == .host_boxed_array) {
            return try self.hostBoxedArrayIndexScalar(value.asHostBoxedArray(), @intCast(idx));
        }
        return error.Type;
    }

    fn derivedDenseVectorItemValue(self: *Session, value: Value, idx: usize) KError!Value {
        const view = try hostDenseView(self, value);
        return switch (valueNumericMode(value) orelse return error.Type) {
            .int => switch (view) {
                .scalar_int => |item| blk: {
                    if (idx != 0) return error.Internal;
                    break :blk try self.intValue(item);
                },
                .int_array => |items| try self.intValue(try hostIntDenseViewItem(items, idx)),
                else => error.Type,
            },
            .float => switch (view) {
                .scalar_float => |item| blk: {
                    if (idx != 0) return error.Internal;
                    break :blk switch (valueFloatStorageKind(value) orelse .float64) {
                        .float32 => try self.float32Value(@floatCast(item)),
                        .float64 => try self.floatValue(item),
                    };
                },
                .float_array => |items| blk: {
                    const item = try hostFloatDenseViewItem(items, idx);
                    break :blk switch (valueFloatStorageKind(value) orelse .float64) {
                        .float32 => try self.float32Value(@floatCast(item)),
                        .float64 => try self.floatValue(item),
                    };
                },
                else => error.Type,
            },
        };
    }

    fn releaseDerivedStepArgs(self: *Session, source_args: []const Value, step_args: []const Value, start_idx: usize) void {
        for (source_args[start_idx..], start_idx..) |arg, arg_idx| {
            if (derivedSequenceLen(arg) != null) self.releaseValue(step_args[arg_idx]);
        }
    }

    fn eachSequenceLen(value: Value) ?usize {
        if (stringSourceInfo(value)) |source| return source.bytes().len;
        return derivedSequenceLen(value);
    }

    fn eachSequenceItemValue(self: *Session, value: Value, idx: usize) KError!Value {
        if (stringSourceInfo(value)) |source| return try self.stringIndexScalarValue(source, @intCast(idx));
        return try self.derivedSequenceItemValue(value, idx);
    }

    fn releaseEachStepArgs(self: *Session, source_args: []const Value, step_args: []const Value, start_idx: usize) void {
        for (source_args[start_idx..], start_idx..) |arg, arg_idx| {
            if (eachSequenceLen(arg) != null) self.releaseValue(step_args[arg_idx]);
        }
    }

    fn createManagedArrayLikeFromValues(self: *Session, values: []const Value) KError!Value {
        return try self.makeArrayFromValues(values);
    }

    fn nextSamplingProfileCodeId(self: *Session) u16 {
        if (comptime !enable_sampling_profile) {
            return sampling_profile_no_code;
        }
        if (self.next_profile_code_id >= sampling_profile_max_code_count) return sampling_profile_no_code;
        const id = self.next_profile_code_id;
        self.next_profile_code_id += 1;
        return id;
    }

    fn rememberSamplingProfileCodeInfo(self: *Session, id: u16, kind: SamplingProfileCodeKind, source: []const u8) void {
        if (comptime !enable_sampling_profile) {
            return;
        }
        if (id == sampling_profile_no_code) return;
        if (staticSamplingProfileCodeInfo(id) != null) return;
        if (id >= self.profile_dynamic_code_used.len) return;
        self.profile_dynamic_code_infos[id] = .{
            .id = id,
            .kind = kind,
            .source = source,
        };
        self.profile_dynamic_code_used[id] = true;
    }

    fn invokeClosureInCurrentRun(self: *Session, callee: Value, closure: *const Closure, args: []const Value) KError!Value {
        _ = self;
        _ = callee;
        if (closure.code.arity != args.len) return error.Arity;
        return error.Unsupported;
    }

    fn applyDerivedBase(self: *Session, callee: Value, args: []const Value) KError!Value {
        if (try self.tryApplyAllAxisCallableProjection(callee, args)) |projection| return projection;
        return switch (callee.tag()) {
            .builtin => try self.applyBuiltinCall(callee.asBuiltin(), args),
            .array => try self.applyArrayCall(callee, args),
            .closure => blk: {
                const closure = callee.asClosure();
                if (try self.tryProjectDerivedClosureUnderApplication(callee, closure, args)) |projection| break :blk projection;
                if (try self.applyDerivedClosure(closure, args)) |result| break :blk result;
                if (try self.tryProjectPlainClosureUnderApplication(callee, closure, args)) |projection| break :blk projection;
                if (codeForRunnablePlainClosureArgs(closure, args)) |compact| break :blk try self.runCodeBorrowed(compact, codeRunArgs(compact, args));
                if (try self.tryApplyOwnedClosureArgs(closure, args)) |result| break :blk result;
                break :blk try self.invokeClosureInCurrentRun(callee, closure, args);
            },
            else => error.Type,
        };
    }

    fn projectionInfoFromClosure(self: *Session, closure: *const Closure) KError!?ProjectionInfo {
        _ = self;
        if (!closureIsProjection(closure)) return null;
        if (closure.captures.len < 3) return error.Internal;
        const slot_count_i64 = scalarIntLikeValue(closure.captures[1]) orelse return error.Internal;
        const hole_mask_i64 = scalarIntLikeValue(closure.captures[2]) orelse return error.Internal;
        if (slot_count_i64 < 0) return error.Internal;
        const slot_count = std.math.cast(usize, slot_count_i64) orelse return error.Internal;
        if (slot_count > 63) return error.Unsupported;
        const hole_mask = std.math.cast(u64, hole_mask_i64) orelse return error.Internal;
        if ((hole_mask >> @intCast(slot_count)) != 0) return error.Internal;
        if (closure.captures.len != 3 + slot_count) return error.Internal;
        return .{
            .callee = closure.captures[0],
            .slot_count = slot_count,
            .hole_mask = hole_mask,
            .slot_values = closure.captures[3..],
        };
    }

    fn monadicBuiltinFromClosure(self: *Session, closure: *const Closure) KError!?BuiltinId {
        _ = self;
        if (!closureIsMonadicBuiltin(closure)) return null;
        if (closure.captures.len != 1 or closure.captures[0].tag() != .builtin) return error.Internal;
        return closure.captures[0].asBuiltin();
    }

    fn innerProductInfoFromClosure(self: *Session, closure: *const Closure) KError!?InnerProductInfo {
        _ = self;
        if (!closureIsInnerProduct(closure)) return null;
        if (closure.captures.len != 2) return error.Internal;
        if (closure.captures[0].tag() != .builtin or closure.captures[1].tag() != .builtin) return error.Internal;
        return .{
            .reduce = closure.captures[0].asBuiltin(),
            .map = closure.captures[1].asBuiltin(),
        };
    }

    fn compositionInfoFromClosure(self: *Session, closure: *const Closure) KError!?CompositionInfo {
        _ = self;
        if (closure.kind != .composition) return null;
        if (closure.captures.len != 2) return error.Internal;
        return .{
            .outer = closure.captures[0],
            .inner = closure.captures[1],
        };
    }

    fn tryApplyStructuredDerivedClosure2(self: *Session, closure: *const Closure, arg0: Value, arg1: Value) KError!?Value {
        if (try self.innerProductInfoFromClosure(closure)) |info| {
            if (info.reduce != .add) return null;
            if (info.map == .mul) {
                if (numericVectorLen(arg0) == null or numericVectorLen(arg1) == null) return null;
            } else if (try self.tryFastDenseFloatInnerAddMap(info, &.{ arg0, arg1 })) |value| {
                if (self.debugDetailedProbeActive()) self.debug.structured_derived2_hit_count += 1;
                return value;
            } else {
                return null;
            }
            if (self.debugDetailedProbeActive()) self.debug.structured_derived2_hit_count += 1;
            return try self.applyMatmulValues(arg0, arg1);
        }

        const kind = closureDerivedKind(closure) orelse return null;
        if (kind != .each_left or closure.captures.len != 1) return null;
        const base = closure.captures[0];
        if (base.tag() != .closure) return null;
        const base_info = (try self.innerProductInfoFromClosure(base.asClosure())) orelse return null;
        if (base_info.reduce != .add or base_info.map != .mul) return null;
        if (!valueIsRenderableMatrixLike(arg0)) return null;
        if (self.debugDetailedProbeActive()) self.debug.structured_derived2_hit_count += 1;
        return try self.applyMatmulValues(arg0, arg1);
    }

    fn materializeSequenceItems(self: *Session, value: Value) KError![]Value {
        var items = std.ArrayList(Value).empty;
        errdefer {
            for (items.items) |item| self.releaseValue(item);
            items.deinit(self.allocator);
        }

        if (derivedSequenceLen(value)) |len| {
            try items.ensureTotalCapacity(self.allocator, len);
            for (0..len) |idx| try items.append(self.allocator, try self.derivedSequenceItemValue(value, idx));
        } else {
            try items.append(self.allocator, try self.retainEscapedValue(value));
        }

        return try items.toOwnedSlice(self.allocator);
    }

    fn deepSelectorMapsRemaining(selector: Value) bool {
        return derivedSequenceLen(selector) != null;
    }

    fn applyDeepIndexStep(self: *Session, base: Value, selector: Value) KError!Value {
        return switch (base.tag()) {
            .array => try self.applyArrayCall1(base, selector),
            .builtin, .closure => try self.applyValue(base, &[_]Value{selector}),
            else => error.Type,
        };
    }

    fn deepIndexValue(self: *Session, base: Value, selectors: []const Value) KError!Value {
        if (selectors.len == 0) return self.shareValue(base);
        if (isAllAxisSelectorValue(selectors[0])) {
            if (selectors.len == 1) return self.shareValue(base);
            return try self.deepIndexAllAxisValue(base, selectors[1..]);
        }
        const selected = try self.applyDeepIndexStep(base, selectors[0]);
        if (selectors.len == 1) return selected;
        defer self.releaseValue(selected);

        if (deepSelectorMapsRemaining(selectors[0])) {
            return try self.deepIndexAllAxisValue(selected, selectors[1..]);
        }
        return try self.deepIndexValue(selected, selectors[1..]);
    }

    fn deepIndexAllAxisValue(self: *Session, base: Value, rest: []const Value) KError!Value {
        const items = try self.materializeTopLevelItems(base);
        defer {
            for (items) |value| self.releaseValue(value);
            self.allocator.free(items);
        }

        for (items, 0..) |item, idx| {
            const selected = try self.deepIndexValue(item, rest);
            self.releaseValue(items[idx]);
            items[idx] = selected;
        }

        const result = try self.makeArrayFromValues(items);
        if (try self.promoteRenderableMatrixValue(result)) |promoted| {
            if (promoted.raw != result.raw and isManagedValue(result)) self.releaseValue(result);
            return promoted;
        }
        return result;
    }

    const AmendKind = enum {
        unary,
        assign,
        binary,
        deep_unary,
        deep_assign,
        deep_binary,
    };

    const IndexedAssignTarget = union(enum) {
        global: u16,
        local: u8,
    };

    const SymbolTargetName = struct {
        bytes: []const u8,
        owned: bool = false,
    };

    fn releaseSymbolTargetName(self: *Session, name: SymbolTargetName) void {
        if (name.owned) self.allocator.free(name.bytes);
    }

    fn symbolTargetName(self: *Session, value: Value) KError!?SymbolTargetName {
        if (symbolBytes(value)) |name| return .{ .bytes = name };
        if (value.tag() != .array or value.arrayKind() != .host_symbol_list) return null;
        const list = value.asHostStringList();
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.allocator);
        for (0..list.len) |idx| {
            if (idx != 0) try out.append(self.allocator, '.');
            try out.appendSlice(self.allocator, try hostStringListItemBytes(list, idx));
        }
        return .{ .bytes = try out.toOwnedSlice(self.allocator), .owned = true };
    }

    fn namespaceChildForParent(parent_path: []const u8, global_name: []const u8) ?[]const u8 {
        if (parent_path.len == 0) {
            if (std.mem.indexOfScalar(u8, global_name, '.') != null) return null;
            return global_name;
        }

        const dot_index = std.mem.lastIndexOfScalar(u8, global_name, '.') orelse return null;
        if (!std.mem.eql(u8, global_name[0..dot_index], parent_path)) return null;
        return global_name[dot_index + 1 ..];
    }

    fn namespaceKeysValue(self: *Session, value: Value) KError!?Value {
        const name = (try self.symbolTargetName(value)) orelse return null;
        defer self.releaseSymbolTargetName(name);

        var children = std.ArrayList([]const u8).empty;
        defer children.deinit(self.allocator);

        for (self.global_names.items, 0..) |global_name, idx| {
            if (idx >= self.global_cells.items.len or !self.global_cells.items[idx].initialized) continue;
            const child = namespaceChildForParent(name.bytes, global_name) orelse continue;
            var seen = false;
            for (children.items) |existing| {
                if (std.mem.eql(u8, existing, child)) {
                    seen = true;
                    break;
                }
            }
            if (!seen) try children.append(self.allocator, child);
        }

        return try self.createManagedHostSymbolListFromSlices(children.items);
    }

    fn tryApplySymbolTargetAmend(self: *Session, base: Value, selector: Value, kind: AmendKind, func_or_value: Value, arg: Value) KError!?Value {
        const mode: ShallowAmendMode = switch (kind) {
            .deep_unary => .unary,
            .deep_assign => .assign,
            .deep_binary => .binary,
            else => return null,
        };
        const name = (try self.symbolTargetName(base)) orelse return null;
        defer self.releaseSymbolTargetName(name);

        const selectors = try self.materializeSelectorPath(selector);
        defer self.releaseArgs(selectors);

        const slot = try self.internGlobalSlot(name.bytes);
        const amended = if (selectors.len == 0 and mode == .assign)
            try self.applyWholeAmend(Value.fromBool(false), mode, func_or_value, arg)
        else blk: {
            const current = try self.loadGlobalSlot(slot);
            break :blk try self.applyDeepAmend(current, selectors, mode, func_or_value, arg);
        };
        errdefer self.releaseValue(amended);
        try self.storeGlobalSlot(slot, amended);
        return amended;
    }

    fn applyAmend(self: *Session, base: Value, selector: Value, kind: AmendKind, func_or_value: Value, arg: Value) KError!Value {
        if (try self.tryApplyCallableTryAmend(base, selector, kind, func_or_value)) |result| return result;
        if (try self.tryApplySymbolTargetAmend(base, selector, kind, func_or_value, arg)) |amended| return amended;
        if (try self.tryApplyIndexedSelectorPathAmend(base, selector, kind, func_or_value, arg)) |amended| return amended;
        return switch (kind) {
            .unary => try self.applyShallowAmend(base, selector, .unary, func_or_value, arg),
            .assign => try self.applyShallowAmend(base, selector, .assign, func_or_value, arg),
            .binary => try self.applyShallowAmend(base, selector, .binary, func_or_value, arg),
            .deep_unary, .deep_assign, .deep_binary => blk: {
                const mode: ShallowAmendMode = switch (kind) {
                    .deep_unary => .unary,
                    .deep_assign => .assign,
                    .deep_binary => .binary,
                    else => unreachable,
                };
                const selectors = try self.materializeSelectorPath(selector);
                defer self.releaseArgs(selectors);
                break :blk try self.applyDeepAmend(base, selectors, mode, func_or_value, arg);
            },
        };
    }

    fn tryApplyCallableTryAmend(self: *Session, base: Value, selector: Value, kind: AmendKind, handler: Value) KError!?Value {
        switch (kind) {
            .unary, .deep_unary => {},
            .assign, .binary, .deep_assign, .deep_binary => return null,
        }
        switch (base.tag()) {
            .builtin, .closure => {},
            else => return null,
        }
        return self.applyDot(base, selector) catch |err| switch (err) {
            error.OutOfMemory, error.Internal => err,
            else => try self.retainEscapedValue(handler),
        };
    }

    fn applyAmendOwned(self: *Session, base: Value, selector: Value, kind: AmendKind, func_or_value: Value, arg: Value) KError!Value {
        if (comptime enable_probe_instrumentation) self.debug.owned_amend_count += 1;
        errdefer self.releaseValue(base);
        const result = try self.applyAmend(base, selector, kind, func_or_value, arg);
        self.releaseValue(base);
        return result;
    }

    const ShallowAmendMode = enum {
        unary,
        assign,
        binary,
    };

    fn materializeIndexedSelectorPath(self: *Session, selector: Value) KError!?[]Value {
        const boxed = boxedArrayItems(selector) orelse return null;
        if (boxed.len == 0 or !isSelectorPathMarkerValue(boxed[0])) return null;
        const items = try self.allocator.alloc(Value, boxed.len - 1);
        errdefer self.allocator.free(items);
        var initialized: usize = 0;
        errdefer {
            for (items[0..initialized]) |value| self.releaseValue(value);
        }
        for (boxed[1..], 0..) |value, idx| {
            items[idx] = try self.retainEscapedValue(value);
            initialized += 1;
        }
        return items;
    }

    fn tryApplyIndexedSelectorPathAmend(self: *Session, base: Value, selector: Value, kind: AmendKind, func_or_value: Value, arg: Value) KError!?Value {
        const mode: ShallowAmendMode = switch (kind) {
            .unary, .deep_unary => .unary,
            .assign, .deep_assign => .assign,
            .binary, .deep_binary => .binary,
        };
        const selectors = (try self.materializeIndexedSelectorPath(selector)) orelse return null;
        defer self.releaseArgs(selectors);
        return try self.applyDeepAmend(base, selectors, mode, func_or_value, arg);
    }

    fn materializeSelectorPath(self: *Session, selector: Value) KError![]Value {
        var items = std.ArrayList(Value).empty;
        errdefer {
            for (items.items) |value| self.releaseValue(value);
            items.deinit(self.allocator);
        }

        switch (selector.tag()) {
            .int, .bool => {
                try items.append(self.allocator, try self.retainEscapedValue(selector));
            },
            .array => if (boxedArrayItems(selector)) |boxed| {
                for (boxed) |value| try items.append(self.allocator, try self.retainEscapedValue(value));
            } else switch (selector.arrayKind()) {
                .numeric_array => {
                    if (valueNonVectorNumericShape(selector) != null) {
                        const rows = try self.materializeTopLevelItems(selector);
                        defer self.releaseArgs(rows);
                        for (rows) |value| try items.append(self.allocator, try self.retainEscapedValue(value));
                    } else {
                        const array = try numericHostArrayValue(self, selector);
                        const len = array.len();
                        for (0..len) |idx| {
                            try items.append(self.allocator, try self.hostDenseIndexScalar(selector, array, @intCast(idx)));
                        }
                    }
                },
                else => return error.Type,
            },
            else => return error.Type,
        }

        return try items.toOwnedSlice(self.allocator);
    }

    fn applyDeepAmend(self: *Session, base: Value, selectors: []const Value, mode: ShallowAmendMode, func_or_value: Value, arg: Value) KError!Value {
        if (selectors.len == 0) return try self.applyWholeAmend(base, mode, func_or_value, arg);
        if (isAllAxisSelectorValue(selectors[0])) {
            if (selectors.len == 1) return try self.applyShallowAmend(base, selectors[0], mode, func_or_value, arg);
            return try self.applyDeepAmendAllAxis(base, selectors[1..], mode, func_or_value, arg);
        }
        if (selectors.len == 1) return try self.applyShallowAmend(base, selectors[0], mode, func_or_value, arg);

        const selected = try self.applyArrayCall1(base, selectors[0]);
        defer self.releaseValue(selected);
        const amended = try self.applyDeepAmend(selected, selectors[1..], mode, func_or_value, arg);
        defer self.releaseValue(amended);
        return try self.applyShallowAmend(base, selectors[0], .assign, amended, Value.fromBool(false));
    }

    fn applyDeepAmendAllAxis(self: *Session, base: Value, rest: []const Value, mode: ShallowAmendMode, func_or_value: Value, arg: Value) KError!Value {
        const items = try self.materializeTopLevelItems(base);
        defer {
            for (items) |value| self.releaseValue(value);
            self.allocator.free(items);
        }

        var rhs_items: ?[]Value = null;
        defer if (rhs_items) |values| {
            for (values) |value| self.releaseValue(value);
            self.allocator.free(values);
        };
        if (mode != .unary) {
            const rhs_source = if (mode == .assign) func_or_value else arg;
            if (rhs_source.tag() == .array) {
                const maybe = try self.tryMaterializeTopLevelItems(rhs_source);
                if (maybe) |values| {
                    if (values.len == items.len) rhs_items = values else {
                        for (values) |value| self.releaseValue(value);
                        self.allocator.free(values);
                    }
                }
            }
        }

        for (items, 0..) |item, idx| {
            const child_func_or_value = if (mode == .assign)
                if (rhs_items) |values| values[idx] else func_or_value
            else
                func_or_value;
            const child_arg = if (mode == .binary)
                if (rhs_items) |values| values[idx] else arg
            else
                arg;
            const amended = try self.applyDeepAmend(item, rest, mode, child_func_or_value, child_arg);
            self.releaseValue(items[idx]);
            items[idx] = amended;
        }

        return try self.rebuildTopLevelItems(base, items);
    }

    const DenseAssignRhs = union(enum) {
        int_scalar: i64,
        float_scalar: f64,
        int_vector: HostIntArrayView,
        float_vector: []const f64,
    };

    const DenseAssignTargets = union(enum) {
        scalar: usize,
        slice: []const usize,
        arithmetic: ArithmeticIndexSlice,
    };

    fn amendCloneOwner(base: Value) HeapOwner {
        std.debug.assert(base.tag() == .array);
        return switch (base.arrayOwner()) {
            .scratch => .scratch,
            .managed, .frozen => .managed,
        };
    }

    fn hostIntKindCanRepresent(kind: HostIntStorageKind, value: i64) bool {
        return switch (kind) {
            .bit => value == 0 or value == 1,
            .int8 => std.math.cast(i8, value) != null,
            .int16 => std.math.cast(i16, value) != null,
            .int32 => std.math.cast(i32, value) != null,
            .int64 => true,
        };
    }

    fn denseAssignRhs(self: *Session, rhs_source: Value, selectors_len: usize) KError!?DenseAssignRhs {
        if (scalarIntLikeValue(rhs_source)) |value| return .{ .int_scalar = value };
        if (rhs_source.tag() == .float) return .{ .float_scalar = rhs_source.asFloat() };
        if (rhs_source.tag() != .array) return null;
        if (valueNonVectorNumericShape(rhs_source) != null) return null;
        const rhs_array = try numericHostArrayValue(self, rhs_source);
        if (rhs_array.len() != selectors_len) return null;
        return switch (hostDenseNumericMode(rhs_array)) {
            .int => .{ .int_vector = hostIntArrayView(rhs_array) orelse return null },
            .float => switch (rhs_array.storage) {
                .float64 => |items| .{ .float_vector = hostDenseLogicalItems(f64, rhs_array, items) },
                else => null,
            },
        };
    }

    fn denseAssignRhsFitsIntKind(kind: HostIntStorageKind, selectors_len: usize, rhs: DenseAssignRhs) bool {
        return switch (rhs) {
            .int_scalar => |value| hostIntKindCanRepresent(kind, value),
            .float_scalar => |value| blk: {
                const int_value = exactIntFromFloat(value) orelse break :blk false;
                break :blk hostIntKindCanRepresent(kind, int_value);
            },
            .int_vector => |view| blk: {
                std.debug.assert(hostIntArrayViewLen(view) == selectors_len);
                for (0..selectors_len) |idx| {
                    if (!hostIntKindCanRepresent(kind, hostIntViewItem(view, idx))) break :blk false;
                }
                break :blk true;
            },
            .float_vector => |items| blk: {
                std.debug.assert(items.len == selectors_len);
                for (items) |item| {
                    const int_value = exactIntFromFloat(item) orelse break :blk false;
                    if (!hostIntKindCanRepresent(kind, int_value)) break :blk false;
                }
                break :blk true;
            },
        };
    }

    fn denseAssignTargetsLen(targets: DenseAssignTargets) usize {
        return switch (targets) {
            .scalar => 1,
            .slice => |selectors| selectors.len,
            .arithmetic => |slice| slice.len,
        };
    }

    fn denseAssignArithmeticTarget(slice: ArithmeticIndexSlice, idx: usize) usize {
        const target_i64 = @as(i64, @intCast(slice.start)) + @as(i64, @intCast(idx)) * @as(i64, slice.step);
        std.debug.assert(target_i64 >= 0);
        return @intCast(target_i64);
    }

    fn recordFastDenseAssignHit(self: *Session, targets: DenseAssignTargets, rhs: DenseAssignRhs, reused: bool) void {
        if (comptime !enable_probe_instrumentation) return;
        self.debug.fast_dense_assign_hit_count += 1;
        if (reused) self.debug.fast_dense_assign_reuse_count += 1;
        self.debug.fast_dense_assign_target_element_count += denseAssignTargetsLen(targets);
        switch (targets) {
            .scalar => self.debug.fast_dense_assign_scalar_target_count += 1,
            .slice, .arithmetic => self.debug.fast_dense_assign_vector_target_count += 1,
        }
        switch (rhs) {
            .int_scalar, .float_scalar => self.debug.fast_dense_assign_scalar_rhs_count += 1,
            .int_vector, .float_vector => self.debug.fast_dense_assign_vector_rhs_count += 1,
        }
    }

    fn denseAssignIntScalarValue(rhs: DenseAssignRhs) KError!i64 {
        return switch (rhs) {
            .int_scalar => |value| value,
            .float_scalar => |value| exactIntFromFloat(value) orelse return error.Unsupported,
            .int_vector => |view| blk: {
                std.debug.assert(hostIntArrayViewLen(view) == 1);
                break :blk hostIntViewItem(view, 0);
            },
            .float_vector => |items| blk: {
                std.debug.assert(items.len == 1);
                break :blk exactIntFromFloat(items[0]) orelse return error.Unsupported;
            },
        };
    }

    fn denseAssignFloatScalarValue(rhs: DenseAssignRhs) f64 {
        return switch (rhs) {
            .int_scalar => |value| @as(f64, @floatFromInt(value)),
            .float_scalar => |value| value,
            .int_vector => |view| blk: {
                std.debug.assert(hostIntArrayViewLen(view) == 1);
                break :blk @as(f64, @floatFromInt(hostIntViewItem(view, 0)));
            },
            .float_vector => |items| blk: {
                std.debug.assert(items.len == 1);
                break :blk items[0];
            },
        };
    }

    fn denseAssignScalarIntLike(rhs_source: Value) ?i64 {
        if (scalarIntLikeValue(rhs_source)) |value| return value;
        if (rhs_source.tag() == .float) return exactIntFromFloat(rhs_source.asFloat());
        return null;
    }

    fn denseAssignScalarFloatLike(rhs_source: Value) ?f64 {
        if (scalarIntLikeValue(rhs_source)) |value| return @floatFromInt(value);
        if (rhs_source.tag() == .float) return rhs_source.asFloat();
        return null;
    }

    fn applyDenseAssignIntScalar(out: *HostIntResult, target_idx: usize, item_value: i64) KError!void {
        switch (out.*) {
            .bit => |*bits| switch (item_value) {
                0 => bitSet(bits.words, target_idx, false),
                1 => bitSet(bits.words, target_idx, true),
                else => return error.Unsupported,
            },
            .int8 => |*items| items.items[target_idx] = std.math.cast(i8, item_value) orelse return error.Unsupported,
            .int16 => |*items| items.items[target_idx] = std.math.cast(i16, item_value) orelse return error.Unsupported,
            .int32 => |*items| items.items[target_idx] = std.math.cast(i32, item_value) orelse return error.Unsupported,
            .int64 => |*items| items.items[target_idx] = item_value,
        }
    }

    fn tryApplyDenseAssignBitArithmeticScalar(out: *HostIntResult, slice: ArithmeticIndexSlice, item_value: i64) KError!bool {
        switch (out.*) {
            .bit => |*bits| switch (item_value) {
                0 => {
                    bitSetArithmeticSlice(bits.words, slice, false);
                    return true;
                },
                1 => {
                    bitSetArithmeticSlice(bits.words, slice, true);
                    return true;
                },
                else => return error.Unsupported,
            },
            else => return false,
        }
    }

    fn applyDenseAssignIntRhs(out: *HostIntResult, targets: DenseAssignTargets, rhs: DenseAssignRhs) KError!void {
        switch (targets) {
            .scalar => |target_idx| try applyDenseAssignIntScalar(out, target_idx, try denseAssignIntScalarValue(rhs)),
            .slice => |selectors| switch (rhs) {
                .int_scalar => |value| {
                    for (selectors) |target_idx| try applyDenseAssignIntScalar(out, target_idx, value);
                },
                .float_scalar => |value| {
                    const int_value = exactIntFromFloat(value) orelse return error.Unsupported;
                    for (selectors) |target_idx| try applyDenseAssignIntScalar(out, target_idx, int_value);
                },
                .int_vector => |view| {
                    std.debug.assert(hostIntArrayViewLen(view) == selectors.len);
                    for (selectors, 0..) |target_idx, idx| try applyDenseAssignIntScalar(out, target_idx, hostIntViewItem(view, idx));
                },
                .float_vector => |items| {
                    std.debug.assert(items.len == selectors.len);
                    for (selectors, 0..) |target_idx, idx| {
                        const int_value = exactIntFromFloat(items[idx]) orelse return error.Unsupported;
                        try applyDenseAssignIntScalar(out, target_idx, int_value);
                    }
                },
            },
            .arithmetic => |slice| switch (rhs) {
                .int_scalar => |value| {
                    if (try tryApplyDenseAssignBitArithmeticScalar(out, slice, value)) return;
                    for (0..slice.len) |idx| try applyDenseAssignIntScalar(out, denseAssignArithmeticTarget(slice, idx), value);
                },
                .float_scalar => |value| {
                    const int_value = exactIntFromFloat(value) orelse return error.Unsupported;
                    if (try tryApplyDenseAssignBitArithmeticScalar(out, slice, int_value)) return;
                    for (0..slice.len) |idx| try applyDenseAssignIntScalar(out, denseAssignArithmeticTarget(slice, idx), int_value);
                },
                .int_vector => |view| {
                    std.debug.assert(hostIntArrayViewLen(view) == slice.len);
                    for (0..slice.len) |idx| try applyDenseAssignIntScalar(out, denseAssignArithmeticTarget(slice, idx), hostIntViewItem(view, idx));
                },
                .float_vector => |items| {
                    std.debug.assert(items.len == slice.len);
                    for (0..slice.len) |idx| {
                        const int_value = exactIntFromFloat(items[idx]) orelse return error.Unsupported;
                        try applyDenseAssignIntScalar(out, denseAssignArithmeticTarget(slice, idx), int_value);
                    }
                },
            },
        }
    }

    fn applyDenseAssignFloatRhs(out: []f64, targets: DenseAssignTargets, rhs: DenseAssignRhs) void {
        switch (targets) {
            .scalar => |target_idx| out[target_idx] = denseAssignFloatScalarValue(rhs),
            .slice => |selectors| switch (rhs) {
                .int_scalar => |value| {
                    const float_value = @as(f64, @floatFromInt(value));
                    for (selectors) |target_idx| out[target_idx] = float_value;
                },
                .float_scalar => |value| {
                    for (selectors) |target_idx| out[target_idx] = value;
                },
                .int_vector => |view| {
                    std.debug.assert(hostIntArrayViewLen(view) == selectors.len);
                    for (selectors, 0..) |target_idx, idx| out[target_idx] = @as(f64, @floatFromInt(hostIntViewItem(view, idx)));
                },
                .float_vector => |items| {
                    std.debug.assert(items.len == selectors.len);
                    for (selectors, 0..) |target_idx, idx| out[target_idx] = items[idx];
                },
            },
            .arithmetic => |slice| switch (rhs) {
                .int_scalar => |value| {
                    const float_value = @as(f64, @floatFromInt(value));
                    for (0..slice.len) |idx| out[denseAssignArithmeticTarget(slice, idx)] = float_value;
                },
                .float_scalar => |value| {
                    for (0..slice.len) |idx| out[denseAssignArithmeticTarget(slice, idx)] = value;
                },
                .int_vector => |view| {
                    std.debug.assert(hostIntArrayViewLen(view) == slice.len);
                    for (0..slice.len) |idx| out[denseAssignArithmeticTarget(slice, idx)] = @as(f64, @floatFromInt(hostIntViewItem(view, idx)));
                },
                .float_vector => |items| {
                    std.debug.assert(items.len == slice.len);
                    for (0..slice.len) |idx| out[denseAssignArithmeticTarget(slice, idx)] = items[idx];
                },
            },
        }
    }

    fn prepareReusableHostDenseForMutation(self: *Session, source: Value) bool {
        const handle = valueNumericHandle(source) orelse return true;
        const mutable_handle = @constCast(handle);
        if (numericBackendAttachment(handle) != null) {
            if (mutable_handle.header.owner != .managed) return false;
            self.evictBackendAttachment(mutable_handle);
        }
        mutable_handle.preferred = .host;
        return true;
    }

    fn recordFastDenseAssignMiss(self: *Session) void {
        if (comptime enable_probe_instrumentation) self.debug.fast_dense_assign_miss_count += 1;
    }

    fn recordFastDenseAssignClone(self: *Session, base: Value) void {
        if (comptime !enable_probe_instrumentation) return;
        self.debug.fast_dense_assign_clone_count += 1;

        if (mutableNumericHandle(base)) |handle| {
            switch (handle.header.owner) {
                .managed => {
                    if (handle.header.ref_count != 1) {
                        self.debug.fast_dense_assign_clone_reason_counts[@backingInt(DebugFastDenseAssignCloneReason.non_unique)] += 1;
                        return;
                    }
                },
                .frozen => {
                    self.debug.fast_dense_assign_clone_reason_counts[@backingInt(DebugFastDenseAssignCloneReason.frozen)] += 1;
                    return;
                },
                .scratch => {},
            }
        }

        self.debug.fast_dense_assign_clone_reason_counts[@backingInt(DebugFastDenseAssignCloneReason.other)] += 1;
    }

    fn finishFastDenseScalarIntAssign(self: *Session, target_idx: usize, rhs: DenseAssignRhs, out: *HostIntResult, reused: bool) KError!Value {
        const host = out.arrayPtr();
        hostDenseSetFlags(host, host_dense_flag_normalized);
        self.invalidateHostDenseCachesForMutation(out.value(), host);
        const value = out.value();
        self.recordFastDenseAssignHit(.{ .scalar = target_idx }, rhs, reused);
        return if (reused) self.shareValue(value) else value;
    }

    fn finishFastDenseScalarFloatAssign(self: *Session, target_idx: usize, rhs: DenseAssignRhs, out: HostFloatResult, reused: bool) KError!Value {
        hostDenseSetFlags(out.array, host_dense_flag_normalized);
        self.invalidateHostDenseCachesForMutation(out.value(), out.array);
        const value = out.value();
        self.recordFastDenseAssignHit(.{ .scalar = target_idx }, rhs, reused);
        return if (reused) self.shareValue(value) else value;
    }

    fn tryFastDenseScalarAssignDirect(self: *Session, base: Value, target_idx: usize, rhs_source: Value) KError!?Value {
        if (valueNumericMode(base) == null) return null;
        if (valueNonVectorNumericShape(base) != null) return null;
        const base_array = try numericHostArrayValue(self, base);

        switch (base_array.storage) {
            .bit => {
                const rhs_int = denseAssignScalarIntLike(rhs_source) orelse return null;
                if (rhs_int != 0 and rhs_int != 1) return null;
                if (comptime enable_probe_instrumentation) self.debug.fast_dense_assign_attempt_count += 1;

                var reused = false;
                var out = if (self.tryReuseHostIntArrayResult(base, .bit)) |existing| blk: {
                    if (!self.prepareReusableHostDenseForMutation(base)) {
                        self.recordFastDenseAssignMiss();
                        return null;
                    }
                    reused = true;
                    break :blk existing;
                } else blk: {
                    self.recordFastDenseAssignClone(base);
                    var allocated = try self.allocOwnedHostIntCloneResult(amendCloneOwner(base), .bit, base_array.len());
                    errdefer self.releaseValue(allocated.value());
                    @memcpy(allocated.bit.words, hostDenseLogicalBitWords(base_array, base_array.storage.bit));
                    break :blk allocated;
                };
                try applyDenseAssignIntScalar(&out, target_idx, rhs_int);
                return try self.finishFastDenseScalarIntAssign(target_idx, .{ .int_scalar = rhs_int }, &out, reused);
            },
            .int8, .int16, .int32, .int64 => {
                const rhs_int = denseAssignScalarIntLike(rhs_source) orelse return null;
                const view = hostIntArrayView(base_array) orelse return null;
                const kind = hostIntArrayViewKind(view);
                if (!hostIntKindCanRepresent(kind, rhs_int)) return null;
                if (comptime enable_probe_instrumentation) self.debug.fast_dense_assign_attempt_count += 1;

                var reused = false;
                var out = if (self.tryReuseHostIntArrayResult(base, kind)) |existing| blk: {
                    if (!self.prepareReusableHostDenseForMutation(base)) {
                        self.recordFastDenseAssignMiss();
                        return null;
                    }
                    reused = true;
                    break :blk existing;
                } else blk: {
                    self.recordFastDenseAssignClone(base);
                    var allocated = try self.allocOwnedHostIntCloneResult(amendCloneOwner(base), kind, base_array.len());
                    errdefer self.releaseValue(allocated.value());
                    try copyHostIntViewToResult(&allocated, view);
                    break :blk allocated;
                };
                try applyDenseAssignIntScalar(&out, target_idx, rhs_int);
                return try self.finishFastDenseScalarIntAssign(target_idx, .{ .int_scalar = rhs_int }, &out, reused);
            },
            .float32 => return null,
            .float64 => |base_items| {
                const rhs_float = denseAssignScalarFloatLike(rhs_source) orelse return null;
                const rhs: DenseAssignRhs = if (scalarIntLikeValue(rhs_source)) |rhs_int|
                    .{ .int_scalar = rhs_int }
                else
                    .{ .float_scalar = rhs_float };
                if (comptime enable_probe_instrumentation) self.debug.fast_dense_assign_attempt_count += 1;

                var reused = false;
                const out = if (self.tryReuseHostFloatArrayResult(base)) |existing| blk: {
                    if (!self.prepareReusableHostDenseForMutation(base)) {
                        self.recordFastDenseAssignMiss();
                        return null;
                    }
                    reused = true;
                    break :blk existing;
                } else blk: {
                    self.recordFastDenseAssignClone(base);
                    const allocated = try self.allocOwnedHostFloatResult(amendCloneOwner(base), base_array.len());
                    errdefer self.releaseValue(allocated.value());
                    @memcpy(allocated.items, base_items);
                    break :blk allocated;
                };
                out.items[target_idx] = rhs_float;
                return try self.finishFastDenseScalarFloatAssign(target_idx, rhs, out, reused);
            },
        }
    }

    fn tryFastDenseAssignAmendImpl(self: *Session, base: Value, targets: DenseAssignTargets, rhs_source: Value) KError!?Value {
        const targets_len = denseAssignTargetsLen(targets);
        if (targets_len == 0) {
            self.recordFastDenseAssignMiss();
            return null;
        }
        if (valueNumericMode(base) == null) {
            self.recordFastDenseAssignMiss();
            return null;
        }
        if (valueNonVectorNumericShape(base) != null) {
            self.recordFastDenseAssignMiss();
            return null;
        }

        const rhs = (try self.denseAssignRhs(rhs_source, targets_len)) orelse {
            self.recordFastDenseAssignMiss();
            return null;
        };
        const base_array = try numericHostArrayValue(self, base);

        return switch (hostDenseNumericMode(base_array)) {
            .int => blk: {
                const view = hostIntArrayView(base_array) orelse {
                    self.recordFastDenseAssignMiss();
                    return null;
                };
                const kind = hostIntArrayViewKind(view);
                if (!denseAssignRhsFitsIntKind(kind, targets_len, rhs)) {
                    self.recordFastDenseAssignMiss();
                    return null;
                }

                var reused = false;
                var out = if (self.tryReuseHostIntArrayResult(base, kind)) |existing| blk_out: {
                    if (!self.prepareReusableHostDenseForMutation(base)) {
                        self.recordFastDenseAssignMiss();
                        return null;
                    }
                    reused = true;
                    break :blk_out existing;
                } else blk_out: {
                    self.recordFastDenseAssignClone(base);
                    var allocated = try self.allocOwnedHostIntCloneResult(amendCloneOwner(base), kind, base_array.len());
                    errdefer self.releaseValue(allocated.value());
                    try copyHostIntViewToResult(&allocated, view);
                    break :blk_out allocated;
                };
                try applyDenseAssignIntRhs(&out, targets, rhs);
                const host = out.arrayPtr();
                hostDenseSetFlags(host, host_dense_flag_normalized);
                self.invalidateHostDenseCachesForMutation(out.value(), host);
                const value = out.value();
                self.recordFastDenseAssignHit(targets, rhs, reused);
                break :blk if (reused) self.shareValue(value) else value;
            },
            .float => blk: {
                const base_items = base_array.storage.float64;
                var reused = false;
                var out = if (self.tryReuseHostFloatArrayResult(base)) |existing| blk_out: {
                    if (!self.prepareReusableHostDenseForMutation(base)) {
                        self.recordFastDenseAssignMiss();
                        return null;
                    }
                    reused = true;
                    break :blk_out existing;
                } else blk_out: {
                    self.recordFastDenseAssignClone(base);
                    const allocated = try self.allocOwnedHostFloatResult(amendCloneOwner(base), base_array.len());
                    errdefer self.releaseValue(allocated.value());
                    @memcpy(allocated.items, base_items);
                    break :blk_out allocated;
                };
                applyDenseAssignFloatRhs(out.items, targets, rhs);
                hostDenseSetFlags(out.array, host_dense_flag_normalized);
                self.invalidateHostDenseCachesForMutation(out.value(), out.array);
                const value = out.value();
                self.recordFastDenseAssignHit(targets, rhs, reused);
                break :blk if (reused) self.shareValue(value) else value;
            },
        };
    }

    fn tryFastDenseAssignScalarAmend(self: *Session, base: Value, target_idx: usize, rhs_source: Value) KError!?Value {
        if (comptime enable_probe_instrumentation) self.debug.fast_dense_assign_attempt_count += 1;
        return try self.tryFastDenseAssignAmendImpl(base, .{ .scalar = target_idx }, rhs_source);
    }

    fn tryFastIndexedDenseScalarAssignOwned(self: *Session, base: Value, selector: Value, rhs_source: Value) KError!?Value {
        if (base.tag() != .array) return null;
        const raw_index = scalarIntLikeValue(selector) orelse return null;
        errdefer self.releaseValue(base);
        const target_idx = try normalizeIndex(raw_index, try self.topLevelLen(base));
        if (try self.tryFastDenseScalarAssignDirect(base, target_idx, rhs_source)) |amended| {
            if (comptime enable_probe_instrumentation) self.debug.owned_amend_count += 1;
            self.releaseValue(base);
            return amended;
        }
        const amended = (try self.tryFastDenseAssignScalarAmend(base, target_idx, rhs_source)) orelse return null;
        if (comptime enable_probe_instrumentation) self.debug.owned_amend_count += 1;
        self.releaseValue(base);
        return amended;
    }

    const DirectGlobalIndexedAssignResult = struct {
        result: ?Value = null,
    };

    fn tryFastGlobalDenseScalarAssignInPlace(
        self: *Session,
        slot: u16,
        selector: Value,
        rhs_source: Value,
        want_result: bool,
    ) KError!?DirectGlobalIndexedAssignResult {
        const cell = try self.loadGlobalCell(slot);
        const base = cell.value;
        if (!cell.class.isArray()) return null;
        const raw_index = scalarIntLikeValue(selector) orelse return null;
        if (comptime enable_probe_instrumentation) self.debug.fast_dense_assign_attempt_count += 1;
        if (valueNonVectorNumericShape(base) != null) {
            self.recordFastDenseAssignMiss();
            return null;
        }
        const base_array = hostDenseIfPresent(base) orelse {
            self.recordFastDenseAssignMiss();
            return null;
        };
        const target_idx = try normalizeIndex(raw_index, base_array.len());
        const rhs = (try self.denseAssignRhs(rhs_source, 1)) orelse {
            self.recordFastDenseAssignMiss();
            return null;
        };

        switch (hostDenseNumericMode(base_array)) {
            .int => {
                const view = hostIntArrayView(base_array) orelse {
                    self.recordFastDenseAssignMiss();
                    return null;
                };
                const kind = hostIntArrayViewKind(view);
                if (!denseAssignRhsFitsIntKind(kind, 1, rhs)) {
                    self.recordFastDenseAssignMiss();
                    return null;
                }
                var out = self.tryReuseHostIntArrayResult(base, kind) orelse {
                    self.recordFastDenseAssignMiss();
                    return null;
                };
                if (!self.prepareReusableHostDenseForMutation(base)) {
                    self.recordFastDenseAssignMiss();
                    return null;
                }
                try applyDenseAssignIntRhs(&out, .{ .scalar = target_idx }, rhs);
                const host = out.arrayPtr();
                hostDenseSetFlags(host, host_dense_flag_normalized);
                self.invalidateHostDenseCachesForMutation(base, host);
            },
            .float => {
                const out = self.tryReuseHostFloatArrayResult(base) orelse {
                    self.recordFastDenseAssignMiss();
                    return null;
                };
                if (!self.prepareReusableHostDenseForMutation(base)) {
                    self.recordFastDenseAssignMiss();
                    return null;
                }
                applyDenseAssignFloatRhs(out.items, .{ .scalar = target_idx }, rhs);
                hostDenseSetFlags(out.array, host_dense_flag_normalized);
                self.invalidateHostDenseCachesForMutation(base, out.array);
            },
        }

        cell.class = classifyGlobalValue(base);
        if (comptime enable_probe_instrumentation) {
            self.recordFastDenseAssignHit(.{ .scalar = target_idx }, rhs, true);
            self.debug.owned_amend_count += 1;
        }
        return .{
            .result = if (want_result) try self.applyArrayCall1Scalar(base, raw_index) else null,
        };
    }

    fn tryFastDenseAssignAmend(self: *Session, base: Value, selectors: []const usize, rhs_source: Value) KError!?Value {
        if (comptime enable_probe_instrumentation) self.debug.fast_dense_assign_attempt_count += 1;
        return try self.tryFastDenseAssignAmendImpl(base, .{ .slice = selectors }, rhs_source);
    }

    fn tryFastDenseAssignArithmeticAmend(self: *Session, base: Value, slice: ArithmeticIndexSlice, rhs_source: Value) KError!?Value {
        if (comptime enable_probe_instrumentation) self.debug.fast_dense_assign_attempt_count += 1;
        return try self.tryFastDenseAssignAmendImpl(base, .{ .arithmetic = slice }, rhs_source);
    }

    fn applyWholeAmend(self: *Session, base: Value, mode: ShallowAmendMode, func_or_value: Value, arg: Value) KError!Value {
        return switch (mode) {
            .assign => try self.retainEscapedValue(func_or_value),
            .unary => try self.applyValue(func_or_value, &[_]Value{base}),
            .binary => try self.applyValue(func_or_value, &[_]Value{ base, arg }),
        };
    }

    fn tryApplyGroupedShallowAmend(self: *Session, base: Value, selector: Value, mode: ShallowAmendMode, func_or_value: Value, arg: Value) KError!?Value {
        var owned_groups: ?[]Value = null;
        defer if (owned_groups) |values| {
            for (values) |value| self.releaseValue(value);
            self.allocator.free(values);
        };
        const groups = boxedArrayItems(selector) orelse blk: {
            if (valueNonVectorNumericShape(selector) == null) return null;
            owned_groups = try self.materializeTopLevelItems(selector);
            break :blk owned_groups.?;
        };
        if (groups.len == 0) return try self.retainEscapedValue(base);

        var rhs_items: ?[]Value = null;
        defer if (rhs_items) |values| {
            for (values) |value| self.releaseValue(value);
            self.allocator.free(values);
        };

        if (mode != .unary) {
            const rhs_source = if (mode == .assign) func_or_value else arg;
            if (rhs_source.tag() == .array) {
                const maybe = try self.tryMaterializeTopLevelItems(rhs_source);
                if (maybe) |values| rhs_items = values;
            }
        }

        var current = try self.retainEscapedValue(base);
        errdefer self.releaseValue(current);

        for (groups, 0..) |group, idx| {
            const group_func_or_value = if (mode == .assign)
                if (rhs_items) |values| if (values.len == groups.len) values[idx] else func_or_value else func_or_value
            else
                func_or_value;
            const group_arg = if (mode == .binary)
                if (rhs_items) |values| if (values.len == groups.len) values[idx] else arg else arg
            else
                arg;
            const amended = try self.applyShallowAmend(current, group, mode, group_func_or_value, group_arg);
            self.releaseValue(current);
            current = amended;
        }

        return current;
    }

    fn findKeyIndexInItems(self: *Session, keys: []const Value, key: Value) KError!?usize {
        for (keys, 0..) |candidate, idx| {
            if (try self.valueMatchEqual(candidate, key)) return idx;
        }
        return null;
    }

    fn createKeyArrayFromValues(self: *Session, keys: []const Value) KError!Value {
        var symbol_slices = std.ArrayList([]const u8).empty;
        defer symbol_slices.deinit(self.allocator);
        try symbol_slices.ensureTotalCapacity(self.allocator, keys.len);
        for (keys) |key| {
            const bytes = symbolBytes(key) orelse break;
            try symbol_slices.append(self.allocator, bytes);
        }
        if (symbol_slices.items.len == keys.len) return try self.createManagedHostSymbolListFromSlices(symbol_slices.items);
        return try self.makeArrayFromValues(keys);
    }

    fn missingDictAmendValue(self: *Session, func: Value, rhs: Value) KError!Value {
        if (func.tag() == .builtin) {
            return switch (func.asBuiltin()) {
                .add, .sub => if (rhs.tag() == .float) try self.floatValue(0) else try self.intValue(0),
                .mul, .div => if (rhs.tag() == .float) try self.floatValue(1) else try self.intValue(1),
                else => try self.prototypeLikeValue(rhs),
            };
        }
        return try self.prototypeLikeValue(rhs);
    }

    fn tryApplyDictShallowAmend(self: *Session, base: Value, selector: Value, mode: ShallowAmendMode, func_or_value: Value, arg: Value) KError!?Value {
        if (base.tag() != .array or base.arrayKind() != .host_keyed_store) return null;
        const store = base.asHostKeyedStore();
        if (store.layout != .dict) return null;

        const selector_items = try self.materializeSequenceItems(selector);
        defer self.releaseArgs(selector_items);
        if (selector_items.len == 0) return try self.retainEscapedValue(base);

        var keys = std.ArrayList(Value).empty;
        var values = std.ArrayList(Value).empty;
        defer {
            for (keys.items) |value| self.releaseValue(value);
            for (values.items) |value| self.releaseValue(value);
            keys.deinit(self.allocator);
            values.deinit(self.allocator);
        }

        const existing_len = keyedStoreNameCount(store);
        try keys.ensureTotalCapacity(self.allocator, existing_len + selector_items.len);
        try values.ensureTotalCapacity(self.allocator, existing_len + selector_items.len);
        for (0..existing_len) |idx| {
            try keys.append(self.allocator, try self.keyedStoreNameValue(store, idx));
            try values.append(self.allocator, try self.keyedStoreValueAt(store, idx));
        }

        var rhs_items: ?[]Value = null;
        defer if (rhs_items) |items| {
            for (items) |value| self.releaseValue(value);
            self.allocator.free(items);
        };

        const rhs_source = switch (mode) {
            .assign => func_or_value,
            .binary => arg,
            .unary => Value.fromBool(false),
        };
        const selector_is_scalar = derivedSequenceLen(selector) == null;
        if (mode != .unary and rhs_source.tag() == .array) {
            const maybe = try self.tryMaterializeTopLevelItems(rhs_source);
            if (maybe) |items| rhs_items = items;
        }

        for (selector_items, 0..) |key, idx| {
            const rhs = if (rhs_items) |items|
                if (!selector_is_scalar and items.len == selector_items.len) items[idx] else rhs_source
            else
                rhs_source;

            const existing = try self.findKeyIndexInItems(keys.items, key);
            const target_idx = existing orelse blk: {
                try keys.append(self.allocator, try self.retainEscapedValue(key));
                const placeholder = switch (mode) {
                    .assign => try self.retainEscapedValue(rhs),
                    .unary => try self.prototypeLikeValue(store.values),
                    .binary => try self.missingDictAmendValue(func_or_value, rhs),
                };
                try values.append(self.allocator, placeholder);
                break :blk values.items.len - 1;
            };

            const current = values.items[target_idx];
            const next = switch (mode) {
                .assign => if (existing == null) try self.retainEscapedValue(current) else try self.retainEscapedValue(rhs),
                .unary => try self.applyValue(func_or_value, &[_]Value{current}),
                .binary => try self.applyValue(func_or_value, &[_]Value{ current, rhs }),
            };
            self.releaseValue(values.items[target_idx]);
            values.items[target_idx] = next;
        }

        const keys_value = try self.createKeyArrayFromValues(keys.items);
        defer self.releaseValue(keys_value);
        const values_value = try self.makeArrayFromValues(values.items);
        defer self.releaseValue(values_value);
        return try self.createHostDictValueFromKeySequenceValue("", keys_value, values_value);
    }

    fn retainedTableColumnData(self: *Session, store: *const HostKeyedStore, column_idx: usize) KError!Value {
        return try self.retainEscapedValue(tableColumnData(store, column_idx));
    }

    fn buildTableColumnFromValue(self: *Session, name: Value, value: Value, row_count: usize) KError!HostTableColumn {
        const spec = try self.classifyDictTableColumn(value);
        return try self.buildDictTableColumn(name, spec, row_count);
    }

    fn tryApplyTableColumnAssign(self: *Session, store: *const HostKeyedStore, selector: Value, rhs: Value) KError!?Value {
        const name = keyedLookupNameBytes(selector) orelse return null;
        const existing_idx = store.lookup.get(name);
        const old_count = keyedStoreNameCount(store);
        const new_count = old_count + if (existing_idx == null) @as(usize, 1) else 0;
        const columns = try self.allocator.alloc(HostTableColumn, new_count);
        var built: usize = 0;
        errdefer {
            for (columns[0..built]) |column| {
                self.releaseValue(column.name);
                self.releaseValue(column.data);
                if (column.validity) |mask| self.releaseValue(mask);
            }
            self.allocator.free(columns);
        }

        const metadata = keyedStoreTableMetadata(store);
        for (0..old_count) |idx| {
            const column_name = try self.keyedStoreNameValue(store, idx);
            errdefer self.releaseValue(column_name);
            if (existing_idx != null and existing_idx.? == idx) {
                columns[built] = try self.buildTableColumnFromValue(column_name, rhs, store.row_count);
            } else {
                columns[built] = .{
                    .name = try self.retainEscapedValue(column_name),
                    .data = try self.retainedTableColumnData(store, idx),
                    .validity = if (metadata[idx].validity) |mask| try self.retainEscapedValue(mask) else null,
                    .kind = metadata[idx].kind,
                };
            }
            self.releaseValue(column_name);
            built += 1;
        }

        if (existing_idx == null) {
            const column_name = try self.managedHostSymbol(name);
            errdefer self.releaseValue(column_name);
            columns[built] = try self.buildTableColumnFromValue(column_name, rhs, store.row_count);
            self.releaseValue(column_name);
            built += 1;
        }

        return try self.createManagedHostTable(store.row_count, columns);
    }

    fn tableRowAssignColumnRhs(self: *Session, rhs: Value, column_name: []const u8) KError!Value {
        if (rhs.tag() != .array or rhs.arrayKind() != .host_keyed_store) return error.Type;
        const rhs_store = rhs.asHostKeyedStore();
        return switch (rhs_store.layout) {
            .dict => try self.keyedStoreLookupValue(rhs_store, column_name),
            .table => try self.keyedStoreLookupValue(rhs_store, column_name),
        };
    }

    fn tryApplyTableRowAssign(self: *Session, base: Value, store: *const HostKeyedStore, selector: Value, rhs: Value) KError!?Value {
        const row_indices = self.collectSelectorIndices(base, selector) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        defer self.allocator.free(row_indices);
        if (row_indices.len == 0) return try self.retainEscapedValue(base);

        const column_count = keyedStoreNameCount(store);
        const columns = try self.allocator.alloc(HostTableColumn, column_count);
        var built: usize = 0;
        errdefer {
            for (columns[0..built]) |column| {
                self.releaseValue(column.name);
                self.releaseValue(column.data);
                if (column.validity) |mask| self.releaseValue(mask);
            }
            self.allocator.free(columns);
        }

        for (0..column_count) |column_idx| {
            const column_name = try self.keyedStoreNameValue(store, column_idx);
            errdefer self.releaseValue(column_name);
            const column_name_bytes = keyedLookupNameBytes(column_name) orelse return error.Type;
            const rhs_column = try self.tableRowAssignColumnRhs(rhs, column_name_bytes);
            defer self.releaseValue(rhs_column);

            var rhs_items: ?[]Value = null;
            defer if (rhs_items) |items| {
                for (items) |value| self.releaseValue(value);
                self.allocator.free(items);
            };
            if (rhs_column.tag() == .array) {
                const maybe = try self.tryMaterializeTopLevelItems(rhs_column);
                if (maybe) |items| rhs_items = items;
            }

            const row_values = try self.allocator.alloc(Value, store.row_count);
            defer self.allocator.free(row_values);
            var initialized: usize = 0;
            defer {
                for (row_values[0..initialized]) |value| self.releaseValue(value);
            }

            for (0..store.row_count) |row| {
                row_values[row] = try self.tableCellScalarValue(store, column_idx, row);
                initialized += 1;
            }

            for (row_indices, 0..) |row, row_pos| {
                const replacement = if (rhs_items) |items|
                    if (items.len == row_indices.len) items[row_pos] else rhs_column
                else
                    rhs_column;
                self.releaseValue(row_values[row]);
                row_values[row] = try self.retainEscapedValue(replacement);
            }

            const column_value = try self.makeArrayFromValues(row_values);
            defer self.releaseValue(column_value);
            columns[built] = try self.buildTableColumnFromValue(column_name, column_value, store.row_count);
            self.releaseValue(column_name);
            built += 1;
        }

        return try self.createManagedHostTable(store.row_count, columns);
    }

    fn tryApplyTableShallowAmend(self: *Session, base: Value, selector: Value, mode: ShallowAmendMode, func_or_value: Value, arg: Value) KError!?Value {
        _ = arg;
        if (base.tag() != .array or base.arrayKind() != .host_keyed_store) return null;
        const store = base.asHostKeyedStore();
        if (store.layout != .table) return null;
        if (mode != .assign) return null;
        if (try self.tryApplyTableColumnAssign(store, selector, func_or_value)) |table| return table;
        return try self.tryApplyTableRowAssign(base, store, selector, func_or_value);
    }

    fn applyShallowAmend(self: *Session, base: Value, selector: Value, mode: ShallowAmendMode, func_or_value: Value, arg: Value) KError!Value {
        if (base.tag() != .array) return error.Type;
        if (try self.tryApplyDictShallowAmend(base, selector, mode, func_or_value, arg)) |dict| return dict;
        if (try self.tryApplyTableShallowAmend(base, selector, mode, func_or_value, arg)) |table| return table;
        if (try self.tryApplyGroupedShallowAmend(base, selector, mode, func_or_value, arg)) |grouped| return grouped;
        var tried_scalar_fast_assign = false;
        if (mode == .assign and valueNumericMode(base) != null) {
            if (scalarIntLikeValue(selector)) |raw_index| {
                tried_scalar_fast_assign = true;
                const target_idx = try normalizeIndex(raw_index, try self.topLevelLen(base));
                if (try self.tryFastDenseAssignScalarAmend(base, target_idx, func_or_value)) |fast| return fast;
            }
            if (!tried_scalar_fast_assign) {
                if (try numericValueRangeIotaSelectorSlice(base, selector)) |slice| {
                    if (try self.tryFastDenseAssignArithmeticAmend(base, slice, func_or_value)) |fast| return fast;
                }
            }
        }
        const selectors = self.collectSelectorIndices(base, selector) catch |err| switch (err) {
            error.Type => if (try self.tryApplyNumericMatrixColumnAmend(base, selector, mode, func_or_value, arg)) |matrix| return matrix else return err,
            else => return err,
        };
        defer self.allocator.free(selectors);

        if (mode == .assign and !tried_scalar_fast_assign) {
            if (try self.tryFastDenseAssignAmend(base, selectors, func_or_value)) |fast| return fast;
        }

        if (selectors.len == 0) return try self.retainEscapedValue(base);

        const items = try self.materializeTopLevelItems(base);
        defer {
            for (items) |value| self.releaseValue(value);
            self.allocator.free(items);
        }

        var rhs_items: ?[]Value = null;
        defer if (rhs_items) |values| {
            for (values) |value| self.releaseValue(value);
            self.allocator.free(values);
        };

        const rhs_source = switch (mode) {
            .assign => func_or_value,
            .binary => arg,
            .unary => Value.fromBool(false),
        };
        const selector_is_scalar = selector.tag() == .int or selector.tag() == .bool;
        if (mode != .unary and rhs_source.tag() == .array) {
            const maybe = try self.tryMaterializeTopLevelItems(rhs_source);
            if (maybe) |values| rhs_items = values;
        }

        var idx: usize = 0;
        while (idx < selectors.len) : (idx += 1) {
            const target_idx = selectors[idx];
            const current = items[target_idx];
            const next = switch (mode) {
                .assign => if (rhs_items) |values|
                    if (!selector_is_scalar and values.len == selectors.len) try self.retainEscapedValue(values[idx]) else try self.retainEscapedValue(func_or_value)
                else
                    try self.retainEscapedValue(func_or_value),
                .unary => try self.applyValue(func_or_value, &[_]Value{current}),
                .binary => blk: {
                    const rhs = if (rhs_items) |values|
                        if (!selector_is_scalar and values.len == selectors.len) values[idx] else arg
                    else
                        arg;
                    break :blk try self.applyValue(func_or_value, &[_]Value{ current, rhs });
                },
            };
            self.releaseValue(items[target_idx]);
            items[target_idx] = next;
        }

        return try self.rebuildTopLevelItems(base, items);
    }

    fn collectSelectorIndices(self: *Session, base: Value, selector: Value) KError![]usize {
        return try self.collectSelectorIndicesForLen(try self.topLevelLen(base), selector);
    }

    fn collectSelectorIndicesForLen(self: *Session, top_len: usize, selector: Value) KError![]usize {
        var indices = std.ArrayList(usize).empty;
        defer indices.deinit(self.allocator);

        if (isAllAxisSelectorValue(selector)) {
            try indices.ensureTotalCapacity(self.allocator, top_len);
            for (0..top_len) |idx| try indices.append(self.allocator, idx);
            return try indices.toOwnedSlice(self.allocator);
        }

        switch (selector.tag()) {
            .int, .bool => {
                try indices.append(self.allocator, try normalizeIndex(scalarIntLikeValue(selector).?, top_len));
            },
            .array => {
                if (stringBytes(selector)) |bytes| {
                    try indices.ensureTotalCapacity(self.allocator, bytes.len);
                    for (bytes) |byte| try indices.append(self.allocator, try normalizeIndex(@intCast(byte), top_len));
                } else if (valueHostIntStructuralView(selector)) |view| switch (view) {
                    .dense => |dense| {
                        const len = hostIntArrayViewLen(dense);
                        try indices.ensureTotalCapacity(self.allocator, len);
                        for (0..len) |idx| {
                            try indices.append(self.allocator, try normalizeIndex(hostIntViewItem(dense, idx), top_len));
                        }
                    },
                    else => {
                        const len = hostIntDenseViewLen(view);
                        try indices.ensureTotalCapacity(self.allocator, len);
                        for (0..len) |idx| {
                            try indices.append(self.allocator, try normalizeIndex(try hostIntDenseViewItem(view, idx), top_len));
                        }
                    },
                } else return error.Type;
            },
            else => return error.Type,
        }

        return try indices.toOwnedSlice(self.allocator);
    }

    fn matrixCellValue(self: *Session, value: Value, row: usize, col: usize) KError!Value {
        const row_value = try self.applyArrayCall1Scalar(value, @intCast(row));
        defer self.releaseValue(row_value);
        return try self.applyArrayCall1Scalar(row_value, @intCast(col));
    }

    fn tryApplyNumericMatrixColumnAmend(self: *Session, base: Value, selector: Value, mode: ShallowAmendMode, func_or_value: Value, arg: Value) KError!?Value {
        const shape = valueNumericMatrixShape(base) orelse return null;
        const rows = shape.rows;
        const cols = shape.cols;
        const col_indices = self.collectSelectorIndicesForLen(cols, selector) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        defer self.allocator.free(col_indices);
        if (col_indices.len == 0) return try self.retainEscapedValue(base);

        const total = rows * cols;
        const items = try self.allocator.alloc(Value, total);
        defer self.allocator.free(items);
        var initialized: usize = 0;
        defer {
            for (items[0..initialized]) |value| self.releaseValue(value);
        }

        switch (valueNumericMode(base) orelse return null) {
            .int => for (0..total) |idx| {
                items[idx] = try self.intValue(try numericIntAt(base, idx));
                initialized += 1;
            },
            .float => for (0..total) |idx| {
                items[idx] = try self.floatValue(try numericFloatAt(base, idx));
                initialized += 1;
            },
        }

        const rhs_source = switch (mode) {
            .assign => func_or_value,
            .binary => arg,
            .unary => Value.fromBool(false),
        };
        const rhs_matrix_shape = if (mode != .unary) valueNumericMatrixShape(rhs_source) else null;
        const rhs_is_matrix = if (rhs_matrix_shape) |rhs_shape|
            rhs_shape.rows == rows and rhs_shape.cols == col_indices.len
        else
            false;

        for (0..rows) |row| {
            for (col_indices, 0..) |col, col_pos| {
                const flat_idx = row * cols + col;
                const current = items[flat_idx];
                var rhs_cell: ?Value = null;
                defer if (rhs_cell) |value| self.releaseValue(value);
                const rhs = if (rhs_is_matrix) blk: {
                    rhs_cell = try self.matrixCellValue(rhs_source, row, col_pos);
                    break :blk rhs_cell.?;
                } else rhs_source;

                const next = switch (mode) {
                    .assign => try self.retainEscapedValue(rhs),
                    .unary => try self.applyValue(func_or_value, &[_]Value{current}),
                    .binary => try self.applyValue(func_or_value, &[_]Value{ current, rhs }),
                };
                self.releaseValue(items[flat_idx]);
                items[flat_idx] = next;
            }
        }

        const rebuilt = try self.makeArrayFromValues(items);
        return try applyNonVectorNumericShapeToValue(self, rebuilt, numericShapeSnapshotMatrix(rows, cols));
    }

    fn topLevelLen(self: *Session, value: Value) KError!usize {
        _ = self;
        if (value.tag() != .array) return error.Type;
        if (stringSourceInfo(value)) |source| return source.bytes().len;
        if (value.arrayKind() == .host_keyed_store) {
            const store = value.asHostKeyedStore();
            return switch (store.layout) {
                .dict => keyedStoreNameCount(store),
                .table => store.row_count,
            };
        }
        if (derivedSequenceLen(value)) |len| return len;
        return error.Type;
    }

    fn materializeTopLevelItems(self: *Session, value: Value) KError![]Value {
        const len = try self.topLevelLen(value);
        const items = try self.allocator.alloc(Value, len);
        errdefer self.allocator.free(items);
        var initialized: usize = 0;
        errdefer {
            for (items[0..initialized]) |item| self.releaseValue(item);
        }

        if (stringSourceInfo(value)) |source| {
            for (0..len) |idx| {
                items[idx] = try self.stringIndexScalarValue(source, @intCast(idx));
                initialized += 1;
            }
        } else if (value.arrayKind() == .host_keyed_store) {
            const store = value.asHostKeyedStore();
            switch (store.layout) {
                .dict => for (0..len) |idx| {
                    items[idx] = try self.keyedStoreValueAt(store, idx);
                    initialized += 1;
                },
                .table => for (0..len) |idx| {
                    items[idx] = try self.tableRowDictValue(store, idx);
                    initialized += 1;
                },
            }
        } else {
            for (0..len) |idx| {
                items[idx] = try self.derivedSequenceItemValue(value, idx);
                initialized += 1;
            }
        }
        return items;
    }

    fn tryMaterializeTopLevelItems(self: *Session, value: Value) KError!?[]Value {
        if (value.tag() != .array) return null;
        return try self.materializeTopLevelItems(value);
    }

    fn rebuildTopLevelItems(self: *Session, base: Value, items: []const Value) KError!Value {
        if (stringSourceInfo(base) != null) {
            var text_values = std.ArrayList(Value).empty;
            defer {
                for (text_values.items) |value| self.releaseValue(value);
                text_values.deinit(self.allocator);
            }
            try text_values.ensureTotalCapacity(self.allocator, items.len);

            var all_text = true;
            for (items) |item| {
                if (stringBytes(item) != null) {
                    try text_values.append(self.allocator, try self.retainEscapedValue(item));
                } else if (item.tag() == .array and item.arrayKind() == .host_string_list) {
                    try text_values.append(self.allocator, try self.joinHostStringList(item.asHostStringList(), &.{}));
                } else {
                    all_text = false;
                    break;
                }
            }

            if (all_text) {
                var all_unit_strings = true;
                for (text_values.items) |item| {
                    const bytes = stringBytes(item) orelse return error.Internal;
                    if (bytes.len != 1) {
                        all_unit_strings = false;
                        break;
                    }
                }
                if (all_unit_strings) {
                    const out = try self.allocator.alloc(u8, text_values.items.len);
                    defer self.allocator.free(out);
                    for (text_values.items, 0..) |item, idx| out[idx] = stringBytes(item).?[0];
                    return try self.managedHostString(out);
                }
                return try self.createManagedHostStringList(text_values.items);
            }
        }

        if (base.tag() == .array and base.arrayKind() == .host_boxed_array) {
            if (scalarNumericItemsHaveSingleClass(items)) return try self.makeArrayFromValues(items);
            return try self.createManagedHostBoxedArrayWithPrototype(items, base.asHostBoxedArray().prototype);
        }

        if (stringSourceInfo(base) != null) {
            var all_unit_strings = true;
            for (items) |item| {
                const bytes = stringBytes(item) orelse {
                    all_unit_strings = false;
                    break;
                };
                if (bytes.len != 1) {
                    all_unit_strings = false;
                    break;
                }
            }
            if (all_unit_strings) {
                const out = try self.allocator.alloc(u8, items.len);
                defer self.allocator.free(out);
                for (items, 0..) |item, idx| out[idx] = stringBytes(item).?[0];
                return try self.managedHostString(out);
            }
        }

        if (base.tag() == .array and base.arrayKind() == .host_string_list) {
            var all_text = true;
            for (items) |item| {
                if (stringBytes(item) == null and symbolBytes(item) == null) {
                    all_text = false;
                    break;
                }
            }
            if (all_text) return try self.createManagedHostTextListFromValues(items);
        }

        if (base.tag() == .array and base.arrayKind() == .host_symbol_list) {
            var slices = std.ArrayList([]const u8).empty;
            defer slices.deinit(self.allocator);
            try slices.ensureTotalCapacity(self.allocator, items.len);
            for (items) |item| {
                const bytes = symbolBytes(item) orelse break;
                try slices.append(self.allocator, bytes);
            }
            if (slices.items.len == items.len) return try self.createManagedHostSymbolListFromSlices(slices.items);
        }

        const rebuilt = try self.makeArrayFromValues(items);
        if (try self.promoteRenderableMatrixValue(rebuilt)) |promoted| {
            if (promoted.raw != rebuilt.raw and isManagedValue(rebuilt)) self.releaseValue(rebuilt);
            return promoted;
        }
        if (valueNumericMatrixShape(base)) |shape| {
            return try applyNonVectorNumericShapeToValue(self, rebuilt, numericShapeSnapshotMatrix(shape.rows, shape.cols));
        }
        return rebuilt;
    }

    fn applyDot(self: *Session, left: Value, right: Value) KError!Value {
        const items = try self.materializeSequenceItems(right);
        defer self.releaseArgs(items);
        if (items.len > max_direct_apply_args) return error.Unsupported;
        return try self.applyValue(left, items);
    }

    fn applyProjectionClosure(self: *Session, info: ProjectionInfo, args: []const Value) KError!Value {
        var profile_scope = self.beginSamplingProfileScope(.apply_projection);
        defer profile_scope.end();
        if (self.debugDetailedProbeActive()) self.debug.apply_projection_count += 1;
        if (try self.tryApplyDirectBuiltinProjection(info, args)) |value| return value;
        const full_slot_values = try self.scratch_arena.allocator().alloc(Value, info.slot_count);
        var next_hole_mask: u64 = 0;
        var arg_idx: usize = 0;

        for (0..info.slot_count) |slot_idx| {
            if (((info.hole_mask >> @intCast(slot_idx)) & 1) != 0) {
                if (arg_idx < args.len) {
                    full_slot_values[slot_idx] = args[arg_idx];
                    arg_idx += 1;
                } else {
                    full_slot_values[slot_idx] = Value.fromBool(false);
                    next_hole_mask |= (@as(u64, 1) << @intCast(slot_idx));
                }
            } else {
                full_slot_values[slot_idx] = info.slot_values[slot_idx];
            }
        }

        if (next_hole_mask != 0) {
            return try self.allocManagedProjectionClosure(
                info.callee,
                std.math.cast(u8, info.slot_count) orelse return error.Unsupported,
                next_hole_mask,
                full_slot_values,
            );
        }

        const extra_count = args.len - arg_idx;
        const apply_args = try self.scratch_arena.allocator().alloc(Value, info.slot_count + extra_count);
        @memcpy(apply_args[0..info.slot_count], full_slot_values);
        for (args[arg_idx..], 0..) |arg, idx| apply_args[info.slot_count + idx] = arg;
        return try self.applyValue(info.callee, apply_args);
    }

    fn tryApplyDirectBuiltinProjection(self: *Session, info: ProjectionInfo, args: []const Value) KError!?Value {
        if (info.callee.tag() != .builtin) return null;
        if (info.slot_count == 0 or info.slot_count > max_direct_apply_args) return null;
        const hole_count: usize = @intCast(@popCount(info.hole_mask));
        if (args.len != hole_count) return null;

        const op = info.callee.asBuiltin();
        if (!builtinUsesGenericArityDispatch(op)) return null;

        var apply_args: [max_direct_apply_args]Value = undefined;
        var arg_idx: usize = 0;
        for (0..info.slot_count) |slot_idx| {
            if (((info.hole_mask >> @intCast(slot_idx)) & 1) != 0) {
                apply_args[slot_idx] = args[arg_idx];
                arg_idx += 1;
            } else {
                apply_args[slot_idx] = info.slot_values[slot_idx];
            }
        }

        return switch (info.slot_count) {
            1 => try self.applyMonad(op, apply_args[0]),
            2 => try self.applyDyad(dyadicBuiltinForGenericCall(op), apply_args[0], apply_args[1]),
            3 => if (op == .unique or op == .find) try self.insertValue(apply_args[0], apply_args[1], apply_args[2]) else error.Arity,
            else => error.Arity,
        };
    }

    fn applyMonadicBuiltinClosure(self: *Session, op: BuiltinId, args: []const Value) KError!Value {
        return switch (args.len) {
            0 => error.Arity,
            1 => try self.applyMonad(op, args[0]),
            else => error.Type,
        };
    }

    fn applyCompositionClosure(self: *Session, info: CompositionInfo, args: []const Value) KError!Value {
        const inner_result = try self.applyValue(info.inner, args);
        defer self.releaseValue(inner_result);
        return try self.applyValue(info.outer, &[_]Value{inner_result});
    }

    fn applyDerivedClosure(self: *Session, closure: *const Closure, args: []const Value) KError!?Value {
        if (!closureMayUseDerivedApply(closure)) return null;
        if (self.debugDetailedProbeActive()) self.debug.apply_derived_closure_count += 1;
        if (try self.monadicBuiltinFromClosure(closure)) |op| {
            return try self.applyMonadicBuiltinClosure(op, args);
        }
        if (try self.projectionInfoFromClosure(closure)) |info| {
            return try self.applyProjectionClosure(info, args);
        }
        if (try self.innerProductInfoFromClosure(closure)) |info| {
            return try self.applyInnerProductClosure(info, args);
        }
        if (try self.compositionInfoFromClosure(closure)) |info| {
            return try self.applyCompositionClosure(info, args);
        }
        if (closureIsBareAdverb(closure)) return error.Type;
        const kind = closureDerivedKind(closure) orelse return null;
        return try self.applyDerivedKind(kind, closure.captures, args);
    }

    fn builtinSupportsMonad(op: BuiltinId) bool {
        if (!builtinAvailable(op)) return false;
        return switch (op) {
            .identity,
            .add,
            .sub,
            .mul,
            .div,
            .exp,
            .log,
            .sin,
            .cos,
            .tanh,
            .sigmoid,
            .iota,
            .minimum,
            .maximum,
            .reverse,
            .less,
            .more,
            .grade_up,
            .grade_down,
            .not,
            .count,
            .floor,
            .null_fill_without,
            .equal,
            .stringify,
            .bytes,
            .utf8,
            .char,
            .type_of,
            .unique,
            .eval_string,
            .open,
            .close,
            .read,
            .flush,
            .run,
            .stat,
            .load,
            .sql,
            .exec,
            .rotcacheview,
            .layernorm,
            .gelu,
            .geluapprox,
            .softmax,
            => true,
            .concat, .take, .drop, .reshape, .cast, .contains, .split, .join, .find, .grad, .valuegrad, .prng, .write, .save, .register, .rotcache, .rotcacheupdate, .rope, .ropeflat, .ropecisflat, .rmsnorm, .mlpdense, .conv2d, .convtranspose2d, .upsamplenearest2d, .groupnorm, .pow, .sdpa, .sam3boxrpb, .sdpamask, .sdpaflat, .apply => false,
        };
    }

    fn builtinSupportsDyad(op: BuiltinId) bool {
        if (!builtinAvailable(op)) return false;
        return switch (op) {
            .identity,
            .add,
            .sub,
            .mul,
            .div,
            .pow,
            .iota,
            .minimum,
            .maximum,
            .less,
            .more,
            .not,
            .concat,
            .count,
            .floor,
            .null_fill_without,
            .equal,
            .stringify,
            .contains,
            .split,
            .join,
            .unique,
            .open,
            .write,
            .run,
            .load,
            .save,
            .read,
            .sql,
            .exec,
            .register,
            .rotcache,
            .rotcacheupdate,
            .apply,
            => true,
            .exp, .log, .sin, .cos, .tanh, .sigmoid, .reverse, .grade_up, .grade_down, .take, .drop, .reshape, .cast, .find, .bytes, .utf8, .char, .type_of, .eval_string, .close, .flush, .stat, .grad, .valuegrad, .prng, .rotcacheview, .rope, .ropeflat, .ropecisflat, .rmsnorm, .layernorm, .gelu, .geluapprox, .mlpdense, .conv2d, .convtranspose2d, .upsamplenearest2d, .groupnorm, .softmax, .sdpa, .sam3boxrpb, .sdpamask, .sdpaflat => false,
        };
    }

    fn convergeUsesMonadicBase(base: Value) bool {
        return switch (base.tag()) {
            .builtin => builtinSupportsMonad(base.asBuiltin()) and !builtinSupportsDyad(base.asBuiltin()),
            .closure => blk: {
                const closure = base.asClosure();
                if (closureIsMonadicBuiltin(closure)) break :blk true;
                if (projectionHoleCount(closure)) |hole_count| break :blk hole_count == 1;
                if (closureDerivedKind(closure)) |kind| {
                    break :blk derivedClosureSupportsMonadicScanBase(kind, closure);
                }
                break :blk closure.code.arity == 1;
            },
            .array => true,
            else => false,
        };
    }

    fn derivedClosureSupportsMonadicScanBase(kind: DerivedVerbKind, closure: *const Closure) bool {
        return switch (kind) {
            .each_prior => closure.captures.len == 1 and eachPriorRollingBaseSupportsDyad(closure.captures[0]),
            .fold => closure.captures.len == 1,
            .each, .scan, .each_right, .each_left, .grad, .valuegrad => false,
        };
    }

    fn eachPriorRollingBaseSupportsDyad(base: Value) bool {
        return switch (base.tag()) {
            .builtin => builtinSupportsDyad(base.asBuiltin()),
            .closure => blk: {
                const closure = base.asClosure();
                if (projectionHoleCount(closure)) |hole_count| break :blk hole_count == 2;
                if (closureDerivedKind(closure) != null) break :blk false;
                break :blk closure.code.arity == 2;
            },
            else => false,
        };
    }

    fn projectionHoleCount(closure: *const Closure) ?u8 {
        if (!closureIsProjection(closure)) return null;
        if (closure.captures.len < 3) return null;
        const slot_count_i64 = scalarIntLikeValue(closure.captures[1]) orelse return null;
        const hole_mask_i64 = scalarIntLikeValue(closure.captures[2]) orelse return null;
        if (slot_count_i64 < 0 or slot_count_i64 > 63 or hole_mask_i64 < 0) return null;
        const slot_count: u6 = @intCast(slot_count_i64);
        const hole_mask: u64 = @intCast(hole_mask_i64);
        if ((hole_mask >> slot_count) != 0) return null;
        if (closure.captures.len != 3 + @as(usize, slot_count)) return null;
        return @intCast(@popCount(hole_mask));
    }

    fn valueIsCallable(value: Value) bool {
        return switch (value.tag()) {
            .builtin, .closure, .array => true,
            else => false,
        };
    }

    fn eachPriorUsesMonadicBase(base: Value) bool {
        return switch (base.tag()) {
            .builtin => builtinSupportsMonad(base.asBuiltin()) and !builtinSupportsDyad(base.asBuiltin()),
            .closure => blk: {
                const closure = base.asClosure();
                if (closureIsMonadicBuiltin(closure)) break :blk true;
                if (closureDerivedKind(closure)) |kind| {
                    break :blk switch (kind) {
                        .each => closure.captures.len == 1 and eachPriorUsesMonadicBase(closure.captures[0]),
                        .fold, .scan, .each_right, .each_left, .each_prior, .grad, .valuegrad => true,
                    };
                }
                break :blk closure.code.arity == 1;
            },
            else => false,
        };
    }

    fn eachPriorImplicitSeedValue(self: *Session, base: Value, vector: Value) KError!Value {
        return switch (base.tag()) {
            .builtin => switch (base.asBuiltin()) {
                .add, .sub => try self.intValue(0),
                .mul, .div => try self.intValue(1),
                .minimum, .maximum => blk: {
                    if (vector.tag() == .array and vector.arrayKind() == .host_keyed_store) {
                        const store = vector.asHostKeyedStore();
                        if (store.layout == .dict) break :blk try self.keyedStoreValueAt(store, 0);
                    }
                    break :blk try self.eachSequenceItemValue(vector, 0);
                },
                .concat => try self.createManagedHostBoxedArray(&.{}),
                else => try self.floatValue(std.math.nan(f64)),
            },
            else => try self.eachSequenceItemValue(vector, 0),
        };
    }

    fn applyDerivedKind(self: *Session, kind: DerivedVerbKind, captures: []const Value, args: []const Value) KError!Value {
        if (try self.tryApplyStringDerivedKind(kind, captures, args)) |value| return value;
        if (try self.tryApplyNumericEncodeDecodeDerivedKind(kind, captures, args)) |value| return value;
        return switch (kind) {
            .each => blk: {
                if (captures.len != 1) return error.Internal;
                break :blk try self.applyEachDerived(captures[0], args);
            },
            .fold => blk: {
                if (captures.len != 1) return error.Internal;
                break :blk if (args.len == 1 and convergeUsesMonadicBase(captures[0]))
                    try self.applyConvergeDerived(captures[0], args[0], false)
                else
                    try self.applyFoldDerived(captures[0], args, false);
            },
            .scan => blk: {
                if (captures.len != 1) return error.Internal;
                break :blk if (args.len == 1 and convergeUsesMonadicBase(captures[0]))
                    try self.applyConvergeDerived(captures[0], args[0], true)
                else
                    try self.applyFoldDerived(captures[0], args, true);
            },
            .each_right => blk: {
                if (captures.len != 1) return error.Internal;
                break :blk try self.applyEachRightDerived(captures[0], args);
            },
            .each_left => blk: {
                if (captures.len != 1) return error.Internal;
                break :blk try self.applyEachLeftDerived(captures[0], args);
            },
            .each_prior => blk: {
                if (captures.len != 1) return error.Internal;
                break :blk try self.applyEachPriorDerived(captures[0], args);
            },
            .grad => try self.applyAutogradDerived(.grad, captures, args),
            .valuegrad => try self.applyAutogradDerived(.valuegrad, captures, args),
        };
    }

    fn tryApplyStringDerivedKind(self: *Session, kind: DerivedVerbKind, captures: []const Value, args: []const Value) KError!?Value {
        if (captures.len != 1) return null;
        if (captures[0].tag() == .builtin and captures[0].asBuiltin() == .concat) {
            return switch (kind) {
                .fold => try self.tryApplyStringJoinDerived(args),
                .scan => try self.tryApplyStringSplitDerived(args),
                else => null,
            };
        }
        if (stringDelimiterBytes(captures[0]) != null) {
            return switch (kind) {
                .fold => if (args.len == 1 and isJoinableStringSequence(args[0]))
                    try self.joinValues(captures[0], args[0])
                else
                    null,
                .scan => if (args.len == 1 and stringBytes(args[0]) != null)
                    try self.splitValues(captures[0], args[0])
                else
                    null,
                else => null,
            };
        }
        return switch (kind) {
            else => null,
        };
    }

    fn tryApplyStringJoinDerived(self: *Session, args: []const Value) KError!?Value {
        if (args.len == 1) {
            if (!isJoinableStringSequence(args[0])) return null;
            const empty = try self.frozenHostString(&.{});
            defer self.releaseValue(empty);
            return try self.joinValues(empty, args[0]);
        }
        if (args.len == 2 and stringDelimiterBytes(args[0]) != null and isJoinableStringSequence(args[1])) {
            return try self.joinValues(args[0], args[1]);
        }
        return null;
    }

    fn tryApplyNumericEncodeDecodeDerivedKind(self: *Session, kind: DerivedVerbKind, captures: []const Value, args: []const Value) KError!?Value {
        if (captures.len != 1 or args.len != 1) return null;
        if (valueNumericMode(captures[0]) != .int) return null;
        return switch (kind) {
            .fold => try self.decodeNumericValues(captures[0], args[0]),
            .scan => try self.encodeNumericValues(captures[0], args[0]),
            else => null,
        };
    }

    fn tryApplyStringSplitDerived(self: *Session, args: []const Value) KError!?Value {
        if (args.len == 2 and stringDelimiterBytes(args[0]) != null and stringBytes(args[1]) != null) {
            return try self.splitValues(args[0], args[1]);
        }
        return null;
    }

    fn valuesExactlyEqual(self: *Session, left: Value, right: Value) KError!bool {
        return try self.valueMatchEqual(left, right);
    }

    fn appendCollectedIterateValue(self: *Session, results: *std.ArrayList(Value), value: Value) KError!void {
        const snapshot = self.freezeConstantValue(value) catch |err| switch (err) {
            error.Unsupported => try self.retainEscapedValue(value),
            else => return err,
        };
        try results.append(self.allocator, snapshot);
    }

    fn applyConvergeDerived(self: *Session, base: Value, input: Value, collect: bool) KError!Value {
        const initial = self.shareValue(input);
        defer self.releaseValue(initial);

        var current = self.shareValue(input);
        errdefer self.releaseValue(current);

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }

        if (collect) try self.appendCollectedIterateValue(&results, current);

        while (true) {
            const next = try self.applyDerivedBase(base, &[_]Value{current});
            const converged = (try self.valuesExactlyEqual(current, next)) or (try self.valuesExactlyEqual(initial, next));
            if (converged) {
                if (!collect) {
                    self.releaseValue(next);
                    return current;
                }
                self.releaseValue(current);
                self.releaseValue(next);
                return try self.createManagedArrayLikeFromValues(results.items);
            }
            self.releaseValue(current);
            current = next;
            if (collect) try self.appendCollectedIterateValue(&results, current);
        }
    }

    fn tryApplyControlledFoldDerived(self: *Session, base: Value, args: []const Value, collect: bool) KError!?Value {
        if (args.len < 2) return null;
        const base_arity = (try self.callableProjectionArity(base)) orelse return null;
        if (!(base_arity < 2 or (args.len > base_arity and args.len - base_arity == 1))) return null;

        const seeds = args[1..];
        if (seeds.len == 0 or seeds.len > max_direct_apply_args) return error.Unsupported;
        if (scalarIntLikeValue(args[0])) |count| {
            return try self.applyCountedOverDerived(base, count, seeds, collect);
        }
        if (valueIsCallable(args[0])) {
            return try self.applyWhileOverDerived(base, args[0], seeds, collect);
        }
        return null;
    }

    fn applyDerivedBaseToControlledWindow(self: *Session, base: Value, window: []const Value) KError!Value {
        var step_args: [max_direct_apply_args]Value = undefined;
        var retained_count: usize = 0;
        errdefer for (step_args[0..retained_count]) |value| self.releaseValue(value);
        for (window, 0..) |value, idx| {
            step_args[idx] = try self.retainEscapedValue(value);
            retained_count += 1;
        }
        defer for (step_args[0..retained_count]) |value| self.releaseValue(value);
        return try self.applyDerivedBase(base, step_args[0..window.len]);
    }

    fn tryApplyCountedUnaryPlainClosure(self: *Session, base: Value, count: usize, seed: Value) KError!?Value {
        if (base.tag() != .closure) return null;
        const closure = base.asClosure();
        const code = codeForPlainClosure(closure, 1) orelse return null;
        if (code.slot_count > max_code_frame_slots) return null;

        var current = self.shareValue(seed);
        var current_live = true;
        errdefer if (current_live) self.releaseValue(current);

        var idx: usize = 0;
        while (idx < count) : (idx += 1) {
            var args = [_]Value{current};
            current_live = false;
            const next = try self.runCodeOwned(code, args[0..]);
            current = next;
            current_live = true;
        }

        current_live = false;
        return current;
    }

    fn createControlledScanResult(self: *Session, values: []const Value) KError!Value {
        for (values) |value| {
            if (value.tag() == .array) return try self.createManagedHostBoxedArray(values);
        }
        return try self.createManagedArrayLikeFromValues(values);
    }

    fn copyControlledScanResultValue(self: *Session, value: Value) KError!Value {
        if (value.tag() == .array and value.arrayKind() != .host_keyed_store) {
            if (derivedSequenceLen(value)) |len| {
                var items = std.ArrayList(Value).empty;
                defer {
                    for (items.items) |item| self.releaseValue(item);
                    items.deinit(self.allocator);
                }
                try items.ensureTotalCapacity(self.allocator, len);
                for (0..len) |idx| try items.append(self.allocator, try self.derivedSequenceItemValue(value, idx));
                return try self.createManagedArrayLikeFromValues(items.items);
            }
        }
        return try self.retainEscapedValue(value);
    }

    fn appendControlledScanResult(self: *Session, results: *std.ArrayList(Value), value: Value) KError!void {
        const snapshot = try self.copyControlledScanResultValue(value);
        errdefer self.releaseValue(snapshot);
        try results.append(self.allocator, snapshot);
    }

    fn applyCountedOverDerived(self: *Session, base: Value, raw_count: i64, seeds: []const Value, collect: bool) KError!Value {
        const count: usize = if (raw_count < 0) blk: {
            if (seeds.len != 1) return error.Type;
            break :blk 0;
        } else std.math.cast(usize, raw_count) orelse return error.Unsupported;
        if (!collect and seeds.len == 1) {
            if (try self.tryApplyCountedUnaryPlainClosure(base, count, seeds[0])) |value| return value;
        }
        const result_len = std.math.add(usize, count, 1) catch return error.Unsupported;

        var window: [max_direct_apply_args]Value = undefined;
        for (seeds, 0..) |seed, idx| window[idx] = self.shareValue(seed);
        defer for (window[0..seeds.len]) |value| self.releaseValue(value);

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }

        if (collect) {
            try results.ensureTotalCapacity(self.allocator, result_len);
        }

        if (count < seeds.len) {
            if (collect) {
                for (window[0..result_len]) |value| try self.appendControlledScanResult(&results, value);
                return try self.createControlledScanResult(results.items);
            }
            return self.shareValue(window[count]);
        }

        for (seeds.len..result_len) |_| {
            const next = try self.applyDerivedBaseToControlledWindow(base, window[0..seeds.len]);
            if (collect) try self.appendControlledScanResult(&results, window[0]);
            self.releaseValue(window[0]);
            if (seeds.len > 1) std.mem.copyForwards(Value, window[0 .. seeds.len - 1], window[1..seeds.len]);
            window[seeds.len - 1] = next;
        }

        if (collect) {
            for (window[0..seeds.len]) |value| try self.appendControlledScanResult(&results, value);
            return try self.createControlledScanResult(results.items);
        }
        return self.shareValue(window[seeds.len - 1]);
    }

    fn applyWhileOverDerived(self: *Session, base: Value, predicate: Value, seeds: []const Value, collect: bool) KError!Value {
        var window: [max_direct_apply_args]Value = undefined;
        for (seeds, 0..) |seed, idx| window[idx] = self.shareValue(seed);
        defer for (window[0..seeds.len]) |value| self.releaseValue(value);

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }

        if (collect) try results.ensureTotalCapacity(self.allocator, seeds.len);

        while (true) {
            const predicate_arg = try self.retainEscapedValue(window[seeds.len - 1]);
            defer self.releaseValue(predicate_arg);
            const condition = try self.applyDerivedBase(predicate, &[_]Value{predicate_arg});
            const keep_going = branchTruthValue(condition) orelse {
                self.releaseValue(condition);
                return error.Type;
            };
            self.releaseValue(condition);
            if (!keep_going) break;

            const next = try self.applyDerivedBaseToControlledWindow(base, window[0..seeds.len]);
            if (collect) try self.appendControlledScanResult(&results, window[0]);
            self.releaseValue(window[0]);
            if (seeds.len > 1) std.mem.copyForwards(Value, window[0 .. seeds.len - 1], window[1..seeds.len]);
            window[seeds.len - 1] = next;
        }

        if (collect) {
            for (window[0..seeds.len]) |value| try self.appendControlledScanResult(&results, value);
            return try self.createControlledScanResult(results.items);
        }
        return self.shareValue(window[seeds.len - 1]);
    }

    fn isBuiltinFoldClosure(value: Value) bool {
        if (value.tag() != .closure) return false;
        const closure = value.asClosure();
        return closure.header.owner == .frozen and
            closureDerivedKind(closure) == .fold and
            closure.captures.len == 1 and
            closure.captures[0].tag() == .builtin;
    }

    fn shouldBoxEachFoldScalarResults(base: Value, results: []const Value) bool {
        if (!isBuiltinFoldClosure(base)) return false;
        return scalarNumericItemsHaveMixedClass(results);
    }

    fn applyEachDerived(self: *Session, base: Value, args: []const Value) KError!Value {
        var profile_scope = self.beginSamplingProfileScope(.apply_each);
        defer profile_scope.end();
        if (args.len == 1 and numericVectorLen(base) != null) return try self.binValues(base, args[0]);
        if (args.len == 1 and args[0].tag() == .array and args[0].arrayKind() == .host_keyed_store) {
            const store = args[0].asHostKeyedStore();
            if (store.layout == .dict) return try self.applyEachDictValues(base, store);
        }
        if (try self.tryFastTransposeEachDerived(base, args)) |value| return value;
        if (try self.tryFastBatchedMatmulEachDerived(base, args)) |value| return value;
        if (try self.tryFastUnaryLiftedEachDerived(base, args)) |value| return value;
        if (try self.tryFastBackendMatrixRowFoldEachDerived(base, args)) |value| return value;
        if (try self.tryFastHostMatrixRowAddScanEach(base, args)) |value| return value;
        if (try self.tryFastHostMatrixRowMinMaxScanEach(base, args)) |value| return value;
        if (try self.tryFastNumericUnaryEachDerived(base, args)) |value| return value;
        if (try self.tryFastNumericClosureEachDerived(base, args)) |value| return value;
        if (try self.tryFastDenseEachDerived(base, args)) |value| return value;
        if (try self.tryFastCountEachDerived(base, args)) |value| return value;
        var len: ?usize = null;
        var saw_array = false;
        for (args) |arg| {
            if (eachSequenceLen(arg)) |arg_len| {
                saw_array = true;
                if (len) |existing| {
                    if (existing != arg_len) return error.Type;
                } else {
                    len = arg_len;
                }
            }
        }
        if (!saw_array) return try self.applyDerivedBase(base, args);
        if (comptime enable_probe_instrumentation) self.debug.apply_each_generic_count += 1;

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }

        const out_len = len.?;
        try results.ensureTotalCapacity(self.allocator, out_len);
        for (0..out_len) |idx| {
            var step_args_buf: [8]Value = undefined;
            if (args.len > step_args_buf.len) return error.Unsupported;
            for (args, 0..) |arg, arg_idx| {
                step_args_buf[arg_idx] = if (eachSequenceLen(arg) != null) try self.eachSequenceItemValue(arg, idx) else arg;
            }
            const result = blk: {
                defer self.releaseEachStepArgs(args, step_args_buf[0..args.len], 0);
                break :blk try self.applyDerivedBase(base, step_args_buf[0..args.len]);
            };
            try results.append(self.allocator, result);
        }
        if (shouldBoxEachFoldScalarResults(base, results.items)) return try self.createManagedHostBoxedArray(results.items);
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn tryFastCountEachDerived(self: *Session, base: Value, args: []const Value) KError!?Value {
        if (args.len != 1 or base.tag() != .builtin or base.asBuiltin() != .count) return null;
        const value = args[0];
        if (stringBytes(value) != null) return try self.countValue(value);
        if (valueNumericHandle(value)) |handle| {
            if (handle.rank == 0) return null;
            if (handle.shape[0] < 0) return error.Internal;
            const out_len: usize = @intCast(handle.shape[0]);
            const item_count = if (handle.rank == 1) @as(i64, 1) else try countDimAsI64(handle.shape[1]);
            const out = try self.allocator.alloc(i64, out_len);
            defer self.allocator.free(out);
            @memset(out, item_count);
            return try self.createManagedHostIntArray(out);
        }

        const out_len = derivedSequenceLen(value) orelse return null;
        const out = try self.allocator.alloc(i64, out_len);
        defer self.allocator.free(out);

        if (value.tag() == .array and value.arraySubkind() == .host_boxed_array) {
            const array = value.asHostBoxedArray();
            for (array.items[0..array.len()], 0..) |item, idx| {
                out[idx] = try self.countValueAsI64(item);
            }
            return try self.createManagedHostIntArray(out);
        }

        for (0..out_len) |idx| {
            const item = try self.derivedSequenceItemValue(value, idx);
            out[idx] = self.countValueAsI64(item) catch |err| {
                self.releaseValue(item);
                return err;
            };
            self.releaseValue(item);
        }
        return try self.createManagedHostIntArray(out);
    }

    fn tryFastTransposeEachDerived(self: *Session, base: Value, args: []const Value) KError!?Value {
        if (args.len != 1 or base.tag() != .builtin or base.asBuiltin() != .add) return null;
        const handle = shapedNumericHandle(args[0]) orelse return null;
        if (handle.rank < 3 or valueNumericMode(args[0]) == null) return null;
        return try self.transposeDenseNumericValueSwapAxes(args[0], handle, 1, 2);
    }

    fn tryFastBatchedMatmulEachDerived(self: *Session, base: Value, args: []const Value) KError!?Value {
        if (args.len != 2 or base.tag() != .closure) return null;
        const closure = base.asClosure();
        if (try self.closureIsRank3BatchedMatmulBase(closure)) {
            return try self.applyBatchedMatmulValues(args[0], args[1]);
        }
        if (try self.closureIsNestedBatchedMatmulBase(closure)) {
            const shape = (try leadingBatchedMatmulShapeForValues(args[0], args[1])) orelse return null;
            return try self.applyLeadingBatchedMatmulValues(args[0], args[1], shape);
        }
        return null;
    }

    fn closureIsRank3BatchedMatmulBase(self: *Session, closure: *const Closure) KError!bool {
        if (try self.innerProductInfoFromClosure(closure)) |info| {
            if (info.reduce == .add and info.map == .mul) {
                return true;
            }
        }
        if (closureDerivedKind(closure) != .each_left or closure.captures.len != 1) return false;
        const inner = closure.captures[0];
        if (inner.tag() != .closure) return false;
        const info = (try self.innerProductInfoFromClosure(inner.asClosure())) orelse return false;
        return info.reduce == .add and info.map == .mul;
    }

    fn closureIsNestedBatchedMatmulBase(self: *Session, closure: *const Closure) KError!bool {
        if (closureDerivedKind(closure) != .each or closure.captures.len != 1) return false;
        const inner = closure.captures[0];
        if (inner.tag() != .closure) return false;
        const inner_closure = inner.asClosure();
        return (try self.closureIsRank3BatchedMatmulBase(inner_closure)) or
            (try self.closureIsNestedBatchedMatmulBase(inner_closure));
    }

    fn tryFastBackendMatrixRowFoldEachDerived(self: *Session, base: Value, args: []const Value) KError!?Value {
        return runtime_backend_exec.tryFastBackendMatrixRowFoldEachDerived(backend_exec_api, self, base, args);
    }

    fn eachScanMinMaxBuiltin(base: Value) ?BuiltinId {
        if (isDerivedBuiltinClosure(base, .scan, .minimum)) return .minimum;
        if (isDerivedBuiltinClosure(base, .scan, .maximum)) return .maximum;
        return null;
    }

    fn fastHostMatrixRowAddScan(self: *Session, matrix: Value, shape: NumericMatrixShape, view: HostDenseView) KError!?Value {
        const len = shape.rows * shape.cols;
        return switch (view) {
            .int_array => |items| blk: {
                const out = try self.allocator.alloc(i64, len);
                defer self.allocator.free(out);
                try fillRowAddScanInt(out, items, shape.rows, shape.cols);
                const result = try self.createManagedHostIntArray(out);
                break :blk try applyNonVectorNumericShapeToValue(self, result, valueNonVectorNumericShape(matrix));
            },
            .float_array => |items| blk: {
                if (hostFloatDenseViewStorageKind(items) == .float32) {
                    const plan = try self.planHostFloat32UnaryOutput(matrix, len, true);
                    try fillRowAddScanFloat32(plan.output.items, items, shape.rows, shape.cols);
                    break :blk try self.finishHostFloat32Output(plan, 0);
                }
                const out = try self.allocator.alloc(f64, len);
                defer self.allocator.free(out);
                try fillRowAddScanFloat(out, items, shape.rows, shape.cols);
                const result = try self.createManagedHostFloatArray(out);
                break :blk try applyNonVectorNumericShapeToValue(self, result, valueNonVectorNumericShape(matrix));
            },
            else => null,
        };
    }

    fn tryFastHostMatrixRowAddScanEach(self: *Session, base: Value, args: []const Value) KError!?Value {
        if (args.len != 1) return null;
        if (self.dense_backend_override == .mlx) return null;
        if (!isDerivedBuiltinClosure(base, .scan, .add)) return null;
        const matrix = args[0];
        const shape = valueNumericMatrixShape(matrix) orelse return null;
        if (shape.rows == 0 or shape.cols == 0) return null;
        if (shape.cols == 1) return self.shareValue(matrix);
        const view = hostDenseView(self, matrix) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        if (self.debugDetailedProbeActive()) self.debug.apply_each_fast_dense_count += 1;
        return try self.fastHostMatrixRowAddScan(matrix, shape, view);
    }

    fn fastHostMatrixRowBitMinMaxScan(self: *Session, matrix: Value, shape: NumericMatrixShape, bits: HostBitSlice, op: BuiltinId) KError!Value {
        const out = try self.allocHostBitArrayUninitialized(.managed, bits.len);
        const metadata = fillRowBitMinMaxScan(out.words, bits, op, shape.rows, shape.cols);
        const value = try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
        return try applyNonVectorNumericShapeToValue(self, value, valueNonVectorNumericShape(matrix));
    }

    fn fastHostMatrixRowMinMaxScanInt(self: *Session, matrix: Value, shape: NumericMatrixShape, view: HostIntDenseView, op: BuiltinId) KError!Value {
        const flags = hostIntDenseValueFlags(matrix, view);
        if (minMaxScanCanReturnInput(op, flags)) return self.shareValue(matrix);
        const input_kind = hostIntDenseViewKind(view);
        var plan = try self.planHostIntUnaryOutput(matrix, input_kind, input_kind, shape.rows * shape.cols, true, true);
        try fillRowMinMaxScanInt(&plan.output, view, op, shape.rows, shape.cols);
        return try self.finishHostIntOutput(plan, host_dense_flag_normalized);
    }

    fn fastHostMatrixRowMinMaxScanFloat(self: *Session, matrix: Value, shape: NumericMatrixShape, view: HostFloatDenseView, op: BuiltinId) KError!Value {
        const flags = hostFloatDenseValueFlags(matrix, view);
        if (minMaxScanCanReturnInput(op, flags)) return self.shareValue(matrix);
        const len = shape.rows * shape.cols;
        if (hostFloatDenseViewStorageKind(view) == .float32) {
            const plan = try self.planHostFloat32UnaryOutput(matrix, len, true);
            try fillRowMinMaxScanFloat32(plan.output.items, view, op, shape.rows, shape.cols);
            return try self.finishHostFloat32Output(plan, 0);
        }
        const plan = try self.planHostFloatUnaryOutput(matrix, len, true);
        try fillRowMinMaxScanFloat(plan.output.items, view, op, shape.rows, shape.cols);
        return try self.finishHostFloatOutput(plan, 0);
    }

    fn tryFastHostMatrixRowMinMaxScanEach(self: *Session, base: Value, args: []const Value) KError!?Value {
        if (args.len != 1) return null;
        if (self.dense_backend_override == .mlx) return null;
        const op = eachScanMinMaxBuiltin(base) orelse return null;
        const matrix = args[0];
        const shape = valueNumericMatrixShape(matrix) orelse return null;
        if (shape.rows == 0 or shape.cols == 0) return null;
        if (shape.cols == 1) return self.shareValue(matrix);

        const view = hostDenseView(self, matrix) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        if (self.debugDetailedProbeActive()) self.debug.apply_each_fast_dense_count += 1;
        return switch (view) {
            .int_array => |items| blk: {
                if (hostIntDenseViewBitSlice(items)) |bits| break :blk try self.fastHostMatrixRowBitMinMaxScan(matrix, shape, bits, op);
                const range = hostIntDenseValueRange(matrix, items);
                if (range.min >= 0 and range.max <= 1) {
                    const host = numericHostArrayValue(self, matrix) catch null;
                    if (host) |array| switch (array.storage) {
                        .bit => |words| {
                            const bits = HostBitSlice{ .words = hostDenseLogicalBitWords(array, words), .len = array.logical_len };
                            break :blk try self.fastHostMatrixRowBitMinMaxScan(matrix, shape, bits, op);
                        },
                        else => {},
                    };
                }
                break :blk try self.fastHostMatrixRowMinMaxScanInt(matrix, shape, items, op);
            },
            .float_array => |items| try self.fastHostMatrixRowMinMaxScanFloat(matrix, shape, items, op),
            else => null,
        };
    }

    fn tryFastBackendMatrixRowFoldBuiltin(self: *Session, op: BuiltinId, matrix: Value) KError!?Value {
        return runtime_backend_exec.tryFastBackendMatrixRowFoldBuiltin(backend_exec_api, self, op, matrix);
    }

    fn tryFastUnaryLiftedEachDerived(self: *Session, base: Value, args: []const Value) KError!?Value {
        if (args.len != 1 or base.tag() != .closure) return null;
        const closure = base.asClosure();
        const kind = (try self.classifyCompactUnaryLiftedClosure(closure)) orelse return null;
        const len = derivedSequenceLen(args[0]) orelse return null;
        if (self.debugDetailedProbeActive()) self.debug.apply_each_fast_unary_lifted_count += 1;

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len);
        for (0..len) |idx| {
            const item = try self.derivedSequenceItemValue(args[0], idx);
            const result = blk: {
                defer self.releaseValue(item);
                break :blk try self.applyCompactUnaryLiftedKind(kind, item);
            };
            try results.append(self.allocator, result);
        }
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn tryFastDenseEachDerived(self: *Session, base: Value, args: []const Value) KError!?Value {
        if (args.len != 2) return null;
        const kind = try self.classifyDenseElementwiseBaseRuntime(base) orelse {
            self.noteDenseEachMiss(.unsupported_base);
            return null;
        };
        if (args[0].tag() != .array and args[1].tag() != .array) {
            self.noteDenseEachMiss(.non_dense_args_or_shape);
            return null;
        }
        if (!wholeArrayEachDyadSafe(args[0], args[1])) {
            self.noteDenseEachMiss(.non_dense_args_or_shape);
            return null;
        }
        if (self.debugDetailedProbeActive()) self.debug.apply_each_fast_dense_count += 1;
        return try self.applyDenseElementwiseKind(kind, args[0], args[1]);
    }

    fn wholeArrayEachDyadSafe(left: Value, right: Value) bool {
        if (left.tag() != .array or right.tag() != .array) return true;
        if (valueNumericMode(left) == null or valueNumericMode(right) == null) return false;
        if (rowwiseMatrixVectorDyad(left, right) != null) return true;
        const left_shape = valueNonVectorNumericShape(left);
        const right_shape = valueNonVectorNumericShape(right);
        if (left_shape == null and right_shape == null) return true;
        if (left_shape == null or right_shape == null) return false;
        const lhs = left_shape.?;
        const rhs = right_shape.?;
        return lhs.rank == rhs.rank and std.mem.eql(i32, lhs.shapeSlice(), rhs.shapeSlice());
    }

    fn hostShapedIntFoldSupportsBuiltin(op: BuiltinId) bool {
        return switch (op) {
            .add, .sub, .mul, .iota, .minimum, .maximum, .pow => true,
            else => false,
        };
    }

    fn hostShapedFloatFoldSupportsBuiltin(op: BuiltinId) bool {
        return switch (op) {
            .add, .sub, .mul, .div, .minimum, .maximum, .pow => true,
            else => false,
        };
    }

    fn hostShapedBitFoldSupportsBuiltin(op: BuiltinId) bool {
        return switch (op) {
            .minimum, .mul, .maximum => true,
            else => false,
        };
    }

    fn tryFastNumericRazeFold(self: *Session, args: []const Value, collect: bool) KError!?Value {
        if (collect or args.len != 1) return null;
        const value = args[0];
        if (valueNumericMode(value) == null) return null;

        if (valueNumericHandle(value)) |handle| {
            if (handle.rank == 0) return null;
            const shape = try numericShapeRazeFirstTwoAxesSnapshot(handle) orelse return self.shareValue(value);
            return try newReshapeViewValue(self, value, shape);
        }

        if (numericVectorLen(value) != null) return self.shareValue(value);
        return null;
    }

    fn tryFastSeededNumericRazeFold(self: *Session, seed: Value, right: Value) KError!?Value {
        if (valueNumericMode(seed) == null or valueNumericMode(right) == null) return null;
        _ = derivedSequenceLen(right) orelse return null;

        const right_razed = (try self.tryFastNumericRazeFold(&[_]Value{right}, false)) orelse return null;
        defer self.releaseValue(right_razed);

        if (valueNonVectorNumericShape(right_razed) == null) {
            if (valueNonVectorNumericShape(seed) != null) return null;
            return try self.concatValues(seed, right_razed);
        }

        const seed_matrix = valueNumericMatrixShape(seed) orelse return null;
        const right_matrix = valueNumericMatrixShape(right_razed) orelse return null;
        if (seed_matrix.cols != right_matrix.cols) return null;
        return try self.concatValues(seed, right_razed);
    }

    fn appendConcatRazeItemValues(self: *Session, values: *std.ArrayList(Value), value: Value) KError!void {
        if (derivedSequenceLen(value)) |len| {
            try values.ensureUnusedCapacity(self.allocator, len);
            for (0..len) |idx| {
                const item = try self.derivedSequenceItemValue(value, idx);
                errdefer self.releaseValue(item);
                try values.append(self.allocator, item);
            }
            return;
        }

        const retained = try self.retainEscapedValue(value);
        errdefer self.releaseValue(retained);
        try values.append(self.allocator, retained);
    }

    fn seededConcatRazeFold(self: *Session, seed: Value, right: Value) KError!Value {
        const len = derivedSequenceLen(right) orelse return error.Type;
        var values = std.ArrayList(Value).empty;
        defer {
            for (values.items) |value| self.releaseValue(value);
            values.deinit(self.allocator);
        }

        try self.appendConcatRazeItemValues(&values, seed);
        for (0..len) |idx| {
            const item = try self.derivedSequenceItemValue(right, idx);
            defer self.releaseValue(item);
            try self.appendConcatRazeItemValues(&values, item);
        }
        return try self.createManagedArrayLikeFromValues(values.items);
    }

    fn tryConcatRazeFold(self: *Session, args: []const Value, collect: bool) KError!?Value {
        if (collect) return null;
        if (args.len == 1) return try self.tryFastNumericRazeFold(args, collect);
        if (args.len != 2) return null;
        if (valueNumericMode(args[0]) == null or valueNumericMode(args[1]) == null) return null;
        _ = derivedSequenceLen(args[1]) orelse return null;
        if (try self.tryFastSeededNumericRazeFold(args[0], args[1])) |value| return value;
        return try self.seededConcatRazeFold(args[0], args[1]);
    }

    fn tryFastStructuralFoldDerived(self: *Session, base: Value, args: []const Value, collect: bool) KError!?Value {
        if (base.tag() != .builtin) return null;
        return switch (base.asBuiltin()) {
            .concat => try self.tryConcatRazeFold(args, collect),
            else => null,
        };
    }

    fn tryFastHostFoldDerived(self: *Session, base: Value, args: []const Value, collect: bool) KError!?Value {
        if (base.tag() != .builtin) return null;
        if (!collect) {
            if (try self.tryFastHostShapedFold(base.asBuiltin(), args)) |value| return value;
        }
        return switch (base.asBuiltin()) {
            .add => try self.tryFastHostAddFoldScan(args, collect),
            .sub => if (!collect) try self.tryFastHostSubFold(args) else null,
            .mul => try self.tryFastHostMulFoldScan(args, collect),
            .minimum, .maximum => if (collect)
                try self.tryFastHostMinMaxScan(base.asBuiltin(), args)
            else
                try self.tryFastHostMinMaxFold(base.asBuiltin(), args),
            else => null,
        };
    }

    fn shouldTryHostFoldBeforeBackend(self: *Session, base: Value, args: []const Value, collect: bool) bool {
        if (collect or self.dense_backend_override != .auto or self.device_preference == .gpu) return false;
        if (base.tag() != .builtin or args.len == 0 or args.len > 2) return false;
        switch (base.asBuiltin()) {
            .add, .sub, .mul, .minimum, .maximum => {},
            else => return false,
        }

        const vector = args[args.len - 1];
        if (valueNonVectorNumericShape(vector) != null) return false;
        if (numericVectorLen(vector) == null) return false;
        if (hasBackendRealization(vector)) return false;
        return valueSupportsCheapHostDensePlanning(vector);
    }

    fn tryFastBackendFoldDerived(self: *Session, base: Value, args: []const Value, collect: bool) KError!?Value {
        return runtime_backend_exec.tryFastBackendFoldDerived(backend_exec_api, self, base, args, collect);
    }

    fn fastRangeIotaAddFoldScan(self: *Session, handle: *const NumericArray, seed: ?i64, collect: bool) KError!Value {
        const len = numericArrayRangeLen(handle);
        if (seed == null and len == 0) return error.Type;

        if (!collect) {
            const len_i128: i128 = @intCast(len);
            const last_idx_i128: i128 = @intCast(if (len == 0) 0 else len - 1);
            const start_i128: i128 = numericArrayRangeIota(handle).start;
            const step_i128: i128 = numericArrayRangeIota(handle).step;
            var total_i128 = start_i128 * len_i128;
            total_i128 += step_i128 * @divTrunc(len_i128 * last_idx_i128, 2);
            if (seed) |seed_value| total_i128 += seed_value;
            const total_i64 = std.math.cast(i64, total_i128) orelse return error.Unsupported;
            return try self.intValue(total_i64);
        }

        const out = try self.allocator.alloc(i64, len);
        defer self.allocator.free(out);

        var current = numericArrayRangeIota(handle).start;
        if (seed) |seed_value| {
            var acc = seed_value;
            for (0..len) |idx| {
                acc = try checkedIntOp(.add, acc, current);
                out[idx] = acc;
                current = try checkedIntOp(.add, current, numericArrayRangeIota(handle).step);
            }
        } else {
            var acc = current;
            out[0] = acc;
            current = try checkedIntOp(.add, current, numericArrayRangeIota(handle).step);
            for (1..len) |idx| {
                acc = try checkedIntOp(.add, acc, current);
                out[idx] = acc;
                current = try checkedIntOp(.add, current, numericArrayRangeIota(handle).step);
            }
        }
        return try self.createManagedHostIntArray(out);
    }

    fn tryFastHostAddFoldScan(self: *Session, args: []const Value, collect: bool) KError!?Value {
        if (args.len == 0 or args.len > 2) return null;
        if (self.dense_backend_override == .mlx) return null;

        const vector = args[args.len - 1];
        if (valueNonVectorNumericShape(vector) != null) {
            if (collect and args.len == 1) {
                if (shapedNumericHandle(vector)) |handle| {
                    if (try self.fastHostFirstAxisAddScan(vector, handle)) |value| {
                        noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                        return value;
                    }
                }
            }
            return null;
        }
        if (vector.tag() == .array and vector.arrayKind() == .numeric_array) {
            const handle = vector.asNumericArray();
            if (numericArrayIsVectorRangeIota(handle)) {
                const len = numericArrayRangeLen(handle);
                if (args.len == 1 and len == 0) return null;

                if (len <= 1) return null;

                if (args.len == 2) {
                    if (scalarIntLikeValue(args[0])) |seed_int| {
                        noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                        return try self.fastRangeIotaAddFoldScan(handle, seed_int, collect);
                    }
                    return null;
                }
                noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                return try self.fastRangeIotaAddFoldScan(handle, null, collect);
            }
        }
        if (hostDenseIfPresent(vector)) |array| {
            const len = array.len();

            if (args.len == 1 and len == 0) return null;

            if (len <= 1) return null;

            if (hostIntArrayView(array)) |int_view| {
                if (args.len == 2) {
                    if (scalarIntLikeValue(args[0])) |seed_int| {
                        noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                        return if (collect)
                            try self.fastHostAddScanInt(vector, int_view, seed_int)
                        else
                            try self.fastHostAddFoldInt(array, int_view, seed_int);
                    }
                    const seed_float = scalarNumericValue(args[0]) catch return null;
                    noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                    return if (collect)
                        try self.fastHostAddScanFloatFromInt(vector, int_view, seed_float)
                    else
                        try self.fastHostAddFoldFloatFromInt(int_view, seed_float);
                }

                noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                return if (collect)
                    try self.fastHostAddScanIntUnseeded(vector, int_view)
                else
                    try self.fastHostAddFoldIntUnseeded(array, int_view);
            }

            return switch (array.storage) {
                .float32 => |items| blk: {
                    if (args.len == 2) {
                        const seed = scalarNumericValue(args[0]) catch break :blk null;
                        const seed_kind = scalarFloatStorageKind(args[0]) orelse .float32;
                        noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                        break :blk if (collect)
                            try self.fastHostAddScanFloat32(vector, items, seed, seed_kind)
                        else
                            try self.fastHostAddFoldFloat32(items, seed, seed_kind);
                    }
                    noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                    break :blk if (collect)
                        try self.fastHostAddScanFloat32Unseeded(vector, items)
                    else
                        try self.fastHostAddFoldFloat32Unseeded(items);
                },
                .float64 => |items| blk: {
                    if (args.len == 2) {
                        const seed = scalarNumericValue(args[0]) catch break :blk null;
                        noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                        break :blk if (collect)
                            try self.fastHostAddScanFloat(vector, items, seed)
                        else
                            try self.fastHostAddFoldFloat(items, seed);
                    }
                    noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                    break :blk if (collect)
                        try self.fastHostAddScanFloatUnseeded(vector, items)
                    else
                        try self.fastHostAddFoldFloatUnseeded(items);
                },
                else => null,
            };
        }

        const view = hostDenseView(self, vector) catch return null;
        return switch (view) {
            .float_array => |items| blk: {
                const len = hostFloatDenseViewLen(items);
                if (args.len == 1 and len == 0) break :blk null;
                if (len <= 1) break :blk null;
                const storage_kind = hostFloatDenseViewStorageKind(items) orelse break :blk null;
                if (args.len == 2) {
                    const seed = scalarNumericValue(args[0]) catch break :blk null;
                    const seed_kind: HostFloatStorageKind = if ((scalarFloatStorageKind(args[0]) orelse .float32) == .float64) .float64 else storage_kind;
                    noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                    break :blk if (collect)
                        switch (seed_kind) {
                            .float32 => try self.fastHostAddScanFloat32ViewMaybeSeed(vector, items, @floatCast(seed)),
                            .float64 => try self.fastHostAddScanFloatViewMaybeSeed(vector, items, seed),
                        }
                    else
                        try self.fastHostAddFoldFloatView(items, seed, seed_kind);
                }
                noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                break :blk if (collect)
                    switch (storage_kind) {
                        .float32 => try self.fastHostAddScanFloat32ViewMaybeSeed(vector, items, null),
                        .float64 => try self.fastHostAddScanFloatViewMaybeSeed(vector, items, null),
                    }
                else
                    try self.fastHostAddFoldFloatViewUnseeded(items, storage_kind);
            },
            .int_array => |items| blk: {
                const len = hostIntDenseViewLen(items);
                if (args.len == 1 and len == 0) break :blk null;
                if (len <= 1) break :blk null;
                if (args.len == 2) {
                    if (scalarIntLikeValue(args[0])) |seed_int| {
                        noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                        break :blk if (collect)
                            try self.fastHostAddScanIntDenseViewMaybeSeed(vector, items, seed_int)
                        else
                            try self.fastHostAddFoldIntView(items, seed_int);
                    }
                    const seed_float = scalarNumericValue(args[0]) catch break :blk null;
                    noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                    break :blk if (collect)
                        try self.fastHostAddScanFloatFromIntDenseView(vector, items, seed_float)
                    else
                        try self.fastHostAddFoldFloatFromIntDenseView(items, seed_float);
                }
                noteDensePlanDecision(self, if (collect) .scan else .reduce, .host, .host, .host_fast_kernel);
                break :blk if (collect)
                    try self.fastHostAddScanIntDenseViewMaybeSeed(vector, items, null)
                else
                    try self.fastHostAddFoldIntViewUnseeded(items);
            },
            else => null,
        };
    }

    fn fastRangeIotaSubFold(self: *Session, handle: *const NumericArray, seed: ?i64) KError!Value {
        const len = numericArrayRangeLen(handle);
        if (seed == null and len == 0) return error.Type;

        var acc = seed orelse numericArrayRangeIota(handle).start;
        var current = if (seed == null)
            try checkedIntOp(.add, numericArrayRangeIota(handle).start, numericArrayRangeIota(handle).step)
        else
            numericArrayRangeIota(handle).start;
        const start_idx: usize = if (seed == null) 1 else 0;
        for (start_idx..len) |_| {
            acc = try checkedIntOp(.sub, acc, current);
            current = try checkedIntOp(.add, current, numericArrayRangeIota(handle).step);
        }
        return try self.intValue(acc);
    }

    fn fastHostSubFoldIntUnseeded(self: *Session, view: HostIntArrayView) KError!Value {
        var acc = hostIntViewItem(view, 0);
        for (1..hostIntArrayViewLen(view)) |idx| {
            acc = try checkedIntOp(.sub, acc, hostIntViewItem(view, idx));
        }
        return try self.intValue(acc);
    }

    fn fastHostSubFoldInt(self: *Session, view: HostIntArrayView, seed: i64) KError!Value {
        var acc = seed;
        for (0..hostIntArrayViewLen(view)) |idx| {
            acc = try checkedIntOp(.sub, acc, hostIntViewItem(view, idx));
        }
        return try self.intValue(acc);
    }

    fn fastHostSubFoldFloatUnseeded(self: *Session, items: []const f64) KError!Value {
        return try self.floatValue(foldSubFloatSlice(items, null));
    }

    fn fastHostSubFoldFloat(self: *Session, items: []const f64, seed: f64) KError!Value {
        return try self.floatValue(foldSubFloatSlice(items, seed));
    }

    fn fastHostSubFoldFloat32Unseeded(self: *Session, items: []const f32) KError!Value {
        return try self.float32Value(foldSubFloat32Slice(items, null));
    }

    fn fastHostSubFoldFloat32(self: *Session, items: []const f32, seed: f64, seed_kind: HostFloatStorageKind) KError!Value {
        return switch (seed_kind) {
            .float32 => try self.float32Value(foldSubFloat32Slice(items, @floatCast(seed))),
            .float64 => try self.floatValue(foldSubFloat32SlicePromoted(items, seed)),
        };
    }

    fn fastHostSubFoldFloatFromInt(self: *Session, view: HostIntArrayView, seed: f64) KError!Value {
        var acc = seed;
        switch (view) {
            .bit => |items| {
                for (0..items.len) |idx| acc -= @floatFromInt(@intFromBool(bitGet(items.words, idx)));
            },
            .int8 => |items| {
                for (items) |item| acc -= @floatFromInt(item);
            },
            .int16 => |items| {
                for (items) |item| acc -= @floatFromInt(item);
            },
            .int32 => |items| {
                for (items) |item| acc -= @floatFromInt(item);
            },
            .int64 => |items| {
                for (items) |item| acc -= @floatFromInt(item);
            },
        }
        return try self.floatValue(acc);
    }

    fn tryFastHostSubFold(self: *Session, args: []const Value) KError!?Value {
        if (args.len == 0 or args.len > 2) return null;
        if (self.dense_backend_override == .mlx) return null;

        const vector = args[args.len - 1];
        if (valueNonVectorNumericShape(vector) != null) return null;
        if (vector.tag() == .array and vector.arrayKind() == .numeric_array) {
            const handle = vector.asNumericArray();
            if (numericArrayIsVectorRangeIota(handle)) {
                const len = numericArrayRangeLen(handle);
                if (args.len == 1 and len == 0) return null;
                if (len <= 1) return null;

                if (args.len == 2) {
                    if (scalarIntLikeValue(args[0])) |seed_int| {
                        noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                        return try self.fastRangeIotaSubFold(handle, seed_int);
                    }
                    return null;
                }
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                return try self.fastRangeIotaSubFold(handle, null);
            }
        }

        const array = hostDenseIfPresent(vector) orelse return null;
        const len = array.len();
        if (args.len == 1 and len == 0) return null;
        if (len <= 1) return null;

        if (hostIntArrayView(array)) |int_view| {
            if (args.len == 2) {
                if (scalarIntLikeValue(args[0])) |seed_int| {
                    noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                    return try self.fastHostSubFoldInt(int_view, seed_int);
                }
                const seed_float = scalarNumericValue(args[0]) catch return null;
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                return try self.fastHostSubFoldFloatFromInt(int_view, seed_float);
            }

            noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
            return try self.fastHostSubFoldIntUnseeded(int_view);
        }

        return switch (array.storage) {
            .float32 => |items| blk: {
                if (args.len == 2) {
                    const seed = scalarNumericValue(args[0]) catch break :blk null;
                    const seed_kind = scalarFloatStorageKind(args[0]) orelse .float32;
                    noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                    break :blk try self.fastHostSubFoldFloat32(items, seed, seed_kind);
                }
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                break :blk try self.fastHostSubFoldFloat32Unseeded(items);
            },
            .float64 => |items| blk: {
                if (args.len == 2) {
                    const seed = scalarNumericValue(args[0]) catch break :blk null;
                    noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                    break :blk try self.fastHostSubFoldFloat(items, seed);
                }
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                break :blk try self.fastHostSubFoldFloatUnseeded(items);
            },
            else => null,
        };
    }

    fn tryFastHostMulFoldScan(self: *Session, args: []const Value, collect: bool) KError!?Value {
        if (collect or args.len == 0 or args.len > 2) return null;
        if (self.dense_backend_override == .mlx) return null;

        const vector = args[args.len - 1];
        if (valueNonVectorNumericShape(vector) != null) return null;
        const array = hostDenseIfPresent(vector) orelse return null;

        const len = array.len();
        if (args.len == 1 and len == 0) return null;

        if (len <= 1) return null;

        switch (array.storage) {
            .bit => |words| {
                const bits = HostBitSlice{ .words = words, .len = len };
                if (args.len == 2) {
                    if (scalarIntLikeValue(args[0])) |seed_int| {
                        noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                        return try self.fastHostMulFoldBit(bits, seed_int);
                    }
                    const seed_float = scalarNumericValue(args[0]) catch return null;
                    noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                    return try self.fastHostMulFoldFloatFromBit(bits, seed_float);
                }
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                return try self.fastHostMulFoldBitUnseeded(bits);
            },
            .float32 => |items| {
                if (args.len == 2) {
                    const seed = scalarNumericValue(args[0]) catch return null;
                    const seed_kind = scalarFloatStorageKind(args[0]) orelse .float32;
                    noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                    return try self.fastHostMulFoldFloat32(items, seed, seed_kind);
                }
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                return try self.fastHostMulFoldFloat32Unseeded(items);
            },
            .float64 => |items| {
                const seed = if (args.len == 2) scalarNumericValue(args[0]) catch return null else null;
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                return try self.fastHostMulFoldFloat(items, seed);
            },
            else => return null,
        }
    }

    fn tryFastHostMinMaxFold(self: *Session, op: BuiltinId, args: []const Value) KError!?Value {
        if (args.len == 0 or args.len > 2) return null;
        if (self.dense_backend_override == .mlx) return null;

        const vector = args[args.len - 1];
        if (valueNonVectorNumericShape(vector) != null) return null;
        if (denseReduceScanActualBackend(self, false, vector) != .host) return null;

        const view = hostDenseView(self, vector) catch return null;
        const len = switch (view) {
            .int_array => |items| hostIntDenseViewLen(items),
            .float_array => |items| hostFloatDenseViewLen(items),
            else => return null,
        };

        if (args.len == 1 and len == 0) return null;
        if (args.len == 2 and len == 0) {
            noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
            return self.shareValue(args[0]);
        }

        switch (view) {
            .int_array => |items| {
                const bounds = if (try tryHostIntDenseViewRangeMorsel(self, items)) |morsel_bounds|
                    morsel_bounds
                else
                    hostIntDenseViewRange(items);
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                if (args.len == 1) {
                    return try self.intValue(switch (op) {
                        .minimum => bounds.min,
                        .maximum => bounds.max,
                        else => unreachable,
                    });
                }
                if (scalarIntLikeValue(args[0])) |seed_int| {
                    return try self.intValue(switch (op) {
                        .minimum => @min(seed_int, bounds.min),
                        .maximum => @max(seed_int, bounds.max),
                        else => unreachable,
                    });
                }
                const seed = scalarNumericValue(args[0]) catch return null;
                return try self.floatValue(switch (op) {
                    .minimum => @min(seed, @as(f64, @floatFromInt(bounds.min))),
                    .maximum => @max(seed, @as(f64, @floatFromInt(bounds.max))),
                    else => unreachable,
                });
            },
            .float_array => |items| {
                const bounds = if (try tryHostFloatDenseViewBoundsMorsel(self, items)) |morsel_bounds|
                    morsel_bounds
                else
                    try hostFloatDenseViewBounds(items);
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                const result_kind = mergeHostFloatStorageKind(valueFloatStorageKind(vector), if (args.len == 2) scalarFloatStorageKind(args[0]) else null) orelse .float64;
                if (args.len == 1) {
                    const result = switch (op) {
                        .minimum => bounds.min,
                        .maximum => bounds.max,
                        else => unreachable,
                    };
                    return switch (result_kind) {
                        .float32 => try self.float32Value(@floatCast(result)),
                        .float64 => try self.floatValue(result),
                    };
                }
                const seed = scalarNumericValue(args[0]) catch return null;
                const result = switch (op) {
                    .minimum => @min(seed, bounds.min),
                    .maximum => @max(seed, bounds.max),
                    else => unreachable,
                };
                return switch (result_kind) {
                    .float32 => try self.float32Value(@floatCast(result)),
                    .float64 => try self.floatValue(result),
                };
            },
            else => return null,
        }
    }

    fn tryFastHostShapedFold(self: *Session, op: BuiltinId, args: []const Value) KError!?Value {
        if (args.len == 0 or args.len > 2) return null;
        if (self.dense_backend_override == .mlx) return null;

        const supports_int_result = hostShapedIntFoldSupportsBuiltin(op);
        const supports_float_result = hostShapedFloatFoldSupportsBuiltin(op);
        if (!supports_int_result and !supports_float_result) return null;

        const value = args[args.len - 1];
        const handle = shapedNumericHandle(value) orelse return null;
        if (denseReduceScanActualBackend(self, false, value) != .host) return null;

        const outer_len: usize = @intCast(handle.shape[0]);
        if (args.len == 1 and outer_len == 0) {
            return null;
        }

        if (outer_len <= 1) return null;

        const block_len = numericShapeInnerBlockLen(handle);
        const view = hostDenseView(self, value) catch return null;

        switch (view) {
            .int_array => |items| {
                if (hostShapedBitFoldSupportsBuiltin(op)) switch (items) {
                    .dense => |dense| switch (dense) {
                        .bit => |bits| {
                            if (args.len == 1) {
                                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                                return try self.fastHostShapedBitFoldUnseeded(handle, bits, op);
                            }
                            if (scalarIntLikeValue(args[0])) |seed_int| {
                                if (seed_int == 0 or seed_int == 1) {
                                    noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                                    return try self.fastHostShapedBitFold(handle, bits, op, seed_int != 0);
                                }
                            }
                        },
                        else => {},
                    },
                    else => {},
                };
                if (args.len == 2) {
                    if (scalarIntLikeValue(args[0])) |seed_int| {
                        if (supports_int_result) {
                            noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                            return try self.fastHostShapedIntFold(handle, items, op, seed_int);
                        }
                    }
                    if (!supports_float_result) return null;
                    const seed = scalarNumericValue(args[0]) catch return null;
                    noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                    return try self.fastHostShapedFloatFoldFromInt(handle, items, op, block_len, outer_len, seed);
                }
                if (!supports_int_result) {
                    if (!supports_float_result) return null;
                    noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                    return try self.fastHostShapedFloatFoldFromInt(handle, items, op, block_len, outer_len, null);
                }
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                return try self.fastHostShapedIntFoldUnseeded(handle, items, op);
            },
            .float_array => |items| {
                if (!supports_float_result) return null;
                const seed = if (args.len == 2) scalarNumericValue(args[0]) catch return null else null;
                noteDensePlanDecision(self, .reduce, .host, .host, .host_fast_kernel);
                if (hostFloatDenseViewStorageKind(items) == .float32) {
                    return try self.fastHostShapedFloat32Fold(handle, items, op, block_len, outer_len, seed);
                }
                return try self.fastHostShapedFloatFold(handle, items, op, block_len, outer_len, seed);
            },
            else => return null,
        }
    }

    fn finishHostReducedIntResult(self: *Session, handle: *const NumericArray, items: []const i64) KError!Value {
        const value = try self.createManagedHostIntArray(items);
        return try applyNonVectorNumericShapeToValue(self, value, numericShapeTailSnapshot(handle));
    }

    fn finishHostReducedBitResult(self: *Session, handle: *const NumericArray, out: HostBitAlloc) KError!Value {
        const metadata = analyzeBitSlice(.{ .words = out.words, .len = out.len });
        const value = try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
        return try applyNonVectorNumericShapeToValue(self, value, numericShapeTailSnapshot(handle));
    }

    fn finishHostReducedFloatResult(self: *Session, handle: *const NumericArray, items: []const f64) KError!Value {
        const value = try self.createManagedHostFloatArray(items);
        return try applyNonVectorNumericShapeToValue(self, value, numericShapeTailSnapshot(handle));
    }

    fn finishHostReducedFloat32Result(self: *Session, handle: *const NumericArray, items: []const f32) KError!Value {
        const value = try self.createManagedHostFloat32Array(items);
        return try applyNonVectorNumericShapeToValue(self, value, numericShapeTailSnapshot(handle));
    }

    fn fillHostShapedIntFold(out: []i64, view: HostIntDenseView, op: BuiltinId, block_len: usize, outer_len: usize, seed: ?i64) KError!void {
        const start_row: usize = if (seed) |seed_value| blk: {
            @memset(out, seed_value);
            break :blk 0;
        } else blk: {
            for (0..block_len) |col_idx| out[col_idx] = try hostIntDenseViewItem(view, col_idx);
            break :blk 1;
        };

        for (start_row..outer_len) |row_idx| {
            const row_base = row_idx * block_len;
            for (0..block_len) |col_idx| {
                out[col_idx] = try checkedIntOp(op, out[col_idx], try hostIntDenseViewItem(view, row_base + col_idx));
            }
        }
    }

    fn fillHostShapedFloatFold(out: []f64, view: HostFloatDenseView, op: BuiltinId, block_len: usize, outer_len: usize, seed: ?f64) KError!void {
        const start_row: usize = if (seed) |seed_value| blk: {
            @memset(out, seed_value);
            break :blk 0;
        } else blk: {
            for (0..block_len) |col_idx| out[col_idx] = try hostFloatDenseViewItem(view, col_idx);
            break :blk 1;
        };

        for (start_row..outer_len) |row_idx| {
            const row_base = row_idx * block_len;
            for (0..block_len) |col_idx| {
                out[col_idx] = applyFloatOp(op, out[col_idx], try hostFloatDenseViewItem(view, row_base + col_idx));
            }
        }
    }

    fn fillHostShapedFloat32Fold(out: []f32, view: HostFloatDenseView, op: BuiltinId, block_len: usize, outer_len: usize, seed: ?f64) KError!void {
        const start_row: usize = if (seed) |seed_value| blk: {
            @memset(out, @floatCast(seed_value));
            break :blk 0;
        } else blk: {
            for (0..block_len) |col_idx| out[col_idx] = @floatCast(try hostFloatDenseViewItem(view, col_idx));
            break :blk 1;
        };

        for (start_row..outer_len) |row_idx| {
            const row_base = row_idx * block_len;
            for (0..block_len) |col_idx| {
                out[col_idx] = @floatCast(applyFloatOp(op, out[col_idx], try hostFloatDenseViewItem(view, row_base + col_idx)));
            }
        }
    }

    fn fillHostShapedFloatFoldFromInt(out: []f64, view: HostIntDenseView, op: BuiltinId, block_len: usize, outer_len: usize, seed: ?f64) KError!void {
        const start_row: usize = if (seed) |seed_value| blk: {
            @memset(out, seed_value);
            break :blk 0;
        } else blk: {
            for (0..block_len) |col_idx| out[col_idx] = @floatFromInt(try hostIntDenseViewItem(view, col_idx));
            break :blk 1;
        };

        for (start_row..outer_len) |row_idx| {
            const row_base = row_idx * block_len;
            for (0..block_len) |col_idx| {
                out[col_idx] = applyFloatOp(op, out[col_idx], @floatFromInt(try hostIntDenseViewItem(view, row_base + col_idx)));
            }
        }
    }

    fn bitFoldApplyWord(op: BuiltinId, left: u64, right: u64) u64 {
        return switch (op) {
            .minimum, .mul => left & right,
            .maximum => left | right,
            else => unreachable,
        };
    }

    fn bitFoldSeedWord(op: BuiltinId, seed: bool, mask: u64) u64 {
        return switch (op) {
            .minimum, .mul, .maximum => if (seed) mask else 0,
            else => unreachable,
        };
    }

    fn fillHostShapedBitFold(out: []u64, view: HostBitSlice, op: BuiltinId, block_len: usize, outer_len: usize, seed: ?bool) void {
        if (block_len % host_bit_word_bits == 0) {
            const row_words = block_len / host_bit_word_bits;
            if (seed) |seed_value| {
                const seed_word: u64 = if (seed_value) std.math.maxInt(u64) else 0;
                @memset(out, seed_word);
                for (0..outer_len) |row_idx| {
                    const row = view.words[row_idx * row_words ..][0..row_words];
                    for (out, row) |*out_word, row_word| {
                        out_word.* = bitFoldApplyWord(op, out_word.*, row_word);
                    }
                }
            } else {
                @memcpy(out, view.words[0..row_words]);
                for (1..outer_len) |row_idx| {
                    const row = view.words[row_idx * row_words ..][0..row_words];
                    for (out, row) |*out_word, row_word| {
                        out_word.* = bitFoldApplyWord(op, out_word.*, row_word);
                    }
                }
            }
            return;
        }

        for (out, 0..) |*out_word, word_idx| {
            const active_len = bitWordActiveLen(block_len, word_idx, out.len);
            const mask = bitLowMask(active_len);
            const col_start = word_idx * host_bit_word_bits;
            var acc: u64 = undefined;
            const start_row: usize = if (seed) |seed_value| blk: {
                acc = bitFoldSeedWord(op, seed_value, mask);
                break :blk 0;
            } else blk: {
                acc = bitExtractWindow(view.words, col_start) & mask;
                break :blk 1;
            };

            for (start_row..outer_len) |row_idx| {
                const row_start = row_idx * block_len + col_start;
                const row_bits = bitExtractWindow(view.words, row_start) & mask;
                acc = bitFoldApplyWord(op, acc, row_bits);
            }
            out_word.* = acc & mask;
        }
    }

    fn fastHostShapedIntFoldUnseeded(self: *Session, handle: *const NumericArray, view: HostIntDenseView, op: BuiltinId) KError!Value {
        const block_len = numericShapeInnerBlockLen(handle);
        const outer_len: usize = @intCast(handle.shape[0]);
        const out = try self.allocator.alloc(i64, block_len);
        defer self.allocator.free(out);
        try fillHostShapedIntFold(out, view, op, block_len, outer_len, null);
        return try self.finishHostReducedIntResult(handle, out);
    }

    fn fastHostShapedIntFold(self: *Session, handle: *const NumericArray, view: HostIntDenseView, op: BuiltinId, seed: i64) KError!Value {
        const block_len = numericShapeInnerBlockLen(handle);
        const outer_len: usize = @intCast(handle.shape[0]);
        const out = try self.allocator.alloc(i64, block_len);
        defer self.allocator.free(out);
        try fillHostShapedIntFold(out, view, op, block_len, outer_len, seed);
        return try self.finishHostReducedIntResult(handle, out);
    }

    fn fastHostShapedBitFoldUnseeded(self: *Session, handle: *const NumericArray, view: HostBitSlice, op: BuiltinId) KError!Value {
        const block_len = numericShapeInnerBlockLen(handle);
        const outer_len: usize = @intCast(handle.shape[0]);
        const out = try self.allocHostBitArrayUninitialized(.managed, block_len);
        fillHostShapedBitFold(out.words, view, op, block_len, outer_len, null);
        return try self.finishHostReducedBitResult(handle, out);
    }

    fn fastHostShapedBitFold(self: *Session, handle: *const NumericArray, view: HostBitSlice, op: BuiltinId, seed: bool) KError!Value {
        const block_len = numericShapeInnerBlockLen(handle);
        const outer_len: usize = @intCast(handle.shape[0]);
