    fn fastHostAddFoldIntUnseeded(self: *Session, array: *const HostDenseArray, view: HostIntArrayView) KError!Value {
        const range = hostIntAddFoldProofRange(array, view);
        if (hostAddIntFoldUsesSimd(view, range, null)) self.noteSimdKernel(.reduction);
        if (try tryFoldAddIntViewMorselMaybeUnchecked(self, view, range, null)) |total| return try self.intValue(total);
        return try self.intValue(try foldAddIntViewMaybeUnchecked(view, range, null));
    }

    fn fastHostAddFoldInt(self: *Session, array: *const HostDenseArray, view: HostIntArrayView, seed: i64) KError!Value {
        const range = hostIntAddFoldProofRange(array, view);
        if (hostAddIntFoldUsesSimd(view, range, seed)) self.noteSimdKernel(.reduction);
        if (try tryFoldAddIntViewMorselMaybeUnchecked(self, view, range, seed)) |total| return try self.intValue(total);
        return try self.intValue(try foldAddIntViewMaybeUnchecked(view, range, seed));
    }

    fn fastHostAddFoldIntViewUnseeded(self: *Session, view: HostIntDenseView) KError!Value {
        if (hostIntDenseViewContiguousArrayView(view)) |source| {
            const range = hostIntDenseViewRange(view);
            if (hostAddIntFoldUsesSimd(source, range, null)) self.noteSimdKernel(.reduction);
            if (try tryFoldAddIntViewMorselMaybeUnchecked(self, source, range, null)) |total| return try self.intValue(total);
        }
        return try self.intValue(try foldAddIntDenseView(view, null));
    }

    fn fastHostAddFoldIntView(self: *Session, view: HostIntDenseView, seed: i64) KError!Value {
        if (hostIntDenseViewContiguousArrayView(view)) |source| {
            const range = hostIntDenseViewRange(view);
            if (hostAddIntFoldUsesSimd(source, range, seed)) self.noteSimdKernel(.reduction);
            if (try tryFoldAddIntViewMorselMaybeUnchecked(self, source, range, seed)) |total| return try self.intValue(total);
        }
        return try self.intValue(try foldAddIntDenseView(view, seed));
    }

    fn fastHostAddFoldFloatUnseeded(self: *Session, items: []const f64) KError!Value {
        if (hostAddFloatFoldUsesSimd(items, null)) self.noteSimdKernel(.reduction);
        if (try tryFoldAddFloatSliceMorsel(self, items, null)) |total| return try self.floatValue(total);
        return try self.floatValue(foldAddFloatSlice(items, null));
    }

    fn fastHostAddFoldFloat(self: *Session, items: []const f64, seed: f64) KError!Value {
        if (hostAddFloatFoldUsesSimd(items, seed)) self.noteSimdKernel(.reduction);
        if (try tryFoldAddFloatSliceMorsel(self, items, seed)) |total| return try self.floatValue(total);
        return try self.floatValue(foldAddFloatSlice(items, seed));
    }

    fn fastHostAddFoldFloat32Unseeded(self: *Session, items: []const f32) KError!Value {
        if (hostAddFloat32FoldUsesSimd(items, null)) self.noteSimdKernel(.reduction);
        if (try tryFoldAddFloat32SliceMorsel(self, items, null)) |total| return try self.float32Value(total);
        return try self.float32Value(foldAddFloat32Slice(items, null));
    }

    fn fastHostAddFoldFloat32(self: *Session, items: []const f32, seed: f64, seed_kind: HostFloatStorageKind) KError!Value {
        return switch (seed_kind) {
            .float32 => if (try tryFoldAddFloat32SliceMorsel(self, items, @floatCast(seed))) |total|
                try self.float32Value(total)
            else
                try self.float32Value(foldAddFloat32Slice(items, @floatCast(seed))),
            .float64 => if (try tryFoldAddFloat32SlicePromotedMorsel(self, items, seed)) |total|
                try self.floatValue(total)
            else
                try self.floatValue(foldAddFloat32SlicePromoted(items, seed)),
        };
    }

    fn fastHostAddFoldFloatViewUnseeded(self: *Session, view: HostFloatDenseView, storage_kind: HostFloatStorageKind) KError!Value {
        return switch (storage_kind) {
            .float32 => if (try tryFoldAddFloat32ViewMorsel(self, view, null)) |total|
                try self.float32Value(total)
            else
                try self.float32Value(try foldAddFloat32View(view, null)),
            .float64 => if (try tryFoldAddFloatViewMorsel(self, view, null)) |total|
                try self.floatValue(total)
            else
                try self.floatValue(try foldAddFloatView(view, null)),
        };
    }

    fn fastHostAddFoldFloatView(self: *Session, view: HostFloatDenseView, seed: f64, result_kind: HostFloatStorageKind) KError!Value {
        return switch (result_kind) {
            .float32 => if (try tryFoldAddFloat32ViewMorsel(self, view, @floatCast(seed))) |total|
                try self.float32Value(total)
            else
                try self.float32Value(try foldAddFloat32View(view, @floatCast(seed))),
            .float64 => if (try tryFoldAddFloatViewMorsel(self, view, seed)) |total|
                try self.floatValue(total)
            else
                try self.floatValue(try foldAddFloatView(view, seed)),
        };
    }

    fn fastHostAddFoldFloatFromInt(self: *Session, view: HostIntArrayView, seed: f64) KError!Value {
        return try self.floatValue(foldAddFloatIntView(view, seed));
    }

    fn fastHostAddFoldFloatFromIntDenseView(self: *Session, view: HostIntDenseView, seed: f64) KError!Value {
        return try self.floatValue(try foldAddFloatIntDenseView(view, seed));
    }

    fn fastHostMulFoldBitUnseeded(self: *Session, items: HostBitSlice) KError!Value {
        return try self.intValue(if (bitWordsAllTrue(items)) 1 else 0);
    }

    fn fastHostMulFoldBit(self: *Session, items: HostBitSlice, seed: i64) KError!Value {
        return try self.intValue(if (bitWordsAllTrue(items)) seed else 0);
    }

    fn fastHostMulFoldFloatFromBit(self: *Session, items: HostBitSlice, seed: f64) KError!Value {
        return try self.floatValue(if (bitWordsAllTrue(items)) seed else 0.0);
    }

    fn fastHostMulFoldFloat(self: *Session, items: []const f64, seed: ?f64) KError!Value {
        return try self.floatValue(foldMulFloatSlice(items, seed));
    }

    fn fastHostMulFoldFloat32Unseeded(self: *Session, items: []const f32) KError!Value {
        return try self.float32Value(foldMulFloat32Slice(items, null));
    }

    fn fastHostMulFoldFloat32(self: *Session, items: []const f32, seed: f64, seed_kind: HostFloatStorageKind) KError!Value {
        return switch (seed_kind) {
            .float32 => try self.float32Value(foldMulFloat32Slice(items, @floatCast(seed))),
            .float64 => try self.floatValue(foldMulFloat32SlicePromoted(items, seed)),
        };
    }

    fn fastHostAddScanIntUnseeded(self: *Session, source_value: Value, view: HostIntArrayView) KError!Value {
        return try self.fastHostAddScanIntMaybeSeed(source_value, view, null);
    }

    fn fastHostAddScanInt(self: *Session, source_value: Value, view: HostIntArrayView, seed: i64) KError!Value {
        return try self.fastHostAddScanIntMaybeSeed(source_value, view, seed);
    }

    fn fastHostAddScanIntMaybeSeed(self: *Session, source_value: Value, view: HostIntArrayView, seed: ?i64) KError!Value {
        if (try self.fastHostAddScanIntSignedRange(source_value, view, seed)) |value| return value;

        const analysis = try analyzeAddScanIntView(view, seed);
        const len = hostIntArrayViewLen(view);
        var plan = try self.planHostIntUnaryOutput(
            source_value,
            hostIntArrayViewKind(view),
            analysis.kind,
            len,
            true,
            true,
        );
        fillAddScanIntResult(&plan.output, view, seed);
        return try self.finishHostIntOutput(plan, analysis.flags);
    }

    fn fastHostAddScanIntDenseViewMaybeSeed(self: *Session, source_value: Value, view: HostIntDenseView, seed: ?i64) KError!Value {
        if (view == .dense) return try self.fastHostAddScanIntMaybeSeed(source_value, view.dense, seed);
        if (try self.fastHostAddScanIntDenseViewSignedRange(source_value, view, seed)) |value| return value;

        const analysis = try analyzeAddScanIntDenseView(view, seed);
        const len = hostIntDenseViewLen(view);
        var plan = try self.planHostIntUnaryOutput(
            source_value,
            analysis.kind,
            analysis.kind,
            len,
            false,
            true,
        );
        try fillAddScanIntDenseResult(&plan.output, view, seed);
        return try self.finishHostIntOutput(plan, analysis.flags);
    }

    fn fastHostAddScanIntSignedRange(self: *Session, source_value: Value, view: HostIntArrayView, seed: ?i64) KError!?Value {
        const len = hostIntArrayViewLen(view);
        const input_range = hostIntDenseValueRange(source_value, .{ .dense = view });
        const result_range = addScanSignedRangeBounds(input_range, len, seed) orelse return null;
        var plan = try self.planHostIntUnaryOutput(
            source_value,
            hostIntArrayViewKind(view),
            hostIntStorageKindForRange(result_range.min, result_range.max),
            len,
            true,
            true,
        );
        fillAddScanIntResult(&plan.output, view, seed);
        return try self.finishHostIntOutputWithRange(plan, addScanIntFlags(input_range), result_range);
    }

    fn fastHostAddScanIntDenseViewSignedRange(self: *Session, source_value: Value, view: HostIntDenseView, seed: ?i64) KError!?Value {
        const len = hostIntDenseViewLen(view);
        const input_range = hostIntDenseValueRange(source_value, view);
        const result_range = addScanSignedRangeBounds(input_range, len, seed) orelse return null;
        const result_kind = hostIntStorageKindForRange(result_range.min, result_range.max);
        var plan = try self.planHostIntUnaryOutput(
            source_value,
            result_kind,
            result_kind,
            len,
            false,
            true,
        );
        try fillAddScanIntDenseResult(&plan.output, view, seed);
        return try self.finishHostIntOutputWithRange(plan, addScanIntFlags(input_range), result_range);
    }

    fn fastHostAddScanFloatUnseeded(self: *Session, source_value: Value, items: []const f64) KError!Value {
        return try self.fastHostAddScanFloatMaybeSeed(source_value, items, null);
    }

    fn fastHostAddScanFloat(self: *Session, source_value: Value, items: []const f64, seed: f64) KError!Value {
        return try self.fastHostAddScanFloatMaybeSeed(source_value, items, seed);
    }

    fn fastHostAddScanFloatMaybeSeed(self: *Session, source_value: Value, items: []const f64, seed: ?f64) KError!Value {
        const len = items.len;
        const plan = try self.planHostFloatUnaryOutput(source_value, len, true);
        const flags = fillAddScanFloatSlice(plan.output.items, items, seed);
        return try self.finishHostFloatOutput(plan, flags);
    }

    fn fastHostAddScanFloatViewMaybeSeed(self: *Session, source_value: Value, view: HostFloatDenseView, seed: ?f64) KError!Value {
        if (view == .dense) return try self.fastHostAddScanFloatMaybeSeed(source_value, view.dense, seed);
        const len = hostFloatDenseViewLen(view);
        const plan = try self.planHostFloatUnaryOutput(source_value, len, false);
        const flags = try fillAddScanFloatView(plan.output.items, view, seed);
        return try self.finishHostFloatOutput(plan, flags);
    }

    fn fastHostAddScanFloat32Unseeded(self: *Session, source_value: Value, items: []const f32) KError!Value {
        return try self.fastHostAddScanFloat32MaybeSeed(source_value, items, null, .float32);
    }

    fn fastHostAddScanFloat32(self: *Session, source_value: Value, items: []const f32, seed: f64, seed_kind: HostFloatStorageKind) KError!Value {
        return try self.fastHostAddScanFloat32MaybeSeed(source_value, items, seed, seed_kind);
    }

    fn fastHostAddScanFloat32MaybeSeed(self: *Session, source_value: Value, items: []const f32, seed: ?f64, seed_kind: HostFloatStorageKind) KError!Value {
        const len = items.len;
        return switch (seed_kind) {
            .float32 => blk: {
                const plan = try self.planHostFloat32UnaryOutput(source_value, len, true);
                const flags = fillAddScanFloat32Slice(plan.output.items, items, if (seed) |value| @as(f32, @floatCast(value)) else null);
                break :blk try self.finishHostFloat32Output(plan, flags);
            },
            .float64 => blk: {
                const promoted_seed = seed orelse @as(f64, @floatCast(items[0]));
                const promoted_start: usize = if (seed == null) 1 else 0;
                const plan = try self.planHostFloatUnaryOutput(source_value, len, false);
                const flags = fillAddScanFloat32SlicePromoted(plan.output.items, items, promoted_seed, promoted_start);
                break :blk try self.finishHostFloatOutput(plan, flags);
            },
        };
    }

    fn fastHostAddScanFloat32ViewMaybeSeed(self: *Session, source_value: Value, view: HostFloatDenseView, seed: ?f32) KError!Value {
        const len = hostFloatDenseViewLen(view);
        const plan = try self.planHostFloat32UnaryOutput(source_value, len, false);
        const flags = try fillAddScanFloat32View(plan.output.items, view, seed);
        return try self.finishHostFloat32Output(plan, flags);
    }

    fn fastHostAddScanFloatFromInt(self: *Session, source_value: Value, view: HostIntArrayView, seed: f64) KError!Value {
        const len = hostIntArrayViewLen(view);
        const plan = try self.planHostFloatUnaryOutput(source_value, len, false);
        fillAddScanFloatIntView(plan.output.items, view, seed);
        return try self.finishHostFloatOutput(plan, addScanIntFlags(hostIntArrayViewRange(view)));
    }

    fn fastHostAddScanFloatFromIntDenseView(self: *Session, source_value: Value, view: HostIntDenseView, seed: f64) KError!Value {
        if (view == .dense) return try self.fastHostAddScanFloatFromInt(source_value, view.dense, seed);
        const len = hostIntDenseViewLen(view);
        const plan = try self.planHostFloatUnaryOutput(source_value, len, false);
        try fillAddScanFloatIntDenseView(plan.output.items, view, seed);
        return try self.finishHostFloatOutput(plan, addScanIntFlags(hostIntDenseValueRange(source_value, view)));
    }

    fn fastHostFirstAxisAddScan(self: *Session, value: Value, handle: *const NumericArray) KError!?Value {
        if (handle.rank <= 1) return null;
        const outer_len: usize = @intCast(handle.shape[0]);
        const block_len = numericShapeInnerBlockLen(handle);
        if (outer_len == 0 or block_len == 0) return null;
        const len = outer_len * block_len;
        const view = hostDenseView(self, value) catch return null;
        return switch (view) {
            .int_array => |items| blk: {
                const out = try self.allocator.alloc(i64, len);
                defer self.allocator.free(out);
                try fillFirstAxisAddScanInt(out, items, block_len, outer_len);
                const result = try self.createManagedHostIntArray(out);
                break :blk try applyNonVectorNumericShapeToValue(self, result, numericShapeSnapshotFromHandle(handle));
            },
            .float_array => |items| blk: {
                if (hostFloatDenseViewStorageKind(items) == .float32) {
                    const plan = try self.planHostFloat32UnaryOutput(value, len, true);
                    try fillFirstAxisAddScanFloat32(plan.output.items, items, block_len, outer_len);
                    break :blk try self.finishHostFloat32Output(plan, 0);
                }
                const out = try self.allocator.alloc(f64, len);
                defer self.allocator.free(out);
                try fillFirstAxisAddScanFloat(out, items, block_len, outer_len);
                const result = try self.createManagedHostFloatArray(out);
                break :blk try applyNonVectorNumericShapeToValue(self, result, numericShapeSnapshotFromHandle(handle));
            },
            else => null,
        };
    }

    fn fastHostBitMinMaxScan(self: *Session, op: BuiltinId, bits: HostBitSlice, seed: ?i64) KError!Value {
        const out = try self.allocHostBitArrayUninitialized(.managed, bits.len);
        const metadata = switch (op) {
            .minimum => fillBitPrefixAndScan(out.words, bits, if (seed) |value| value != 0 else true),
            .maximum => fillBitPrefixOrScan(out.words, bits, if (seed) |value| value != 0 else false),
            else => unreachable,
        };
        return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
    }

    fn fastHostFirstAxisBitMinMaxScan(self: *Session, handle: *const NumericArray, bits: HostBitSlice, op: BuiltinId) KError!Value {
        if (handle.rank <= 1) return error.Type;
        const outer_len: usize = @intCast(handle.shape[0]);
        const block_len = numericShapeInnerBlockLen(handle);
        if (outer_len == 0 or block_len == 0) return error.Type;
        const out = try self.allocHostBitArrayUninitialized(.managed, bits.len);
        const metadata = fillFirstAxisBitMinMaxScan(out.words, bits, op, block_len, outer_len);
        const value = try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
        return try applyNonVectorNumericShapeToValue(self, value, numericShapeSnapshotFromHandle(handle));
    }

    fn fastHostFirstAxisBitLikeMinMaxScan(self: *Session, handle: *const NumericArray, view: HostIntDenseView, op: BuiltinId) KError!Value {
        if (handle.rank <= 1) return error.Type;
        const outer_len: usize = @intCast(handle.shape[0]);
        const block_len = numericShapeInnerBlockLen(handle);
        if (outer_len == 0 or block_len == 0) return error.Type;
        const out = try self.allocHostBitArrayUninitialized(.managed, hostIntDenseViewLen(view));
        const metadata = try fillFirstAxisBitLikeMinMaxScan(out.words, view, op, block_len, outer_len);
        const value = try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
        return try applyNonVectorNumericShapeToValue(self, value, numericShapeSnapshotFromHandle(handle));
    }

    fn fastHostMinMaxScanInt(self: *Session, source_value: Value, view: HostIntDenseView, op: BuiltinId, seed: ?i64) KError!Value {
        const len = hostIntDenseViewLen(view);
        const input_range = hostIntDenseValueRange(source_value, view);
        const result_range = minMaxScanIntResultRange(input_range, seed);
        var plan = try self.planHostIntUnaryOutput(
            source_value,
            hostIntDenseViewKind(view),
            hostIntStorageKindForRange(result_range.min, result_range.max),
            len,
            false,
            true,
        );
        try fillMinMaxScanIntResult(&plan.output, view, op, seed, minMaxScanTerminalInt(op, result_range));
        return try self.finishHostIntOutputWithRange(plan, minMaxScanFlags(op), result_range);
    }

    fn fastHostMinMaxScanFloatFromInt(self: *Session, view: HostIntDenseView, op: BuiltinId, seed: f64) KError!Value {
        const len = hostIntDenseViewLen(view);
        const out = try self.allocator.alloc(f64, len);
        defer self.allocator.free(out);
        try fillMinMaxScanFloatFromInt(out, view, op, seed);
        return try self.createManagedHostFloatArray(out);
    }

    fn fastHostMinMaxScanFloat(self: *Session, source_value: Value, view: HostFloatDenseView, op: BuiltinId, seed: ?f64) KError!Value {
        const len = hostFloatDenseViewLen(view);
        const plan = try self.planHostFloatUnaryOutput(source_value, len, false);
        try fillMinMaxScanFloat(plan.output.items, view, op, seed);
        return try self.finishHostFloatOutput(plan, minMaxScanFlags(op));
    }

    fn fastHostMinMaxScanFloat32(self: *Session, source_value: Value, view: HostFloatDenseView, op: BuiltinId, seed: ?f32) KError!Value {
        const len = hostFloatDenseViewLen(view);
        const plan = try self.planHostFloat32UnaryOutput(source_value, len, true);
        try fillMinMaxScanFloat32(plan.output.items, view, op, seed);
        return try self.finishHostFloat32Output(plan, minMaxScanFlags(op));
    }

    fn minMaxScanCanReturnInput(op: BuiltinId, flags: u8) bool {
        const mono = monotonicFlags(flags);
        return switch (op) {
            .minimum => (mono & host_dense_flag_dsc) != 0,
            .maximum => (mono & host_dense_flag_asc) != 0,
            else => false,
        };
    }

    fn minMaxScanNeedsFirstPrefix(op: BuiltinId, flags: u8) bool {
        const mono = monotonicFlags(flags);
        return switch (op) {
            .minimum => (mono & host_dense_flag_asc) != 0,
            .maximum => (mono & host_dense_flag_dsc) != 0,
            else => false,
        };
    }

    fn repeatFirstAxisFirstCell(self: *Session, source: Value, shape: NumericShapeSnapshot) KError!?Value {
        if (shape.rank <= 1 or shape.shape[0] <= 0) return null;
        const rows: usize = @intCast(shape.shape[0]);
        const row_indices = try newRangeIotaValueWithParams(self, .managed, rows, 0, 0);
        defer self.releaseValue(row_indices);
        return try newFirstAxisIndexValue(self, source, row_indices);
    }

    fn tryFastHostMinMaxScanOrderedInt(self: *Session, op: BuiltinId, vector: Value, view: HostIntDenseView, shape: ?NumericShapeSnapshot) KError!?Value {
        const flags = hostIntDenseValueFlags(vector, view);
        const len = hostIntDenseViewLen(view);
        if (len == 0) return null;
        if (minMaxScanCanReturnInput(op, flags)) return self.shareValue(vector);
        if (!minMaxScanNeedsFirstPrefix(op, flags)) return null;
        if (shape) |snapshot| return try self.repeatFirstAxisFirstCell(vector, snapshot);

        const first = try hostIntDenseViewItem(view, 0);
        return try newRangeIotaValueWithParams(self, .managed, len, first, 0);
    }

    fn tryFastHostMinMaxScanOrderedFloat(self: *Session, op: BuiltinId, vector: Value, view: HostFloatDenseView, shape: ?NumericShapeSnapshot) KError!?Value {
        const flags = hostFloatDenseValueFlags(vector, view);
        const len = hostFloatDenseViewLen(view);
        if (len == 0) return null;
        if (minMaxScanCanReturnInput(op, flags)) return self.shareValue(vector);
        if (!minMaxScanNeedsFirstPrefix(op, flags)) return null;
        if (shape) |snapshot| return try self.repeatFirstAxisFirstCell(vector, snapshot);

        const first = try hostFloatDenseViewItem(view, 0);
        const count = std.math.cast(i64, len) orelse return error.Unsupported;
        const scalar = switch (valueFloatStorageKind(vector) orelse .float64) {
            .float32 => try self.float32Value(@floatCast(first)),
            .float64 => try self.floatValue(first),
        };
        return try self.takeScalarValue(count, scalar);
    }

    fn tryFastHostMinMaxScanConstantBit(self: *Session, vector: Value) KError!?Value {
        const array = hostDenseIfPresent(vector) orelse return null;
        switch (array.storage) {
            .bit => {},
            else => return null,
        }
        const range = hostDenseCachedIntRange(array) orelse return null;
        if (range.min != range.max) return null;
        return self.shareValue(vector);
    }

    fn emptyFoldIdentityInt(op: BuiltinId) ?i64 {
        return switch (op) {
            .add, .sub => 0,
            .mul => 1,
            .minimum => std.math.maxInt(i64),
            .maximum => -std.math.maxInt(i64),
            .unique, .find => kiwi_int_null,
            else => null,
        };
    }

    fn emptyFoldIdentityByte(op: BuiltinId) ?u8 {
        return switch (op) {
            .add, .sub => 0,
            .mul => 1,
            .minimum => 0x7f,
            .maximum => 0x80,
            else => null,
        };
    }

    fn emptyFoldIdentityFloat(op: BuiltinId) ?f64 {
        return switch (op) {
            .add => 0.0,
            .sub => -0.0,
            .mul => 1.0,
            .minimum => std.math.inf(f64),
            .maximum => -std.math.inf(f64),
            .unique, .find => kiwiFloatNull(),
            else => null,
        };
    }

    fn emptyFoldIdentityFloat32(op: BuiltinId) ?f32 {
        return switch (op) {
            .add => 0.0,
            .sub => -0.0,
            .mul => 1.0,
            .minimum => std.math.inf(f32),
            .maximum => -std.math.inf(f32),
            .unique, .find => kiwiFloat32Null(),
            else => null,
        };
    }

    fn emptyFoldHasIdentity(op: BuiltinId) bool {
        return emptyFoldIdentityInt(op) != null;
    }

    fn emptyFoldFloatResultStorageKind(template: Value, seed: ?Value) HostFloatStorageKind {
        return mergeHostFloatStorageKind(valueFloatStorageKind(template), if (seed) |seed_value| scalarFloatStorageKind(seed_value) else null) orelse .float64;
    }

    fn emptyFoldFloatFill(op: BuiltinId, seed: ?Value) KError!f64 {
        if (seed) |seed_value| return try scalarNumericValue(seed_value);
        return emptyFoldIdentityFloat(op) orelse error.Type;
    }

    fn emptyFoldFloat32Fill(op: BuiltinId, seed: ?Value) KError!f32 {
        if (seed) |seed_value| return @floatCast(try scalarNumericValue(seed_value));
        return emptyFoldIdentityFloat32(op) orelse error.Type;
    }

    fn emptyFoldIntFill(op: BuiltinId, seed: ?Value) KError!i64 {
        if (seed) |seed_value| return scalarIntLikeValue(seed_value) orelse error.Type;
        return emptyFoldIdentityInt(op) orelse error.Type;
    }

    fn emptyNumericFoldResult(self: *Session, op: BuiltinId, seed: ?Value, template: Value) KError!Value {
        const mode = valueNumericMode(template) orelse return error.Type;
        const out_shape = if (valueNumericHandle(template)) |handle|
            numericShapeTailSnapshot(handle)
        else
            null;
        const want_float = mode == .float or if (seed) |seed_value|
            scalarIntLikeValue(seed_value) == null
        else
            false;

        if (want_float) {
            switch (emptyFoldFloatResultStorageKind(template, seed)) {
                .float32 => {
                    const fill = try emptyFoldFloat32Fill(op, seed);
                    if (out_shape) |shape| {
                        const len = try numericShapeSnapshotElementCount(shape);
                        const out = try self.allocator.alloc(f32, len);
                        defer self.allocator.free(out);
                        @memset(out, fill);
                        const value = try self.createManagedHostFloat32Array(out);
                        return try applyNonVectorNumericShapeToValue(self, value, shape);
                    }
                    return try self.float32Value(fill);
                },
                .float64 => {
                    const fill = try emptyFoldFloatFill(op, seed);
                    if (out_shape) |shape| {
                        const len = try numericShapeSnapshotElementCount(shape);
                        const out = try self.allocator.alloc(f64, len);
                        defer self.allocator.free(out);
                        @memset(out, fill);
                        const value = try self.createManagedHostFloatArray(out);
                        return try applyNonVectorNumericShapeToValue(self, value, shape);
                    }
                    return try self.floatValue(fill);
                },
            }
        }

        const fill = try emptyFoldIntFill(op, seed);
        if (out_shape) |shape| {
            const len = try numericShapeSnapshotElementCount(shape);
            const out = try self.allocator.alloc(i64, len);
            defer self.allocator.free(out);
            @memset(out, fill);
            const value = try self.createManagedHostIntArray(out);
            return try applyNonVectorNumericShapeToValue(self, value, shape);
        }
        return try self.intValue(fill);
    }

    fn emptyNumericPrototypeFoldResult(self: *Session, op: BuiltinId, seed: ?Value, prototype: Value) KError!Value {
        const mode = valueNumericMode(prototype) orelse return error.Type;
        const flat_len = numericFlatLen(prototype) orelse return try self.emptyNumericFoldResult(op, seed, prototype);
        const out_shape = valueNonVectorNumericShape(prototype);
        const want_float = mode == .float or if (seed) |seed_value|
            scalarIntLikeValue(seed_value) == null
        else
            false;

        if (want_float) {
            switch (emptyFoldFloatResultStorageKind(prototype, seed)) {
                .float32 => {
                    const fill = try emptyFoldFloat32Fill(op, seed);
                    const out = try self.allocator.alloc(f32, flat_len);
                    defer self.allocator.free(out);
                    @memset(out, fill);
                    const value = try self.createManagedHostFloat32Array(out);
                    return try applyNonVectorNumericShapeToValue(self, value, out_shape);
                },
                .float64 => {
                    const fill = try emptyFoldFloatFill(op, seed);
                    const out = try self.allocator.alloc(f64, flat_len);
                    defer self.allocator.free(out);
                    @memset(out, fill);
                    const value = try self.createManagedHostFloatArray(out);
                    return try applyNonVectorNumericShapeToValue(self, value, out_shape);
                },
            }
        }

        const fill = try emptyFoldIntFill(op, seed);
        const out = try self.allocator.alloc(i64, flat_len);
        defer self.allocator.free(out);
        @memset(out, fill);
        const value = try self.createManagedHostIntArray(out);
        return try applyNonVectorNumericShapeToValue(self, value, out_shape);
    }

    fn emptyPrototypeFoldResult(self: *Session, op: BuiltinId, prototype: Value) KError!?Value {
        if (valueNumericMode(prototype) != null) {
            return try self.emptyNumericPrototypeFoldResult(op, null, prototype);
        }
        if (stringBytes(prototype)) |bytes| {
            if (emptyFoldIdentityByte(op)) |fill| {
                const out = try self.allocator.alloc(u8, bytes.len);
                defer self.allocator.free(out);
                @memset(out, fill);
                return try self.managedHostCharVector(out);
            }
            return try self.retainEscapedValue(prototype);
        }
        if (symbolBytes(prototype) != null) return try self.retainEscapedValue(prototype);
        if (prototype.tag() != .array) return null;

        return switch (prototype.arrayKind()) {
            .host_symbol_list => try self.retainEscapedValue(prototype),
            .host_string_list => blk: {
                const list = prototype.asHostStringList();
                const values = try self.allocator.alloc(Value, list.len);
                defer self.allocator.free(values);
                var initialized: usize = 0;
                defer {
                    for (values[0..initialized]) |item| self.releaseValue(item);
                }

                for (values, 0..) |*out, idx| {
                    const item = try self.hostStringListItemValue(list, idx);
                    defer self.releaseValue(item);
                    out.* = (try self.emptyPrototypeFoldResult(op, item)) orelse try self.retainEscapedValue(item);
                    initialized += 1;
                }
                break :blk try self.makeArrayFromValues(values);
            },
            .host_boxed_array => blk: {
                const array = prototype.asHostBoxedArray();
                if (array.len() == 0) break :blk try self.retainEscapedValue(prototype);

                const values = try self.allocator.alloc(Value, array.len());
                defer self.allocator.free(values);
                var initialized: usize = 0;
                defer {
                    for (values[0..initialized]) |item| self.releaseValue(item);
                }

                for (values, array.items[0..array.len()]) |*out, item| {
                    out.* = (try self.emptyPrototypeFoldResult(op, item)) orelse try self.retainEscapedValue(item);
                    initialized += 1;
                }
                break :blk try self.makeArrayFromValues(values);
            },
            else => null,
        };
    }

    fn tryEmptyBuiltinFoldScanResult(self: *Session, base: Value, args: []const Value, collect: bool, template: Value) KError!?Value {
        if (base.tag() != .builtin) return null;
        const op = base.asBuiltin();
        if (!emptyFoldHasIdentity(op) and args.len < 2) return null;

        if (collect) return self.shareValue(template);
        if (args.len == 1 and template.tag() == .array and template.arrayKind() == .host_boxed_array) {
            const array = template.asHostBoxedArray();
            if (array.len() == 0) {
                if (array.prototype) |prototype| {
                    if (try self.emptyPrototypeFoldResult(op, prototype)) |value| return value;
                } else {
                    return self.shareValue(template);
                }
            }
        }

        if (valueNumericMode(template) != null) {
            return try self.emptyNumericFoldResult(op, if (args.len >= 2) args[0] else null, template);
        }
        if (args.len >= 2) return self.shareValue(args[0]);
        return try self.intValue(emptyFoldIdentityInt(op) orelse return null);
    }

    fn appendDerivedScanResult(self: *Session, results: *std.ArrayList(Value), value: Value) KError!void {
        const retained = try self.retainEscapedValue(value);
        errdefer self.releaseValue(retained);
        try results.append(self.allocator, retained);
    }

    fn tryApplyIdentityFoldScan(self: *Session, base: Value, args: []const Value, collect: bool) KError!?Value {
        if (base.tag() != .builtin or base.asBuiltin() != .identity or args.len != 1) return null;
        const value = args[0];

        if (stringSourceInfo(value)) |source| {
            const bytes = source.bytes();
            if (collect) return self.shareValue(value);
            if (bytes.len == 0) return try self.managedHostString(" ");
            return try self.stringIndexScalarValue(source, @intCast(bytes.len - 1));
        }

        return null;
    }

    fn tryApplyKeyedDictFoldScan(self: *Session, base: Value, args: []const Value, collect: bool) KError!?Value {
        const store_value = switch (args.len) {
            1 => args[0],
            2 => args[1],
            else => return null,
        };
        if (store_value.tag() != .array or store_value.arrayKind() != .host_keyed_store) return null;
        const store = store_value.asHostKeyedStore();
        if (store.layout == .table) return try self.applyKeyedTableFoldScan(base, args, store, collect);
        if (store.layout != .dict) return null;

        const folded = if (args.len == 1)
            try self.applyFoldDerived(base, &[_]Value{store.values}, collect)
        else
            try self.applyFoldDerived(base, &[_]Value{ args[0], store.values }, collect);
        errdefer self.releaseValue(folded);

        if (!collect) return folded;
        defer self.releaseValue(folded);
        return try self.createHostDictValueFromKeySequenceValue(store.path, store.names, folded);
    }

    fn keyedTableSeedForColumn(self: *Session, seed: Value, store: *const HostKeyedStore, column_idx: usize) KError!Value {
        const column_count = keyedStoreNameCount(store);
        if (seed.tag() == .array and seed.arrayKind() == .host_keyed_store) {
            const seed_store = seed.asHostKeyedStore();
            if (keyedStoreNameCount(seed_store) != column_count) return error.Type;
            return try self.keyedStoreValueAt(seed_store, column_idx);
        }
        if (derivedSequenceLen(seed)) |len| {
            if (len != column_count) return error.Type;
            return try self.derivedSequenceItemValue(seed, column_idx);
        }
        return self.shareValue(seed);
    }

    fn createHostTableValueFromKeyedColumnValues(self: *Session, source: *const HostKeyedStore, columns: []const Value) KError!Value {
        if (columns.len != keyedStoreNameCount(source)) return error.Type;

        var row_count: ?usize = null;
        const metadata = try self.allocator.alloc(HostKeyedColumnMetadata, columns.len);
        errdefer self.allocator.free(metadata);
        for (columns, 0..) |column, idx| {
            const len = numericVectorLen(column) orelse return error.Type;
            if (row_count) |existing| {
                if (existing != len) return error.Type;
            } else {
                row_count = len;
            }
            metadata[idx] = .{
                .kind = if (try self.boolNumericVectorValue(column)) .boolean else switch (valueNumericMode(column) orelse return error.Type) {
                    .int => .int,
                    .float => .float,
                },
                .validity = null,
            };
        }

        const names = try self.retainEscapedValue(source.names);
        errdefer self.releaseValue(names);
        const values = try self.createManagedHostBoxedArray(columns);
        errdefer self.releaseValue(values);
        var lookup = try self.createKeyedStoreLookupFromNamesValue(names);
        errdefer lookup.deinit(self.allocator);
        const owned_path = try self.allocator.dupe(u8, source.path);
        errdefer self.allocator.free(owned_path);
        return try self.createManagedKeyedStore(owned_path, true, names, values, metadata, .table, row_count orelse 0, lookup);
    }

    fn applyKeyedTableFoldScan(self: *Session, base: Value, args: []const Value, store: *const HostKeyedStore, collect: bool) KError!Value {
        const column_count = keyedStoreNameCount(store);
        if (keyedStoreValues(store).len() != column_count) return error.Type;

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, column_count);

        for (0..column_count) |column_idx| {
            const column = tableColumnData(store, column_idx);
            const folded = if (args.len == 1) blk: {
                break :blk try self.applyFoldDerived(base, &[_]Value{column}, collect);
            } else blk: {
                const seed = try self.keyedTableSeedForColumn(args[0], store, column_idx);
                defer self.releaseValue(seed);
                break :blk try self.applyFoldDerived(base, &[_]Value{ seed, column }, collect);
            };
            errdefer self.releaseValue(folded);
            try results.append(self.allocator, folded);
        }

        if (collect) return try self.createHostTableValueFromKeyedColumnValues(store, results.items);
        const values = try self.makeArrayFromValues(results.items);
        defer self.releaseValue(values);
        return try self.createHostDictValueFromKeySequenceValue(store.path, store.names, values);
    }

    fn tryApplyConcatScan(self: *Session, base: Value, args: []const Value, collect: bool) KError!?Value {
        if (!collect or args.len != 1 or base.tag() != .builtin or base.asBuiltin() != .concat) return null;
        const vector = args[0];
        const len = derivedSequenceLen(vector) orelse return null;

        var acc = try self.createManagedHostBoxedArray(&.{});
        errdefer self.releaseValue(acc);

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len);
        for (0..len) |idx| {
            const item = try self.derivedSequenceItemValue(vector, idx);
            const next = blk: {
                defer self.releaseValue(item);
                break :blk try self.concatValues(acc, item);
            };
            self.releaseValue(acc);
            acc = next;
            try self.appendDerivedScanResult(&results, acc);
        }

        defer self.releaseValue(acc);
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn applyFoldDerived(self: *Session, base: Value, args: []const Value, collect: bool) KError!Value {
        var profile_scope = self.beginSamplingProfileScope(if (collect) .apply_scan else .apply_fold);
        defer profile_scope.end();
        if (args.len == 0) return error.Arity;
        if (self.shouldTryHostFoldBeforeBackend(base, args, collect)) {
            if (try self.tryFastHostFoldDerived(base, args, collect)) |value| {
                self.noteHostFoldScanFast(collect);
                return value;
            }
        }
        if (try self.tryFastBackendFoldDerived(base, args, collect)) |value| return value;
        if (try self.tryFastStructuralFoldDerived(base, args, collect)) |value| return value;
        if (try self.tryFastHostFoldDerived(base, args, collect)) |value| {
            self.noteHostFoldScanFast(collect);
            return value;
        }
        if (base.tag() == .builtin) {
            self.noteHostFoldScanMiss(self.classifyHostFoldScanMiss(base.asBuiltin(), args, collect));
        }
        if (try self.tryApplyControlledFoldDerived(base, args, collect)) |value| return value;
        if (try self.tryApplyIdentityFoldScan(base, args, collect)) |value| return value;
        if (try self.tryApplyKeyedDictFoldScan(base, args, collect)) |value| return value;
        if (try self.tryApplyConcatScan(base, args, collect)) |value| return value;
        if (comptime enable_probe_instrumentation) {
            if (collect) {
                self.debug.apply_scan_generic_count += 1;
            } else {
                self.debug.apply_fold_generic_count += 1;
            }
        }

        if (args.len == 1) {
            const vector = args[0];
            const len = derivedSequenceLen(vector) orelse {
                if (!collect) return self.shareValue(vector);
                return error.Type;
            };
            if (len == 0) {
                if (try self.tryEmptyBuiltinFoldScanResult(base, args, collect, vector)) |value| return value;
                return error.Type;
            }

            var acc = try self.derivedSequenceItemValue(vector, 0);
            if (!collect) {
                for (1..len) |idx| {
                    const item = try self.derivedSequenceItemValue(vector, idx);
                    const next = blk: {
                        defer self.releaseValue(item);
                        break :blk try self.applyDerivedBase(base, &[_]Value{ acc, item });
                    };
                    self.releaseValue(acc);
                    acc = next;
                }
                return acc;
            }

            var results = std.ArrayList(Value).empty;
            defer {
                for (results.items) |value| self.releaseValue(value);
                results.deinit(self.allocator);
            }
            try results.ensureTotalCapacity(self.allocator, len);
            try self.appendDerivedScanResult(&results, acc);
            for (1..len) |idx| {
                const item = try self.derivedSequenceItemValue(vector, idx);
                const next = blk: {
                    defer self.releaseValue(item);
                    break :blk try self.applyDerivedBase(base, &[_]Value{ acc, item });
                };
                self.releaseValue(acc);
                acc = next;
                try self.appendDerivedScanResult(&results, acc);
            }
            defer self.releaseValue(acc);
            return try self.createManagedArrayLikeFromValues(results.items);
        }

        var len: ?usize = null;
        var sequence_template: ?Value = null;
        for (args[1..]) |arg| {
            const arg_len = derivedSequenceLen(arg) orelse {
                if (len == null) continue;
                return error.Type;
            };
            if (len) |existing| {
                if (existing != arg_len) return error.Type;
            } else {
                len = arg_len;
                sequence_template = arg;
            }
        }

        if (len == null) {
            const result = try self.applyDerivedBase(base, args);
            if (collect) {
                if (try self.callableProjectionArity(base)) |base_arity| {
                    if (base_arity > 2 and args.len >= base_arity) {
                        defer self.releaseValue(result);
                        return try self.enlistValue(result);
                    }
                }
            }
            return result;
        }
        if (len.? == 0) {
            if (sequence_template) |template| {
                if (try self.tryEmptyBuiltinFoldScanResult(base, args, collect, template)) |value| return value;
            }
            return error.Type;
        }

        var acc = self.shareValue(args[0]);
        if (!collect) {
            for (0..len.?) |idx| {
                var step_args_buf: [8]Value = undefined;
                if (args.len > step_args_buf.len) return error.Unsupported;
                step_args_buf[0] = acc;
                for (args[1..], 1..) |arg, arg_idx| step_args_buf[arg_idx] = try self.derivedSequenceItemValue(arg, idx);
                const next = blk: {
                    defer self.releaseDerivedStepArgs(args, step_args_buf[0..args.len], 1);
                    break :blk try self.applyDerivedBase(base, step_args_buf[0..args.len]);
                };
                self.releaseValue(acc);
                acc = next;
            }
            return acc;
        }

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len.?);
        for (0..len.?) |idx| {
            var step_args_buf: [8]Value = undefined;
            if (args.len > step_args_buf.len) return error.Unsupported;
            step_args_buf[0] = acc;
            for (args[1..], 1..) |arg, arg_idx| step_args_buf[arg_idx] = try self.derivedSequenceItemValue(arg, idx);
            const next = blk: {
                defer self.releaseDerivedStepArgs(args, step_args_buf[0..args.len], 1);
                break :blk try self.applyDerivedBase(base, step_args_buf[0..args.len]);
            };
            self.releaseValue(acc);
            acc = next;
            try self.appendDerivedScanResult(&results, acc);
        }
        defer self.releaseValue(acc);
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn applyEachRightDerived(self: *Session, base: Value, args: []const Value) KError!Value {
        var profile_scope = self.beginSamplingProfileScope(.apply_each_right);
        defer profile_scope.end();
        if (args.len != 2) return error.Arity;
        if (try self.tryFastHostEachRightStringContains(base, args[0], args[1])) |value| {
            if (comptime enable_probe_instrumentation) self.debug.apply_each_right_fast_string_contains_count += 1;
            return value;
        }
        if (try self.tryFastDenseEachRightDerived(base, args)) |value| return value;
        if (comptime enable_probe_instrumentation) self.debug.apply_each_right_generic_count += 1;
        const len = eachSequenceLen(args[1]) orelse return try self.applyDerivedBase(base, args);
        const preserved_left = try self.retainEscapedValue(args[0]);
        defer self.releaseValue(preserved_left);

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len);
        for (0..len) |idx| {
            const item = try self.eachSequenceItemValue(args[1], idx);
            const result = blk: {
                defer self.releaseValue(item);
                break :blk try self.applyDerivedBase(base, &[_]Value{ preserved_left, item });
            };
            try results.append(self.allocator, result);
        }
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn tryFastDenseEachRightDerived(self: *Session, base: Value, args: []const Value) KError!?Value {
        if (args.len != 2) return null;
        if (args[1].tag() != .array) {
            self.noteDenseEachRightMiss(.non_vector_right);
            return null;
        }
        if (valueNonVectorNumericShape(args[1]) != null) {
            self.noteDenseEachRightMiss(.non_vector_right);
            return null;
        }
        const kind = try self.classifyDenseElementwiseBaseRuntime(base) orelse {
            self.noteDenseEachRightMiss(.unsupported_base);
            return null;
        };
        const len = derivedSequenceLen(args[1]) orelse return null;
        const preserved_left = try self.retainEscapedValue(args[0]);
        defer self.releaseValue(preserved_left);
        if (self.debugDetailedProbeActive()) self.debug.apply_each_right_fast_dense_count += 1;

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len);
        for (0..len) |idx| {
            const item = try self.derivedSequenceItemValue(args[1], idx);
            const result = blk: {
                defer self.releaseValue(item);
                break :blk try self.applyDenseElementwiseKind(kind, preserved_left, item);
            };
            try results.append(self.allocator, result);
        }
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn tryFastHostEachRightStringContains(self: *Session, base: Value, left: Value, right: Value) KError!?Value {
        if (base.tag() != .builtin or base.asBuiltin() != .contains) return null;
        const needle = stringBytes(left) orelse {
            if (self.debugDetailedProbeActive()) self.debug.each_right_fast_string_contains_miss_non_string_left_count += 1;
            return null;
        };
        if (right.tag() != .array) {
            if (self.debugDetailedProbeActive()) self.debug.each_right_fast_string_contains_miss_non_string_right_count += 1;
            return null;
        }
        return switch (right.arrayKind()) {
            .host_string_list => try self.fastHostStringListContainsEachRight(needle, right.asHostStringList()),
            .host_boxed_array => try self.fastHostBoxedStringContainsEachRight(needle, right.asHostBoxedArray().items),
            else => blk: {
                if (self.debugDetailedProbeActive()) self.debug.each_right_fast_string_contains_miss_non_string_right_count += 1;
                break :blk null;
            },
        };
    }

    fn fastHostStringListContainsEachRight(self: *Session, needle: []const u8, list: *const HostStringList) KError!Value {
        const out = try self.allocator.alloc(bool, list.len);
        defer self.allocator.free(out);
        if (needle.len == 0) {
            @memset(out, true);
            return try self.createManagedHostBitArray(out);
        }
        switch (list.storage) {
            .eager => |items| {
                for (items, 0..) |item, idx| {
                    out[idx] = containsHostStringSlice(hostStringPieceBytes(list.base, item), needle);
                }
            },
            .split_scalar => |lazy| {
                const base = list.base orelse return error.Internal;
                const src = hostTextBytes(base);
                var piece_idx: usize = 0;
                var start: usize = 0;
                while (piece_idx < out.len) {
                    const sep_idx = std.mem.indexOfScalarPos(u8, src, start, lazy.sep) orelse break;
                    out[piece_idx] = containsHostStringSlice(src[start..sep_idx], needle);
                    piece_idx += 1;
                    start = sep_idx + 1;
                }
                if (piece_idx < out.len) out[piece_idx] = containsHostStringSlice(src[start..], needle);
            },
        }
        return try self.createManagedHostBitArray(out);
    }

    fn fastHostBoxedStringContainsEachRight(self: *Session, needle: []const u8, items: []const Value) KError!?Value {
        const out = try self.allocator.alloc(bool, items.len);
        defer self.allocator.free(out);
        if (needle.len == 0) {
            @memset(out, true);
            return try self.createManagedHostBitArray(out);
        }
        for (items, 0..) |item, idx| {
            const haystack = stringBytes(item) orelse return null;
            out[idx] = containsHostStringSlice(haystack, needle);
        }
        return try self.createManagedHostBitArray(out);
    }

    fn tryFastRowListInnerProductEachLeft(self: *Session, left: Value, right: Value) KError!?Value {
        if (left.tag() != .array or left.arraySubkind() != .host_boxed_array) return null;
        const rows = left.asHostBoxedArray();
        if (rows.len() == 0) return null;

        const right_len = numericVectorLen(right) orelse return null;
        var result_mode = valueNumericMode(right) orelse return null;
        for (rows.items) |row| {
            const row_len = numericVectorLen(row) orelse return null;
            if (row_len != right_len) return error.Type;
            const row_mode = valueNumericMode(row) orelse return null;
            if (row_mode == .float) result_mode = .float;
        }

        const right_view = try hostDenseView(self, right);
        if (result_mode == .float) {
            const out = try self.allocManagedHostFloatResult(rows.len());
            for (rows.items, 0..) |row, row_idx| {
                const row_view = try hostDenseView(self, row);
                var acc: f64 = 0.0;
                for (0..right_len) |col_idx| {
                    acc += (try hostDenseViewFloatItem(row_view, col_idx)) *
                        (try hostDenseViewFloatItem(right_view, col_idx));
                }
                out.items[row_idx] = acc;
            }
            return out.value();
        }

        var out = try self.allocManagedHostIntResult(.int64, rows.len());
        for (rows.items, 0..) |row, row_idx| {
            const row_view = try hostDenseView(self, row);
            var acc: i128 = 0;
            for (0..right_len) |col_idx| {
                acc += @as(i128, try hostDenseViewIntItem(row_view, col_idx)) *
                    @as(i128, try hostDenseViewIntItem(right_view, col_idx));
            }
            try out.set(row_idx, std.math.cast(i64, acc) orelse return error.Unsupported);
        }
        return out.value();
    }

    fn applyEachLeftDerived(self: *Session, base: Value, args: []const Value) KError!Value {
        var profile_scope = self.beginSamplingProfileScope(.apply_each_left);
        defer profile_scope.end();
        if (args.len < 2) return error.Arity;
        if (base.tag() == .closure) {
            if (try self.innerProductInfoFromClosure(base.asClosure())) |info| {
                if (args.len == 2 and info.reduce == .add and info.map == .mul and valueIsRenderableMatrixLike(args[0])) {
                    return try self.applyMatmulValues(args[0], args[1]);
                }
                if (args.len == 2 and info.reduce == .add and info.map == .mul) {
                    if (try self.tryFastRowListInnerProductEachLeft(args[0], args[1])) |result| return result;
                }
            }
        }
        if (comptime enable_probe_instrumentation) self.debug.apply_each_left_generic_count += 1;
        const len = eachSequenceLen(args[0]) orelse return try self.applyDerivedBase(base, args);
        if (args.len > max_direct_apply_args) return error.Unsupported;
        const preserved_right = try self.retainArgs(args[1..]);
        defer self.releaseArgs(preserved_right);

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len);
        for (0..len) |idx| {
            const item = try self.eachSequenceItemValue(args[0], idx);
            var step_args_buf: [max_direct_apply_args]Value = undefined;
            step_args_buf[0] = item;
            @memcpy(step_args_buf[1 .. 1 + preserved_right.len], preserved_right);
            const result = blk: {
                defer self.releaseValue(item);
                break :blk try self.applyDerivedBase(base, step_args_buf[0 .. 1 + preserved_right.len]);
            };
            try results.append(self.allocator, result);
        }
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn applyRollingEachPriorDerived(self: *Session, base: Value, seed: Value, vector: Value) KError!Value {
        if (base.tag() == .builtin and base.asBuiltin() == .equal) {
            if (stringSourceInfo(vector)) |source| return try self.equalEachPriorStringValue(source.bytes());
        }
        if (try self.tryFastBitRollingEachPriorDerived(base, seed, vector)) |result| return result;
        if (vector.tag() == .array and vector.arrayKind() == .host_keyed_store) {
            const store = vector.asHostKeyedStore();
            if (store.layout == .dict) return try self.applyRollingEachPriorDictDerived(base, seed, store);
        }

        const len = eachSequenceLen(vector) orelse return error.Type;
        if (comptime enable_probe_instrumentation) {
            self.debug.apply_each_prior_generic_count += 1;
            self.debug.apply_each_prior_generic_element_count += len;
        }
        if (len == 0) return try self.createManagedHostIntArray(&.{});

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len);

        var prior = try self.retainEscapedValue(seed);
        for (0..len) |idx| {
            const current = try self.eachSequenceItemValue(vector, idx);
            errdefer self.releaseValue(current);
            const value = try self.applyDerivedBase(base, &[_]Value{ current, prior });
            self.releaseValue(prior);
            prior = current;
            try results.append(self.allocator, value);
        }
        defer self.releaseValue(prior);
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn equalEachPriorStringValue(self: *Session, bytes: []const u8) KError!Value {
        if (bytes.len == 0) return try self.createManagedHostIntArray(&.{});
        const out = try self.allocHostBitArray(.managed, bytes.len);
        bitSet(out.words, 0, false);
        var stats = BitSequenceStats{ .saw_zero = true, .has_prev = true, .prev = false };
        for (bytes[1..], 1..) |byte, idx| {
            const bit = byte == bytes[idx - 1];
            bitSet(out.words, idx, bit);
            stats.note(bit);
        }
        const metadata = stats.metadata();
        return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
    }

    fn applyRollingEachPriorDictDerived(self: *Session, base: Value, seed: Value, store: *const HostKeyedStore) KError!Value {
        const len = keyedStoreValuesValueCount(store.values) orelse return error.Internal;
        if (comptime enable_probe_instrumentation) {
            self.debug.apply_each_prior_generic_count += 1;
            self.debug.apply_each_prior_generic_element_count += len;
        }
        if (len == 0) {
            const values_value = try self.createManagedHostIntArray(&.{});
            defer self.releaseValue(values_value);
            return try self.createDictLikeValue(store, values_value);
        }

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len);

        var prior = try self.retainEscapedValue(seed);
        for (0..len) |idx| {
            const current = try self.keyedStoreValueAt(store, idx);
            errdefer self.releaseValue(current);
            const value = try self.applyDerivedBase(base, &[_]Value{ current, prior });
            self.releaseValue(prior);
            prior = current;
            try results.append(self.allocator, value);
        }
        defer self.releaseValue(prior);

        const values_value = try self.createManagedArrayLikeFromValues(results.items);
        defer self.releaseValue(values_value);
        return try self.createDictLikeValue(store, values_value);
    }

    fn tryFastBitRollingEachPriorDerived(self: *Session, base: Value, seed: Value, vector: Value) KError!?Value {
        if (base.tag() != .builtin) return null;
        const op = base.asBuiltin();
        switch (op) {
            .minimum, .mul, .maximum, .equal => {},
            else => return null,
        }
        const len = numericVectorLen(vector) orelse return null;
        const bits = valueNumericBitSlice(vector) orelse return null;
        if (bits.len != len) return error.Type;
        const BitSeedInfo = struct {
            bit: bool,
            force_first_false: bool,
        };
        const seed_info: BitSeedInfo = blk: {
            if (scalarIntLikeValue(seed)) |seed_int| {
                if (seed_int != 0 and seed_int != 1) {
                    if (op == .equal) break :blk .{ .bit = false, .force_first_false = true };
                    return null;
                }
                break :blk .{ .bit = seed_int == 1, .force_first_false = false };
            }
            if (op != .equal) return null;
            const seed_numeric = scalarNumericValue(seed) catch return null;
            if (seed_numeric == 0.0) break :blk .{ .bit = false, .force_first_false = false };
            if (seed_numeric == 1.0) break :blk .{ .bit = true, .force_first_false = false };
            break :blk .{ .bit = false, .force_first_false = true };
        };

        if (comptime enable_probe_instrumentation) {
            self.debug.apply_each_prior_fast_bit_count += 1;
            self.debug.apply_each_prior_fast_bit_element_count += len;
        }

        const out = try self.allocHostBitArrayUninitialized(.managed, bits.len);
        var carry: u64 = @intFromBool(seed_info.bit);
        for (bits.words, 0..) |_, word_idx| {
            const word = bitWordMasked(bits.words, bits.len, word_idx);
            const prior = (word << 1) | carry;
            var result = switch (op) {
                .minimum, .mul => word & prior,
                .maximum => word | prior,
                .equal => ~(word ^ prior),
                else => unreachable,
            };
            if (word_idx == 0 and seed_info.force_first_false) result &= ~@as(u64, 1);
            out.words[word_idx] = result;
            carry = word >> 63;
        }
        bitClearUnusedTail(out.words, out.len);
        return try self.finishManagedHostBitAlloc(out, host_dense_flag_normalized, .{ .min = 0, .max = 1 });
    }

    fn applyStencilEachPriorDerived(self: *Session, base: Value, left: Value, vector: Value) KError!Value {
        const raw_window_len = scalarIntLikeValue(left) orelse return error.Type;
        if (raw_window_len < 0) return error.Type;
        const sequence_len = eachSequenceLen(vector) orelse return error.Type;
        const window_len: usize = @intCast(raw_window_len);
        const result_len: usize = if (window_len == 0)
            sequence_len + 1
        else if (window_len > sequence_len)
            0
        else
            sequence_len + 1 - window_len;

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, result_len);

        const count_value = try self.intValue(raw_window_len);
        defer self.releaseValue(count_value);

        for (0..result_len) |start| {
            const start_i64 = std.math.cast(i64, start) orelse return error.Unsupported;
            const start_value = try self.intValue(start_i64);
            defer self.releaseValue(start_value);
            const dropped = try self.dropValues(start_value, vector);
            defer self.releaseValue(dropped);
            const window = try self.takeValues(count_value, dropped);
            const value = blk: {
                defer self.releaseValue(window);
                break :blk try self.applyDerivedBase(base, &[_]Value{window});
            };
            try results.append(self.allocator, value);
        }
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn emptyWindowResultValue(self: *Session, window_len: i64, vector: Value) KError!Value {
        const count_value = try self.intValue(window_len);
        defer self.releaseValue(count_value);
        const sample = try self.takeValues(count_value, vector);
        defer self.releaseValue(sample);
        const prototype = (try self.prototypeValueForTake(sample)) orelse try self.prototypeLikeValue(sample);
        defer self.releaseValue(prototype);
        return try self.createManagedHostBoxedArrayWithPrototype(&.{}, prototype);
    }

    fn windowEachPriorValue(self: *Session, window_len_raw: i64, vector: Value) KError!Value {
        if (window_len_raw < 0) return error.Type;
        const sequence_len = eachSequenceLen(vector) orelse return error.Type;
        const window_len: usize = @intCast(window_len_raw);
        if (window_len > sequence_len) return try self.emptyWindowResultValue(window_len_raw, vector);

        const result_len: usize = if (window_len == 0) sequence_len + 1 else sequence_len + 1 - window_len;
        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, result_len);

        const count_value = try self.intValue(window_len_raw);
        defer self.releaseValue(count_value);

        for (0..result_len) |start| {
            const start_i64 = std.math.cast(i64, start) orelse return error.Unsupported;
            const start_value = try self.intValue(start_i64);
            defer self.releaseValue(start_value);
            const dropped = try self.dropValues(start_value, vector);
            defer self.releaseValue(dropped);
            try results.append(self.allocator, try self.takeValues(count_value, dropped));
        }
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn applyEachPriorDerived(self: *Session, base: Value, args: []const Value) KError!Value {
        return switch (args.len) {
            1 => blk: {
                if (eachPriorUsesMonadicBase(base)) return error.Arity;
                if (scalarIntLikeValue(base)) |window_len| break :blk try self.windowEachPriorValue(window_len, args[0]);
                const sequence_len = if (args[0].tag() == .array and args[0].arrayKind() == .host_keyed_store and args[0].asHostKeyedStore().layout == .dict)
                    keyedStoreValuesValueCount(args[0].asHostKeyedStore().values) orelse return error.Internal
                else
                    eachSequenceLen(args[0]) orelse return error.Type;
                if (sequence_len == 0) return try self.createManagedHostIntArray(&.{});
                const seed = try self.eachPriorImplicitSeedValue(base, args[0]);
                defer self.releaseValue(seed);
                break :blk try self.applyRollingEachPriorDerived(base, seed, args[0]);
            },
            2 => if (eachPriorUsesMonadicBase(base))
                try self.applyStencilEachPriorDerived(base, args[0], args[1])
            else
                try self.applyRollingEachPriorDerived(base, args[0], args[1]),
            else => error.Arity,
        };
    }

    fn classifyHostFoldScanMiss(self: *Session, op: BuiltinId, args: []const Value, collect: bool) DebugHostFoldScanMiss {
        if (args.len == 0 or args.len > 2) return .unsupported_input;
        if (collect and op != .add and op != .minimum and op != .maximum) return .unsupported_builtin;
        switch (op) {
            .add, .sub, .mul, .minimum, .maximum => {},
            else => return .unsupported_builtin,
        }
        if (self.dense_backend_override == .mlx) return .backend_override;

        const value = args[args.len - 1];
        if (!collect) {
            if (shapedNumericHandle(value)) |handle| {
                if (denseReduceScanActualBackend(self, false, value) != .host) return .planner_non_host;
                const outer_len: usize = @intCast(handle.shape[0]);
                if (outer_len <= 1) return .preserve_generic_semantics;
                return .unsupported_input;
            }
        }

        if (valueNonVectorNumericShape(value) != null) return .non_numeric_or_shape;
        if ((op == .minimum or op == .maximum) and denseReduceScanActualBackend(self, false, value) != .host) {
            return .planner_non_host;
        }

        if (value.tag() == .array and value.arrayKind() == .numeric_array) {
            const handle = value.asNumericArray();
            if (numericArrayIsVectorRangeIota(handle)) {
                if (numericArrayRangeLen(handle) <= 1) return .preserve_generic_semantics;
                return .unsupported_input;
            }
        }

        const array = hostDenseIfPresent(value) orelse return .unsupported_input;
        if (array.len() <= 1) return .preserve_generic_semantics;
        return .unsupported_input;
    }

    fn checkedSelectorDyad(op: BuiltinId, left: i64, right: i64) KError!i64 {
        const result = switch (op) {
            .add => @addWithOverflow(left, right),
            .sub => @subWithOverflow(left, right),
            else => return error.Type,
        };
        if (result[1] != 0) return error.Type;
        return result[0];
    }

    fn recordIndexedAssign(self: *Session, target: IndexedAssignTarget) void {
        if (comptime enable_probe_instrumentation) {
            self.debug.indexed_assign_count += 1;
            switch (target) {
                .global => self.debug.indexed_assign_global_count += 1,
                .local => self.debug.indexed_assign_local_count += 1,
            }
        }
    }

    fn releaseOwnedValues(self: *Session, values: []const Value) void {
        for (values) |value| self.releaseValue(value);
    }

    fn tryApplyOwnedClosureArgs(self: *Session, closure: *const Closure, args: []const Value) KError!?Value {
        const may_derived = closureMayUseDerivedApply(closure);
        switch (args.len) {
            1 => {
                if (may_derived) {
                    if (try self.applyDerivedClosure(closure, args)) |result| return result;
                }
                return null;
            },
            2 => {
                if (may_derived) {
                    if (try self.tryApplyStructuredDerivedClosure2(closure, args[0], args[1])) |result| return result;
                    if (try self.applyDerivedClosure(closure, args)) |result| return result;
                }
                return null;
            },
            3 => {
                if (may_derived) {
                    if (try self.applyDerivedClosure(closure, args)) |result| return result;
                }
                return null;
            },
            else => return if (may_derived) try self.applyDerivedClosure(closure, args) else null,
        }
    }

    fn callableProjectionArity(self: *Session, value: Value) KError!?usize {
        return switch (value.tag()) {
            .builtin => if (builtinSupportsDyad(value.asBuiltin()))
                2
            else if (builtinSupportsMonad(value.asBuiltin()))
                1
            else
                null,
            .closure => blk: {
                const closure = value.asClosure();
                if (try self.monadicBuiltinFromClosure(closure)) |_| break :blk 1;
                if (projectionHoleCount(closure)) |hole_count| break :blk hole_count;
                if (try self.innerProductInfoFromClosure(closure)) |_| break :blk 2;
                if (try self.compositionInfoFromClosure(closure)) |_| break :blk 1;
                if (closureDerivedKind(closure)) |kind| {
                    break :blk try self.derivedProjectionArity(kind, closure.captures);
                }
                break :blk closure.code.arity;
            },
            .array => 1,
            else => null,
        };
    }

    fn derivedProjectionArity(self: *Session, kind: DerivedVerbKind, captures: []const Value) KError!?usize {
        if (captures.len != 1) return null;
        const base_arity = (try self.callableProjectionArity(captures[0])) orelse return null;
        return switch (kind) {
            .fold, .scan, .each_prior => if (base_arity == 2) 1 else base_arity,
            .each, .each_right, .each_left => base_arity,
            .grad, .valuegrad => null,
        };
    }

    fn tryProjectDerivedCallUnderApplication(self: *Session, callee: Value, kind: DerivedVerbKind, captures: []const Value, args: []const Value) KError!?Value {
        if (args.len == 0) return null;
        const arity = (try self.derivedProjectionArity(kind, captures)) orelse return null;
        if (args.len >= arity) return null;
        if (arity > 63) return error.Unsupported;

        const slot_values = try self.scratch_arena.allocator().alloc(Value, arity);
        var hole_mask: u64 = 0;
        for (0..arity) |idx| {
            if (idx < args.len) {
                slot_values[idx] = args[idx];
            } else {
                slot_values[idx] = Value.fromBool(false);
                hole_mask |= @as(u64, 1) << @intCast(idx);
            }
        }
        return try self.allocManagedProjectionClosure(callee, @intCast(arity), hole_mask, slot_values);
    }

    fn directDerivedKindProjectsUnderApplication(kind: DerivedVerbKind) bool {
        return switch (kind) {
            .fold, .scan => true,
            .each, .each_right, .each_left, .each_prior, .grad, .valuegrad => false,
        };
    }

    fn tryProjectDirectDerivedCallUnderApplication(self: *Session, base: Value, kind: DerivedVerbKind, captures: []const Value, args: []const Value) KError!?Value {
        if (!directDerivedKindProjectsUnderApplication(kind)) return null;
        if (args.len == 0) return null;
        const arity = (try self.derivedProjectionArity(kind, captures)) orelse return null;
        if (args.len >= arity) return null;
        const callee = Value.closure(try self.allocDerivedClosure(kind, base));
        defer self.releaseValue(callee);
        return try self.tryProjectDerivedCallUnderApplication(callee, kind, captures, args);
    }

    fn tryProjectDerivedClosureUnderApplication(self: *Session, callee: Value, closure: *const Closure, args: []const Value) KError!?Value {
        const kind = closureDerivedKind(closure) orelse return null;
        return try self.tryProjectDerivedCallUnderApplication(callee, kind, closure.captures, args);
    }

    fn applyGlobalIndexArrayValue(self: *Session, callee: Value, selector: Value) KError!?Value {
        if (callee.tag() != .array) return null;
        if (callee.arrayKind() == .host_keyed_store and callee.asHostKeyedStore().layout == .dict) {
            return try self.applyArrayCall1(callee, selector);
        }
        if (scalarIntLikeValue(selector)) |raw_index| return try self.applyArrayCall1Scalar(callee, raw_index);
        return try self.applyArrayCall1(callee, selector);
    }

    const InsertBounds = struct {
        start: usize,
        end: usize,
    };

    fn insertBoundsFromSelector(selector: Value, len: usize) KError!InsertBounds {
        if (scalarIntLikeValue(selector)) |raw| {
            if (raw < 0 or raw > @as(i64, @intCast(len))) return error.Type;
            const idx: usize = @intCast(raw);
            return .{ .start = idx, .end = idx };
        }

        const selector_len = numericVectorLen(selector) orelse return error.Type;
        if (selector_len != 2) return error.Type;
        const start_raw = try numericIntAt(selector, 0);
        const end_raw = try numericIntAt(selector, 1);
        if (start_raw < 0 or end_raw < start_raw or end_raw > @as(i64, @intCast(len))) return error.Type;
        return .{ .start = @intCast(start_raw), .end = @intCast(end_raw) };
    }

    fn insertNumericValueCount(value: Value) KError!usize {
        if (numericVectorLen(value)) |len| return len;
        if (scalarNumericFloatValue(value) != null or value.tag() == .float32) return 1;
        return error.Type;
    }

    fn insertNumericFloatAt(value: Value, idx: usize) KError!f64 {
        if (numericVectorLen(value) != null) {
            return switch (valueNumericMode(value) orelse return error.Type) {
                .int => @floatFromInt(try numericIntAt(value, idx)),
                .float => try numericFloatAt(value, idx),
            };
        }
        return switch (value.tag()) {
            .int => @floatFromInt(value.asInt()),
            .bool => @floatFromInt(@intFromBool(value.asBool())),
            .float32 => @floatCast(value.asFloat32()),
            .float => value.asFloat(),
            else => error.Type,
        };
    }

    fn insertNumericIntAt(value: Value, idx: usize) KError!i64 {
        if (numericVectorLen(value) != null) return try numericIntAt(value, idx);
        return scalarIntLikeValue(value) orelse error.Type;
    }

    fn insertNumericValue(self: *Session, source: Value, selector: Value, replacement: Value) KError!Value {
        const source_len = numericVectorLen(source) orelse return error.Type;
        const bounds = try insertBoundsFromSelector(selector, source_len);
        const replacement_len = try insertNumericValueCount(replacement);
        const out_len = source_len - (bounds.end - bounds.start) + replacement_len;
        const source_mode = valueNumericMode(source) orelse return error.Type;
        const replacement_mode = valueNumericMode(replacement) orelse return error.Type;
        const out_mode: HostDenseElem = if (source_mode == .float or replacement_mode == .float) .float else .int;

        switch (out_mode) {
            .int => {
                const out = try self.allocator.alloc(i64, out_len);
                defer self.allocator.free(out);
                var out_idx: usize = 0;
                for (0..bounds.start) |idx| {
                    out[out_idx] = try numericIntAt(source, idx);
                    out_idx += 1;
                }
                for (0..replacement_len) |idx| {
                    out[out_idx] = try insertNumericIntAt(replacement, idx);
                    out_idx += 1;
                }
                for (bounds.end..source_len) |idx| {
                    out[out_idx] = try numericIntAt(source, idx);
                    out_idx += 1;
                }
                return try self.createManagedHostIntArray(out);
            },
            .float => {
                const out = try self.allocator.alloc(f64, out_len);
                defer self.allocator.free(out);
                var out_idx: usize = 0;
                for (0..bounds.start) |idx| {
                    out[out_idx] = try insertNumericFloatAt(source, idx);
                    out_idx += 1;
                }
                for (0..replacement_len) |idx| {
                    out[out_idx] = try insertNumericFloatAt(replacement, idx);
                    out_idx += 1;
                }
                for (bounds.end..source_len) |idx| {
                    out[out_idx] = try insertNumericFloatAt(source, idx);
                    out_idx += 1;
                }
                return try self.createManagedHostFloatArray(out);
            },
        }
    }

    fn tryFastHostMinMaxScan(self: *Session, op: BuiltinId, args: []const Value) KError!?Value {
        if (!enable_host_minmax_scan_fast_path) return null;
        if (args.len == 0 or args.len > 2) return null;
        if (self.dense_backend_override == .mlx) return null;

        const vector = args[args.len - 1];
        const shape = valueNonVectorNumericShape(vector);
        if (args.len == 1) {
            if (try self.tryFastHostMinMaxScanConstantBit(vector)) |result| {
                noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                return result;
            }
        }

        const view = hostDenseView(self, vector) catch return null;
        const len = switch (view) {
            .int_array => |items| hostIntDenseViewLen(items),
            .float_array => |items| hostFloatDenseViewLen(items),
            else => return null,
        };
        if (args.len == 1 and len == 0) return null;
        if (len <= 1) return null;
        if (args.len == 1) {
            switch (view) {
                .int_array => |items| {
                    if (try self.tryFastHostMinMaxScanOrderedInt(op, vector, items, shape)) |result| {
                        noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                        return result;
                    }
                },
                .float_array => |items| {
                    if (try self.tryFastHostMinMaxScanOrderedFloat(op, vector, items, shape)) |result| {
                        noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                        return result;
                    }
                },
                else => {},
            }
        }
        if (shape != null and args.len == 1) {
            switch (view) {
                .int_array => |items| {
                    if (hostIntDenseViewBitSlice(items)) |bits| {
                        const handle = shapedNumericHandle(vector) orelse return null;
                        noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                        return try self.fastHostFirstAxisBitMinMaxScan(handle, bits, op);
                    }
                    const range = hostIntDenseValueRange(vector, items);
                    if (range.min >= 0 and range.max <= 1) {
                        const handle = shapedNumericHandle(vector) orelse return null;
                        noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                        const host = numericHostArrayValue(self, vector) catch null;
                        if (host) |array| switch (array.storage) {
                            .bit => |words| {
                                const bits = HostBitSlice{ .words = hostDenseLogicalBitWords(array, words), .len = array.logical_len };
                                return try self.fastHostFirstAxisBitMinMaxScan(handle, bits, op);
                            },
                            else => {},
                        };
                        return try self.fastHostFirstAxisBitLikeMinMaxScan(handle, items, op);
                    }
                },
                else => {},
            }
        }
        if (shape != null) return null;

        switch (view) {
            .int_array => |items| {
                if (hostIntDenseViewBitSlice(items)) |bits| {
                    if (args.len == 1) {
                        noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                        return try self.fastHostBitMinMaxScan(op, bits, null);
                    }
                    if (scalarIntLikeValue(args[0])) |seed_int| {
                        if (bitMinMaxScanResultIsBit(op, seed_int)) {
                            noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                            return try self.fastHostBitMinMaxScan(op, bits, seed_int);
                        }
                        noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                        return try self.fastHostMinMaxScanInt(vector, items, op, seed_int);
                    }
                    const seed_float = scalarNumericValue(args[0]) catch return null;
                    noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                    return try self.fastHostMinMaxScanFloatFromInt(items, op, seed_float);
                }

                if (args.len == 1) {
                    noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                    return try self.fastHostMinMaxScanInt(vector, items, op, null);
                }
                if (scalarIntLikeValue(args[0])) |seed_int| {
                    noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                    return try self.fastHostMinMaxScanInt(vector, items, op, seed_int);
                }
                const seed_float = scalarNumericValue(args[0]) catch return null;
                noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                return try self.fastHostMinMaxScanFloatFromInt(items, op, seed_float);
            },
            .float_array => |items| {
                const storage_kind = hostFloatDenseViewStorageKind(items) orelse .float64;
                if (args.len == 1) {
                    noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                    if (storage_kind == .float32) return try self.fastHostMinMaxScanFloat32(vector, items, op, null);
                    return try self.fastHostMinMaxScanFloat(vector, items, op, null);
                }
                const seed = scalarNumericValue(args[0]) catch return null;
                const result_kind = mergeHostFloatStorageKind(storage_kind, scalarFloatStorageKind(args[0])) orelse .float64;
                noteDensePlanDecision(self, .scan, .host, .host, .host_fast_kernel);
                if (result_kind == .float32) return try self.fastHostMinMaxScanFloat32(vector, items, op, @floatCast(seed));
                return try self.fastHostMinMaxScanFloat(vector, items, op, seed);
            },
            else => return null,
        }
    }

    fn insertStringValue(self: *Session, source: Value, selector: Value, replacement: Value) KError!Value {
        const source_bytes = stringBytes(source) orelse return error.Type;
        const replacement_bytes = stringBytes(replacement) orelse return error.Type;
        const bounds = try insertBoundsFromSelector(selector, source_bytes.len);
        const out_len = source_bytes.len - (bounds.end - bounds.start) + replacement_bytes.len;
        const out = try self.allocator.alloc(u8, out_len);
        defer self.allocator.free(out);
        @memcpy(out[0..bounds.start], source_bytes[0..bounds.start]);
        @memcpy(out[bounds.start .. bounds.start + replacement_bytes.len], replacement_bytes);
        @memcpy(out[bounds.start + replacement_bytes.len ..], source_bytes[bounds.end..]);
        if (out.len == 1) return try self.managedHostCharVector(out);
        return try self.managedHostString(out);
    }

    fn insertSymbolReplacementCount(value: Value) KError!usize {
        if (symbolBytes(value) != null) return 1;
        if (value.tag() == .array and value.arrayKind() == .host_symbol_list) return value.asHostStringList().len;
        return error.Type;
    }

    fn insertSymbolReplacementBytes(value: Value, idx: usize) KError![]const u8 {
        if (symbolBytes(value)) |bytes| {
            if (idx != 0) return error.Internal;
            return bytes;
        }
        if (value.tag() == .array and value.arrayKind() == .host_symbol_list) return try hostStringListItemBytes(value.asHostStringList(), idx);
        return error.Type;
    }

    fn insertSymbolListValue(self: *Session, source: Value, selector: Value, replacement: Value) KError!Value {
        if (source.tag() != .array or source.arrayKind() != .host_symbol_list) return error.Type;
        const source_list = source.asHostStringList();
        const bounds = try insertBoundsFromSelector(selector, source_list.len);
        const replacement_len = try insertSymbolReplacementCount(replacement);
        const out_len = source_list.len - (bounds.end - bounds.start) + replacement_len;
        const out = try self.allocator.alloc([]const u8, out_len);
        defer self.allocator.free(out);
        var out_idx: usize = 0;
        for (0..bounds.start) |idx| {
            out[out_idx] = try hostStringListItemBytes(source_list, idx);
            out_idx += 1;
        }
        for (0..replacement_len) |idx| {
            out[out_idx] = try insertSymbolReplacementBytes(replacement, idx);
            out_idx += 1;
        }
        for (bounds.end..source_list.len) |idx| {
            out[out_idx] = try hostStringListItemBytes(source_list, idx);
            out_idx += 1;
        }
        return try self.createManagedHostSymbolListFromSlices(out);
    }

    fn insertBoxedReplacementCount(value: Value) usize {
        if (value.tag() == .array and value.arrayKind() == .host_boxed_array) return value.asHostBoxedArray().len();
        return 1;
    }

    fn insertBoxedReplacementValue(self: *Session, value: Value, idx: usize) KError!Value {
        if (value.tag() == .array and value.arrayKind() == .host_boxed_array) return try self.hostBoxedArrayIndexScalar(value.asHostBoxedArray(), @intCast(idx));
        if (idx != 0) return error.Internal;
        return try self.retainEscapedValue(value);
    }

    fn insertBoxedValue(self: *Session, source: Value, selector: Value, replacement: Value) KError!Value {
        if (source.tag() != .array or source.arrayKind() != .host_boxed_array) return error.Type;
        const source_array = source.asHostBoxedArray();
        const bounds = try insertBoundsFromSelector(selector, source_array.len());
        const replacement_len = insertBoxedReplacementCount(replacement);
        const out_len = source_array.len() - (bounds.end - bounds.start) + replacement_len;
        const out = try self.allocator.alloc(Value, out_len);
        defer self.allocator.free(out);
        var initialized: usize = 0;
        defer {
            for (out[0..initialized]) |value| self.releaseValue(value);
        }

        for (0..bounds.start) |idx| {
            out[initialized] = try self.hostBoxedArrayIndexScalar(source_array, @intCast(idx));
            initialized += 1;
        }
        for (0..replacement_len) |idx| {
            out[initialized] = try self.insertBoxedReplacementValue(replacement, idx);
            initialized += 1;
        }
        for (bounds.end..source_array.len()) |idx| {
            out[initialized] = try self.hostBoxedArrayIndexScalar(source_array, @intCast(idx));
            initialized += 1;
        }
        return try self.createManagedHostBoxedArray(out);
    }

    fn tableRangeValue(self: *Session, store: *const HostKeyedStore, start: usize, end: usize) KError!Value {
        if (end < start or end > store.row_count) return error.Type;
        const row_indices = try self.allocator.alloc(usize, end - start);
        defer self.allocator.free(row_indices);
        for (row_indices, start..) |*idx, row| idx.* = row;
        return try self.tableSelectRows(store, row_indices);
    }

    fn insertTableValue(self: *Session, source: Value, selector: Value, replacement: Value) KError!Value {
        if (source.tag() != .array or source.arrayKind() != .host_keyed_store) return error.Type;
        const source_store = source.asHostKeyedStore();
        if (source_store.layout != .table) return error.Type;
        const bounds = try insertBoundsFromSelector(selector, source_store.row_count);

        const replacement_table = blk: {
            if (replacement.tag() != .array or replacement.arrayKind() != .host_keyed_store) return error.Type;
            const replacement_store = replacement.asHostKeyedStore();
            break :blk switch (replacement_store.layout) {
                .table => try self.retainEscapedValue(replacement),
                .dict => try self.flipValue(replacement),
            };
        };
        defer self.releaseValue(replacement_table);
        const replacement_store = replacement_table.asHostKeyedStore();
        if (replacement_store.layout != .table) return error.Type;

        const prefix = try self.tableRangeValue(source_store, 0, bounds.start);
        defer self.releaseValue(prefix);
        const suffix = try self.tableRangeValue(source_store, bounds.end, source_store.row_count);
        defer self.releaseValue(suffix);

        const left = try self.concatTableValues(prefix.asHostKeyedStore(), replacement_store);
        defer self.releaseValue(left);
        return try self.concatTableValues(left.asHostKeyedStore(), suffix.asHostKeyedStore());
    }

    fn insertValue(self: *Session, source: Value, selector: Value, replacement: Value) KError!Value {
        if (stringBytes(source) != null) return try self.insertStringValue(source, selector, replacement);
        if (source.tag() == .array) {
            return switch (source.arrayKind()) {
                .host_symbol_list => try self.insertSymbolListValue(source, selector, replacement),
                .host_boxed_array => try self.insertBoxedValue(source, selector, replacement),
                .host_keyed_store => try self.insertTableValue(source, selector, replacement),
                else => if (valueNumericMode(source) != null)
                    try self.insertNumericValue(source, selector, replacement)
                else
                    error.Type,
            };
        }
        return error.Type;
    }

    fn builtinUsesGenericArityDispatch(op: BuiltinId) bool {
        return switch (op) {
            .prng,
            .grad,
            .valuegrad,
            .rope,
            .ropeflat,
            .ropecisflat,
            .rmsnorm,
            .layernorm,
            .gelu,
            .geluapprox,
            .mlpdense,
            .conv2d,
            .convtranspose2d,
            .upsamplenearest2d,
            .groupnorm,
            .softmax,
            .sdpa,
            .sam3boxrpb,
            .sdpamask,
            .sdpaflat,
            => false,
            else => true,
        };
    }

    fn applyBuiltinCall(self: *Session, op: BuiltinId, args: []const Value) KError!Value {
        var profile_scope = self.beginSamplingProfileScope(.apply_builtin);
        defer profile_scope.end();
        if (!builtinAvailable(op)) return error.Unsupported;
        if (op == .apply) {
            if (args.len < 2) return error.Arity;
            return try self.applyValue(args[0], args[1..]);
        }
        if (op == .prng) return try self.applyPrngBuiltin(args);
        if (op == .grad or op == .valuegrad) return try self.applyAutogradBuiltin(op, args);
        if (comptime runtime_has_mlx_builtin_surface) {
            if (op == .rope) return try self.applyRopeBuiltin(args);
            if (op == .ropeflat) return try self.applyRopeFlatBuiltin(args);
            if (op == .ropecisflat) return try self.applyRopeCisFlatBuiltin(args);
            if (op == .rmsnorm) return try self.applyRmsNormBuiltin(args);
            if (op == .layernorm) return try self.applyLayerNormBuiltin(args);
            if (op == .gelu) return try self.applyGeluBuiltin(args);
            if (op == .geluapprox) return try self.applyGeluApproxBuiltin(args);
            if (op == .mlpdense) return try self.applyMlpDenseBuiltin(args);
            if (op == .conv2d) return try self.applyConv2dBuiltin(args);
            if (op == .convtranspose2d) return try self.applyConvTranspose2dBuiltin(args);
            if (op == .upsamplenearest2d) return try self.applyUpsampleNearest2dBuiltin(args);
            if (op == .groupnorm) return try self.applyGroupNormBuiltin(args);
            if (op == .softmax) return try self.applySoftmaxBuiltin(args);
            if (op == .sdpa) return try self.applySdpaBuiltin(args);
            if (op == .sam3boxrpb) return try self.applySam3BoxRpbBuiltin(args);
            if (op == .sdpamask) return try self.applySdpaMaskBuiltin(args);
            if (op == .sdpaflat) return try self.applySdpaFlatBuiltin(args);
        } else switch (op) {
            .rope,
            .ropeflat,
            .ropecisflat,
            .rmsnorm,
            .layernorm,
            .gelu,
            .geluapprox,
            .mlpdense,
            .conv2d,
            .convtranspose2d,
            .upsamplenearest2d,
            .groupnorm,
            .softmax,
            .sdpa,
            .sam3boxrpb,
            .sdpamask,
            .sdpaflat,
            => return error.Unsupported,
            else => {},
        }
        return switch (args.len) {
            0 => error.Arity,
            1 => self.applyMonad(op, args[0]),
            2 => self.applyDyad(dyadicBuiltinForGenericCall(op), args[0], args[1]),
            3 => if (op == .unique or op == .find)
                self.insertValue(args[0], args[1], args[2])
            else if (op == .register)
                if (comptime runtime_has_register_builtin) self.registerValueWithHandle(args[0], args[1], args[2]) else error.Unsupported
            else if (op == .sql)
                if (comptime runtime_has_sql_builtin) self.sqlValueWithHandleParams(args[0], args[1], args[2]) else error.Unsupported
            else if (op == .exec)
                if (comptime runtime_has_exec_builtin) self.execValueWithHandleParams(args[0], args[1], args[2]) else error.Unsupported
            else
                error.Arity,
            else => error.Arity,
        };
    }

    fn applyArrayCall(self: *Session, callee: Value, args: []const Value) KError!Value {
        if (args.len == 0) return error.Arity;
        if (args.len == 1) return try self.applyArrayCall1(callee, args[0]);
        return try self.deepIndexValue(callee, args);
    }

    fn dyadicBuiltinForGenericCall(op: BuiltinId) BuiltinId {
        return switch (op) {
            .count => .take,
            .floor => .drop,
            .stringify => .cast,
            .unique => .find,
            else => op,
        };
    }

    fn applyArrayCall1Scalar(self: *Session, callee: Value, raw_index: i64) KError!Value {
        if (callee.tag() != .array) return error.Type;
        if (callee.arrayKind() == .host_keyed_store and callee.asHostKeyedStore().layout == .dict) {
            const key = try self.intValue(raw_index);
            defer self.releaseValue(key);
            return try self.keyedStoreLookupValueByKey(callee.asHostKeyedStore(), key);
        }
        if (stringSourceInfo(callee)) |source| return try self.stringIndexScalarValue(source, raw_index);
        if (try numericValueScalarIndexValue(self, callee, raw_index)) |result| return result;
        if (valueRangeIotaHandle(callee)) |handle| {
            return (try numericStructuralScalarIndexValue(self, .{ .handle = handle }, raw_index)).?;
        }
        if (valueNonVectorNumericShape(callee) == null) {
            if (hostDenseIfPresent(callee)) |array| return try self.hostDenseIndexScalar(callee, array, raw_index);
        }
        if (valueNumericHandle(callee)) |handle| {
            return try self.hostDenseIndexScalar(callee, try hostStructuralArrayForHandle(self, @constCast(handle)), raw_index);
        }
        return switch (callee.arrayKind()) {
            .host_boxed_array => try self.hostBoxedArrayIndexScalar(callee.asHostBoxedArray(), raw_index),
            .host_string_list => try self.hostStringListIndexScalar(callee.asHostStringList(), raw_index),
            .host_symbol_list => if (normalizeIndexOrNull(raw_index, callee.asHostStringList().len)) |idx|
                try self.hostSymbolListItemValue(callee.asHostStringList(), idx)
            else
                try self.emptySymbolValue(),
            .host_symbol => error.Type,
            .host_handle => error.Type,
            .host_relation => error.Type,
            .host_keyed_store => blk: {
                const store = callee.asHostKeyedStore();
                if (store.layout != .table) break :blk error.Type;
                break :blk try self.tableRowDictValue(store, normalizeIndexOrNull(raw_index, store.row_count));
            },
            else => error.Internal,
        };
    }

    fn applyHostSymbolCall1(self: *Session, callee: Value, selector: Value) KError!?Value {
        if (callee.tag() != .array or callee.arrayKind() != .host_symbol) return null;
        const name = hostTextBytes(callee.asHostSymbol());
        if (std.mem.eql(u8, name, "j")) return try self.jsonEncodeValue(selector);
        if (std.mem.eql(u8, name, "k")) return try self.kTextEncodeValue(selector);
        if (std.mem.eql(u8, name, "fb")) return try self.floatFromBitsValue(selector);
        return null;
    }

    fn stringIndexScalarValue(self: *Session, source: HostStringSource, raw_index: i64) KError!Value {
        const bytes = source.bytes();
        if (raw_index >= 0 and raw_index < @as(i64, @intCast(bytes.len))) {
            const idx: usize = @intCast(raw_index);
            return try self.managedHostStringViewWithReason(source.base, .{
                .start = source.span.start + idx,
                .len = 1,
            }, .generic);
        }
        return try self.managedHostString(&[_]u8{' '});
    }

    fn allocManagedHostStringUninitialized(self: *Session, len: usize) !HostStringAlloc {
        const buf = try hostTextAllocSlice(self.allocator, len);
        errdefer self.allocator.free(buf);
        const text = hostTextFromAlloc(buf);
        text.* = .{
            .header = HeapHeader.init(.host_string, .managed),
            .len = len,
        };
        return .{
            .value = Value.array(text),
            .bytes = hostTextBytesFromAlloc(buf, len),
        };
    }

    fn gatherTypedStringIndexInBounds(comptime SelT: type, out: []u8, bytes: []const u8, selector: []const SelT) void {
        const src: [*]const u8 = bytes.ptr;
        var dst: [*]u8 = out.ptr;
        var idx: usize = 0;
        while (idx + 8 <= selector.len) : (idx += 8) {
            dst[0] = src[@as(usize, @intCast(selector[idx + 0]))];
            dst[1] = src[@as(usize, @intCast(selector[idx + 1]))];
            dst[2] = src[@as(usize, @intCast(selector[idx + 2]))];
            dst[3] = src[@as(usize, @intCast(selector[idx + 3]))];
            dst[4] = src[@as(usize, @intCast(selector[idx + 4]))];
            dst[5] = src[@as(usize, @intCast(selector[idx + 5]))];
            dst[6] = src[@as(usize, @intCast(selector[idx + 6]))];
            dst[7] = src[@as(usize, @intCast(selector[idx + 7]))];
            dst += 8;
        }
        while (idx < selector.len) : (idx += 1) {
            dst[0] = src[@as(usize, @intCast(selector[idx]))];
            dst += 1;
        }
    }

    fn gatherStringIndexInBounds(out: []u8, bytes: []const u8, selector: HostIntArrayView) void {
        switch (selector) {
            .bit => unreachable,
            .int8 => |items| gatherTypedStringIndexInBounds(i8, out, bytes, items),
            .int16 => |items| gatherTypedStringIndexInBounds(i16, out, bytes, items),
            .int32 => |items| gatherTypedStringIndexInBounds(i32, out, bytes, items),
            .int64 => |items| gatherTypedStringIndexInBounds(i64, out, bytes, items),
        }
    }

    fn stringIndexDenseInBoundsValue(self: *Session, source: HostStringSource, selector: HostIntArrayView) KError!Value {
        const len = hostIntArrayViewLen(selector);
        const bytes = source.bytes();
        if (len == 1) {
            const selected = [_]u8{bytes[@intCast(hostIntViewItem(selector, 0))]};
            return try self.managedHostCharVector(&selected);
        }
        const out = try self.allocManagedHostStringUninitialized(len);
        gatherStringIndexInBounds(out.bytes, bytes, selector);
        return out.value;
    }

    fn stringIndexBoxedValue(self: *Session, source: HostStringSource, selector: *const HostBoxedArray) KError!Value {
        const items = try self.allocator.alloc(Value, selector.len());
        defer self.allocator.free(items);
        var initialized: usize = 0;
        defer {
            for (items[0..initialized]) |item| self.releaseValue(item);
        }

        for (selector.items[0..selector.len()], 0..) |item, idx| {
            items[idx] = try self.stringIndexValue(source, item);
            initialized += 1;
        }
        return try self.makeArrayFromValues(items);
    }

    fn stringIndexValue(self: *Session, source: HostStringSource, selector: Value) KError!Value {
        if (scalarIntLikeValue(selector)) |raw_index| return try self.stringIndexScalarValue(source, raw_index);
        if (selector.tag() == .array and selector.arrayKind() == .host_boxed_array) {
            return try self.stringIndexBoxedValue(source, selector.asHostBoxedArray());
        }

        const bytes = source.bytes();
        if (hostDenseIfPresent(selector)) |array| {
            if (hostIntArrayView(array)) |dense_view| switch (dense_view) {
                .bit => {},
                else => if (denseSelectorCachedRangeFitsSource(array, bytes.len))
                    return try self.stringIndexDenseInBoundsValue(source, dense_view),
            };
        }

        const view = valueHostIntStructuralView(selector) orelse return error.Type;
        const len = hostIntDenseViewLen(view);
        if (len == 1) {
            const raw_index = try hostIntDenseViewItem(view, 0);
            const selected = [_]u8{if (raw_index >= 0 and raw_index < @as(i64, @intCast(bytes.len)))
                bytes[@intCast(raw_index)]
            else
                ' '};
            return try self.managedHostCharVector(&selected);
        }
        const out = try self.allocManagedHostStringUninitialized(len);
        errdefer self.releaseValue(out.value);
        for (0..len) |idx| {
            const raw_index = try hostIntDenseViewItem(view, idx);
            out.bytes[idx] = if (raw_index >= 0 and raw_index < @as(i64, @intCast(bytes.len)))
                bytes[@intCast(raw_index)]
            else
                ' ';
        }
        return out.value;
    }

    fn stringIndexWhereBitMaskValue(self: *Session, source: HostStringSource, mask: HostBitSlice) KError!Value {
        const bytes = source.bytes();
        const len = bitCountTrue(mask);
        const out = try self.allocManagedHostStringUninitialized(len);
        errdefer self.releaseValue(out.value);

        if (mask.len <= bytes.len) {
            if (comptime enable_string_mask_neon) {
                const written = kiwi_string_mask_compress_neon(out.bytes.ptr, out.bytes.len, bytes.ptr, mask.words.ptr, mask.len);
                std.debug.assert(written == out.bytes.len);
                self.noteSimdKernel(.string_mask_select);
            } else {
                copyStringWhereBitMaskBytesInBounds(out.bytes, bytes, mask);
            }
        } else {
            copyStringWhereBitMaskScalarPadded(out.bytes, bytes, mask);
        }

        if (len == 1) {
            const result = try self.managedHostCharVector(out.bytes);
            self.releaseValue(out.value);
            return result;
        }
        return out.value;
    }

    fn stringRejectWhereBitMaskValue(self: *Session, source: HostStringSource, mask: HostBitSlice) KError!Value {
        const bytes = source.bytes();
        if (mask.len != bytes.len) return error.Type;

        const inverted_words = try self.allocator.alloc(u64, bitWordCount(mask.len));
        defer self.allocator.free(inverted_words);
        fillBitNotWords(inverted_words, mask);
        return try self.stringIndexWhereBitMaskValue(source, .{ .words = inverted_words, .len = mask.len });
    }

    fn applyWhereMaskCall(self: *Session, callee: Value, mask_value: Value) KError!Value {
        if (valueNumericBitSlice(mask_value)) |bits| {
            if (callee.tag() == .array) {
                if (stringSourceInfo(callee)) |source| {
                    return try self.stringIndexWhereBitMaskValue(source, bits);
                }
            }
        }

        if (try tryApplyBackendBoolMaskSelect(self, callee, mask_value)) |result| return result;

        const selector = try self.whereValue(mask_value);
        defer self.releaseValue(selector);
        return try self.applyValue(callee, &[_]Value{selector});
    }

    fn applyArrayCall1(self: *Session, callee: Value, selector: Value) KError!Value {
        if (callee.tag() != .array) return error.Type;
        if (isAllAxisSelectorValue(selector)) return self.shareValue(callee);
        if (try self.applyHostSymbolCall1(callee, selector)) |result| return result;
        if (selector.tag() == .array and selector.arrayKind() == .host_keyed_store and
            !(callee.arrayKind() == .host_symbol and std.mem.eql(u8, hostTextBytes(callee.asHostSymbol()), "j")))
        {
            const selector_store = selector.asHostKeyedStore();
            if (selector_store.layout == .dict) return try self.applyDictSelectorValue(callee, selector_store);
        }
        if (callee.arrayKind() == .host_keyed_store and callee.asHostKeyedStore().layout == .dict) {
            const store = callee.asHostKeyedStore();
            if (derivedSequenceLen(selector) != null) return try self.keyedStoreLookupSequenceValue(store, selector);
            return try self.keyedStoreLookupValueByKey(store, selector);
        }
        if (scalarIntLikeValue(selector)) |raw_index| return try self.applyArrayCall1Scalar(callee, raw_index);
        if (stringSourceInfo(callee)) |source| return try self.stringIndexValue(source, selector);
        switch (selector.tag()) {
            .array => if (try numericValueArithmeticSelectorSlice(callee, selector)) |slice| {
                if (try numericValueArithmeticSliceValue(self, callee, slice)) |result| return result;
                if (try numericValueFirstAxisArithmeticSliceValue(self, callee, slice)) |result| return result;
            },
            else => {},
        }
        if (selector.tag() == .array) {
            if (try numericValueFirstAxisIndexSelectorValue(self, callee, selector)) |result| return result;
            if (try tryApplyBackendBoolIndexVector(self, callee, selector)) |result| return result;
        }
        if (valueRangeIotaHandle(callee)) |handle| return try self.applyRangeIotaIndex(handle, selector);
        if (valueNumericHandle(callee)) |handle| return try self.applyHostArrayIndex(callee, try hostStructuralArrayForHandle(self, @constCast(handle)), selector);
        return switch (callee.arrayKind()) {
            .host_boxed_array => try self.applyHostBoxedArrayIndex(callee.asHostBoxedArray(), selector),
            .host_symbol => error.Type,
            .host_string_list => switch (selector.tag()) {
                .int, .bool => try self.hostStringListIndexScalar(callee.asHostStringList(), scalarIntLikeValue(selector).?),
                .array => blk: {
                    break :blk try self.selectHostTextListBySelectorValue(callee.asHostStringList(), selector, false);
                },
                else => error.Type,
            },
            .host_symbol_list => switch (selector.tag()) {
                .int, .bool => if (normalizeIndexOrNull(scalarIntLikeValue(selector).?, callee.asHostStringList().len)) |idx|
                    try self.hostSymbolListItemValue(callee.asHostStringList(), idx)
                else
                    try self.emptySymbolValue(),
                .array => blk: {
                    break :blk try self.selectHostTextListBySelectorValue(callee.asHostStringList(), selector, true);
                },
                else => error.Type,
            },
            .host_relation => blk: {
                const name = keyedLookupNameBytes(selector) orelse break :blk error.Type;
                break :blk try self.materializeRelationColumn(callee.asHostRelation(), name);
            },
            .host_keyed_store => blk: {
                const store = callee.asHostKeyedStore();
                if (store.layout == .dict) {
                    if (derivedSequenceLen(selector) != null) break :blk try self.keyedStoreLookupSequenceValue(store, selector);
                    break :blk try self.keyedStoreLookupValueByKey(store, selector);
                }
                if (keyedLookupNameBytes(selector)) |name| break :blk try self.keyedStoreLookupValue(store, name);
                if (store.layout == .table) {
                    if (valueHostIntStructuralView(selector)) |view| {
                        break :blk try self.tableSelectRowsBySelector(store, view);
                    }
                }
                break :blk error.Type;
            },
            else => error.Internal,
        };
    }

    fn applyValue(self: *Session, callee: Value, args: []const Value) KError!Value {
        if (try self.tryApplyAllAxisCallableProjection(callee, args)) |projection| return projection;
        return switch (callee.tag()) {
            .builtin => try self.applyBuiltinCall(callee.asBuiltin(), args),
            .closure => blk: {
                const closure = callee.asClosure();
                if (try self.tryProjectDerivedClosureUnderApplication(callee, closure, args)) |projection| break :blk projection;
                if (try self.applyDerivedClosure(closure, args)) |result| break :blk result;
                if (try self.tryProjectPlainClosureUnderApplication(callee, closure, args)) |projection| break :blk projection;
                if (codeForRunnablePlainClosureArgs(closure, args)) |compact| break :blk try self.runCodeBorrowed(compact, codeRunArgs(compact, args));
                if (closure.code.arity != args.len) return error.Arity;
                break :blk try self.runClosureMode(closure, args, false);
            },
            .array => try self.applyArrayCall(callee, args),
            else => error.Type,
        };
    }

    fn argsContainAllAxisSelector(args: []const Value) bool {
        for (args) |arg| {
            if (isAllAxisSelectorValue(arg)) return true;
        }
        return false;
    }

    fn tryApplyAllAxisCallableProjection(self: *Session, callee: Value, args: []const Value) KError!?Value {
        switch (callee.tag()) {
            .builtin, .closure => {},
            else => return null,
        }
        if (!argsContainAllAxisSelector(args)) return null;
        if (args.len > 63) return error.Unsupported;

        const slot_values = try self.scratch_arena.allocator().alloc(Value, args.len);
        var hole_mask: u64 = 0;
        for (args, 0..) |arg, idx| {
            if (isAllAxisSelectorValue(arg)) {
                slot_values[idx] = Value.fromBool(false);
                hole_mask |= @as(u64, 1) << @intCast(idx);
            } else {
                slot_values[idx] = arg;
            }
        }
        return try self.allocManagedProjectionClosure(callee, @intCast(args.len), hole_mask, slot_values);
    }

    fn tryProjectPlainClosureUnderApplication(self: *Session, callee: Value, closure: *const Closure, args: []const Value) KError!?Value {
        if (!closureIsCompactPlainGlobal(closure)) return null;
        const code = closure.code;
        if (args.len >= code.arity) return null;
        if (codeCanRunWithArgLen(code, args.len)) return null;
        if (code.arity > 63) return error.Unsupported;

        const slot_count: usize = code.arity;
        const slot_values = try self.scratch_arena.allocator().alloc(Value, slot_count);
        var hole_mask: u64 = 0;
        for (0..slot_count) |idx| {
            if (idx < args.len) {
                slot_values[idx] = args[idx];
            } else {
                slot_values[idx] = Value.fromBool(false);
                hole_mask |= @as(u64, 1) << @intCast(idx);
            }
        }
        return try self.allocManagedProjectionClosure(callee, code.arity, hole_mask, slot_values);
    }

    const AutogradTargetBackend = enum {
        host,
        mlx,
    };

    const dense_autodiff_max_nodes = 16;
    const DenseAutodiffNodeIndex = u8;
    const dense_autodiff_no_slot = std.math.maxInt(u8);

    pub const DebugDenseAutodiffLowering = enum {
        ok,
        wrong_arity,
        non_vector_target,
        non_scalar_result,
        unsupported_opcode,
        unsupported_shape_flow,
        unsupported_builtin,
        capture_or_global_dependency,
        non_dense_operand,
    };
    const debug_dense_autodiff_lowering_count = @typeInfo(DebugDenseAutodiffLowering).@"enum".field_names.len;

    const DenseAutodiffNode = union(enum) {
        input,
        const_scalar: f64,
        scan_add: DenseAutodiffNodeIndex,
        unary_map: struct {
            op: BuiltinId,
            src: DenseAutodiffNodeIndex,
        },
        neg: DenseAutodiffNodeIndex,
        add: struct {
            left: DenseAutodiffNodeIndex,
            right: DenseAutodiffNodeIndex,
        },
        sub: struct {
            left: DenseAutodiffNodeIndex,
            right: DenseAutodiffNodeIndex,
        },
        mul: struct {
            left: DenseAutodiffNodeIndex,
            right: DenseAutodiffNodeIndex,
        },
        reduce_add: DenseAutodiffNodeIndex,
    };

    const DenseAutodiffNodeKind = enum {
        vector,
        scalar,
    };

    const DenseAutodiffProgram = struct {
        nodes: [dense_autodiff_max_nodes]DenseAutodiffNode = undefined,
        kinds: [dense_autodiff_max_nodes]DenseAutodiffNodeKind = undefined,
        len: DenseAutodiffNodeIndex = 0,
        root: DenseAutodiffNodeIndex = 0,

        fn push(self: *DenseAutodiffProgram, node: DenseAutodiffNode, kind: DenseAutodiffNodeKind) DenseAutodiffNodeIndex {
            std.debug.assert(self.len < dense_autodiff_max_nodes);
            const idx = self.len;
            self.nodes[idx] = node;
            self.kinds[idx] = kind;
            self.len += 1;
            return idx;
        }
    };

    const DenseAutodiffExecPlan = struct {
        forward_slots: [dense_autodiff_max_nodes]u8 = @as([dense_autodiff_max_nodes]u8, @splat(dense_autodiff_no_slot)),
        adjoint_slots: [dense_autodiff_max_nodes]u8 = @as([dense_autodiff_max_nodes]u8, @splat(dense_autodiff_no_slot)),
        forward_slot_count: u8 = 0,
        adjoint_slot_count: u8 = 0,
    };

    const DenseAutodiffExecBackend = enum {
        host,
        mlx,
    };

    const DenseAutodiffCacheKey = struct {
        closure: *const Closure,
        input_kind: DenseAutodiffNodeKind,
    };

    const DenseAutodiffLowerResult = union(enum) {
        program: DenseAutodiffProgram,
        reject: DebugDenseAutodiffLowering,
    };

    const DenseAutodiffLowerStackItem = union(enum) {
        node: DenseAutodiffNodeIndex,
        derived_add_fold,
        derived_add_scan,
        builtin: BuiltinId,
    };

    const AutogradTarget = struct {
        values: []f64,
        shape: []i32,
        is_scalar: bool,
        backend: AutogradTargetBackend,
    };

    fn applyAutogradBuiltin(self: *Session, op: BuiltinId, args: []const Value) KError!Value {
        if (args.len == 0 or args.len > 2) return error.Arity;
        switch (args[0].tag()) {
            .builtin, .closure => {},
            else => return error.Type,
        }

        var captures_buf: [2]Value = .{ args[0], Value.fromBool(false) };
        var capture_len: usize = 1;
        if (args.len == 2) {
            const arg_index = scalarIntLikeValue(args[1]) orelse return error.Type;
            if (arg_index < 0) return error.Type;
            captures_buf[1] = try self.intValue(arg_index);
            capture_len = 2;
        }

        const kind: DerivedVerbKind = if (op == .grad) .grad else .valuegrad;
        if (self.debugDetailedProbeActive()) switch (op) {
            .grad => self.debug.autograd_builtin_grad_count += 1,
            .valuegrad => self.debug.autograd_builtin_valuegrad_count += 1,
            else => {},
        };
        const closure = try self.allocFrozenDerivedClosureWithCaptures(kind, captures_buf[0..capture_len]);
        return Value.closure(closure);
    }

    fn applyAutogradDerived(self: *Session, kind: DerivedVerbKind, captures: []const Value, args: []const Value) KError!Value {
        if (captures.len == 0 or captures.len > 2) return error.Internal;

        const base = captures[0];
        const arg_index: usize = if (captures.len == 2) blk: {
            const raw = scalarIntLikeValue(captures[1]) orelse return error.Internal;
            if (raw < 0) return error.Internal;
            break :blk @intCast(raw);
        } else 0;
        if (arg_index >= args.len) return error.Arity;

        if (try self.tryFastDenseAutograd(kind, base, args, arg_index)) |value| return value;
        if (self.debugDetailedProbeActive()) self.debug.autograd_slow_finite_difference_count += 1;

        var sibling = try self.initSiblingSession();
        defer sibling.deinit();

        const sibling_args = try sibling.retainArgs(args);
        defer sibling.releaseArgs(sibling_args);
        const original = try sibling.applyValue(base, sibling_args);
        const original_scalar = try self.scalarNumericAutogradResult(original);
        sibling.releaseValue(original);

        const target = try materializeAutogradTarget(self.allocator, args[arg_index]);
        defer self.allocator.free(target.values);
        defer self.allocator.free(target.shape);

        const grad = try self.allocator.alloc(f64, target.values.len);
        defer self.allocator.free(grad);

        const eps = 0.25;
        for (0..target.values.len) |idx| {
            const p2 = try sibling.evalAutogradPerturbed(base, args, arg_index, target, idx, 2.0 * eps);
            const p1 = try sibling.evalAutogradPerturbed(base, args, arg_index, target, idx, eps);
            const m1 = try sibling.evalAutogradPerturbed(base, args, arg_index, target, idx, -eps);
            const m2 = try sibling.evalAutogradPerturbed(base, args, arg_index, target, idx, -2.0 * eps);
            grad[idx] = (-p2 + 8.0 * p1 - 8.0 * m1 + m2) / (12.0 * eps);
        }

        const grad_value = if (target.is_scalar)
            try self.floatValue(grad[0])
        else switch (target.backend) {
            .host => try self.createManagedHostFloatArray(grad),
            .mlx => blk: {
                const items = try self.allocator.alloc(f32, grad.len);
                defer self.allocator.free(items);
                for (grad, 0..) |item, idx| items[idx] = @floatCast(item);
                break :blk try self.wrapManagedBackendArray(mlx.Array.fromFloatSlice(items, target.shape));
            },
        };

        if (kind == .grad) return grad_value;

        const rooted_original = try self.numericScalarValueFromF64(original_scalar);
        defer self.releaseValue(rooted_original);
        defer self.releaseValue(grad_value);
        const pair = [_]Value{ rooted_original, grad_value };
        return try self.createManagedHostBoxedArray(&pair);
    }

    fn tryFastDenseAutograd(self: *Session, kind: DerivedVerbKind, base: Value, args: []const Value, arg_index: usize) KError!?Value {
        if (args.len != 1 or arg_index != 0) return null;
        const scratch = self.scratch_arena.allocator();
        const target = try materializeAutogradTarget(scratch, args[0]);
        if (!target.is_scalar and target.shape.len != 1) return null;
        const input_kind: DenseAutodiffNodeKind = if (target.is_scalar) .scalar else .vector;
        const program = self.detectDenseAutodiffProgramForInput(base, input_kind) orelse return null;
        self.last_dense_autodiff_exec_backend = null;

        if (!target.is_scalar and self.chooseDenseAutodiffExecBackend(&program, args[0]) == .mlx) {
            if (try self.tryFastDenseAutogradBackend(kind, &program, args[0])) |value| return value;
        }

        const grad = try scratch.alloc(f64, target.values.len);

        const original_scalar = try executeDenseAutodiffProgram(scratch, &program, target.values, grad);

        const grad_value = try self.autogradGradientValue(target, grad);
        if (comptime enable_probe_instrumentation) self.last_dense_autodiff_exec_backend = .host;
        if (kind == .grad) return grad_value;

        const original_value = try self.numericScalarValueFromF64(original_scalar);
        defer self.releaseValue(original_value);
        defer self.releaseValue(grad_value);
        const pair = [_]Value{ original_value, grad_value };
        return try self.createManagedHostBoxedArray(&pair);
    }

    fn tryFastDenseAutogradBackend(self: *Session, kind: DerivedVerbKind, program: *const DenseAutodiffProgram, value: Value) KError!?Value {
        return runtime_backend_autodiff.tryFastDenseAutogradBackend(backend_autodiff_api, self, kind, program, value);
    }

    fn chooseDenseAutodiffExecBackend(self: *Session, program: *const DenseAutodiffProgram, value: Value) DenseAutodiffExecBackend {
        _ = program;
        if (comptime !runtime_has_mlx or !mlx.supports_full_ops) return .host;
        return switch (planDenseAutodiffBackend(self, value)) {
            .host => .host,
            .mlx => .mlx,
        };
    }

    fn autogradGradientValue(self: *Session, target: AutogradTarget, grad: []const f64) KError!Value {
        if (target.is_scalar) return try self.floatValue(grad[0]);
        return switch (target.backend) {
            .host => try self.createManagedHostFloatArray(grad),
            .mlx => blk: {
                const items = try self.allocator.alloc(f32, grad.len);
                defer self.allocator.free(items);
                for (grad, 0..) |item, idx| items[idx] = @floatCast(item);
                break :blk try self.wrapManagedBackendArray(mlx.Array.fromFloatSlice(items, target.shape));
            },
        };
    }

    fn numericScalarValueFromF64(self: *Session, value: f64) KError!Value {
        const rounded = @round(value);
        if (rounded == value) {
            const as_i64 = std.math.lossyCast(i64, rounded);
            if (@as(f64, @floatFromInt(as_i64)) == value) return try self.intValue(as_i64);
        }
        return try self.floatValue(value);
    }

    fn initSiblingSession(self: *Session) !Session {
        var sibling = try Session.initWithDevice(self.allocator, self.device_preference);
        errdefer sibling.deinit();
        try self.cloneGlobalsInto(&sibling);
        return sibling;
    }

    fn cloneGlobalsInto(self: *Session, sibling: *Session) !void {
        try sibling.global_cells.resize(self.allocator, self.global_cells.items.len);
        try sibling.global_names.resize(self.allocator, self.global_names.items.len);
        for (sibling.global_cells.items) |*cell| {
            cell.* = .{
                .value = Value.fromBool(false),
                .initialized = false,
                .class = .uninitialized,
                .code = null,
            };
        }
        for (self.global_names.items, 0..) |name, idx| {
            sibling.global_names.items[idx] = try sibling.arena.allocator().dupe(u8, name);
        }

        var it = self.global_slots.iterator();
        while (it.next()) |entry| {
            try sibling.global_slots.put(sibling.global_names.items[entry.value_ptr.*], entry.value_ptr.*);
        }

        for (self.global_cells.items, 0..) |cell, idx| {
            if (!cell.initialized) continue;
            const value = try sibling.retainEscapedValue(cell.value);
            sibling.global_cells.items[idx] = .{
                .value = value,
                .initialized = true,
                .class = classifyGlobalValue(value),
                .code = codeForStoredGlobal(value),
            };
        }
    }

    fn retainArgs(self: *Session, args: []const Value) ![]Value {
        const retained = try self.allocator.alloc(Value, args.len);
        errdefer self.allocator.free(retained);
        var initialized: usize = 0;
        errdefer {
            for (retained[0..initialized]) |value| self.releaseValue(value);
        }
        for (args, 0..) |arg, idx| {
            retained[idx] = try self.retainEscapedValue(arg);
            initialized += 1;
        }
        return retained;
    }

    fn releaseArgs(self: *Session, args: []Value) void {
        for (args) |value| self.releaseValue(value);
        self.allocator.free(args);
    }

    fn evalAutogradPerturbed(self: *Session, base: Value, args: []const Value, arg_index: usize, target: AutogradTarget, perturb_index: usize, delta: f64) KError!f64 {
        var call_args = try self.allocator.alloc(Value, args.len);
        defer self.allocator.free(call_args);
        var initialized: usize = 0;
        defer {
            for (call_args[0..initialized]) |value| self.releaseValue(value);
        }

        for (args, 0..) |arg, idx| {
            call_args[idx] = if (idx == arg_index)
                try self.makePerturbedArgument(arg, target, perturb_index, delta)
            else
                try self.retainEscapedValue(arg);
            initialized += 1;
        }

        const value = try self.applyValue(base, call_args);
        defer self.releaseValue(value);
        return try self.scalarNumericAutogradResult(value);
    }

    fn makePerturbedArgument(self: *Session, original: Value, target: AutogradTarget, perturb_index: usize, delta: f64) KError!Value {
        if (target.is_scalar) return try self.floatValue(target.values[0] + delta);

        const items = try self.allocator.dupe(f64, target.values);
        defer self.allocator.free(items);
        items[perturb_index] += delta;
        _ = original;
        return switch (target.backend) {
            .host => try self.createManagedHostFloatArray(items),
            .mlx => blk: {
                const converted = try self.allocator.alloc(f32, items.len);
                defer self.allocator.free(converted);
                for (items, 0..) |item, idx| converted[idx] = @floatCast(item);
                break :blk try self.wrapManagedBackendArray(mlx.Array.fromFloatSlice(converted, target.shape));
            },
        };
    }

    fn scalarNumericAutogradResult(self: *Session, value: Value) KError!f64 {
        _ = self;
        return switch (value.tag()) {
            .int, .bool, .float => try scalarNumericValue(value),
            .array => blk: {
                const backend = backendArrayIfPresent(value) orelse return error.Type;
                var owned = backend.array.clone() catch |err| return mapMlxError(err);
                defer owned.deinit();
                owned.eval() catch |err| return mapMlxError(err);
                if (owned.ndim() != 0) return error.Type;
                break :blk switch (owned.dtype()) {
                    c.MLX_BOOL => @floatFromInt(@intFromBool(owned.boolItem() catch |err| return mapMlxError(err))),
                    c.MLX_INT32, c.MLX_INT64, c.MLX_UINT32 => @floatFromInt(owned.intItem() catch |err| return mapMlxError(err)),
                    c.MLX_FLOAT16, c.MLX_FLOAT32, c.MLX_FLOAT64, c.MLX_BFLOAT16 => owned.floatItem() catch |err| return mapMlxError(err),
                    else => return error.Type,
                };
            },
            else => error.Type,
        };
    }

    pub fn debugDenseAutodiffLowering(self: *Session, value: Value) Session.DebugDenseAutodiffLowering {
        return switch (self.detectDenseAutodiffProgramDetailedForInput(value, .vector)) {
            .program => .ok,
            .reject => |reason| reason,
        };
    }

    fn detectDenseAutodiffProgramForInput(self: *Session, base: Value, input_kind: DenseAutodiffNodeKind) ?DenseAutodiffProgram {
        return switch (self.detectDenseAutodiffProgramDetailedForInput(base, input_kind)) {
            .program => |program| blk: {
                if (self.debugDetailedProbeActive()) self.debug.dense_autodiff_lower_success_count += 1;
                break :blk program;
            },
            .reject => |reason| blk: {
                self.noteDenseAutodiffReject(reason);
                break :blk null;
            },
        };
    }

    fn detectDenseAutodiffProgramDetailedForInput(self: *Session, base: Value, input_kind: DenseAutodiffNodeKind) DenseAutodiffLowerResult {
        if (base.tag() != .closure) return .{ .reject = .unsupported_shape_flow };
        const closure = base.asClosure();
        const cacheable = closure.header.owner == .frozen;
        const cache_key = DenseAutodiffCacheKey{
            .closure = closure,
            .input_kind = input_kind,
        };
        if (cacheable) {
            if (self.dense_autodiff_cache.get(cache_key)) |cached| {
                if (self.debugDetailedProbeActive()) self.debug.dense_autodiff_cache_hit_count += 1;
                return cached;
            }
            if (self.debugDetailedProbeActive()) self.debug.dense_autodiff_cache_miss_count += 1;
        } else if (closure.header.owner != .scratch) {
            return .{ .reject = .capture_or_global_dependency };
        }
        if (closure.captures.len != 0 or closure.code.references_globals) {
            const result: DenseAutodiffLowerResult = .{ .reject = .capture_or_global_dependency };
            if (cacheable) self.dense_autodiff_cache.put(cache_key, result) catch {};
            return result;
        }
        if (closure.code.arity != 1) {
            const result: DenseAutodiffLowerResult = .{ .reject = .wrong_arity };
            if (cacheable) self.dense_autodiff_cache.put(cache_key, result) catch {};
            return result;
        }

        var program = DenseAutodiffProgram{};
        const input = program.push(.input, input_kind);

        var stack: [dense_autodiff_max_nodes * 2]DenseAutodiffLowerStackItem = undefined;
        var stack_len: usize = 0;

        const compact = closure.code;
        var ip: usize = 0;
        while (ip < compact.bytes.len) {
            const raw = compact.bytes[ip];
            ip += 1;

            if (compactIsConstValueOpcode(raw)) {
                const slot: usize = raw - ck_const_value_base;
                if (slot >= compact.constants.len) return .{ .reject = .unsupported_shape_flow };
                if (denseAutodiffPushConstantOrDerived(&program, &stack, &stack_len, compact.constants[slot])) |reject| return .{ .reject = reject };
                continue;
            }
            if (raw >= ck_load_local_base and raw < ck_load_local_base + ck_range_width) {
                if (raw - ck_load_local_base != 0) return .{ .reject = .wrong_arity };
                denseAutodiffPushStack(&stack, &stack_len, .{ .node = input }) orelse return .{ .reject = .unsupported_shape_flow };
                continue;
            }
            if (raw >= ck_take_local_base and raw < ck_take_local_base + ck_range_width) {
                if (raw - ck_take_local_base != 0) return .{ .reject = .wrong_arity };
                denseAutodiffPushStack(&stack, &stack_len, .{ .node = input }) orelse return .{ .reject = .unsupported_shape_flow };
                continue;
            }
            if (raw >= ck_store_local_base and raw < ck_store_local_base + ck_range_width) return .{ .reject = .unsupported_opcode };

            if (compactIsMonadOpcode(raw)) {
                switch (raw - ck_monad_base) {
                    ckm_identity => {},
                    ckm_sub => {
                        const item = denseAutodiffPopStack(&stack, &stack_len) orelse return .{ .reject = .unsupported_shape_flow };
                        const src = denseAutodiffNodeFromStackItem(item) orelse return .{ .reject = .unsupported_builtin };
                        const node = program.push(.{ .neg = src }, program.kinds[src]);
                        denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                    },
                    else => return .{ .reject = .unsupported_builtin },
                }
                continue;
            }

            if (compactIsDyadOpcode(raw)) {
                const tag: DenseAutodiffBinaryTag = switch (raw - ck_dyad_base) {
                    ckd_add => .add,
                    ckd_sub => .sub,
                    ckd_mul => .mul,
                    else => return .{ .reject = .unsupported_builtin },
                };
                const left_item = denseAutodiffPopStack(&stack, &stack_len) orelse return .{ .reject = .unsupported_shape_flow };
                const right_item = denseAutodiffPopStack(&stack, &stack_len) orelse return .{ .reject = .unsupported_shape_flow };
                const left = denseAutodiffNodeFromStackItem(left_item) orelse return .{ .reject = .unsupported_builtin };
                const right = denseAutodiffNodeFromStackItem(right_item) orelse return .{ .reject = .unsupported_builtin };
                const node = denseAutodiffPushBinary(&program, tag, left, right);
                denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                continue;
            }

            switch (raw) {
                ck_const_i8 => {
                    const value: i8 = @bitCast(denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow });
                    const node = program.push(.{ .const_scalar = @floatFromInt(value) }, .scalar);
                    denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                },
                ck_const_i64 => {
                    const value = denseAutodiffReadI64(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    const node = program.push(.{ .const_scalar = @floatFromInt(value) }, .scalar);
                    denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                },
                ck_const_false => {
                    const node = program.push(.{ .const_scalar = 0.0 }, .scalar);
                    denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                },
                ck_const_true => {
                    const node = program.push(.{ .const_scalar = 1.0 }, .scalar);
                    denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                },
                ck_const_value_u8 => {
                    const slot = denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    if (slot >= compact.constants.len) return .{ .reject = .unsupported_shape_flow };
                    if (denseAutodiffPushConstantOrDerived(&program, &stack, &stack_len, compact.constants[slot])) |reject| return .{ .reject = reject };
                },
                ck_const_builtin_u8 => {
                    const raw_builtin = denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    const builtin: BuiltinId = @fromBackingInt(@intCast(raw_builtin));
                    switch (builtin) {
                        .add, .exp, .log, .sin, .cos, .tanh, .sigmoid => {
                            denseAutodiffPushStack(&stack, &stack_len, .{ .builtin = builtin }) orelse return .{ .reject = .unsupported_shape_flow };
                        },
                        else => return .{ .reject = .unsupported_builtin },
                    }
                },
                ck_make_adverb_u8 => {
                    const raw_kind = denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    const kind: DerivedVerbKind = @fromBackingInt(@intCast(raw_kind));
                    const base_item = denseAutodiffPopStack(&stack, &stack_len) orelse return .{ .reject = .unsupported_shape_flow };
                    switch (base_item) {
                        .builtin => |builtin| switch (builtin) {
                            .add => switch (kind) {
                                .fold => denseAutodiffPushStack(&stack, &stack_len, .derived_add_fold) orelse return .{ .reject = .unsupported_shape_flow },
                                .scan => denseAutodiffPushStack(&stack, &stack_len, .derived_add_scan) orelse return .{ .reject = .unsupported_shape_flow },
                                else => return .{ .reject = .unsupported_builtin },
                            },
                            else => return .{ .reject = .unsupported_builtin },
                        },
                        else => return .{ .reject = .unsupported_builtin },
                    }
                },
                ck_add_local_local, ck_sub_local_local, ck_mul_local_local => {
                    const left_slot = denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    const right_slot = denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    if (left_slot != 0 or right_slot != 0) return .{ .reject = .wrong_arity };
                    const node = denseAutodiffPushBinary(&program, switch (raw) {
                        ck_add_local_local => .add,
                        ck_sub_local_local => .sub,
                        ck_mul_local_local => .mul,
                        else => unreachable,
                    }, input, input);
                    denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                },
                ck_add_local_const_i64, ck_sub_local_const_i64, ck_mul_local_const_i64 => {
                    const slot = denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    const rhs_value = denseAutodiffReadI64(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    if (slot != 0) return .{ .reject = .wrong_arity };
                    const rhs = program.push(.{ .const_scalar = @floatFromInt(rhs_value) }, .scalar);
                    const node = denseAutodiffPushBinary(&program, switch (raw) {
                        ck_add_local_const_i64 => .add,
                        ck_sub_local_const_i64 => .sub,
                        ck_mul_local_const_i64 => .mul,
                        else => unreachable,
                    }, input, rhs);
                    denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                },
                ck_add_const_local_i64, ck_sub_const_local_i64 => {
                    const lhs_value = denseAutodiffReadI64(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    const slot = denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    if (slot != 0) return .{ .reject = .wrong_arity };
                    const lhs = program.push(.{ .const_scalar = @floatFromInt(lhs_value) }, .scalar);
                    const node = denseAutodiffPushBinary(&program, if (raw == ck_add_const_local_i64) .add else .sub, lhs, input);
                    denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                },
                ck_discard => _ = denseAutodiffPopStack(&stack, &stack_len) orelse return .{ .reject = .unsupported_shape_flow },
                ck_call_adverb_stack_u8 => {
                    const raw_kind = denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    const kind: DerivedVerbKind = @fromBackingInt(@intCast(raw_kind));
                    const argc = denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    if (argc != 1) return .{ .reject = .unsupported_opcode };
                    const base_item = denseAutodiffPopStack(&stack, &stack_len) orelse return .{ .reject = .unsupported_shape_flow };
                    const arg_item = denseAutodiffPopStack(&stack, &stack_len) orelse return .{ .reject = .unsupported_shape_flow };
                    const node_arg = denseAutodiffNodeFromStackItem(arg_item) orelse return .{ .reject = .unsupported_builtin };
                    const base_builtin = switch (base_item) {
                        .builtin => |builtin| builtin,
                        else => return .{ .reject = .unsupported_builtin },
                    };
                    if (base_builtin != .add) return .{ .reject = .unsupported_builtin };
                    const node = switch (kind) {
                        .fold => blk: {
                            if (program.kinds[node_arg] != .vector) return .{ .reject = .non_vector_target };
                            break :blk program.push(.{ .reduce_add = node_arg }, .scalar);
                        },
                        .scan => blk: {
                            if (program.kinds[node_arg] != .vector) return .{ .reject = .non_vector_target };
                            break :blk program.push(.{ .scan_add = node_arg }, .vector);
                        },
                        else => return .{ .reject = .unsupported_builtin },
                    };
                    denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                },
                ck_call_stack_u8 => {
                    const flags = denseAutodiffReadByte(compact.bytes, &ip) orelse return .{ .reject = .unsupported_shape_flow };
                    if (compactCallArgc(flags) != 1 or compactCallStoresLocal(flags)) return .{ .reject = .unsupported_opcode };
                    const callee_item = denseAutodiffPopStack(&stack, &stack_len) orelse return .{ .reject = .unsupported_shape_flow };
                    const arg_item = denseAutodiffPopStack(&stack, &stack_len) orelse return .{ .reject = .unsupported_shape_flow };
                    const node_arg = denseAutodiffNodeFromStackItem(arg_item) orelse return .{ .reject = .unsupported_builtin };
                    const node = switch (callee_item) {
                        .derived_add_fold => blk: {
                            if (program.kinds[node_arg] != .vector) return .{ .reject = .non_vector_target };
                            break :blk program.push(.{ .reduce_add = node_arg }, .scalar);
                        },
                        .derived_add_scan => blk: {
                            if (program.kinds[node_arg] != .vector) return .{ .reject = .non_vector_target };
                            break :blk program.push(.{ .scan_add = node_arg }, .vector);
                        },
                        .builtin => |builtin| switch (builtin) {
                            .exp, .log, .sin, .cos, .tanh, .sigmoid => program.push(.{ .unary_map = .{ .op = builtin, .src = node_arg } }, program.kinds[node_arg]),
                            else => return .{ .reject = .unsupported_builtin },
                        },
                        else => return .{ .reject = .unsupported_builtin },
                    };
                    denseAutodiffPushStack(&stack, &stack_len, .{ .node = node }) orelse return .{ .reject = .unsupported_shape_flow };
                },
                ck_return => break,
                else => return .{ .reject = .unsupported_opcode },
            }
        }

        if (stack_len != 1) {
            const result: DenseAutodiffLowerResult = .{ .reject = .unsupported_shape_flow };
            if (cacheable) self.dense_autodiff_cache.put(cache_key, result) catch {};
            return result;
        }
        const root_item = stack[0];
        const root = denseAutodiffNodeFromStackItem(root_item) orelse {
            const result: DenseAutodiffLowerResult = .{ .reject = .unsupported_builtin };
            if (cacheable) self.dense_autodiff_cache.put(cache_key, result) catch {};
            return result;
        };
        if (program.kinds[root] != .scalar) {
            const result: DenseAutodiffLowerResult = .{ .reject = .non_scalar_result };
            if (cacheable) self.dense_autodiff_cache.put(cache_key, result) catch {};
            return result;
        }
        program.root = root;
        const result: DenseAutodiffLowerResult = .{ .program = program };
        if (cacheable) self.dense_autodiff_cache.put(cache_key, result) catch {};
        return result;
    }

    fn denseAutodiffPushConstantOrDerived(
        program: *DenseAutodiffProgram,
        stack: *[dense_autodiff_max_nodes * 2]DenseAutodiffLowerStackItem,
        stack_len: *usize,
        value: Value,
    ) ?DebugDenseAutodiffLowering {
        if (denseAutodiffScalarConstFromValue(value)) |scalar| {
            const node = program.push(.{ .const_scalar = scalar }, .scalar);
            denseAutodiffPushStack(stack, stack_len, .{ .node = node }) orelse return .unsupported_shape_flow;
        } else if (isDerivedBuiltinClosure(value, .fold, .add)) {
            denseAutodiffPushStack(stack, stack_len, .derived_add_fold) orelse return .unsupported_shape_flow;
        } else if (isDerivedBuiltinClosure(value, .scan, .add)) {
            denseAutodiffPushStack(stack, stack_len, .derived_add_scan) orelse return .unsupported_shape_flow;
        } else {
            return .unsupported_builtin;
        }
        return null;
    }

    fn denseAutodiffReadByte(bytes: []const u8, ip: *usize) ?u8 {
        if (ip.* >= bytes.len) return null;
        const value = bytes[ip.*];
        ip.* += 1;
        return value;
    }

    fn denseAutodiffReadI64(bytes: []const u8, ip: *usize) ?i64 {
        const end = ip.* + 8;
        if (end > bytes.len) return null;
        var value: u64 = 0;
        var idx: usize = 0;
        while (idx < 8) : (idx += 1) {
            value |= @as(u64, bytes[ip.* + idx]) << @intCast(idx * 8);
        }
        ip.* = end;
        return @bitCast(value);
    }

    fn denseAutodiffScalarConstFromValue(value: Value) ?f64 {
        return switch (value.tag()) {
            .int => @floatFromInt(value.asInt()),
            .bool => @floatFromInt(@intFromBool(value.asBool())),
            .float32 => @floatCast(value.asFloat32()),
            .float => value.asFloat(),
            else => null,
        };
    }

    fn denseAutodiffPushStack(stack: *[dense_autodiff_max_nodes * 2]DenseAutodiffLowerStackItem, len: *usize, item: DenseAutodiffLowerStackItem) ?void {
        if (len.* >= stack.len) return null;
        stack[len.*] = item;
        len.* += 1;
    }

    fn denseAutodiffPopStack(stack: *[dense_autodiff_max_nodes * 2]DenseAutodiffLowerStackItem, len: *usize) ?DenseAutodiffLowerStackItem {
        if (len.* == 0) return null;
        len.* -= 1;
        return stack[len.*];
    }

    fn denseAutodiffNodeFromStackItem(item: DenseAutodiffLowerStackItem) ?DenseAutodiffNodeIndex {
        return switch (item) {
            .node => |node| node,
            else => null,
        };
    }

    const DenseAutodiffBinaryTag = enum { add, sub, mul };

    fn denseAutodiffPushBinary(program: *DenseAutodiffProgram, tag: DenseAutodiffBinaryTag, left: DenseAutodiffNodeIndex, right: DenseAutodiffNodeIndex) DenseAutodiffNodeIndex {
        const kind: DenseAutodiffNodeKind = if (program.kinds[left] == .vector or program.kinds[right] == .vector) .vector else .scalar;
        return program.push(switch (tag) {
            .add => .{ .add = .{ .left = left, .right = right } },
            .sub => .{ .sub = .{ .left = left, .right = right } },
            .mul => .{ .mul = .{ .left = left, .right = right } },
        }, kind);
    }

    fn isDerivedBuiltinClosure(value: Value, kind: DerivedVerbKind, builtin: BuiltinId) bool {
        if (value.tag() != .closure) return false;
        const closure = value.asClosure();
        return closure.header.owner == .frozen and
            closureDerivedKind(closure) == kind and
            closure.captures.len == 1 and
            closure.captures[0].tag() == .builtin and
            closure.captures[0].asBuiltin() == builtin;
    }

    fn evalSourceIsolated(self: *Session, source: []const u8) KError!Value {
        var sibling = try self.initSiblingSession();
        defer sibling.deinit();
        const value = try sibling.evalSource(source);
        return try self.retainEscapedValue(value);
    }

    fn setNumericMatrixShapeOnValue(self: *Session, value: Value, rows: usize, cols: usize) !Value {
        _ = self;
        const handle = mutableNumericHandle(value) orelse return error.Type;
        numericArraySetMatrixShape(handle, rows, cols);
        return value;
    }

    fn createManagedHostNumericMatrixRows(self: *Session, array: *const HostDenseArray, row_indices: []const usize, cols: usize) KError!Value {
        const shape = numericShapeSnapshotMatrix(row_indices.len, cols);
        switch (array.storage) {
            .bit => {
                const total = row_indices.len * cols;
                const out = try self.allocHostBitArray(.managed, total);
                for (row_indices, 0..) |row_idx, out_row_idx| {
                    const src_start = row_idx * cols;
                    const dst_start = out_row_idx * cols;
                    bitCopyRange(out.words, dst_start, .{ .words = array.storage.bit, .len = array.logical_len }, src_start, cols);
                }
                const value = try self.finishManagedHostBitAlloc(out, host_dense_flag_normalized, .{ .min = 0, .max = 1 });
                return try applyNonVectorNumericShapeToValue(self, value, shape);
            },
            .float64 => |items| {
                const logical_items = hostDenseLogicalItems(f64, array, items);
                var out = std.ArrayList(f64).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, row_indices.len * cols);
                for (row_indices) |row_idx| {
                    const base = row_idx * cols;
                    try out.appendSlice(self.allocator, logical_items[base .. base + cols]);
                }
                const value = try self.createManagedHostFloatArray(out.items);
                return try applyNonVectorNumericShapeToValue(self, value, shape);
            },
            .float32 => |items| {
                const logical_items = hostDenseLogicalItems(f32, array, items);
                var out = std.ArrayList(f32).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, row_indices.len * cols);
                for (row_indices) |row_idx| {
                    const base = row_idx * cols;
                    try out.appendSlice(self.allocator, logical_items[base .. base + cols]);
                }
                const value = try self.createManagedHostFloat32Array(out.items);
                return try applyNonVectorNumericShapeToValue(self, value, shape);
            },
            else => {
                const view = hostIntArrayView(array) orelse return error.Type;
                var out = std.ArrayList(i64).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, row_indices.len * cols);
                for (row_indices) |row_idx| {
                    const base = row_idx * cols;
                    for (0..cols) |col| try out.append(self.allocator, hostIntViewItem(view, base + col));
                }
                const value = try self.createManagedHostIntArray(out.items);
                return try applyNonVectorNumericShapeToValue(self, value, shape);
            },
        }
    }

    fn copyBitMatrixRowsByDenseSelector(
        dst_words: []u64,
        source: HostBitSlice,
        selector: HostIntDenseView,
        source_rows: usize,
        cols: usize,
    ) KError!void {
        for (0..hostIntDenseViewLen(selector)) |out_row_idx| {
            const source_row = try normalizeIndex(try hostIntDenseViewItem(selector, out_row_idx), source_rows);
            bitCopyRange(dst_words, out_row_idx * cols, source, source_row * cols, cols);
        }
    }

    fn hostNumericMatrixIndexByIntVector(self: *Session, array: *const HostDenseArray, selector: HostIntArrayView, rows: usize, cols: usize) KError!Value {
        if (std.meta.activeTag(array.storage) == .bit) {
            if (comptime enable_probe_instrumentation) self.debug.host_matrix_index_copy_count += 1;
            const selected_rows = hostIntArrayViewLen(selector);
            const total = selected_rows * cols;
            const out = try self.allocHostBitArray(.managed, total);
            try copyBitMatrixRowsByDenseSelector(
                out.words,
                .{ .words = array.storage.bit, .len = array.logical_len },
                .{ .dense = selector },
                rows,
                cols,
            );
            const metadata = analyzeBitSlice(.{ .words = out.words, .len = out.len });
            const value = try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
            return try applyNonVectorNumericShapeToValue(self, value, numericShapeSnapshotMatrix(selected_rows, cols));
        }
        if (comptime enable_probe_instrumentation) self.debug.host_matrix_index_copy_count += 1;
        var row_indices = std.ArrayList(usize).empty;
        defer row_indices.deinit(self.allocator);
        try row_indices.ensureTotalCapacity(self.allocator, hostIntArrayViewLen(selector));
        for (0..hostIntArrayViewLen(selector)) |sel_idx| {
            try row_indices.append(self.allocator, try normalizeIndex(hostIntViewItem(selector, sel_idx), rows));
        }
        return try self.createManagedHostNumericMatrixRows(array, row_indices.items, cols);
    }

    fn hostNumericMatrixIndexByIntDenseView(self: *Session, array: *const HostDenseArray, selector: HostIntDenseView, rows: usize, cols: usize) KError!Value {
        if (std.meta.activeTag(array.storage) == .bit) {
            if (comptime enable_probe_instrumentation) self.debug.host_matrix_index_copy_count += 1;
            const selected_rows = hostIntDenseViewLen(selector);
            const total = selected_rows * cols;
            const out = try self.allocHostBitArray(.managed, total);
            try copyBitMatrixRowsByDenseSelector(
                out.words,
                .{ .words = array.storage.bit, .len = array.logical_len },
                selector,
                rows,
                cols,
            );
            const metadata = analyzeBitSlice(.{ .words = out.words, .len = out.len });
            const value = try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
            return try applyNonVectorNumericShapeToValue(self, value, numericShapeSnapshotMatrix(selected_rows, cols));
        }
        if (selector == .dense) return try self.hostNumericMatrixIndexByIntVector(array, selector.dense, rows, cols);
        if (comptime enable_probe_instrumentation) self.debug.host_matrix_index_copy_count += 1;
        var row_indices = std.ArrayList(usize).empty;
        defer row_indices.deinit(self.allocator);
        try row_indices.ensureTotalCapacity(self.allocator, hostIntDenseViewLen(selector));
        for (0..hostIntDenseViewLen(selector)) |sel_idx| {
            try row_indices.append(self.allocator, try normalizeIndex(try hostIntDenseViewItem(selector, sel_idx), rows));
        }
        return try self.createManagedHostNumericMatrixRows(array, row_indices.items, cols);
    }

    fn applyHostArrayIndex(self: *Session, source_value: Value, array: *const HostDenseArray, selector: Value) KError!Value {
        return switch (selector.tag()) {
            .int, .bool => try self.hostDenseIndexScalar(source_value, array, scalarIntLikeValue(selector).?),
            .array => switch (selector.arrayKind()) {
                .numeric_array => if (hostDenseIfPresent(selector)) |selector_array|
                    try self.hostDenseIndexVector(source_value, array, selector_array)
                else if (valueHostIntStructuralView(selector)) |view|
                    try self.hostDenseIndexDenseSelector(source_value, array, view)
                else
                    error.Type,
                else => error.Internal,
            },
            else => error.Type,
        };
    }

    fn applyHostBoxedArrayIndex(self: *Session, array: *const HostBoxedArray, selector: Value) KError!Value {
        return switch (selector.tag()) {
            .int, .bool => try self.hostBoxedArrayIndexScalar(array, scalarIntLikeValue(selector).?),
            .array => blk: {
                if (stringBytes(selector)) |bytes| {
                    if (bytes.len == 0) break :blk try self.selectHostBoxedArrayBySourceIndices(array, &.{});
                    const indices = try self.collectSelectorIndicesForLen(array.len(), selector);
                    defer self.allocator.free(indices);
                    break :blk try self.selectHostBoxedArrayBySourceIndices(array, indices);
                }
                break :blk switch (selector.arrayKind()) {
                    .numeric_array => if (hostDenseIfPresent(selector)) |selector_array|
                        try self.hostBoxedArrayIndexVector(array, selector_array)
                    else if (valueHostIntStructuralView(selector)) |view|
                        try self.hostBoxedArrayIndexDenseSelector(array, view)
                    else
                        error.Type,
                    else => error.Internal,
                };
            },
            else => error.Type,
        };
    }

    fn hostDenseIndexScalar(self: *Session, source_value: Value, array: *const HostDenseArray, raw_index: i64) KError!Value {
        if (valueNonVectorNumericShape(source_value) != null) return try numericValueScalarIndexValue(self, source_value, raw_index) orelse error.Type;
        const idx = normalizeIndexOrNull(raw_index, array.len()) orelse return try self.hostDensePrototypeScalarValue(array);
        return switch (array.storage) {
            .bit => |words| Value.fromBool(bitGet(words, idx)),
            .int8, .int16, .int32, .int64 => try self.intValue(hostIntViewItem(hostIntArrayView(array).?, idx)),
            .float32 => |items| try self.float32Value(items[idx]),
            .float64 => |items| try self.floatValue(items[idx]),
        };
    }

    fn hostBoxedArrayIndexScalar(self: *Session, array: *const HostBoxedArray, raw_index: i64) KError!Value {
        const idx = normalizeIndexOrNull(raw_index, array.len()) orelse {
            if (array.len() == 0) {
                if (array.prototype) |prototype| return try self.retainEscapedValue(prototype);
                return try self.managedHostString(&.{});
            }
            return try self.deepPrototypeValue(.managed, array.items[0]);
        };
        return self.shareValue(array.items[idx]);
    }

    fn hostDenseIndexVector(self: *Session, source_value: Value, array: *const HostDenseArray, selector: *const HostDenseArray) KError!Value {
        if (hostIntArrayView(selector)) |selector_view| {
            if (std.meta.activeTag(selector_view) != .bit and denseSelectorCachedRangeFitsSource(selector, array.logical_len)) {
                if (comptime enable_probe_instrumentation) self.debug.host_index_in_bounds_fast_count += 1;
                return switch (array.storage) {
                    .bit => try self.gatherManagedHostBitArraySelectionInBounds(.{ .words = array.storage.bit, .len = array.logical_len }, selector_view),
                    .float32 => |items| try self.gatherManagedHostFloat32ArraySelectionInBounds(items, selector_view),
                    .float64 => |items| try self.gatherManagedHostFloatArraySelectionInBounds(items, selector_view),
                    else => try self.gatherManagedHostIntArraySelectionInBounds(hostIntArrayView(array).?, selector_view),
                };
            }
            if (comptime enable_probe_instrumentation) self.debug.host_index_in_bounds_fallback_count += 1;
            return try self.hostDenseIndexByIntVector(source_value, array, selector_view);
        }
        return error.Type;
    }

    fn hostBoxedArrayIndexVector(self: *Session, array: *const HostBoxedArray, selector: *const HostDenseArray) KError!Value {
        if (hostIntArrayView(selector)) |selector_view| {
            return try self.hostBoxedArrayIndexByIntVector(array, selector_view);
        }
        return error.Type;
    }

    fn hostDenseIndexDenseSelector(self: *Session, source_value: Value, array: *const HostDenseArray, selector: HostIntDenseView) KError!Value {
        return try self.hostDenseIndexByIntDenseView(source_value, array, selector);
    }

    fn hostBoxedArrayIndexDenseSelector(self: *Session, array: *const HostBoxedArray, selector: HostIntDenseView) KError!Value {
        return try self.hostBoxedArrayIndexByIntDenseView(array, selector);
    }

    const DenseIntGatherStats = struct {
        flags: u8,
        range: HostIntRange,
    };

    const DenseIntGatherStatsBuilder = struct {
        asc: bool = true,
        dsc: bool = true,
        min_value: i64 = 0,
        max_value: i64 = 0,
        prev: i64 = 0,
        count: usize = 0,

        fn push(self: *DenseIntGatherStatsBuilder, item: i64) void {
            if (self.count == 0) {
                self.min_value = item;
                self.max_value = item;
            } else {
                self.min_value = @min(self.min_value, item);
                self.max_value = @max(self.max_value, item);
                if (self.prev > item) self.asc = false;
                if (self.prev < item) self.dsc = false;
            }
            self.prev = item;
            self.count += 1;
        }

        fn finish(self: DenseIntGatherStatsBuilder) DenseIntGatherStats {
            return .{
                .flags = host_dense_flag_normalized | orderFlagsFromMonotonic(self.asc, self.dsc),
                .range = if (self.count == 0)
                    .{ .min = 0, .max = 0 }
                else
                    .{ .min = self.min_value, .max = self.max_value },
            };
        }
    };

    const DenseBitSequenceStatsBuilder = struct {
        asc: bool = true,
        dsc: bool = true,
        saw_zero: bool = false,
        saw_one: bool = false,
        prev: bool = false,
        count: usize = 0,

        fn pushWord(self: *DenseBitSequenceStatsBuilder, word: u64, active_len: usize) void {
            if (active_len == 0) return;
            const active_mask = bitLowMask(active_len);
            const masked = word & active_mask;
            if (masked != 0) self.saw_one = true;
            if (masked != active_mask) self.saw_zero = true;

            const first = (masked & 1) != 0;
            if (self.count != 0) {
                if (@intFromBool(self.prev) > @intFromBool(first)) self.asc = false;
                if (@intFromBool(self.prev) < @intFromBool(first)) self.dsc = false;
            }
            if (active_len > 1) {
                const transition_mask = bitLowMask(active_len - 1);
                if (((masked & ~(masked >> 1)) & transition_mask) != 0) self.asc = false;
                if (((~masked & (masked >> 1)) & transition_mask) != 0) self.dsc = false;
            }
            self.prev = ((masked >> @intCast(active_len - 1)) & 1) != 0;
            self.count += active_len;
        }

        fn finish(self: DenseBitSequenceStatsBuilder) DenseIntGatherStats {
            return .{
                .flags = host_dense_flag_normalized | orderFlagsFromMonotonic(self.asc, self.dsc),
                .range = if (self.count == 0)
                    .{ .min = 0, .max = 0 }
                else
                    .{
                        .min = if (self.saw_zero) 0 else 1,
                        .max = if (self.saw_one) 1 else 0,
                    },
            };
        }
    };

    fn denseSelectorCachedRangeFitsSource(selector: *const HostDenseArray, source_len: usize) bool {
        const range = hostDenseCachedIntRange(selector) orelse return false;
        if (range.min < 0) return false;
        if (selector.logical_len == 0) return true;
        const source_len_i64 = std.math.cast(i64, source_len) orelse return false;
        return range.max < source_len_i64;
    }

    fn gatherTypedBitDenseSelectionUnchecked(
        comptime SelT: type,
        out: *HostBitAlloc,
        source: HostBitSlice,
        selector: []const SelT,
    ) DenseIntGatherStats {
        const src = source.words;
        var selector_ptr: [*]const SelT = selector.ptr;
        var stats = DenseBitSequenceStatsBuilder{};

        for (0..out.words.len) |word_idx| {
            const active_len = bitWordActiveLen(out.len, word_idx, out.words.len);
            var word: u64 = 0;
            var bit_idx: usize = 0;
            while (bit_idx + 8 <= active_len) : (bit_idx += 8) {
                const chunk =
                    (@as(u64, @intFromBool(bitGet(src, @as(usize, @intCast(selector_ptr[0]))))) << 0) |
                    (@as(u64, @intFromBool(bitGet(src, @as(usize, @intCast(selector_ptr[1]))))) << 1) |
                    (@as(u64, @intFromBool(bitGet(src, @as(usize, @intCast(selector_ptr[2]))))) << 2) |
                    (@as(u64, @intFromBool(bitGet(src, @as(usize, @intCast(selector_ptr[3]))))) << 3) |
                    (@as(u64, @intFromBool(bitGet(src, @as(usize, @intCast(selector_ptr[4]))))) << 4) |
                    (@as(u64, @intFromBool(bitGet(src, @as(usize, @intCast(selector_ptr[5]))))) << 5) |
                    (@as(u64, @intFromBool(bitGet(src, @as(usize, @intCast(selector_ptr[6]))))) << 6) |
                    (@as(u64, @intFromBool(bitGet(src, @as(usize, @intCast(selector_ptr[7]))))) << 7);
                word |= chunk << @intCast(bit_idx);
                selector_ptr += 8;
            }
            while (bit_idx < active_len) : (bit_idx += 1) {
                if (bitGet(src, @as(usize, @intCast(selector_ptr[0])))) {
                    word |= @as(u64, 1) << @intCast(bit_idx);
                }
                selector_ptr += 1;
            }
            out.words[word_idx] = word;
            stats.pushWord(word, active_len);
        }

        return stats.finish();
    }

    fn gatherBitDenseSelectionUnchecked(
        out: *HostBitAlloc,
        source: HostBitSlice,
        selector: HostIntArrayView,
    ) DenseIntGatherStats {
        return switch (selector) {
            .bit => unreachable,
            .int8 => |items| gatherTypedBitDenseSelectionUnchecked(i8, out, source, items),
            .int16 => |items| gatherTypedBitDenseSelectionUnchecked(i16, out, source, items),
            .int32 => |items| gatherTypedBitDenseSelectionUnchecked(i32, out, source, items),
            .int64 => |items| gatherTypedBitDenseSelectionUnchecked(i64, out, source, items),
        };
    }

    fn gatherTypedIntDenseSelectionUnchecked(
        comptime T: type,
        comptime SelT: type,
        out: []T,
        source: []const T,
        selector: []const SelT,
    ) void {
        const src: [*]const T = source.ptr;
        var dst: [*]T = out.ptr;
        var idx: usize = 0;
        while (idx + 8 <= selector.len) : (idx += 8) {
            const item0 = src[@as(usize, @intCast(selector[idx + 0]))];
            const item1 = src[@as(usize, @intCast(selector[idx + 1]))];
            const item2 = src[@as(usize, @intCast(selector[idx + 2]))];
            const item3 = src[@as(usize, @intCast(selector[idx + 3]))];
            const item4 = src[@as(usize, @intCast(selector[idx + 4]))];
            const item5 = src[@as(usize, @intCast(selector[idx + 5]))];
            const item6 = src[@as(usize, @intCast(selector[idx + 6]))];
            const item7 = src[@as(usize, @intCast(selector[idx + 7]))];
            dst[0] = item0;
            dst[1] = item1;
            dst[2] = item2;
            dst[3] = item3;
            dst[4] = item4;
            dst[5] = item5;
            dst[6] = item6;
            dst[7] = item7;
            dst += 8;
        }
        while (idx < selector.len) : (idx += 1) {
            const item = src[@as(usize, @intCast(selector[idx]))];
            dst[0] = item;
            dst += 1;
        }
    }

    fn gatherIntDenseSelectionUnchecked(
        comptime T: type,
        out: []T,
        source: []const T,
        selector: HostIntArrayView,
    ) void {
        switch (selector) {
            .bit => unreachable,
            .int8 => |items| gatherTypedIntDenseSelectionUnchecked(T, i8, out, source, items),
            .int16 => |items| gatherTypedIntDenseSelectionUnchecked(T, i16, out, source, items),
            .int32 => |items| gatherTypedIntDenseSelectionUnchecked(T, i32, out, source, items),
            .int64 => |items| gatherTypedIntDenseSelectionUnchecked(T, i64, out, source, items),
        }
    }

    fn gatherTypedFloatDenseSelectionUnchecked(
        comptime FloatT: type,
        comptime SelT: type,
        out: []FloatT,
        source: []const FloatT,
        selector: []const SelT,
    ) void {
        for (selector, 0..) |raw_idx, out_idx| {
            out[out_idx] = source[@as(usize, @intCast(raw_idx))];
        }
    }

    fn gatherFloatDenseSelectionUnchecked(comptime FloatT: type, out: []FloatT, source: []const FloatT, selector: HostIntArrayView) void {
        switch (selector) {
            .bit => unreachable,
            .int8 => |items| gatherTypedFloatDenseSelectionUnchecked(FloatT, i8, out, source, items),
            .int16 => |items| gatherTypedFloatDenseSelectionUnchecked(FloatT, i16, out, source, items),
            .int32 => |items| gatherTypedFloatDenseSelectionUnchecked(FloatT, i32, out, source, items),
            .int64 => |items| gatherTypedFloatDenseSelectionUnchecked(FloatT, i64, out, source, items),
        }
    }

    fn gatherManagedHostBitArraySelectionInBounds(self: *Session, source: HostBitSlice, selector: HostIntArrayView) KError!Value {
        const len = hostIntArrayViewLen(selector);
        var out = try self.allocManagedHostIntResult(.bit, len);
        const stats = switch (out) {
            .bit => |*result| gatherBitDenseSelectionUnchecked(result, source, selector),
            else => unreachable,
        };

        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, stats.flags);
        hostDenseSetCachedIntRange(host, stats.range);
        return value;
    }

    fn gatherManagedHostBitArraySelection(self: *Session, source: HostBitSlice, selector: HostIntArrayView) KError!Value {
        const len = hostIntArrayViewLen(selector);
        var out = try self.allocManagedHostIntResult(.bit, len);

        var asc = true;
        var dsc = true;
        var saw_zero = len == 0;
        var saw_one = false;
        var prev = false;

        switch (out) {
            .bit => |*result| {
                for (0..len) |idx| {
                    const source_idx = try normalizeIndex(hostIntViewItem(selector, idx), source.len);
                    const item = bitGet(source.words, source_idx);
                    bitSet(result.words, idx, item);
                    if (idx == 0) {
                        saw_zero = !item;
                        saw_one = item;
                    } else {
                        if (item) saw_one = true else saw_zero = true;
                        if (@intFromBool(prev) > @intFromBool(item)) asc = false;
                        if (@intFromBool(prev) < @intFromBool(item)) dsc = false;
                    }
                    prev = item;
                }
            },
            else => unreachable,
        }

        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, host_dense_flag_normalized | orderFlagsFromMonotonic(asc, dsc));
        hostDenseSetCachedIntRange(host, .{
            .min = if (saw_zero) 0 else 1,
            .max = if (saw_one) 1 else 0,
        });
        return value;
    }

    fn gatherManagedHostFloatArraySelection(self: *Session, source: []const f64, selector: HostIntArrayView) KError!Value {
        const len = hostIntArrayViewLen(selector);
        var out = try self.allocManagedHostFloatResult(len);
        for (0..len) |idx| {
            const source_idx = try normalizeIndex(hostIntViewItem(selector, idx), source.len);
            out.items[idx] = source[source_idx];
        }

        const value = out.value();
        const analysis = analyzeFloatSlice(out.items);
        hostDenseSetFlags(try mutableNumericHostArrayValue(self, value), analysis.flags);
        return value;
