        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, host_dense_flag_normalized | if (len <= 1) host_dense_flag_asc | host_dense_flag_dsc else 0);
        return value;
    }

