        for (0..out.len) |query_idx| {
            const query = @as(f64, @floatFromInt(try hostIntDenseViewItem(right_items, query_idx)));
            if (!has_valid_bounds) {
                out[query_idx] = miss_i64;
                continue;
            }
            if ((mono & host_dense_flag_asc) != 0) {
