    }

    fn tryFillIntFindSortedIntQueries(
        left: Value,
        left_items: HostIntDenseView,
        right_items: HostIntDenseView,
        out: []i64,
        miss_index: usize,
    ) KError!bool {
        const mono = monotonicFlags(hostIntDenseValueFlags(left, left_items));
        if (mono == 0) return false;
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        const len = hostIntDenseViewLen(left_items);
        if (len == 0) {
            @memset(out, miss_i64);
            return true;
        }
        const bounds = hostIntDenseValueRange(left, left_items);
        for (0..out.len) |query_idx| {
            const query = try hostIntDenseViewItem(right_items, query_idx);
            if (query < bounds.min or query > bounds.max) {
                out[query_idx] = miss_i64;
                continue;
            }
            if ((mono & host_dense_flag_asc) != 0) {
                const idx = try lowerBoundAscInt(left_items, query);
                out[query_idx] = if (idx < len and (try hostIntDenseViewItem(left_items, idx)) == query)
                    std.math.cast(i64, idx) orelse return error.Unsupported
                else
                    miss_i64;
                continue;
            }
            if ((mono & host_dense_flag_dsc) != 0) {
                const idx = try lowerBoundDscInt(left_items, query);
                out[query_idx] = if (idx < len and (try hostIntDenseViewItem(left_items, idx)) == query)
                    std.math.cast(i64, idx) orelse return error.Unsupported
                else
                    miss_i64;
                continue;
            }
            out[query_idx] = miss_i64;
        }
        return true;
    }

    fn tryFillIntFindSortedFloatQueries(
        left: Value,
        left_items: HostIntDenseView,
        right_items: HostFloatDenseView,
        out: []i64,
        miss_index: usize,
    ) KError!bool {
        const mono = monotonicFlags(hostIntDenseValueFlags(left, left_items));
        if (mono == 0) return false;
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        const len = hostIntDenseViewLen(left_items);
        if (len == 0) {
            @memset(out, miss_i64);
            return true;
        }
        const bounds = hostIntDenseValueRange(left, left_items);
        for (0..out.len) |query_idx| {
            const query = exactIntFromFloat(try hostFloatDenseViewItem(right_items, query_idx));
            if (query == null or query.? < bounds.min or query.? > bounds.max) {
                out[query_idx] = miss_i64;
                continue;
            }
            if ((mono & host_dense_flag_asc) != 0) {
                const idx = try lowerBoundAscInt(left_items, query.?);
                out[query_idx] = if (idx < len and (try hostIntDenseViewItem(left_items, idx)) == query.?)
                    std.math.cast(i64, idx) orelse return error.Unsupported
                else
                    miss_i64;
                continue;
            }
            if ((mono & host_dense_flag_dsc) != 0) {
                const idx = try lowerBoundDscInt(left_items, query.?);
                out[query_idx] = if (idx < len and (try hostIntDenseViewItem(left_items, idx)) == query.?)
                    std.math.cast(i64, idx) orelse return error.Unsupported
                else
                    miss_i64;
                continue;
            }
            out[query_idx] = miss_i64;
        }
        return true;
    }

    fn rangeIotaFindIndexForQuery(left_items: HostRangeIotaView, query: i64, miss_i64: i64) KError!i64 {
        const len = hostRangeIotaViewLen(left_items);
        if (len == 0) return miss_i64;
        const range = numericArrayRangeIota(left_items.handle);
        if (range.step == 0) return if (query == range.start) 0 else miss_i64;

        if (range.step == 1) {
            const idx_i128 = @as(i128, query) - @as(i128, range.start);
            if (idx_i128 < 0) return miss_i64;
            const idx = std.math.cast(usize, idx_i128) orelse return miss_i64;
            if (idx >= len) return miss_i64;
            return std.math.cast(i64, idx) orelse return error.Unsupported;
        }

        if (range.step == -1) {
            const idx_i128 = @as(i128, range.start) - @as(i128, query);
            if (idx_i128 < 0) return miss_i64;
            const idx = std.math.cast(usize, idx_i128) orelse return miss_i64;
            if (idx >= len) return miss_i64;
            return std.math.cast(i64, idx) orelse return error.Unsupported;
        }

        const delta = @as(i128, query) - @as(i128, range.start);
        const step = @as(i128, range.step);
        const step_abs = if (step < 0) -step else step;
        if (@mod(delta, step_abs) != 0) return miss_i64;

        const idx_i128 = @divTrunc(delta, step);
        if (idx_i128 < 0) return miss_i64;
        const idx = std.math.cast(usize, idx_i128) orelse return miss_i64;
        if (idx >= len) return miss_i64;
        return std.math.cast(i64, idx) orelse return error.Unsupported;
    }

    fn fillRangeIotaFindRangeIotaQueries(out: []i64, left_items: HostRangeIotaView, right_items: HostRangeIotaView, miss_i64: i64) KError!void {
        const left_range = numericArrayRangeIota(left_items.handle);
        const right_range = numericArrayRangeIota(right_items.handle);

        if (left_range.step == 1 and right_range.step == 1) {
            var query = right_range.start;
            for (out) |*slot| {
                slot.* = try rangeIotaFindIndexForQuery(left_items, query, miss_i64);
                query = std.math.add(i64, query, 1) catch return error.Unsupported;
            }
            return;
        }

        if (left_range.step == -1 and right_range.step == -1) {
            var query = right_range.start;
            for (out) |*slot| {
                slot.* = try rangeIotaFindIndexForQuery(left_items, query, miss_i64);
                query = std.math.sub(i64, query, 1) catch return error.Unsupported;
            }
            return;
        }

        for (0..out.len) |query_idx| {
            out[query_idx] = try rangeIotaFindIndexForQuery(left_items, try hostRangeIotaViewItem(right_items, query_idx), miss_i64);
        }
    }

    fn tryFillIntFindRangeIotaIntQueries(
        left_items: HostIntDenseView,
        right_items: HostIntDenseView,
        out: []i64,
        miss_index: usize,
    ) KError!bool {
        const range = switch (left_items) {
            .range_iota => |items| items,
            else => return false,
        };
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        if (right_items == .range_iota) {
            const left_bounds = hostRangeIotaViewBounds(range);
            const right_bounds = hostRangeIotaViewBounds(right_items.range_iota);
            if (right_bounds.max < left_bounds.min or right_bounds.min > left_bounds.max) {
                @memset(out, miss_i64);
                return true;
            }
            try fillRangeIotaFindRangeIotaQueries(out, range, right_items.range_iota, miss_i64);
            return true;
        }
        for (0..out.len) |query_idx| {
            out[query_idx] = try rangeIotaFindIndexForQuery(range, try hostIntDenseViewItem(right_items, query_idx), miss_i64);
        }
        return true;
    }

    fn findIntSmallRangeSpan(left_len: usize, out_len: usize, range: HostIntRange) ?usize {
        const span_i128 = @as(i128, range.max) - @as(i128, range.min) + 1;
        if (span_i128 <= 0) return null;
        const span = std.math.cast(usize, span_i128) orelse return null;
        if (span > find_int_small_range_max_span) return null;
        const work_budget: u128 = 4 * (@as(u128, left_len) + @as(u128, out_len)) + 16;
        if (@as(u128, span) > work_budget) return null;
        return span;
    }

    fn fillIntFindSmallRangeTableFromDense(table: []i64, left_items: HostIntArrayView, min_value: i64, miss_i64: i64) KError!void {
        switch (left_items) {
            .bit => |items| {
                for (0..items.len) |idx| {
                    const value: i64 = @intFromBool(bitGet(items.words, idx));
                    const slot = @as(usize, @intCast(value - min_value));
                    if (table[slot] == miss_i64) table[slot] = std.math.cast(i64, idx) orelse return error.Unsupported;
                }
            },
            .int8 => |items| {
                for (items, 0..) |item, idx| {
                    const value: i64 = item;
                    const slot = @as(usize, @intCast(value - min_value));
                    if (table[slot] == miss_i64) table[slot] = std.math.cast(i64, idx) orelse return error.Unsupported;
                }
            },
            .int16 => |items| {
                for (items, 0..) |item, idx| {
                    const value: i64 = item;
                    const slot = @as(usize, @intCast(value - min_value));
                    if (table[slot] == miss_i64) table[slot] = std.math.cast(i64, idx) orelse return error.Unsupported;
                }
            },
            .int32 => |items| {
                for (items, 0..) |item, idx| {
                    const value: i64 = item;
                    const slot = @as(usize, @intCast(value - min_value));
                    if (table[slot] == miss_i64) table[slot] = std.math.cast(i64, idx) orelse return error.Unsupported;
                }
            },
            .int64 => |items| {
                for (items, 0..) |item, idx| {
                    const slot = @as(usize, @intCast(item - min_value));
                    if (table[slot] == miss_i64) table[slot] = std.math.cast(i64, idx) orelse return error.Unsupported;
                }
            },
        }
    }

    fn fillIntFindSmallRangeDenseQueries(out: []i64, table: []const i64, right_items: HostIntArrayView, range: HostIntRange, miss_i64: i64) void {
        switch (right_items) {
            .bit => |items| {
                for (0..items.len) |idx| {
                    const query: i64 = @intFromBool(bitGet(items.words, idx));
                    out[idx] = if (query < range.min or query > range.max) miss_i64 else table[@as(usize, @intCast(query - range.min))];
                }
            },
            .int8 => |items| {
                for (items, 0..) |item, idx| {
                    const query: i64 = item;
                    out[idx] = if (query < range.min or query > range.max) miss_i64 else table[@as(usize, @intCast(query - range.min))];
                }
            },
            .int16 => |items| {
                for (items, 0..) |item, idx| {
                    const query: i64 = item;
                    out[idx] = if (query < range.min or query > range.max) miss_i64 else table[@as(usize, @intCast(query - range.min))];
                }
            },
            .int32 => |items| {
                for (items, 0..) |item, idx| {
                    const query: i64 = item;
                    out[idx] = if (query < range.min or query > range.max) miss_i64 else table[@as(usize, @intCast(query - range.min))];
                }
            },
            .int64 => |items| {
                for (items, 0..) |query, idx| {
                    out[idx] = if (query < range.min or query > range.max) miss_i64 else table[@as(usize, @intCast(query - range.min))];
                }
            },
        }
    }

    fn intFindSmallRangeDenseQueriesAllHit(table: []const i64, right_items: HostIntArrayView, range: HostIntRange, miss_i64: i64) bool {
        return switch (right_items) {
            .bit => |items| blk: {
                for (0..items.len) |idx| {
                    const query: i64 = @intFromBool(bitGet(items.words, idx));
                    if (query < range.min or query > range.max) break :blk false;
                    if (table[@as(usize, @intCast(query - range.min))] == miss_i64) break :blk false;
                }
                break :blk true;
            },
            .int8 => |items| blk: {
                for (items) |item| {
                    const query: i64 = item;
                    if (query < range.min or query > range.max) break :blk false;
                    if (table[@as(usize, @intCast(query - range.min))] == miss_i64) break :blk false;
                }
                break :blk true;
            },
            .int16 => |items| blk: {
                for (items) |item| {
                    const query: i64 = item;
                    if (query < range.min or query > range.max) break :blk false;
                    if (table[@as(usize, @intCast(query - range.min))] == miss_i64) break :blk false;
                }
                break :blk true;
            },
            .int32 => |items| blk: {
                for (items) |item| {
                    const query: i64 = item;
                    if (query < range.min or query > range.max) break :blk false;
                    if (table[@as(usize, @intCast(query - range.min))] == miss_i64) break :blk false;
                }
                break :blk true;
            },
            .int64 => |items| blk: {
                for (items) |query| {
                    if (query < range.min or query > range.max) break :blk false;
                    if (table[@as(usize, @intCast(query - range.min))] == miss_i64) break :blk false;
                }
                break :blk true;
            },
        };
    }

    const FindMultiOutputStats = struct {
        initialized: bool = false,
        saw_miss: bool = false,
        min_value: i64 = 0,
        max_value: i64 = 0,
        prev_value: i64 = 0,
        asc: bool = true,
        dsc: bool = true,

        fn observe(self: *FindMultiOutputStats, value: i64, miss_i64: i64) void {
            if (value == miss_i64) self.saw_miss = true;
            if (!self.initialized) {
                self.initialized = true;
                self.min_value = value;
                self.max_value = value;
                self.prev_value = value;
                return;
            }
            self.min_value = @min(self.min_value, value);
            self.max_value = @max(self.max_value, value);
            if (self.prev_value > value) self.asc = false;
            if (self.prev_value < value) self.dsc = false;
            self.prev_value = value;
        }

        fn range(self: FindMultiOutputStats) HostIntRange {
            return if (self.initialized)
                .{ .min = self.min_value, .max = self.max_value }
            else
                .{ .min = 0, .max = 0 };
        }

        fn flags(self: FindMultiOutputStats) u8 {
            return host_dense_flag_normalized | orderFlagsFromMonotonic(self.asc, self.dsc);
        }
    };

    fn findMultiIndexOutputKind(miss_index: usize) KError!HostIntStorageKind {
        const max_index = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        return hostIntStorageKindForRange(0, max_index);
    }

    fn storeFindMultiOutput(comptime OutT: type, out: []OutT, idx: usize, value: i64, miss_i64: i64, stats: *FindMultiOutputStats) void {
        out[idx] = @intCast(value);
        stats.observe(value, miss_i64);
    }

    fn fillIntFindSmallRangeDenseQueriesOutput(
        comptime OutT: type,
        out: []OutT,
        table: []const i64,
        right_items: HostIntArrayView,
        range: HostIntRange,
        miss_i64: i64,
    ) FindMultiOutputStats {
        var stats = FindMultiOutputStats{};
        switch (right_items) {
            .bit => |items| {
                for (0..items.len) |idx| {
                    const query: i64 = @intFromBool(bitGet(items.words, idx));
                    const value = if (query < range.min or query > range.max) miss_i64 else table[@as(usize, @intCast(query - range.min))];
                    storeFindMultiOutput(OutT, out, idx, value, miss_i64, &stats);
                }
            },
            .int8 => |items| {
                for (items, 0..) |item, idx| {
                    const query: i64 = item;
                    const value = if (query < range.min or query > range.max) miss_i64 else table[@as(usize, @intCast(query - range.min))];
                    storeFindMultiOutput(OutT, out, idx, value, miss_i64, &stats);
                }
            },
            .int16 => |items| {
                for (items, 0..) |item, idx| {
                    const query: i64 = item;
                    const value = if (query < range.min or query > range.max) miss_i64 else table[@as(usize, @intCast(query - range.min))];
                    storeFindMultiOutput(OutT, out, idx, value, miss_i64, &stats);
                }
            },
            .int32 => |items| {
                for (items, 0..) |item, idx| {
                    const query: i64 = item;
                    const value = if (query < range.min or query > range.max) miss_i64 else table[@as(usize, @intCast(query - range.min))];
                    storeFindMultiOutput(OutT, out, idx, value, miss_i64, &stats);
                }
            },
            .int64 => |items| {
                for (items, 0..) |query, idx| {
                    const value = if (query < range.min or query > range.max) miss_i64 else table[@as(usize, @intCast(query - range.min))];
                    storeFindMultiOutput(OutT, out, idx, value, miss_i64, &stats);
                }
            },
        }
        return stats;
    }

    fn int8FindFullDomainSlot(value: i8) usize {
        return @intCast(@as(u8, @bitCast(value)));
    }

    fn int16FindFullDomainSlot(value: i16) usize {
        return @intCast(@as(u16, @bitCast(value)));
    }

    fn fillInt8FindFullDomainTable(table: []i32, left_items: []const i8, miss_i32: i32) void {
        @memset(table, miss_i32);
        var idx = left_items.len;
        while (idx != 0) {
            idx -= 1;
            table[int8FindFullDomainSlot(left_items[idx])] = @intCast(idx);
        }
    }

    fn fillInt16FindFullDomainTable(table: []i32, left_items: []const i16, miss_i32: i32) void {
        @memset(table, miss_i32);
        var idx = left_items.len;
        while (idx != 0) {
            idx -= 1;
            table[int16FindFullDomainSlot(left_items[idx])] = @intCast(idx);
        }
    }

    fn fillInt8FindFullDomainQueriesOutput(comptime OutT: type, out: []OutT, table: []const i32, right_items: []const i8, miss_i64: i64) FindMultiOutputStats {
        var stats = FindMultiOutputStats{};
        for (right_items, 0..) |query, idx| {
            storeFindMultiOutput(OutT, out, idx, table[int8FindFullDomainSlot(query)], miss_i64, &stats);
        }
        return stats;
    }

    fn fillInt16FindFullDomainInt8QueriesOutput(comptime OutT: type, out: []OutT, table: []const i32, right_items: []const i8, miss_i64: i64) FindMultiOutputStats {
        var stats = FindMultiOutputStats{};
        for (right_items, 0..) |query, idx| {
            storeFindMultiOutput(OutT, out, idx, table[int16FindFullDomainSlot(query)], miss_i64, &stats);
        }
        return stats;
    }

    fn fillInt16FindFullDomainQueriesOutput(comptime OutT: type, out: []OutT, table: []const i32, right_items: []const i16, miss_i64: i64) FindMultiOutputStats {
        var stats = FindMultiOutputStats{};
        for (right_items, 0..) |query, idx| {
            storeFindMultiOutput(OutT, out, idx, table[int16FindFullDomainSlot(query)], miss_i64, &stats);
        }
        return stats;
    }

    fn finishInt8FindFullDomainDenseValue(self: *Session, table: []const i32, right_items: []const i8, miss_index: usize) KError!Value {
        const out_len = right_items.len;
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        var out = try self.allocManagedHostIntResult(try findMultiIndexOutputKind(miss_index), out_len);
        const stats = switch (out) {
            .int8 => |*items| fillInt8FindFullDomainQueriesOutput(i8, items.items, table, right_items, miss_i64),
            .int16 => |*items| fillInt8FindFullDomainQueriesOutput(i16, items.items, table, right_items, miss_i64),
            .int32 => |*items| fillInt8FindFullDomainQueriesOutput(i32, items.items, table, right_items, miss_i64),
            .int64 => |*items| fillInt8FindFullDomainQueriesOutput(i64, items.items, table, right_items, miss_i64),
            .bit => unreachable,
        };
        return try self.finishFindMultiOutputValue(&out, stats, miss_index, out_len);
    }

    fn finishInt16FindFullDomainInt8QueriesDenseValue(self: *Session, table: []const i32, right_items: []const i8, miss_index: usize) KError!Value {
        const out_len = right_items.len;
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        var out = try self.allocManagedHostIntResult(try findMultiIndexOutputKind(miss_index), out_len);
        const stats = switch (out) {
            .int8 => |*items| fillInt16FindFullDomainInt8QueriesOutput(i8, items.items, table, right_items, miss_i64),
            .int16 => |*items| fillInt16FindFullDomainInt8QueriesOutput(i16, items.items, table, right_items, miss_i64),
            .int32 => |*items| fillInt16FindFullDomainInt8QueriesOutput(i32, items.items, table, right_items, miss_i64),
            .int64 => |*items| fillInt16FindFullDomainInt8QueriesOutput(i64, items.items, table, right_items, miss_i64),
            .bit => unreachable,
        };
        return try self.finishFindMultiOutputValue(&out, stats, miss_index, out_len);
    }

    fn finishInt16FindFullDomainDenseValue(self: *Session, table: []const i32, right_items: []const i16, miss_index: usize) KError!Value {
        const out_len = right_items.len;
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        var out = try self.allocManagedHostIntResult(try findMultiIndexOutputKind(miss_index), out_len);
        const stats = switch (out) {
            .int8 => |*items| fillInt16FindFullDomainQueriesOutput(i8, items.items, table, right_items, miss_i64),
            .int16 => |*items| fillInt16FindFullDomainQueriesOutput(i16, items.items, table, right_items, miss_i64),
            .int32 => |*items| fillInt16FindFullDomainQueriesOutput(i32, items.items, table, right_items, miss_i64),
            .int64 => |*items| fillInt16FindFullDomainQueriesOutput(i64, items.items, table, right_items, miss_i64),
            .bit => unreachable,
        };
        return try self.finishFindMultiOutputValue(&out, stats, miss_index, out_len);
    }

    fn finishFindMultiOutputValue(
        self: *Session,
        out: *HostIntResult,
        stats: FindMultiOutputStats,
        miss_index: usize,
        out_len: usize,
    ) KError!Value {
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, stats.flags());
        hostDenseSetCachedIntRange(host, stats.range());
        if (!stats.saw_miss) return value;

        defer self.releaseValue(value);
        return try self.normalizeKnownFindMissResult(value, miss_index, out_len);
    }

    fn finishFindFullDomainOutputValue(self: *Session, out: *HostIntResult, saw_miss: bool, miss_index: usize, out_len: usize) KError!Value {
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, host_dense_flag_normalized);
        hostDenseClearCachedIntRange(host);
        if (!saw_miss) return value;

        defer self.releaseValue(value);
        return try self.normalizeKnownFindMissResult(value, miss_index, out_len);
    }

    fn tryFastHostNumericVectorFindFullDomainDenseValue(self: *Session, left: Value, right: Value, miss_index: usize) KError!?Value {
        const left_view = hostDenseView(self, left) catch return null;
        const right_view = hostDenseView(self, right) catch return null;
        const left_items = switch (left_view) {
            .int_array => |items| switch (items) {
                .dense => |dense_items| dense_items,
                else => return null,
            },
            else => return null,
        };
        const right_items = switch (right_view) {
            .int_array => |items| switch (items) {
                .dense => |dense_items| dense_items,
                else => return null,
            },
            else => return null,
        };

        const out_len = hostIntArrayViewLen(right_items);
        if (out_len <= 1) return null;
        const left_len = hostIntArrayViewLen(left_items);
        if (left_len == 0) return null;
        const miss_i32 = std.math.cast(i32, miss_index) orelse return null;
        const out_kind = try findMultiIndexOutputKind(miss_index);

        const dense_left_view: HostIntDenseView = .{ .dense = left_items };
        if (monotonicFlags(hostIntDenseValueFlags(left, dense_left_view)) != 0) return null;

        switch (left_items) {
            .int8 => |left_ints| switch (right_items) {
                .int8 => |right_ints| {
                    const table = try self.allocator.alloc(i32, 256);
                    defer self.allocator.free(table);
                    if (comptime !enable_host_find_full_domain_c_helpers) {
                        fillInt8FindFullDomainTable(table, left_ints, miss_i32);
                        return try self.finishInt8FindFullDomainDenseValue(table, right_ints, miss_index);
                    }
                    if (out_kind != .int32) {
                        fillInt8FindFullDomainTable(table, left_ints, miss_i32);
                        return try self.finishInt8FindFullDomainDenseValue(table, right_ints, miss_index);
                    }
                    kiwi_host_find_i8_build_table_i32(table.ptr, left_ints.ptr, left_ints.len, miss_i32);
                    if (table[int8FindFullDomainSlot(right_ints[0])] == miss_i32) {
                        var out = try self.allocManagedHostIntResult(.int64, out_len);
                        const out_items = switch (out) {
                            .int64 => |items| items.items,
                            else => unreachable,
                        };
                        kiwi_host_find_i8_lookup_table_i64_null(out_items.ptr, table.ptr, right_ints.ptr, right_ints.len, miss_i32, kiwi_int_null);
                        return try self.finishFindFullDomainOutputValue(&out, false, miss_index, out_len);
                    }
                    var out = try self.allocManagedHostIntResult(.int32, out_len);
                    const out_items = switch (out) {
                        .int32 => |items| items.items,
                        else => unreachable,
                    };
                    const saw_miss = kiwi_host_find_i8_lookup_table_i32(out_items.ptr, table.ptr, right_ints.ptr, right_ints.len, miss_i32) != 0;
                    return try self.finishFindFullDomainOutputValue(&out, saw_miss, miss_index, out_len);
                },
                else => return null,
            },
            .int16 => |left_ints| switch (right_items) {
                .int8 => |right_ints| {
                    const table = try self.allocator.alloc(i32, 65536);
                    defer self.allocator.free(table);
                    if (comptime !enable_host_find_full_domain_c_helpers) {
                        fillInt16FindFullDomainTable(table, left_ints, miss_i32);
                        return try self.finishInt16FindFullDomainInt8QueriesDenseValue(table, right_ints, miss_index);
                    }
                    if (out_kind != .int32) {
                        fillInt16FindFullDomainTable(table, left_ints, miss_i32);
                        return try self.finishInt16FindFullDomainInt8QueriesDenseValue(table, right_ints, miss_index);
                    }
                    kiwi_host_find_i16_build_table_i32(table.ptr, left_ints.ptr, left_ints.len, miss_i32);
                    if (table[int16FindFullDomainSlot(right_ints[0])] == miss_i32) {
                        var out = try self.allocManagedHostIntResult(.int64, out_len);
                        const out_items = switch (out) {
                            .int64 => |items| items.items,
                            else => unreachable,
                        };
                        kiwi_host_find_i16_lookup_table_i8_queries_i64_null(out_items.ptr, table.ptr, right_ints.ptr, right_ints.len, miss_i32, kiwi_int_null);
                        return try self.finishFindFullDomainOutputValue(&out, false, miss_index, out_len);
                    }
                    var out = try self.allocManagedHostIntResult(.int32, out_len);
                    const out_items = switch (out) {
                        .int32 => |items| items.items,
                        else => unreachable,
                    };
                    const saw_miss = kiwi_host_find_i16_lookup_table_i8_queries_i32(out_items.ptr, table.ptr, right_ints.ptr, right_ints.len, miss_i32) != 0;
                    return try self.finishFindFullDomainOutputValue(&out, saw_miss, miss_index, out_len);
                },
                .int16 => |right_ints| {
                    const table = try self.allocator.alloc(i32, 65536);
                    defer self.allocator.free(table);
                    if (comptime !enable_host_find_full_domain_c_helpers) {
                        fillInt16FindFullDomainTable(table, left_ints, miss_i32);
                        return try self.finishInt16FindFullDomainDenseValue(table, right_ints, miss_index);
                    }
                    if (out_kind != .int32) {
                        fillInt16FindFullDomainTable(table, left_ints, miss_i32);
                        return try self.finishInt16FindFullDomainDenseValue(table, right_ints, miss_index);
                    }
                    kiwi_host_find_i16_build_table_i32(table.ptr, left_ints.ptr, left_ints.len, miss_i32);
                    if (table[int16FindFullDomainSlot(right_ints[0])] == miss_i32) {
                        var out = try self.allocManagedHostIntResult(.int64, out_len);
                        const out_items = switch (out) {
                            .int64 => |items| items.items,
                            else => unreachable,
                        };
                        kiwi_host_find_i16_lookup_table_i64_null(out_items.ptr, table.ptr, right_ints.ptr, right_ints.len, miss_i32, kiwi_int_null);
                        return try self.finishFindFullDomainOutputValue(&out, false, miss_index, out_len);
                    }
                    var out = try self.allocManagedHostIntResult(.int32, out_len);
                    const out_items = switch (out) {
                        .int32 => |items| items.items,
                        else => unreachable,
                    };
                    const saw_miss = kiwi_host_find_i16_lookup_table_i32(out_items.ptr, table.ptr, right_ints.ptr, right_ints.len, miss_i32) != 0;
                    return try self.finishFindFullDomainOutputValue(&out, saw_miss, miss_index, out_len);
                },
                else => return null,
            },
            else => return null,
        }
    }

    fn tryFastHostNumericVectorFindSmallRangeDenseValue(self: *Session, left: Value, right: Value, miss_index: usize) KError!?Value {
        const left_view = hostDenseView(self, left) catch return null;
        const right_view = hostDenseView(self, right) catch return null;
        const left_items = switch (left_view) {
            .int_array => |items| switch (items) {
                .dense => |dense_items| dense_items,
                else => return null,
            },
            else => return null,
        };
        const right_items = switch (right_view) {
            .int_array => |items| switch (items) {
                .dense => |dense_items| dense_items,
                else => return null,
            },
            else => return null,
        };
        switch (left_items) {
            .int8, .int16 => {},
            else => return null,
        }
        const out_len = hostIntArrayViewLen(right_items);
        if (out_len <= 1) return null;
        const left_len = hostIntArrayViewLen(left_items);
        if (left_len == 0) return null;

        const dense_left_view: HostIntDenseView = .{ .dense = left_items };
        if (monotonicFlags(hostIntDenseValueFlags(left, dense_left_view)) != 0) return null;
        const range = hostIntDenseValueRange(left, dense_left_view);
        const span = findIntSmallRangeSpan(left_len, out_len, range) orelse return null;

        const table = try self.allocator.alloc(i64, span);
        defer self.allocator.free(table);
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        @memset(table, miss_i64);

        try fillIntFindSmallRangeTableFromDense(table, left_items, range.min, miss_i64);
        if (!intFindSmallRangeDenseQueriesAllHit(table, right_items, range, miss_i64)) return null;

        var out = try self.allocManagedHostIntResult(try findMultiIndexOutputKind(miss_index), out_len);
        const stats = switch (out) {
            .int8 => |*items| fillIntFindSmallRangeDenseQueriesOutput(i8, items.items, table, right_items, range, miss_i64),
            .int16 => |*items| fillIntFindSmallRangeDenseQueriesOutput(i16, items.items, table, right_items, range, miss_i64),
            .int32 => |*items| fillIntFindSmallRangeDenseQueriesOutput(i32, items.items, table, right_items, range, miss_i64),
            .int64 => |*items| fillIntFindSmallRangeDenseQueriesOutput(i64, items.items, table, right_items, range, miss_i64),
            .bit => unreachable,
        };
        return try self.finishFindMultiOutputValue(&out, stats, miss_index, out_len);
    }

    fn tryFillIntFindSmallRangeDenseIntQueries(
        self: *Session,
        left: Value,
        left_items: HostIntDenseView,
        right_items: HostIntDenseView,
        out: []i64,
        miss_index: usize,
    ) KError!bool {
        const left_dense = switch (left_items) {
            .dense => |items| items,
            else => return false,
        };
        const right_dense = switch (right_items) {
            .dense => |items| items,
            else => return false,
        };
        const left_len = hostIntArrayViewLen(left_dense);
        if (left_len == 0) return false;
        const range = hostIntDenseValueRange(left, left_items);
        const span = findIntSmallRangeSpan(left_len, out.len, range) orelse return false;

        const table = try self.allocator.alloc(i64, span);
        defer self.allocator.free(table);
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        @memset(table, miss_i64);

        try fillIntFindSmallRangeTableFromDense(table, left_dense, range.min, miss_i64);
        fillIntFindSmallRangeDenseQueries(out, table, right_dense, range, miss_i64);
        return true;
    }

    fn tryFillIntFindSmallRangeIntQueries(
        self: *Session,
        left: Value,
        left_items: HostIntDenseView,
        right_items: HostIntDenseView,
        out: []i64,
        miss_index: usize,
    ) KError!bool {
        const left_len = hostIntDenseViewLen(left_items);
        if (left_len == 0) return false;
        const range = hostIntDenseValueRange(left, left_items);
        const span = findIntSmallRangeSpan(left_len, out.len, range) orelse return false;

        const table = try self.allocator.alloc(i64, span);
        defer self.allocator.free(table);
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        @memset(table, miss_i64);

        for (0..left_len) |idx| {
            const value = try hostIntDenseViewItem(left_items, idx);
            const slot = @as(usize, @intCast(value - range.min));
            if (table[slot] == miss_i64) table[slot] = std.math.cast(i64, idx) orelse return error.Unsupported;
        }
        for (0..out.len) |query_idx| {
            const query = try hostIntDenseViewItem(right_items, query_idx);
            out[query_idx] = if (query < range.min or query > range.max)
                miss_i64
            else
                table[@as(usize, @intCast(query - range.min))];
        }
        return true;
    }

    fn tryFillIntFindSmallRangeFloatQueries(
        self: *Session,
        left: Value,
        left_items: HostIntDenseView,
        right_items: HostFloatDenseView,
        out: []i64,
        miss_index: usize,
    ) KError!bool {
        const left_len = hostIntDenseViewLen(left_items);
        if (left_len == 0) return false;
        const range = hostIntDenseValueRange(left, left_items);
        const span = findIntSmallRangeSpan(left_len, out.len, range) orelse return false;

        const table = try self.allocator.alloc(i64, span);
        defer self.allocator.free(table);
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        @memset(table, miss_i64);

        for (0..left_len) |idx| {
            const value = try hostIntDenseViewItem(left_items, idx);
            const slot = @as(usize, @intCast(value - range.min));
            if (table[slot] == miss_i64) table[slot] = std.math.cast(i64, idx) orelse return error.Unsupported;
        }
        for (0..out.len) |query_idx| {
            const query = exactIntFromFloat(try hostFloatDenseViewItem(right_items, query_idx));
            out[query_idx] = if (query == null or query.? < range.min or query.? > range.max)
                miss_i64
            else
                table[@as(usize, @intCast(query.? - range.min))];
        }
        return true;
    }

    fn fillIntFindHashedIntQueries(
        self: *Session,
        out: []i64,
        left_array: ?*HostDenseArray,
        left_items: HostIntDenseView,
        right_items: HostIntDenseView,
        miss_index: usize,
    ) KError!void {
        if (left_items == .dense and right_items == .dense) {
            return fillIntFindDenseHashedIntQueries(self, out, left_array, left_items.dense, right_items.dense, miss_index);
        }
        var lookup = std.AutoHashMap(i64, usize).init(self.allocator);
        defer lookup.deinit();
        try lookup.ensureTotalCapacity(std.math.cast(u32, hostIntDenseViewLen(left_items)) orelse return error.Unsupported);
        for (0..hostIntDenseViewLen(left_items)) |idx| {
            const key = try hostIntDenseViewItem(left_items, idx);
            if (lookup.get(key) == null) try lookup.put(key, idx);
        }

        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        for (0..out.len) |query_idx| {
            const query = try hostIntDenseViewItem(right_items, query_idx);
            out[query_idx] = if (lookup.get(query)) |found_idx|
                std.math.cast(i64, found_idx) orelse return error.Unsupported
            else
                miss_i64;
        }
    }

    fn fillIntFindHashedFloatQueries(
        self: *Session,
        out: []i64,
        left_array: ?*HostDenseArray,
        left_items: HostIntDenseView,
        right_items: HostFloatDenseView,
        miss_index: usize,
    ) KError!void {
        if (left_items == .dense and right_items == .dense) {
            return fillIntFindDenseHashedFloatQueries(self, out, left_array, left_items.dense, right_items.dense, miss_index);
        }
        var lookup = std.AutoHashMap(i64, usize).init(self.allocator);
        defer lookup.deinit();
        try lookup.ensureTotalCapacity(std.math.cast(u32, hostIntDenseViewLen(left_items)) orelse return error.Unsupported);
        for (0..hostIntDenseViewLen(left_items)) |idx| {
            const key = try hostIntDenseViewItem(left_items, idx);
            if (lookup.get(key) == null) try lookup.put(key, idx);
        }

        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        for (0..out.len) |query_idx| {
            const query = exactIntFromFloat(try hostFloatDenseViewItem(right_items, query_idx));
            out[query_idx] = if (query) |query_int|
                if (lookup.get(query_int)) |found_idx|
                    std.math.cast(i64, found_idx) orelse return error.Unsupported
                else
                    miss_i64
            else
                miss_i64;
        }
    }

    const FindSelfOutputStats = struct {
        initialized: bool = false,
        min_value: i64 = 0,
        max_value: i64 = 0,
        prev_value: i64 = 0,
        asc: bool = true,
        dsc: bool = true,

        fn observe(self: *FindSelfOutputStats, value: usize) void {
            const item: i64 = @intCast(value);
            if (!self.initialized) {
                self.initialized = true;
                self.min_value = item;
                self.max_value = item;
                self.prev_value = item;
                return;
            }
            self.min_value = @min(self.min_value, item);
            self.max_value = @max(self.max_value, item);
            if (self.prev_value > item) self.asc = false;
            if (self.prev_value < item) self.dsc = false;
            self.prev_value = item;
        }

        fn range(self: FindSelfOutputStats) HostIntRange {
            return if (self.initialized)
                .{ .min = self.min_value, .max = self.max_value }
            else
                .{ .min = 0, .max = 0 };
        }

        fn flags(self: FindSelfOutputStats) u8 {
            return host_dense_flag_normalized | orderFlagsFromMonotonic(self.asc, self.dsc);
        }
    };

    fn numericFindValuesShareIdentity(left: Value, right: Value) bool {
        if (left.raw == right.raw) return true;
        const left_handle = valueNumericHandle(left) orelse return false;
        const right_handle = valueNumericHandle(right) orelse return false;
        return left_handle == right_handle;
    }

    fn findSelfIndexOutputKind(len: usize) KError!HostIntStorageKind {
        if (len == 0) return .int8;
        const max_index = std.math.cast(i64, len - 1) orelse return error.Unsupported;
        return hostIntStorageKindForRange(0, max_index);
    }

    fn storeFindSelfOutput(comptime OutT: type, out: []OutT, idx: usize, value: usize, stats: *FindSelfOutputStats) void {
        out[idx] = @intCast(value);
        stats.observe(value);
    }

    fn finishFindSelfOutput(self: *Session, out: *HostIntResult, stats: FindSelfOutputStats) KError!Value {
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, stats.flags());
        hostDenseSetCachedIntRange(host, stats.range());
        return value;
    }

    fn fillFindSelfSortedIntOutput(comptime OutT: type, out: []OutT, view: HostIntDenseView) KError!FindSelfOutputStats {
        var stats = FindSelfOutputStats{};
        if (out.len == 0) return stats;

        var run_start: usize = 0;
        var prev = try hostIntDenseViewItem(view, 0);
        storeFindSelfOutput(OutT, out, 0, 0, &stats);
        for (1..out.len) |idx| {
            const item = try hostIntDenseViewItem(view, idx);
            if (item != prev) {
                run_start = idx;
                prev = item;
            }
            storeFindSelfOutput(OutT, out, idx, run_start, &stats);
        }
        return stats;
    }

    fn selfFindSortedIntValue(self: *Session, view: HostIntDenseView, len: usize) KError!Value {
        if (len == 0) return try newRangeIotaValue(self, .managed, 0);
        _ = std.math.cast(i64, len - 1) orelse return error.Unsupported;
        var out = try self.allocManagedHostIntResult(try findSelfIndexOutputKind(len), len);
        const stats = switch (out) {
            .int8 => |*items| try fillFindSelfSortedIntOutput(i8, items.items, view),
            .int16 => |*items| try fillFindSelfSortedIntOutput(i16, items.items, view),
            .int32 => |*items| try fillFindSelfSortedIntOutput(i32, items.items, view),
            .int64 => |*items| try fillFindSelfSortedIntOutput(i64, items.items, view),
            .bit => unreachable,
        };
        return try self.finishFindSelfOutput(&out, stats);
    }

    fn fillFindSelfBitOutput(comptime OutT: type, out: []OutT, items: HostBitSlice) FindSelfOutputStats {
        var stats = FindSelfOutputStats{};
        var first_false: ?usize = null;
        var first_true: ?usize = null;
        for (0..items.len) |idx| {
            const bit = bitGet(items.words, idx);
            const found = if (bit) blk: {
                if (first_true == null) first_true = idx;
                break :blk first_true.?;
            } else blk: {
                if (first_false == null) first_false = idx;
                break :blk first_false.?;
            };
            storeFindSelfOutput(OutT, out, idx, found, &stats);
        }
        return stats;
    }

    fn selfFindBitValue(self: *Session, items: HostBitSlice) KError!Value {
