        const stats = switch (out) {
            .int8 => |*dest| fillFindSelfBitOutput(i8, dest.items, items),
            .int16 => |*dest| fillFindSelfBitOutput(i16, dest.items, items),
            .int32 => |*dest| fillFindSelfBitOutput(i32, dest.items, items),
            .int64 => |*dest| fillFindSelfBitOutput(i64, dest.items, items),
