        };
        return try self.finishFindSelfOutput(&out, stats);
    }

    fn fillFindSelfInt8Output(comptime OutT: type, out: []OutT, items: []const i8) FindSelfOutputStats {
        var first: [256]usize = undefined;
        @memset(first[0..], items.len);

        var stats = FindSelfOutputStats{};
        for (items, 0..) |item, idx| {
            const slot: usize = @as(u8, @bitCast(item));
            if (first[slot] == items.len) first[slot] = idx;
            storeFindSelfOutput(OutT, out, idx, first[slot], &stats);
        }
        return stats;
    }

