    fn tryFastHostNumericVectorSelfFindValue(self: *Session, left: Value, left_len: usize) KError!?Value {
        const left_view = hostDenseView(self, left) catch return null;
        return switch (left_view) {
            .int_array => |items| blk: {
                if (left_len == 0) break :blk try newRangeIotaValue(self, .managed, 0);

                if (items == .range_iota) {
                    const range = numericArrayRangeIota(items.range_iota.handle);
                    break :blk if (range.step == 0)
                        try newRangeIotaValueWithParams(self, .managed, left_len, 0, 0)
                    else
                        try newRangeIotaValue(self, .managed, left_len);
                }

                const mono = monotonicFlags(hostIntDenseValueFlags(left, items));
                if (mono != 0) break :blk try self.selfFindSortedIntValue(items, left_len);

                break :blk switch (items) {
                    .dense => |dense_items| switch (dense_items) {
                        .bit => |bits| try self.selfFindBitValue(bits),
                        .int8 => |int_items| try self.selfFindInt8Value(int_items),
                        .int16 => |int_items| try self.selfFindInt16Value(int_items),
                        .int32 => |int_items| try self.selfFindInt32Value(int_items),
                        .int64 => |int_items| try self.selfFindInt64Value(int_items),
                    },
                    else => null,
                };
            },
            else => null,
        };
    }

    fn tryFastHostNumericVectorFindMultiValue(self: *Session, left: Value, right: Value, miss_index: usize) KError!?Value {
        const left_view = hostDenseView(self, left) catch return null;
        const right_view = hostDenseView(self, right) catch return null;
        const left_array = managedHostDenseArrayForFindCache(left);
        const out_len = numericRowQueryLen(right) orelse return null;
        if (out_len <= 1) return null;

        var out = try self.allocManagedHostIntResult(.int64, out_len);
        const out_items = switch (out) {
            .int64 => |result| result.items,
            else => unreachable,
        };

        switch (left_view) {
            .float_array => |left_items| switch (right_view) {
                .float_array => |right_items| {
                    if (try tryFillFloatFindSortedFloatQueries(left, left_items, right_items, out_items, miss_index)) {
                        return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                    }
                    if (preferBruteForceNumericFind(hostFloatDenseViewLen(left_items), out_len)) {
                        try fillFloatFindBruteForceFloatQueries(out_items, left_items, right_items, miss_index);
                    } else {
                        try fillFloatFindHashedFloatQueries(self, out_items, left_array, left_items, right_items, miss_index);
                    }
                    return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                },
                .int_array => |right_items| {
                    if (try tryFillFloatFindSortedIntQueries(left, left_items, right_items, out_items, miss_index)) {
                        return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                    }
                    if (preferBruteForceNumericFind(hostFloatDenseViewLen(left_items), out_len)) {
                        try fillFloatFindBruteForceIntQueries(out_items, left_items, right_items, miss_index);
                    } else {
                        try fillFloatFindHashedIntQueries(self, out_items, left_array, left_items, right_items, miss_index);
                    }
                    return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                },
                else => return null,
            },
            .int_array => |left_items| switch (right_view) {
                .int_array => |right_items| {
                    if (try tryFillIntFindRangeIotaIntQueries(left_items, right_items, out_items, miss_index)) {
                        return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                    }
                    if (try tryFillIntFindSortedIntQueries(left, left_items, right_items, out_items, miss_index)) {
                        return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                    }
                    if (try self.tryFillIntFindSmallRangeDenseIntQueries(left, left_items, right_items, out_items, miss_index)) {
                        return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                    }
                    if (try tryFillIntFindSmallRangeIntQueries(self, left, left_items, right_items, out_items, miss_index)) {
                        return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                    }
                    if (preferBruteForceNumericFind(hostIntDenseViewLen(left_items), out_len)) {
                        try fillIntFindBruteForceIntQueries(out_items, left_items, right_items, miss_index);
                    } else {
                        try fillIntFindHashedIntQueries(self, out_items, left_array, left_items, right_items, miss_index);
                    }
                    return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                },
                .float_array => |right_items| {
                    if (try tryFillIntFindSortedFloatQueries(left, left_items, right_items, out_items, miss_index)) {
                        return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                    }
                    if (try tryFillIntFindSmallRangeFloatQueries(self, left, left_items, right_items, out_items, miss_index)) {
                        return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                    }
                    if (preferBruteForceNumericFind(hostIntDenseViewLen(left_items), out_len)) {
                        try fillIntFindBruteForceFloatQueries(out_items, left_items, right_items, miss_index);
                    } else {
                        try fillIntFindHashedFloatQueries(self, out_items, left_array, left_items, right_items, miss_index);
                    }
                    return try self.finishManagedHostInt64MultiFindResult(&out, out_items);
                },
                else => return null,
            },
            else => return null,
        }
    }

    fn finishManagedHostInt64MultiFindResult(self: *Session, out: *HostIntResult, out_items: []const i64) !Value {
        _ = self;
        const analysis = analyzeIntSlice(out_items);
        hostDenseSetFlags(out.arrayPtr(), analysis.flags);
        hostDenseSetCachedIntRange(out.arrayPtr(), analysis.range);
        return out.value();
    }

    fn numericMajorCellMatchesAt(left: Value, left_base: usize, right: Value, right_base: usize, cell_len: usize) KError!bool {
        for (0..cell_len) |offset| {
            if (!try numericValuesEqualAt(left, left_base + offset, right, right_base + offset)) return false;
        }
        return true;
    }

    fn findNumericMajorCellIndex(
        left: Value,
        right: Value,
        left_count: usize,
        cell_len: usize,
        query_base: usize,
    ) KError!?usize {
        for (0..left_count) |left_idx| {
            const left_base = left_idx * cell_len;
            if (try numericMajorCellMatchesAt(left, left_base, right, query_base, cell_len)) return left_idx;
        }
        return null;
    }

    fn shapedNumericFindValues(self: *Session, left: Value, right: Value) KError!?Value {
        const left_shape = numericFindShape(left) orelse return null;
        if (left_shape.rank <= 1) return null;
        const right_shape = numericFindShape(right) orelse return null;

        const cell_rank = left_shape.rank - 1;
        if (right_shape.rank < cell_rank) return error.Type;

        var cell_shape = NumericShapeSnapshot{};
        cell_shape.rank = cell_rank;
        for (0..cell_rank) |idx| cell_shape.shape[idx] = left_shape.shape[idx + 1];

        const output_rank = right_shape.rank - cell_rank;
        const output_shape = numericFindOutputShape(right_shape, output_rank);
        const query_count: usize = if (output_rank == 0) 1 else try fixedShapeProduct(output_shape.shapeSlice());
        const left_count = @as(usize, @intCast(left_shape.shape[0]));
        const cell_len = try fixedShapeProduct(cell_shape.shapeSlice());
        const shapes_match = numericFindTrailingShapeMatches(right_shape, output_rank, cell_shape);

        if (valueNumericHandle(left)) |handle| _ = try tryEnsureHostRealizationForHandle(self, @constCast(handle));
        if (valueNumericHandle(right)) |handle| _ = try tryEnsureHostRealizationForHandle(self, @constCast(handle));

        if (output_rank == 0) {
            if (shapes_match) {
                if (try findNumericMajorCellIndex(left, right, left_count, cell_len, 0)) |found| {
                    return try self.intValue(@intCast(found));
                }
            }
            return try self.intNullValue();
        }

        const out = try self.allocator.alloc(i64, query_count);
        defer self.allocator.free(out);

        if (!shapes_match) {
            @memset(out, kiwi_int_null);
        } else {
            for (0..query_count) |query_idx| {
                const query_base = query_idx * cell_len;
                out[query_idx] = if (try findNumericMajorCellIndex(left, right, left_count, cell_len, query_base)) |found|
                    @intCast(found)
                else
                    kiwi_int_null;
            }
        }

        const result = try self.createManagedHostIntArray(out);
        if (output_shape.rank > 1) return try applyNonVectorNumericShapeToValue(self, result, output_shape);
        return result;
    }

    fn tryFastBackendNumericVectorFindValue(self: *Session, left: Value, right: Value) KError!?Value {
        return runtime_backend_exec.tryFastBackendNumericVectorFindValue(backend_exec_api, self, left, right);
    }

    fn tryFastBackendArgmaxValue(self: *Session, value: Value) KError!?Value {
        return runtime_backend_exec.tryFastBackendArgmaxValue(backend_exec_api, self, value);
    }

    fn argmaxValue(self: *Session, value: Value) KError!Value {
        if (valueNumericMode(value) == null or valueNumericMatrixShape(value) != null) return error.Type;
        const len = numericFlatLen(value) orelse return error.Type;
        if (len == 0) return error.Type;
        if (len == 1) return try self.intValue(0);
        if (try self.tryFastBackendArgmaxValue(value)) |result| return result;

        if (valueNumericHandle(value)) |handle| _ = try tryEnsureHostRealizationForHandle(self, @constCast(handle));
        switch (valueNumericMode(value).?) {
            .int => {
                var best_idx: usize = 0;
                var best_value = try numericIntAt(value, 0);
                for (1..len) |idx| {
                    const current = try numericIntAt(value, idx);
                    if (current > best_value) {
                        best_value = current;
                        best_idx = idx;
                    }
                }
                return try self.intValue(@intCast(best_idx));
            },
            .float => {
                var best_idx: usize = 0;
                var best_value = try numericFloatAt(value, 0);
                for (1..len) |idx| {
                    const current = try numericFloatAt(value, idx);
                    if (current > best_value) {
                        best_value = current;
                        best_idx = idx;
                    }
                }
                return try self.intValue(@intCast(best_idx));
            },
        }
    }

    const dense_backend_find_multi_host_len_cpu: usize = 131_072;
    const dense_backend_find_multi_host_len_gpu: usize = 65_536;
    const dense_backend_find_multi_host_query_len: usize = 256;

    fn valueHasHostDenseRealization(value: Value) bool {
        const handle = valueNumericHandle(value) orelse return false;
        return numericHasHostAttachment(handle);
    }

    fn backendResidentNumericVectorFindPrefersHost(
        self: *Session,
        left: Value,
        right: Value,
        left_len: usize,
        query_len: usize,
    ) bool {
        if (query_len <= 1 or query_len > dense_backend_find_multi_host_query_len) return false;

        const left_facts = denseValuePlanFacts(left);
        const right_facts = denseValuePlanFacts(right);
        if (!(left_facts.has_backend_residency or right_facts.has_backend_residency)) return false;

        const left_host_limit = if (self.device_preference == .gpu)
            dense_backend_find_multi_host_len_gpu
        else
            dense_backend_find_multi_host_len_cpu;

        if (valueHasHostDenseRealization(left)) return true;
        return left_len <= left_host_limit;
    }

    fn normalizeFindMissResult(self: *Session, result: Value, miss_index: usize, query_len: usize) KError!Value {
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        if (valueNumericHandle(result)) |handle| {
            if (numericHasBackendAttachment(handle) and !numericHasHostAttachment(handle)) {
                _ = try tryEnsureHostRealizationForHandle(self, @constCast(handle));
            }
        }
        if (query_len == 1) {
            const item = scalarIntLikeValue(result) orelse blk: {
                if (valueNumericMode(result) != .int) return error.Type;
                break :blk try numericIntAt(result, 0);
            };
            return if (item == miss_i64) try self.intNullValue() else try self.intValue(item);
        }

        var saw_miss = false;
        for (0..query_len) |idx| {
            if ((try numericIntAt(result, idx)) == miss_i64) {
                saw_miss = true;
                break;
            }
        }
        if (!saw_miss) return self.shareValue(result);

        return try self.normalizeKnownFindMissResult(result, miss_index, query_len);
    }

    fn normalizeKnownFindMissResult(self: *Session, result: Value, miss_index: usize, query_len: usize) KError!Value {
        const miss_i64 = std.math.cast(i64, miss_index) orelse return error.Unsupported;
        if (valueNumericHandle(result)) |handle| {
            if (numericHasBackendAttachment(handle) and !numericHasHostAttachment(handle)) {
                _ = try tryEnsureHostRealizationForHandle(self, @constCast(handle));
            }
        }
        if (query_len == 1) {
            const item = scalarIntLikeValue(result) orelse blk: {
                if (valueNumericMode(result) != .int) return error.Type;
                break :blk try numericIntAt(result, 0);
            };
            return if (item == miss_i64) try self.intNullValue() else try self.intValue(item);
        }

        const items = try self.allocator.alloc(i64, query_len);
        defer self.allocator.free(items);
        for (0..query_len) |idx| {
            const item = try numericIntAt(result, idx);
            items[idx] = if (item == miss_i64) kiwi_int_null else item;
        }
        return try self.createManagedHostIntArray(items);
    }

    fn findNumericVectorValue(self: *Session, left: Value, right: Value) KError!?Value {
        if (valueNumericMode(left) == null or (numericFindShape(left) orelse return null).rank > 1) return null;
        const left_len = numericFlatLen(left) orelse return null;
        const query_len = numericRowQueryLen(right) orelse return null;
        if (!backendResidentNumericVectorFindPrefersHost(self, left, right, left_len, query_len)) {
            if (try self.tryFastBackendNumericVectorFindValue(left, right)) |result| {
                return result;
            }
        }
        if (query_len == 1 and
            numericValueSupportsStructuralFlatItemsWithoutHost(left) and
            numericValueSupportsStructuralFlatItemsWithoutHost(right))
        {
            if (try self.tryFastHostNumericVectorFindScalarIndex(left, right, left_len)) |idx| {
                return if (idx == left_len) try self.intNullValue() else try self.intValue(@intCast(idx));
            }
        }
        if (query_len != 1 and left_len == query_len and numericFindValuesShareIdentity(left, right)) {
            if (try self.tryFastHostNumericVectorSelfFindValue(left, left_len)) |result| return result;
        }
        if (query_len != 1) {
            if (try self.tryFastHostNumericVectorFindFullDomainDenseValue(left, right, left_len)) |result| return result;
            if (try self.tryFastHostNumericVectorFindSmallRangeDenseValue(left, right, left_len)) |result| return result;
            if (try self.tryFastHostNumericVectorFindMultiValue(left, right, left_len)) |result| {
                defer self.releaseValue(result);
                return try self.normalizeFindMissResult(result, left_len, query_len);
            }
        }
        if (valueNumericHandle(left)) |handle| _ = try tryEnsureHostRealizationForHandle(self, @constCast(handle));
        if (valueNumericHandle(right)) |handle| _ = try tryEnsureHostRealizationForHandle(self, @constCast(handle));
        if (query_len == 1) {
            if (try self.tryFastHostNumericVectorFindScalarIndex(left, right, left_len)) |idx| {
                return if (idx == left_len) try self.intNullValue() else try self.intValue(@intCast(idx));
            }
        }
        if (query_len != 1) {
            if (try self.tryFastHostNumericVectorFindFullDomainDenseValue(left, right, left_len)) |result| return result;
            if (try self.tryFastHostNumericVectorFindSmallRangeDenseValue(left, right, left_len)) |result| return result;
            if (try self.tryFastHostNumericVectorFindMultiValue(left, right, left_len)) |result| {
                defer self.releaseValue(result);
                return try self.normalizeFindMissResult(result, left_len, query_len);
            }
            var out = std.ArrayList(i64).empty;
            defer out.deinit(self.allocator);
            try out.ensureTotalCapacity(self.allocator, query_len);
            for (0..query_len) |query_idx| {
                var found_idx: i64 = kiwi_int_null;
                for (0..left_len) |idx| {
                    if (try numericValuesEqualAt(left, idx, right, query_idx)) {
                        found_idx = @intCast(idx);
                        break;
                    }
                }
                try out.append(self.allocator, found_idx);
            }
            return try self.createManagedHostIntArray(out.items);
        }
        for (0..left_len) |idx| {
            if (try numericValuesEqualAt(left, idx, right, 0)) return try self.intValue(@intCast(idx));
        }
        return try self.intNullValue();
    }

    fn findStringValue(self: *Session, left: Value, right: Value) KError!?Value {
        const haystack = stringBytes(left) orelse return null;
        const queries = stringBytes(right) orelse return try self.findMissForQueryValue(right);
        if (queries.len == 0) return try self.createManagedHostIntArray(&.{});
        if (queries.len == 1) {
            return if (findHostStringByte(haystack, queries[0])) |idx|
                try self.intValue(@intCast(idx))
            else
                try self.intNullValue();
        }
        if (haystack.len >= host_string_find_table_min_len and queries.len >= host_string_find_table_min_queries) {
            return try self.findHostStringBytesTable(haystack, queries);
        }

        const out = try self.allocator.alloc(i64, queries.len);
        defer self.allocator.free(out);
        for (queries, 0..) |query, idx| {
            out[idx] = if (findHostStringByte(haystack, query)) |found|
                @intCast(found)
            else
                kiwi_int_null;
        }
        return try self.createManagedHostIntArray(out);
    }

    fn findHostStringBytesTable(self: *Session, haystack: []const u8, queries: []const u8) KError!Value {
        if (comptime enable_host_string_find_table_neon) {
            const out = try self.allocator.alloc(i64, queries.len);
            defer self.allocator.free(out);
            kiwi_string_find_bytes_neon(out.ptr, haystack.ptr, haystack.len, queries.ptr, queries.len, kiwi_int_null);
            return try self.createManagedHostIntArray(out);
        }

        var wanted: [256]u8 = undefined;
        @memset(wanted[0..], 0);
        var first: [256]usize = undefined;
        @memset(first[0..], haystack.len);

        var remaining: usize = 0;
        for (queries) |query| {
            const key: usize = @intCast(query);
            if (wanted[key] == 0) {
                wanted[key] = 1;
                remaining += 1;
            }
        }

        if (remaining > 0) {
            for (haystack, 0..) |byte, idx| {
                const key: usize = @intCast(byte);
                if (wanted[key] != 0 and first[key] == haystack.len) {
                    first[key] = idx;
                    remaining -= 1;
                    if (remaining == 0) break;
                }
            }
        }

        const out = try self.allocator.alloc(i64, queries.len);
        defer self.allocator.free(out);
        for (queries, 0..) |query, idx| {
            const found = first[@intCast(query)];
            out[idx] = if (found < haystack.len) @intCast(found) else kiwi_int_null;
        }
        return try self.createManagedHostIntArray(out);
    }

    fn findHostStringByte(haystack: []const u8, query: u8) ?usize {
        if (comptime enable_host_find_vectorized) {
            if (haystack.len >= host_find_vector_min_len) {
                const items: [*]const i8 = @ptrCast(haystack.ptr);
                const found = kiwi_host_find_i8(items, haystack.len, @as(i8, @bitCast(query)));
                return if (found < haystack.len) found else null;
            }
        }
        return std.mem.indexOfScalar(u8, haystack, query);
    }

    fn containsHostStringSlice(haystack: []const u8, needle: []const u8) bool {
        if (needle.len == 0) return true;
        if (needle.len > haystack.len) return false;
        if (needle.len == 1) return findHostStringByte(haystack, needle[0]) != null;
        return std.mem.indexOf(u8, haystack, needle) != null;
    }

    fn findQuerySequenceLen(value: Value) ?usize {
        if (stringSourceInfo(value) != null) return null;
        return derivedSequenceLen(value);
    }

    fn findMissForQueryValue(self: *Session, query: Value) KError!Value {
        const query_len = findQuerySequenceLen(query) orelse return try self.intNullValue();
        const items = try self.allocator.alloc(i64, query_len);
        defer self.allocator.free(items);
        @memset(items, kiwi_int_null);
        return try self.createManagedHostIntArray(items);
    }

    fn singleStringBytesValue(self: *Session, value: Value) KError!?[]const u8 {
        if (stringBytes(value)) |bytes| return bytes;
        if (value.tag() == .array and value.arrayKind() == .host_string_list) {
            const list = value.asHostStringList();
            if (list.len == 1) return try hostStringListItemBytes(list, 0);
        }
        if (value.tag() == .array and value.arrayKind() == .host_boxed_array) {
            const boxed = value.asHostBoxedArray();
            if (boxed.len() == 1) return try self.singleStringBytesValue(boxed.items[0]);
        }
        return null;
    }

    fn valueStringListBoxedTextEqual(self: *Session, list_value: Value, boxed_value: Value) KError!bool {
        if (list_value.tag() != .array or list_value.arrayKind() != .host_string_list) return false;
        if (boxed_value.tag() != .array or boxed_value.arrayKind() != .host_boxed_array) return false;

        const list = list_value.asHostStringList();
        const boxed = boxed_value.asHostBoxedArray();
        if (list.len != boxed.len()) return false;
        for (0..list.len) |idx| {
            const left = try hostStringListItemBytes(list, idx);
            const right = (try self.singleStringBytesValue(boxed.items[idx])) orelse return false;
            if (!std.mem.eql(u8, left, right)) return false;
        }
        return true;
    }

    fn valueFindEqual(self: *Session, left: Value, right: Value) KError!bool {
        if (try self.valueMatchEqual(left, right)) return true;
        if (try self.valueStringListBoxedTextEqual(left, right)) return true;
        if (try self.valueStringListBoxedTextEqual(right, left)) return true;
        return false;
    }

    fn findSequenceIndex(self: *Session, left: Value, left_len: usize, query: Value) KError!?usize {
        for (0..left_len) |idx| {
            const item = try self.derivedSequenceItemValue(left, idx);
            defer self.releaseValue(item);
            if (try self.valueFindEqual(item, query)) return idx;
        }
        return null;
    }

    fn findSequenceValue(self: *Session, left: Value, right: Value) KError!?Value {
        const left_len = derivedSequenceLen(left) orelse return null;
        if (try self.findSequenceIndex(left, left_len, right)) |idx| return try self.intValue(@intCast(idx));

        const query_len = findQuerySequenceLen(right) orelse return try self.intNullValue();
        var out = std.ArrayList(i64).empty;
        defer out.deinit(self.allocator);
        try out.ensureTotalCapacity(self.allocator, query_len);
        for (0..query_len) |query_idx| {
            const query = try self.derivedSequenceItemValue(right, query_idx);
            defer self.releaseValue(query);
            const idx = try self.findSequenceIndex(left, left_len, query);
            try out.append(self.allocator, if (idx) |found| @intCast(found) else kiwi_int_null);
        }
        return try self.createManagedHostIntArray(out.items);
    }

    fn keyedStoreValueFindIndex(self: *Session, store: *const HostKeyedStore, query: Value) KError!?usize {
        const len = keyedStoreValuesValueCount(store.values) orelse return error.Internal;
        for (0..len) |idx| {
            const item = try self.keyedStoreValueAt(store, idx);
            defer self.releaseValue(item);
            if (try self.valueFindEqual(item, query)) return idx;
        }
        return null;
    }

    fn keyedStoreFindMissingKeyPrototype(self: *Session, store: *const HostKeyedStore) KError!Value {
        const len = keyedStoreNameCount(store);
        if (len == 0) return try self.emptySymbolValue();
        const first = try self.keyedStoreNameValue(store, 0);
        defer self.releaseValue(first);
        return try self.prototypeLikeValue(first);
    }

    fn findKeyedStoreValue(self: *Session, store: *const HostKeyedStore, query: Value) KError!Value {
        if (store.layout != .dict) return error.Type;
        if (try self.keyedStoreValueFindIndex(store, query)) |idx| return try self.keyedStoreNameValue(store, idx);
        return try self.keyedStoreFindMissingKeyPrototype(store);
    }

    fn findKeyedStoreValues(self: *Session, store: *const HostKeyedStore, query: Value) KError!?Value {
        if (store.layout != .dict) return null;
        const query_len = findQuerySequenceLen(query) orelse return try self.findKeyedStoreValue(store, query);

        const values = try self.allocator.alloc(Value, query_len);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |value| self.releaseValue(value);
        }

        for (0..query_len) |idx| {
            const item = try self.derivedSequenceItemValue(query, idx);
            defer self.releaseValue(item);
            values[idx] = try self.findKeyedStoreValue(store, item);
            initialized += 1;
        }
        return try self.makeArrayFromValues(values);
    }

    fn findValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.findStringValue(left, right)) |result| return result;
        if (try self.shapedNumericFindValues(left, right)) |result| return result;
        if (try self.findNumericVectorValue(left, right)) |result| return result;
        if (left.tag() == .array and left.arrayKind() == .host_keyed_store) {
            const store = left.asHostKeyedStore();
            if (try self.findKeyedStoreValues(store, right)) |result| return result;
            const key = keyedLookupNameBytes(right) orelse return try self.findMissForQueryValue(right);
            return if (store.lookup.get(key)) |idx| try self.intValue(@intCast(idx)) else try self.intNullValue();
        }
        if (try self.findSequenceValue(left, right)) |result| return result;
        return try self.findMissForQueryValue(right);
    }

    fn binNumericAt(value: Value, idx: usize) KError!f64 {
        return switch (valueNumericMode(value) orelse return error.Type) {
            .int => @floatFromInt(try numericIntAt(value, idx)),
            .float => try numericFloatAt(value, idx),
        };
    }

    fn binSearchScalarValue(self: *Session, left: Value, query: Value) KError!Value {
        const left_len = numericVectorLen(left) orelse return error.Type;
        if (left_len == 0) return try self.intValue(-1);
        const needle = try scalarNumericValue(query);
        if (needle < try binNumericAt(left, 0)) return try self.intValue(-1);

        var low: usize = 0;
        var high: usize = left_len;
        while (high - low > 1) {
            const mid = low + (high - low) / 2;
            if (try binNumericAt(left, mid) > needle) {
                high = mid;
            } else {
                low = mid;
            }
        }
        return try self.intValue(@intCast(low));
    }

    fn binValues(self: *Session, left: Value, right: Value) KError!Value {
        _ = valueNumericMode(left) orelse return error.Type;
        _ = numericVectorLen(left) orelse return error.Type;
        if (scalarNumericClass(right) != null) return try self.binSearchScalarValue(left, right);
        const query_len = derivedSequenceLen(right) orelse return error.Type;

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, query_len);

        for (0..query_len) |idx| {
            const query = try self.derivedSequenceItemValue(right, idx);
            defer self.releaseValue(query);
            try results.append(self.allocator, try self.binValues(left, query));
        }
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn countLenAsI64(len: usize) KError!i64 {
        return std.math.cast(i64, len) orelse return error.Unsupported;
    }

    fn countDimAsI64(dim: i32) KError!i64 {
        if (dim < 0) return error.Internal;
        return @intCast(dim);
    }

    fn countValueAsI64(self: *Session, value: Value) KError!i64 {
        if (stringBytes(value)) |text| return try countLenAsI64(text.len);
        return switch (value.tag()) {
            .array => blk: {
                if (valueNumericHandle(value)) |handle| {
                    if (handle.rank != 0) break :blk try countDimAsI64(handle.shape[0]);
                }
                break :blk switch (value.arrayKind()) {
                    .host_boxed_array => try countLenAsI64(value.asHostBoxedArray().len()),
                    .host_string_list, .host_symbol_list => try countLenAsI64(value.asHostStringList().len),
                    .host_handle => 1,
                    .host_relation => try countLenAsI64(try self.relationRowCount(@constCast(value.asHostRelation()))),
                    .host_keyed_store => blk2: {
                        const store = value.asHostKeyedStore();
                        break :blk2 try countLenAsI64(if (store.layout == .table) store.row_count else keyedStoreNameCount(store));
                    },
                    else => error.Internal,
                };
            },
            else => 1,
        };
    }

    fn countValue(self: *Session, value: Value) KError!Value {
        return try self.intValue(try self.countValueAsI64(value));
    }

    fn lowercaseAsciiCopy(self: *Session, bytes: []const u8) KError!?[]u8 {
        var changed = false;
        for (bytes) |byte| {
            if (byte >= 'A' and byte <= 'Z') {
                changed = true;
                break;
            }
        }
        if (!changed) return null;

        const out = try self.allocator.alloc(u8, bytes.len);
        for (bytes, 0..) |byte, idx| {
            out[idx] = if (byte >= 'A' and byte <= 'Z') byte + 32 else byte;
        }
        return out;
    }

    fn lowerStringValue(self: *Session, value: Value) KError!?Value {
        const source = stringSourceInfo(value) orelse return null;
        const bytes = source.bytes();
        const out = (try self.lowercaseAsciiCopy(bytes)) orelse return self.shareValue(value);
        defer self.allocator.free(out);
        return try self.managedHostString(out);
    }

    fn lowerSymbolValue(self: *Session, value: Value) KError!?Value {
        const bytes = symbolBytes(value) orelse return null;
        const out = (try self.lowercaseAsciiCopy(bytes)) orelse return self.shareValue(value);
        defer self.allocator.free(out);
        return try self.managedHostSymbol(out);
    }

    fn lowerHostTextListValue(self: *Session, value: Value) KError!?Value {
        if (value.tag() != .array) return null;
        const kind = value.arrayKind();
        if (kind != .host_string_list and kind != .host_symbol_list) return null;

        const list = value.asHostStringList();
        const slices = try self.allocator.alloc([]const u8, list.len);
        defer self.allocator.free(slices);
        const owned = try self.allocator.alloc(?[]u8, list.len);
        defer {
            for (owned) |maybe_bytes| {
                if (maybe_bytes) |bytes| self.allocator.free(bytes);
            }
            self.allocator.free(owned);
        }
        for (owned) |*slot| slot.* = null;

        var changed = false;
        for (0..list.len) |idx| {
            const bytes = try hostStringListItemBytes(list, idx);
            if (try self.lowercaseAsciiCopy(bytes)) |out| {
                slices[idx] = out;
                owned[idx] = out;
                changed = true;
            } else {
                slices[idx] = bytes;
            }
        }
        if (!changed) return self.shareValue(value);

        return switch (kind) {
            .host_string_list => try self.createOwnedHostTextListFromSlicesKind(.managed, .host_string_list, .host_string, list.display, slices),
            .host_symbol_list => try self.createManagedHostSymbolListFromSlices(slices),
            else => unreachable,
        };
    }

    fn floorBoxedArrayValue(self: *Session, array: *const HostBoxedArray) KError!Value {
        if (array.items.len == 0) return try self.createManagedHostBoxedArray(&.{});

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |item| self.releaseValue(item);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, array.items.len);
        for (array.items) |item| {
            try results.append(self.allocator, try self.floorValue(item));
        }
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn floorValue(self: *Session, value: Value) KError!Value {
        if (try self.lowerStringValue(value)) |text| return text;
        if (try self.lowerSymbolValue(value)) |symbol| return symbol;
        if (try self.lowerHostTextListValue(value)) |list| return list;
        return switch (value.tag()) {
            .int, .bool => self.shareValue(value),
            .float => blk: {
                const floored = @floor(value.asFloat());
                const int_value = std.math.lossyCast(i64, floored);
                break :blk try self.intValue(int_value);
            },
            .array => switch (value.arrayKind()) {
                .host_boxed_array => try self.floorBoxedArrayValue(value.asHostBoxedArray()),
                .numeric_array => if (valueHostIntStructuralView(value) != null)
                    self.shareValue(value)
                else switch ((try numericHostArrayValue(self, value)).storage) {
                    .float64 => |items| blk: {
                        var out = std.ArrayList(i64).empty;
                        defer out.deinit(self.allocator);
                        try out.ensureTotalCapacity(self.allocator, items.len);
                        for (items) |item| try out.append(self.allocator, std.math.lossyCast(i64, @floor(item)));
                        break :blk try self.createManagedHostIntArray(out.items);
                    },
                    else => self.shareValue(value),
                },
                else => error.Internal,
            },
            else => error.Type,
        };
    }

    fn iotaBitVectorValue(self: *Session, array: *const HostDenseArray) KError!Value {
        const bits: HostBitSlice = .{ .words = array.storage.bit, .len = array.len() };
        const rank = bits.len;

        var cols: usize = 1;
        for (0..rank) |idx| {
            cols *= @as(usize, @intFromBool(bitGet(bits.words, idx)));
        }

        if (cols == 0) {
            const empty = try self.createManagedHostIntArray(&.{});
            return try self.setNumericMatrixShapeOnValue(empty, rank, 0);
        }

        var out = std.ArrayList(i64).empty;
        defer out.deinit(self.allocator);
        try out.ensureTotalCapacity(self.allocator, rank * cols);
        for (0..rank) |_| try out.append(self.allocator, 0);

        const value = try self.createManagedHostIntArray(out.items);
        return try self.setNumericMatrixShapeOnValue(value, rank, cols);
    }

    fn iotaIntVectorValue(self: *Session, array: *const HostDenseArray) KError!Value {
        const view = hostIntArrayView(array) orelse return error.Type;
        const rank = hostIntArrayViewLen(view);

        var cols: usize = 1;
        for (0..rank) |idx| {
            const count_i64 = hostIntViewItem(view, idx);
            if (count_i64 < 0) return error.Type;
            const count: usize = @intCast(count_i64);
            cols = std.math.mul(usize, cols, count) catch return error.Unsupported;
        }

        if (cols == 0) {
            const empty = try self.createManagedHostIntArray(&.{});
            return try self.setNumericMatrixShapeOnValue(empty, rank, 0);
        }

        var out = std.ArrayList(i64).empty;
        defer out.deinit(self.allocator);
        try out.ensureTotalCapacity(self.allocator, std.math.mul(usize, rank, cols) catch return error.Unsupported);

        var stride = cols;
        for (0..rank) |axis| {
            const count: usize = @intCast(hostIntViewItem(view, axis));
            stride = @divExact(stride, count);
            for (0..cols) |idx| {
                const digit = @as(i64, @intCast((idx / stride) % count));
                try out.append(self.allocator, digit);
            }
        }

        const value = try self.createManagedHostIntArray(out.items);
        return try self.setNumericMatrixShapeOnValue(value, rank, cols);
    }

    fn whereScalarCountValue(self: *Session, count_value: i64) KError!Value {
        if (count_value < 0) return error.Type;
        const count: usize = @intCast(count_value);
        var out = std.ArrayList(i64).empty;
        defer out.deinit(self.allocator);
        try out.ensureTotalCapacity(self.allocator, count);
        for (0..count) |_| try out.append(self.allocator, 0);
        return try self.createManagedHostIntArray(out.items);
    }

    fn fillWhereBitVectorIndices(comptime T: type, out: []T, bits: HostBitSlice) HostIntRange {
        var out_idx: usize = 0;
        var first_value: i64 = 0;
        var last_value: i64 = 0;
        for (bits.words, 0..) |_, word_idx| {
            const word_base = word_idx * host_bit_word_bits;
            var selected = bitWordMasked(bits.words, bits.len, word_idx);
            while (selected != 0) {
                const bit_idx: usize = @intCast(@ctz(selected));
                const index = word_base + bit_idx;
                out[out_idx] = @intCast(index);
                const index_i64: i64 = @intCast(index);
                if (out_idx == 0) first_value = index_i64;
                last_value = index_i64;
                out_idx += 1;
                selected &= selected - 1;
            }
        }
        return if (out.len == 0)
            .{ .min = 0, .max = 0 }
        else
            .{ .min = first_value, .max = last_value };
    }

    const where_i8_byte_stride: u64 = 0x0808_0808_0808_0808;
    const WhereI16Offsets8 = @Vector(8, i16);
    const WhereI32Offsets4 = @Vector(4, i32);
    const WhereI32Offsets8 = struct {
        lo: WhereI32Offsets4,
        hi: WhereI32Offsets4,
    };
    const where_i8_offsets8 = makeWhereI8Offsets8();
    const where_i16_offsets8 = makeWhereI16Offsets8();
    const where_i32_offsets8 = makeWhereI32Offsets8();
    const where_i8_counts8 = makeWhereI8Counts8();

    fn makeWhereI8Offsets8() [256]u64 {
        @setEvalBranchQuota(4096);
        var table: [256]u64 = undefined;
        for (&table, 0..) |*entry, mask_idx| {
            var packed_offsets: u64 = 0;
            var out_idx: usize = 0;
            for (0..8) |lane| {
                if (((mask_idx >> @intCast(lane)) & 1) == 0) continue;
                packed_offsets |= @as(u64, @intCast(lane)) << @intCast(out_idx * 8);
                out_idx += 1;
            }
            entry.* = packed_offsets;
        }
        return table;
    }

    fn makeWhereI16Offsets8() [256]WhereI16Offsets8 {
        @setEvalBranchQuota(4096);
        var table: [256]WhereI16Offsets8 = undefined;
        for (&table, 0..) |*entry, mask_idx| {
            var lanes: [8]i16 = @splat(0);
            var out_idx: usize = 0;
            for (0..8) |lane| {
                if (((mask_idx >> @intCast(lane)) & 1) == 0) continue;
                lanes[out_idx] = @intCast(lane);
                out_idx += 1;
            }
            entry.* = lanes;
        }
        return table;
    }

    fn makeWhereI32Offsets8() [256]WhereI32Offsets8 {
        @setEvalBranchQuota(4096);
        var table: [256]WhereI32Offsets8 = undefined;
        for (&table, 0..) |*entry, mask_idx| {
            var lo: [4]i32 = @splat(0);
            var hi: [4]i32 = @splat(0);
            var out_idx: usize = 0;
            for (0..8) |lane| {
                if (((mask_idx >> @intCast(lane)) & 1) == 0) continue;
                if (out_idx < 4) {
                    lo[out_idx] = @intCast(lane);
                } else {
                    hi[out_idx - 4] = @intCast(lane);
                }
                out_idx += 1;
            }
            entry.* = .{ .lo = lo, .hi = hi };
        }
        return table;
    }

    fn makeWhereI8Counts8() [256]u8 {
        var table: [256]u8 = undefined;
        for (&table, 0..) |*entry, mask_idx| entry.* = @popCount(@as(u8, @intCast(mask_idx)));
        return table;
    }

    fn writeI8Offsets8(dst: [*]i8, packed_offsets: u64) void {
        const typed: *align(1) u64 = @ptrCast(dst);
        typed.* = packed_offsets;
    }

    fn whereI16Offsets8(mask_byte: u8, base: usize) WhereI16Offsets8 {
        const base_vec: WhereI16Offsets8 = @splat(@as(i16, @intCast(base)));
        return where_i16_offsets8[mask_byte] + base_vec;
    }

    fn writeI16Offsets8(dst: [*]i16, offsets: WhereI16Offsets8) void {
        const typed: *align(1) WhereI16Offsets8 = @ptrCast(dst);
        typed.* = offsets;
    }

    fn whereI32Offsets8(mask_byte: u8, base: usize) WhereI32Offsets8 {
        const base_vec: WhereI32Offsets4 = @splat(@as(i32, @intCast(base)));
        const offsets = where_i32_offsets8[mask_byte];
        return .{
            .lo = offsets.lo + base_vec,
            .hi = offsets.hi + base_vec,
        };
    }

    fn writeI32Offsets8(dst: [*]i32, offsets: WhereI32Offsets8) void {
        const lo: *align(1) WhereI32Offsets4 = @ptrCast(dst);
        const hi: *align(1) WhereI32Offsets4 = @ptrCast(dst + 4);
        lo.* = offsets.lo;
        hi.* = offsets.hi;
    }

    fn booleanGradeBytePartitionSupported(comptime IdxT: type) bool {
        return IdxT == i8 or IdxT == i16 or IdxT == i32;
    }

    fn writeBooleanGradeOffsets8(comptime IdxT: type, out: []IdxT, pos: *usize, limit: usize, mask_byte: u8, base: usize) void {
        const count: usize = where_i8_counts8[mask_byte];
        if (count == 0) return;

        if (comptime IdxT == i8) {
            const packed_base = @as(u64, @intCast(base)) * 0x0101_0101_0101_0101;
            const packed_offsets = where_i8_offsets8[mask_byte] +% packed_base;
            if (pos.* + 8 <= limit) {
                writeI8Offsets8(out[pos.*..].ptr, packed_offsets);
            } else {
                var tail: [8]i8 = undefined;
                writeI8Offsets8(tail[0..].ptr, packed_offsets);
                @memcpy(out[pos.*..][0..count], tail[0..count]);
            }
        } else if (comptime IdxT == i16) {
            const offsets = whereI16Offsets8(mask_byte, base);
            if (pos.* + 8 <= limit) {
                writeI16Offsets8(out[pos.*..].ptr, offsets);
            } else {
                var tail: [8]i16 = undefined;
                writeI16Offsets8(tail[0..].ptr, offsets);
                @memcpy(out[pos.*..][0..count], tail[0..count]);
            }
        } else if (comptime IdxT == i32) {
            const offsets = whereI32Offsets8(mask_byte, base);
            if (pos.* + 8 <= limit) {
                writeI32Offsets8(out[pos.*..].ptr, offsets);
            } else {
                var tail: [8]i32 = undefined;
                writeI32Offsets8(tail[0..].ptr, offsets);
                @memcpy(out[pos.*..][0..count], tail[0..count]);
            }
        } else {
            @compileError("unsupported boolean grade byte partition index type");
        }

        pos.* += count;
    }

    fn fillBooleanGradeNative(comptime IdxT: type, out: []IdxT, bits: HostBitSlice, count_one: usize, ascending: bool) bool {
        if (comptime !enable_host_where_vectorized) return false;
        if (bits.len < host_where_vector_min_len) return false;
        const ascending_c: i32 = if (ascending) 1 else 0;

        const written = if (comptime IdxT == i16) switch (comptime zig_builtin.target.cpu.arch) {
            .aarch64 => kiwi_host_grade_bool_i16_neon(out.ptr, out.len, bits.words.ptr, bits.len, count_one, ascending_c),
            .x86_64 => kiwi_host_grade_bool_i16_sse2(out.ptr, out.len, bits.words.ptr, bits.len, count_one, ascending_c),
            else => unreachable,
        } else if (comptime IdxT == i32) switch (comptime zig_builtin.target.cpu.arch) {
            .aarch64 => kiwi_host_grade_bool_i32_neon(out.ptr, out.len, bits.words.ptr, bits.len, count_one, ascending_c),
            .x86_64 => kiwi_host_grade_bool_i32_sse2(out.ptr, out.len, bits.words.ptr, bits.len, count_one, ascending_c),
            else => unreachable,
        } else return false;

        std.debug.assert(written == out.len);
        return true;
    }

    fn fillBooleanGradeBytePartitions(comptime IdxT: type, out: []IdxT, bits: HostBitSlice, count_one: usize, ascending: bool) bool {
        if (fillBooleanGradeNative(IdxT, out, bits, count_one, ascending)) return true;
        if (comptime !booleanGradeBytePartitionSupported(IdxT)) return false;

        const count_zero = bits.len - count_one;
        const zero_limit = if (ascending) count_zero else bits.len;
        const one_limit = if (ascending) bits.len else count_one;
        var zero_pos: usize = if (ascending) 0 else count_one;
        var one_pos: usize = if (ascending) count_zero else 0;

        const bytes: [*]const u8 = @ptrCast(bits.words.ptr);
        const byte_count = (bits.len + 7) / 8;
        for (0..byte_count) |byte_idx| {
            const active = @min(@as(usize, 8), bits.len - byte_idx * 8);
            const active_mask: u8 = @intCast(bitLowMask(active));
            const ones = bytes[byte_idx] & active_mask;
            const zeros = (~bytes[byte_idx]) & active_mask;
            const base = byte_idx * 8;

            writeBooleanGradeOffsets8(IdxT, out, &zero_pos, zero_limit, zeros, base);
            writeBooleanGradeOffsets8(IdxT, out, &one_pos, one_limit, ones, base);
        }

        std.debug.assert(zero_pos == zero_limit);
        std.debug.assert(one_pos == one_limit);
        return true;
    }

    fn fillWhereBitVectorIndicesI8Table(out: []i8, bits: HostBitSlice) HostIntRange {
        std.debug.assert(bits.len <= 128);
        std.debug.assert(bitUnusedTailClear(bits));

        const bytes: [*]const u8 = @ptrCast(bits.words.ptr);
        const byte_count = (bits.len + 7) / 8;
        var out_idx: usize = 0;
        var base: u64 = 0;
        for (0..byte_count) |byte_idx| {
            const mask_byte = bytes[byte_idx];
            const count: usize = where_i8_counts8[mask_byte];
            if (count == 0) {
                base +%= where_i8_byte_stride;
                continue;
            }

            const packed_offsets = where_i8_offsets8[mask_byte] +% base;
            if (out_idx + 8 <= out.len) {
                writeI8Offsets8(out[out_idx..].ptr, packed_offsets);
            } else {
                var tail: [8]i8 = undefined;
                writeI8Offsets8(tail[0..].ptr, packed_offsets);
                @memcpy(out[out_idx..][0..count], tail[0..count]);
            }
            out_idx += count;
            base +%= where_i8_byte_stride;
        }

        std.debug.assert(out_idx == out.len);
        return whereFilledIntRange(i8, out);
    }

    fn fillWhereBitVectorRejectIndicesI8Table(out: []i8, bits: HostBitSlice) HostIntRange {
        std.debug.assert(bits.len <= 128);

        const bytes: [*]const u8 = @ptrCast(bits.words.ptr);
        const byte_count = (bits.len + 7) / 8;
        var out_idx: usize = 0;
        var base: u64 = 0;
        for (0..byte_count) |byte_idx| {
            const active = @min(@as(usize, 8), bits.len - byte_idx * 8);
            const active_mask: u8 = @intCast(bitLowMask(active));
            const mask_byte = (~bytes[byte_idx]) & active_mask;
            const count: usize = where_i8_counts8[mask_byte];
            if (count == 0) {
                base +%= where_i8_byte_stride;
                continue;
            }

            const packed_offsets = where_i8_offsets8[mask_byte] +% base;
            if (out_idx + 8 <= out.len) {
                writeI8Offsets8(out[out_idx..].ptr, packed_offsets);
            } else {
                var tail: [8]i8 = undefined;
                writeI8Offsets8(tail[0..].ptr, packed_offsets);
                @memcpy(out[out_idx..][0..count], tail[0..count]);
            }
            out_idx += count;
            base +%= where_i8_byte_stride;
        }

        std.debug.assert(out_idx == out.len);
        return whereFilledIntRange(i8, out);
    }

    fn fillWhereBitVectorIndicesI16ZigVector(out: []i16, bits: HostBitSlice) void {
        std.debug.assert(bitUnusedTailClear(bits));

        const bytes: [*]const u8 = @ptrCast(bits.words.ptr);
        const byte_count = (bits.len + 7) / 8;
        var out_idx: usize = 0;
        for (0..byte_count) |byte_idx| {
            const mask_byte = bytes[byte_idx];
            const count: usize = where_i8_counts8[mask_byte];
            if (count == 0) continue;

            const offsets = whereI16Offsets8(mask_byte, byte_idx * 8);
            if (out_idx + 8 <= out.len) {
                writeI16Offsets8(out[out_idx..].ptr, offsets);
            } else {
                var tail: [8]i16 = undefined;
                writeI16Offsets8(tail[0..].ptr, offsets);
                @memcpy(out[out_idx..][0..count], tail[0..count]);
            }
            out_idx += count;
        }

        std.debug.assert(out_idx == out.len);
    }

    fn fillWhereBitVectorRejectIndicesI16ZigVector(out: []i16, bits: HostBitSlice) void {
        const bytes: [*]const u8 = @ptrCast(bits.words.ptr);
        const byte_count = (bits.len + 7) / 8;
        var out_idx: usize = 0;
        for (0..byte_count) |byte_idx| {
            const active = @min(@as(usize, 8), bits.len - byte_idx * 8);
            const active_mask: u8 = @intCast(bitLowMask(active));
            const mask_byte = (~bytes[byte_idx]) & active_mask;
            const count: usize = where_i8_counts8[mask_byte];
            if (count == 0) continue;

            const offsets = whereI16Offsets8(mask_byte, byte_idx * 8);
            if (out_idx + 8 <= out.len) {
                writeI16Offsets8(out[out_idx..].ptr, offsets);
            } else {
                var tail: [8]i16 = undefined;
                writeI16Offsets8(tail[0..].ptr, offsets);
                @memcpy(out[out_idx..][0..count], tail[0..count]);
            }
            out_idx += count;
        }

        std.debug.assert(out_idx == out.len);
    }

    fn fillWhereBitVectorIndicesI32ZigVector(out: []i32, bits: HostBitSlice) void {
        std.debug.assert(bitUnusedTailClear(bits));

        const bytes: [*]const u8 = @ptrCast(bits.words.ptr);
        const byte_count = (bits.len + 7) / 8;
        var out_idx: usize = 0;
        for (0..byte_count) |byte_idx| {
            const mask_byte = bytes[byte_idx];
            const count: usize = where_i8_counts8[mask_byte];
            if (count == 0) continue;

            const offsets = whereI32Offsets8(mask_byte, byte_idx * 8);
            if (out_idx + 8 <= out.len) {
                writeI32Offsets8(out[out_idx..].ptr, offsets);
            } else {
                var tail: [8]i32 = undefined;
                writeI32Offsets8(tail[0..].ptr, offsets);
                @memcpy(out[out_idx..][0..count], tail[0..count]);
            }
            out_idx += count;
        }

        std.debug.assert(out_idx == out.len);
    }

    fn fillWhereBitVectorRejectIndicesI32ZigVector(out: []i32, bits: HostBitSlice) void {
        const bytes: [*]const u8 = @ptrCast(bits.words.ptr);
        const byte_count = (bits.len + 7) / 8;
        var out_idx: usize = 0;
        for (0..byte_count) |byte_idx| {
            const active = @min(@as(usize, 8), bits.len - byte_idx * 8);
            const active_mask: u8 = @intCast(bitLowMask(active));
            const mask_byte = (~bytes[byte_idx]) & active_mask;
            const count: usize = where_i8_counts8[mask_byte];
            if (count == 0) continue;

            const offsets = whereI32Offsets8(mask_byte, byte_idx * 8);
            if (out_idx + 8 <= out.len) {
                writeI32Offsets8(out[out_idx..].ptr, offsets);
            } else {
                var tail: [8]i32 = undefined;
                writeI32Offsets8(tail[0..].ptr, offsets);
                @memcpy(out[out_idx..][0..count], tail[0..count]);
            }
            out_idx += count;
        }

        std.debug.assert(out_idx == out.len);
    }

    fn whereFilledIntRange(comptime T: type, items: []const T) HostIntRange {
        if (items.len == 0) return .{ .min = 0, .max = 0 };
        return .{
            .min = @intCast(items[0]),
            .max = @intCast(items[items.len - 1]),
        };
    }

    fn fillWhereBitVectorIndicesI32Vector(out: []i32, bits: HostBitSlice) bool {
        if (comptime enable_host_where_zig_vectorized) {
            if (bits.len < host_where_vector_min_len) return false;
            fillWhereBitVectorIndicesI32ZigVector(out, bits);
            return true;
        }
        if (comptime !enable_host_where_vectorized) return false;
        if (bits.len < host_where_vector_min_len) return false;
        std.debug.assert(bitUnusedTailClear(bits));
        const written = switch (comptime zig_builtin.target.cpu.arch) {
            .aarch64 => kiwi_host_where_i32_neon(out.ptr, out.len, bits.words.ptr, bits.len),
            .x86_64 => kiwi_host_where_i32_sse2(out.ptr, out.len, bits.words.ptr, bits.len),
            else => unreachable,
        };
        std.debug.assert(written == out.len);
        return true;
    }

    fn fillWhereBitVectorRejectIndicesI32Vector(out: []i32, bits: HostBitSlice) bool {
        if (comptime enable_host_where_zig_vectorized) {
            if (bits.len < host_where_vector_min_len) return false;
            fillWhereBitVectorRejectIndicesI32ZigVector(out, bits);
            return true;
        }
        if (comptime !enable_host_where_vectorized) return false;
        if (bits.len < host_where_vector_min_len) return false;
        const written = switch (comptime zig_builtin.target.cpu.arch) {
            .aarch64 => kiwi_host_where_not_i32_neon(out.ptr, out.len, bits.words.ptr, bits.len),
            .x86_64 => kiwi_host_where_not_i32_sse2(out.ptr, out.len, bits.words.ptr, bits.len),
            else => unreachable,
        };
        std.debug.assert(written == out.len);
        return true;
    }

    fn fillWhereBitVectorIndicesI16Vector(out: []i16, bits: HostBitSlice) bool {
        if (comptime enable_host_where_zig_vectorized) {
            if (bits.len < host_where_vector_min_len) return false;
            fillWhereBitVectorIndicesI16ZigVector(out, bits);
            return true;
        }
        if (comptime !enable_host_where_vectorized) return false;
        if (bits.len < host_where_vector_min_len) return false;
        std.debug.assert(bitUnusedTailClear(bits));
        const written = switch (comptime zig_builtin.target.cpu.arch) {
            .aarch64 => kiwi_host_where_i16_neon(out.ptr, out.len, bits.words.ptr, bits.len),
            .x86_64 => kiwi_host_where_i16_sse2(out.ptr, out.len, bits.words.ptr, bits.len),
            else => unreachable,
        };
        std.debug.assert(written == out.len);
        return true;
    }

    fn fillWhereBitVectorRejectIndicesI16Vector(out: []i16, bits: HostBitSlice) bool {
        if (comptime enable_host_where_zig_vectorized) {
            if (bits.len < host_where_vector_min_len) return false;
            fillWhereBitVectorRejectIndicesI16ZigVector(out, bits);
            return true;
        }
        if (comptime !enable_host_where_vectorized) return false;
        if (bits.len < host_where_vector_min_len) return false;
        const written = switch (comptime zig_builtin.target.cpu.arch) {
            .aarch64 => kiwi_host_where_not_i16_neon(out.ptr, out.len, bits.words.ptr, bits.len),
            .x86_64 => kiwi_host_where_not_i16_sse2(out.ptr, out.len, bits.words.ptr, bits.len),
            else => unreachable,
