    fn whereBitVectorValue(self: *Session, array: *const HostDenseArray) KError!Value {
        const bits: HostBitSlice = .{ .words = array.storage.bit, .len = array.len() };
        const count = bitCountTrue(bits);
        const max_index: i64 = if (bits.len == 0) 0 else std.math.cast(i64, bits.len - 1) orelse return error.Unsupported;
        if (count == 0) return try newRangeIotaValue(self, .managed, 0);
        if (count == bits.len) return try newRangeIotaValue(self, .managed, bits.len);
        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_index), count);
        const range = switch (out) {
            .bit => unreachable,
            .int8 => |*result| fillWhereBitVectorIndicesI8Table(result.items, bits),
            .int16 => |*result| blk: {
                if (fillWhereBitVectorIndicesI16Vector(result.items, bits)) {
                    self.noteSimdKernel(.where_indices);
                    break :blk whereFilledIntRange(i16, result.items);
                }
                break :blk fillWhereBitVectorIndices(i16, result.items, bits);
            },
            .int32 => |*result| blk: {
                if (fillWhereBitVectorIndicesI32Vector(result.items, bits)) {
                    self.noteSimdKernel(.where_indices);
                    break :blk whereFilledIntRange(i32, result.items);
                }
                break :blk fillWhereBitVectorIndices(i32, result.items, bits);
            },
            .int64 => |*result| fillWhereBitVectorIndices(i64, result.items, bits),
        };
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, if (count <= 1)
            host_dense_flag_normalized | host_dense_flag_asc | host_dense_flag_dsc
        else
            host_dense_flag_normalized | host_dense_flag_asc);
        hostDenseSetCachedIntRange(host, range);
        return value;
    }

    const WhereIntVectorStats = struct {
        total: usize,
        first_value: ?i64,
        last_value: i64,
    };

    fn whereIntVectorStatsForItems(comptime CountT: type, items: []const CountT) KError!WhereIntVectorStats {
        var stats: WhereIntVectorStats = .{
            .total = 0,
            .first_value = null,
            .last_value = 0,
        };
        for (items, 0..) |item, idx| {
            const count_i64: i64 = item;
            if (count_i64 < 0) return error.Type;
            const count = std.math.cast(usize, count_i64) orelse return error.Unsupported;
            stats.total = std.math.add(usize, stats.total, count) catch return error.Unsupported;
            if (count != 0) {
                const index_value: i64 = @intCast(idx);
                if (stats.first_value == null) stats.first_value = index_value;
                stats.last_value = index_value;
            }
        }
        return stats;
    }

    fn whereIntVectorStats(view: HostIntArrayView) KError!WhereIntVectorStats {
        return switch (view) {
            .bit => unreachable,
            .int8 => |items| whereIntVectorStatsForItems(i8, items),
            .int16 => |items| whereIntVectorStatsForItems(i16, items),
            .int32 => |items| whereIntVectorStatsForItems(i32, items),
            .int64 => |items| whereIntVectorStatsForItems(i64, items),
        };
    }

    fn countWhereValueAsI64(self: *Session, value: Value) KError!i64 {
        if (scalarIntLikeValue(value)) |count_value| {
            if (count_value < 0) return error.Type;
            return count_value;
        }
        if (valueNumericMode(value) != null and valueNumericMatrixShape(value) == null) {
            const array = try numericHostArrayValue(self, value);
            return switch (array.storage) {
                .bit => try countLenAsI64(bitCountTrue(.{ .words = array.storage.bit, .len = array.len() })),
                .int8, .int16, .int32, .int64 => blk: {
                    const view = hostIntArrayView(array) orelse return error.Type;
                    break :blk try countLenAsI64((try whereIntVectorStats(view)).total);
                },
                else => error.Type,
            };
        }
        return error.Type;
    }

    fn countWhereValue(self: *Session, value: Value) KError!Value {
        return try self.intValue(try self.countWhereValueAsI64(value));
    }

    fn fillWhereIntVectorIndicesFromItems(comptime OutT: type, comptime CountT: type, out: []OutT, items: []const CountT) void {
        var out_idx: usize = 0;
        for (items, 0..) |item, idx| {
            const count: usize = @intCast(item);
            if (count == 0) continue;
            @memset(out[out_idx..][0..count], @as(OutT, @intCast(idx)));
            out_idx += count;
        }
        std.debug.assert(out_idx == out.len);
    }

    fn fillWhereIntVectorIndicesForView(comptime OutT: type, out: []OutT, view: HostIntArrayView) void {
        switch (view) {
            .bit => unreachable,
            .int8 => |items| fillWhereIntVectorIndicesFromItems(OutT, i8, out, items),
            .int16 => |items| fillWhereIntVectorIndicesFromItems(OutT, i16, out, items),
            .int32 => |items| fillWhereIntVectorIndicesFromItems(OutT, i32, out, items),
            .int64 => |items| fillWhereIntVectorIndicesFromItems(OutT, i64, out, items),
        }
    }

    fn whereIntVectorValue(self: *Session, array: *const HostDenseArray) KError!Value {
        const view = hostIntArrayView(array) orelse return error.Type;
        const stats = try whereIntVectorStats(view);
        if (stats.total == 0) return try newRangeIotaValue(self, .managed, 0);

        const max_index: i64 = std.math.cast(i64, hostIntArrayViewLen(view) - 1) orelse return error.Unsupported;
        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_index), stats.total);
        switch (out) {
            .bit => unreachable,
            .int8 => |*result| fillWhereIntVectorIndicesForView(i8, result.items, view),
            .int16 => |*result| fillWhereIntVectorIndicesForView(i16, result.items, view),
            .int32 => |*result| fillWhereIntVectorIndicesForView(i32, result.items, view),
            .int64 => |*result| fillWhereIntVectorIndicesForView(i64, result.items, view),
        }
        const range: HostIntRange = .{ .min = stats.first_value.?, .max = stats.last_value };
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, if (range.min == range.max)
            host_dense_flag_normalized | host_dense_flag_asc | host_dense_flag_dsc
        else
            host_dense_flag_normalized | host_dense_flag_asc);
        hostDenseSetCachedIntRange(host, range);
        return value;
    }

    fn whereBoxedArrayValue(self: *Session, array: *const HostBoxedArray) KError!Value {
        var row_indices = std.ArrayList(i64).empty;
        defer row_indices.deinit(self.allocator);
        var col_indices = std.ArrayList(i64).empty;
        defer col_indices.deinit(self.allocator);

        for (array.items[0..array.len()], 0..) |item, row_idx| {
            const selector = try self.whereValue(item);
            errdefer self.releaseValue(selector);
            const view = valueHostIntStructuralView(selector) orelse return error.Type;
            const len = hostIntDenseViewLen(view);
            try row_indices.ensureUnusedCapacity(self.allocator, len);
            try col_indices.ensureUnusedCapacity(self.allocator, len);
            const row_value = std.math.cast(i64, row_idx) orelse return error.Unsupported;
            for (0..len) |idx| {
                row_indices.appendAssumeCapacity(row_value);
                col_indices.appendAssumeCapacity(try hostIntDenseViewItem(view, idx));
            }
            self.releaseValue(selector);
        }

        const rows = try self.createManagedHostIntArray(row_indices.items);
        defer self.releaseValue(rows);
        const cols = try self.createManagedHostIntArray(col_indices.items);
        defer self.releaseValue(cols);
        return try self.makeArrayFromValues(&[_]Value{ rows, cols });
    }

    fn whereNumericMatrixValue(self: *Session, value: Value, shape: NumericMatrixShape) KError!Value {
        const mode = valueNumericMode(value) orelse return error.Type;
        var row_indices = std.ArrayList(i64).empty;
        defer row_indices.deinit(self.allocator);
        var col_indices = std.ArrayList(i64).empty;
        defer col_indices.deinit(self.allocator);

        for (0..shape.rows) |row| {
            const row_value = std.math.cast(i64, row) orelse return error.Unsupported;
            for (0..shape.cols) |col| {
                const flat_idx = row * shape.cols + col;
                const present = switch (mode) {
                    .int => (try numericIntAt(value, flat_idx)) != 0,
                    .float => (try numericFloatAt(value, flat_idx)) != 0.0,
                };
                if (!present) continue;
                try row_indices.append(self.allocator, row_value);
                try col_indices.append(self.allocator, std.math.cast(i64, col) orelse return error.Unsupported);
            }
        }

        const rows = try self.createManagedHostIntArray(row_indices.items);
        defer self.releaseValue(rows);
        const cols = try self.createManagedHostIntArray(col_indices.items);
        defer self.releaseValue(cols);
        return try self.makeArrayFromValues(&[_]Value{ rows, cols });
    }

    fn whereValue(self: *Session, value: Value) KError!Value {
        if (scalarIntLikeValue(value)) |count_value| return try self.whereScalarCountValue(count_value);
        if (value.tag() == .array) {
            switch (value.arrayKind()) {
                .host_keyed_store => {
                    const store = value.asHostKeyedStore();
                    if (store.layout == .dict) {
                        const selector = try self.whereValue(store.values);
                        defer self.releaseValue(selector);
                        return try self.applyValue(store.names, &[_]Value{selector});
                    }
                },
                .host_boxed_array => return try self.whereBoxedArrayValue(value.asHostBoxedArray()),
                else => {},
            }
        }
        if (valueNumericMatrixShape(value)) |shape| return try self.whereNumericMatrixValue(value, shape);
        if (valueNumericMode(value) != null and valueNumericMatrixShape(value) == null) {
            const array = try numericHostArrayValue(self, value);
            return switch (array.storage) {
                .bit => try self.whereBitVectorValue(array),
                .int8, .int16, .int32, .int64 => try self.whereIntVectorValue(array),
                else => error.Type,
            };
        }
        return error.Type;
    }

    fn filterRightLen(value: Value) ?usize {
        return switch (value.tag()) {
            .int, .bool, .float, .float32, .builtin, .closure => 1,
            .array => blk: {
                if (stringSourceInfo(value)) |source| break :blk source.bytes().len;
                if (value.arrayKind() == .host_symbol or value.arrayKind() == .host_handle or value.arrayKind() == .host_table_scalar) break :blk 1;
                if (value.arrayKind() == .host_keyed_store) {
                    const store = value.asHostKeyedStore();
                    break :blk switch (store.layout) {
                        .dict => keyedStoreNameCount(store),
                        .table => store.row_count,
                    };
                }
                if (value.arrayKind() == .host_relation) {
                    const relation = value.asHostRelation();
                    break :blk if (relation.cached_row_count_known) relation.cached_row_count else null;
                }
                break :blk derivedSequenceLen(value);
            },
        };
    }

    fn sourceIndicesFromScalarFilterCount(self: *Session, count_value: i64, source_len: usize) KError![]usize {
        if (count_value < 0) return error.Type;
        const count: usize = @intCast(count_value);
        const total = std.math.mul(usize, count, source_len) catch return error.Unsupported;
        const out = try self.allocator.alloc(usize, total);
        errdefer self.allocator.free(out);

        var write_idx: usize = 0;
        for (0..source_len) |source_idx| {
            for (0..count) |_| {
                out[write_idx] = source_idx;
                write_idx += 1;
            }
        }
        return out;
    }

    fn sourceIndicesFromCountFilterView(self: *Session, view: HostIntDenseView, source_len: usize) KError![]usize {
        if (hostIntDenseViewLen(view) != source_len) return error.Type;

        var total: usize = 0;
        for (0..source_len) |idx| {
            const count_i64 = try hostIntDenseViewItem(view, idx);
            if (count_i64 < 0) return error.Type;
            const count: usize = @intCast(count_i64);
            total = std.math.add(usize, total, count) catch return error.Unsupported;
        }

        const out = try self.allocator.alloc(usize, total);
        errdefer self.allocator.free(out);

        var write_idx: usize = 0;
        for (0..source_len) |source_idx| {
            const count: usize = @intCast(try hostIntDenseViewItem(view, source_idx));
            for (0..count) |_| {
                out[write_idx] = source_idx;
                write_idx += 1;
            }
        }
        return out;
    }

    fn sourceIndicesFromBitFilterMask(self: *Session, bits: HostBitSlice, source_len: usize) KError![]usize {
        if (bits.len != source_len) return error.Type;
        const out = try self.allocator.alloc(usize, bitCountTrue(bits));
        errdefer self.allocator.free(out);

        var out_idx: usize = 0;
        for (bits.words, 0..) |_, word_idx| {
            const word_base = word_idx * host_bit_word_bits;
            var selected = bitWordMasked(bits.words, bits.len, word_idx);
            while (selected != 0) {
                const bit_idx: usize = @intCast(@ctz(selected));
                out[out_idx] = word_base + bit_idx;
                out_idx += 1;
                selected &= selected - 1;
            }
        }
        return out;
    }

    fn sourceIndicesFromBitRejectMask(self: *Session, bits: HostBitSlice, source_len: usize) KError![]usize {
        if (bits.len != source_len) return error.Type;
        const out = try self.allocator.alloc(usize, source_len - bitCountTrue(bits));
        errdefer self.allocator.free(out);

        var out_idx: usize = 0;
        for (0..source_len) |idx| {
            if (bitGet(bits.words, idx)) continue;
            out[out_idx] = idx;
            out_idx += 1;
        }
        return out;
    }

    fn sourceIndicesFromScalarRejectCount(self: *Session, count_value: i64, source_len: usize) KError![]usize {
        if (count_value != 0) return try self.allocator.alloc(usize, 0);

        const out = try self.allocator.alloc(usize, source_len);
        errdefer self.allocator.free(out);
        for (out, 0..) |*item, idx| item.* = idx;
        return out;
    }

    fn sourceIndicesFromCountRejectView(self: *Session, view: HostIntDenseView, source_len: usize) KError![]usize {
        if (hostIntDenseViewLen(view) != source_len) return error.Type;

        var total: usize = 0;
        for (0..source_len) |idx| {
            const count_i64 = try hostIntDenseViewItem(view, idx);
            if (count_i64 == 0) total += 1;
        }

        const out = try self.allocator.alloc(usize, total);
        errdefer self.allocator.free(out);

        var write_idx: usize = 0;
        for (0..source_len) |source_idx| {
            if ((try hostIntDenseViewItem(view, source_idx)) != 0) continue;
            out[write_idx] = source_idx;
            write_idx += 1;
        }
        return out;
    }

    fn directHostBitFilterMask(value: Value, source_len: usize) KError!?HostBitSlice {
        const len = numericVectorLen(value) orelse return null;
        if (len != source_len) return error.Type;
        const host = hostDenseIfPresent(value) orelse return null;
        return switch (host.storage) {
            .bit => |words| .{ .words = words, .len = host.logical_len },
            else => null,
        };
    }

    fn sourceIndicesFromFilterPredicate(self: *Session, predicate: Value, source_len: usize) KError![]usize {
        if (scalarIntLikeValue(predicate)) |count_value| {
            return try self.sourceIndicesFromScalarFilterCount(count_value, source_len);
        }
        if (numericVectorLen(predicate) == null) return error.Type;
        const view = valueHostIntStructuralView(predicate) orelse blk: {
            if (valueNumericMode(predicate) == null) return error.Type;
            const host = try numericHostArrayValue(self, predicate);
            const host_view = hostIntArrayView(host) orelse return error.Type;
            break :blk HostIntDenseView{ .dense = host_view };
        };
        return try self.sourceIndicesFromCountFilterView(view, source_len);
    }

    fn sourceIndicesFromRejectPredicate(self: *Session, predicate: Value, source_len: usize) KError![]usize {
        if (scalarIntLikeValue(predicate)) |count_value| {
            return try self.sourceIndicesFromScalarRejectCount(count_value, source_len);
        }
        if (numericVectorLen(predicate) == null) return error.Type;
        const view = valueHostIntStructuralView(predicate) orelse blk: {
            if (valueNumericMode(predicate) == null) return error.Type;
            const host = try numericHostArrayValue(self, predicate);
            const host_view = hostIntArrayView(host) orelse return error.Type;
            break :blk HostIntDenseView{ .dense = host_view };
        };
        return try self.sourceIndicesFromCountRejectView(view, source_len);
    }

    fn filterPredicatePayload(value: Value) Value {
        if (value.tag() == .array and value.arrayKind() == .host_keyed_store) {
            const store = value.asHostKeyedStore();
            if (store.layout == .dict) return store.values;
        }
        return value;
    }

    fn intSelectorValueFromSourceIndices(self: *Session, indices: []const usize) KError!Value {
        const values = try self.allocator.alloc(i64, indices.len);
        defer self.allocator.free(values);
        for (indices, 0..) |idx, out_idx| {
            values[out_idx] = std.math.cast(i64, idx) orelse return error.Unsupported;
        }
        return try self.createManagedHostIntArray(values);
    }

    fn selectHostStringListBySourceIndices(self: *Session, list: *const HostStringList, indices: []const usize) KError!Value {
        if (indices.len == 0) return try self.emptySequenceForHostStringList(list);

        const items = try self.allocator.alloc([]const u8, indices.len);
        defer self.allocator.free(items);
        for (indices, 0..) |source_idx, out_idx| {
            if (source_idx >= list.len) return error.Type;
            items[out_idx] = try hostStringListItemBytes(list, source_idx);
        }
        return try self.createManagedHostStringListFromSlices(items);
    }

    fn selectHostSymbolListBySourceIndices(self: *Session, list: *const HostStringList, indices: []const usize) KError!Value {
        const items = try self.allocator.alloc([]const u8, indices.len);
        defer self.allocator.free(items);
        for (indices, 0..) |source_idx, out_idx| {
            if (source_idx >= list.len) return error.Type;
            items[out_idx] = try hostStringListItemBytes(list, source_idx);
        }
        return try self.createManagedHostSymbolListFromSlices(items);
    }

    fn selectHostTextListBySelectorValue(self: *Session, list: *const HostStringList, selector: Value, symbol: bool) KError!Value {
        const selector_len = if (stringBytes(selector)) |bytes|
            bytes.len
        else if (valueHostIntStructuralView(selector)) |view|
            hostIntDenseViewLen(view)
        else
            return error.Type;
        if (!symbol and selector_len == 0) return try self.emptySequenceForHostStringList(list);

        const items = try self.allocator.alloc([]const u8, selector_len);
        defer self.allocator.free(items);
        var string_prototype_bytes: ?[]u8 = null;
        defer if (string_prototype_bytes) |bytes| self.allocator.free(bytes);

        if (stringBytes(selector)) |bytes| {
            for (bytes, 0..) |byte, idx| {
                items[idx] = if (normalizeIndexOrNull(@intCast(byte), list.len)) |source_idx|
                    try hostStringListItemBytes(list, source_idx)
                else blk: {
                    if (symbol) break :blk &.{};
                    if (string_prototype_bytes == null) string_prototype_bytes = try self.hostStringListPrototypeBytes(list);
                    break :blk string_prototype_bytes.?;
                };
            }
        } else {
            const view = valueHostIntStructuralView(selector) orelse return error.Type;
            for (0..selector_len) |idx| {
                const raw_index = try hostIntDenseViewItem(view, idx);
                items[idx] = if (normalizeIndexOrNull(raw_index, list.len)) |source_idx|
                    try hostStringListItemBytes(list, source_idx)
                else blk: {
                    if (symbol) break :blk &.{};
                    if (string_prototype_bytes == null) string_prototype_bytes = try self.hostStringListPrototypeBytes(list);
                    break :blk string_prototype_bytes.?;
                };
            }
        }

        return if (symbol)
            try self.createManagedHostSymbolListFromSlices(items)
        else
            try self.createManagedHostStringListFromSlices(items);
    }

    fn selectHostTextListByBitMask(self: *Session, list: *const HostStringList, bits: HostBitSlice, invert: bool, symbol: bool) KError!Value {
        if (bits.len != list.len) return error.Type;
        const true_count = bitCountTrue(bits);
        const selected_len = if (invert) bits.len - true_count else true_count;
        if (!symbol and selected_len == 0) return try self.emptySequenceForHostStringList(list);

        const items = try self.allocator.alloc([]const u8, selected_len);
        defer self.allocator.free(items);

        var out_idx: usize = 0;
        for (bits.words, 0..) |_, word_idx| {
            const word_base = word_idx * host_bit_word_bits;
            const active = bitWordActiveLen(bits.len, word_idx, bits.words.len);
            const active_mask = bitLowMask(active);
            var selected = bitWordMasked(bits.words, bits.len, word_idx);
            if (invert) selected = (~selected) & active_mask;
            while (selected != 0) {
                const bit_idx: usize = @intCast(@ctz(selected));
                const source_idx = word_base + bit_idx;
                items[out_idx] = try hostStringListItemBytes(list, source_idx);
                out_idx += 1;
                selected &= selected - 1;
            }
        }
        std.debug.assert(out_idx == selected_len);

        return if (symbol)
            try self.createManagedHostSymbolListFromSlices(items)
        else
            try self.createManagedHostStringListFromSlices(items);
    }

    fn selectHostStringListByBitMask(self: *Session, list: *const HostStringList, bits: HostBitSlice, invert: bool) KError!Value {
        return try self.selectHostTextListByBitMask(list, bits, invert, false);
    }

    fn selectHostSymbolListByBitMask(self: *Session, list: *const HostStringList, bits: HostBitSlice, invert: bool) KError!Value {
        return try self.selectHostTextListByBitMask(list, bits, invert, true);
    }

    fn selectHostBoxedArrayBySourceIndices(self: *Session, array: *const HostBoxedArray, indices: []const usize) KError!Value {
        if (indices.len == 0) {
            if (array.len() != 0) return try self.emptySequenceForBoxedItem(.managed, array.items[0]);
            if (array.prototype) |prototype| return try self.emptySequenceForBoxedItem(.managed, prototype);
            return try self.createManagedHostBoxedArray(&.{});
        }

        const items = try self.allocator.alloc(Value, indices.len);
        defer self.allocator.free(items);
        for (indices, 0..) |source_idx, out_idx| {
            if (source_idx >= array.len()) return error.Type;
            items[out_idx] = array.items[source_idx];
        }
        if (try self.tryCreateCharVectorFromSingletonStringItems(items)) |text| return text;
        return try self.makeArrayFromValues(items);
    }

    fn selectRightBySourceIndices(self: *Session, right: Value, indices: []const usize) KError!Value {
        if (right.tag() == .array) {
            switch (right.arrayKind()) {
                .host_keyed_store => {
                    const store = right.asHostKeyedStore();
                    return switch (store.layout) {
                        .dict => try self.projectKeyedStore(store, indices),
                        .table => try self.tableSelectRows(store, indices),
                    };
                },
                .host_string_list => return try self.selectHostStringListBySourceIndices(right.asHostStringList(), indices),
                .host_symbol_list => return try self.selectHostSymbolListBySourceIndices(right.asHostStringList(), indices),
                .host_boxed_array => return try self.selectHostBoxedArrayBySourceIndices(right.asHostBoxedArray(), indices),
                .host_symbol, .host_table_scalar => {
                    const count = std.math.cast(i64, indices.len) orelse return error.Unsupported;
                    const count_value = try self.intValue(count);
                    defer self.releaseValue(count_value);
                    return try self.takeValues(count_value, right);
                },
                else => {},
            }
        } else {
            const count = std.math.cast(i64, indices.len) orelse return error.Unsupported;
            const count_value = try self.intValue(count);
            defer self.releaseValue(count_value);
            return try self.takeValues(count_value, right);
        }

        const selector = try self.intSelectorValueFromSourceIndices(indices);
        defer self.releaseValue(selector);
        return try self.applyArrayCall1(right, selector);
    }

    fn filterSelectByHostBitMask(self: *Session, right: Value, predicate: Value, bits: HostBitSlice, source_len: usize) KError!Value {
        _ = predicate;
        if (right.tag() == .array) {
            if (stringSourceInfo(right)) |source| return try self.stringIndexWhereBitMaskValue(source, bits);
            switch (right.arrayKind()) {
                .host_string_list => return try self.selectHostStringListByBitMask(right.asHostStringList(), bits, false),
                .host_symbol_list => return try self.selectHostSymbolListByBitMask(right.asHostStringList(), bits, false),
                else => {},
            }
        }
        const indices = try self.sourceIndicesFromBitFilterMask(bits, source_len);
        defer self.allocator.free(indices);
        return try self.selectRightBySourceIndices(right, indices);
    }

    fn applyFilterCallable(self: *Session, left: Value, right: Value) KError!Value {
        if (left.tag() == .closure) {
            const closure = left.asClosure();
            if (closure.kind == .plain and closure.code.arity == 0) {
                return try self.applyValue(left, &.{});
            }
        }
        return try self.applyValue(left, &.{right});
    }

    fn rejectSelectByHostBitMask(self: *Session, right: Value, bits: HostBitSlice, source_len: usize) KError!Value {
        if (right.tag() == .array) {
            if (stringSourceInfo(right)) |source| return try self.stringRejectWhereBitMaskValue(source, bits);
            switch (right.arrayKind()) {
                .host_string_list => return try self.selectHostStringListByBitMask(right.asHostStringList(), bits, true),
                .host_symbol_list => return try self.selectHostSymbolListByBitMask(right.asHostStringList(), bits, true),
                else => {},
            }
        }

        const indices = try self.sourceIndicesFromBitRejectMask(bits, source_len);
        defer self.allocator.free(indices);
        return try self.selectRightBySourceIndices(right, indices);
    }

    fn filterValues(self: *Session, left: Value, right: Value) KError!Value {
        const source_len = filterRightLen(right) orelse return error.Type;
        const predicate = try self.applyFilterCallable(left, right);
        defer self.releaseValue(predicate);
        const predicate_payload = filterPredicatePayload(predicate);

        if (try directHostBitFilterMask(predicate_payload, source_len)) |bits| {
            return try self.filterSelectByHostBitMask(right, predicate_payload, bits, source_len);
        }
        if (valueBackendBoolMaskLen(predicate_payload)) |mask_len| {
            if (mask_len != source_len) return error.Type;
            if (right.tag() == .array and valueNumericMode(right) != null) {
                if (try tryApplyBackendBoolMaskSelect(self, right, predicate_payload)) |result| return result;
            }
        }

        const indices = try self.sourceIndicesFromFilterPredicate(predicate_payload, source_len);
        defer self.allocator.free(indices);
        return try self.selectRightBySourceIndices(right, indices);
    }

    fn rejectValues(self: *Session, left: Value, right: Value) KError!Value {
        const source_len = filterRightLen(right) orelse return error.Type;
        const predicate = try self.applyFilterCallable(left, right);
        defer self.releaseValue(predicate);
        const predicate_payload = filterPredicatePayload(predicate);

        if (try directHostBitFilterMask(predicate_payload, source_len)) |bits| {
            return try self.rejectSelectByHostBitMask(right, bits, source_len);
        }

        const indices = try self.sourceIndicesFromRejectPredicate(predicate_payload, source_len);
        defer self.allocator.free(indices);
        return try self.selectRightBySourceIndices(right, indices);
    }

    fn groupOrUnitMatrixValue(self: *Session, value: Value) KError!Value {
        if (scalarIntLikeValue(value) != null) return try self.unitMatrixValue(value);
        return try self.groupValue(value);
    }

    fn createEmptyGroupValues(self: *Session) KError!Value {
        const empty_indices = try self.createManagedHostIntArray(&.{});
        defer self.releaseValue(empty_indices);
        return try self.createManagedHostBoxedArrayWithPrototype(&.{}, empty_indices);
    }

    fn createGroupIndexValues(self: *Session, counts: []const usize, groups: []const usize) KError!Value {
        if (counts.len == 0) return try self.createEmptyGroupValues();

        var starts = try self.allocator.alloc(usize, counts.len);
        defer self.allocator.free(starts);
        var cursors = try self.allocator.alloc(usize, counts.len);
        defer self.allocator.free(cursors);

        var total: usize = 0;
        for (counts, 0..) |count, idx| {
            starts[idx] = total;
            cursors[idx] = total;
            total = std.math.add(usize, total, count) catch return error.Unsupported;
        }
        if (total != groups.len) return error.Internal;

        var flat = try self.allocator.alloc(i64, total);
        defer self.allocator.free(flat);
        for (groups, 0..) |group_idx, item_idx| {
            if (group_idx >= counts.len) return error.Internal;
            flat[cursors[group_idx]] = std.math.cast(i64, item_idx) orelse return error.Unsupported;
            cursors[group_idx] += 1;
        }

        var values = try self.allocator.alloc(Value, counts.len);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |value| self.releaseValue(value);
        }

        for (counts, 0..) |count, group_idx| {
            const start = starts[group_idx];
            values[group_idx] = try self.createManagedHostIntArray(flat[start .. start + count]);
            initialized += 1;
        }
        return try self.createManagedHostBoxedArray(values);
    }

    fn createGroupDictValue(self: *Session, keys_value: Value, counts: []const usize, groups: []const usize) KError!Value {
        const values_value = try self.createGroupIndexValues(counts, groups);
        defer self.releaseValue(values_value);
        if (stringSourceInfo(keys_value) != null) return try self.createHostDictValueFromCharStringKeys("", keys_value, values_value);
        return try self.createHostDictValueFromKeySequenceValue("", keys_value, values_value);
    }

    fn createEmptyGroupDictValue(self: *Session, keys_value: Value) KError!Value {
        const values_value = try self.createEmptyGroupValues();
        defer self.releaseValue(values_value);
        if (stringSourceInfo(keys_value) != null) return try self.createHostDictValueFromCharStringKeys("", keys_value, values_value);
        return try self.createHostDictValueFromKeySequenceValue("", keys_value, values_value);
    }

    fn createGroupDictValueFromIndexValues(self: *Session, keys_value: Value, values: []const Value) KError!Value {
        const values_value = try self.createManagedHostBoxedArray(values);
        defer self.releaseValue(values_value);
        return try self.createHostDictValueFromKeySequenceValue("", keys_value, values_value);
    }

    fn groupIndexResultRange(result: *const HostIntResult, count: usize) HostIntRange {
        if (count == 0) return .{ .min = 0, .max = 0 };
        return switch (result.*) {
            .bit => unreachable,
            .int8 => |out| .{ .min = @intCast(out.items[0]), .max = @intCast(out.items[count - 1]) },
            .int16 => |out| .{ .min = @intCast(out.items[0]), .max = @intCast(out.items[count - 1]) },
            .int32 => |out| .{ .min = @intCast(out.items[0]), .max = @intCast(out.items[count - 1]) },
            .int64 => |out| .{ .min = out.items[0], .max = out.items[count - 1] },
        };
    }

    fn setGroupIndexResultMetadata(self: *Session, value: Value, result: *const HostIntResult, count: usize) KError!void {
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, if (count <= 1)
            host_dense_flag_normalized | host_dense_flag_asc | host_dense_flag_dsc
        else
            host_dense_flag_normalized | host_dense_flag_asc);
        hostDenseSetCachedIntRange(host, groupIndexResultRange(result, count));
    }

    fn createGroupIndexOutputValues(
        self: *Session,
        counts: []const usize,
        index_kind: HostIntStorageKind,
        values: []Value,
        outputs: []HostIntResult,
    ) KError!void {
        if (counts.len != values.len or counts.len != outputs.len) return error.Internal;
        var initialized: usize = 0;
        errdefer {
            for (values[0..initialized]) |value| self.releaseValue(value);
        }
        for (counts, 0..) |count, idx| {
            outputs[idx] = try self.allocManagedHostIntResult(index_kind, count);
            values[idx] = outputs[idx].value();
            initialized += 1;
        }
    }

    fn fillWhereBitVectorRejectIndices(comptime T: type, out: []T, bits: HostBitSlice) HostIntRange {
        var out_idx: usize = 0;
        var first_value: i64 = 0;
        var last_value: i64 = 0;
        for (bits.words, 0..) |word, word_idx| {
            const word_base = word_idx * host_bit_word_bits;
            const active_len = bitWordActiveLen(bits.len, word_idx, bits.words.len);
            var selected = (~word) & bitLowMask(active_len);
            while (selected != 0) {
                const bit_idx: usize = @intCast(@ctz(selected));
                const index = word_base + bit_idx;
                out[out_idx] = @intCast(index);
                const index_i64: i64 = @intCast(index);
                if (out_idx == 0) first_value = index_i64;
                last_value = index_i64;
                out_idx += 1;
                selected &= selected - 1;
            }
        }
        std.debug.assert(out_idx == out.len);
        return if (out.len == 0)
            .{ .min = 0, .max = 0 }
        else
            .{ .min = first_value, .max = last_value };
    }

    fn groupBitIndexValue(self: *Session, bits: HostBitSlice, want_true: bool, count: usize) KError!Value {
        if (count == 0) return try newRangeIotaValue(self, .managed, 0);
        if (count == bits.len) return try newRangeIotaValue(self, .managed, bits.len);

        const max_index: i64 = if (bits.len == 0) 0 else std.math.cast(i64, bits.len - 1) orelse return error.Unsupported;
        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_index), count);
        const range = switch (out) {
            .bit => unreachable,
            .int8 => |*result| if (want_true)
                fillWhereBitVectorIndicesI8Table(result.items, bits)
            else
                fillWhereBitVectorRejectIndicesI8Table(result.items, bits),
            .int16 => |*result| if (want_true) blk: {
                if (fillWhereBitVectorIndicesI16Vector(result.items, bits)) break :blk whereFilledIntRange(i16, result.items);
                break :blk fillWhereBitVectorIndices(i16, result.items, bits);
            } else blk: {
                if (fillWhereBitVectorRejectIndicesI16Vector(result.items, bits)) break :blk whereFilledIntRange(i16, result.items);
                break :blk fillWhereBitVectorRejectIndices(i16, result.items, bits);
            },
            .int32 => |*result| if (want_true) blk: {
                if (fillWhereBitVectorIndicesI32Vector(result.items, bits)) break :blk whereFilledIntRange(i32, result.items);
                break :blk fillWhereBitVectorIndices(i32, result.items, bits);
            } else blk: {
                if (fillWhereBitVectorRejectIndicesI32Vector(result.items, bits)) break :blk whereFilledIntRange(i32, result.items);
                break :blk fillWhereBitVectorRejectIndices(i32, result.items, bits);
            },
            .int64 => |*result| if (want_true)
                fillWhereBitVectorIndices(i64, result.items, bits)
            else
                fillWhereBitVectorRejectIndices(i64, result.items, bits),
        };
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, if (count <= 1)
            host_dense_flag_normalized | host_dense_flag_asc | host_dense_flag_dsc
        else
            host_dense_flag_normalized | host_dense_flag_asc);
        hostDenseSetCachedIntRange(host, range);
        return value;
    }

    fn sortedBitBoundaryAsc(bits: HostBitSlice) usize {
        var lo: usize = 0;
        var hi: usize = bits.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (!bitGet(bits.words, mid)) lo = mid + 1 else hi = mid;
        }
        return lo;
    }

    fn sortedBitBoundaryDsc(bits: HostBitSlice) usize {
        var lo: usize = 0;
        var hi: usize = bits.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (bitGet(bits.words, mid)) lo = mid + 1 else hi = mid;
        }
        return lo;
    }

    fn groupSortedBitVectorValue(self: *Session, bits: HostBitSlice, flags: u8) KError!?Value {
        const mono = monotonicFlags(flags);
        if (mono == 0) return null;

        var key_buf: [2]i64 = undefined;
        var values_buf: [2]Value = undefined;
        var group_count: usize = 0;
        defer {
            for (values_buf[0..group_count]) |group_value| self.releaseValue(group_value);
        }

        const appendGroup = struct {
            fn append(
                session: *Session,
                keys: *[2]i64,
                values: *[2]Value,
                count: *usize,
                key: i64,
                len: usize,
                start: usize,
            ) KError!void {
                if (len == 0) return;
                keys[count.*] = key;
                values[count.*] = try newRangeIotaValueWithParams(session, .managed, len, @intCast(start), 1);
                count.* += 1;
            }
        }.append;

        if ((mono & host_dense_flag_asc) != 0) {
            const first_true = sortedBitBoundaryAsc(bits);
            const false_count = first_true;
            const true_count = bits.len - first_true;
            try appendGroup(self, &key_buf, &values_buf, &group_count, 0, false_count, 0);
            try appendGroup(self, &key_buf, &values_buf, &group_count, 1, true_count, false_count);
        } else {
            const first_false = sortedBitBoundaryDsc(bits);
            const true_count = first_false;
            const false_count = bits.len - first_false;
            try appendGroup(self, &key_buf, &values_buf, &group_count, 1, true_count, 0);
            try appendGroup(self, &key_buf, &values_buf, &group_count, 0, false_count, true_count);
        }

        const keys_value = try self.createManagedHostIntArray(key_buf[0..group_count]);
        defer self.releaseValue(keys_value);
        return try self.createGroupDictValueFromIndexValues(keys_value, values_buf[0..group_count]);
    }

    fn groupBitVectorValue(self: *Session, value: Value, bits: HostBitSlice, flags: u8) KError!Value {
        if (bits.len == 0) return try self.createEmptyGroupDictValue(value);

        if (try self.groupSortedBitVectorValue(bits, flags)) |result| return result;
        const true_count = bitCountTrue(bits);
        const false_count = bits.len - true_count;

        var key_buf: [2]i64 = undefined;
        var values_buf: [2]Value = undefined;
        var group_count: usize = 0;
        defer {
            for (values_buf[0..group_count]) |group_value| self.releaseValue(group_value);
        }

        const appendGroup = struct {
            fn append(
                session: *Session,
                bits_arg: HostBitSlice,
                keys: *[2]i64,
                values: *[2]Value,
                count: *usize,
                key: i64,
                want_true: bool,
                selected_count: usize,
            ) KError!void {
                if (selected_count == 0) return;
                keys[count.*] = key;
                values[count.*] = try session.groupBitIndexValue(bits_arg, want_true, selected_count);
                count.* += 1;
            }
        }.append;

        if (bitGet(bits.words, 0)) {
            try appendGroup(self, bits, &key_buf, &values_buf, &group_count, 1, true, true_count);
            try appendGroup(self, bits, &key_buf, &values_buf, &group_count, 0, false, false_count);
        } else {
            try appendGroup(self, bits, &key_buf, &values_buf, &group_count, 0, false, false_count);
            try appendGroup(self, bits, &key_buf, &values_buf, &group_count, 1, true, true_count);
        }

        const keys_value = try self.createManagedHostIntArray(key_buf[0..group_count]);
        defer self.releaseValue(keys_value);
        return try self.createGroupDictValueFromIndexValues(keys_value, values_buf[0..group_count]);
    }

    fn floatGroupHashKey(value: f64) u64 {
        if (std.math.isNan(value)) return 0x7ff8_0000_0000_0000;
        return @as(u64, @bitCast(value));
    }

    fn floatGroupEqual(left: f64, right: f64) bool {
        if (std.math.isNan(left) and std.math.isNan(right)) return true;
        return @as(u64, @bitCast(left)) == @as(u64, @bitCast(right));
    }

    fn valueGroupEqual(self: *Session, left: Value, right: Value) KError!bool {
        if (tableScalarValue(left)) |scalar| {
            if (scalar.is_null) return tableScalarValue(right) != null and valueAsHostTableScalar(right).is_null and scalar.kind == valueAsHostTableScalar(right).kind;
            return try self.valueGroupEqual(scalar.value, right);
        }
        if (tableScalarValue(right)) |scalar| {
            if (scalar.is_null) return false;
            return try self.valueGroupEqual(left, scalar.value);
        }

        if (left.tag() == .array and right.tag() == .array) {
            if (try self.numericArrayGroupEqual(left, right)) |matched| return matched;
            if (try self.derivedSequenceGroupEqual(left, right)) |matched| return matched;
        }

        if (left.tag() != right.tag()) {
            const lhs = scalarIntLikeValue(left) orelse return false;
            const rhs = scalarIntLikeValue(right) orelse return false;
            return lhs == rhs;
        }

        return switch (left.tag()) {
            .int => left.asInt() == right.asInt(),
            .float32 => floatGroupEqual(left.asFloat(), right.asFloat()),
            .float => floatGroupEqual(left.asFloat(), right.asFloat()),
            .bool => left.asBool() == right.asBool(),
            .builtin => left.asBuiltin() == right.asBuiltin(),
            .closure => left.asClosure() == right.asClosure(),
            .array => switch (left.arrayKind()) {
                .host_table_scalar => blk: {
                    if (right.arrayKind() != .host_table_scalar) break :blk false;
                    const lhs = valueAsHostTableScalar(left);
                    const rhs = valueAsHostTableScalar(right);
                    if (lhs.kind != rhs.kind or lhs.is_null != rhs.is_null) break :blk false;
                    if (lhs.is_null) break :blk true;
                    break :blk try self.valueGroupEqual(lhs.value, rhs.value);
                },
                .host_string, .host_string_view => if (stringBytes(right)) |right_text|
                    std.mem.eql(u8, stringBytes(left).?, right_text)
                else
                    false,
                .host_symbol => right.arrayKind() == .host_symbol and std.mem.eql(u8, hostTextBytes(left.asHostSymbol()), hostTextBytes(right.asHostSymbol())),
                .host_boxed_array => blk: {
                    if (right.arrayKind() != .host_boxed_array) break :blk false;
                    const left_items = left.asHostBoxedArray().items;
                    const right_items = right.asHostBoxedArray().items;
                    if (left_items.len != right_items.len) break :blk false;
                    for (left_items, right_items) |left_item, right_item| {
                        if (!try self.valueGroupEqual(left_item, right_item)) break :blk false;
                    }
                    break :blk true;
                },
                .host_string_list => blk: {
                    if (right.arrayKind() != .host_string_list) break :blk false;
                    const left_list = left.asHostStringList();
                    const right_list = right.asHostStringList();
                    if (left_list.len != right_list.len) break :blk false;
                    for (0..left_list.len) |idx| {
                        const left_item = try self.hostStringListItemValue(left_list, idx);
                        const right_item = try self.hostStringListItemValue(right_list, idx);
                        defer self.releaseValue(left_item);
                        defer self.releaseValue(right_item);
                        if (!try self.valueGroupEqual(left_item, right_item)) break :blk false;
                    }
                    break :blk true;
                },
                .host_symbol_list => blk: {
                    if (right.arrayKind() != .host_symbol_list) break :blk false;
                    const left_list = left.asHostStringList();
                    const right_list = right.asHostStringList();
                    if (left_list.len != right_list.len) break :blk false;
                    for (0..left_list.len) |idx| {
                        const left_item = try hostStringListItemBytes(left_list, idx);
                        const right_item = try hostStringListItemBytes(right_list, idx);
                        if (!std.mem.eql(u8, left_item, right_item)) break :blk false;
                    }
                    break :blk true;
                },
                .numeric_array => blk: {
                    switch (right.arrayKind()) {
                        .numeric_array => {},
                        else => break :blk false,
                    }
                    const lhs = try numericHostArrayValue(self, left);
                    const rhs = try numericHostArrayValue(self, right);
                    if (lhs.len() != rhs.len()) break :blk false;
                    var lhs_dims_buf: [numeric_array_max_rank]i32 = @as([numeric_array_max_rank]i32, @splat(0));
                    var rhs_dims_buf: [numeric_array_max_rank]i32 = @as([numeric_array_max_rank]i32, @splat(0));
                    if (!std.mem.eql(i32, numericValueShapeDims(left, lhs, &lhs_dims_buf), numericValueShapeDims(right, rhs, &rhs_dims_buf))) break :blk false;
                    for (0..lhs.len()) |idx| {
                        const left_item = try self.hostDenseIndexScalar(left, lhs, @intCast(idx));
                        const right_item = try self.hostDenseIndexScalar(right, rhs, @intCast(idx));
                        defer self.releaseValue(left_item);
                        defer self.releaseValue(right_item);
                        if (!try self.valueGroupEqual(left_item, right_item)) break :blk false;
                    }
                    break :blk true;
                },
                .host_keyed_store => blk: {
                    if (right.arrayKind() != .host_keyed_store) break :blk false;
                    const lhs = left.asHostKeyedStore();
                    const rhs = right.asHostKeyedStore();
                    if (lhs.layout != rhs.layout or lhs.row_count != rhs.row_count) break :blk false;
                    const count = keyedStoreNameCount(lhs);
                    if (count != keyedStoreNameCount(rhs)) break :blk false;
                    for (0..count) |idx| {
                        const left_name = try self.keyedStoreNameValue(lhs, idx);
                        const right_name = try self.keyedStoreNameValue(rhs, idx);
                        defer self.releaseValue(left_name);
                        defer self.releaseValue(right_name);
                        if (!try self.valueGroupEqual(left_name, right_name)) break :blk false;
                        const left_value = try self.keyedStoreValueAt(lhs, idx);
                        const right_value = try self.keyedStoreValueAt(rhs, idx);
                        defer self.releaseValue(left_value);
                        defer self.releaseValue(right_value);
                        if (!try self.valueGroupEqual(left_value, right_value)) break :blk false;
                    }
                    break :blk true;
                },
                .host_handle, .host_relation => false,
                else => false,
            },
        };
    }

    fn numericArrayGroupEqual(self: *Session, left: Value, right: Value) KError!?bool {
        if (left.tag() != .array or right.tag() != .array) return null;
        const left_mode = valueNumericMode(left) orelse return null;
        const right_mode = valueNumericMode(right) orelse return null;
        if (left_mode != right_mode) return false;

        const left_shape = valueNumericBuilderShape(left) orelse return false;
        const right_shape = valueNumericBuilderShape(right) orelse return false;
        if (!numericShapeSnapshotEqual(left_shape, right_shape)) return false;

        const len = try numericShapeSnapshotElementCount(left_shape);
        const right_len = try numericShapeSnapshotElementCount(right_shape);
        if (len != right_len) return false;

        switch (left_mode) {
            .int => for (0..len) |idx| {
                if (try numericIntAt(left, idx) != try numericIntAt(right, idx)) return false;
            },
            .float => for (0..len) |idx| {
                if (!floatGroupEqual(try numericFloatAt(left, idx), try numericFloatAt(right, idx))) return false;
            },
        }
        _ = self;
        return true;
    }

    fn derivedSequenceGroupEqual(self: *Session, left: Value, right: Value) KError!?bool {
        const left_len = derivedSequenceLen(left) orelse return null;
        const right_len = derivedSequenceLen(right) orelse return null;
        if (left_len != right_len) return false;
        for (0..left_len) |idx| {
            const left_item = try self.derivedSequenceItemValue(left, idx);
            defer self.releaseValue(left_item);
            const right_item = try self.derivedSequenceItemValue(right, idx);
            defer self.releaseValue(right_item);
            if (!try self.valueGroupEqual(left_item, right_item)) return false;
        }
        return true;
    }

    fn groupStringValue(self: *Session, value: Value, bytes: []const u8) KError!Value {
        if (bytes.len == 0) return try self.createEmptyGroupDictValue(value);

        var counts = std.ArrayList(usize).empty;
        defer counts.deinit(self.allocator);
        var unique_bytes = std.ArrayList(u8).empty;
        defer unique_bytes.deinit(self.allocator);
        try counts.ensureTotalCapacity(self.allocator, @min(bytes.len, 256));
        try unique_bytes.ensureTotalCapacity(self.allocator, @min(bytes.len, 256));

        var byte_counts = @as([256]usize, @splat(0));
        var byte_groups = @as([256]usize, @splat(0));
        const groups = try self.allocator.alloc(usize, bytes.len);
        defer self.allocator.free(groups);

        for (bytes, 0..) |byte, idx| {
            if (byte_counts[byte] == 0) {
                byte_groups[byte] = unique_bytes.items.len;
                try unique_bytes.append(self.allocator, byte);
                try counts.append(self.allocator, 0);
            }
            const group_idx = byte_groups[byte];
            counts.items[group_idx] += 1;
            groups[idx] = group_idx;
            byte_counts[byte] += 1;
        }

        const keys_value = try self.managedHostString(unique_bytes.items);
        defer self.releaseValue(keys_value);
        return try self.createGroupDictValue(keys_value, counts.items, groups);
    }

    fn appendSortedIntGroupRun(self: *Session, key: i64, count: usize, keys: *std.ArrayList(i64), counts: *std.ArrayList(usize)) KError!void {
        try keys.append(self.allocator, key);
        try counts.append(self.allocator, count);
    }

    fn hostIntViewLowerBoundAsc(view: HostIntArrayView, len: usize, key: i64) usize {
        var lo: usize = 0;
        var hi: usize = len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (hostIntViewItem(view, mid) < key) lo = mid + 1 else hi = mid;
        }
        return lo;
    }

    fn hostIntViewUpperBoundAsc(view: HostIntArrayView, len: usize, key: i64) usize {
        var lo: usize = 0;
        var hi: usize = len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (hostIntViewItem(view, mid) <= key) lo = mid + 1 else hi = mid;
        }
        return lo;
    }

    fn hostIntViewLowerBoundDsc(view: HostIntArrayView, len: usize, key: i64) usize {
        var lo: usize = 0;
        var hi: usize = len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (hostIntViewItem(view, mid) > key) lo = mid + 1 else hi = mid;
        }
        return lo;
    }

    fn hostIntViewUpperBoundDsc(view: HostIntArrayView, len: usize, key: i64) usize {
        var lo: usize = 0;
        var hi: usize = len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (hostIntViewItem(view, mid) >= key) lo = mid + 1 else hi = mid;
        }
        return lo;
    }

    fn smallSortedGroupSpan(range: HostIntRange, len: usize) ?usize {
        const span_i128 = @as(i128, range.max) - @as(i128, range.min) + 1;
        if (span_i128 <= 0) return null;
        const span = std.math.cast(usize, span_i128) orelse return null;
        if (span > group_int_table_max_span) return null;
        if (span > @max(@as(usize, 256), len / 64)) return null;
        return span;
    }

    fn groupSortedSmallRangeIntVectorValue(self: *Session, value: Value, array: *const HostDenseArray, view: HostIntArrayView, len: usize) KError!?Value {
        if (len == 0) return try self.createEmptyGroupDictValue(value);
        const mono = monotonicFlags(array.flags);
        if (mono == 0) return null;
        const range = intRangeForGroupTable(array, view) orelse return null;
        const span = smallSortedGroupSpan(range, len) orelse return null;
        const asc = (mono & host_dense_flag_asc) != 0;

        var keys = std.ArrayList(i64).empty;
        defer keys.deinit(self.allocator);
        var values = std.ArrayList(Value).empty;
        defer {
            for (values.items) |group_value| self.releaseValue(group_value);
            values.deinit(self.allocator);
        }
        try keys.ensureTotalCapacity(self.allocator, span);
        try values.ensureTotalCapacity(self.allocator, span);

        for (0..span) |offset| {
            const offset_i64 = std.math.cast(i64, offset) orelse return error.Unsupported;
            const key = if (asc) range.min + offset_i64 else range.max - offset_i64;
            const start = if (asc)
                hostIntViewLowerBoundAsc(view, len, key)
            else
                hostIntViewLowerBoundDsc(view, len, key);
            if (start >= len or hostIntViewItem(view, start) != key) continue;
            const end = if (asc)
                hostIntViewUpperBoundAsc(view, len, key)
            else
                hostIntViewUpperBoundDsc(view, len, key);
            if (end <= start) continue;
            try keys.append(self.allocator, key);
            const group_value = try newRangeIotaValueWithParams(self, .managed, end - start, @intCast(start), 1);
            errdefer self.releaseValue(group_value);
            try values.append(self.allocator, group_value);
        }

        const keys_value = try self.createManagedHostIntArray(keys.items);
        defer self.releaseValue(keys_value);
        return try self.createGroupDictValueFromIndexValues(keys_value, values.items);
    }

    fn groupSortedIntVectorValue(self: *Session, value: Value, array: *const HostDenseArray, view: HostIntArrayView, len: usize) KError!?Value {
        if (len == 0) return try self.createEmptyGroupDictValue(value);

        var keys = std.ArrayList(i64).empty;
        defer keys.deinit(self.allocator);
        var counts = std.ArrayList(usize).empty;
        defer counts.deinit(self.allocator);

        try keys.ensureTotalCapacity(self.allocator, @min(len, 1024));
        try counts.ensureTotalCapacity(self.allocator, @min(len, 1024));

        const trusted_mono = monotonicFlags(array.flags);
        const check_order = trusted_mono == 0;
        var asc = check_order or (trusted_mono & host_dense_flag_asc) != 0;
        var dsc = check_order or (trusted_mono & host_dense_flag_dsc) != 0;
        var run_start: usize = 0;
        var current = hostIntViewItem(view, 0);
        var prior = current;
        var idx: usize = 1;
        while (idx < len) : (idx += 1) {
            const item = hostIntViewItem(view, idx);
            if (check_order) {
                if (prior > item) asc = false;
                if (prior < item) dsc = false;
                if (!asc and !dsc) return null;
                prior = item;
            }
            if (item == current) continue;
            try self.appendSortedIntGroupRun(current, idx - run_start, &keys, &counts);
            run_start = idx;
            current = item;
        }
        try self.appendSortedIntGroupRun(current, len - run_start, &keys, &counts);

        var values = std.ArrayList(Value).empty;
        defer {
            for (values.items) |group_value| self.releaseValue(group_value);
            values.deinit(self.allocator);
        }
        try values.ensureTotalCapacity(self.allocator, counts.items.len);
        var start: usize = 0;
        for (counts.items) |count| {
            const group_value = try newRangeIotaValueWithParams(self, .managed, count, @intCast(start), 1);
            errdefer self.releaseValue(group_value);
            try values.append(self.allocator, group_value);
            start += count;
        }

        const keys_value = try self.createManagedHostIntArray(keys.items);
        defer self.releaseValue(keys_value);
        return try self.createGroupDictValueFromIndexValues(keys_value, values.items);
    }

    const group_int_table_max_span: usize = 65536;
    const group_int_table_dense_factor: usize = 8;

    fn smallRangeGroupSpan(range: HostIntRange, len: usize) ?usize {
        const span_i128 = @as(i128, range.max) - @as(i128, range.min) + 1;
        if (span_i128 <= 0) return null;
        const span = std.math.cast(usize, span_i128) orelse return null;
        if (span > group_int_table_max_span) return null;
        const dense_limit = @max(@as(usize, 256), std.math.mul(usize, len, group_int_table_dense_factor) catch std.math.maxInt(usize));
        if (span > dense_limit) return null;
        return span;
    }

    fn intRangeForGroupTable(array: *const HostDenseArray, view: HostIntArrayView) ?HostIntRange {
        return hostDenseCachedIntRange(array) orelse
            hostIntArrayViewEndpointRange(view, array.flags) orelse
            hostIntArrayViewStorageRange(view);
    }

    fn groupSmallRangeIntItemsValue(
        self: *Session,
        range: HostIntRange,
        comptime T: type,
        items: []const T,
        len: usize,
    ) KError!?Value {
        const span = smallRangeGroupSpan(range, len) orelse return null;
        const use_direct_index_outputs = span <= 64 or len <= 65536;
        const range_min_i128 = @as(i128, range.min);

        const empty_slot = std.math.maxInt(usize);
        var slots = try self.allocator.alloc(usize, span);
        defer self.allocator.free(slots);
        @memset(slots, empty_slot);

        var keys = std.ArrayList(i64).empty;
        defer keys.deinit(self.allocator);
        var counts = std.ArrayList(usize).empty;
        defer counts.deinit(self.allocator);
        try keys.ensureTotalCapacity(self.allocator, @min(len, span));
        try counts.ensureTotalCapacity(self.allocator, @min(len, span));

        const grouped_indices = if (use_direct_index_outputs) null else try self.allocator.alloc(usize, len);
        defer if (grouped_indices) |group_items| self.allocator.free(group_items);

        for (items[0..len], 0..) |item_raw, idx| {
            const item: i64 = @intCast(item_raw);
            const offset_i128 = @as(i128, item) - range_min_i128;
            if (offset_i128 < 0) return null;
            const offset = std.math.cast(usize, offset_i128) orelse return null;
            if (offset >= span) return null;

            const group_idx = if (slots[offset] != empty_slot)
                slots[offset]
            else blk: {
                const new_idx = keys.items.len;
                slots[offset] = new_idx;
                try keys.append(self.allocator, item);
                try counts.append(self.allocator, 0);
                break :blk new_idx;
            };
            counts.items[group_idx] += 1;
            if (grouped_indices) |group_items| group_items[idx] = group_idx;
        }

        const group_count = counts.items.len;
        if (grouped_indices) |groups| {
            const keys_value = try self.createManagedHostIntArray(keys.items);
            defer self.releaseValue(keys_value);
            return try self.createGroupDictValue(keys_value, counts.items, groups);
        }
        const max_index: i64 = std.math.cast(i64, len - 1) orelse return error.Unsupported;
        const index_kind = hostIntStorageKindForRange(0, max_index);
        const values = try self.allocator.alloc(Value, group_count);
        defer self.allocator.free(values);
        const outputs = try self.allocator.alloc(HostIntResult, group_count);
        defer self.allocator.free(outputs);
        try self.createGroupIndexOutputValues(counts.items, index_kind, values, outputs);
        defer {
            for (values) |group_value| self.releaseValue(group_value);
        }

        const cursors = try self.allocator.alloc(usize, group_count);
        defer self.allocator.free(cursors);
        @memset(cursors, 0);

        switch (index_kind) {
            .bit => unreachable,
            .int8 => for (items[0..len], 0..) |item_raw, idx| {
                const item: i64 = @intCast(item_raw);
                const offset = std.math.cast(usize, @as(i128, item) - range_min_i128) orelse return error.Internal;
                const group_idx = slots[offset];
                const cursor = cursors[group_idx];
                outputs[group_idx].int8.items[cursor] = @intCast(idx);
                cursors[group_idx] = cursor + 1;
            },
            .int16 => for (items[0..len], 0..) |item_raw, idx| {
                const item: i64 = @intCast(item_raw);
                const offset = std.math.cast(usize, @as(i128, item) - range_min_i128) orelse return error.Internal;
                const group_idx = slots[offset];
                const cursor = cursors[group_idx];
                outputs[group_idx].int16.items[cursor] = @intCast(idx);
                cursors[group_idx] = cursor + 1;
            },
            .int32 => for (items[0..len], 0..) |item_raw, idx| {
                const item: i64 = @intCast(item_raw);
                const offset = std.math.cast(usize, @as(i128, item) - range_min_i128) orelse return error.Internal;
                const group_idx = slots[offset];
                const cursor = cursors[group_idx];
                outputs[group_idx].int32.items[cursor] = @intCast(idx);
                cursors[group_idx] = cursor + 1;
            },
            .int64 => for (items[0..len], 0..) |item_raw, idx| {
                const item: i64 = @intCast(item_raw);
                const offset = std.math.cast(usize, @as(i128, item) - range_min_i128) orelse return error.Internal;
                const group_idx = slots[offset];
                const cursor = cursors[group_idx];
                outputs[group_idx].int64.items[cursor] = @intCast(idx);
                cursors[group_idx] = cursor + 1;
            },
        }
        for (counts.items, cursors) |count, cursor| {
            if (count != cursor) return error.Internal;
        }
        for (values, outputs, counts.items) |group_value, *output, count| {
            try self.setGroupIndexResultMetadata(group_value, output, count);
        }

        const keys_value = try self.createManagedHostIntArray(keys.items);
        defer self.releaseValue(keys_value);
        return try self.createGroupDictValueFromIndexValues(keys_value, values);
    }

    fn groupSmallRangeIntVectorValue(self: *Session, value: Value, array: *const HostDenseArray, view: HostIntArrayView, len: usize) KError!?Value {
        if (len == 0) return try self.createEmptyGroupDictValue(value);
        const range = intRangeForGroupTable(array, view) orelse return null;
        return switch (view) {
            .bit => null,
            .int8 => |items| try self.groupSmallRangeIntItemsValue(range, i8, items, len),
            .int16 => |items| try self.groupSmallRangeIntItemsValue(range, i16, items, len),
            .int32 => |items| try self.groupSmallRangeIntItemsValue(range, i32, items, len),
            .int64 => |items| try self.groupSmallRangeIntItemsValue(range, i64, items, len),
        };
    }

    fn tryFastHostIntVectorGroupValue(self: *Session, value: Value, len: usize) KError!?Value {
        const array = hostDenseIfPresent(value) orelse return null;
        const view = hostIntArrayView(array) orelse return null;
        if (hostIntArrayViewLen(view) != len) return error.Type;

        switch (view) {
            .bit => |bits| return try self.groupBitVectorValue(value, bits, array.flags),
            else => {},
        }
        if (try self.groupSortedSmallRangeIntVectorValue(value, array, view, len)) |result| return result;
        if (try self.groupSortedIntVectorValue(value, array, view, len)) |result| return result;
        if (try self.groupSmallRangeIntVectorValue(value, array, view, len)) |result| return result;
        return null;
    }

    fn groupNumericIntVectorValue(self: *Session, value: Value, len: usize) KError!Value {
        if (len == 0) return try self.createEmptyGroupDictValue(value);
        if (try self.tryFastHostIntVectorGroupValue(value, len)) |result| return result;

        var lookup = std.AutoHashMap(i64, usize).init(self.allocator);
        defer lookup.deinit();
        try lookup.ensureTotalCapacity(std.math.cast(u32, len) orelse return error.Unsupported);

        var keys = std.ArrayList(i64).empty;
        defer keys.deinit(self.allocator);
        var counts = std.ArrayList(usize).empty;
        defer counts.deinit(self.allocator);
        try keys.ensureTotalCapacity(self.allocator, len);
        try counts.ensureTotalCapacity(self.allocator, len);

        const groups = try self.allocator.alloc(usize, len);
        defer self.allocator.free(groups);

        for (0..len) |idx| {
            const item = try numericIntAt(value, idx);
            const group_idx = lookup.get(item) orelse blk: {
                const new_idx = keys.items.len;
                try lookup.put(item, new_idx);
                try keys.append(self.allocator, item);
                try counts.append(self.allocator, 0);
                break :blk new_idx;
            };
            counts.items[group_idx] += 1;
            groups[idx] = group_idx;
        }

        const keys_value = try self.createManagedHostIntArray(keys.items);
        defer self.releaseValue(keys_value);
        return try self.createGroupDictValue(keys_value, counts.items, groups);
    }

    fn groupNumericFloatVectorValue(self: *Session, value: Value, len: usize) KError!Value {
        if (len == 0) return try self.createEmptyGroupDictValue(value);

        var lookup = std.AutoHashMap(u64, usize).init(self.allocator);
        defer lookup.deinit();
        try lookup.ensureTotalCapacity(std.math.cast(u32, len) orelse return error.Unsupported);

        var keys = std.ArrayList(f64).empty;
        defer keys.deinit(self.allocator);
        var counts = std.ArrayList(usize).empty;
        defer counts.deinit(self.allocator);
        try keys.ensureTotalCapacity(self.allocator, len);
        try counts.ensureTotalCapacity(self.allocator, len);

        const groups = try self.allocator.alloc(usize, len);
        defer self.allocator.free(groups);

        for (0..len) |idx| {
            const item = try numericFloatAt(value, idx);
            const key = floatGroupHashKey(item);
            const group_idx = lookup.get(key) orelse blk: {
                const new_idx = keys.items.len;
                try lookup.put(key, new_idx);
                try keys.append(self.allocator, item);
                try counts.append(self.allocator, 0);
                break :blk new_idx;
            };
            counts.items[group_idx] += 1;
            groups[idx] = group_idx;
        }

        const keys_value = try self.createManagedHostFloatArray(keys.items);
        defer self.releaseValue(keys_value);
        return try self.createGroupDictValue(keys_value, counts.items, groups);
    }

    fn groupSequenceItemsValue(self: *Session, key_source: Value, items: []const Value) KError!Value {
        if (items.len == 0) return try self.createEmptyGroupDictValue(key_source);

        var keys = std.ArrayList(Value).empty;
        defer {
            for (keys.items) |value| self.releaseValue(value);
            keys.deinit(self.allocator);
        }
        var counts = std.ArrayList(usize).empty;
        defer counts.deinit(self.allocator);
        try keys.ensureTotalCapacity(self.allocator, items.len);
        try counts.ensureTotalCapacity(self.allocator, items.len);

        const groups = try self.allocator.alloc(usize, items.len);
        defer self.allocator.free(groups);

        for (items, 0..) |item, item_idx| {
            var group_idx: ?usize = null;
            for (keys.items, 0..) |candidate, candidate_idx| {
                if (try self.valueGroupEqual(candidate, item)) {
                    group_idx = candidate_idx;
                    break;
                }
            }
            const resolved = group_idx orelse blk: {
                const new_idx = keys.items.len;
                try keys.append(self.allocator, try self.retainEscapedValue(item));
                try counts.append(self.allocator, 0);
                break :blk new_idx;
            };
            counts.items[resolved] += 1;
            groups[item_idx] = resolved;
        }

        const keys_value = try self.createKeyArrayFromValues(keys.items);
        defer self.releaseValue(keys_value);
        return try self.createGroupDictValue(keys_value, counts.items, groups);
    }

    fn createGroupedOriginalKeyValues(
        self: *Session,
        original_keys: []const Value,
        counts: []const usize,
        groups: []const usize,
    ) KError!Value {
        if (counts.len == 0) return try self.createEmptyGroupValues();

        var values = try self.allocator.alloc(Value, counts.len);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |value| self.releaseValue(value);
        }

        for (counts, 0..) |count, group_idx| {
            var group_keys = try self.allocator.alloc(Value, count);
            defer self.allocator.free(group_keys);
            var used: usize = 0;
            for (groups, 0..) |candidate_group, item_idx| {
                if (candidate_group == group_idx) {
                    group_keys[used] = original_keys[item_idx];
                    used += 1;
                }
            }
            if (used != count) return error.Internal;
            values[group_idx] = try self.createKeyArrayFromValues(group_keys);
            initialized += 1;
        }

        return try self.createManagedHostBoxedArray(values);
    }

    fn groupDictValue(self: *Session, store: *const HostKeyedStore) KError!Value {
        const len = keyedStoreNameCount(store);
        if (len == 0) return try self.createEmptyGroupDictValue(store.values);

        var original_keys = try self.allocator.alloc(Value, len);
        defer self.allocator.free(original_keys);
        var values = try self.allocator.alloc(Value, len);
        defer self.allocator.free(values);
        var keys_initialized: usize = 0;
        var values_initialized: usize = 0;
        defer {
            for (original_keys[0..keys_initialized]) |value| self.releaseValue(value);
            for (values[0..values_initialized]) |value| self.releaseValue(value);
        }

        for (0..len) |idx| {
            original_keys[idx] = try self.keyedStoreNameValue(store, idx);
            keys_initialized += 1;
            values[idx] = try self.keyedStoreValueAt(store, idx);
            values_initialized += 1;
        }

        var grouped_keys = std.ArrayList(Value).empty;
        defer {
            for (grouped_keys.items) |value| self.releaseValue(value);
            grouped_keys.deinit(self.allocator);
        }
        var counts = std.ArrayList(usize).empty;
        defer counts.deinit(self.allocator);
        try grouped_keys.ensureTotalCapacity(self.allocator, len);
        try counts.ensureTotalCapacity(self.allocator, len);

        const groups = try self.allocator.alloc(usize, len);
        defer self.allocator.free(groups);

        for (values, 0..) |item, item_idx| {
            var group_idx: ?usize = null;
            for (grouped_keys.items, 0..) |candidate, candidate_idx| {
                if (try self.valueGroupEqual(candidate, item)) {
                    group_idx = candidate_idx;
                    break;
                }
            }
            const resolved = group_idx orelse blk: {
                const new_idx = grouped_keys.items.len;
                try grouped_keys.append(self.allocator, try self.retainEscapedValue(item));
                try counts.append(self.allocator, 0);
                break :blk new_idx;
            };
            counts.items[resolved] += 1;
            groups[item_idx] = resolved;
        }

        const keys_value = try self.createKeyArrayFromValues(grouped_keys.items);
        defer self.releaseValue(keys_value);
        const values_value = try self.createGroupedOriginalKeyValues(original_keys, counts.items, groups);
        defer self.releaseValue(values_value);
        if (stringSourceInfo(keys_value) != null) return try self.createHostDictValueFromCharStringKeys("", keys_value, values_value);
        return try self.createHostDictValueFromKeySequenceValue("", keys_value, values_value);
    }

    fn groupValue(self: *Session, value: Value) KError!Value {
        if (stringBytes(value)) |bytes| return try self.groupStringValue(value, bytes);

        if (value.tag() == .array and value.arrayKind() == .host_keyed_store) {
            const store = value.asHostKeyedStore();
            if (store.layout == .dict) return try self.groupDictValue(store);
        }

        if (valueNumericMode(value)) |mode| {
            if (valueNonVectorNumericShape(value) == null) {
                const len = numericFlatLen(value) orelse return error.Type;
                return switch (mode) {
                    .int => try self.groupNumericIntVectorValue(value, len),
                    .float => try self.groupNumericFloatVectorValue(value, len),
                };
            }
        }

        const items = try self.materializeTopLevelItems(value);
        defer {
            for (items) |item| self.releaseValue(item);
            self.allocator.free(items);
        }
        return try self.groupSequenceItemsValue(value, items);
    }

    fn unitMatrixValue(self: *Session, value: Value) KError!Value {
        const count_i64 = scalarIntLikeValue(value) orelse return error.Type;
        if (count_i64 < 0) return error.Type;
        const count: usize = @intCast(count_i64);
        const len = std.math.mul(usize, count, count) catch return error.Unsupported;

        var out = std.ArrayList(i64).empty;
        defer out.deinit(self.allocator);
        try out.ensureTotalCapacity(self.allocator, len);

        for (0..count) |row| {
            for (0..count) |col| try out.append(self.allocator, if (row == col) 1 else 0);
        }

        const matrix = try self.createManagedHostIntArray(out.items);
        return try self.setNumericMatrixShapeOnValue(matrix, count, count);
    }

    fn iotaValue(self: *Session, value: Value) KError!Value {
        if (scalarIntLikeValue(value)) |count_value| {
            if (count_value < 0) {
                const count = std.math.cast(usize, -@as(i128, count_value)) orelse return error.Unsupported;
                return try newRangeIotaValueWithParams(self, .managed, count, count_value, 1);
            }
            const count: usize = @intCast(count_value);
            return try newRangeIotaValue(self, .managed, count);
        }
        if (try self.namespaceKeysValue(value)) |keys| return keys;
        if (value.tag() == .array and value.arrayKind() == .host_keyed_store) {
            return self.shareValue(value.asHostKeyedStore().names);
        }
        if (valueNumericMode(value) != null and valueNumericMatrixShape(value) == null) {
            const array = try numericHostArrayValue(self, value);
            return switch (array.storage) {
                .bit => try self.iotaBitVectorValue(array),
                .int8, .int16, .int32, .int64 => try self.iotaIntVectorValue(array),
                else => error.Type,
            };
        }
        return error.Type;
    }

    fn reverseValue(self: *Session, value: Value) KError!Value {
        switch (value.tag()) {
            .int, .bool, .float32, .float, .builtin, .closure => return self.shareValue(value),
            .array => {},
        }
        if (value.tag() == .array) switch (value.arrayKind()) {
            .host_string => return try self.reverseHostString(value.asHostString()),
            .host_symbol => return self.shareValue(value),
            .host_string_view => return try self.reverseStringBytes(hostStringViewBytes(value.asHostStringView())),
            .host_string_list => return try self.reverseHostStringList(value.asHostStringList()),
            .host_symbol_list => return try self.reverseHostSymbolList(value.asHostStringList()),
            .host_keyed_store => return try self.reverseKeyedStore(value.asHostKeyedStore()),
            else => {},
        };
        if (valueVectorRangeIotaHandle(value)) |handle| {
            const len = numericArrayRangeLen(handle);
            const start = if (len == 0)
                numericArrayRangeIota(handle).start
            else
                try numericArrayRangeIotaValueAt(handle, len - 1);
            const step = try checkedIntOp(.sub, 0, numericArrayRangeIota(handle).step);
            return try newRangeIotaValueWithParams(self, .managed, len, start, step);
        }
        if (shapedNumericHandle(value)) |handle| {
            const rows: usize = @intCast(handle.shape[0]);
            const start = if (rows == 0) 0 else rows - 1;
            if (try numericValueFirstAxisArithmeticSliceValue(self, value, .{
                .start = start,
                .len = rows,
                .step = -1,
            })) |result| return result;
        }
        if (numericVectorLen(value)) |len| {
            if (try self.reverseNumericVectorViewValue(value, len)) |result| return result;
        }
        if (boxedArrayItems(value)) |items| {
            var out = std.ArrayList(Value).empty;
            defer out.deinit(self.allocator);
            try out.ensureTotalCapacity(self.allocator, items.len);
            var idx = items.len;
            while (idx > 0) {
                idx -= 1;
                try out.append(self.allocator, items[idx]);
            }
            return try self.createManagedHostBoxedArray(out.items);
        }
        const array = try numericHostArrayValue(self, value);
        if (valueNumericMatrixShape(value)) |shape| {
            var row_indices = std.ArrayList(usize).empty;
            defer row_indices.deinit(self.allocator);
            try row_indices.ensureTotalCapacity(self.allocator, shape.rows);
            var idx = shape.rows;
            while (idx > 0) {
                idx -= 1;
                try row_indices.append(self.allocator, idx);
            }
            return try self.createManagedHostNumericMatrixRows(array, row_indices.items, shape.cols);
        }
        return try self.reverseDenseHostVectorValue(value, array);
    }

    fn reverseNumericVectorViewValue(self: *Session, value: Value, len: usize) KError!?Value {
        if (valueNumericMode(value) == null) return null;
        if (hostDenseIfPresent(value)) |array| {
            if (std.meta.activeTag(array.storage) == .bit) return null;
        }
        if (try self.reverseExistingNumericVectorReverseViewValue(value, len)) |source| return source;
        if (len == 0) return try newFlatSliceValue(self, value, 0, 0);

        const reversed_rows = blk: {
            const matrix = try newReshapeViewValue(self, value, numericShapeSnapshotMatrix(len, 1));
            errdefer self.releaseValue(matrix);
            const rows = try newFirstAxisSliceValueWithStep(self, matrix, len - 1, len, -1);
            self.releaseValue(matrix);
            break :blk rows;
        };
        errdefer self.releaseValue(reversed_rows);

        const vector = try newReshapeViewValue(self, reversed_rows, numericShapeSnapshotVector(len));
        self.releaseValue(reversed_rows);
        return vector;
    }

    fn reverseExistingNumericVectorReverseViewValue(self: *Session, value: Value, len: usize) KError!?Value {
        const handle = valueNumericHandle(value) orelse return null;
        if (!numericArrayIsReshapeView(handle) or handle.rank != 1 or @as(usize, @intCast(handle.shape[0])) != len) return null;
        const rows_value = numericArrayReshapeSource(handle) orelse return null;
        const rows_handle = valueNumericHandle(rows_value) orelse return null;
        if (!numericArrayIsFirstAxisSlice(rows_handle) or rows_handle.rank != 2) return null;
        if (@as(usize, @intCast(rows_handle.shape[0])) != len or rows_handle.shape[1] != 1) return null;

        const slice = numericArrayFirstAxisSlicePayload(rows_handle) orelse return null;
        if (slice.step != -1) return null;
        if ((len == 0 and slice.start != 0) or (len != 0 and slice.start != len - 1)) return null;

        const matrix_handle = valueNumericHandle(slice.source) orelse return null;
        if (!numericArrayIsReshapeView(matrix_handle) or matrix_handle.rank != 2) return null;
        if (@as(usize, @intCast(matrix_handle.shape[0])) != len or matrix_handle.shape[1] != 1) return null;
        const source = numericArrayReshapeSource(matrix_handle) orelse return null;
        if ((numericVectorLen(source) orelse return null) != len) return null;
        return self.shareValue(source);
    }

    fn reverseHostSymbolList(self: *Session, list: *const HostStringList) KError!Value {
        const items = try self.allocator.alloc([]const u8, list.len);
        defer self.allocator.free(items);
        var src_idx = list.len;
        for (items) |*item| {
            src_idx -= 1;
            item.* = try hostStringListItemBytes(list, src_idx);
        }
        return try self.createManagedHostSymbolListFromSlices(items);
    }

    fn reverseHostString(self: *Session, text: *const HostText) KError!Value {
        return try self.reverseStringBytes(hostTextBytes(text));
    }

    fn reverseDenseHostVectorValue(self: *Session, value: Value, array: *const HostDenseArray) KError!Value {
        return switch (array.storage) {
            .bit => |words| blk: {
                const out = try self.allocHostBitArray(.managed, array.len());
                bitReverseInto(out.words, .{ .words = words, .len = array.len() });
                break :blk try self.finishManagedHostBitAlloc(out, reversedDenseFlags(array.flags), sourceHostIntRange(value, array));
            },
            .int8 => |items| blk: {
                const out = try self.allocHostArrayTyped(i8, .int8, .managed, items.len);
                reverseTypedSlice(i8, out.items, items);
                const host = out.array;
                hostDenseSetFlags(host, reversedDenseFlags(array.flags));
                hostDenseSetCachedIntRange(host, sourceHostIntRange(value, array));
                break :blk out.value();
            },
            .int16 => |items| blk: {
                const out = try self.allocHostArrayTyped(i16, .int16, .managed, items.len);
                reverseTypedSlice(i16, out.items, items);
                const host = out.array;
                hostDenseSetFlags(host, reversedDenseFlags(array.flags));
                hostDenseSetCachedIntRange(host, sourceHostIntRange(value, array));
                break :blk out.value();
            },
            .int32 => |items| blk: {
                const out = try self.allocHostArrayTyped(i32, .int32, .managed, items.len);
                reverseTypedSlice(i32, out.items, items);
                const host = out.array;
                hostDenseSetFlags(host, reversedDenseFlags(array.flags));
                hostDenseSetCachedIntRange(host, sourceHostIntRange(value, array));
                break :blk out.value();
            },
            .int64 => |items| blk: {
                const out = try self.allocHostArrayTyped(i64, .int64, .managed, items.len);
                reverseTypedSlice(i64, out.items, items);
                const host = out.array;
                hostDenseSetFlags(host, reversedDenseFlags(array.flags));
                hostDenseSetCachedIntRange(host, sourceHostIntRange(value, array));
                break :blk out.value();
            },
            .float32 => |items| blk: {
                const out = try self.allocHostArrayTyped(f32, .float32, .managed, items.len);
                reverseTypedSlice(f32, out.items, items);
                const host = out.array;
                hostDenseSetFlags(host, reversedDenseFlags(array.flags));
                hostDenseCopyFloatBounds(host, array);
                break :blk out.value();
            },
            .float64 => |items| blk: {
                const out = try self.allocHostArrayTyped(f64, .float64, .managed, items.len);
                reverseTypedSlice(f64, out.items, items);
                const host = out.array;
                hostDenseSetFlags(host, reversedDenseFlags(array.flags));
                hostDenseCopyFloatBounds(host, array);
                break :blk out.value();
            },
        };
    }

    fn reverseStringBytes(self: *Session, src: []const u8) KError!Value {
        const buf = try self.allocManagedHostTextBuffer(src.len);
        errdefer self.allocator.free(buf);
        const out = hostTextBytesFromAlloc(buf, src.len);
        var idx: usize = src.len;
        var out_idx: usize = 0;
        while (idx > 0) {
            idx -= 1;
            out[out_idx] = src[idx];
            out_idx += 1;
        }
        const owned = hostTextFromAlloc(buf);
        owned.* = .{
            .header = HeapHeader.init(.host_string, .managed),
            .len = src.len,
        };
        return Value.array(owned);
    }

    fn reverseHostStringList(self: *Session, list: *const HostStringList) KError!Value {
        return switch (list.storage) {
            .eager => |items| blk: {
                const reversed = try self.allocator.alloc(HostStringPiece, items.len);
                defer self.allocator.free(reversed);
                var idx: usize = items.len;
                var out_idx: usize = 0;
                while (idx > 0) {
                    idx -= 1;
                    reversed[out_idx] = items[idx];
                    out_idx += 1;
                }
                break :blk try self.createManagedHostStringListPieces(list.base, reversed);
            },
            .split_scalar => |lazy| blk: {
                const base = list.base orelse unreachable;
                const src = hostTextBytes(base);
                const reversed = try self.allocator.alloc(HostStringPiece, list.len);
                defer self.allocator.free(reversed);
                var piece_idx: usize = list.len;
                var start: usize = 0;
                while (std.mem.indexOfScalarPos(u8, src, start, lazy.sep)) |sep_idx| {
                    piece_idx -= 1;
                    reversed[piece_idx] = .{ .view = .{
                        .start = start,
                        .len = sep_idx - start,
                    } };
                    start = sep_idx + 1;
                }
                piece_idx -= 1;
                reversed[piece_idx] = .{ .view = .{
                    .start = start,
                    .len = src.len - start,
                } };
                break :blk try self.createManagedHostStringListPieces(base, reversed);
            },
        };
    }

    fn notValue(self: *Session, value: Value) KError!Value {
        if (boolLikeValue(value)) |truthy| return Value.fromBool(!truthy);
        if (stringBytes(value)) |bytes| return try self.notStringValue(bytes);
        if (symbolBytes(value)) |bytes| return Value.fromBool(bytes.len == 0);
        if (valueIsGrowlerNullProjection(value)) return Value.fromBool(true);
        if (value.tag() == .array and value.arrayKind() == .host_keyed_store) {
            const store = value.asHostKeyedStore();
            if (store.layout == .dict) return try self.notDictValues(store);
        }
        if (boxedArrayItems(value)) |items| {
            var out = std.ArrayList(Value).empty;
            defer out.deinit(self.allocator);
            try out.ensureTotalCapacity(self.allocator, items.len);
            for (items) |item| try out.append(self.allocator, try self.notValue(item));
            return try self.makeArrayFromValues(out.items);
        }
        switch (value.tag()) {
            .builtin, .closure => return Value.fromBool(false),
            else => {},
        }
        if (hostDenseIfPresent(value)) |array| switch (array.storage) {
            .bit => |words| {
                const source_bits: HostBitSlice = .{
                    .words = hostDenseLogicalBitWords(array, words),
                    .len = array.logical_len,
                };
                const plan = try self.planHostIntUnaryOutput(value, .bit, .bit, array.logical_len, true, true);
                fillBitNotWords(plan.output.bit.words, source_bits);
                const result = try self.finishHostIntOutput(plan, host_dense_flag_normalized | invertMonotonicFlags(array.flags));
                hostDenseSetCachedIntRange(try mutableNumericHostArrayValue(self, result), .{ .min = 0, .max = 1 });
                return result;
            },
            else => {},
        };
        if (valueHostIntStructuralView(value)) |view| {
            const len = hostIntDenseViewLen(view);
            const out = try self.allocHostBitArray(.managed, len);
            var stats = BitSequenceStats{};
            for (0..len) |idx| {
                const item = (try hostIntDenseViewItem(view, idx)) == 0;
                bitSet(out.words, idx, item);
                stats.note(item);
            }
            const metadata = stats.metadata();
            return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
        }
        const array = try numericHostArrayValue(self, value);
        switch (array.storage) {
            .bit => |words| {
                const plan = try self.planHostIntUnaryOutput(value, .bit, .bit, array.len(), true, true);
                fillBitNotWords(plan.output.bit.words, .{ .words = words, .len = array.len() });
                const result = try self.finishHostIntOutput(plan, host_dense_flag_normalized | invertMonotonicFlags(array.flags));
                hostDenseSetCachedIntRange(try mutableNumericHostArrayValue(self, result), .{ .min = 0, .max = 1 });
                return result;
            },
            .float64 => |items| {
                const out = try self.allocHostBitArray(.managed, items.len);
                var stats = BitSequenceStats{};
                for (items, 0..) |item, idx| {
                    const bit = item == 0.0;
                    bitSet(out.words, idx, bit);
                    stats.note(bit);
                }
                const metadata = stats.metadata();
                return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
            },
            else => {
                const view = hostIntArrayView(array).?;
                const len = hostIntArrayViewLen(view);
                const out = try self.allocHostBitArray(.managed, len);
                var stats = BitSequenceStats{};
                for (0..len) |idx| {
                    const bit = hostIntViewItem(view, idx) == 0;
                    bitSet(out.words, idx, bit);
                    stats.note(bit);
                }
                const metadata = stats.metadata();
                return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
            },
        }
    }

    fn notDictValues(self: *Session, store: *const HostKeyedStore) KError!Value {
        const len = keyedStoreValuesValueCount(store.values) orelse return error.Internal;
        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len);

        for (0..len) |idx| {
            const item = try self.keyedStoreValueAt(store, idx);
            errdefer self.releaseValue(item);
            const result = try self.notValue(item);
            self.releaseValue(item);
            try results.append(self.allocator, result);
        }

        const values_value = try self.makeArrayFromValues(results.items);
        defer self.releaseValue(values_value);
        return try self.createDictLikeValue(store, values_value);
    }

    fn notStringValue(self: *Session, bytes: []const u8) KError!Value {
        if (bytes.len == 0) return try self.createManagedHostIntArray(&.{});
        if (bytes.len == 1) return try self.intValue(@intFromBool(bytes[0] == 0));
        const out = try self.allocator.alloc(i64, bytes.len);
        defer self.allocator.free(out);
        for (bytes, out) |byte, *item| item.* = @intFromBool(byte == 0);
        return try self.createManagedHostIntArray(out);
    }

    fn valueIsGrowlerNullProjection(value: Value) bool {
        if (value.tag() != .closure) return false;
        const closure = value.asClosure();
        if (!closureIsProjection(closure)) return false;
        if (closure.captures.len != 5) return false;
        if (closure.captures[0].tag() != .builtin or closure.captures[0].asBuiltin() != .identity) return false;
        const slot_count = scalarIntLikeValue(closure.captures[1]) orelse return false;
        const hole_mask = scalarIntLikeValue(closure.captures[2]) orelse return false;
        if (slot_count != 2 or hole_mask != 0b10) return false;
        return closure.captures[3].tag() == .builtin and closure.captures[3].asBuiltin() == .identity;
    }

    fn scalarNullLikeValue(value: Value) bool {
        if (tableScalarValue(value)) |scalar| return scalar.is_null;
        return switch (value.tag()) {
            .int => isKiwiIntNull(value.asInt()),
            .float32 => isKiwiFloat32Null(value.asFloat32()),
            .float => isKiwiFloatNull(value.asFloat()),
            .bool, .builtin => false,
            .closure => valueIsGrowlerNullProjection(value),
            .array => switch (value.arrayKind()) {
                .host_symbol => hostTextBytes(value.asHostSymbol()).len == 0,
                else => false,
            },
        };
    }

    fn valueIsAtomicForFillWithout(value: Value) bool {
        return switch (value.tag()) {
            .array => switch (value.arrayKind()) {
                .host_symbol, .host_table_scalar => true,
                .host_string, .host_string_view => blk: {
                    const text = stringBytes(value) orelse &.{};
                    break :blk text.len == 1;
                },
                else => false,
            },
            else => true,
        };
    }

    fn numericFalseMaskValue(self: *Session, value: Value) KError!Value {
        const mode = valueNumericMode(value) orelse return Value.fromBool(false);
        const total = numericFlatLen(value) orelse if (value.tag() == .array)
            (try numericHostArrayValue(self, value)).len()
        else
            return Value.fromBool(false);
        const bits = try self.allocator.alloc(bool, total);
        defer self.allocator.free(bits);
        switch (mode) {
            .int => {
                for (0..total) |idx| bits[idx] = isKiwiIntNull(try numericIntAt(value, idx));
            },
            .float => {
                for (0..total) |idx| bits[idx] = isKiwiFloatNull(try numericFloatAt(value, idx));
            },
        }
        const mask = try self.createManagedHostBitArray(bits);
        if (valueNonVectorNumericShape(value)) |shape| return try applyNonVectorNumericShapeToValue(self, mask, shape);
        return mask;
    }

    fn nullValue(self: *Session, value: Value) KError!Value {
        if (scalarNullLikeValue(value)) return Value.fromBool(true);
        if (tableScalarValue(value)) |scalar| return Value.fromBool(scalar.is_null);
        if (value.tag() != .array) return Value.fromBool(false);

        if (stringBytes(value)) |text| {
            var out = try self.allocHostBitArrayUninitialized(.managed, text.len);
            const metadata = fillStringByteEqWords(&out, text, " ");
            return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
        }
        if (valueNumericMode(value) != null) return try self.numericFalseMaskValue(value);
        if (boxedArrayItems(value)) |items| {
            var out = std.ArrayList(Value).empty;
            defer out.deinit(self.allocator);
            try out.ensureTotalCapacity(self.allocator, items.len);
            for (items) |item| try out.append(self.allocator, try self.nullValue(item));
            return try self.makeArrayFromValues(out.items);
        }
        return switch (value.arrayKind()) {
            .host_string_list => blk: {
                const bits = try self.allocator.alloc(bool, value.asHostStringList().len);
                defer self.allocator.free(bits);
                for (bits, 0..) |*bit, idx| bit.* = (try hostStringListItemBytes(value.asHostStringList(), idx)).len == 0;
                break :blk try self.createManagedHostBitArray(bits);
            },
            .host_symbol_list => blk: {
                const bits = try self.allocator.alloc(bool, value.asHostStringList().len);
                defer self.allocator.free(bits);
                for (bits, 0..) |*bit, idx| bit.* = (try hostStringListItemBytes(value.asHostStringList(), idx)).len == 0;
                break :blk try self.createManagedHostBitArray(bits);
            },
            .host_symbol => Value.fromBool(hostTextBytes(value.asHostSymbol()).len == 0),
            else => error.Type,
        };
    }

    fn fillNumericNulls(self: *Session, left: Value, right: Value, mode: HostDenseElem) KError!Value {
        const total = numericFlatLen(right) orelse if (right.tag() == .array)
            (try numericHostArrayValue(self, right)).len()
        else
            return error.Type;
        const result = switch (mode) {
            .float => blk: {
                const fill_value = try scalarNumericValue(left);
                const items = try self.allocator.alloc(f64, total);
                defer self.allocator.free(items);
                for (0..total) |idx| {
                    const item = try numericFloatAt(right, idx);
                    items[idx] = if (isKiwiFloatNull(item)) fill_value else item;
                }
                break :blk try self.createManagedHostFloatArray(items);
            },
            .int => blk: {
                if (left.tag() == .float) {
                    const fill_value = left.asFloat();
                    const items = try self.allocator.alloc(f64, total);
                    defer self.allocator.free(items);
                    for (0..total) |idx| {
                        const item = try numericIntAt(right, idx);
                        items[idx] = if (isKiwiIntNull(item)) fill_value else @floatFromInt(item);
                    }
                    break :blk try self.createManagedHostFloatArray(items);
                }
                const fill_value = scalarIntLikeValue(left) orelse return error.Type;
                const items = try self.allocator.alloc(i64, total);
                defer self.allocator.free(items);
                for (0..total) |idx| {
                    const item = try numericIntAt(right, idx);
                    items[idx] = if (isKiwiIntNull(item)) fill_value else item;
                }
                break :blk try self.createManagedHostIntArray(items);
            },
        };
        if (valueNonVectorNumericShape(right)) |shape| return try applyNonVectorNumericShapeToValue(self, result, shape);
        return result;
    }

    fn fillStringNulls(self: *Session, left: Value, right: Value) KError!?Value {
        const bytes = stringBytes(right) orelse return null;
        const fill_bytes = stringBytes(left) orelse return null;
        if (fill_bytes.len != 1) return null;
        const out = try self.allocator.alloc(u8, bytes.len);
        defer self.allocator.free(out);
        for (bytes, out) |byte, *item| item.* = if (byte == ' ') fill_bytes[0] else byte;
        return try self.managedHostString(out);
    }

    fn fillSymbolListNulls(self: *Session, left: Value, right: *const HostStringList) KError!?Value {
        const fill_bytes = symbolBytes(left) orelse return null;
        const items = try self.allocator.alloc([]const u8, right.len);
        defer self.allocator.free(items);
        for (items, 0..) |*item, idx| {
            const bytes = try hostStringListItemBytes(right, idx);
            item.* = if (bytes.len == 0) fill_bytes else bytes;
        }
        return try self.createManagedHostSymbolListFromSlices(items);
    }

    fn fillValues(self: *Session, left: Value, right: Value) KError!Value {
        if (scalarNullLikeValue(right)) return self.shareValue(left);
        if (try self.fillStringNulls(left, right)) |result| return result;
        if (valueNumericMode(right)) |mode| return try self.fillNumericNulls(left, right, mode);
        if (right.tag() != .array) return self.shareValue(right);
        if (right.arrayKind() == .host_keyed_store) {
            const store = right.asHostKeyedStore();
            if (store.layout == .dict) return try self.fillDictValues(left, store);
        }
        if (right.arrayKind() == .host_symbol_list) {
            if (try self.fillSymbolListNulls(left, right.asHostStringList())) |result| return result;
        }
        if (boxedArrayItems(right)) |items| {
            var out = std.ArrayList(Value).empty;
            defer out.deinit(self.allocator);
            try out.ensureTotalCapacity(self.allocator, items.len);
            for (items) |item| try out.append(self.allocator, try self.fillValues(left, item));
            return try self.makeArrayFromValues(out.items);
        }
        return self.shareValue(right);
    }

    fn fillDictValues(self: *Session, left: Value, store: *const HostKeyedStore) KError!Value {
        const len = keyedStoreValuesValueCount(store.values) orelse return error.Internal;
        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len);

        for (0..len) |idx| {
            const item = try self.keyedStoreValueAt(store, idx);
            errdefer self.releaseValue(item);
            const result = try self.fillValues(left, item);
            self.releaseValue(item);
            try results.append(self.allocator, result);
        }

        const values_value = try self.makeArrayFromValues(results.items);
        defer self.releaseValue(values_value);
        return try self.createDictLikeValue(store, values_value);
    }

    fn numericScalarItemValue(self: *Session, value: Value, idx: usize) KError!Value {
        const array = try numericHostArrayValue(self, value);
        return try self.hostDenseIndexScalar(value, array, @intCast(idx));
    }

    fn sequenceContainsValue(self: *Session, haystack: Value, needle: Value) KError!bool {
        if (valueNumericMatrixShape(haystack)) |shape| {
            for (0..shape.rows) |row_idx| {
                const item = try numericValueFirstAxisCellValue(self, haystack, shapedNumericHandle(haystack).?, @intCast(row_idx));
                defer self.releaseValue(item);
                if (try self.valueStructuralEqual(item, needle)) return true;
            }
            return false;
        }
        if (valueNumericMode(haystack) != null) {
            const len = numericFlatLen(haystack) orelse (try numericHostArrayValue(self, haystack)).len();
            for (0..len) |idx| {
                const item = try self.numericScalarItemValue(haystack, idx);
                defer self.releaseValue(item);
                if (try self.valueStructuralEqual(item, needle)) return true;
            }
            return false;
        }
        if (haystack.tag() == .array and haystack.arrayKind() == .host_symbol_list) {
            const needle_bytes = symbolBytes(needle) orelse return false;
            const list = haystack.asHostStringList();
            for (0..list.len) |idx| {
                if (std.mem.eql(u8, try hostStringListItemBytes(list, idx), needle_bytes)) return true;
            }
            return false;
        }
        if (haystack.tag() == .array and haystack.arrayKind() == .host_string_list) {
            const needle_bytes = stringBytes(needle) orelse symbolBytes(needle) orelse return false;
            const list = haystack.asHostStringList();
            for (0..list.len) |idx| {
                if (std.mem.eql(u8, try hostStringListItemBytes(list, idx), needle_bytes)) return true;
            }
            return false;
        }
        if (boxedArrayItems(haystack)) |items| {
            for (items) |item| {
                if (try self.valueStructuralEqual(item, needle)) return true;
            }
            return false;
        }
        return try self.valueStructuralEqual(haystack, needle);
    }

    fn withoutStringValues(self: *Session, left: []const u8, right: Value) KError!Value {
        const removed = stringBytes(right) orelse return try self.managedHostString(left);
        var lookup = @as([256]bool, @splat(false));
        for (removed) |ch| lookup[ch] = true;
        var out = std.ArrayList(u8).empty;
        defer out.deinit(self.allocator);
        for (left) |ch| {
            if (!lookup[ch]) try out.append(self.allocator, ch);
        }
        return try self.managedHostString(out.items);
    }

    fn withoutNumericVectorValues(self: *Session, left: Value, right: Value) KError!Value {
        const source = try numericHostArrayValue(self, left);
        const len = source.len();
        var removed_any = false;

        switch (source.storage) {
            .bit => {
                const remove_false = try self.sequenceContainsValue(right, Value.fromBool(false));
                const remove_true = try self.sequenceContainsValue(right, Value.fromBool(true));
                if (!remove_false and !remove_true) return self.shareValue(left);

                const bits: HostBitSlice = .{ .words = source.storage.bit, .len = len };
                const count_true = bitCountTrue(bits);
                const count_false = len - count_true;
                const out_len = (if (remove_false) 0 else count_false) + (if (remove_true) 0 else count_true);
                const out = try self.allocHostBitArray(.managed, out_len);

                if (!remove_false and remove_true) {
                    const metadata = (BitSequenceStats{
                        .saw_zero = out_len != 0,
                        .has_prev = out_len != 0,
                        .prev = false,
                    }).metadata();
                    return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
                }
                if (remove_false and !remove_true) {
                    bitFill(out.words, out.len, true);
                    const metadata = (BitSequenceStats{
                        .saw_one = out_len != 0,
                        .has_prev = out_len != 0,
                        .prev = true,
                    }).metadata();
                    return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
                }
                removed_any = true;
                return try self.finishManagedHostBitAlloc(out, host_dense_flag_normalized | host_dense_flag_asc | host_dense_flag_dsc, .{ .min = 0, .max = 0 });
            },
            .float64 => |items| {
                var out = std.ArrayList(f64).empty;
                defer out.deinit(self.allocator);
                for (items) |item| {
                    const value = try self.floatValue(item);
                    if (try self.sequenceContainsValue(right, value)) {
                        removed_any = true;
                        continue;
                    }
                    try out.append(self.allocator, item);
                }
                if (!removed_any) return self.shareValue(left);
                return try self.createManagedHostFloatArray(out.items);
            },
            else => {
                const view = hostIntArrayView(source).?;
                var out = std.ArrayList(i64).empty;
                defer out.deinit(self.allocator);
                for (0..hostIntArrayViewLen(view)) |idx| {
                    const item_value = try self.intValue(hostIntViewItem(view, idx));
                    if (try self.sequenceContainsValue(right, item_value)) {
                        removed_any = true;
                        continue;
                    }
                    try out.append(self.allocator, item_value.asInt());
                }
                if (!removed_any) return self.shareValue(left);
                return try self.createManagedHostIntArray(out.items);
            },
        }
    }

    fn withoutNumericMatrixValues(self: *Session, left: Value, right: Value, shape: NumericMatrixShape) KError!Value {
        var row_indices = std.ArrayList(usize).empty;
        defer row_indices.deinit(self.allocator);
        try row_indices.ensureTotalCapacity(self.allocator, shape.rows);
        var removed_any = false;
        for (0..shape.rows) |row_idx| {
            const row = try numericValueFirstAxisCellValue(self, left, shapedNumericHandle(left).?, @intCast(row_idx));
            defer self.releaseValue(row);
            if (try self.sequenceContainsValue(right, row)) {
                removed_any = true;
                continue;
            }
            try row_indices.append(self.allocator, row_idx);
        }
        if (!removed_any) return self.shareValue(left);
        return try numericValueMatrixSelectRows(self, left, row_indices.items);
    }

    fn withoutBoxedValues(self: *Session, left: Value, right: Value, items: []const Value) KError!Value {
        var out = std.ArrayList(Value).empty;
        defer out.deinit(self.allocator);
        try out.ensureTotalCapacity(self.allocator, items.len);
        var removed_any = false;
        for (items) |item| {
            if (try self.sequenceContainsValue(right, item)) {
                removed_any = true;
                continue;
            }
            try out.append(self.allocator, item);
        }
        if (!removed_any) return self.shareValue(left);
        return try self.makeArrayFromValues(out.items);
    }

    fn withoutSymbolListValues(self: *Session, left: Value, right: Value, list: *const HostStringList) KError!Value {
        var out = std.ArrayList([]const u8).empty;
        defer out.deinit(self.allocator);
        try out.ensureTotalCapacity(self.allocator, list.len);
        var removed_any = false;
        for (0..list.len) |idx| {
            const bytes = try hostStringListItemBytes(list, idx);
            const item = try self.managedHostSymbol(bytes);
            defer self.releaseValue(item);
            if (try self.sequenceContainsValue(right, item)) {
                removed_any = true;
                continue;
            }
            try out.append(self.allocator, bytes);
        }
        if (!removed_any) return self.shareValue(left);
        return try self.createManagedHostSymbolListFromSlices(out.items);
    }

    fn withoutValues(self: *Session, left: Value, right: Value) KError!Value {
        if (stringBytes(left)) |text| return try self.withoutStringValues(text, right);
        if (valueNumericMatrixShape(left)) |shape| return try self.withoutNumericMatrixValues(left, right, shape);
        if (valueNumericMode(left) != null) return try self.withoutNumericVectorValues(left, right);
        if (left.tag() == .array and left.arrayKind() == .host_symbol_list) return try self.withoutSymbolListValues(left, right, left.asHostStringList());
        if (boxedArrayItems(left)) |items| return try self.withoutBoxedValues(left, right, items);
        return error.Type;
    }

    fn fillWithoutValues(self: *Session, left: Value, right: Value) KError!Value {
        if (valueIsAtomicForFillWithout(left)) return try self.fillValues(left, right);
        return try self.withoutValues(left, right);
    }

    fn hostNumericMatrixRowOrder(array: *const HostDenseArray, lhs_row: usize, rhs_row: usize, cols: usize) std.math.Order {
        const left_base = lhs_row * cols;
        const right_base = rhs_row * cols;
        return switch (array.storage) {
            .bit => {
                for (0..cols) |col| {
                    const order = std.math.order(
                        @intFromBool(bitGet(array.storage.bit, left_base + col)),
                        @intFromBool(bitGet(array.storage.bit, right_base + col)),
                    );
                    if (order != .eq) return order;
                }
                return .eq;
            },
            .int8 => |items| {
                for (0..cols) |col| {
                    const order = std.math.order(items[left_base + col], items[right_base + col]);
                    if (order != .eq) return order;
                }
                return .eq;
            },
            .int16 => |items| {
                for (0..cols) |col| {
                    const order = std.math.order(items[left_base + col], items[right_base + col]);
                    if (order != .eq) return order;
                }
                return .eq;
            },
            .int32 => |items| {
                for (0..cols) |col| {
                    const order = std.math.order(items[left_base + col], items[right_base + col]);
                    if (order != .eq) return order;
                }
                return .eq;
            },
            .int64 => |items| {
                for (0..cols) |col| {
                    const order = std.math.order(items[left_base + col], items[right_base + col]);
                    if (order != .eq) return order;
                }
                return .eq;
            },
            .float32 => |items| {
                for (0..cols) |col| {
                    const order = std.math.order(items[left_base + col], items[right_base + col]);
                    if (order != .eq) return order;
                }
                return .eq;
            },
            .float64 => |items| {
                for (0..cols) |col| {
                    const order = std.math.order(items[left_base + col], items[right_base + col]);
                    if (order != .eq) return order;
                }
                return .eq;
            },
        };
    }

    const HostIndexedOrderContext = struct {
        array: *const HostDenseArray,
        matrix_cols: ?usize = null,
    };

    fn hostItemOrder(context: HostIndexedOrderContext, lhs: usize, rhs: usize) std.math.Order {
        if (context.matrix_cols) |cols| return hostNumericMatrixRowOrder(context.array, lhs, rhs, cols);
        return switch (context.array.storage) {
            .bit => std.math.order(@intFromBool(bitGet(context.array.storage.bit, lhs)), @intFromBool(bitGet(context.array.storage.bit, rhs))),
            .int8 => std.math.order(context.array.storage.int8[lhs], context.array.storage.int8[rhs]),
            .int16 => std.math.order(context.array.storage.int16[lhs], context.array.storage.int16[rhs]),
            .int32 => std.math.order(context.array.storage.int32[lhs], context.array.storage.int32[rhs]),
            .int64 => std.math.order(context.array.storage.int64[lhs], context.array.storage.int64[rhs]),
            .float32 => std.math.order(context.array.storage.float32[lhs], context.array.storage.float32[rhs]),
            .float64 => std.math.order(context.array.storage.float64[lhs], context.array.storage.float64[rhs]),
        };
    }

    fn orderComesBefore(order: std.math.Order, ascending: bool) bool {
        return if (ascending) order == .lt else order == .gt;
    }

    fn hostIndexedOrder(_: *Session, context: HostIndexedOrderContext, lhs: usize, rhs: usize) KError!std.math.Order {
        return hostItemOrder(context, lhs, rhs);
    }

    fn numericVectorIndexedOrder(_: *Session, value: Value, lhs: usize, rhs: usize) KError!std.math.Order {
        return switch (valueNumericMode(value) orelse return error.Type) {
            .float => std.math.order(try numericFloatAt(value, lhs), try numericFloatAt(value, rhs)),
            .int => std.math.order(try numericIntAt(value, lhs), try numericIntAt(value, rhs)),
        };
    }

    fn numericMatrixIndexedOrder(self: *Session, view: NumericMatrixView, lhs: usize, rhs: usize) KError!std.math.Order {
        return try numericMatrixRowOrder(self, view, lhs, rhs);
    }

    const dense_int16_matrix_radix_grade_min_rows: usize = 512;
    const dense_int16_matrix_radix_grade_max_cols: usize = 64;
    const dense_int16_matrix_range_grade_max_span: usize = 8192;

    fn prefixRadixCounts(counts: []usize, ascending: bool) void {
        var total: usize = 0;
        if (ascending) {
            for (counts) |*count| {
                const next = total + count.*;
                count.* = total;
                total = next;
            }
        } else {
            var idx = counts.len;
            while (idx != 0) {
                idx -= 1;
                const next = total + counts[idx];
                counts[idx] = total;
                total = next;
            }
        }
    }

    fn managedHostInt16MatrixRadixGradeValue(self: *Session, items: []const i16, shape: NumericMatrixShape, ascending: bool) KError!Value {
        if (shape.rows <= 1 or shape.cols == 0) return try newRangeIotaValue(self, .managed, shape.rows);

        const counts = try self.allocator.alloc(usize, 1 << 16);
        defer self.allocator.free(counts);
        @memset(counts, 0);

        const idxs = try self.allocator.alloc(usize, shape.rows);
        defer self.allocator.free(idxs);
        const scratch = try self.allocator.alloc(usize, shape.rows);
        defer self.allocator.free(scratch);

        for (idxs, 0..) |*slot, idx| slot.* = idx;
        var current: []usize = idxs;
        var dest: []usize = scratch;

        var reverse_col: usize = 0;
        while (reverse_col < shape.cols) : (reverse_col += 1) {
            const col = shape.cols - 1 - reverse_col;
            var min_bucket: usize = counts.len - 1;
            var max_bucket: usize = 0;
            for (current) |row_idx| {
                const bucket: usize = @intCast(int16GradeBucket(items[row_idx * shape.cols + col]));
                counts[bucket] += 1;
                min_bucket = @min(min_bucket, bucket);
                max_bucket = @max(max_bucket, bucket);
            }

            prefixRadixCounts(counts[min_bucket .. max_bucket + 1], ascending);
            for (current) |row_idx| {
                const bucket: usize = @intCast(int16GradeBucket(items[row_idx * shape.cols + col]));
                const out_idx = counts[bucket];
                counts[bucket] = out_idx + 1;
                dest[out_idx] = row_idx;
            }
            @memset(counts[min_bucket .. max_bucket + 1], 0);

            const tmp = current;
            current = dest;
            dest = tmp;
        }

        return try self.managedHostIndexArrayValue(current);
    }

    fn managedHostInt16MatrixRangeGradeValue(self: *Session, items: []const i16, shape: NumericMatrixShape, ascending: bool, min_value: i64, range_len: usize) KError!Value {
        if (shape.rows <= 1 or shape.cols == 0) return try newRangeIotaValue(self, .managed, shape.rows);

        const counts = try self.allocator.alloc(usize, range_len);
        defer self.allocator.free(counts);

        const idxs = try self.allocator.alloc(usize, shape.rows);
        defer self.allocator.free(idxs);
        const scratch = try self.allocator.alloc(usize, shape.rows);
        defer self.allocator.free(scratch);

        for (idxs, 0..) |*slot, idx| slot.* = idx;
        var current: []usize = idxs;
        var dest: []usize = scratch;

        var reverse_col: usize = 0;
        while (reverse_col < shape.cols) : (reverse_col += 1) {
            const col = shape.cols - 1 - reverse_col;
            @memset(counts, 0);
            for (current) |row_idx| {
                const bucket: usize = @intCast(@as(i64, items[row_idx * shape.cols + col]) - min_value);
                counts[bucket] += 1;
            }

            prefixRadixCounts(counts, ascending);
            for (current) |row_idx| {
                const bucket: usize = @intCast(@as(i64, items[row_idx * shape.cols + col]) - min_value);
                const out_idx = counts[bucket];
                counts[bucket] = out_idx + 1;
                dest[out_idx] = row_idx;
            }

            const tmp = current;
            current = dest;
            dest = tmp;
        }

        return try self.managedHostIndexArrayValue(current);
    }

    fn tryManagedHostInt16MatrixRadixGradeValue(self: *Session, array: *const HostDenseArray, shape: NumericMatrixShape, ascending: bool) KError!?Value {
        if (shape.rows < dense_int16_matrix_radix_grade_min_rows or shape.cols > dense_int16_matrix_radix_grade_max_cols) return null;
        const items = switch (array.storage) {
            .int16 => |items| items,
            else => return null,
        };
        if (hostDenseCachedIntRange(array)) |range| {
            if (intGradeRangeLen(range)) |range_len| {
                if (range_len <= dense_int16_matrix_range_grade_max_span) {
                    return try self.managedHostInt16MatrixRangeGradeValue(items, shape, ascending, range.min, range_len);
                }
            }
        }
        return try self.managedHostInt16MatrixRadixGradeValue(items, shape, ascending);
    }

    fn managedHostNumericMatrixGradeValue(self: *Session, array: *const HostDenseArray, shape: NumericMatrixShape, ascending: bool) KError!Value {
        if (try self.tryManagedHostInt16MatrixRadixGradeValue(array, shape, ascending)) |result| return result;
        const idxs = try self.allocator.alloc(usize, shape.rows);
        defer self.allocator.free(idxs);
        for (idxs, 0..) |*slot, idx| slot.* = idx;
        try self.stableMergeSortIndices(idxs, ascending, HostIndexedOrderContext{ .array = array, .matrix_cols = shape.cols }, hostIndexedOrder);
        return try self.managedHostIndexArrayValue(idxs);
    }

    fn tryFastHostNumericMatrixGradeValue(self: *Session, value: Value, ascending: bool) KError!?Value {
        const array = hostDenseIfPresent(value) orelse return null;
        const shape = valueNumericMatrixShape(value) orelse return null;
        return try self.managedHostNumericMatrixGradeValue(array, shape, ascending);
    }

    fn stableMergeSortIndices(
        self: *Session,
        idxs: []usize,
        ascending: bool,
        context: anytype,
        comptime orderFn: fn (*Session, @TypeOf(context), usize, usize) KError!std.math.Order,
    ) KError!void {
        if (idxs.len <= 1) return;
        const scratch = try self.allocator.alloc(usize, idxs.len);
        defer self.allocator.free(scratch);

        var src: []usize = idxs;
        var dst: []usize = scratch;
        var width: usize = 1;
        var flipped = false;
        while (width < idxs.len) {
            var start: usize = 0;
            while (start < src.len) : (start += width * 2) {
                const mid = @min(start + width, src.len);
                const end = @min(start + width * 2, src.len);
                var left = start;
                var right = mid;
                var out = start;
                while (left < mid and right < end) : (out += 1) {
                    const order = try orderFn(self, context, src[right], src[left]);
                    if (orderComesBefore(order, ascending)) {
                        dst[out] = src[right];
                        right += 1;
                    } else {
                        dst[out] = src[left];
                        left += 1;
                    }
                }
                while (left < mid) : ({
                    left += 1;
                    out += 1;
                }) dst[out] = src[left];
                while (right < end) : ({
                    right += 1;
                    out += 1;
                }) dst[out] = src[right];
            }
            const next_width = if (width > idxs.len / 2) idxs.len else width * 2;
            const tmp = src;
            src = dst;
            dst = tmp;
            width = next_width;
            flipped = !flipped;
        }
        if (flipped) @memcpy(idxs, src);
    }

    fn reverseIndexValue(self: *Session, len: usize) KError!Value {
        if (len == 0) return try newRangeIotaValue(self, .managed, 0);
        const start = std.math.cast(i64, len - 1) orelse return error.Unsupported;
        return try newRangeIotaValueWithParams(self, .managed, len, start, -1);
    }

    fn tryMonotonicGradeValue(self: *Session, len: usize, flags: u8, ascending: bool) KError!?Value {
        if (len <= 1) return try newRangeIotaValue(self, .managed, len);

        const mono = monotonicFlags(flags);
        if (mono == 0) return null;

        const direct_flag = if (ascending) host_dense_flag_asc else host_dense_flag_dsc;
        if ((mono & direct_flag) != 0) return try newRangeIotaValue(self, .managed, len);
        return null;
    }

    fn managedHostIndexArrayValue(self: *Session, idxs: []const usize) KError!Value {
        const max_value = if (idxs.len == 0)
            0
        else
            std.math.cast(i64, idxs.len - 1) orelse return error.Unsupported;

        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_value), idxs.len);
        var asc = true;
        var dsc = true;
        var prev: i64 = 0;
        for (idxs, 0..) |idx, out_idx| {
            const value = std.math.cast(i64, idx) orelse return error.Unsupported;
            try out.set(out_idx, value);
            if (out_idx != 0) {
                if (prev > value) asc = false;
                if (prev < value) dsc = false;
            }
            prev = value;
        }

        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, host_dense_flag_normalized | orderFlagsFromMonotonic(asc, dsc));
        hostDenseSetCachedIntRange(host, .{ .min = 0, .max = max_value });
        return value;
    }

    fn intGradeRangeLen(range: HostIntRange) ?usize {
        const len_i128 = @as(i128, range.max) - @as(i128, range.min) + 1;
        if (len_i128 <= 0 or len_i128 > std.math.maxInt(usize)) return null;
        return @intCast(len_i128);
    }

    fn preferBucketIntGrade(len: usize, range_len: usize) bool {
        if (range_len == 0) return false;
        if (range_len > (1 << 18)) return false;
        const scaled_len = std.math.mul(usize, len, 16) catch std.math.maxInt(usize);
        return range_len <= scaled_len;
    }

    const small_grade_stack_threshold: usize = 128;
    const small_dense_int8_grade_threshold: usize = 24;
    const small_dense_int16_grade_threshold: usize = 48;
    const small_dense_int32_grade_threshold: usize = 64;
    const small_dense_int64_grade_threshold: usize = 64;
    const small_dense_float_grade_threshold: usize = 64;

    fn gradeResultMaxValue(len: usize) KError!i64 {
        return if (len == 0)
            0
        else
            std.math.cast(i64, len - 1) orelse return error.Unsupported;
    }

    fn finalizeManagedGradeResult(self: *Session, out: *HostIntResult, max_value: i64) KError!Value {
        const flags = host_dense_flag_normalized |
            (if (max_value <= 0) host_dense_flag_asc | host_dense_flag_dsc else 0);
        return try self.finishManagedGradeResultWithFlags(out, max_value, flags);
    }

    fn finishManagedGradeResultWithFlags(self: *Session, out: *HostIntResult, max_value: i64, flags: u8) KError!Value {
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, flags);
        hostDenseSetCachedIntRange(host, .{ .min = 0, .max = max_value });
        return value;
    }

    fn fillTypedBooleanGradeIndicesBitSlice(comptime IdxT: type, out: []IdxT, bits: HostBitSlice, ascending: bool) void {
        const count_one = bitCountTrue(bits);
        const count_zero = bits.len - count_one;

        if (fillBooleanGradeBytePartitions(IdxT, out, bits, count_one, ascending)) return;

        var zero_pos: usize = if (ascending) 0 else count_one;
        var one_pos: usize = if (ascending) count_zero else 0;

        for (bits.words, 0..) |_, word_idx| {
            const active_mask = if (word_idx + 1 == bits.words.len) bitTailMask(bits.len) else std.math.maxInt(u64);
            const word = bits.words[word_idx] & active_mask;
            const word_base = word_idx * host_bit_word_bits;

            var zeros = (~word) & active_mask;
            while (zeros != 0) {
                const bit_idx: usize = @intCast(@ctz(zeros));
                out[zero_pos] = @intCast(word_base + bit_idx);
                zero_pos += 1;
                zeros &= zeros - 1;
            }

            var ones = word;
            while (ones != 0) {
                const bit_idx: usize = @intCast(@ctz(ones));
                out[one_pos] = @intCast(word_base + bit_idx);
                one_pos += 1;
                ones &= ones - 1;
            }
        }
        std.debug.assert(zero_pos == (if (ascending) bits.len - count_one else bits.len));
        std.debug.assert(one_pos == (if (ascending) bits.len else count_one));
    }

    fn fillTypedBooleanGradeIndicesIntSlice(comptime T: type, comptime IdxT: type, out: []IdxT, items: []const T, ascending: bool) void {
        var count_one: usize = 0;
        for (items) |item| {
            if (item != 0) count_one += 1;
        }

        var zero_pos: usize = if (ascending) 0 else count_one;
        var one_pos: usize = if (ascending) out.len - count_one else 0;
        for (items, 0..) |item, idx| {
            if (item == 0) {
                out[zero_pos] = @intCast(idx);
                zero_pos += 1;
            } else {
                out[one_pos] = @intCast(idx);
                one_pos += 1;
            }
        }
    }

    fn fillTypedBooleanGradeResult(comptime IdxT: type, dest: []IdxT, items: HostIntArrayView, ascending: bool) void {
        switch (items) {
            .bit => |bits| fillTypedBooleanGradeIndicesBitSlice(IdxT, dest, bits, ascending),
            .int8 => |slice| fillTypedBooleanGradeIndicesIntSlice(i8, IdxT, dest, slice, ascending),
            .int16 => |slice| fillTypedBooleanGradeIndicesIntSlice(i16, IdxT, dest, slice, ascending),
            .int32 => |slice| fillTypedBooleanGradeIndicesIntSlice(i32, IdxT, dest, slice, ascending),
            .int64 => |slice| fillTypedBooleanGradeIndicesIntSlice(i64, IdxT, dest, slice, ascending),
        }
    }

    fn managedHostBooleanGradeValue(self: *Session, view: HostIntDenseView, len: usize, ascending: bool) KError!Value {
        switch (view) {
            .dense => |items| {
                const max_value = try gradeResultMaxValue(len);
                var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_value), len);
                switch (out) {
                    .bit => unreachable,
                    .int8 => |*dest| fillTypedBooleanGradeResult(i8, dest.items, items, ascending),
                    .int16 => |*dest| fillTypedBooleanGradeResult(i16, dest.items, items, ascending),
                    .int32 => |*dest| fillTypedBooleanGradeResult(i32, dest.items, items, ascending),
                    .int64 => |*dest| fillTypedBooleanGradeResult(i64, dest.items, items, ascending),
                }
                return try finalizeManagedGradeResult(self, &out, max_value);
            },
            else => {
                if (len <= small_grade_stack_threshold) {
                    var idxs_buf: [small_grade_stack_threshold]usize = undefined;
                    const idxs = idxs_buf[0..len];
                    try fillBooleanGradeIndices(idxs, view, ascending);
                    return try self.managedHostIndexArrayValue(idxs);
                }

                const idxs = try self.allocator.alloc(usize, len);
                defer self.allocator.free(idxs);
                try fillBooleanGradeIndices(idxs, view, ascending);
                return try self.managedHostIndexArrayValue(idxs);
            },
        }
    }

    fn prefixStringByteGradeCounts(counts: *[256]usize, ascending: bool) void {
        var total: usize = 0;
        if (ascending) {
            for (counts[0..]) |*count| {
                const next = total + count.*;
                count.* = total;
                total = next;
            }
            return;
        }

        var bucket = counts.len;
        while (bucket > 0) {
            bucket -= 1;
            const next = total + counts[bucket];
            counts[bucket] = total;
            total = next;
        }
    }

    fn fillTypedStringByteGradeResult(comptime IdxT: type, dest: []IdxT, bytes: []const u8, counts: *[256]usize) void {
        for (bytes, 0..) |byte, idx| {
            const out_idx = counts[byte];
            counts[byte] = out_idx + 1;
            dest[out_idx] = @intCast(idx);
        }
    }

    fn fillManagedStringByteGradeResult(out: *HostIntResult, bytes: []const u8, ascending: bool) void {
        var counts: [256]usize = undefined;
        @memset(counts[0..], 0);
        for (bytes) |byte| counts[byte] += 1;
        prefixStringByteGradeCounts(&counts, ascending);

        switch (out.*) {
            .bit => unreachable,
            .int8 => |*dest| fillTypedStringByteGradeResult(i8, dest.items, bytes, &counts),
            .int16 => |*dest| fillTypedStringByteGradeResult(i16, dest.items, bytes, &counts),
            .int32 => |*dest| fillTypedStringByteGradeResult(i32, dest.items, bytes, &counts),
            .int64 => |*dest| fillTypedStringByteGradeResult(i64, dest.items, bytes, &counts),
        }
    }

    fn managedStringByteGradeValue(self: *Session, bytes: []const u8, ascending: bool) KError!Value {
        if (bytes.len <= 1) return try newRangeIotaValue(self, .managed, bytes.len);
        const max_value = try gradeResultMaxValue(bytes.len);
        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_value), bytes.len);
        fillManagedStringByteGradeResult(&out, bytes, ascending);
        return try finalizeManagedGradeResult(self, &out, max_value);
    }

    fn int8GradeBucket(item: i8) u8 {
        return @as(u8, @bitCast(item)) ^ 0x80;
    }

    fn fillTypedReverseMonotonicGradeIndicesBitSlice(comptime IdxT: type, out: []IdxT, bits: HostBitSlice) bool {
        var out_idx: usize = 0;
        var scan = bits.len;
        var unique = true;
        while (scan > 0) {
            const run_end = scan;
            const run_value = bitGet(bits.words, run_end - 1);
            scan -= 1;
            while (scan > 0 and bitGet(bits.words, scan - 1) == run_value) : (scan -= 1) {
                unique = false;
            }
            for (scan..run_end) |idx| {
                out[out_idx] = @intCast(idx);
                out_idx += 1;
            }
        }
        return unique;
    }

    fn fillTypedReverseMonotonicGradeIndicesIntSlice(comptime T: type, comptime IdxT: type, out: []IdxT, items: []const T) bool {
        var out_idx: usize = 0;
        var scan = items.len;
        var unique = true;
        while (scan > 0) {
            const run_end = scan;
            const run_value = items[run_end - 1];
            scan -= 1;
            while (scan > 0 and items[scan - 1] == run_value) : (scan -= 1) {
                unique = false;
            }
            for (scan..run_end) |idx| {
                out[out_idx] = @intCast(idx);
                out_idx += 1;
            }
        }
        return unique;
    }

    fn fillTypedReverseMonotonicGradeIndicesFloatSlice(comptime IdxT: type, out: []IdxT, items: []const f64) bool {
        var out_idx: usize = 0;
        var scan = items.len;
        var unique = true;
        while (scan > 0) {
            const run_end = scan;
            const run_value = items[run_end - 1];
            scan -= 1;
            while (scan > 0 and std.math.order(items[scan - 1], run_value) == .eq) : (scan -= 1) {
                unique = false;
            }
            for (scan..run_end) |idx| {
                out[out_idx] = @intCast(idx);
                out_idx += 1;
            }
        }
        return unique;
    }

    fn fillTypedInsertionGradeIndicesIntSlice(comptime T: type, comptime IdxT: type, out: []IdxT, items: []const T, ascending: bool) void {
        for (out, 0..) |*slot, idx| slot.* = @intCast(idx);
        for (1..out.len) |idx| {
            const key_idx = @as(usize, @intCast(out[idx]));
            const key = items[key_idx];
            var scan = idx;
            while (scan > 0) {
                const prev_idx = @as(usize, @intCast(out[scan - 1]));
                if (!orderComesBefore(std.math.order(key, items[prev_idx]), ascending)) break;
                out[scan] = @intCast(prev_idx);
                scan -= 1;
            }
            out[scan] = @intCast(key_idx);
        }
    }

    fn fillTypedInsertionGradeIndicesFloatSlice(comptime IdxT: type, out: []IdxT, items: []const f64, ascending: bool) void {
        for (out, 0..) |*slot, idx| slot.* = @intCast(idx);
        for (1..out.len) |idx| {
            const key_idx = @as(usize, @intCast(out[idx]));
            const key = items[key_idx];
            var scan = idx;
            while (scan > 0) {
                const prev_idx = @as(usize, @intCast(out[scan - 1]));
                if (!orderComesBefore(std.math.order(key, items[prev_idx]), ascending)) break;
                out[scan] = @intCast(prev_idx);
                scan -= 1;
            }
            out[scan] = @intCast(key_idx);
        }
    }

    fn fillTypedInt8GradeResult(comptime T: type, dest: []T, items: []const i8, counts: *[256]usize) void {
        for (items, 0..) |item, idx| {
            const bucket = int8GradeBucket(item);
            const out_idx = counts[bucket];
            counts[bucket] = out_idx + 1;
            dest[out_idx] = @intCast(idx);
        }
    }

    fn managedHostInt8GradeValue(self: *Session, items: []const i8, ascending: bool) KError!Value {
        const max_value = try gradeResultMaxValue(items.len);

        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_value), items.len);
        var counts: [256]usize = undefined;
        @memset(counts[0..], 0);

        for (items) |item| {
            counts[int8GradeBucket(item)] += 1;
        }

        var total: usize = 0;
        var non_empty_buckets: usize = 0;
        if (ascending) {
            for (counts[0..]) |*count| {
                if (count.* != 0) non_empty_buckets += 1;
                const next = total + count.*;
                count.* = total;
                total = next;
            }
        } else {
            var bucket = counts.len;
            while (bucket > 0) {
                bucket -= 1;
                if (counts[bucket] != 0) non_empty_buckets += 1;
                const next = total + counts[bucket];
                counts[bucket] = total;
                total = next;
            }
        }

        switch (out) {
            .bit => unreachable,
            .int8 => |*dest| fillTypedInt8GradeResult(i8, dest.items, items, &counts),
            .int16 => |*dest| fillTypedInt8GradeResult(i16, dest.items, items, &counts),
            .int32 => |*dest| fillTypedInt8GradeResult(i32, dest.items, items, &counts),
            .int64 => |*dest| fillTypedInt8GradeResult(i64, dest.items, items, &counts),
        }

        const flags = host_dense_flag_normalized |
            (if (non_empty_buckets <= 1) host_dense_flag_asc | host_dense_flag_dsc else 0);
        return try self.finishManagedGradeResultWithFlags(&out, max_value, flags);
    }

    fn fillBooleanGradeIndices(out: []usize, view: HostIntDenseView, ascending: bool) KError!void {
        switch (view) {
            .dense => |items| switch (items) {
                .bit => |bits| fillTypedBooleanGradeIndicesBitSlice(usize, out, bits, ascending),
                .int8 => |slice| fillTypedBooleanGradeIndicesIntSlice(i8, usize, out, slice, ascending),
                .int16 => |slice| fillTypedBooleanGradeIndicesIntSlice(i16, usize, out, slice, ascending),
                .int32 => |slice| fillTypedBooleanGradeIndicesIntSlice(i32, usize, out, slice, ascending),
                .int64 => |slice| fillTypedBooleanGradeIndicesIntSlice(i64, usize, out, slice, ascending),
            },
            else => {
                var count_one: usize = 0;
                for (0..out.len) |idx| {
                    if ((try hostIntDenseViewItem(view, idx)) != 0) count_one += 1;
                }

                var zero_pos: usize = if (ascending) 0 else count_one;
                var one_pos: usize = if (ascending) out.len - count_one else 0;
                for (0..out.len) |idx| {
                    if ((try hostIntDenseViewItem(view, idx)) == 0) {
                        out[zero_pos] = idx;
                        zero_pos += 1;
                    } else {
                        out[one_pos] = idx;
                        one_pos += 1;
                    }
                }
            },
        }
    }

    fn fillBucketGradeIndices(out: []usize, view: HostIntDenseView, range: HostIntRange, ascending: bool, allocator: std.mem.Allocator) KError!void {
        const bucket_count = intGradeRangeLen(range) orelse return error.Unsupported;
        const counts = try allocator.alloc(usize, bucket_count);
        defer allocator.free(counts);
        @memset(counts, 0);

        for (0..out.len) |idx| {
            const value = try hostIntDenseViewItem(view, idx);
            const bucket_i128 = if (ascending)
                @as(i128, value) - @as(i128, range.min)
            else
                @as(i128, range.max) - @as(i128, value);
            counts[@intCast(bucket_i128)] += 1;
        }

        var total: usize = 0;
        for (counts) |*count| {
            const next = total + count.*;
            count.* = total;
            total = next;
        }

        for (0..out.len) |idx| {
            const value = try hostIntDenseViewItem(view, idx);
            const bucket_i128 = if (ascending)
                @as(i128, value) - @as(i128, range.min)
            else
                @as(i128, range.max) - @as(i128, value);
            const bucket: usize = @intCast(bucket_i128);
            out[counts[bucket]] = idx;
            counts[bucket] += 1;
        }
    }

    fn intGradePassCount(kind: HostIntStorageKind) usize {
        return switch (kind) {
            .bit, .int8 => 1,
            .int16 => 2,
            .int32 => 4,
            .int64 => 8,
        };
    }

    fn intGradeKey(value: i64, kind: HostIntStorageKind, ascending: bool) u64 {
        const key = switch (kind) {
            .bit => @as(u64, @intCast(value)),
            .int8 => @as(u64, @as(u8, @bitCast(std.math.cast(i8, value) orelse unreachable)) ^ 0x80),
            .int16 => @as(u64, @as(u16, @bitCast(std.math.cast(i16, value) orelse unreachable)) ^ 0x8000),
            .int32 => @as(u64, @as(u32, @bitCast(std.math.cast(i32, value) orelse unreachable)) ^ 0x8000_0000),
            .int64 => @as(u64, @bitCast(value)) ^ 0x8000_0000_0000_0000,
        };
        return if (ascending) key else ~key;
    }

    fn intGradeKeyTyped(comptime T: type, value: T, ascending: bool) @Int(.unsigned, @bitSizeOf(T)) {
        const KeyT = @Int(.unsigned, @bitSizeOf(T));
        const sign_mask: KeyT = @as(KeyT, 1) << (@bitSizeOf(T) - 1);
        const key = @as(KeyT, @bitCast(value)) ^ sign_mask;
        return if (ascending) key else ~key;
    }

    fn floatGradeKey(value: f64, ascending: bool) ?u64 {
        if (std.math.isNan(value)) return null;
        const key = if (value == 0.0)
            @as(u64, 0x8000_0000_0000_0000)
        else blk: {
            const bits: u64 = @bitCast(value);
            break :blk if ((bits & 0x8000_0000_0000_0000) != 0)
                ~bits
            else
                bits ^ 0x8000_0000_0000_0000;
        };
        return if (ascending) key else ~key;
    }

    fn fillInsertionGradeIndicesIntView(out: []usize, view: HostIntDenseView, ascending: bool) KError!void {
        for (out, 0..) |*slot, idx| slot.* = idx;
        for (1..out.len) |idx| {
            const key_idx = out[idx];
            const key = try hostIntDenseViewItem(view, key_idx);
            var scan = idx;
            while (scan > 0) {
                const prev_idx = out[scan - 1];
                if (!orderComesBefore(std.math.order(key, try hostIntDenseViewItem(view, prev_idx)), ascending)) break;
                out[scan] = prev_idx;
                scan -= 1;
            }
            out[scan] = key_idx;
        }
    }

    fn fillInsertionGradeIndicesFloatView(out: []usize, view: HostFloatDenseView, ascending: bool) KError!void {
        for (out, 0..) |*slot, idx| slot.* = idx;
        for (1..out.len) |idx| {
            const key_idx = out[idx];
            const key = try hostFloatDenseViewItem(view, key_idx);
            var scan = idx;
            while (scan > 0) {
                const prev_idx = out[scan - 1];
                if (!orderComesBefore(std.math.order(key, try hostFloatDenseViewItem(view, prev_idx)), ascending)) break;
                out[scan] = prev_idx;
                scan -= 1;
            }
            out[scan] = key_idx;
        }
    }

    fn fillReverseMonotonicGradeIndicesIntView(out: []usize, view: HostIntDenseView) KError!bool {
        var out_idx: usize = 0;
        var scan = out.len;
        var unique = true;
        while (scan > 0) {
            const run_end = scan;
            const run_value = try hostIntDenseViewItem(view, run_end - 1);
            scan -= 1;
            while (scan > 0 and (try hostIntDenseViewItem(view, scan - 1)) == run_value) : (scan -= 1) {
                unique = false;
            }
            for (scan..run_end) |idx| {
                out[out_idx] = idx;
                out_idx += 1;
            }
        }
        return unique;
    }

    fn fillReverseMonotonicGradeIndicesFloatView(out: []usize, view: HostFloatDenseView) KError!bool {
        var out_idx: usize = 0;
        var scan = out.len;
        var unique = true;
        while (scan > 0) {
            const run_end = scan;
            const run_value = try hostFloatDenseViewItem(view, run_end - 1);
            scan -= 1;
            while (scan > 0 and std.math.order(try hostFloatDenseViewItem(view, scan - 1), run_value) == .eq) : (scan -= 1) {
                unique = false;
            }
            for (scan..run_end) |idx| {
                out[out_idx] = idx;
                out_idx += 1;
            }
        }
        return unique;
    }

    fn fillTypedBucketGradeIndicesIntSlice(
        comptime T: type,
        comptime IdxT: type,
        out: []IdxT,
        items: []const T,
        range: HostIntRange,
        ascending: bool,
        allocator: std.mem.Allocator,
    ) KError!void {
        const bucket_count = intGradeRangeLen(range) orelse return error.Unsupported;
        const counts = try allocator.alloc(usize, bucket_count);
        defer allocator.free(counts);
        @memset(counts, 0);

        for (items) |item| {
            const value: i64 = item;
            const bucket_i128 = if (ascending)
                @as(i128, value) - @as(i128, range.min)
            else
                @as(i128, range.max) - @as(i128, value);
            counts[@intCast(bucket_i128)] += 1;
        }

        var total: usize = 0;
        for (counts) |*count| {
            const next = total + count.*;
            count.* = total;
            total = next;
        }

        for (items, 0..) |item, idx| {
            const value: i64 = item;
            const bucket_i128 = if (ascending)
                @as(i128, value) - @as(i128, range.min)
            else
                @as(i128, range.max) - @as(i128, value);
            const bucket: usize = @intCast(bucket_i128);
            out[counts[bucket]] = @intCast(idx);
            counts[bucket] += 1;
        }
    }

    fn fillRadixGradeIndicesTypedIntSlice(
        comptime T: type,
        comptime IdxT: type,
        out: []IdxT,
        items: []const T,
        ascending: bool,
        allocator: std.mem.Allocator,
    ) KError!void {
        if (out.len == 0) return;

        const KeyT = @Int(.unsigned, @bitSizeOf(T));
        const keys = try allocator.alloc(KeyT, out.len);
        defer allocator.free(keys);
        var pass_counts: [@sizeOf(KeyT)][256]usize = undefined;
        for (&pass_counts) |*counts| @memset(counts, 0);
        for (items, 0..) |item, idx| {
            const key = intGradeKeyTyped(T, item, ascending);
            keys[idx] = key;
            out[idx] = @intCast(idx);
            for (0..@sizeOf(KeyT)) |pass| {
                const shift: std.math.Log2Int(KeyT) = @intCast(pass * 8);
                const digit = @as(u8, @truncate(key >> shift));
                pass_counts[pass][digit] += 1;
            }
        }

        const scratch = try allocator.alloc(IdxT, out.len);
        defer allocator.free(scratch);
        const scratch_keys = try allocator.alloc(KeyT, out.len);
        defer allocator.free(scratch_keys);

        var active_passes = @as([@sizeOf(KeyT)]bool, @splat(false));
        for (0..@sizeOf(KeyT)) |pass| {
            active_passes[pass] = true;
            for (pass_counts[pass]) |count| {
                if (count == out.len) {
                    active_passes[pass] = false;
                    break;
                }
            }
        }

        var src: []IdxT = out;
        var dst: []IdxT = scratch;
        var src_keys: []KeyT = keys;
        var dst_keys: []KeyT = scratch_keys;
        for (0..@sizeOf(KeyT)) |pass| {
            if (!active_passes[pass]) continue;
            var counts = pass_counts[pass];
            const shift: std.math.Log2Int(KeyT) = @intCast(pass * 8);
            var total: usize = 0;
            for (counts[0..]) |*count| {
                const next = total + count.*;
                count.* = total;
                total = next;
            }

            for (src_keys, src) |key, idx| {
                const digit = @as(u8, @truncate(key >> shift));
                const out_idx = counts[digit];
                counts[digit] = out_idx + 1;
                dst[out_idx] = idx;
                dst_keys[out_idx] = key;
            }

            const tmp = src;
            src = dst;
            dst = tmp;
            const tmp_keys = src_keys;
            src_keys = dst_keys;
            dst_keys = tmp_keys;
        }

        if (src.ptr != out.ptr) @memcpy(out, src);
    }

    fn fillRadixGradeIndicesTypedFloatSlice(comptime IdxT: type, out: []IdxT, items: []const f64, ascending: bool, allocator: std.mem.Allocator) KError!bool {
        if (out.len == 0) return true;

        const keys = try allocator.alloc(u64, out.len);
        defer allocator.free(keys);
        var pass_counts: [8][256]usize = undefined;
        for (&pass_counts) |*counts| @memset(counts, 0);
        for (items, 0..) |item, idx| {
            const key = floatGradeKey(item, ascending) orelse return false;
            keys[idx] = key;
            out[idx] = @intCast(idx);
            for (0..8) |pass| {
                const shift: u6 = @intCast(pass * 8);
                const digit = @as(u8, @truncate(key >> shift));
                pass_counts[pass][digit] += 1;
            }
        }

        const scratch = try allocator.alloc(IdxT, out.len);
        defer allocator.free(scratch);
        const scratch_keys = try allocator.alloc(u64, out.len);
        defer allocator.free(scratch_keys);

        var active_passes = @as([8]bool, @splat(false));
        for (0..8) |pass| {
            active_passes[pass] = true;
            for (pass_counts[pass]) |count| {
                if (count == out.len) {
                    active_passes[pass] = false;
                    break;
                }
            }
        }

        var src: []IdxT = out;
        var dst: []IdxT = scratch;
        var src_keys: []u64 = keys;
        var dst_keys: []u64 = scratch_keys;
        for (0..8) |pass| {
            if (!active_passes[pass]) continue;
            var counts = pass_counts[pass];
            const shift: u6 = @intCast(pass * 8);
            var total: usize = 0;
            for (counts[0..]) |*count| {
                const next = total + count.*;
                count.* = total;
                total = next;
            }

            for (src_keys, src) |key, idx| {
                const digit = @as(u8, @truncate(key >> shift));
                const out_idx = counts[digit];
                counts[digit] = out_idx + 1;
                dst[out_idx] = idx;
                dst_keys[out_idx] = key;
            }

            const tmp = src;
            src = dst;
            dst = tmp;
            const tmp_keys = src_keys;
            src_keys = dst_keys;
            dst_keys = tmp_keys;
        }

        if (src.ptr != out.ptr) @memcpy(out, src);
        return true;
    }

    fn fillRadixGradeIndicesFloatView(out: []usize, view: HostFloatDenseView, ascending: bool, allocator: std.mem.Allocator) KError!bool {
        if (out.len == 0) return true;

        const keys = try allocator.alloc(u64, out.len);
        defer allocator.free(keys);
        for (0..out.len) |idx| {
            keys[idx] = floatGradeKey(try hostFloatDenseViewItem(view, idx), ascending) orelse return false;
            out[idx] = idx;
        }

        const scratch = try allocator.alloc(usize, out.len);
        defer allocator.free(scratch);

        var counts: [256]usize = undefined;
        var src: []usize = out;
        var dst: []usize = scratch;
        for (0..8) |pass| {
            @memset(counts[0..], 0);
            const shift: u6 = @intCast(pass * 8);
            for (src) |idx| {
                const digit = @as(u8, @truncate(keys[idx] >> shift));
                counts[digit] += 1;
            }

            var total: usize = 0;
            for (counts[0..]) |*count| {
                const next = total + count.*;
                count.* = total;
                total = next;
            }

            for (src) |idx| {
                const digit = @as(u8, @truncate(keys[idx] >> shift));
                dst[counts[digit]] = idx;
                counts[digit] += 1;
            }

            const tmp = src;
            src = dst;
            dst = tmp;
        }

        if (src.ptr != out.ptr) @memcpy(out, src);
        return true;
    }

    fn fillRadixGradeIndices(out: []usize, view: HostIntDenseView, kind: HostIntStorageKind, ascending: bool, allocator: std.mem.Allocator) KError!void {
        if (out.len == 0) return;

        const scratch = try allocator.alloc(usize, out.len);
        defer allocator.free(scratch);
        for (out, 0..) |*slot, idx| slot.* = idx;

        var counts: [256]usize = undefined;
        var src: []usize = out;
        var dst: []usize = scratch;
        const pass_count = intGradePassCount(kind);
        for (0..pass_count) |pass| {
            @memset(counts[0..], 0);
            const shift: u6 = @intCast(pass * 8);
            for (src) |idx| {
                const digit = @as(u8, @truncate(intGradeKey(try hostIntDenseViewItem(view, idx), kind, ascending) >> shift));
                counts[digit] += 1;
            }

            var total: usize = 0;
            for (counts[0..]) |*count| {
                const next = total + count.*;
                count.* = total;
                total = next;
            }

            for (src) |idx| {
                const digit = @as(u8, @truncate(intGradeKey(try hostIntDenseViewItem(view, idx), kind, ascending) >> shift));
                dst[counts[digit]] = idx;
                counts[digit] += 1;
            }

            const tmp = src;
            src = dst;
            dst = tmp;
        }

        if (src.ptr != out.ptr) @memcpy(out, src);
    }

