                .int32 => |slice| fillTypedReverseMonotonicGradeIndicesIntSlice(i32, i16, dest.items, slice),
                .int64 => |slice| fillTypedReverseMonotonicGradeIndicesIntSlice(i64, i16, dest.items, slice),
