    fn managedHostDenseFloatRadixGradeValue(self: *Session, items: []const f64, ascending: bool) KError!?Value {
        const len = items.len;
        const max_value = try gradeResultMaxValue(len);
        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_value), len);
        if (!try fillManagedDenseFloatRadixGradeResult(self, &out, items, ascending)) return null;
        return try finalizeManagedGradeResult(self, &out, max_value);
    }

    fn tryFastHostFloatDenseGradeValue(self: *Session, value: Value, view: HostFloatDenseView, ascending: bool) KError!?Value {
        const len = hostFloatDenseViewLen(view);
        if (len <= 1) return try newRangeIotaValue(self, .managed, len);
        const flags = hostFloatDenseValueFlags(value, view);
        if (try self.tryMonotonicGradeValue(len, flags, ascending)) |result| return result;

        const mono = monotonicFlags(flags);
        const reverse_flag = if (ascending) host_dense_flag_dsc else host_dense_flag_asc;
        if ((mono & reverse_flag) != 0) {
            return switch (view) {
                .dense => |items| blk: {
                    const result = try self.managedHostDenseFloatReverseMonotonicGradeValue(items);
                    if (result.unique) break :blk try self.reverseIndexValue(len);
                    break :blk result.value;
                },
                else => blk: {
                    if (len <= small_grade_stack_threshold) {
                        var idxs_buf: [small_grade_stack_threshold]usize = undefined;
                        const idxs = idxs_buf[0..len];
                        const unique = try fillReverseMonotonicGradeIndicesFloatView(idxs, view);
                        if (unique) break :blk try self.reverseIndexValue(len);
                        break :blk try self.managedHostIndexArrayValue(idxs);
                    }

                    const idxs = try self.allocator.alloc(usize, len);
                    defer self.allocator.free(idxs);
                    const unique = try fillReverseMonotonicGradeIndicesFloatView(idxs, view);
                    if (unique) break :blk try self.reverseIndexValue(len);
                    break :blk try self.managedHostIndexArrayValue(idxs);
                },
            };
        }

        if (len <= small_dense_float_grade_threshold) {
            return switch (view) {
                .dense => |items| try self.managedHostDenseFloatInsertionGradeValue(items, ascending),
                else => blk: {
                    var idxs_buf: [small_grade_stack_threshold]usize = undefined;
                    const idxs = idxs_buf[0..len];
                    try fillInsertionGradeIndicesFloatView(idxs, view, ascending);
                    break :blk try self.managedHostIndexArrayValue(idxs);
                },
            };
        }

        return switch (view) {
            .dense => |items| try self.managedHostDenseFloatRadixGradeValue(items, ascending),
            else => blk: {
                const idxs = try self.allocator.alloc(usize, len);
                defer self.allocator.free(idxs);

                const fast = try fillRadixGradeIndicesFloatView(idxs, view, ascending, self.allocator);
                if (fast) break :blk try self.managedHostIndexArrayValue(idxs);
                break :blk null;
            },
        };
    }

    fn tryFastHostIntDenseGradeValue(self: *Session, value: Value, view: HostIntDenseView, ascending: bool) KError!?Value {
        const len = hostIntDenseViewLen(view);
        if (len <= 1) return try newRangeIotaValue(self, .managed, len);

        const flags = hostIntDenseValueFlags(value, view);
        if (try self.tryMonotonicGradeValue(len, flags, ascending)) |result| return result;

        const range = hostIntDenseValueRange(value, view);
        const mono = monotonicFlags(flags);
        const reverse_flag = if (ascending) host_dense_flag_dsc else host_dense_flag_asc;
        if ((mono & reverse_flag) != 0) {
            switch (view) {
                .dense => |items| {
                    const result = try self.managedHostDenseIntReverseMonotonicGradeValue(items);
                    if (result.unique) return try self.reverseIndexValue(len);
                    return result.value;
                },
                .range_iota => {
                    return try self.reverseIndexValue(len);
                },
                else => {
                    if (len <= small_grade_stack_threshold) {
                        var idxs_buf: [small_grade_stack_threshold]usize = undefined;
                        const idxs = idxs_buf[0..len];
                        const unique = try fillReverseMonotonicGradeIndicesIntView(idxs, view);
                        if (unique) return try self.reverseIndexValue(len);
                        return try self.managedHostIndexArrayValue(idxs);
                    }

                    const idxs = try self.allocator.alloc(usize, len);
                    defer self.allocator.free(idxs);
                    const unique = try fillReverseMonotonicGradeIndicesIntView(idxs, view);
                    if (unique) return try self.reverseIndexValue(len);
                    return try self.managedHostIndexArrayValue(idxs);
                },
            }
        }

        switch (view) {
            .dense => |items| {
                if (range.min >= 0 and range.max <= 1) {
                    return try self.managedHostBooleanGradeValue(view, len, ascending);
                }

                const small_dense_threshold = switch (items) {
                    .int8 => small_dense_int8_grade_threshold,
                    .int16 => small_dense_int16_grade_threshold,
                    .int32 => small_dense_int32_grade_threshold,
                    .int64 => small_dense_int64_grade_threshold,
                    .bit => small_grade_stack_threshold,
                };
                if (len <= small_dense_threshold) {
                    return try self.managedHostDenseIntInsertionGradeValue(items, ascending);
                }

                switch (items) {
                    .int8 => |slice| return try self.managedHostInt8GradeValue(slice, ascending),
                    .int16 => |slice| {
                        if (len <= 1024) {
                            if (try self.tryManagedHostInt16LowUniqueGradeValue(slice, ascending)) |result| return result;
                        }
                        if (len < (1 << 15)) return try self.managedHostInt16RadixGradeValue(slice, ascending);
                    },
                    .int32 => |slice| {
                        if (try self.tryManagedHostInt32LowUniqueGradeValue(slice, ascending)) |result| return result;
                    },
                    .int64 => |slice| {
                        if (try self.tryManagedHostInt64LowUniqueGradeValue(slice, ascending)) |result| return result;
                    },
                    else => {},
                }

                if (intGradeRangeLen(range)) |range_len| {
                    if (preferBucketIntGrade(len, range_len)) {
                        return try self.managedHostDenseIntBucketGradeValue(items, range, ascending);
                    }
                }

                return try self.managedHostDenseIntRadixGradeValue(items, ascending);
            },
            else => {
                if (range.min >= 0 and range.max <= 1) {
                    return try self.managedHostBooleanGradeValue(view, len, ascending);
                }

                if (len <= small_grade_stack_threshold) {
                    var idxs_buf: [small_grade_stack_threshold]usize = undefined;
                    const idxs = idxs_buf[0..len];
                    try fillInsertionGradeIndicesIntView(idxs, view, ascending);
                    return try self.managedHostIndexArrayValue(idxs);
                }

                const idxs = try self.allocator.alloc(usize, len);
                defer self.allocator.free(idxs);

                if (intGradeRangeLen(range)) |range_len| {
                    if (preferBucketIntGrade(len, range_len)) {
                        try fillBucketGradeIndices(idxs, view, range, ascending, self.allocator);
                        return try self.managedHostIndexArrayValue(idxs);
                    }
                }

                try fillRadixGradeIndices(idxs, view, hostIntStorageKindForRange(range.min, range.max), ascending, self.allocator);
                return try self.managedHostIndexArrayValue(idxs);
            },
        }
    }

    fn gradeValue(self: *Session, value: Value, ascending: bool) KError!Value {
        if (value.tag() == .array and value.arrayKind() == .host_keyed_store) {
            const store = value.asHostKeyedStore();
            if (store.layout == .dict) return try self.gradeDictValue(store, ascending);
        }
        if (stringSourceInfo(value)) |source| {
            return try self.managedStringByteGradeValue(source.bytes(), ascending);
        }
        if (NumericStructuralView.init(value)) |structural| {
            if (try numericStructuralGradeValue(self, structural, ascending)) |result| {
                if (self.debugDetailedProbeActive()) self.debug.grade_structural_numeric_fast_count += 1;
                return result;
            }
        }
        if (valueNumericMode(value) != null) {
            if (numericVectorLen(value)) |len| {
                if (hostDenseIfPresent(value) != null or numericValueSupportsStructuralFlatItemsWithoutHost(value)) {
                    const view = try hostDenseView(self, value);
                    switch (view) {
                        .int_array => |items| {
                            if (try self.tryFastHostIntDenseGradeValue(value, items, ascending)) |result| {
                                if (self.debugDetailedProbeActive()) self.debug.grade_structural_numeric_fast_count += 1;
                                return result;
                            }
                        },
                        .float_array => |items| {
                            if (try self.tryFastHostFloatDenseGradeValue(value, items, ascending)) |result| {
                                if (self.debugDetailedProbeActive()) self.debug.grade_structural_numeric_fast_count += 1;
                                return result;
                            }
                        },
                        else => {},
                    }
                    const idxs = try self.allocator.alloc(usize, len);
                    defer self.allocator.free(idxs);
                    for (idxs, 0..) |*slot, idx| slot.* = idx;
                    try self.stableMergeSortIndices(idxs, ascending, value, numericVectorIndexedOrder);
                    if (self.debugDetailedProbeActive()) self.debug.grade_structural_numeric_fast_count += 1;
                    return try self.managedHostIndexArrayValue(idxs);
                }
            }
        }
        if (valueNumericMatrixView(value)) |matrix| {
            if (try self.tryFastHostNumericMatrixGradeValue(value, ascending)) |result| {
                if (self.debugDetailedProbeActive()) self.debug.grade_structural_numeric_fast_count += 1;
                return result;
            }
            const idxs = try self.allocator.alloc(usize, matrix.shape.rows);
            defer self.allocator.free(idxs);
            for (idxs, 0..) |*slot, idx| slot.* = idx;
            try self.stableMergeSortIndices(idxs, ascending, matrix, numericMatrixIndexedOrder);
            if (self.debugDetailedProbeActive()) self.debug.grade_structural_numeric_fast_count += 1;
            return try self.managedHostIndexArrayValue(idxs);
        }
        const array = try numericHostArrayValue(self, value);
        const matrix_shape = valueNumericMatrixShape(value);
        const len = if (matrix_shape) |shape| shape.rows else array.len();
        const idxs = try self.allocator.alloc(usize, len);
        defer self.allocator.free(idxs);
        for (idxs, 0..) |*slot, idx| slot.* = idx;
        try self.stableMergeSortIndices(idxs, ascending, HostIndexedOrderContext{ .array = array, .matrix_cols = if (matrix_shape) |shape| shape.cols else null }, hostIndexedOrder);
        return try self.managedHostIndexArrayValue(idxs);
    }

    fn fillSortedBitWords(words: []u64, len: usize, count_one: usize, ascending: bool) void {
        if (words.len == 0) return;
        if (ascending) {
            const count_zero = len - count_one;
            const boundary_word = count_zero / host_bit_word_bits;
            const boundary_bit = count_zero % host_bit_word_bits;
            @memset(words[0..boundary_word], 0);
            if (boundary_word == words.len) return;
            if (boundary_bit == 0) {
                @memset(words[boundary_word..], std.math.maxInt(u64));
            } else {
                words[boundary_word] = ~bitLowMask(boundary_bit);
                @memset(words[boundary_word + 1 ..], std.math.maxInt(u64));
            }
            return;
        }

        const boundary_word = count_one / host_bit_word_bits;
        const boundary_bit = count_one % host_bit_word_bits;
        @memset(words[0..boundary_word], std.math.maxInt(u64));
        if (boundary_word == words.len) return;
        if (boundary_bit == 0) {
            @memset(words[boundary_word..], 0);
        } else {
            words[boundary_word] = bitLowMask(boundary_bit);
            @memset(words[boundary_word + 1 ..], 0);
        }
    }

    fn sortSelfGradeBitValue(self: *Session, bits: HostBitSlice, ascending: bool) KError!Value {
        const count_one = bitCountTrue(bits);
        const out = try self.allocHostBitArrayUninitialized(.managed, bits.len);
        fillSortedBitWords(out.words, bits.len, count_one, ascending);
        const all_equal = count_one == 0 or count_one == bits.len;
        const flags = host_dense_flag_normalized |
            (if (ascending or all_equal) host_dense_flag_asc else 0) |
            (if (!ascending or all_equal) host_dense_flag_dsc else 0);
        return try self.finishManagedHostBitAlloc(out, flags, .{
            .min = if (count_one == bits.len and bits.len != 0) 1 else 0,
            .max = if (count_one == 0) 0 else 1,
        });
    }

    fn int8ValueForGradeBucket(bucket: usize) i8 {
        const raw: u8 = @intCast(bucket);
        return @bitCast(raw ^ 0x80);
    }

    fn int16GradeBucket(item: i16) u16 {
        return @as(u16, @bitCast(item)) ^ 0x8000;
    }

    fn int16ValueForGradeBucket(bucket: usize) i16 {
        const raw: u16 = @intCast(bucket);
        return @bitCast(raw ^ 0x8000);
    }

    fn int16SortKey(item: i16, ascending: bool) u16 {
        const key = int16GradeBucket(item);
        return if (ascending) key else ~key;
    }

    fn int32GradeBucket(item: i32) u32 {
        return @as(u32, @bitCast(item)) ^ 0x8000_0000;
    }

    fn int32SortKey(item: i32, ascending: bool) u32 {
        const key = int32GradeBucket(item);
        return if (ascending) key else ~key;
    }

    fn int64SortKey(item: i64, ascending: bool) u64 {
        const key = @as(u64, @bitCast(item)) ^ 0x8000_0000_0000_0000;
        return if (ascending) key else ~key;
    }

    fn fillTypedInt16RadixGradeResult(comptime IdxT: type, out: []IdxT, items: []const i16, ascending: bool, allocator: std.mem.Allocator) KError!void {
        var count0: [256]usize = undefined;
        var count1: [256]usize = undefined;
        @memset(count0[0..], 0);
        @memset(count1[0..], 0);

        for (items) |item| {
            const key = int16SortKey(item, ascending);
            count0[@as(u8, @truncate(key))] += 1;
            count1[@as(u8, @truncate(key >> 8))] += 1;
        }

        var total: usize = 0;
        for (count0[0..]) |*count| {
            const next = total + count.*;
            count.* = total;
            total = next;
        }
        total = 0;
        for (count1[0..]) |*count| {
            const next = total + count.*;
            count.* = total;
            total = next;
        }

        const tmp_values = try allocator.alloc(i16, items.len);
        defer allocator.free(tmp_values);
        const tmp_indices = try allocator.alloc(IdxT, items.len);
        defer allocator.free(tmp_indices);

        for (items, 0..) |item, idx| {
            const key = int16SortKey(item, ascending);
            const digit = @as(u8, @truncate(key));
            const out_idx = count0[digit];
            count0[digit] = out_idx + 1;
            tmp_values[out_idx] = item;
            tmp_indices[out_idx] = @intCast(idx);
        }

        for (tmp_values, tmp_indices) |item, idx| {
            const key = int16SortKey(item, ascending);
            const digit = @as(u8, @truncate(key >> 8));
            const out_idx = count1[digit];
            count1[digit] = out_idx + 1;
            out[out_idx] = idx;
        }
    }

    fn managedHostInt16RadixGradeValue(self: *Session, items: []const i16, ascending: bool) KError!Value {
        const max_value = try gradeResultMaxValue(items.len);
        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_value), items.len);
        switch (out) {
            .bit => unreachable,
            .int8 => |*dest| try fillTypedInt16RadixGradeResult(i8, dest.items, items, ascending, self.allocator),
            .int16 => |*dest| try fillTypedInt16RadixGradeResult(i16, dest.items, items, ascending, self.allocator),
            .int32 => |*dest| try fillTypedInt16RadixGradeResult(i32, dest.items, items, ascending, self.allocator),
            .int64 => |*dest| try fillTypedInt16RadixGradeResult(i64, dest.items, items, ascending, self.allocator),
        }
        return try self.finishManagedGradeResultWithFlags(&out, max_value, host_dense_flag_normalized);
    }

    const dense_int16_low_unique_grade_max: usize = 64;

    fn sortedInt16LowUniqueCounts(items: []const i16, values_buf: *[dense_int16_low_unique_grade_max]i16, counts_buf: *[dense_int16_low_unique_grade_max]usize, ascending: bool) ?usize {
        var unique_count: usize = 0;

        for (items) |item| {
            var found: ?usize = null;
            for (values_buf[0..unique_count], 0..) |value, idx| {
                if (value == item) {
                    found = idx;
                    break;
                }
            }
            if (found) |idx| {
                counts_buf[idx] += 1;
                continue;
            }
            if (unique_count == dense_int16_low_unique_grade_max) return null;
            values_buf[unique_count] = item;
            counts_buf[unique_count] = 1;
            unique_count += 1;
        }

        const values = values_buf[0..unique_count];
        const counts = counts_buf[0..unique_count];
        for (1..unique_count) |idx| {
            const value = values[idx];
            const count = counts[idx];
            var scan = idx;
            while (scan > 0 and orderComesBefore(std.math.order(value, values[scan - 1]), ascending)) {
                values[scan] = values[scan - 1];
                counts[scan] = counts[scan - 1];
                scan -= 1;
            }
            values[scan] = value;
            counts[scan] = count;
        }

        return unique_count;
    }

    fn sortedInt16Bucket(values: []const i16, item: i16, ascending: bool) usize {
        var lo: usize = 0;
        var hi: usize = values.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const before = if (ascending) values[mid] < item else values[mid] > item;
            if (before) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    fn fillTypedInt16LowUniqueGradeResult(comptime IdxT: type, out: []IdxT, items: []const i16, values: []const i16, starts: []usize, ascending: bool) void {
        for (items, 0..) |item, idx| {
            const bucket = sortedInt16Bucket(values, item, ascending);
            std.debug.assert(bucket < values.len and values[bucket] == item);
            const out_idx = starts[bucket];
            starts[bucket] = out_idx + 1;
            out[out_idx] = @intCast(idx);
        }
    }

    fn tryManagedHostInt16LowUniqueGradeValue(self: *Session, items: []const i16, ascending: bool) KError!?Value {
        var values_buf: [dense_int16_low_unique_grade_max]i16 = undefined;
        var counts_buf: [dense_int16_low_unique_grade_max]usize = undefined;
        const unique_count = sortedInt16LowUniqueCounts(items, &values_buf, &counts_buf, ascending) orelse return null;

        const values = values_buf[0..unique_count];
        const counts = counts_buf[0..unique_count];
        var total: usize = 0;
        for (counts) |*count| {
            const next = total + count.*;
            count.* = total;
            total = next;
        }

        const max_value = try gradeResultMaxValue(items.len);
        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_value), items.len);
        switch (out) {
            .bit => unreachable,
            .int8 => |*dest| fillTypedInt16LowUniqueGradeResult(i8, dest.items, items, values, counts, ascending),
            .int16 => |*dest| fillTypedInt16LowUniqueGradeResult(i16, dest.items, items, values, counts, ascending),
            .int32 => |*dest| fillTypedInt16LowUniqueGradeResult(i32, dest.items, items, values, counts, ascending),
            .int64 => |*dest| fillTypedInt16LowUniqueGradeResult(i64, dest.items, items, values, counts, ascending),
        }
        return try self.finishManagedGradeResultWithFlags(&out, max_value, host_dense_flag_normalized);
    }

    const dense_int32_low_unique_grade_max: usize = 64;
    const dense_int32_low_unique_table_size: usize = 128;

    fn int32LowUniqueHashSlot(item: i32) usize {
        var x: u32 = @bitCast(item);
        x ^= x >> 16;
        x *%= @as(u32, 0x7feb_352d);
        x ^= x >> 15;
        x *%= @as(u32, 0x846c_a68b);
        x ^= x >> 16;
        return @intCast(x & (dense_int32_low_unique_table_size - 1));
    }

    fn sortedInt32LowUniqueCounts(items: []const i32, values_buf: *[dense_int32_low_unique_grade_max]i32, counts_buf: *[dense_int32_low_unique_grade_max]usize, ascending: bool) ?usize {
        var table = @as([dense_int32_low_unique_table_size]u8, @splat(0));
        var unique_count: usize = 0;

        for (items) |item| {
            var slot = int32LowUniqueHashSlot(item);
            while (true) {
                const encoded = table[slot];
                if (encoded == 0) {
                    if (unique_count == dense_int32_low_unique_grade_max) return null;
                    values_buf[unique_count] = item;
                    counts_buf[unique_count] = 1;
                    table[slot] = @intCast(unique_count + 1);
                    unique_count += 1;
                    break;
                }

                const value_idx: usize = @intCast(encoded - 1);
                if (values_buf[value_idx] == item) {
                    counts_buf[value_idx] += 1;
                    break;
                }
                slot = (slot + 1) & (dense_int32_low_unique_table_size - 1);
            }
        }

        const values = values_buf[0..unique_count];
        const counts = counts_buf[0..unique_count];
        for (1..unique_count) |idx| {
            const value = values[idx];
            const count = counts[idx];
            var scan = idx;
            while (scan > 0 and orderComesBefore(std.math.order(value, values[scan - 1]), ascending)) {
                values[scan] = values[scan - 1];
                counts[scan] = counts[scan - 1];
                scan -= 1;
            }
            values[scan] = value;
            counts[scan] = count;
        }

        return unique_count;
    }

    fn sortedInt32Bucket(values: []const i32, item: i32, ascending: bool) usize {
        var lo: usize = 0;
        var hi: usize = values.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const before = if (ascending) values[mid] < item else values[mid] > item;
            if (before) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    fn fillTypedInt32LowUniqueGradeResult(comptime IdxT: type, out: []IdxT, items: []const i32, values: []const i32, starts: []usize, ascending: bool) void {
        for (items, 0..) |item, idx| {
            const bucket = sortedInt32Bucket(values, item, ascending);
            std.debug.assert(bucket < values.len and values[bucket] == item);
            const out_idx = starts[bucket];
            starts[bucket] = out_idx + 1;
            out[out_idx] = @intCast(idx);
        }
    }

    fn tryManagedHostInt32LowUniqueGradeValue(self: *Session, items: []const i32, ascending: bool) KError!?Value {
        var values_buf: [dense_int32_low_unique_grade_max]i32 = undefined;
        var counts_buf: [dense_int32_low_unique_grade_max]usize = undefined;
        const unique_count = sortedInt32LowUniqueCounts(items, &values_buf, &counts_buf, ascending) orelse return null;

        const values = values_buf[0..unique_count];
        const counts = counts_buf[0..unique_count];
        var total: usize = 0;
        for (counts) |*count| {
            const next = total + count.*;
            count.* = total;
            total = next;
        }

        const max_value = try gradeResultMaxValue(items.len);
        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_value), items.len);
        switch (out) {
            .bit => unreachable,
            .int8 => |*dest| fillTypedInt32LowUniqueGradeResult(i8, dest.items, items, values, counts, ascending),
            .int16 => |*dest| fillTypedInt32LowUniqueGradeResult(i16, dest.items, items, values, counts, ascending),
            .int32 => |*dest| fillTypedInt32LowUniqueGradeResult(i32, dest.items, items, values, counts, ascending),
            .int64 => |*dest| fillTypedInt32LowUniqueGradeResult(i64, dest.items, items, values, counts, ascending),
        }
        return try self.finishManagedGradeResultWithFlags(&out, max_value, host_dense_flag_normalized);
    }

    const dense_int64_low_unique_grade_max: usize = 64;
    const dense_int64_low_unique_table_size: usize = 128;

    fn int64LowUniqueHashSlot(item: i64) usize {
        var x: u64 = @bitCast(item);
        x ^= x >> 33;
        x *%= @as(u64, 0xff51_afd7_ed55_8ccd);
        x ^= x >> 33;
        x *%= @as(u64, 0xc4ce_b9fe_1a85_ec53);
        x ^= x >> 33;
        return @intCast(x & (dense_int64_low_unique_table_size - 1));
    }

    fn sortedInt64LowUniqueCounts(items: []const i64, values_buf: *[dense_int64_low_unique_grade_max]i64, counts_buf: *[dense_int64_low_unique_grade_max]usize, ascending: bool) ?usize {
        var table = @as([dense_int64_low_unique_table_size]u8, @splat(0));
        var unique_count: usize = 0;

        for (items) |item| {
            var slot = int64LowUniqueHashSlot(item);
            while (true) {
                const encoded = table[slot];
                if (encoded == 0) {
                    if (unique_count == dense_int64_low_unique_grade_max) return null;
                    values_buf[unique_count] = item;
                    counts_buf[unique_count] = 1;
                    table[slot] = @intCast(unique_count + 1);
                    unique_count += 1;
                    break;
                }

                const value_idx: usize = @intCast(encoded - 1);
                if (values_buf[value_idx] == item) {
                    counts_buf[value_idx] += 1;
                    break;
                }
                slot = (slot + 1) & (dense_int64_low_unique_table_size - 1);
            }
        }

        const values = values_buf[0..unique_count];
        const counts = counts_buf[0..unique_count];
        for (1..unique_count) |idx| {
            const value = values[idx];
            const count = counts[idx];
            var scan = idx;
            while (scan > 0 and orderComesBefore(std.math.order(value, values[scan - 1]), ascending)) {
                values[scan] = values[scan - 1];
                counts[scan] = counts[scan - 1];
                scan -= 1;
            }
            values[scan] = value;
            counts[scan] = count;
        }

        return unique_count;
    }

    fn sortedInt64Bucket(values: []const i64, item: i64, ascending: bool) usize {
        var lo: usize = 0;
        var hi: usize = values.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const before = if (ascending) values[mid] < item else values[mid] > item;
            if (before) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    fn fillTypedInt64LowUniqueGradeResult(comptime IdxT: type, out: []IdxT, items: []const i64, values: []const i64, starts: []usize, ascending: bool) void {
        for (items, 0..) |item, idx| {
            const bucket = sortedInt64Bucket(values, item, ascending);
            std.debug.assert(bucket < values.len and values[bucket] == item);
            const out_idx = starts[bucket];
            starts[bucket] = out_idx + 1;
            out[out_idx] = @intCast(idx);
        }
    }

    fn tryManagedHostInt64LowUniqueGradeValue(self: *Session, items: []const i64, ascending: bool) KError!?Value {
        var values_buf: [dense_int64_low_unique_grade_max]i64 = undefined;
        var counts_buf: [dense_int64_low_unique_grade_max]usize = undefined;
        const unique_count = sortedInt64LowUniqueCounts(items, &values_buf, &counts_buf, ascending) orelse return null;

        const values = values_buf[0..unique_count];
        const counts = counts_buf[0..unique_count];
        var total: usize = 0;
        for (counts) |*count| {
            const next = total + count.*;
            count.* = total;
            total = next;
        }

        const max_value = try gradeResultMaxValue(items.len);
        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(0, max_value), items.len);
        switch (out) {
            .bit => unreachable,
            .int8 => |*dest| fillTypedInt64LowUniqueGradeResult(i8, dest.items, items, values, counts, ascending),
            .int16 => |*dest| fillTypedInt64LowUniqueGradeResult(i16, dest.items, items, values, counts, ascending),
            .int32 => |*dest| fillTypedInt64LowUniqueGradeResult(i32, dest.items, items, values, counts, ascending),
            .int64 => |*dest| fillTypedInt64LowUniqueGradeResult(i64, dest.items, items, values, counts, ascending),
        }
        return try self.finishManagedGradeResultWithFlags(&out, max_value, host_dense_flag_normalized);
    }

    fn sortSelfGradeDenseInt8Value(self: *Session, items: []const i8, ascending: bool) KError!Value {
        var counts: [256]usize = undefined;
        @memset(counts[0..], 0);
        for (items) |item| counts[int8GradeBucket(item)] += 1;

        var out = try self.allocManagedHostIntResult(.int8, items.len);
        const dest = switch (out) {
            .int8 => |*alloc| alloc.items,
            else => unreachable,
        };

        var write_idx: usize = 0;
        var non_empty_buckets: usize = 0;
        var min_value: i64 = 0;
        var max_value: i64 = 0;
        var bucket_iter: usize = 0;
        while (bucket_iter < counts.len) : (bucket_iter += 1) {
            const bucket = if (ascending) bucket_iter else counts.len - 1 - bucket_iter;
            const count = counts[bucket];
            if (count == 0) continue;

            const value = int8ValueForGradeBucket(bucket);
            if (non_empty_buckets == 0) {
                min_value = value;
                max_value = value;
            } else {
                min_value = @min(min_value, value);
                max_value = @max(max_value, value);
            }
            non_empty_buckets += 1;
            @memset(dest[write_idx .. write_idx + count], value);
            write_idx += count;
        }

        const all_equal = non_empty_buckets <= 1;
        const flags = host_dense_flag_normalized |
            (if (ascending or all_equal) host_dense_flag_asc else 0) |
            (if (!ascending or all_equal) host_dense_flag_dsc else 0);
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, flags);
        hostDenseSetCachedIntRange(host, .{ .min = min_value, .max = max_value });
        return value;
    }

