    fn sortSelfGradeDenseInt16RadixValue(self: *Session, items: []const i16, ascending: bool) KError!Value {
        var count0: [256]usize = undefined;
        var count1: [256]usize = undefined;
        @memset(count0[0..], 0);
        @memset(count1[0..], 0);

        var min_value: i64 = 0;
        var max_value: i64 = 0;
        for (items, 0..) |item, idx| {
            const key = int16SortKey(item, ascending);
            count0[@as(u8, @truncate(key))] += 1;
            count1[@as(u8, @truncate(key >> 8))] += 1;
            if (idx == 0) {
                min_value = item;
                max_value = item;
            } else {
                min_value = @min(min_value, item);
                max_value = @max(max_value, item);
            }
        }

        var total: usize = 0;
        for (count0[0..]) |*count| {
            const next = total + count.*;
            count.* = total;
            total = next;
        }
        total = 0;
        for (count1[0..]) |*count| {
            const next = total + count.*;
            count.* = total;
            total = next;
        }

        const tmp = try self.allocator.alloc(i16, items.len);
        defer self.allocator.free(tmp);

        var out = try self.allocManagedHostIntResult(.int16, items.len);
        const dest = switch (out) {
            .int16 => |*alloc| alloc.items,
            else => unreachable,
        };

        for (items) |item| {
            const key = int16SortKey(item, ascending);
            const digit = @as(u8, @truncate(key));
            const out_idx = count0[digit];
            count0[digit] = out_idx + 1;
            tmp[out_idx] = item;
        }
        for (tmp) |item| {
            const key = int16SortKey(item, ascending);
            const digit = @as(u8, @truncate(key >> 8));
            const out_idx = count1[digit];
            count1[digit] = out_idx + 1;
            dest[out_idx] = item;
        }

        const all_equal = items.len <= 1 or min_value == max_value;
        const flags = host_dense_flag_normalized |
            (if (ascending or all_equal) host_dense_flag_asc else 0) |
            (if (!ascending or all_equal) host_dense_flag_dsc else 0);
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, flags);
        hostDenseSetCachedIntRange(host, .{ .min = min_value, .max = max_value });
        return value;
    }

    fn sortSelfGradeDenseInt16Value(self: *Session, items: []const i16, ascending: bool) KError!Value {
        if (items.len <= 1024) {
            if (try self.trySortSelfGradeDenseInt16LowUniqueValue(items, ascending)) |result| return result;
        }
        if (items.len < (1 << 15)) return try self.sortSelfGradeDenseInt16RadixValue(items, ascending);
        return try self.sortSelfGradeDenseInt16CountingValue(items, ascending);
    }

