    fn sortSelfGradeDenseInt32RadixValue(self: *Session, items: []const i32, ascending: bool) KError!Value {
        var pass_counts: [4][256]usize = undefined;
        for (&pass_counts) |*counts| @memset(counts, 0);

        var min_value: i64 = 0;
        var max_value: i64 = 0;
        for (items, 0..) |item, idx| {
            const key = int32SortKey(item, ascending);
            inline for (0..4) |pass| {
                const shift: u5 = @intCast(pass * 8);
                pass_counts[pass][@as(u8, @truncate(key >> shift))] += 1;
            }
            if (idx == 0) {
                min_value = item;
                max_value = item;
            } else {
                min_value = @min(min_value, item);
                max_value = @max(max_value, item);
            }
        }

        for (&pass_counts) |*counts| {
            var total: usize = 0;
            for (counts[0..]) |*count| {
                const next = total + count.*;
                count.* = total;
                total = next;
            }
        }

        const tmp = try self.allocator.alloc(i32, items.len);
        defer self.allocator.free(tmp);

        var out = try self.allocManagedHostIntResult(.int32, items.len);
        const dest = switch (out) {
            .int32 => |*alloc| alloc.items,
            else => unreachable,
        };

        for (items) |item| {
            const key = int32SortKey(item, ascending);
            const digit = @as(u8, @truncate(key));
            const out_idx = pass_counts[0][digit];
            pass_counts[0][digit] = out_idx + 1;
            tmp[out_idx] = item;
        }
        for (tmp) |item| {
            const key = int32SortKey(item, ascending);
            const digit = @as(u8, @truncate(key >> 8));
            const out_idx = pass_counts[1][digit];
            pass_counts[1][digit] = out_idx + 1;
            dest[out_idx] = item;
        }
        for (dest) |item| {
            const key = int32SortKey(item, ascending);
            const digit = @as(u8, @truncate(key >> 16));
            const out_idx = pass_counts[2][digit];
            pass_counts[2][digit] = out_idx + 1;
            tmp[out_idx] = item;
        }
        for (tmp) |item| {
            const key = int32SortKey(item, ascending);
            const digit = @as(u8, @truncate(key >> 24));
            const out_idx = pass_counts[3][digit];
            pass_counts[3][digit] = out_idx + 1;
            dest[out_idx] = item;
        }

        const all_equal = items.len <= 1 or min_value == max_value;
        const flags = host_dense_flag_normalized |
            (if (ascending or all_equal) host_dense_flag_asc else 0) |
            (if (!ascending or all_equal) host_dense_flag_dsc else 0);
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, flags);
        hostDenseSetCachedIntRange(host, .{ .min = min_value, .max = max_value });
        return value;
    }

    fn sortSelfGradeDenseInt32Value(self: *Session, items: []const i32, ascending: bool) KError!Value {
        if (try self.trySortSelfGradeDenseInt32LowUniqueValue(items, ascending)) |result| return result;
        return try self.sortSelfGradeDenseInt32RadixValue(items, ascending);
    }

