    fn scatterInt64SortPass(src: []const i64, dest: []i64, counts: *[256]usize, comptime shift: u6, ascending: bool) void {
        for (src) |item| {
            const key = int64SortKey(item, ascending);
            const digit = @as(u8, @truncate(key >> shift));
            const out_idx = counts[digit];
            counts[digit] = out_idx + 1;
            dest[out_idx] = item;
        }
    }

    fn sortSelfGradeDenseInt64RadixValue(self: *Session, items: []const i64, ascending: bool) KError!Value {
        var pass_counts: [8][256]usize = undefined;
        for (&pass_counts) |*counts| @memset(counts, 0);

        var min_value: i64 = 0;
        var max_value: i64 = 0;
        for (items, 0..) |item, idx| {
            const key = int64SortKey(item, ascending);
            inline for (0..8) |pass| {
                const shift: u6 = @intCast(pass * 8);
                pass_counts[pass][@as(u8, @truncate(key >> shift))] += 1;
            }
            if (idx == 0) {
                min_value = item;
                max_value = item;
            } else {
                min_value = @min(min_value, item);
                max_value = @max(max_value, item);
            }
        }

        for (&pass_counts) |*counts| {
            var total: usize = 0;
            for (counts[0..]) |*count| {
                const next = total + count.*;
                count.* = total;
                total = next;
            }
        }

        const tmp = try self.allocator.alloc(i64, items.len);
        defer self.allocator.free(tmp);

        var out = try self.allocManagedHostIntResult(.int64, items.len);
        const dest = switch (out) {
            .int64 => |*alloc| alloc.items,
            else => unreachable,
        };

        scatterInt64SortPass(items, tmp, &pass_counts[0], 0, ascending);
        scatterInt64SortPass(tmp, dest, &pass_counts[1], 8, ascending);
        scatterInt64SortPass(dest, tmp, &pass_counts[2], 16, ascending);
        scatterInt64SortPass(tmp, dest, &pass_counts[3], 24, ascending);
        scatterInt64SortPass(dest, tmp, &pass_counts[4], 32, ascending);
        scatterInt64SortPass(tmp, dest, &pass_counts[5], 40, ascending);
        scatterInt64SortPass(dest, tmp, &pass_counts[6], 48, ascending);
        scatterInt64SortPass(tmp, dest, &pass_counts[7], 56, ascending);

        const all_equal = items.len <= 1 or min_value == max_value;
        const flags = host_dense_flag_normalized |
            (if (ascending or all_equal) host_dense_flag_asc else 0) |
            (if (!ascending or all_equal) host_dense_flag_dsc else 0);
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, flags);
        hostDenseSetCachedIntRange(host, .{ .min = min_value, .max = max_value });
        return value;
    }

    fn sortSelfGradeDenseInt64Value(self: *Session, items: []const i64, ascending: bool) KError!Value {
        if (try self.trySortSelfGradeDenseInt64LowUniqueValue(items, ascending)) |result| return result;
        return try self.sortSelfGradeDenseInt64RadixValue(items, ascending);
    }

    fn tryFastSortSelfGradeValue(self: *Session, value: Value, ascending: bool) KError!?Value {
        const array = hostDenseIfPresent(value) orelse return null;
        if (valueNumericMatrixShape(value) != null) return null;
        const target_flag = if (ascending) host_dense_flag_asc else host_dense_flag_dsc;
        if ((monotonicFlags(array.flags) & target_flag) != 0) return self.shareValue(value);
        return switch (array.storage) {
            .bit => try self.sortSelfGradeBitValue(.{ .words = array.storage.bit, .len = array.len() }, ascending),
            .int8 => |items| try self.sortSelfGradeDenseInt8Value(hostDenseLogicalItems(i8, array, items), ascending),
            .int16 => |items| try self.sortSelfGradeDenseInt16Value(hostDenseLogicalItems(i16, array, items), ascending),
            .int32 => |items| try self.sortSelfGradeDenseInt32Value(hostDenseLogicalItems(i32, array, items), ascending),
            .int64 => |items| try self.sortSelfGradeDenseInt64Value(hostDenseLogicalItems(i64, array, items), ascending),
            else => null,
        };
    }

    fn stampSortSelfGradeMetadata(self: *Session, source: Value, result: Value, ascending: bool) void {
        _ = self;
        const result_host = hostDenseIfPresent(result) orelse return;
        if (valueNumericMatrixShape(result) != null) return;
        var flags = host_dense_flag_normalized |
            (if (ascending) host_dense_flag_asc else host_dense_flag_dsc);

        if (result_host.len() <= 1) {
            flags |= host_dense_flag_asc | host_dense_flag_dsc;
        } else if (hostDenseIfPresent(source)) |source_host| {
            if ((monotonicFlags(source_host.flags) == (host_dense_flag_asc | host_dense_flag_dsc))) {
                flags |= host_dense_flag_asc | host_dense_flag_dsc;
            }
        }

        const mutable_result = @constCast(result_host);
        hostDenseSetFlags(mutable_result, flags);

        const source_host = hostDenseIfPresent(source) orelse return;
        if (valueNumericMatrixShape(source) != null) return;
        const source_view = hostIntArrayView(source_host) orelse return;
        const range = hostDenseCachedIntRange(source_host) orelse
            hostIntArrayViewEndpointRange(source_view, source_host.flags) orelse
            return;
        if (hostIntArrayView(result_host) != null) hostDenseSetCachedIntRange(mutable_result, range);
    }

    fn sortSelfGradeValue(self: *Session, value: Value, ascending: bool) KError!Value {
        if (try self.tryFastSortSelfGradeValue(value, ascending)) |result| return result;
        const selector = try self.gradeValue(value, ascending);
        defer self.releaseValue(selector);
        if (valueNumericMatrixShape(value) != null) return try newFirstAxisIndexValue(self, value, selector);
        const result = try self.applyArrayCall1(value, selector);
        self.stampSortSelfGradeMetadata(value, result, ascending);
        return result;
    }

    fn canMutateHostDenseAppend(handle: *const NumericArray, array: *const HostDenseArray) bool {
        if (handle.header.owner != .managed or handle.header.ref_count != 1) return false;
        if (handle.host != array) return false;
        if (handle.mlx != null) return false;
        if (numericArrayStructuralTag(handle) != .materialized) return false;
        if (handle.rank != 1) return false;
        if (@as(usize, @intCast(handle.shape[0])) != array.logical_len) return false;
        return true;
    }

    fn writeHostDenseIntScalar(array: *HostDenseArray, kind: HostIntStorageKind, idx: usize, scalar_int: i64) KError!void {
        switch (kind) {
            .bit => {
                if (scalar_int != 0 and scalar_int != 1) return error.Unsupported;
                bitSet(array.storage.bit, idx, scalar_int == 1);
            },
            .int8 => array.storage.int8[idx] = std.math.cast(i8, scalar_int) orelse return error.Unsupported,
            .int16 => array.storage.int16[idx] = std.math.cast(i16, scalar_int) orelse return error.Unsupported,
            .int32 => array.storage.int32[idx] = std.math.cast(i32, scalar_int) orelse return error.Unsupported,
            .int64 => array.storage.int64[idx] = scalar_int,
        }
    }

    fn tryAppendIntVectorScalarInPlace(
        self: *Session,
        vector: Value,
        view: HostIntDenseView,
        result_kind: HostIntStorageKind,
        scalar_int: i64,
        range: HostIntRange,
        flags: u8,
    ) KError!?Value {
        switch (view) {
            .dense => {},
            else => return null,
        }
        const handle = mutableNumericHandle(vector) orelse return null;
        const array = @constCast(hostDenseIfPresent(vector) orelse return null);
        if (!canMutateHostDenseAppend(handle, array)) return null;

        const old_len = array.logical_len;
        const new_len = std.math.add(usize, old_len, 1) catch return error.Unsupported;
        try self.ensureManagedHostDenseIntCapacity(array, result_kind, new_len);
        try writeHostDenseIntScalar(array, result_kind, old_len, scalar_int);
        array.logical_len = new_len;
        numericArraySetVectorShape(handle, new_len);
        if (result_kind == .bit) bitClearUnusedTail(array.storage.bit, new_len);
        self.clearManagedHostDenseFindCache(array);
        hostDenseSetFlags(array, flags);
        hostDenseSetCachedIntRange(array, range);
        return self.shareValue(vector);
    }

    fn concatIntVectorScalar(self: *Session, vector: Value, view: HostIntDenseView, scalar: Value, scalar_int: i64, scalar_on_right: bool) KError!Value {
        const len = hostIntDenseViewLen(view);
        const total_len = std.math.add(usize, len, 1) catch return error.Unsupported;
        var range = if (len == 0) hostIntRangeForValue(scalar_int) else hostIntDenseValueRange(vector, view);
        if (len != 0) {
            range.min = @min(range.min, scalar_int);
            range.max = @max(range.max, scalar_int);
        }
        const vector_kind = hostIntDenseViewKind(view);
        const kind: HostIntStorageKind = if ((vector_kind == .bit or len == 0) and scalar.tag() == .bool)
            .bit
        else
            hostIntStorageKindForRange(range.min, range.max);
        const vector_flags = hostIntDenseValueFlags(vector, view);
        var asc = len <= 1 or (vector_flags & host_dense_flag_asc) != 0;
        var dsc = len <= 1 or (vector_flags & host_dense_flag_dsc) != 0;
        if (len != 0) {
            const first = try hostIntDenseViewItem(view, 0);
            const last = try hostIntDenseViewItem(view, len - 1);
            if (scalar_on_right) {
                asc = asc and last <= scalar_int;
                dsc = dsc and last >= scalar_int;
            } else {
                asc = asc and scalar_int <= first;
                dsc = dsc and scalar_int >= first;
            }
        }
        const flags = host_dense_flag_normalized | orderFlagsFromMonotonic(asc, dsc);

        if (scalar_on_right) {
            if (try self.tryAppendIntVectorScalarInPlace(vector, view, kind, scalar_int, range, flags)) |result| return result;
        }

        var out = try self.allocManagedHostIntResult(kind, total_len);

        var write_idx: usize = 0;
        if (!scalar_on_right) {
            try out.set(0, scalar_int);
            write_idx = 1;
        }
        for (0..len) |idx| try out.set(write_idx + idx, try hostIntDenseViewItem(view, idx));
        if (scalar_on_right) try out.set(len, scalar_int);

        const result = out.value();
        const host = try mutableNumericHostArrayValue(self, result);
        hostDenseSetFlags(host, flags);
        hostDenseSetCachedIntRange(host, range);
        return result;
    }

    fn concatMixedNumericVectorScalarBoxed(self: *Session, vector: Value, scalar: Value, scalar_on_right: bool) KError!Value {
        var values = std.ArrayList(Value).empty;
        var owned_values = std.ArrayList(Value).empty;
        defer {
            for (owned_values.items) |value| self.releaseValue(value);
            owned_values.deinit(self.allocator);
            values.deinit(self.allocator);
        }
        if (scalar_on_right) {
            try self.appendConcatValue(&values, &owned_values, vector, false);
            try values.append(self.allocator, scalar);
        } else {
            try values.append(self.allocator, scalar);
            try self.appendConcatValue(&values, &owned_values, vector, false);
        }
        return try self.createManagedHostBoxedArray(values.items);
    }

    fn concatFloatVectorScalar(self: *Session, view: HostFloatDenseView, scalar_float: f64, scalar_on_right: bool) KError!Value {
        const len = hostFloatDenseViewLen(view);
        const total_len = std.math.add(usize, len, 1) catch return error.Unsupported;
        const out = try self.allocManagedHostFloatResult(total_len);
        var write_idx: usize = 0;
        if (!scalar_on_right) {
            out.items[0] = scalar_float;
            write_idx = 1;
        }
        for (0..len) |idx| out.items[write_idx + idx] = try hostFloatDenseViewItem(view, idx);
        if (scalar_on_right) out.items[len] = scalar_float;

        const analysis = analyzeFloatSlice(out.items);
        const result = out.value();
        hostDenseSetFlags(try mutableNumericHostArrayValue(self, result), analysis.flags);
        return result;
    }

    fn concatNumericVectorScalar(self: *Session, vector: Value, scalar: Value, scalar_on_right: bool) KError!?Value {
        if (numericVectorLen(vector) == null or valueNumericMatrixShape(vector) != null) return null;
        const scalar_float = inlineNumericFloatValue(scalar) orelse return null;
        const vector_view = hostDenseView(self, vector) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        return switch (vector_view) {
            .int_array => |view| switch (scalar.tag()) {
                .int, .bool => try self.concatIntVectorScalar(vector, view, scalar, inlineExactIntNumericValue(scalar).?, scalar_on_right),
                .float, .float32 => try self.concatMixedNumericVectorScalarBoxed(vector, scalar, scalar_on_right),
                else => null,
            },
            .float_array => |view| switch (scalar.tag()) {
                .float, .float32 => try self.concatFloatVectorScalar(view, scalar_float, scalar_on_right),
                .int, .bool => try self.concatMixedNumericVectorScalarBoxed(vector, scalar, scalar_on_right),
                else => null,
            },
            else => null,
        };
    }

    fn concatValues(self: *Session, left: Value, right: Value) KError!Value {
        if (valueIsTextSequence(left) and valueIsTextSequence(right)) {
            return try self.concatTextSequenceValues(left, right);
        }
        if (left.tag() == .array and right.tag() == .array and
            left.arrayKind() == .host_keyed_store and right.arrayKind() == .host_keyed_store)
        {
            const left_store = left.asHostKeyedStore();
            const right_store = right.asHostKeyedStore();
            if (left_store.layout == .dict and right_store.layout == .dict) {
                return try self.concatKeyedDictValues(left_store, right_store);
            }
            if (left_store.layout == .table and right_store.layout == .table) {
                return try self.concatTableValues(left_store, right_store);
            }
            return error.Type;
        }
        if (try concatNumericMatrixShape(self, left, right)) |shape| {
            if (try concatNumericMatrixValue(self, left, right, shape)) |result| return result;
            var values = std.ArrayList(Value).empty;
            var owned_values = std.ArrayList(Value).empty;
            defer {
                for (owned_values.items) |value| self.releaseValue(value);
                owned_values.deinit(self.allocator);
                values.deinit(self.allocator);
            }
            try self.appendConcatValue(&values, &owned_values, left, false);
            try self.appendConcatValue(&values, &owned_values, right, false);
            const result = try self.makeArrayFromValues(values.items);
            return try self.setNumericMatrixShapeOnValue(result, shape.rows, shape.cols);
        }
        if (try self.concatNumericVectorScalar(left, right, true)) |result| return result;
        if (try self.concatNumericVectorScalar(right, left, false)) |result| return result;
        if (left.tag() == .array and right.tag() == .array and
            valueNumericMode(left) != null and valueNumericMode(right) != null and
            numericVectorLen(left) != null and numericVectorLen(right) != null)
        {
            return try newFlatConcatValue(self, left, right);
        }
        var values = std.ArrayList(Value).empty;
        var owned_values = std.ArrayList(Value).empty;
        defer {
            for (owned_values.items) |value| self.releaseValue(value);
            owned_values.deinit(self.allocator);
            values.deinit(self.allocator);
        }
        try self.appendConcatValue(&values, &owned_values, left, true);
        try self.appendConcatValue(&values, &owned_values, right, true);
        return try self.makeArrayFromValues(values.items);
    }

    fn appendConcatStringChars(self: *Session, values: *std.ArrayList(Value), owned_values: *std.ArrayList(Value), source: HostStringSource) KError!void {
        for (0..source.bytes().len) |idx| {
            const item = try self.stringIndexScalarValue(source, @intCast(idx));
            errdefer self.releaseValue(item);
            try values.append(self.allocator, item);
            try owned_values.append(self.allocator, item);
        }
    }

    fn appendConcatValue(self: *Session, values: *std.ArrayList(Value), owned_values: *std.ArrayList(Value), value: Value, split_string_chars: bool) KError!void {
        if (stringSourceInfo(value)) |source| {
            if (split_string_chars) {
                try self.appendConcatStringChars(values, owned_values, source);
            } else {
                try values.append(self.allocator, value);
            }
            return;
        }
        if (symbolBytes(value) != null) {
            try values.append(self.allocator, value);
            return;
        }
        if (value.tag() == .array and value.arrayKind() == .host_string_list) {
            const list = value.asHostStringList();
            for (0..list.len) |idx| {
                const item = try self.hostStringListItemValue(list, idx);
                errdefer self.releaseValue(item);
                try values.append(self.allocator, item);
                try owned_values.append(self.allocator, item);
            }
            return;
        }
        if (value.tag() == .array and value.arrayKind() == .host_symbol_list) {
            const list = value.asHostStringList();
            for (0..list.len) |idx| {
                const item = try self.hostSymbolListItemValue(list, idx);
                errdefer self.releaseValue(item);
                try values.append(self.allocator, item);
                try owned_values.append(self.allocator, item);
            }
            return;
        }
        if (value.tag() != .array) {
            switch (value.tag()) {
                .int, .bool, .float, .float32 => try values.append(self.allocator, value),
                else => return error.Type,
            }
            return;
        }
        if (value.arraySubkind() == .host_boxed_array) {
            const array = value.asHostBoxedArray();
            for (array.items[0..array.len()]) |item| try values.append(self.allocator, item);
            return;
        }
        if (valueHostIntStructuralView(value)) |view| {
            for (0..hostIntDenseViewLen(view)) |idx| try values.append(self.allocator, try self.intValue(try hostIntDenseViewItem(view, idx)));
            return;
        }
        const array = try numericHostArrayValue(self, value);
        switch (array.storage) {
            .bit => |words| for (0..array.len()) |idx| try values.append(self.allocator, Value.fromBool(bitGet(words, idx))),
            .float64 => |items| for (hostDenseLogicalItems(f64, array, items)) |item| try values.append(self.allocator, try self.floatValue(item)),
            else => {
                const view = hostIntArrayView(array).?;
                for (0..hostIntArrayViewLen(view)) |idx| try values.append(self.allocator, try self.intValue(hostIntViewItem(view, idx)));
            },
        }
    }

    fn takeValues(self: *Session, left: Value, right: Value) KError!Value {
        switch (left.tag()) {
            .builtin, .closure => return try self.filterValues(left, right),
            else => {},
        }
        if (isEmptyIntVectorValue(left)) {
            if (try self.tryProjectKeyedStoreByKeys(left, right)) |projected| return projected;
            return try self.applyMonad(.mul, right);
        }
        if (try reshapeShapeSnapshotValue(left)) |shape| {
            return try self.reshapeValueWithShape(.managed, shape, right);
        }
        if (left.tag() == .int and isKiwiIntNull(left.asInt()) and
            !(right.tag() == .array and right.arrayKind() == .host_relation))
        {
            return self.shareValue(right);
        }
        if (try self.tryProjectKeyedStoreByKeys(left, right)) |projected| return projected;
        const raw_count = scalarIntLikeValue(left) orelse return error.Type;
        if (stringSourceInfo(right)) |source| {
            return try self.takeHostString(raw_count, source);
        }
        if (right.tag() == .array and right.arrayKind() == .host_string_list) {
            return try self.takeHostStringList(raw_count, right.asHostStringList());
        }
        if (right.tag() == .array and right.arrayKind() == .host_symbol_list) {
            return try self.takeHostSymbolList(raw_count, right.asHostStringList());
        }
        if (right.tag() != .array) {
            return switch (right.tag()) {
                .int, .bool, .float, .float32 => try self.takeScalarValue(raw_count, right),
                .builtin, .closure => try self.takeAtomBoxedValue(raw_count, right),
                else => error.Type,
            };
        }
        if (right.arrayKind() == .host_keyed_store) {
            const store = right.asHostKeyedStore();
            return switch (store.layout) {
                .dict => try self.keyedDictTakeValue(raw_count, store),
                .table => try self.tableTakeValue(raw_count, store),
            };
        }
        if (right.arrayKind() == .host_relation) {
            return try self.materializeRelationTake(raw_count, right.asHostRelation());
        }
        if (right.arraySubkind() == .host_boxed_array) {
            if (boxedSingletonCharSourceInfo(right)) |source| {
                return try self.takeHostString(raw_count, source);
            }
            return try self.takeHostBoxedArray(raw_count, right.asHostBoxedArray());
        }
        if (right.arrayKind() == .host_symbol) {
            return try self.takeHostSymbol(raw_count, right.asHostSymbol());
        }
        if (right.arrayKind() == .host_table_scalar) {
            return try self.takeAtomBoxedValue(raw_count, right);
        }
        if (valueNumericMatrixView(right)) |matrix| {
            const count: usize = @intCast(@abs(raw_count));
            if (count == 0) return try numericValueMatrixSelectRows(self, right, &.{});
            if (matrix.shape.rows == 0) {
                const total = std.math.mul(usize, count, matrix.shape.cols) catch return error.Unsupported;
                const value = switch (valueNumericMode(right) orelse return error.Type) {
                    .int => try self.createManagedIntNullArray(total),
                    .float => try self.createManagedFloatNullArray(total),
                };
                return try self.setNumericMatrixShapeOnValue(value, count, matrix.shape.cols);
            }

            var row_indices = std.ArrayList(usize).empty;
            defer row_indices.deinit(self.allocator);
            try row_indices.ensureTotalCapacity(self.allocator, count);
            const start = takeCyclicStart(raw_count, count, matrix.shape.rows);
            for (0..count) |idx| try row_indices.append(self.allocator, (start + idx) % matrix.shape.rows);
            return try numericValueMatrixSelectRows(self, right, row_indices.items);
        }
        if (shapedNumericHandle(right)) |handle| {
            const rows: usize = @intCast(handle.shape[0]);
            const count: usize = @intCast(@abs(raw_count));
            if (count == 0) {
                if (try numericValueFirstAxisContiguousSliceValue(self, right, .{ .start = 0, .len = 0 })) |result| return result;
            } else if (rows == 0) {
                const block_len = numericShapeInnerBlockLen(handle);
                const total = std.math.mul(usize, count, block_len) catch return error.Unsupported;
                const value = switch (valueNumericMode(right) orelse return error.Type) {
                    .int => try self.createManagedIntNullArray(total),
                    .float => try self.createManagedFloatNullArray(total),
                };
                const shape = numericShapeFirstAxisSliceSnapshot(handle, count) orelse return error.Type;
                return try applyNonVectorNumericShapeToValue(self, value, shape);
            } else if (count <= rows) {
                const start = if (raw_count >= 0) 0 else rows - count;
                if (try numericValueFirstAxisContiguousSliceValue(self, right, .{ .start = start, .len = count })) |result| return result;
            }
        }
        if (NumericStructuralView.init(right)) |structural| {
            if (try numericStructuralTakeValue(self, structural, raw_count)) |result| return result;
        }
        if (valueNumericMode(right) != null) {
            if (numericVectorLen(right)) |len| {
                const count: usize = @intCast(@abs(raw_count));
                if (count == 0) return try newFlatSliceValue(self, right, 0, 0);
                if (len == 0) return try self.takeEmptyNumericPrototypeValue(raw_count, valueNumericMode(right).?);
                if (count <= len) {
                    const start = if (raw_count >= 0) 0 else len - count;
                    return try newFlatSliceValue(self, right, start, count);
                }
            }
        }
        return try self.takeHostArray(raw_count, right, try numericHostArrayValue(self, right));
    }

    fn takeValueWithOwner(self: *Session, owner: HeapOwner, left: Value, right: Value) KError!Value {
        const result = try self.takeValues(left, right);
        return switch (owner) {
            .managed, .scratch => result,
            .frozen => blk: {
                const frozen = try self.freezeConstantValue(result);
                if (frozen.raw != result.raw) self.releaseValue(result);
                break :blk frozen;
            },
        };
    }

    fn isEmptyIntVectorValue(value: Value) bool {
        if (valueNumericMode(value) != .int) return false;
        return (numericVectorLen(value) orelse return false) == 0;
    }

    fn reshapeShapeSnapshotValue(value: Value) KError!?ReshapeShapeSnapshot {
        const len = numericVectorLen(value) orelse return null;
        if (valueNumericMode(value) != .int) return null;
        if (len == 0) return error.Type;
        if (len > numeric_array_max_rank) return error.Unsupported;

        var snapshot = ReshapeShapeSnapshot{};
        snapshot.rank = @intCast(len);
        for (0..len) |idx| {
            const dim_i64 = try numericIntAt(value, idx);
            if (isKiwiIntNull(dim_i64)) {
                snapshot.shape[idx] = kiwi_int_null;
            } else {
                if (dim_i64 < 0) return error.Type;
                _ = std.math.cast(i32, dim_i64) orelse return error.Unsupported;
                snapshot.shape[idx] = dim_i64;
            }
        }
        return snapshot;
    }

    fn fixedReshapeShapeSnapshot(shape: ReshapeShapeSnapshot) KError!?NumericShapeSnapshot {
        if (shape.hasNullDim()) return null;
        var dims_buf: [numeric_array_max_rank]i32 = @as([numeric_array_max_rank]i32, @splat(0));
        for (shape.shapeSlice(), 0..) |dim, idx| {
            dims_buf[idx] = std.math.cast(i32, dim) orelse return error.Unsupported;
        }
        return try numericShapeSnapshotFromDims(dims_buf[0..shape.rank]);
    }

    fn fixedShapeContainsZero(shape: NumericShapeSnapshot) bool {
        for (shape.shapeSlice()) |dim| {
            if (dim == 0) return true;
        }
        return false;
    }

    fn fixedShapeProduct(dims: []const i32) KError!usize {
        var total: usize = 1;
        for (dims) |dim| {
            if (dim < 0) return error.Type;
            total = std.math.mul(usize, total, @as(usize, @intCast(dim))) catch return error.Unsupported;
        }
        return total;
    }

    fn fixedShapeProductMaxOne(dims: []const i32) KError!usize {
        var total: usize = 1;
        for (dims) |dim| {
            if (dim < 0) return error.Type;
            total = std.math.mul(usize, total, @as(usize, @intCast(@max(1, dim)))) catch return error.Unsupported;
        }
        return total;
    }

    fn createOwnedHostStringSpaces(self: *Session, owner: HeapOwner, len: usize) KError!Value {
        const bytes = try self.allocator.alloc(u8, len);
        defer self.allocator.free(bytes);
        @memset(bytes, ' ');
        return try self.createOwnedHostString(owner, bytes);
    }

    fn createCharPrototypeForFixedShape(self: *Session, owner: HeapOwner, dims: []const i32) KError!Value {
        if (dims.len == 0) return try self.createOwnedHostStringSpaces(owner, 1);
        if (dims.len == 1) return try self.createOwnedHostStringSpaces(owner, @intCast(dims[0]));

        const first: usize = @intCast(dims[0]);
        const prototype = try self.createCharPrototypeForFixedShape(owner, dims[1..]);
        defer self.releaseValue(prototype);
        if (first == 0) {
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }

        const values = try self.allocator.alloc(Value, first);
        defer self.allocator.free(values);
        for (values) |*value| value.* = prototype;

        if (dims.len == 2) {
            const row = stringBytes(prototype) orelse return error.Internal;
            const rows = try self.allocator.alloc([]const u8, first);
            defer self.allocator.free(rows);
            for (rows) |*item| item.* = row;
            return try self.createOwnedHostStringRowsFromSlices(owner, rows);
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn materializeCharReshapeFlat(self: *Session, source: []const u8, total: usize) KError![]u8 {
        const flat = try self.allocator.alloc(u8, total);
        errdefer self.allocator.free(flat);
        if (source.len == 0) {
            @memset(flat, ' ');
        } else {
            for (flat, 0..) |*byte, idx| byte.* = source[idx % source.len];
        }
        return flat;
    }

    fn buildCharReshapeFromFlat(self: *Session, owner: HeapOwner, dims: []const i32, flat: []const u8, base: usize) KError!Value {
        if (dims.len == 0) return error.Type;
        if (dims.len == 1) {
            const len: usize = @intCast(dims[0]);
            if (base + len > flat.len) return error.Internal;
            return try self.createOwnedHostString(owner, flat[base .. base + len]);
        }
        if (dims.len == 2) {
            const rows_len: usize = @intCast(dims[0]);
            const cols_len: usize = @intCast(dims[1]);
            const rows = try self.allocator.alloc([]const u8, rows_len);
            defer self.allocator.free(rows);
            for (rows, 0..) |*row, idx| {
                const start = base + idx * cols_len;
                if (start + cols_len > flat.len) return error.Internal;
                row.* = flat[start .. start + cols_len];
            }
            return try self.createOwnedHostStringRowsFromSlices(owner, rows);
        }

        const first: usize = @intCast(dims[0]);
        const block_len = try fixedShapeProduct(dims[1..]);
        const values = try self.allocator.alloc(Value, first);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |value| self.releaseValue(value);
        }
        for (values, 0..) |*value, idx| {
            value.* = try self.buildCharReshapeFromFlat(owner, dims[1..], flat, base + idx * block_len);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn reshapeHostStringToFixedShape(self: *Session, owner: HeapOwner, shape: NumericShapeSnapshot, source: []const u8) KError!Value {
        if (fixedShapeContainsZero(shape)) return try self.createCharPrototypeForFixedShape(owner, shape.shapeSlice());
        const total = try fixedShapeProduct(shape.shapeSlice());
        const flat = try self.materializeCharReshapeFlat(source, total);
        defer self.allocator.free(flat);
        return try self.buildCharReshapeFromFlat(owner, shape.shapeSlice(), flat, 0);
    }

    fn symbolSourceLen(value: Value) ?usize {
        if (symbolBytes(value) != null) return 1;
        if (value.tag() == .array and value.arrayKind() == .host_symbol_list) return value.asHostStringList().len;
        return null;
    }

    fn symbolSourceItemBytes(value: Value, idx: usize) KError![]const u8 {
        if (symbolBytes(value)) |bytes| {
            if (idx != 0) return error.Internal;
            return bytes;
        }
        if (value.tag() == .array and value.arrayKind() == .host_symbol_list) {
            return try hostStringListItemBytes(value.asHostStringList(), idx);
        }
        return error.Type;
    }

    fn cycledSymbolSourceItemBytes(self: *Session, value: Value, source_len: usize, idx: usize) KError![]const u8 {
        _ = self;
        if (source_len == 0) return &.{};
        return try symbolSourceItemBytes(value, idx % source_len);
    }

    fn createOwnedEmptySymbolList(self: *Session, owner: HeapOwner, len: usize) KError!Value {
        const items = try self.allocator.alloc([]const u8, len);
        defer self.allocator.free(items);
        for (items) |*item| item.* = &.{};
        return try self.createOwnedHostSymbolListFromSlices(owner, items);
    }

    fn createSymbolPrototypeForFixedShape(self: *Session, owner: HeapOwner, dims: []const i32) KError!Value {
        if (dims.len == 0) return try self.createOwnedHostSymbol(owner, &.{});
        if (dims.len == 1) return try self.createOwnedEmptySymbolList(owner, @intCast(dims[0]));

        const first: usize = @intCast(dims[0]);
        const prototype = try self.createSymbolPrototypeForFixedShape(owner, dims[1..]);
        defer self.releaseValue(prototype);
        if (first == 0) return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);

        const values = try self.allocator.alloc(Value, first);
        defer self.allocator.free(values);
        for (values) |*value| value.* = prototype;
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn buildSymbolReshapeFromSource(
        self: *Session,
        owner: HeapOwner,
        dims: []const i32,
        source: Value,
        source_len: usize,
        base: usize,
    ) KError!Value {
        if (dims.len == 0) return error.Type;
        if (dims.len == 1) {
            const len: usize = @intCast(dims[0]);
            const items = try self.allocator.alloc([]const u8, len);
            defer self.allocator.free(items);
            for (items, 0..) |*item, idx| item.* = try self.cycledSymbolSourceItemBytes(source, source_len, base + idx);
            return try self.createOwnedHostSymbolListFromSlices(owner, items);
        }

        const first: usize = @intCast(dims[0]);
        if (first == 0) {
            const prototype = try self.createSymbolPrototypeForFixedShape(owner, dims[1..]);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }

        const block_len = try fixedShapeProductMaxOne(dims[1..]);
        const values = try self.allocator.alloc(Value, first);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |value| self.releaseValue(value);
        }
        for (values, 0..) |*value, idx| {
            value.* = try self.buildSymbolReshapeFromSource(owner, dims[1..], source, source_len, base + idx * block_len);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn reshapeSymbolToFixedShape(self: *Session, owner: HeapOwner, shape: NumericShapeSnapshot, right: Value) KError!Value {
        const source_len = symbolSourceLen(right) orelse return error.Type;
        return try self.buildSymbolReshapeFromSource(owner, shape.shapeSlice(), right, source_len, 0);
    }

    fn createOwnedNumericNullLike(self: *Session, owner: HeapOwner, value: Value) KError!Value {
        const mode = valueNumericMode(value) orelse return error.Type;
        const len = numericFlatLen(value) orelse if (numericVectorLen(value)) |vector_len| vector_len else return error.Type;
        const nulls = switch (mode) {
            .int => try self.createOwnedIntNullArray(owner, len),
            .float => if (valueFloatStorageKind(value) == .float32)
                try self.createOwnedFloat32NullArray(owner, len)
            else
                try self.createOwnedFloatNullArray(owner, len),
        };
        if (valueNonVectorNumericShape(value)) |shape| {
            return try applyNonVectorNumericShapeToValue(self, nulls, shape);
        }
        return nulls;
    }

    fn deepPrototypeValue(self: *Session, owner: HeapOwner, value: Value) KError!Value {
        switch (value.tag()) {
            .int, .bool => return try self.intNullValue(),
            .float32 => return try self.float32NullValue(),
            .float => return try self.floatNullValue(),
            else => {},
        }
        if (stringBytes(value)) |bytes| return try self.createOwnedHostStringSpaces(owner, bytes.len);
        if (symbolBytes(value) != null) return try self.createOwnedHostSymbol(owner, &.{});
        if (valueNumericMode(value) != null) return try self.createOwnedNumericNullLike(owner, value);
        if (value.tag() == .array and value.arrayKind() == .host_symbol_list) {
            return try self.createOwnedEmptySymbolList(owner, value.asHostStringList().len);
        }
        if (value.tag() == .array and value.arrayKind() == .host_string_list) {
            const list = value.asHostStringList();
            const items = try self.allocator.alloc([]const u8, list.len);
            defer self.allocator.free(items);
            for (items, 0..) |*item, idx| {
                const bytes = try hostStringListItemBytes(list, idx);
                const spaces = try self.allocator.alloc(u8, bytes.len);
                defer self.allocator.free(spaces);
                @memset(spaces, ' ');
                item.* = spaces;
            }
            return try self.createOwnedHostStringListFromSlices(owner, items);
        }
        if (value.tag() == .array and value.arrayKind() == .host_boxed_array) {
            const array = value.asHostBoxedArray();
            if (array.len() == 0) {
                if (array.prototype) |prototype| {
                    const next = try self.deepPrototypeValue(owner, prototype);
                    defer self.releaseValue(next);
                    return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, next);
                }
                return try self.createOwnedHostBoxedArray(owner, &.{});
            }
            const values = try self.allocator.alloc(Value, array.len());
            defer self.allocator.free(values);
            var initialized: usize = 0;
            defer {
                for (values[0..initialized]) |item| self.releaseValue(item);
            }
            for (values, array.items[0..array.len()]) |*out, item| {
                out.* = try self.deepPrototypeValue(owner, item);
                initialized += 1;
            }
            return try self.createOwnedHostBoxedArray(owner, values);
        }
        if (value.tag() == .array and value.arrayKind() == .host_keyed_store) {
            const store = value.asHostKeyedStore();
            if (store.layout == .dict) return try self.keyedDictPrototypeLikeValue(store);
        }
        return error.Type;
    }

    fn emptySequenceForBoxedItem(self: *Session, owner: HeapOwner, value: Value) KError!Value {
        switch (value.tag()) {
            .int, .bool => return try self.createOwnedHostIntArray(owner, &.{}),
            .float32 => return try self.createOwnedHostFloat32Array(owner, &.{}),
            .float => return try self.createOwnedHostFloatArray(owner, &.{}),
            else => {},
        }
        if (stringBytes(value) != null) {
            const prototype = try self.deepPrototypeValue(owner, value);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }
        if (symbolBytes(value) != null) return try self.createOwnedHostSymbolListFromSlices(owner, &.{});
        if (valueNumericMode(value) != null) {
            const prototype = try self.createOwnedNumericNullLike(owner, value);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }
        if (value.tag() == .array and value.arrayKind() == .host_symbol_list) {
            const prototype = try self.deepPrototypeValue(owner, value);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }
        if (value.tag() == .array and value.arrayKind() == .host_string_list) {
            const prototype = try self.deepPrototypeValue(owner, value);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }
        if (value.tag() == .array and value.arrayKind() == .host_boxed_array) {
            const prototype = try self.deepPrototypeValue(owner, value);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }
        return error.Type;
    }

    fn emptyReshapeSequenceForItem(self: *Session, owner: HeapOwner, value: Value) KError!Value {
        switch (value.tag()) {
            .int, .bool => return try self.createOwnedHostIntArray(owner, &.{}),
            .float => return try self.createOwnedHostFloatArray(owner, &.{}),
            else => {},
        }
        if (stringBytes(value)) |bytes| {
            const prototype = try self.createOwnedHostStringSpaces(owner, bytes.len);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }
        if (symbolBytes(value) != null) return try self.createOwnedHostSymbolListFromSlices(owner, &.{});
        if (valueNumericMode(value) != null) {
            const prototype = try self.createOwnedNumericNullLike(owner, value);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }
        if (value.tag() == .array and value.arrayKind() == .host_symbol_list) {
            const prototype = try self.deepPrototypeValue(owner, value);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }
        if (value.tag() == .array and value.arrayKind() == .host_string_list) {
            const prototype = try self.deepPrototypeValue(owner, value);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }
        if (value.tag() == .array and value.arrayKind() == .host_boxed_array) {
            const prototype = try self.deepPrototypeValue(owner, value);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }
        return error.Type;
    }

    fn reshapeItemSequenceSourceLen(value: Value) ?usize {
        if (value.tag() != .array) return null;
        if (hasBackendRealization(value)) return null;
        if (shapedNumericHandle(value)) |handle| return @intCast(handle.shape[0]);
        return switch (value.arrayKind()) {
            .host_string_list => value.asHostStringList().len,
            .host_boxed_array => value.asHostBoxedArray().len(),
            else => null,
        };
    }

    fn numericFirstAxisPrototypeItemValue(self: *Session, value: Value) KError!Value {
        const handle = shapedNumericHandle(value) orelse return error.Type;
        const mode = valueNumericMode(value) orelse return error.Type;
        const block_len = numericShapeInnerBlockLen(handle);
        const prototype = switch (mode) {
            .int => try self.createManagedIntNullArray(block_len),
            .float => try self.createManagedFloatNullArray(block_len),
        };
        return try applyNonVectorNumericShapeToValue(self, prototype, numericShapeTailSnapshot(handle));
    }

    fn reshapeItemSequencePrototypeItemValue(self: *Session, value: Value) KError!Value {
        if (shapedNumericHandle(value) != null) return try self.numericFirstAxisPrototypeItemValue(value);
        if (value.tag() == .array and value.arrayKind() == .host_string_list) return try self.managedHostString(&.{});
        if (value.tag() == .array and value.arrayKind() == .host_boxed_array) {
            const array = value.asHostBoxedArray();
            if (array.prototype) |prototype| return try self.retainEscapedValue(prototype);
            return try self.managedHostString(&.{});
        }
        return error.Type;
    }

    fn materializeItemSequenceReshapeFlat(self: *Session, dims: []const i32, right: Value, source_len: usize) KError![]Value {
        const total = try fixedShapeProductMaxOne(dims);
        const flat = try self.allocator.alloc(Value, total);
        errdefer self.allocator.free(flat);

        const fallback = if (source_len == 0) try self.reshapeItemSequencePrototypeItemValue(right) else Value.int(0) catch unreachable;
        defer if (source_len == 0) self.releaseValue(fallback);

        var initialized: usize = 0;
        errdefer {
            for (flat[0..initialized]) |item| self.releaseValue(item);
        }
        for (flat, 0..) |*item, idx| {
            item.* = if (source_len == 0)
                try self.retainEscapedValue(fallback)
            else
                try self.derivedSequenceItemValue(right, idx % source_len);
            initialized += 1;
        }
        return flat;
    }

    fn materializeBoxedReshapeFlat(self: *Session, dims: []const i32, right: *const HostBoxedArray) KError![]Value {
        const total = try fixedShapeProductMaxOne(dims);
        const flat = try self.allocator.alloc(Value, total);
        errdefer self.allocator.free(flat);

        const needs_empty_fallback = right.len() == 0 and right.prototype == null;
        const fallback = if (needs_empty_fallback) try self.managedHostString(&.{}) else Value.int(0) catch unreachable;
        defer if (needs_empty_fallback) self.releaseValue(fallback);

        var initialized: usize = 0;
        errdefer {
            for (flat[0..initialized]) |item| self.releaseValue(item);
        }
        for (flat, 0..) |*item, idx| {
            const source = if (right.len() != 0)
                right.items[idx % right.len()]
            else if (right.prototype) |prototype|
                prototype
            else
                fallback;
            item.* = try self.retainEscapedValue(source);
            initialized += 1;
        }
        return flat;
    }

    fn buildBoxedPrototypeForShape(self: *Session, owner: HeapOwner, dims: []const i32, flat: []const Value, base: usize) KError!Value {
        if (dims.len == 0) return try self.deepPrototypeValue(owner, flat[base]);
        if (dims.len == 1) {
            const len: usize = @intCast(dims[0]);
            if (len == 0) return try self.emptyReshapeSequenceForItem(owner, flat[base]);
            const values = try self.allocator.alloc(Value, len);
            defer self.allocator.free(values);
            var initialized: usize = 0;
            defer {
                for (values[0..initialized]) |item| self.releaseValue(item);
            }
            for (values, 0..) |*value, idx| {
                value.* = try self.deepPrototypeValue(owner, flat[base + idx]);
                initialized += 1;
            }
            return try self.createOwnedHostBoxedArray(owner, values);
        }

        const first: usize = @intCast(dims[0]);
        if (first == 0) {
            const prototype = try self.buildBoxedPrototypeForShape(owner, dims[1..], flat, base);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }

        const block_len = try fixedShapeProductMaxOne(dims[1..]);
        const values = try self.allocator.alloc(Value, first);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |item| self.releaseValue(item);
        }
        for (values, 0..) |*value, idx| {
            value.* = try self.buildBoxedPrototypeForShape(owner, dims[1..], flat, base + idx * block_len);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn buildBoxedReshapeFromFlat(self: *Session, owner: HeapOwner, dims: []const i32, flat: []const Value, base: usize) KError!Value {
        if (dims.len == 0) return error.Type;
        if (dims.len == 1) {
            const len: usize = @intCast(dims[0]);
            if (len == 0) return try self.emptyReshapeSequenceForItem(owner, flat[base]);
            if (base + len > flat.len) return error.Internal;
            return try self.createOwnedHostBoxedArray(owner, flat[base .. base + len]);
        }

        const first: usize = @intCast(dims[0]);
        if (first == 0) {
            const prototype = try self.buildBoxedPrototypeForShape(owner, dims[1..], flat, base);
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }

        const block_len = try fixedShapeProductMaxOne(dims[1..]);
        const values = try self.allocator.alloc(Value, first);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |item| self.releaseValue(item);
        }
        for (values, 0..) |*value, idx| {
            value.* = try self.buildBoxedReshapeFromFlat(owner, dims[1..], flat, base + idx * block_len);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn reshapeBoxedToFixedShape(self: *Session, owner: HeapOwner, shape: NumericShapeSnapshot, array: *const HostBoxedArray) KError!Value {
        const flat = try self.materializeBoxedReshapeFlat(shape.shapeSlice(), array);
        defer {
            for (flat) |item| self.releaseValue(item);
            self.allocator.free(flat);
        }
        return try self.buildBoxedReshapeFromFlat(owner, shape.shapeSlice(), flat, 0);
    }

    fn reshapeItemSequenceToFixedShape(self: *Session, owner: HeapOwner, shape: NumericShapeSnapshot, right: Value) KError!?Value {
        const source_len = reshapeItemSequenceSourceLen(right) orelse return null;
        const flat = try self.materializeItemSequenceReshapeFlat(shape.shapeSlice(), right, source_len);
        defer {
            for (flat) |item| self.releaseValue(item);
            self.allocator.free(flat);
        }
        return try self.buildBoxedReshapeFromFlat(owner, shape.shapeSlice(), flat, 0);
    }

    fn reshapeValueWithShape(self: *Session, owner: HeapOwner, shape: ReshapeShapeSnapshot, right: Value) KError!Value {
        if (try fixedReshapeShapeSnapshot(shape)) |fixed_shape| {
            if (stringSourceInfo(right)) |source| {
                return try self.reshapeHostStringToFixedShape(owner, fixed_shape, source.bytes());
            }
            if (symbolSourceLen(right) != null) return try self.reshapeSymbolToFixedShape(owner, fixed_shape, right);
            if (try self.reshapeItemSequenceToFixedShape(owner, fixed_shape, right)) |result| return result;
            if (right.tag() == .array and right.arrayKind() == .host_boxed_array) {
                return try self.reshapeBoxedToFixedShape(owner, fixed_shape, right.asHostBoxedArray());
            }
            return if (owner == .managed)
                try self.reshapeToSnapshotValue(fixed_shape, right)
            else
                try self.reshapeConstantToSnapshotValue(owner, fixed_shape, right);
        }
        return try self.reshapeNullShapeValue(owner, shape, right);
    }

    fn reshapeToSnapshotValue(self: *Session, shape: NumericShapeSnapshot, right: Value) KError!Value {
        const total = try numericShapeSnapshotElementCount(shape);

        if (right.tag() != .array) {
            return switch (right.tag()) {
                .int, .bool, .float => blk: {
                    const flat = try self.takeScalarValue(@intCast(total), right);
                    break :blk try applyNonVectorNumericShapeToValue(self, flat, shape);
                },
                else => error.Type,
            };
        }

        if (valueRangeIotaHandle(right)) |handle| {
            const source_total = numericArrayRangeLen(handle);
            if (source_total == 0 and total != 0) {
                const reshaped = try self.createManagedIntNullArray(total);
                return try applyNonVectorNumericShapeToValue(self, reshaped, shape);
            }
            if (source_total == total) {
                return try newRangeIotaValueWithShape(
                    self,
                    .managed,
                    total,
                    numericArrayRangeIota(handle).start,
                    numericArrayRangeIota(handle).step,
                    shape,
                );
            }
        }

        if (valueNumericMode(right)) |mode| {
            const source_total = numericFlatLen(right) orelse if (right.tag() == .array)
                (try numericHostArrayValue(self, right)).len()
            else
                return error.Type;
            if (source_total == 0 and total != 0) {
                const reshaped = switch (mode) {
                    .int => try self.createManagedIntNullArray(total),
                    .float => try self.createManagedFloatNullArray(total),
                };
                return try applyNonVectorNumericShapeToValue(self, reshaped, shape);
            }
            if (source_total == total) {
                return try newReshapeViewValue(self, right, shape);
            }
            return switch (mode) {
                .float => blk: {
                    var out = std.ArrayList(f64).empty;
                    defer out.deinit(self.allocator);
                    try out.ensureTotalCapacity(self.allocator, total);
                    for (0..total) |idx| {
                        try out.append(self.allocator, try numericFloatAt(right, @intCast(idx % source_total)));
                    }
                    const reshaped = try self.createManagedHostFloatArray(out.items);
                    break :blk try applyNonVectorNumericShapeToValue(self, reshaped, shape);
                },
                .int => blk: {
                    var out = std.ArrayList(i64).empty;
                    defer out.deinit(self.allocator);
                    try out.ensureTotalCapacity(self.allocator, total);
                    for (0..total) |idx| {
                        try out.append(self.allocator, try numericIntAt(right, @intCast(idx % source_total)));
                    }
                    const reshaped = try self.createManagedHostIntArray(out.items);
                    break :blk try applyNonVectorNumericShapeToValue(self, reshaped, shape);
                },
            };
        }

        return error.Type;
    }

    fn reshapeConstantToSnapshotValue(self: *Session, owner: HeapOwner, shape: NumericShapeSnapshot, right: Value) KError!Value {
        const total = try numericShapeSnapshotElementCount(shape);

        if (right.tag() != .array) {
            return switch (right.tag()) {
                .bool => blk: {
                    const count = total;
                    const data = try self.allocator.alloc(bool, count);
                    defer self.allocator.free(data);
                    @memset(data, right.asBool());
                    const reshaped = try self.createOwnedHostBitArray(owner, data);
                    break :blk try applyNonVectorNumericShapeToValue(self, reshaped, shape);
                },
                .float => blk: {
                    const count = total;
                    const data = try self.allocator.alloc(f64, count);
                    defer self.allocator.free(data);
                    @memset(data, right.asFloat());
                    const reshaped = try self.createOwnedHostFloatArray(owner, data);
                    break :blk try applyNonVectorNumericShapeToValue(self, reshaped, shape);
                },
                .int => blk: {
                    const count = total;
                    const data = try self.allocator.alloc(i64, count);
                    defer self.allocator.free(data);
                    @memset(data, right.asInt());
                    const reshaped = try self.createOwnedHostIntArray(owner, data);
                    break :blk try applyNonVectorNumericShapeToValue(self, reshaped, shape);
                },
                else => error.Type,
            };
        }

        if (valueNumericMode(right)) |mode| {
            const source_total = numericFlatLen(right) orelse if (right.tag() == .array)
                (try numericHostArrayValue(self, right)).len()
            else
                return error.Type;
            if (source_total == 0 and total != 0) {
                const reshaped = switch (mode) {
                    .int => try self.createOwnedIntNullArray(owner, total),
                    .float => try self.createOwnedFloatNullArray(owner, total),
                };
                return try applyNonVectorNumericShapeToValue(self, reshaped, shape);
            }
            if (source_total == total) {
                return try applyNonVectorNumericShapeToValue(self, right, shape);
            }
            return switch (mode) {
                .float => blk: {
                    const data = try self.allocator.alloc(f64, total);
                    defer self.allocator.free(data);
                    for (0..total) |idx| {
                        data[idx] = try numericFloatAt(right, @intCast(idx % source_total));
                    }
                    const reshaped = try self.createOwnedHostFloatArray(owner, data);
                    break :blk try applyNonVectorNumericShapeToValue(self, reshaped, shape);
                },
                .int => blk: {
                    const data = try self.allocator.alloc(i64, total);
                    defer self.allocator.free(data);
                    for (0..total) |idx| {
                        data[idx] = try numericIntAt(right, @intCast(idx % source_total));
                    }
                    const reshaped = try self.createOwnedHostIntArray(owner, data);
                    break :blk try applyNonVectorNumericShapeToValue(self, reshaped, shape);
                },
            };
        }

        return error.Type;
    }

    fn createOwnedNumericVectorSlice(self: *Session, owner: HeapOwner, value: Value, start: usize, len: usize) KError!Value {
        const mode = valueNumericMode(value) orelse return error.Type;
        const source_len = numericVectorLen(value) orelse return error.Type;
        if (start > source_len or start + len > source_len) return error.Internal;
        return switch (mode) {
            .int => blk: {
                const data = try self.allocator.alloc(i64, len);
                defer self.allocator.free(data);
                for (data, 0..) |*item, idx| item.* = try numericIntAt(value, @intCast(start + idx));
                break :blk try self.createOwnedHostIntArray(owner, data);
            },
            .float => blk: {
                const data = try self.allocator.alloc(f64, len);
                defer self.allocator.free(data);
                for (data, 0..) |*item, idx| item.* = try numericFloatAt(value, @intCast(start + idx));
                break :blk try self.createOwnedHostFloatArray(owner, data);
            },
        };
    }

    fn createOwnedNumericScalarSlice(self: *Session, owner: HeapOwner, value: Value, start: usize, len: usize) KError!Value {
        if (start > 1 or start + len > 1) return error.Internal;
        return switch (value.tag()) {
            .int => blk: {
                var data: [1]i64 = .{value.asInt()};
                break :blk try self.createOwnedHostIntArray(owner, data[0..len]);
            },
            .bool => blk: {
                if (len == 0) break :blk try self.createOwnedHostIntArray(owner, &.{});
                var data: [1]bool = .{value.asBool()};
                break :blk try self.createOwnedHostBitArray(owner, data[0..]);
            },
            .float32 => blk: {
                var data: [1]f32 = .{value.asFloat32()};
                break :blk try self.createOwnedHostFloat32Array(owner, data[0..len]);
            },
            .float => blk: {
                var data: [1]f64 = .{value.asFloat()};
                break :blk try self.createOwnedHostFloatArray(owner, data[0..len]);
            },
            else => error.Type,
        };
    }

    fn chunkHostStringBySize(self: *Session, owner: HeapOwner, source: []const u8, chunk_size: usize) KError!Value {
        const count = if (chunk_size == 0 or source.len == 0) 0 else (source.len + chunk_size - 1) / chunk_size;
        if (count == 0) {
            const prototype = try self.createOwnedHostString(owner, &.{});
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }

        const rows = try self.allocator.alloc([]const u8, count);
        defer self.allocator.free(rows);
        for (rows, 0..) |*row, idx| {
            const start = idx * chunk_size;
            const end = @min(source.len, start + chunk_size);
            row.* = source[start..end];
        }
        return try self.createOwnedHostStringRowsFromSlices(owner, rows);
    }

    fn splitHostStringIntoGroups(self: *Session, owner: HeapOwner, source: []const u8, groups: usize) KError!Value {
        if (groups == 0) {
            const prototype = try self.createOwnedHostString(owner, &.{});
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }

        const rows = try self.allocator.alloc([]const u8, groups);
        defer self.allocator.free(rows);
        for (rows, 0..) |*row, idx| {
            const start = idx * source.len / groups;
            const end = (idx + 1) * source.len / groups;
            row.* = source[start..end];
        }
        return try self.createOwnedHostStringRowsFromSlices(owner, rows);
    }

    fn createSymbolChunkValue(self: *Session, owner: HeapOwner, source: Value, source_len: usize, start: usize, len: usize) KError!Value {
        const items = try self.allocator.alloc([]const u8, len);
        defer self.allocator.free(items);
        for (items, 0..) |*item, idx| item.* = try symbolSourceItemBytes(source, start + idx);
        if (source_len == 0 and len != 0) return error.Internal;
        return try self.createOwnedHostSymbolListFromSlices(owner, items);
    }

    fn chunkSymbolBySize(self: *Session, owner: HeapOwner, source: Value, chunk_size: usize) KError!Value {
        const source_len = symbolSourceLen(source) orelse return error.Type;
        const count = if (chunk_size == 0 or source_len == 0) 0 else (source_len + chunk_size - 1) / chunk_size;
        if (count == 0) {
            const prototype = try self.createOwnedHostSymbolListFromSlices(owner, &.{});
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }

        const values = try self.allocator.alloc(Value, count);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |item| self.releaseValue(item);
        }
        for (values, 0..) |*item, idx| {
            const start = idx * chunk_size;
            const end = @min(source_len, start + chunk_size);
            item.* = try self.createSymbolChunkValue(owner, source, source_len, start, end - start);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn splitSymbolIntoGroups(self: *Session, owner: HeapOwner, source: Value, groups: usize) KError!Value {
        const source_len = symbolSourceLen(source) orelse return error.Type;
        if (groups == 0) {
            const prototype = try self.createOwnedHostSymbolListFromSlices(owner, &.{});
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }

        const values = try self.allocator.alloc(Value, groups);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |item| self.releaseValue(item);
        }
        for (values, 0..) |*item, idx| {
            const start = idx * source_len / groups;
            const end = (idx + 1) * source_len / groups;
            item.* = try self.createSymbolChunkValue(owner, source, source_len, start, end - start);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn createBoxedChunkValue(self: *Session, owner: HeapOwner, array: *const HostBoxedArray, start: usize, len: usize) KError!Value {
        if (start > array.len() or start + len > array.len()) return error.Internal;
        return try self.createOwnedHostBoxedArray(owner, array.items[start .. start + len]);
    }

    fn chunkBoxedBySize(self: *Session, owner: HeapOwner, array: *const HostBoxedArray, chunk_size: usize) KError!Value {
        const source_len = array.len();
        const count = if (chunk_size == 0 or source_len == 0) 0 else (source_len + chunk_size - 1) / chunk_size;
        if (count == 0) {
            const prototype = if (array.prototype) |prototype| try self.emptySequenceForBoxedItem(owner, prototype) else try self.createOwnedHostBoxedArray(owner, &.{});
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }

        const values = try self.allocator.alloc(Value, count);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |item| self.releaseValue(item);
        }
        for (values, 0..) |*item, idx| {
            const start = idx * chunk_size;
            const end = @min(source_len, start + chunk_size);
            item.* = try self.createBoxedChunkValue(owner, array, start, end - start);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn splitBoxedIntoGroups(self: *Session, owner: HeapOwner, array: *const HostBoxedArray, groups: usize) KError!Value {
        const source_len = array.len();
        if (groups == 0) {
            const prototype = if (array.prototype) |prototype| try self.emptySequenceForBoxedItem(owner, prototype) else try self.createOwnedHostBoxedArray(owner, &.{});
            defer self.releaseValue(prototype);
            return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);
        }

        const values = try self.allocator.alloc(Value, groups);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |item| self.releaseValue(item);
        }
        for (values, 0..) |*item, idx| {
            const start = idx * source_len / groups;
            const end = (idx + 1) * source_len / groups;
            item.* = try self.createBoxedChunkValue(owner, array, start, end - start);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn chunkNumericVectorBySize(self: *Session, owner: HeapOwner, value: Value, chunk_size: usize) KError!Value {
        const source_len = numericVectorLen(value) orelse return error.Type;
        const count = if (chunk_size == 0 or source_len == 0) 0 else (source_len + chunk_size - 1) / chunk_size;
        const prototype = try self.createOwnedNumericVectorSlice(owner, value, 0, 0);
        defer self.releaseValue(prototype);
        if (count == 0) return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);

        const values = try self.allocator.alloc(Value, count);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |item| self.releaseValue(item);
        }
        for (values, 0..) |*item, idx| {
            const start = idx * chunk_size;
            const end = @min(source_len, start + chunk_size);
            item.* = try self.createOwnedNumericVectorSlice(owner, value, start, end - start);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn chunkNumericScalarBySize(self: *Session, owner: HeapOwner, value: Value, chunk_size: usize) KError!Value {
        const count: usize = if (chunk_size == 0) 0 else 1;
        const prototype = try self.createOwnedNumericScalarSlice(owner, value, 0, 0);
        defer self.releaseValue(prototype);
        if (count == 0) return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);

        const item = try self.createOwnedNumericScalarSlice(owner, value, 0, 1);
        defer self.releaseValue(item);
        return try self.createOwnedHostBoxedArray(owner, &.{item});
    }

    fn splitNumericVectorIntoGroups(self: *Session, owner: HeapOwner, value: Value, groups: usize) KError!Value {
        const source_len = numericVectorLen(value) orelse return error.Type;
        const prototype = try self.createOwnedNumericVectorSlice(owner, value, 0, 0);
        defer self.releaseValue(prototype);
        if (groups == 0) return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);

        const values = try self.allocator.alloc(Value, groups);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |item| self.releaseValue(item);
        }
        for (values, 0..) |*item, idx| {
            const start = idx * source_len / groups;
            const end = (idx + 1) * source_len / groups;
            item.* = try self.createOwnedNumericVectorSlice(owner, value, start, end - start);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn splitNumericScalarIntoGroups(self: *Session, owner: HeapOwner, value: Value, groups: usize) KError!Value {
        const source_len: usize = 1;
        const prototype = try self.createOwnedNumericScalarSlice(owner, value, 0, 0);
        defer self.releaseValue(prototype);
        if (groups == 0) return try self.createOwnedHostBoxedArrayWithPrototype(owner, &.{}, prototype);

        const values = try self.allocator.alloc(Value, groups);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |item| self.releaseValue(item);
        }
        for (values, 0..) |*item, idx| {
            const start = idx * source_len / groups;
            const end = (idx + 1) * source_len / groups;
            item.* = try self.createOwnedNumericScalarSlice(owner, value, start, end - start);
            initialized += 1;
        }
        return try self.createOwnedHostBoxedArray(owner, values);
    }

    fn reshapeNullShapeValue(self: *Session, owner: HeapOwner, shape: ReshapeShapeSnapshot, right: Value) KError!Value {
        const dims = shape.shapeSlice();
        if (dims.len == 1 and isKiwiIntNull(dims[0])) return try self.ownedValueForOwner(owner, right);
        if (dims.len != 2) return error.Type;

        const first_null = isKiwiIntNull(dims[0]);
        const second_null = isKiwiIntNull(dims[1]);
        if (first_null == second_null) return error.Type;

        if (first_null) {
            const chunk_size: usize = @intCast(dims[1]);
            if (stringSourceInfo(right)) |source| return try self.chunkHostStringBySize(owner, source.bytes(), chunk_size);
            if (symbolSourceLen(right) != null) return try self.chunkSymbolBySize(owner, right, chunk_size);
            if (right.tag() == .array and right.arrayKind() == .host_boxed_array) return try self.chunkBoxedBySize(owner, right.asHostBoxedArray(), chunk_size);
            if (valueNumericMode(right) != null and numericVectorLen(right) != null) return try self.chunkNumericVectorBySize(owner, right, chunk_size);
            if (valueNumericMode(right) != null and right.tag() != .array) return try self.chunkNumericScalarBySize(owner, right, chunk_size);
            return error.Type;
        }

        const groups: usize = @intCast(dims[0]);
        if (stringSourceInfo(right)) |source| return try self.splitHostStringIntoGroups(owner, source.bytes(), groups);
        if (symbolSourceLen(right) != null) return try self.splitSymbolIntoGroups(owner, right, groups);
        if (right.tag() == .array and right.arrayKind() == .host_boxed_array) return try self.splitBoxedIntoGroups(owner, right.asHostBoxedArray(), groups);
        if (valueNumericMode(right) != null and numericVectorLen(right) != null) return try self.splitNumericVectorIntoGroups(owner, right, groups);
        if (valueNumericMode(right) != null and right.tag() != .array) return try self.splitNumericScalarIntoGroups(owner, right, groups);
        return error.Type;
    }

    fn intNullValue(self: *Session) KError!Value {
        return try self.intValue(kiwi_int_null);
    }

    fn floatNullValue(self: *Session) KError!Value {
        return try self.floatValue(kiwiFloatNull());
    }

    fn float32NullValue(self: *Session) KError!Value {
        return try self.float32Value(kiwiFloat32Null());
    }

    fn numericPrototypeScalarValue(self: *Session, mode: HostDenseElem) KError!Value {
        return switch (mode) {
            .int => try self.intNullValue(),
            .float => try self.floatNullValue(),
        };
    }

    fn createManagedIntNullArray(self: *Session, count: usize) KError!Value {
        const items = try self.allocator.alloc(i64, count);
        defer self.allocator.free(items);
        @memset(items, kiwi_int_null);
        return try self.createManagedHostIntArray(items);
    }

    fn createManagedFloatNullArray(self: *Session, count: usize) KError!Value {
        const items = try self.allocator.alloc(f64, count);
        defer self.allocator.free(items);
        @memset(items, kiwiFloatNull());
        return try self.createManagedHostFloatArray(items);
    }

    fn createManagedFloat32NullArray(self: *Session, count: usize) KError!Value {
        const items = try self.allocator.alloc(f32, count);
        defer self.allocator.free(items);
        @memset(items, kiwiFloat32Null());
        return try self.createManagedHostFloat32Array(items);
    }

    fn createOwnedIntNullArray(self: *Session, owner: HeapOwner, count: usize) KError!Value {
        const items = try self.allocator.alloc(i64, count);
        defer self.allocator.free(items);
        @memset(items, kiwi_int_null);
        return try self.createOwnedHostIntArray(owner, items);
    }

    fn createOwnedFloatNullArray(self: *Session, owner: HeapOwner, count: usize) KError!Value {
        const items = try self.allocator.alloc(f64, count);
        defer self.allocator.free(items);
        @memset(items, kiwiFloatNull());
        return try self.createOwnedHostFloatArray(owner, items);
    }

    fn createOwnedFloat32NullArray(self: *Session, owner: HeapOwner, count: usize) KError!Value {
        const items = try self.allocator.alloc(f32, count);
        defer self.allocator.free(items);
        @memset(items, kiwiFloat32Null());
        return try self.createOwnedHostFloat32Array(owner, items);
    }

    fn takeEmptyNumericPrototypeValue(self: *Session, raw_count: i64, mode: HostDenseElem) KError!Value {
        const count: usize = @intCast(@abs(raw_count));
        return switch (mode) {
            .int => try self.createManagedIntNullArray(count),
            .float => try self.createManagedFloatNullArray(count),
        };
    }

    fn takeEmptyHostArrayPrototypeValue(self: *Session, raw_count: i64, array: *const HostDenseArray) KError!Value {
        const count: usize = @intCast(@abs(raw_count));
        return switch (array.storage) {
            .float32 => try self.createManagedFloat32NullArray(count),
            .float64 => try self.createManagedFloatNullArray(count),
            else => try self.createManagedIntNullArray(count),
        };
    }

    fn hostDensePrototypeScalarValue(self: *Session, array: *const HostDenseArray) KError!Value {
        return switch (array.storage) {
            .float32 => try self.float32Value(kiwiFloat32Null()),
            .float64 => try self.floatNullValue(),
            else => try self.intNullValue(),
        };
    }

    fn emptySymbolValue(self: *Session) KError!Value {
        return try self.managedHostSymbol(&.{});
    }

    fn keyedDictPrototypeLikeValue(self: *Session, store: *const HostKeyedStore) KError!Value {
        std.debug.assert(store.layout == .dict);
        const len = keyedStoreNameCount(store);
        const values = try self.allocator.alloc(Value, len);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |item| self.releaseValue(item);
        }

        for (0..len) |idx| {
            const item = try self.keyedStoreValueAt(store, idx);
            defer self.releaseValue(item);
            values[idx] = if (try self.prototypeValueForTake(item)) |prototype|
                prototype
            else
                try self.prototypeLikeValue(item);
            initialized += 1;
        }

        const names = try self.retainEscapedValue(store.names);
        errdefer self.releaseValue(names);
        const value_array = try self.makeArrayFromValues(values);
        errdefer self.releaseValue(value_array);
        const lookup = try self.createKeyedStoreLookupFromNamesValue(names);

        const owned_path = try self.allocator.dupe(u8, store.path);
        errdefer self.allocator.free(owned_path);
        return try self.createManagedKeyedStore(owned_path, true, names, value_array, null, .dict, 0, lookup);
    }

    fn prototypeLikeValue(self: *Session, value: Value) KError!Value {
        if (tableScalarValue(value)) |scalar| return try self.tableNullScalarValue(scalar.kind);
        if (stringBytes(value) != null) return try self.managedHostString(&.{});
        if (symbolBytes(value) != null) return try self.emptySymbolValue();
        if (valueNumericMode(value)) |mode| return try self.numericPrototypeScalarValue(mode);
        return switch (value.tag()) {
            .int, .bool => try self.intNullValue(),
            .float32 => try self.float32Value(kiwiFloat32Null()),
            .float => try self.floatNullValue(),
            .array => switch (value.arrayKind()) {
                .host_string_list => try self.managedHostString(&.{}),
                .host_symbol_list => try self.emptySymbolValue(),
                .host_boxed_array => blk: {
                    const items = value.asHostBoxedArray().items;
                    if (items.len == 0) break :blk try self.managedHostString(&.{});
                    break :blk try self.prototypeLikeValue(items[0]);
                },
                .host_keyed_store => blk: {
                    const store = value.asHostKeyedStore();
                    if (store.layout != .dict) break :blk error.Type;
                    break :blk try self.keyedDictPrototypeLikeValue(store);
                },
                else => error.Type,
            },
            else => error.Type,
        };
    }

    fn takeCyclicStart(raw_count: i64, count: usize, source_len: usize) usize {
        std.debug.assert(source_len != 0);
        if (raw_count >= 0) return 0;
        const rem = count % source_len;
        return if (rem == 0) 0 else source_len - rem;
    }

    fn takeAtomBoxedValue(self: *Session, raw_count: i64, value: Value) KError!Value {
        const count: usize = @intCast(@abs(raw_count));
        if (count == 0) return try self.createManagedHostBoxedArray(&.{});

        const items = try self.allocator.alloc(Value, count);
        defer self.allocator.free(items);
        for (items) |*item| item.* = value;
        return try self.createManagedHostBoxedArray(items);
    }

    fn takeEmptyBoxedPrototypeValue(self: *Session, raw_count: i64, array: *const HostBoxedArray) KError!Value {
        const count: usize = @intCast(@abs(raw_count));
        if (count == 0) return try self.createManagedHostBoxedArray(&.{});

        const fill = if (array.prototype) |prototype|
            try self.retainEscapedValue(prototype)
        else
            try self.managedHostString(&.{});
        defer self.releaseValue(fill);
        const items = try self.allocator.alloc(Value, count);
        defer self.allocator.free(items);
        for (items) |*item| item.* = fill;
        return try self.createManagedHostBoxedArray(items);
    }

    fn prototypeValueForTake(self: *Session, value: Value) KError!?Value {
        if (stringBytes(value)) |bytes| {
            const spaces = try self.allocator.alloc(u8, bytes.len);
            defer self.allocator.free(spaces);
            @memset(spaces, ' ');
            return try self.managedHostString(spaces);
        }
        if (valueNumericMode(value)) |mode| {
            if (numericVectorLen(value)) |len| {
                return switch (mode) {
                    .int => try self.createManagedIntNullArray(len),
                    .float => try self.createManagedFloatNullArray(len),
                };
            }
        }
        if (value.tag() == .array and value.arrayKind() == .host_string_list) {
            const list = value.asHostStringList();
            const bytes = if (list.len == 0) &.{} else try hostStringListItemBytes(list, 0);
            const spaces = try self.allocator.alloc(u8, bytes.len);
            defer self.allocator.free(spaces);
            @memset(spaces, ' ');
            return try self.managedHostString(spaces);
        }
        if (value.tag() == .array and value.arrayKind() == .host_boxed_array) {
            const array = value.asHostBoxedArray();
            if (array.len() != 0) {
                const item_prototype = (try self.prototypeValueForTake(array.items[0])) orelse return null;
                defer self.releaseValue(item_prototype);
                return try self.createManagedHostBoxedArray(&.{item_prototype});
            }
            if (array.prototype) |prototype| {
                const item_prototype = (try self.prototypeValueForTake(prototype)) orelse return null;
                defer self.releaseValue(item_prototype);
                return try self.createManagedHostBoxedArrayWithPrototype(&.{}, item_prototype);
            }
        }
        if (value.tag() == .array and value.arrayKind() == .host_keyed_store) {
            const store = value.asHostKeyedStore();
            if (store.layout == .dict) return try self.keyedDictPrototypeLikeValue(store);
        }
        return null;
    }

    fn takeHostString(self: *Session, raw_count: i64, source: HostStringSource) KError!Value {
        const count: usize = @intCast(@abs(raw_count));
        if (count == 0) return try self.managedHostString(&.{});

        const bytes = source.bytes();
        const out = try self.allocator.alloc(u8, count);
        defer self.allocator.free(out);

        if (bytes.len == 0) {
            @memset(out, ' ');
        } else {
            const start = takeCyclicStart(raw_count, count, bytes.len);
            for (out, 0..) |*byte, idx| byte.* = bytes[(start + idx) % bytes.len];
        }
        return try self.managedHostCharVector(out);
    }

    fn takeHostSymbol(self: *Session, raw_count: i64, symbol: *const HostText) KError!Value {
        const count: usize = @intCast(@abs(raw_count));
        const items = try self.allocator.alloc([]const u8, count);
        defer self.allocator.free(items);
        const bytes = hostTextBytes(symbol);
        for (items) |*item| item.* = bytes;
        return try self.createManagedHostSymbolListFromSlices(items);
    }

    fn takeScalarValue(self: *Session, raw_count: i64, value: Value) KError!Value {
        if (raw_count == 0) {
            return switch (value.tag()) {
                .float32 => try self.createManagedHostFloat32Array(&.{}),
                .float => try self.createManagedHostFloatArray(&.{}),
                .int, .bool => try self.createManagedHostIntArray(&.{}),
                else => error.Type,
            };
        }
        const count: usize = @intCast(@abs(raw_count));
        switch (value.tag()) {
            .bool => {
                const out = try self.allocHostBitArray(.managed, count);
                bitFill(out.words, out.len, value.asBool());
                return try self.finishManagedHostBitAlloc(
                    out,
                    host_dense_flag_normalized | host_dense_flag_asc | host_dense_flag_dsc,
                    hostIntRangeForValue(@intFromBool(value.asBool())),
                );
            },
            .float32 => {
                var out = std.ArrayList(f32).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, count);
                for (0..count) |_| try out.append(self.allocator, value.asFloat32());
                return try self.createManagedHostFloat32Array(out.items);
            },
            .float => {
                var out = std.ArrayList(f64).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, count);
                for (0..count) |_| try out.append(self.allocator, value.asFloat());
                return try self.createManagedHostFloatArray(out.items);
            },
            .int => {
                var out = std.ArrayList(i64).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, count);
                for (0..count) |_| try out.append(self.allocator, value.asInt());
                return try self.createManagedHostIntArray(out.items);
            },
            else => return error.Type,
        }
    }

    fn takeHostArray(self: *Session, raw_count: i64, source_value: Value, array: *const HostDenseArray) KError!Value {
        if (valueNumericMatrixShape(source_value)) |shape| {
            const count: usize = @intCast(@abs(raw_count));
            if (count == 0) {
                const value = switch (array.storage) {
                    .bit => try self.createManagedHostBitArray(&.{}),
                    .float32 => try self.createManagedHostFloat32Array(&.{}),
                    .float64 => try self.createManagedHostFloatArray(&.{}),
                    else => try self.createManagedHostIntArray(&.{}),
                };
                return try self.setNumericMatrixShapeOnValue(value, 0, shape.cols);
            }
            if (shape.rows == 0) {
                const total = std.math.mul(usize, count, shape.cols) catch return error.Unsupported;
                const value = switch (array.storage) {
                    .float32 => try self.createManagedFloat32NullArray(total),
                    .float64 => try self.createManagedFloatNullArray(total),
                    else => try self.createManagedIntNullArray(total),
                };
                return try self.setNumericMatrixShapeOnValue(value, count, shape.cols);
            }

            var row_indices = std.ArrayList(usize).empty;
            defer row_indices.deinit(self.allocator);
            try row_indices.ensureTotalCapacity(self.allocator, count);
            const start = takeCyclicStart(raw_count, count, shape.rows);
            for (0..count) |idx| try row_indices.append(self.allocator, (start + idx) % shape.rows);
            return try self.createManagedHostNumericMatrixRows(array, row_indices.items, shape.cols);
        }
        const count: usize = @intCast(@abs(raw_count));
        if (count == 0) {
            return switch (array.storage) {
                .bit => try self.createManagedHostBitArray(&.{}),
                .float32 => try self.createManagedHostFloat32Array(&.{}),
                .float64 => try self.createManagedHostFloatArray(&.{}),
                else => try self.createManagedHostIntArray(&.{}),
            };
        }
        if (array.len() == 0) return try self.takeEmptyHostArrayPrototypeValue(raw_count, array);
        if (raw_count >= 0) {
            return switch (array.storage) {
                .bit => blk: {
                    const source = HostBitSlice{ .words = array.storage.bit, .len = array.logical_len };
                    const out = try self.allocHostBitArray(.managed, count);
                    var dst_start: usize = 0;
                    while (dst_start < count) {
                        const chunk_len = @min(source.len, count - dst_start);
                        bitCopyRange(out.words, dst_start, source, 0, chunk_len);
                        dst_start += chunk_len;
                    }
                    break :blk try self.finishManagedHostBitAlloc(
                        out,
                        if (count <= array.len()) array.flags else host_dense_flag_normalized,
                        sourceHostIntRange(source_value, array),
                    );
                },
                .float64 => |items| blk: {
                    const logical_items = hostDenseLogicalItems(f64, array, items);
                    var out = std.ArrayList(f64).empty;
                    defer out.deinit(self.allocator);
                    try out.ensureTotalCapacity(self.allocator, count);
                    for (0..count) |idx| try out.append(self.allocator, logical_items[idx % logical_items.len]);
                    break :blk try self.createManagedHostFloatArray(out.items);
                },
                .float32 => |items| blk: {
                    const logical_items = hostDenseLogicalItems(f32, array, items);
                    var out = std.ArrayList(f32).empty;
                    defer out.deinit(self.allocator);
                    try out.ensureTotalCapacity(self.allocator, count);
                    for (0..count) |idx| try out.append(self.allocator, logical_items[idx % logical_items.len]);
                    break :blk try self.createManagedHostFloat32Array(out.items);
                },
                else => blk: {
                    const view = hostIntArrayView(array).?;
                    var out = std.ArrayList(i64).empty;
                    defer out.deinit(self.allocator);
                    try out.ensureTotalCapacity(self.allocator, count);
                    for (0..count) |idx| try out.append(self.allocator, hostIntViewItem(view, idx % hostIntArrayViewLen(view)));
                    break :blk try self.createManagedHostIntArray(out.items);
                },
            };
        }
        return switch (array.storage) {
            .bit => blk: {
                const source = HostBitSlice{ .words = array.storage.bit, .len = array.logical_len };
                const out = try self.allocHostBitArray(.managed, count);
                const start = takeCyclicStart(raw_count, count, source.len);
                for (0..count) |idx| bitSet(out.words, idx, bitGet(source.words, (start + idx) % source.len));
                break :blk try self.finishManagedHostBitAlloc(
                    out,
                    if (count <= array.len()) array.flags else host_dense_flag_normalized,
                    sourceHostIntRange(source_value, array),
                );
            },
            .float64 => |items| blk: {
                const logical_items = hostDenseLogicalItems(f64, array, items);
                var out = std.ArrayList(f64).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, count);
                const start = takeCyclicStart(raw_count, count, logical_items.len);
                for (0..count) |idx| try out.append(self.allocator, logical_items[(start + idx) % logical_items.len]);
                break :blk try self.createManagedHostFloatArray(out.items);
            },
            .float32 => |items| blk: {
                const logical_items = hostDenseLogicalItems(f32, array, items);
                var out = std.ArrayList(f32).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, count);
                const start = takeCyclicStart(raw_count, count, logical_items.len);
                for (0..count) |idx| try out.append(self.allocator, logical_items[(start + idx) % logical_items.len]);
                break :blk try self.createManagedHostFloat32Array(out.items);
            },
            else => blk: {
                const view = hostIntArrayView(array).?;
                var out = std.ArrayList(i64).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, count);
                const view_len = hostIntArrayViewLen(view);
                const start = takeCyclicStart(raw_count, count, view_len);
                for (0..count) |idx| try out.append(self.allocator, hostIntViewItem(view, (start + idx) % view_len));
                break :blk try self.createManagedHostIntArray(out.items);
            },
        };
    }

    fn takeHostBoxedArray(self: *Session, raw_count: i64, array: *const HostBoxedArray) KError!Value {
        const count: usize = @intCast(@abs(raw_count));
        if (count == 0) {
            if (array.len() != 0) return try self.emptySequenceForBoxedItem(.managed, array.items[0]);
            if (array.prototype) |prototype| return try self.emptySequenceForBoxedItem(.managed, prototype);
            return try self.createManagedHostBoxedArray(&.{});
        }
        if (array.len() == 0) return try self.takeEmptyBoxedPrototypeValue(raw_count, array);

        var out = std.ArrayList(Value).empty;
        defer out.deinit(self.allocator);
        try out.ensureTotalCapacity(self.allocator, count);

        const start = takeCyclicStart(raw_count, count, array.len());
        for (0..count) |idx| try out.append(self.allocator, array.items[(start + idx) % array.len()]);
        return try self.createManagedHostBoxedArray(out.items);
    }

    fn takeHostStringList(self: *Session, raw_count: i64, list: *const HostStringList) KError!Value {
        const count: usize = @intCast(@abs(raw_count));
        if (count == 0) return try self.emptySequenceForHostStringList(list);
        if (list.len == 0) {
            const items = try self.allocator.alloc([]const u8, count);
            defer self.allocator.free(items);
            for (items) |*item| item.* = &.{};
            return try self.createManagedHostStringListFromSlices(items);
        }

        var out = std.ArrayList(Value).empty;
        defer out.deinit(self.allocator);
        defer {
            for (out.items) |item| self.releaseValue(item);
        }
        try out.ensureTotalCapacity(self.allocator, count);

        const start = takeCyclicStart(raw_count, count, list.len);
        for (0..count) |idx| try out.append(self.allocator, try self.hostStringListItemValue(list, (start + idx) % list.len));
        return try self.createManagedHostTextListFromValues(out.items);
    }

    fn takeHostSymbolList(self: *Session, raw_count: i64, list: *const HostStringList) KError!Value {
        const count: usize = @intCast(@abs(raw_count));
        if (count == 0) return try self.createManagedHostSymbolListFromSlices(&.{});

        const items = try self.allocator.alloc([]const u8, count);
        defer self.allocator.free(items);
        if (list.len == 0) {
            for (items) |*item| item.* = &.{};
        } else {
            const start = takeCyclicStart(raw_count, count, list.len);
            for (items, 0..) |*item, idx| item.* = try hostStringListItemBytes(list, (start + idx) % list.len);
        }
        return try self.createManagedHostSymbolListFromSlices(items);
    }

    fn undSequenceLen(value: Value) ?usize {
        if (stringSourceInfo(value)) |source| return source.bytes().len;
        if (value.tag() == .array and value.arrayKind() == .host_keyed_store) {
            const store = value.asHostKeyedStore();
            return switch (store.layout) {
                .dict => null,
                .table => store.row_count,
            };
        }
        return derivedSequenceLen(value);
    }

    fn sourceIndicesFromRange(self: *Session, start: usize, end: usize) KError![]usize {
        if (end < start) return error.Type;
        const out = try self.allocator.alloc(usize, end - start);
        errdefer self.allocator.free(out);
        for (out, start..) |*item, idx| item.* = idx;
        return out;
    }

    fn sourceIndicesExcludingIndex(self: *Session, len: usize, remove_idx: usize) KError![]usize {
        if (remove_idx >= len) return error.Internal;
        const out = try self.allocator.alloc(usize, len - 1);
        errdefer self.allocator.free(out);
        var write_idx: usize = 0;
        for (0..len) |idx| {
            if (idx == remove_idx) continue;
            out[write_idx] = idx;
            write_idx += 1;
        }
        return out;
    }

    fn selectSequenceRange(self: *Session, value: Value, start: usize, end: usize) KError!Value {
        if (start == end and value.tag() == .array and value.arrayKind() == .host_boxed_array) {
            const array = value.asHostBoxedArray();
            if (array.len() != 0) return try self.emptySequenceForBoxedItem(.managed, array.items[@min(start, array.len() - 1)]);
            if (array.prototype) |prototype| return try self.emptySequenceForBoxedItem(.managed, prototype);
        }
        const indices = try self.sourceIndicesFromRange(start, end);
        defer self.allocator.free(indices);
        return try self.selectRightBySourceIndices(value, indices);
    }

    fn removeSequenceIndex(self: *Session, left: Value, raw_index: i64) KError!Value {
        if (raw_index < 0) return self.shareValue(left);
        const len = undSequenceLen(left) orelse return error.Type;
        const remove_idx = std.math.cast(usize, raw_index) orelse return self.shareValue(left);
        if (remove_idx >= len) return self.shareValue(left);

        const indices = try self.sourceIndicesExcludingIndex(len, remove_idx);
        defer self.allocator.free(indices);
        return try self.selectRightBySourceIndices(left, indices);
    }

    fn cutValues(self: *Session, left: Value, right: Value) KError!Value {
        const view = valueHostIntStructuralView(left) orelse return error.Type;
        const cut_count = hostIntDenseViewLen(view);
        const source_len = undSequenceLen(right) orelse return error.Type;

        if (cut_count == 0) {
            const prototype = try self.selectSequenceRange(right, 0, 0);
            defer self.releaseValue(prototype);
            return try self.createManagedHostBoxedArrayWithPrototype(&.{}, prototype);
        }

        const cuts = try self.allocator.alloc(usize, cut_count);
        defer self.allocator.free(cuts);
        var previous: usize = 0;
        for (cuts, 0..) |*cut, idx| {
            const raw_cut = try hostIntDenseViewItem(view, idx);
            if (raw_cut < 0) return error.Type;
            const cut_idx = std.math.cast(usize, raw_cut) orelse return error.Unsupported;
            if (cut_idx > source_len or (idx != 0 and cut_idx < previous)) return error.Type;
            cut.* = cut_idx;
            previous = cut_idx;
        }

        const values = try self.allocator.alloc(Value, cut_count);
        defer self.allocator.free(values);
        var initialized: usize = 0;
        defer {
            for (values[0..initialized]) |value| self.releaseValue(value);
        }
        for (cuts, 0..) |start, idx| {
            const end = if (idx + 1 < cut_count) cuts[idx + 1] else source_len;
            values[idx] = try self.selectSequenceRange(right, start, end);
            initialized += 1;
        }
        return try self.makeArrayFromValues(values);
    }

    fn dropValues(self: *Session, left: Value, right: Value) KError!Value {
        switch (left.tag()) {
            .builtin, .closure => return try self.rejectValues(left, right),
            else => {},
        }
        if (left.tag() == .array and left.arrayKind() == .host_keyed_store and left.asHostKeyedStore().layout == .dict) {
            return try self.keyedDictDeleteKeys(left.asHostKeyedStore(), right);
        }
        if (scalarIntLikeValue(right)) |raw_index| {
            if (undSequenceLen(left) != null) return try self.removeSequenceIndex(left, raw_index);
        }
        if (scalarIntLikeValue(left) == null and valueHostIntStructuralView(left) != null and undSequenceLen(right) != null) {
            return try self.cutValues(left, right);
        }

        const raw_count = scalarIntLikeValue(left) orelse return error.Type;
        if (stringSourceInfo(right)) |source| {
            return try self.dropHostString(raw_count, source);
        }
        if (right.tag() == .array and right.arrayKind() == .host_string_list) {
            return try self.dropHostStringList(raw_count, right.asHostStringList());
        }
        if (right.tag() == .array and right.arrayKind() == .host_symbol_list) {
            return try self.dropHostSymbolList(raw_count, right.asHostStringList());
        }
        if (boxedSingletonCharSourceInfo(right)) |source| {
            return try self.dropHostString(raw_count, source);
        }
        if (right.tag() == .array and right.arrayKind() == .host_keyed_store) {
            const store = right.asHostKeyedStore();
            return switch (store.layout) {
                .dict => try self.keyedDictDropValue(raw_count, store),
                .table => try self.tableDropValue(raw_count, store),
            };
        }
        if (right.tag() == .array and right.arraySubkind() == .host_boxed_array) {
            return try self.dropHostBoxedArray(raw_count, right.asHostBoxedArray());
        }
        if (valueNumericMatrixView(right)) |matrix| {
            const bounds = dropSliceBounds(raw_count, matrix.shape.rows);
            var row_indices = std.ArrayList(usize).empty;
            defer row_indices.deinit(self.allocator);
            try row_indices.ensureTotalCapacity(self.allocator, bounds.end - bounds.start);
            for (bounds.start..bounds.end) |idx| try row_indices.append(self.allocator, idx);
            return try numericValueMatrixSelectRows(self, right, row_indices.items);
        }
        if (shapedNumericHandle(right)) |handle| {
            const rows: usize = @intCast(handle.shape[0]);
            const bounds = dropSliceBounds(raw_count, rows);
            if (try numericValueFirstAxisContiguousSliceValue(self, right, .{ .start = bounds.start, .len = bounds.end - bounds.start })) |result| return result;
        }
        if (NumericStructuralView.init(right)) |structural| {
            if (try numericStructuralDropValue(self, structural, raw_count)) |result| return result;
        }
        if (valueNumericMode(right) != null) {
            if (numericVectorLen(right)) |len| {
                const bounds = dropSliceBounds(raw_count, len);
                return try newFlatSliceValue(self, right, bounds.start, bounds.end - bounds.start);
            }
        }
        const array = try numericHostArrayValue(self, right);
        if (valueNumericMatrixShape(right)) |shape| {
            const bounds = dropSliceBounds(raw_count, shape.rows);
            var row_indices = std.ArrayList(usize).empty;
            defer row_indices.deinit(self.allocator);
            try row_indices.ensureTotalCapacity(self.allocator, bounds.end - bounds.start);
            for (bounds.start..bounds.end) |idx| try row_indices.append(self.allocator, idx);
            return try self.createManagedHostNumericMatrixRows(array, row_indices.items, shape.cols);
        }
        const len = array.len();
        const bounds = dropSliceBounds(raw_count, len);
        return switch (array.storage) {
            .bit => blk: {
                const out = try self.allocHostBitArray(.managed, bounds.end - bounds.start);
                bitCopyRange(out.words, 0, .{ .words = array.storage.bit, .len = array.logical_len }, bounds.start, bounds.end - bounds.start);
                break :blk try self.finishManagedHostBitAlloc(out, array.flags, sourceHostIntRange(right, array));
            },
            .float64 => |items| try self.createManagedHostFloatArray(hostDenseLogicalItems(f64, array, items)[bounds.start..bounds.end]),
            else => blk: {
                const view = hostIntArrayView(array).?;
                var out = std.ArrayList(i64).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, bounds.end - bounds.start);
                for (bounds.start..bounds.end) |idx| try out.append(self.allocator, hostIntViewItem(view, idx));
                break :blk try self.createManagedHostIntArray(out.items);
            },
        };
    }

    fn dropHostBoxedArray(self: *Session, raw_count: i64, array: *const HostBoxedArray) KError!Value {
        const len = array.len();
        const bounds = dropSliceBounds(raw_count, len);
        const items = array.items[bounds.start..bounds.end];
        if (items.len == 0) {
            if (array.len() != 0) return try self.emptySequenceForBoxedItem(.managed, array.items[0]);
            if (array.prototype) |prototype| return try self.emptySequenceForBoxedItem(.managed, prototype);
        }
        if (try self.tryCreateCharVectorFromSingletonStringItems(items)) |text| return text;
        if (items.len != 0 and boxedItemsCanNumericNormalize(items)) {
            return try self.makeArrayFromValues(items);
        }
        return try self.createManagedHostBoxedArray(items);
    }

    fn dropHostString(self: *Session, raw_count: i64, source: HostStringSource) KError!Value {
        const bounds = dropSliceBounds(raw_count, source.bytes().len);
        const len = bounds.end - bounds.start;
        if (source.is_vector and len == 1) {
            return try self.managedHostCharVector(source.bytes()[bounds.start..bounds.end]);
        }
        return try self.managedHostStringViewWithReason(source.base, .{
            .start = source.span.start + bounds.start,
            .len = len,
        }, .generic);
    }

    fn dropHostStringList(self: *Session, raw_count: i64, list: *const HostStringList) KError!Value {
        const bounds = dropSliceBounds(raw_count, list.len);
        if (bounds.start == bounds.end) return try self.emptySequenceForHostStringList(list);

        var out = std.ArrayList(Value).empty;
        defer out.deinit(self.allocator);
        defer {
            for (out.items) |item| self.releaseValue(item);
        }
        try out.ensureTotalCapacity(self.allocator, bounds.end - bounds.start);
        for (bounds.start..bounds.end) |idx| try out.append(self.allocator, try self.hostStringListItemValue(list, idx));
        return try self.createManagedHostTextListFromValues(out.items);
    }

    fn dropHostSymbolList(self: *Session, raw_count: i64, list: *const HostStringList) KError!Value {
        const bounds = dropSliceBounds(raw_count, list.len);

        const items = try self.allocator.alloc([]const u8, bounds.end - bounds.start);
        defer self.allocator.free(items);
        for (items, bounds.start..) |*item, idx| item.* = try hostStringListItemBytes(list, idx);
        return try self.createManagedHostSymbolListFromSlices(items);
    }

    fn reshapeValues(self: *Session, left: Value, right: Value) KError!Value {
        const row_len_value = scalarIntLikeValue(left) orelse return error.Type;
        if (row_len_value <= 0) return error.Type;

        const row_len: usize = @intCast(row_len_value);
        const total = numericFlatLen(right) orelse if (right.tag() == .array)
            (try numericHostArrayValue(self, right)).len()
        else
            return error.Type;
        if (total == 0 or total % row_len != 0) return error.Unsupported;

        const rows = total / row_len;
        if (valueRangeIotaHandle(right)) |handle| {
            return try newRangeIotaValueWithShape(
                self,
                .managed,
                total,
                numericArrayRangeIota(handle).start,
                numericArrayRangeIota(handle).step,
                numericShapeSnapshotMatrix(rows, row_len),
            );
        }
        if (valueNumericMode(right) != null) {
            return try newReshapeViewValue(self, right, numericShapeSnapshotMatrix(rows, row_len));
        }

        const source = try numericHostArrayValue(self, right);
        if (right.arraySubkind() != .host_boxed_array) {
            const value = switch (source.storage) {
                .bit => blk: {
                    const out = try self.allocHostBitArray(.managed, total);
                    bitCopyRange(out.words, 0, .{ .words = source.storage.bit, .len = source.logical_len }, 0, total);
                    break :blk try self.finishManagedHostBitAlloc(out, source.flags, sourceHostIntRange(right, source));
                },
                .float64 => |items| try self.createManagedHostFloatArray(hostDenseLogicalItems(f64, source, items)),
                else => blk: {
                    const view = hostIntArrayView(source) orelse return error.Type;
                    var out = std.ArrayList(i64).empty;
                    defer out.deinit(self.allocator);
                    try out.ensureTotalCapacity(self.allocator, total);
                    for (0..total) |idx| try out.append(self.allocator, hostIntViewItem(view, idx));
                    break :blk try self.createManagedHostIntArray(out.items);
                },
            };
            return try self.setNumericMatrixShapeOnValue(value, rows, row_len);
        }

        var outer = std.ArrayList(Value).empty;
        defer {
            for (outer.items) |value| self.releaseValue(value);
            outer.deinit(self.allocator);
        }
        try outer.ensureTotalCapacity(self.allocator, rows);

        for (0..rows) |row_idx| {
            var inner = std.ArrayList(Value).empty;
            defer inner.deinit(self.allocator);
            try inner.ensureTotalCapacity(self.allocator, row_len);
            const start = row_idx * row_len;
            for (0..row_len) |col_idx| {
                try inner.append(self.allocator, try self.hostDenseIndexScalar(right, source, @intCast(start + col_idx)));
            }
            try outer.append(self.allocator, try self.createManagedArrayLikeFromValues(inner.items));
        }
        return try self.createManagedArrayLikeFromValues(outer.items);
    }

    fn equalValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(.equal, left, right)) |result| return result;
        if (try self.promoteRenderableNumericDyadOperands(left, right)) |operands| {
            return try self.equalValues(operands.left, operands.right);
        }
        if (try self.equalStringByteValues(left, right)) |result| return result;
        if (try self.tryApplyDictAtomicDyadValue(.equal, left, right)) |result| return result;
        if (left.tag() == .array and left.arrayKind() == .host_keyed_store and
            !(right.tag() == .array and right.arrayKind() == .host_keyed_store))
        {
            const store = left.asHostKeyedStore();
            if (store.layout == .dict) return try self.equalDictScalarValues(store, right, true);
        }
        if (right.tag() == .array and right.arrayKind() == .host_keyed_store and
            !(left.tag() == .array and left.arrayKind() == .host_keyed_store))
        {
            const store = right.asHostKeyedStore();
            if (store.layout == .dict) return try self.equalDictScalarValues(store, left, false);
        }
        const left_table_scalar = tableScalarValue(left) != null;
        const right_table_scalar = tableScalarValue(right) != null;
        if ((left.tag() != .array and right.tag() != .array) or left_table_scalar or right_table_scalar) {
            if (left.tag() == .float or right.tag() == .float) {
                const lhs = switch (left.tag()) {
                    .float => left.asFloat(),
                    .int => @as(f64, @floatFromInt(left.asInt())),
                    .bool => @as(f64, @floatFromInt(@intFromBool(left.asBool()))),
                    else => scalarNumericFloatValue(left) orelse return error.Type,
                };
                const rhs = switch (right.tag()) {
                    .float => right.asFloat(),
                    .int => @as(f64, @floatFromInt(right.asInt())),
                    .bool => @as(f64, @floatFromInt(@intFromBool(right.asBool()))),
                    else => scalarNumericFloatValue(right) orelse return error.Type,
                };
                return Value.fromBool(lhs == rhs);
            }
            const lhs = scalarIntLikeValue(left) orelse return error.Type;
            const rhs = scalarIntLikeValue(right) orelse return error.Type;
            return Value.fromBool(lhs == rhs);
        }
        return try self.equalArrayValues(left, right);
    }

    fn equalDictScalarValues(self: *Session, store: *const HostKeyedStore, other: Value, dict_on_left: bool) KError!Value {
        const len = keyedStoreValuesValueCount(store.values) orelse return error.Internal;
        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, len);

        for (0..len) |idx| {
            const item = try self.keyedStoreValueAt(store, idx);
            errdefer self.releaseValue(item);
            const result = if (dict_on_left)
                try self.equalValues(item, other)
            else
                try self.equalValues(other, item);
            self.releaseValue(item);
            try results.append(self.allocator, result);
        }

        const values_value = try self.createManagedArrayLikeFromValues(results.items);
        defer self.releaseValue(values_value);
        return try self.createDictLikeValue(store, values_value);
    }

    fn compareScalars(self: *Session, op: BuiltinId, left: Value, right: Value) KError!Value {
        _ = self;
        if (left.tag() == .float or right.tag() == .float) {
            const lhs = switch (left.tag()) {
                .float => left.asFloat(),
                .int => @as(f64, @floatFromInt(left.asInt())),
                .bool => @as(f64, @floatFromInt(@intFromBool(left.asBool()))),
                else => return error.Type,
            };
            const rhs = switch (right.tag()) {
                .float => right.asFloat(),
                .int => @as(f64, @floatFromInt(right.asInt())),
                .bool => @as(f64, @floatFromInt(@intFromBool(right.asBool()))),
                else => return error.Type,
            };
            return Value.fromBool(switch (op) {
                .less => lhs < rhs,
                .more => lhs > rhs,
                else => return error.Internal,
            });
        }
        const lhs = scalarIntLikeValue(left) orelse return error.Type;
        const rhs = scalarIntLikeValue(right) orelse return error.Type;
        return Value.fromBool(switch (op) {
            .less => lhs < rhs,
            .more => lhs > rhs,
            else => return error.Internal,
        });
    }

    fn tryFastHostBitCompare(self: *Session, op: BuiltinId, left: Value, right: Value, shape: ?NumericShapeSnapshot) KError!?Value {
        const left_bits = valueNumericBitSlice(left) orelse return null;
        const right_bits = valueNumericBitSlice(right) orelse return null;
        if (left_bits.len != right_bits.len) return error.Type;

        if (enable_packed_bit_simd) {
            var out = try self.allocManagedHostIntResult(.bit, left_bits.len);
            fillBitWordsBinary(out.bit.words, op, left_bits.words, right_bits.words);
            bitClearUnusedTail(out.bit.words, out.bit.len);
            const result = out.value();
            self.noteSimdKernel(.packed_bool);
            return try applyNonVectorNumericShapeToValue(self, result, shape);
        }
        return null;
    }

    fn hostCompareOpCode(op: BuiltinId) ?i32 {
        return switch (op) {
            .equal => host_compare_op_equal,
            .less => host_compare_op_less,
            .more => host_compare_op_more,
            else => null,
        };
    }

    fn finishFastHostCompareResult(self: *Session, out: HostBitAlloc, shape: ?NumericShapeSnapshot) KError!Value {
        var summary: HostCompareSummary = undefined;
        kiwi_host_compare_last_summary(&summary);
        return try self.finishFastHostCompareResultWithSummary(out, shape, summary);
    }

    fn finishFastHostCompareResultWithSummary(self: *Session, out: HostBitAlloc, shape: ?NumericShapeSnapshot, summary: HostCompareSummary) KError!Value {
        const metadata = hostCompareSummaryMetadata(summary);
        const result = try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
        return try applyNonVectorNumericShapeToValue(self, result, shape);
    }

    fn finishConstantHostCompareResult(self: *Session, len: usize, value: bool, shape: ?NumericShapeSnapshot) KError!Value {
        const out = try self.allocHostBitArrayUninitialized(.managed, len);
        bitFill(out.words, out.len, value);
        const metadata = (BitSequenceStats{
            .saw_zero = !value,
            .saw_one = value,
        }).metadata();
        const result = try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
        return try applyNonVectorNumericShapeToValue(self, result, shape);
    }

    fn rangeIotaCompareConstantTruth(op: BuiltinId, left: *const NumericArray, right: *const NumericArray, len: usize) KError!?bool {
        if (len == 0) return false;
        const left_range = numericArrayRangeIota(left);
        const right_range = numericArrayRangeIota(right);
        const diff_start = @as(i128, left_range.start) - @as(i128, right_range.start);
        const diff_step = @as(i128, left_range.step) - @as(i128, right_range.step);
        const span = std.math.mul(i128, diff_step, @as(i128, @intCast(len - 1))) catch return error.Unsupported;
        const diff_last = std.math.add(i128, diff_start, span) catch return error.Unsupported;
        const diff_min = @min(diff_start, diff_last);
        const diff_max = @max(diff_start, diff_last);
        return switch (op) {
            .less => if (diff_max < 0) true else if (diff_min >= 0) false else null,
            .more => if (diff_min > 0) true else if (diff_max <= 0) false else null,
            .equal => if (diff_start == 0 and diff_step == 0) true else if (diff_min > 0 or diff_max < 0) false else null,
            else => null,
        };
    }

    fn tryFastHostRangeCompare(self: *Session, op: BuiltinId, left: Value, right: Value, shape: ?NumericShapeSnapshot) KError!?Value {
        const left_range = valueRangeIotaHandle(left) orelse return null;
        const right_range = valueRangeIotaHandle(right) orelse return null;
        const len = try arrayResultLen(left, right);
        if (numericArrayRangeLen(left_range) != len or numericArrayRangeLen(right_range) != len) return error.Type;
        const value = (try rangeIotaCompareConstantTruth(op, left_range, right_range, len)) orelse return null;
        return try self.finishConstantHostCompareResult(len, value, shape);
    }

    const HostCompareIntDensePtr = struct {
        ptr: *const anyopaque,
        width: i32,
        len: usize,
    };

    fn hostCompareIntDensePtr(view: HostIntArrayView) ?HostCompareIntDensePtr {
        return switch (view) {
            .int8 => |items| .{ .ptr = @ptrCast(items.ptr), .width = 1, .len = items.len },
            .int16 => |items| .{ .ptr = @ptrCast(items.ptr), .width = 2, .len = items.len },
            .int32 => |items| .{ .ptr = @ptrCast(items.ptr), .width = 4, .len = items.len },
            .int64 => |items| .{ .ptr = @ptrCast(items.ptr), .width = 8, .len = items.len },
            .bit => null,
        };
    }

    fn fillFastHostCompareIntArrays(out: *HostBitAlloc, op_code: i32, left: HostIntArrayView, right: HostIntArrayView) bool {
        if (comptime !enable_host_compare_vectorized) return false;
        if (hostIntArrayViewLen(left) != hostIntArrayViewLen(right)) return false;
        switch (left) {
            .int8 => |left_items| switch (right) {
                .int8 => |right_items| {
                    kiwi_host_compare_i8_array(out.words.ptr, left_items.ptr, right_items.ptr, left_items.len, op_code);
                    return true;
                },
                else => {},
            },
            .int16 => |left_items| switch (right) {
                .int16 => |right_items| {
                    kiwi_host_compare_i16_array(out.words.ptr, left_items.ptr, right_items.ptr, left_items.len, op_code);
                    return true;
                },
                else => {},
            },
            .int32 => |left_items| switch (right) {
                .int32 => |right_items| {
                    kiwi_host_compare_i32_array(out.words.ptr, left_items.ptr, right_items.ptr, left_items.len, op_code);
                    return true;
                },
                else => {},
            },
            .int64 => |left_items| switch (right) {
                .int64 => |right_items| {
                    kiwi_host_compare_i64_array(out.words.ptr, left_items.ptr, right_items.ptr, left_items.len, op_code);
                    return true;
                },
                else => {},
            },
            .bit => return false,
        }
        const left_ptr = hostCompareIntDensePtr(left) orelse return false;
        const right_ptr = hostCompareIntDensePtr(right) orelse return false;
        if (left_ptr.len != right_ptr.len) return false;
        kiwi_host_compare_int_mixed_array(out.words.ptr, left_ptr.ptr, left_ptr.width, right_ptr.ptr, right_ptr.width, left_ptr.len, op_code);
        return true;
    }

    fn useZigFastHostCompareIntArrays(left: HostIntArrayView, right: HostIntArrayView) bool {
        if (comptime enable_host_compare_zig_vectorized) return true;
        if (comptime !enable_host_compare_vectorized) return false;
        return switch (left) {
            .int64 => switch (right) {
                .int64 => true,
                else => false,
            },
            else => false,
        };
    }

    fn fillFastHostCompareIntFloatArray(out: *HostBitAlloc, op_code: i32, int_items: HostIntArrayView, float_items: []const f64, int_left: bool) bool {
        if (comptime !enable_host_compare_vectorized) return false;
        const int_ptr = hostCompareIntDensePtr(int_items) orelse return false;
        if (int_ptr.len != float_items.len) return false;
        kiwi_host_compare_int_f64_array(out.words.ptr, int_ptr.ptr, int_ptr.width, float_items.ptr, int_ptr.len, if (int_left) 1 else 0, op_code);
        return true;
    }

    fn canFastHostCompareIntArrays(left: HostIntArrayView, right: HostIntArrayView) bool {
        if (hostIntArrayViewLen(left) != hostIntArrayViewLen(right)) return false;
        return hostCompareIntDensePtr(left) != null and hostCompareIntDensePtr(right) != null;
    }

    fn canFastHostCompareIntScalar(items: HostIntArrayView, scalar: i64) bool {
        return switch (items) {
            .int8 => std.math.cast(i8, scalar) != null,
            .int16 => std.math.cast(i16, scalar) != null,
            .int32 => std.math.cast(i32, scalar) != null,
            .int64 => true,
            .bit => false,
        };
    }

    fn fillFastHostCompareIntScalar(out: *HostBitAlloc, op_code: i32, items: HostIntArrayView, scalar: i64, scalar_left: bool) bool {
        if (comptime !enable_host_compare_vectorized) return false;
        const scalar_left_int: i32 = if (scalar_left) 1 else 0;
        switch (items) {
            .int8 => |view| {
                const typed_scalar = std.math.cast(i8, scalar) orelse return false;
                kiwi_host_compare_i8_scalar(out.words.ptr, view.ptr, view.len, typed_scalar, scalar_left_int, op_code);
                return true;
            },
            .int16 => |view| {
                const typed_scalar = std.math.cast(i16, scalar) orelse return false;
                kiwi_host_compare_i16_scalar(out.words.ptr, view.ptr, view.len, typed_scalar, scalar_left_int, op_code);
                return true;
            },
            .int32 => |view| {
                const typed_scalar = std.math.cast(i32, scalar) orelse return false;
                kiwi_host_compare_i32_scalar(out.words.ptr, view.ptr, view.len, typed_scalar, scalar_left_int, op_code);
                return true;
            },
            .int64 => |view| {
                kiwi_host_compare_i64_scalar(out.words.ptr, view.ptr, view.len, scalar, scalar_left_int, op_code);
                return true;
            },
            .bit => return false,
        }
    }

    fn useZigFastHostCompareIntScalar(items: HostIntArrayView) bool {
        if (comptime enable_host_compare_zig_vectorized) return true;
        if (comptime !enable_host_compare_vectorized) return false;
        return switch (items) {
            .int64 => true,
            else => false,
        };
    }

    fn finishFastHostCompareIntArrays(self: *Session, len: usize, shape: ?NumericShapeSnapshot, op: BuiltinId, op_code: i32, left: HostIntArrayView, right: HostIntArrayView) KError!?Value {
        var out = try self.allocHostBitArrayUninitialized(.managed, len);
        if (useZigFastHostCompareIntArrays(left, right)) {
            const summary = switch (op) {
                .equal => fillZigHostCompareIntArraysOp(.equal, &out, left, right),
                .less => fillZigHostCompareIntArraysOp(.less, &out, left, right),
                .more => fillZigHostCompareIntArraysOp(.more, &out, left, right),
                else => null,
            } orelse return null;
            self.noteSimdKernel(.compare);
            return try self.finishFastHostCompareResultWithSummary(out, shape, summary);
        }
        if (!fillFastHostCompareIntArrays(&out, op_code, left, right)) return null;
        self.noteSimdKernel(.compare);
        return try self.finishFastHostCompareResult(out, shape);
    }

    fn finishFastHostCompareIntScalar(self: *Session, len: usize, shape: ?NumericShapeSnapshot, op: BuiltinId, op_code: i32, items: HostIntArrayView, scalar: i64, scalar_left: bool) KError!?Value {
        var out = try self.allocHostBitArrayUninitialized(.managed, len);
        if (useZigFastHostCompareIntScalar(items)) {
            const maybe_summary = if (scalar_left) switch (op) {
                .equal => fillZigHostCompareIntScalarOp(.equal, true, &out, items, scalar),
                .less => fillZigHostCompareIntScalarOp(.less, true, &out, items, scalar),
                .more => fillZigHostCompareIntScalarOp(.more, true, &out, items, scalar),
                else => null,
            } else switch (op) {
                .equal => fillZigHostCompareIntScalarOp(.equal, false, &out, items, scalar),
                .less => fillZigHostCompareIntScalarOp(.less, false, &out, items, scalar),
                .more => fillZigHostCompareIntScalarOp(.more, false, &out, items, scalar),
                else => null,
            };
            const summary = maybe_summary orelse return null;
            self.noteSimdKernel(.compare);
            return try self.finishFastHostCompareResultWithSummary(out, shape, summary);
        }
        if (!fillFastHostCompareIntScalar(&out, op_code, items, scalar, scalar_left)) return null;
        self.noteSimdKernel(.compare);
        return try self.finishFastHostCompareResult(out, shape);
    }

    fn finishFastHostCompareIntSourcesTyped(
        self: *Session,
        comptime T: type,
        len: usize,
        shape: ?NumericShapeSnapshot,
        op: BuiltinId,
        left: DenseResolvedSource(T),
        right: DenseResolvedSource(T),
    ) KError!?Value {
        var out = try self.allocHostBitArrayUninitialized(.managed, len);
        const summary = fillDenseIntCompareSources(T, &out, op, left, right, len) orelse return null;
        self.noteSimdKernel(.compare);
        return try self.finishFastHostCompareResultWithSummary(out, shape, summary);
    }

    fn finishFastHostCompareMixedIntSourcesTyped(
        self: *Session,
        comptime LeftT: type,
        comptime RightT: type,
        len: usize,
        shape: ?NumericShapeSnapshot,
        op: BuiltinId,
        left: DenseMixedIntResolvedSource(LeftT),
        right: DenseMixedIntResolvedSource(RightT),
    ) KError!?Value {
        var out = try self.allocHostBitArrayUninitialized(.managed, len);
        const summary = fillDenseMixedIntCompareSources(LeftT, RightT, &out, op, left, right, len) orelse return null;
        self.noteSimdKernel(.compare);
        return try self.finishFastHostCompareResultWithSummary(out, shape, summary);
    }

    fn finishFastHostCompareIntArraySources(
        self: *Session,
        len: usize,
        shape: ?NumericShapeSnapshot,
        op: BuiltinId,
        left_items: HostIntArrayView,
        comptime left_reverse: bool,
        right_items: HostIntArrayView,
        comptime right_reverse: bool,
    ) KError!?Value {
        if (hostIntArrayViewLen(left_items) != hostIntArrayViewLen(right_items)) return null;
        inline for (.{ i8, i16, i32, i64 }) |LeftT| {
            if (denseIntArrayViewResolvedSource(LeftT, left_items, left_reverse)) |left_source| {
                inline for (.{ i8, i16, i32, i64 }) |RightT| {
                    if (denseIntArrayViewResolvedSource(RightT, right_items, right_reverse)) |right_source| {
                        if (comptime LeftT == RightT) {
                            return try self.finishFastHostCompareIntSourcesTyped(LeftT, len, shape, op, left_source, right_source);
                        }
                        return try self.finishFastHostCompareMixedIntSourcesTyped(
                            LeftT,
                            RightT,
                            len,
                            shape,
                            op,
                            denseMixedIntSourceFromResolved(LeftT, left_source).?,
                            denseMixedIntSourceFromResolved(RightT, right_source).?,
                        );
                    }
                }
            }
        }
        return null;
    }

    fn finishFastHostCompareIntScalarSource(
        self: *Session,
        len: usize,
        shape: ?NumericShapeSnapshot,
        op: BuiltinId,
        items: HostIntArrayView,
        comptime reverse_items: bool,
        scalar: i64,
        scalar_left: bool,
    ) KError!?Value {
        inline for (.{ i8, i16, i32, i64 }) |T| {
            if (denseIntArrayViewResolvedSource(T, items, reverse_items)) |item_source| {
                const typed_scalar = std.math.cast(T, scalar) orelse return null;
                const scalar_source = DenseResolvedSource(T){ .scalar = typed_scalar };
                return try self.finishFastHostCompareIntSourcesTyped(
                    T,
                    len,
                    shape,
                    op,
                    if (scalar_left) scalar_source else item_source,
                    if (scalar_left) item_source else scalar_source,
                );
            }
        }
        return null;
    }

    fn finishFastHostCompareIntFloatArray(self: *Session, len: usize, shape: ?NumericShapeSnapshot, op: BuiltinId, op_code: i32, int_items: HostIntArrayView, float_items: []const f64, int_left: bool) KError!?Value {
        if (std.meta.activeTag(int_items) == .bit) return null;
        if (hostIntArrayViewLen(int_items) != float_items.len) return null;
        var out = try self.allocHostBitArrayUninitialized(.managed, len);
        if (comptime enable_host_compare_zig_vectorized) {
            const maybe_summary = if (int_left) switch (op) {
                .equal => fillZigHostCompareIntFloatArrayOp(.equal, true, &out, int_items, float_items),
                .less => fillZigHostCompareIntFloatArrayOp(.less, true, &out, int_items, float_items),
                .more => fillZigHostCompareIntFloatArrayOp(.more, true, &out, int_items, float_items),
                else => null,
            } else switch (op) {
                .equal => fillZigHostCompareIntFloatArrayOp(.equal, false, &out, int_items, float_items),
                .less => fillZigHostCompareIntFloatArrayOp(.less, false, &out, int_items, float_items),
                .more => fillZigHostCompareIntFloatArrayOp(.more, false, &out, int_items, float_items),
                else => null,
            };
            const summary = maybe_summary orelse return null;
            self.noteSimdKernel(.compare);
            return try self.finishFastHostCompareResultWithSummary(out, shape, summary);
        }
        if (!fillFastHostCompareIntFloatArray(&out, op_code, int_items, float_items, int_left)) return null;
        self.noteSimdKernel(.compare);
        return try self.finishFastHostCompareResult(out, shape);
    }

    fn finishFastHostCompareFloatArraysTyped(self: *Session, comptime T: type, len: usize, shape: ?NumericShapeSnapshot, op: BuiltinId, left: []const T, right: []const T) KError!?Value {
        var out = try self.allocHostBitArrayUninitialized(.managed, len);
        const summary = switch (op) {
            .equal => fillZigHostCompareFloatArraysOp(T, .equal, &out, left, right),
            .less => fillZigHostCompareFloatArraysOp(T, .less, &out, left, right),
            .more => fillZigHostCompareFloatArraysOp(T, .more, &out, left, right),
            else => null,
        } orelse return null;
        self.noteSimdKernel(.compare);
        return try self.finishFastHostCompareResultWithSummary(out, shape, summary);
    }

    fn finishFastHostCompareFloat64PromotedSources(self: *Session, len: usize, shape: ?NumericShapeSnapshot, op: BuiltinId, left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource) KError!?Value {
        var out = try self.allocHostBitArrayUninitialized(.managed, len);
        const summary = fillDenseFloat64PromotedCompareSources(&out, op, left, right, len) orelse return null;
        self.noteSimdKernel(.compare);
        return try self.finishFastHostCompareResultWithSummary(out, shape, summary);
    }

    fn finishFastHostCompareFloatSourcesTyped(
        self: *Session,
        comptime T: type,
        len: usize,
        shape: ?NumericShapeSnapshot,
        op: BuiltinId,
        left: DenseResolvedSource(T),
        right: DenseResolvedSource(T),
    ) KError!?Value {
        var out = try self.allocHostBitArrayUninitialized(.managed, len);
        const summary = fillDenseFloatCompareSources(T, &out, op, left, right, len) orelse return null;
        self.noteSimdKernel(.compare);
        return try self.finishFastHostCompareResultWithSummary(out, shape, summary);
    }

    fn finishFastHostCompareIntFloatSourcesTyped(
        self: *Session,
        comptime T: type,
        comptime int_left: bool,
        len: usize,
        shape: ?NumericShapeSnapshot,
        op: BuiltinId,
        int_source: DenseResolvedSource(T),
        float_source: DenseFloat64PromotedSource,
    ) KError!?Value {
        var out = try self.allocHostBitArrayUninitialized(.managed, len);
        const summary = fillDenseIntFloatCompareSources(T, int_left, &out, op, int_source, float_source, len) orelse return null;
        self.noteSimdKernel(.compare);
        return try self.finishFastHostCompareResultWithSummary(out, shape, summary);
    }

    fn finishFastHostCompareIntFloatArraySource(
        self: *Session,
        comptime int_left: bool,
        len: usize,
        shape: ?NumericShapeSnapshot,
        op: BuiltinId,
        int_items: HostIntArrayView,
        reverse_int: bool,
        float_source: DenseFloat64PromotedSource,
    ) KError!?Value {
        return switch (int_items) {
            .bit => null,
            .int8 => |items| try self.finishFastHostCompareIntFloatSourcesTyped(i8, int_left, len, shape, op, if (reverse_int) .{ .reverse_array = items } else .{ .array = items }, float_source),
            .int16 => |items| try self.finishFastHostCompareIntFloatSourcesTyped(i16, int_left, len, shape, op, if (reverse_int) .{ .reverse_array = items } else .{ .array = items }, float_source),
            .int32 => |items| try self.finishFastHostCompareIntFloatSourcesTyped(i32, int_left, len, shape, op, if (reverse_int) .{ .reverse_array = items } else .{ .array = items }, float_source),
            .int64 => |items| try self.finishFastHostCompareIntFloatSourcesTyped(i64, int_left, len, shape, op, if (reverse_int) .{ .reverse_array = items } else .{ .array = items }, float_source),
        };
    }

    fn finishFastHostCompareIntScalarFloatSource(
        self: *Session,
        comptime int_left: bool,
        len: usize,
        shape: ?NumericShapeSnapshot,
        op: BuiltinId,
        scalar: i64,
        float_source: DenseFloat64PromotedSource,
    ) KError!?Value {
        return try self.finishFastHostCompareIntFloatSourcesTyped(i64, int_left, len, shape, op, .{ .scalar = scalar }, float_source);
    }

    fn finishFastHostCompareFloatScalarTyped(self: *Session, comptime T: type, len: usize, shape: ?NumericShapeSnapshot, op: BuiltinId, items: []const T, scalar: T, scalar_left: bool) KError!?Value {
        const scalar_source = DenseResolvedSource(T){ .scalar = scalar };
        const item_source = DenseResolvedSource(T){ .array = items };
        return try self.finishFastHostCompareFloatSourcesTyped(
            T,
            len,
            shape,
            op,
            if (scalar_left) scalar_source else item_source,
            if (scalar_left) item_source else scalar_source,
        );
    }

    fn tryFastHostDenseCompare(self: *Session, op: BuiltinId, left: Value, right: Value, shape: ?NumericShapeSnapshot) KError!?Value {
        if (comptime !enable_host_compare_fast) return null;
        const op_code = hostCompareOpCode(op) orelse return null;
        const len = try arrayResultLen(left, right);
        if (len < host_compare_vector_min_len) return null;
        if (rowwiseMatrixVectorDyad(left, right) != null) return null;

        const left_view = hostDenseView(self, left) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        const right_view = hostDenseView(self, right) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };

        switch (left_view) {
            .int_array => |left_items| switch (right_view) {
                .int_array => |right_items| {
                    if (left_items == .dense and right_items == .dense) {
                        if (!canFastHostCompareIntArrays(left_items.dense, right_items.dense)) return null;
                        return try self.finishFastHostCompareIntArrays(len, shape, op, op_code, left_items.dense, right_items.dense);
                    }
                    if (left_items == .dense) {
                        if (fullReverseIntDenseViewSource(right_items)) |right_source| {
                            return try self.finishFastHostCompareIntArraySources(len, shape, op, left_items.dense, false, right_source, true);
                        }
                    }
                    if (right_items == .dense) {
                        if (fullReverseIntDenseViewSource(left_items)) |left_source| {
                            return try self.finishFastHostCompareIntArraySources(len, shape, op, left_source, true, right_items.dense, false);
                        }
                    }
                    return null;
                },
                .scalar_int => |scalar| {
                    if (left_items == .dense) {
                        if (!canFastHostCompareIntScalar(left_items.dense, scalar)) return null;
                        return try self.finishFastHostCompareIntScalar(len, shape, op, op_code, left_items.dense, scalar, false);
                    }
                    if (fullReverseIntDenseViewSource(left_items)) |source| {
                        return try self.finishFastHostCompareIntScalarSource(len, shape, op, source, true, scalar, false);
                    }
                    return null;
                },
                .float_array => |right_items| {
                    if (left_items == .dense and right_items == .dense) {
                        return try self.finishFastHostCompareIntFloatArray(len, shape, op, op_code, left_items.dense, right_items.dense, true);
                    }
                    if (self.denseFloat64PromotedStoreSourceFromHostDenseView(.{ .float_array = right_items })) |right_source| {
                        if (left_items == .dense) {
                            return try self.finishFastHostCompareIntFloatArraySource(true, len, shape, op, left_items.dense, false, right_source);
                        }
                        if (fullReverseIntDenseViewSource(left_items)) |left_source| {
                            return try self.finishFastHostCompareIntFloatArraySource(true, len, shape, op, left_source, true, right_source);
                        }
                    }
                    return null;
                },
                .scalar_float => |scalar| {
                    const right_source = DenseFloat64PromotedSource{ .scalar = scalar };
                    if (left_items == .dense) {
                        return try self.finishFastHostCompareIntFloatArraySource(true, len, shape, op, left_items.dense, false, right_source);
                    }
                    if (fullReverseIntDenseViewSource(left_items)) |left_source| {
                        return try self.finishFastHostCompareIntFloatArraySource(true, len, shape, op, left_source, true, right_source);
                    }
                    return null;
                },
            },
            .scalar_int => |scalar| switch (right_view) {
                .int_array => |right_items| {
                    if (right_items == .dense) {
                        if (!canFastHostCompareIntScalar(right_items.dense, scalar)) return null;
                        return try self.finishFastHostCompareIntScalar(len, shape, op, op_code, right_items.dense, scalar, true);
                    }
                    if (fullReverseIntDenseViewSource(right_items)) |source| {
                        return try self.finishFastHostCompareIntScalarSource(len, shape, op, source, true, scalar, true);
                    }
                    return null;
                },
                .float_array => |right_items| {
                    if (right_items == .dense) {
                        return try self.finishFastHostCompareFloatScalarTyped(f64, len, shape, op, right_items.dense, @floatFromInt(scalar), true);
                    }
                    if (fullReverseFloatDenseViewSource64(right_items)) |source| {
                        return try self.finishFastHostCompareFloatSourcesTyped(f64, len, shape, op, .{ .scalar = @floatFromInt(scalar) }, .{ .reverse_array = source });
                    }
                    if (self.denseFloat64PromotedStoreSourceFromHostDenseView(.{ .float_array = right_items })) |source| {
                        return try self.finishFastHostCompareIntScalarFloatSource(true, len, shape, op, scalar, source);
                    }
                    return null;
                },
                else => {},
            },
            .float_array => |left_items| switch (right_view) {
                .float_array => |right_items| {
                    const left_f32 = hostFloatDenseViewDirectFloat32Slice(left_items);
                    const right_f32 = hostFloatDenseViewDirectFloat32Slice(right_items);
                    if (left_f32) |left_source| {
                        if (right_f32) |right_source| {
                            return try self.finishFastHostCompareFloatArraysTyped(f32, len, shape, op, left_source, right_source);
                        }
                        if (fullReverseFloatDenseViewSource32(right_items)) |right_source| {
                            return try self.finishFastHostCompareFloatSourcesTyped(f32, len, shape, op, .{ .array = left_source }, .{ .reverse_array = right_source });
                        }
                    }
                    if (right_f32) |right_source| {
                        if (fullReverseFloatDenseViewSource32(left_items)) |left_source| {
                            return try self.finishFastHostCompareFloatSourcesTyped(f32, len, shape, op, .{ .reverse_array = left_source }, .{ .array = right_source });
                        }
                    }
                    const left_promoted = self.denseFloat64PromotedStoreSourceFromHostDenseView(.{ .float_array = left_items });
                    const right_promoted = self.denseFloat64PromotedStoreSourceFromHostDenseView(.{ .float_array = right_items });
                    if (left_promoted) |left_source| {
                        if (right_promoted) |right_source| {
                            if (denseFloat64PromotedSourcesUseMixedStorage(left_source, right_source)) {
                                return try self.finishFastHostCompareFloat64PromotedSources(len, shape, op, left_source, right_source);
                            }
                        }
                    }
                    if (left_items == .dense and right_items == .dense) {
                        if (left_items.dense.len != right_items.dense.len) return error.Type;
                        return try self.finishFastHostCompareFloatArraysTyped(f64, len, shape, op, left_items.dense, right_items.dense);
                    }
                    if (left_items == .dense) {
                        if (fullReverseFloatDenseViewSource64(right_items)) |right_source| {
                            return try self.finishFastHostCompareFloatSourcesTyped(f64, len, shape, op, .{ .array = left_items.dense }, .{ .reverse_array = right_source });
                        }
                    }
                    if (right_items == .dense) {
                        if (fullReverseFloatDenseViewSource64(left_items)) |left_source| {
                            return try self.finishFastHostCompareFloatSourcesTyped(f64, len, shape, op, .{ .reverse_array = left_source }, .{ .array = right_items.dense });
                        }
                    }
                    return null;
                },
                .scalar_float => |scalar| {
                    if (scalarFloatStorageKind(right) == .float32) {
                        const typed_scalar: f32 = @floatCast(scalar);
                        if (hostFloatDenseViewDirectFloat32Slice(left_items)) |source| {
                            return try self.finishFastHostCompareFloatScalarTyped(f32, len, shape, op, source, typed_scalar, false);
                        }
                        if (fullReverseFloatDenseViewSource32(left_items)) |source| {
                            return try self.finishFastHostCompareFloatSourcesTyped(f32, len, shape, op, .{ .reverse_array = source }, .{ .scalar = typed_scalar });
                        }
                    }
                    if (self.denseFloat64PromotedStoreSourceFromHostDenseView(.{ .float_array = left_items })) |source| {
                        if (denseFloat64PromotedSourceUsesFloat32(source) and scalarFloatStorageKind(right) == .float64) {
                            return try self.finishFastHostCompareFloat64PromotedSources(len, shape, op, source, .{ .scalar = scalar });
                        }
                    }
                    if (left_items == .dense) {
                        return try self.finishFastHostCompareFloatScalarTyped(f64, len, shape, op, left_items.dense, scalar, false);
                    }
                    if (fullReverseFloatDenseViewSource64(left_items)) |source| {
                        return try self.finishFastHostCompareFloatSourcesTyped(f64, len, shape, op, .{ .reverse_array = source }, .{ .scalar = scalar });
                    }
                    return null;
                },
                .scalar_int => |scalar| {
                    if (left_items == .dense) {
                        return try self.finishFastHostCompareFloatScalarTyped(f64, len, shape, op, left_items.dense, @floatFromInt(scalar), false);
                    }
                    if (fullReverseFloatDenseViewSource64(left_items)) |source| {
                        return try self.finishFastHostCompareFloatSourcesTyped(f64, len, shape, op, .{ .reverse_array = source }, .{ .scalar = @floatFromInt(scalar) });
                    }
                    if (self.denseFloat64PromotedStoreSourceFromHostDenseView(.{ .float_array = left_items })) |source| {
                        return try self.finishFastHostCompareIntScalarFloatSource(false, len, shape, op, scalar, source);
                    }
                    return null;
                },
                .int_array => |right_items| {
                    if (left_items == .dense and right_items == .dense) {
                        return try self.finishFastHostCompareIntFloatArray(len, shape, op, op_code, right_items.dense, left_items.dense, false);
                    }
                    if (self.denseFloat64PromotedStoreSourceFromHostDenseView(.{ .float_array = left_items })) |left_source| {
                        if (right_items == .dense) {
                            return try self.finishFastHostCompareIntFloatArraySource(false, len, shape, op, right_items.dense, false, left_source);
                        }
                        if (fullReverseIntDenseViewSource(right_items)) |right_source| {
                            return try self.finishFastHostCompareIntFloatArraySource(false, len, shape, op, right_source, true, left_source);
                        }
                    }
                    return null;
                },
            },
            .scalar_float => |scalar| switch (right_view) {
                .float_array => |right_items| {
                    if (scalarFloatStorageKind(left) == .float32) {
                        const typed_scalar: f32 = @floatCast(scalar);
                        if (hostFloatDenseViewDirectFloat32Slice(right_items)) |source| {
                            return try self.finishFastHostCompareFloatScalarTyped(f32, len, shape, op, source, typed_scalar, true);
                        }
                        if (fullReverseFloatDenseViewSource32(right_items)) |source| {
                            return try self.finishFastHostCompareFloatSourcesTyped(f32, len, shape, op, .{ .scalar = typed_scalar }, .{ .reverse_array = source });
                        }
                    }
                    if (self.denseFloat64PromotedStoreSourceFromHostDenseView(.{ .float_array = right_items })) |source| {
                        if (denseFloat64PromotedSourceUsesFloat32(source) and scalarFloatStorageKind(left) == .float64) {
                            return try self.finishFastHostCompareFloat64PromotedSources(len, shape, op, .{ .scalar = scalar }, source);
                        }
                    }
                    if (right_items == .dense) {
                        return try self.finishFastHostCompareFloatScalarTyped(f64, len, shape, op, right_items.dense, scalar, true);
                    }
                    if (fullReverseFloatDenseViewSource64(right_items)) |source| {
                        return try self.finishFastHostCompareFloatSourcesTyped(f64, len, shape, op, .{ .scalar = scalar }, .{ .reverse_array = source });
                    }
                    return null;
                },
                .int_array => |right_items| {
                    const left_source = DenseFloat64PromotedSource{ .scalar = scalar };
                    if (right_items == .dense) {
                        return try self.finishFastHostCompareIntFloatArraySource(false, len, shape, op, right_items.dense, false, left_source);
                    }
                    if (fullReverseIntDenseViewSource(right_items)) |right_source| {
                        return try self.finishFastHostCompareIntFloatArraySource(false, len, shape, op, right_source, true, left_source);
                    }
                    return null;
                },
                else => {},
            },
        }
        return null;
    }

    fn compareNumericArrayValues(self: *Session, op: BuiltinId, left: Value, right: Value) KError!Value {
        if (planCompareMaskBackend(self, op, left, right) == .mlx) return try self.applyBackendArrayDyad(op, left, right);
        const shape = try nonVectorNumericShapeForDyad(left, right);
        if (try self.tryFastHostBitCompare(op, left, right, shape)) |result| return result;
        if (try self.tryFastHostRangeCompare(op, left, right, shape)) |result| return result;
        if (try self.tryFastHostDenseCompare(op, left, right, shape)) |result| return result;
        const len = try arrayResultLen(left, right);
        const rowwise = rowwiseMatrixVectorDyad(left, right);
        const out = try self.allocHostBitArray(.managed, len);
        var stats = BitSequenceStats{};
        const integer_compare = valueNumericMode(left) == .int and valueNumericMode(right) == .int;
        for (0..len) |idx| {
            const bit = if (integer_compare) blk: {
                const lhs = if (left.tag() == .array)
                    try numericIntAt(left, if (rowwise) |info| info.operandIndex(true, idx) else idx)
                else
                    scalarIntLikeValue(left).?;
                const rhs = if (right.tag() == .array)
                    try numericIntAt(right, if (rowwise) |info| info.operandIndex(false, idx) else idx)
                else
                    scalarIntLikeValue(right).?;
                break :blk switch (op) {
                    .less => lhs < rhs,
                    .more => lhs > rhs,
                    else => return error.Internal,
                };
            } else blk: {
                const lhs = if (left.tag() == .array)
                    try numericFloatAt(left, if (rowwise) |info| info.operandIndex(true, idx) else idx)
                else
                    scalarNumericFloatValue(left).?;
                const rhs = if (right.tag() == .array)
                    try numericFloatAt(right, if (rowwise) |info| info.operandIndex(false, idx) else idx)
                else
                    scalarNumericFloatValue(right).?;
                break :blk switch (op) {
                    .less => lhs < rhs,
                    .more => lhs > rhs,
                    else => return error.Internal,
                };
            };
            bitSet(out.words, idx, bit);
            stats.note(bit);
        }
        const metadata = stats.metadata();
        const result = try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
        return try applyNonVectorNumericShapeToValue(self, result, shape);
    }

    fn transposeHostDenseMatrixValue(self: *Session, value: Value, shape: NumericMatrixShape) KError!?Value {
        const out_shape = numericShapeSnapshotMatrix(shape.cols, shape.rows);
        const view = hostDenseView(self, value) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        return switch (view) {
            .float_array => |items| blk: {
                const out = try self.allocManagedHostFloatResult(shape.rows * shape.cols);
                for (0..shape.cols) |col_idx| {
                    for (0..shape.rows) |row_idx| {
                        out.items[col_idx * shape.rows + row_idx] = try hostFloatDenseViewItem(items, row_idx * shape.cols + col_idx);
                    }
                }
                const transposed = out.value();
                break :blk try applyNonVectorNumericShapeToValue(self, transposed, out_shape);
            },
            .int_array => |items| blk: {
                const range = hostIntDenseValueRange(value, items);
                const kind = hostIntStorageKindForRange(range.min, range.max);
                var out = try self.allocManagedHostIntResult(kind, shape.rows * shape.cols);
                for (0..shape.cols) |col_idx| {
                    for (0..shape.rows) |row_idx| {
                        try out.set(col_idx * shape.rows + row_idx, try hostIntDenseViewItem(items, row_idx * shape.cols + col_idx));
                    }
                }
                const transposed = out.value();
                const transposed_host = try mutableNumericHostArrayValue(self, transposed);
                hostDenseSetFlags(transposed_host, if (range.min >= 0 and range.max <= 1) host_dense_flag_normalized else 0);
                hostDenseSetCachedIntRange(transposed_host, range);
                break :blk try applyNonVectorNumericShapeToValue(self, transposed, out_shape);
            },
            else => null,
        };
    }

    fn transposeBackendMatrixValue(self: *Session, value: Value) KError!Value {
        if (comptime runtime_has_mlx) {
            return runtime_backend_exec.transposeBackendMatrixValue(backend_exec_api, self, value);
        }
        return error.Unsupported;
    }

    fn transposeBackendSwapAxesValue(self: *Session, value: Value, axis1: usize, axis2: usize) KError!Value {
        if (comptime runtime_has_mlx) {
            return runtime_backend_exec.transposeBackendSwapAxesValue(backend_exec_api, self, value, @intCast(axis1), @intCast(axis2));
        }
        return error.Unsupported;
    }

    fn transposeAxesSourceIndex(source_shape: []const i32, axis1: usize, axis2: usize, out_idx: usize) usize {
        var source_coords: [numeric_array_max_rank]usize = @as([numeric_array_max_rank]usize, @splat(0));
        var remaining = out_idx;
        var axis = source_shape.len;
        while (axis > 0) {
            axis -= 1;
            const source_axis = if (axis == axis1)
                axis2
            else if (axis == axis2)
                axis1
            else
                axis;
            const dim: usize = @intCast(source_shape[source_axis]);
            source_coords[source_axis] = if (dim == 0) 0 else remaining % dim;
            if (dim != 0) remaining /= dim;
        }

        var source_idx: usize = 0;
        for (source_shape, 0..) |dim_i32, source_axis| {
            const dim: usize = @intCast(dim_i32);
            source_idx = source_idx * dim + source_coords[source_axis];
        }
        return source_idx;
    }

    fn transposeHostDenseValueSwapAxes(
        self: *Session,
        value: Value,
        handle: *const NumericArray,
        axis1: usize,
        axis2: usize,
    ) KError!Value {
        const elem_count = numericArrayElementCount(handle);
        const out_shape = numericShapeSnapshotSwapAxes(numericShapeSnapshotFromHandle(handle), axis1, axis2);
        return switch (valueNumericMode(value) orelse return error.Type) {
            .float => blk: {
                var out = std.ArrayList(f64).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, elem_count);
                for (0..elem_count) |out_idx| {
                    try out.append(self.allocator, try numericFloatAt(value, transposeAxesSourceIndex(handle.shapeSlice(), axis1, axis2, out_idx)));
                }
                const transposed = try self.createManagedHostFloatArray(out.items);
                break :blk try applyNonVectorNumericShapeToValue(self, transposed, out_shape);
            },
            .int => blk: {
                var out = std.ArrayList(i64).empty;
                defer out.deinit(self.allocator);
                try out.ensureTotalCapacity(self.allocator, elem_count);
                for (0..elem_count) |out_idx| {
                    try out.append(self.allocator, try numericIntAt(value, transposeAxesSourceIndex(handle.shapeSlice(), axis1, axis2, out_idx)));
                }
                const transposed = try self.createManagedHostIntArray(out.items);
                break :blk try applyNonVectorNumericShapeToValue(self, transposed, out_shape);
            },
        };
    }

    fn transposeDenseNumericValueSwapAxes(
        self: *Session,
        value: Value,
        handle: *const NumericArray,
        axis1: usize,
        axis2: usize,
    ) KError!Value {
        if (handle.rank < 2 or axis1 >= handle.rank or axis2 >= handle.rank or axis1 == axis2) return error.Type;
        const elem_count = numericArrayElementCount(handle);
        if (comptime runtime_has_mlx) {
            if (planTransposeBackend(self, value, elem_count) == .mlx) {
                noteTransposeMaterializationDecision(self, value, elem_count, .mlx);
                return try self.transposeBackendSwapAxesValue(value, axis1, axis2);
            }
        }
        noteTransposeMaterializationDecision(self, value, elem_count, .host);
        return try self.transposeHostDenseValueSwapAxes(value, handle, axis1, axis2);
    }

    fn transposeHostStringList(self: *Session, list: *const HostStringList) KError!Value {
        if (list.len == 0) return try self.createManagedHostBoxedArray(&.{});
        var frame_len: ?usize = null;
        for (0..list.len) |idx| {
            const row = try hostStringListItemBytes(list, idx);
            if (row.len == 1) continue;
            if (frame_len) |cols| {
                if (row.len != cols) return error.Type;
            } else {
                frame_len = row.len;
            }
        }
        const cols = frame_len orelse return error.Type;

        if (cols == 0) {
            const prototype = try self.createOwnedHostStringSpaces(.managed, list.len);
            defer self.releaseValue(prototype);
            return try self.createManagedHostBoxedArrayWithPrototype(&.{}, prototype);
        }

        const payload_len = std.math.mul(usize, cols, list.len) catch return error.Unsupported;
        const payload = try self.allocator.alloc(u8, payload_len);
        defer self.allocator.free(payload);
        const rows = try self.allocator.alloc([]const u8, cols);
        defer self.allocator.free(rows);

        for (0..cols) |col_idx| {
            const start = col_idx * list.len;
            for (0..list.len) |row_idx| {
                const row = try hostStringListItemBytes(list, row_idx);
                payload[start + row_idx] = if (row.len == 1) row[0] else row[col_idx];
            }
            rows[col_idx] = payload[start .. start + list.len];
        }
        return try self.createManagedHostStringRowsFromSlices(rows);
    }

    fn boxedTransposeRowLen(value: Value) ?usize {
        if (stringSourceInfo(value)) |source| {
            if (!source.is_vector) return null;
            return source.bytes().len;
        }
        return derivedSequenceLen(value);
    }

    fn boxedTransposeCellValue(self: *Session, row: Value, col: usize) KError!Value {
        if (stringSourceInfo(row)) |source| {
            if (!source.is_vector) return try self.retainEscapedValue(row);
            return try self.stringIndexScalarValue(source, @intCast(col));
        }
        if (derivedSequenceLen(row) != null) return try self.derivedSequenceItemValue(row, col);
        return try self.retainEscapedValue(row);
    }

    fn transposeHostBoxedColumnValue(self: *Session, items: []const Value) KError!Value {
        var all_unit_strings = true;
        for (items) |item| {
            const bytes = stringBytes(item) orelse {
                all_unit_strings = false;
                break;
            };
            if (bytes.len != 1) {
                all_unit_strings = false;
                break;
            }
        }

        if (all_unit_strings) {
            const out = try self.allocator.alloc(u8, items.len);
            defer self.allocator.free(out);
            for (items, 0..) |item, idx| out[idx] = stringBytes(item).?[0];
            const text = try self.managedHostString(out);
            if (items.len == 1) {
                defer self.releaseValue(text);
                return try self.createManagedHostBoxedArray(&.{text});
            }
            return text;
        }

        return try self.makeArrayFromValues(items);
    }

    fn isBoxedTextVector(value: Value) bool {
        if (value.tag() != .array or value.arrayKind() != .host_boxed_array) return false;
        const array = value.asHostBoxedArray();
        return array.len() == 1 and stringBytes(array.items[0]) != null;
    }

    fn transposeHostBoxedArray(self: *Session, array: *const HostBoxedArray) KError!Value {
        const rows = array.len();
        if (rows == 0) return error.Type;
        var frame_len: ?usize = null;
        for (array.items[0..rows]) |row| {
            const row_len = boxedTransposeRowLen(row) orelse continue;
            if (frame_len) |cols| {
                if (row_len != cols) return error.Type;
            } else {
                frame_len = row_len;
            }
        }
        const cols = frame_len orelse return error.Type;
        if (cols == 0) return error.Type;

        const columns = try self.allocator.alloc(Value, cols);
        defer self.allocator.free(columns);
        var initialized_columns: usize = 0;
        defer {
            for (columns[0..initialized_columns]) |value| self.releaseValue(value);
        }

        for (0..cols) |col| {
            const items = try self.allocator.alloc(Value, rows);
            defer self.allocator.free(items);
            var initialized_items: usize = 0;
            defer {
                for (items[0..initialized_items]) |value| self.releaseValue(value);
            }

            for (array.items) |row| {
                items[initialized_items] = try self.boxedTransposeCellValue(row, col);
                initialized_items += 1;
            }

            columns[initialized_columns] = try self.transposeHostBoxedColumnValue(items);
            initialized_columns += 1;
        }

        if (rows > 1 and columns.len == 1 and isBoxedTextVector(columns[0])) {
            return try self.retainEscapedValue(columns[0]);
        }
        return try self.createManagedHostBoxedArray(columns);
    }

    fn transposeValue(self: *Session, value: Value) KError!Value {
        if (valueNumericHandle(value)) |handle| {
            if (handle.rank > 2 and valueNumericMode(value) != null) {
                return try self.transposeDenseNumericValueSwapAxes(value, handle, 0, 1);
            }
        }
        if (valueNumericMatrixView(value)) |matrix| {
            const elem_count = matrix.shape.rows * matrix.shape.cols;
            if (planTransposeBackend(self, value, elem_count) == .mlx) {
                return try self.transposeBackendMatrixValue(value);
            }
            if (try self.transposeHostDenseMatrixValue(value, matrix.shape)) |result| return result;

            const out_shape = numericShapeSnapshotMatrix(matrix.shape.cols, matrix.shape.rows);
            switch (matrix.mode) {
                .float => {
                    var out = std.ArrayList(f64).empty;
                    defer out.deinit(self.allocator);
                    try out.ensureTotalCapacity(self.allocator, elem_count);
                    for (0..matrix.shape.cols) |col_idx| {
                        for (0..matrix.shape.rows) |row_idx| {
                            try out.append(self.allocator, try numericFloatAt(value, row_idx * matrix.shape.cols + col_idx));
                        }
                    }
                    const transposed = try self.createManagedHostFloatArray(out.items);
                    return try applyNonVectorNumericShapeToValue(self, transposed, out_shape);
                },
                .int => {
                    var out = std.ArrayList(i64).empty;
                    defer out.deinit(self.allocator);
                    try out.ensureTotalCapacity(self.allocator, elem_count);
                    for (0..matrix.shape.cols) |col_idx| {
                        for (0..matrix.shape.rows) |row_idx| {
                            try out.append(self.allocator, try numericIntAt(value, row_idx * matrix.shape.cols + col_idx));
                        }
                    }
                    const transposed = try self.createManagedHostIntArray(out.items);
                    return try applyNonVectorNumericShapeToValue(self, transposed, out_shape);
                },
            }
        }
        if (value.tag() == .array and value.arrayKind() == .host_string_list) {
            return try self.transposeHostStringList(value.asHostStringList());
        }
        if (value.tag() == .array and value.arrayKind() == .host_boxed_array) {
            return try self.transposeHostBoxedArray(value.asHostBoxedArray());
        }
        return error.Type;
    }

    fn minimumValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(.minimum, left, right)) |result| return result;
        if (try self.textByteNumericDyadValue(.minimum, left, right)) |result| return result;
        if (try self.promoteRenderableNumericDyadOperands(left, right)) |operands| {
            return try self.minimumValues(operands.left, operands.right);
        }
        if (try self.tryApplyDictAtomicDyadValue(.minimum, left, right)) |result| return result;
        if (try self.tryApplyRightCallableDyadCompositionValue(.minimum, left, right)) |result| return result;
        if (left.tag() == .bool and right.tag() == .bool) return Value.fromBool(left.asBool() and right.asBool());
        if (try self.tryScalarIntBoolDyad(.minimum, left, right)) |result| return result;
        if (valueNumericMode(left) != null and valueNumericMode(right) != null and (left.tag() == .array or right.tag() == .array)) {
            return try self.applyNumericDyad(.minimum, left, right);
        }
        if (shouldUseGenericArrayDyad(left, right)) return try self.applyGenericArrayDyad(.minimum, left, right);
        if (left.tag() == .float or left.tag() == .float32 or right.tag() == .float or right.tag() == .float32) {
            const lhs = scalarNumericFloatValue(left) orelse return error.Type;
            const rhs = scalarNumericFloatValue(right) orelse return error.Type;
            return switch (scalarNumericResultStorageKind(left, right)) {
                .float32 => try self.float32Value(@floatCast(@min(lhs, rhs))),
                .float64 => try self.floatValue(@min(lhs, rhs)),
            };
        }
        const lhs = scalarIntLikeValue(left) orelse return error.Type;
        const rhs = scalarIntLikeValue(right) orelse return error.Type;
        return try self.intValue(@min(lhs, rhs));
    }

    fn maximumValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(.maximum, left, right)) |result| return result;
        if (try self.textByteNumericDyadValue(.maximum, left, right)) |result| return result;
        if (try self.promoteRenderableNumericDyadOperands(left, right)) |operands| {
            return try self.maximumValues(operands.left, operands.right);
        }
        if (try self.tryApplyDictAtomicDyadValue(.maximum, left, right)) |result| return result;
        if (try self.tryApplyRightCallableDyadCompositionValue(.maximum, left, right)) |result| return result;
        if (left.tag() == .bool and right.tag() == .bool) return Value.fromBool(left.asBool() or right.asBool());
        if (try self.tryScalarIntBoolDyad(.maximum, left, right)) |result| return result;
        if (valueNumericMode(left) != null and valueNumericMode(right) != null and (left.tag() == .array or right.tag() == .array)) {
            return try self.applyNumericDyad(.maximum, left, right);
        }
        if (shouldUseGenericArrayDyad(left, right)) return try self.applyGenericArrayDyad(.maximum, left, right);
        if (left.tag() == .float or left.tag() == .float32 or right.tag() == .float or right.tag() == .float32) {
            const lhs = scalarNumericFloatValue(left) orelse return error.Type;
            const rhs = scalarNumericFloatValue(right) orelse return error.Type;
            return switch (scalarNumericResultStorageKind(left, right)) {
                .float32 => try self.float32Value(@floatCast(@max(lhs, rhs))),
                .float64 => try self.floatValue(@max(lhs, rhs)),
            };
        }
        const lhs = scalarIntLikeValue(left) orelse return error.Type;
        const rhs = scalarIntLikeValue(right) orelse return error.Type;
        return try self.intValue(@max(lhs, rhs));
    }

    fn lessValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(.less, left, right)) |result| return result;
        if (try self.promoteRenderableNumericDyadOperands(left, right)) |operands| {
            return try self.lessValues(operands.left, operands.right);
        }
        if (try self.compareStringByteValues(.less, left, right)) |result| return result;
        if (try self.tryApplyDictAtomicDyadValue(.less, left, right)) |result| return result;
        if (try self.tryApplyRightCallableDyadCompositionValue(.less, left, right)) |result| return result;
        if (try self.tryScalarIntBoolDyad(.less, left, right)) |result| return result;
        if (shouldUseGenericArrayDyad(left, right)) return try self.applyGenericArrayDyad(.less, left, right);
        if (valueNumericMode(left) != null and valueNumericMode(right) != null and (left.tag() == .array or right.tag() == .array)) {
            return try self.compareNumericArrayValues(.less, left, right);
        }
        return try self.compareScalars(.less, left, right);
    }

    fn moreValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(.more, left, right)) |result| return result;
        if (try self.promoteRenderableNumericDyadOperands(left, right)) |operands| {
            return try self.moreValues(operands.left, operands.right);
        }
        if (try self.compareStringByteValues(.more, left, right)) |result| return result;
        if (try self.tryApplyDictAtomicDyadValue(.more, left, right)) |result| return result;
        if (try self.tryApplyRightCallableDyadCompositionValue(.more, left, right)) |result| return result;
        if (try self.tryScalarIntBoolDyad(.more, left, right)) |result| return result;
        if (shouldUseGenericArrayDyad(left, right)) return try self.applyGenericArrayDyad(.more, left, right);
        if (valueNumericMode(left) != null and valueNumericMode(right) != null and (left.tag() == .array or right.tag() == .array)) {
            return try self.compareNumericArrayValues(.more, left, right);
        }
        return try self.compareScalars(.more, left, right);
    }

    fn stringByteDyadLen(left_len: usize, right_len: usize) KError!usize {
        if (left_len == right_len) return left_len;
        if (left_len == 1) return right_len;
        if (right_len == 1) return left_len;
        return error.Type;
    }

    fn equalStringByteValues(self: *Session, left: Value, right: Value) KError!?Value {
        const left_bytes = stringBytes(left) orelse return null;
        const right_bytes = stringBytes(right) orelse return null;
        if (left_bytes.len == 1 and right_bytes.len == 1) {
            return Value.fromBool(left_bytes[0] == right_bytes[0]);
        }

        const len = try stringByteDyadLen(left_bytes.len, right_bytes.len);
        var out = try self.allocHostBitArrayUninitialized(.managed, len);
        const metadata = fillStringByteEqWords(&out, left_bytes, right_bytes);
        return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
    }

    fn compareStringByteValues(self: *Session, op: BuiltinId, left: Value, right: Value) KError!?Value {
        const left_bytes = stringBytes(left) orelse return null;
        const right_bytes = stringBytes(right) orelse return null;
        if (left_bytes.len == 1 and right_bytes.len == 1) {
            return Value.fromBool(switch (op) {
                .less => left_bytes[0] < right_bytes[0],
                .more => left_bytes[0] > right_bytes[0],
                else => return error.Internal,
            });
        }

        const len = try stringByteDyadLen(left_bytes.len, right_bytes.len);
        const out = try self.allocHostBitArrayUninitialized(.managed, len);
        var stats = BitSequenceStats{};
        for (0..len) |idx| {
            const lhs = left_bytes[if (left_bytes.len == 1) 0 else idx];
            const rhs = right_bytes[if (right_bytes.len == 1) 0 else idx];
            const bit = switch (op) {
                .less => lhs < rhs,
                .more => lhs > rhs,
                else => return error.Internal,
            };
            bitSet(out.words, idx, bit);
            stats.note(bit);
        }
        const metadata = stats.metadata();
        return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
    }

    fn textByteNumericDyadValue(self: *Session, op: BuiltinId, left: Value, right: Value) KError!?Value {
        const left_bytes = stringBytes(left) orelse return null;
        const right_bytes = stringBytes(right) orelse return null;
        switch (op) {
            .add, .sub, .mul, .div, .minimum, .maximum => {},
            else => return null,
        }

        const len = try stringByteDyadLen(left_bytes.len, right_bytes.len);
        if (op == .div) {
            if (len == 1) {
                const lhs: f64 = @floatFromInt(left_bytes[if (left_bytes.len == 1) 0 else 0]);
                const rhs: f64 = @floatFromInt(right_bytes[if (right_bytes.len == 1) 0 else 0]);
                return try self.floatValue(lhs / rhs);
            }
            const out = try self.allocator.alloc(f64, len);
            defer self.allocator.free(out);
            for (out, 0..) |*item, idx| {
                const lhs: f64 = @floatFromInt(left_bytes[if (left_bytes.len == 1) 0 else idx]);
                const rhs: f64 = @floatFromInt(right_bytes[if (right_bytes.len == 1) 0 else idx]);
                item.* = lhs / rhs;
            }
            return try self.createManagedHostFloatArray(out);
        }

        if (len == 1) {
            const lhs: i64 = left_bytes[if (left_bytes.len == 1) 0 else 0];
            const rhs: i64 = right_bytes[if (right_bytes.len == 1) 0 else 0];
            return try self.intValue(switch (op) {
                .add => try checkedIntOp(.add, lhs, rhs),
                .sub => try checkedIntOp(.sub, lhs, rhs),
                .mul => try checkedIntOp(.mul, lhs, rhs),
                .minimum => @min(lhs, rhs),
                .maximum => @max(lhs, rhs),
                else => unreachable,
            });
        }

        const out = try self.allocator.alloc(i64, len);
        defer self.allocator.free(out);
        for (out, 0..) |*item, idx| {
            const lhs: i64 = left_bytes[if (left_bytes.len == 1) 0 else idx];
            const rhs: i64 = right_bytes[if (right_bytes.len == 1) 0 else idx];
            item.* = switch (op) {
                .add => try checkedIntOp(.add, lhs, rhs),
                .sub => try checkedIntOp(.sub, lhs, rhs),
                .mul => try checkedIntOp(.mul, lhs, rhs),
                .minimum => @min(lhs, rhs),
                .maximum => @max(lhs, rhs),
                else => unreachable,
            };
        }
        return try self.createManagedHostIntArray(out);
    }

    fn equalArrayValues(self: *Session, left: Value, right: Value) KError!Value {
        if (valueNumericMode(left) != null and valueNumericMode(right) != null) {
            if (planCompareMaskBackend(self, .equal, left, right) == .mlx) return try self.applyBackendArrayDyad(.equal, left, right);
            const shape = try nonVectorNumericShapeForDyad(left, right);
            if (try self.tryFastHostBitCompare(.equal, left, right, shape)) |result| return result;
            if (try self.tryFastHostRangeCompare(.equal, left, right, shape)) |result| return result;
            if (try self.tryFastHostDenseCompare(.equal, left, right, shape)) |result| return result;
            const len = try arrayResultLen(left, right);
            const rowwise = rowwiseMatrixVectorDyad(left, right);
            const out = try self.allocHostBitArray(.managed, len);
            var stats = BitSequenceStats{};
            const integer_compare = valueNumericMode(left) == .int and valueNumericMode(right) == .int;
            for (0..len) |idx| {
                const bit = if (integer_compare) blk: {
                    const lhs = if (left.tag() == .array)
                        try numericIntAt(left, if (rowwise) |info| info.operandIndex(true, idx) else idx)
                    else
                        scalarIntLikeValue(left).?;
                    const rhs = if (right.tag() == .array)
                        try numericIntAt(right, if (rowwise) |info| info.operandIndex(false, idx) else idx)
                    else
                        scalarIntLikeValue(right).?;
                    break :blk lhs == rhs;
                } else blk: {
                    const lhs = if (left.tag() == .array)
                        try numericFloatAt(left, if (rowwise) |info| info.operandIndex(true, idx) else idx)
                    else
                        scalarNumericFloatValue(left).?;
                    const rhs = if (right.tag() == .array)
                        try numericFloatAt(right, if (rowwise) |info| info.operandIndex(false, idx) else idx)
                    else
                        scalarNumericFloatValue(right).?;
                    break :blk lhs == rhs;
                };
                bitSet(out.words, idx, bit);
                stats.note(bit);
            }
            const metadata = stats.metadata();
            const result = try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
            return try applyNonVectorNumericShapeToValue(self, result, shape);
        }
        const left_array = if (left.tag() == .array) try numericHostArrayValue(self, left) else null;
        const right_array = if (right.tag() == .array) try numericHostArrayValue(self, right) else null;
        const len = if (left_array != null and right_array != null) blk: {
            if (left_array.?.len() != right_array.?.len()) return error.Type;
            break :blk left_array.?.len();
        } else if (left_array != null) left_array.?.len() else right_array.?.len();

        const out = try self.allocHostBitArray(.managed, len);
        var stats = BitSequenceStats{};
        for (0..len) |idx| {
            const lhs = if (left_array) |array| try self.hostDenseIndexScalar(left, array, @intCast(idx)) else left;
            const rhs = if (right_array) |array| try self.hostDenseIndexScalar(right, array, @intCast(idx)) else right;
            defer if (left_array != null) self.releaseValue(lhs);
            defer if (right_array != null) self.releaseValue(rhs);
            const eq = try self.equalValues(lhs, rhs);
            defer if (eq.tag() != .bool) self.releaseValue(eq);
            bitSet(out.words, idx, eq.asBool());
            stats.note(eq.asBool());
        }
        const metadata = stats.metadata();
        return try self.finishManagedHostBitAlloc(out, metadata.flags, metadata.range);
    }

    fn addValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(.add, left, right)) |result| return result;
        if (try self.textByteNumericDyadValue(.add, left, right)) |result| return result;
        if (try self.promoteRenderableNumericDyadOperands(left, right)) |operands| {
            return try self.addValues(operands.left, operands.right);
        }
        if (try self.tryApplyDictAtomicDyadValue(.add, left, right)) |result| return result;
        if (try self.tryApplyRightCallableDyadCompositionValue(.add, left, right)) |result| return result;
        if (try self.tryScalarIntBoolDyad(.add, left, right)) |result| return result;
        if (try self.tryAffineRangeAddValues(left, right)) |result| return result;
        if (shouldUseGenericArrayDyad(left, right)) return try self.applyGenericArrayDyad(.add, left, right);
        if (hasArrayOperand(left, right) and canApplyNumericDyad(left, right)) return try self.applyNumericDyad(.add, left, right);
        return switch (left.tag()) {
            .int => switch (right.tag()) {
                .float32 => try self.float32Value(@as(f32, @floatFromInt(left.asInt())) + right.asFloat32()),
                .float => try self.floatValue(@as(f64, @floatFromInt(left.asInt())) + right.asFloat()),
                else => error.Type,
            },
            .bool => switch (right.tag()) {
                .float32 => try self.float32Value(@as(f32, @floatFromInt(@intFromBool(left.asBool()))) + right.asFloat32()),
                .float => try self.floatValue(@as(f64, @floatFromInt(@intFromBool(left.asBool()))) + right.asFloat()),
                else => error.Type,
            },
            .float32 => switch (right.tag()) {
                .int, .bool => try self.float32Value(left.asFloat32() + @as(f32, @floatFromInt(scalarIntLikeValue(right).?))),
                .float32 => try self.float32Value(left.asFloat32() + right.asFloat32()),
                .float => try self.floatValue(left.asFloat() + right.asFloat()),
                else => error.Type,
            },
            .float => switch (right.tag()) {
                .int, .bool => try self.floatValue(left.asFloat() + @as(f64, @floatFromInt(scalarIntLikeValue(right).?))),
                .float32 => try self.floatValue(left.asFloat() + right.asFloat()),
                .float => try self.floatValue(left.asFloat() + right.asFloat()),
                else => error.Type,
            },
            else => error.Type,
        };
    }

    fn subValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(.sub, left, right)) |result| return result;
        if (try self.textByteNumericDyadValue(.sub, left, right)) |result| return result;
        if (try self.promoteRenderableNumericDyadOperands(left, right)) |operands| {
            return try self.subValues(operands.left, operands.right);
        }
        if (try self.tryApplyDictAtomicDyadValue(.sub, left, right)) |result| return result;
        if (try self.tryApplyRightCallableDyadCompositionValue(.sub, left, right)) |result| return result;
        if (try self.tryScalarIntBoolDyad(.sub, left, right)) |result| return result;
        if (shouldUseGenericArrayDyad(left, right)) return try self.applyGenericArrayDyad(.sub, left, right);
        if (hasArrayOperand(left, right) and canApplyNumericDyad(left, right)) return try self.applyNumericDyad(.sub, left, right);
        return switch (left.tag()) {
            .int => switch (right.tag()) {
                .float32 => try self.float32Value(@as(f32, @floatFromInt(left.asInt())) - right.asFloat32()),
                .float => try self.floatValue(@as(f64, @floatFromInt(left.asInt())) - right.asFloat()),
                else => error.Type,
            },
            .bool => switch (right.tag()) {
                .float32 => try self.float32Value(@as(f32, @floatFromInt(@intFromBool(left.asBool()))) - right.asFloat32()),
                .float => try self.floatValue(@as(f64, @floatFromInt(@intFromBool(left.asBool()))) - right.asFloat()),
                else => error.Type,
            },
            .float32 => switch (right.tag()) {
                .int, .bool => try self.float32Value(left.asFloat32() - @as(f32, @floatFromInt(scalarIntLikeValue(right).?))),
                .float32 => try self.float32Value(left.asFloat32() - right.asFloat32()),
                .float => try self.floatValue(left.asFloat() - right.asFloat()),
                else => error.Type,
            },
            .float => switch (right.tag()) {
                .int, .bool => try self.floatValue(left.asFloat() - @as(f64, @floatFromInt(scalarIntLikeValue(right).?))),
                .float32 => try self.floatValue(left.asFloat() - right.asFloat()),
                .float => try self.floatValue(left.asFloat() - right.asFloat()),
                else => error.Type,
            },
            else => error.Type,
        };
    }

    fn mulValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(.mul, left, right)) |result| return result;
        if (try self.textByteNumericDyadValue(.mul, left, right)) |result| return result;
        if (try self.promoteRenderableNumericDyadOperands(left, right)) |operands| {
            return try self.mulValues(operands.left, operands.right);
        }
        if (try self.tryApplyDictAtomicDyadValue(.mul, left, right)) |result| return result;
        if (try self.tryApplyRightCallableDyadCompositionValue(.mul, left, right)) |result| return result;
        if (try self.tryScalarIntBoolDyad(.mul, left, right)) |result| return result;
        if (shouldUseGenericArrayDyad(left, right)) return try self.applyGenericArrayDyad(.mul, left, right);
        if (hasArrayOperand(left, right) and canApplyNumericDyad(left, right)) return try self.applyNumericDyad(.mul, left, right);
        return switch (left.tag()) {
            .int => switch (right.tag()) {
                .float32 => try self.float32Value(@as(f32, @floatFromInt(left.asInt())) * right.asFloat32()),
                .float => try self.floatValue(@as(f64, @floatFromInt(left.asInt())) * right.asFloat()),
                else => error.Type,
            },
            .bool => switch (right.tag()) {
                .float32 => try self.float32Value(@as(f32, @floatFromInt(@intFromBool(left.asBool()))) * right.asFloat32()),
                .float => try self.floatValue(@as(f64, @floatFromInt(@intFromBool(left.asBool()))) * right.asFloat()),
                else => error.Type,
            },
            .float32 => switch (right.tag()) {
                .int, .bool => try self.float32Value(left.asFloat32() * @as(f32, @floatFromInt(scalarIntLikeValue(right).?))),
                .float32 => try self.float32Value(left.asFloat32() * right.asFloat32()),
                .float => try self.floatValue(left.asFloat() * right.asFloat()),
                else => error.Type,
            },
            .float => switch (right.tag()) {
                .int, .bool => try self.floatValue(left.asFloat() * @as(f64, @floatFromInt(scalarIntLikeValue(right).?))),
                .float32 => try self.floatValue(left.asFloat() * right.asFloat()),
                .float => try self.floatValue(left.asFloat() * right.asFloat()),
                else => error.Type,
            },
            else => error.Type,
        };
    }

    fn divValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(.div, left, right)) |result| return result;
        if (try self.textByteNumericDyadValue(.div, left, right)) |result| return result;
        if (try self.promoteRenderableNumericDyadOperands(left, right)) |operands| {
            return try self.divValues(operands.left, operands.right);
        }
        if (try self.tryApplyDictAtomicDyadValue(.div, left, right)) |result| return result;
        if (try self.tryApplyRightCallableDyadCompositionValue(.div, left, right)) |result| return result;
        if (try self.tryScalarIntBoolDyad(.div, left, right)) |result| return result;
        if (shouldUseGenericArrayDyad(left, right)) return try self.applyGenericArrayDyad(.div, left, right);
        if (hasArrayOperand(left, right) and canApplyNumericDyad(left, right)) return try self.applyNumericDyad(.div, left, right);
        const left_float = switch (left.tag()) {
            .int => @as(f64, @floatFromInt(left.asInt())),
            .bool => @as(f64, @floatFromInt(@intFromBool(left.asBool()))),
            .float32 => @as(f64, @floatCast(left.asFloat32())),
            .float => left.asFloat(),
            else => return error.Type,
        };
        const right_float = switch (right.tag()) {
            .int => @as(f64, @floatFromInt(right.asInt())),
            .bool => @as(f64, @floatFromInt(@intFromBool(right.asBool()))),
            .float32 => @as(f64, @floatCast(right.asFloat32())),
            .float => right.asFloat(),
            else => return error.Type,
        };
        return switch (scalarNumericResultStorageKind(left, right)) {
            .float32 => try self.float32Value(@floatCast(left_float / right_float)),
            .float64 => try self.floatValue(left_float / right_float),
        };
    }

    fn powValues(self: *Session, left: Value, right: Value) KError!Value {
        if (try self.tryFastInlineScalarDyad(.pow, left, right)) |result| return result;
        if (try self.promoteRenderableNumericDyadOperands(left, right)) |operands| {
            return try self.powValues(operands.left, operands.right);
        }
        if (hasArrayOperand(left, right) and canApplyNumericDyad(left, right)) return try self.applyNumericDyad(.pow, left, right);
        if (shouldUseGenericArrayDyad(left, right)) return try self.applyGenericArrayDyad(.pow, left, right);
        if (scalarIntLikeValue(left)) |left_int| {
            if (scalarIntLikeValue(right)) |right_int| {
                return try self.intValue(try intPowLikeMlx(left_int, right_int));
            }
        }
        const left_float = scalarNumericFloatValue(left) orelse return error.Type;
        const right_float = scalarNumericFloatValue(right) orelse return error.Type;
        return switch (scalarNumericResultStorageKind(left, right)) {
            .float32 => try self.float32Value(@floatCast(std.math.pow(f64, left_float, right_float))),
            .float64 => try self.floatValue(std.math.pow(f64, left_float, right_float)),
        };
    }

    const MatmulShape = struct {
        left_rank: u8,
        right_rank: u8,
        result_rank: u8,
        left_rows: usize,
        left_cols: usize,
        right_rows: usize,
        right_cols: usize,
        result_rows: usize,
        result_cols: usize,
        result_len: usize,
        result_mode: HostDenseElem,
    };

    fn matmulShapeForValues(left: Value, right: Value) KError!?MatmulShape {
        const left_mode = valueNumericMode(left) orelse return null;
        const right_mode = valueNumericMode(right) orelse return null;

        const left_matrix = valueNumericMatrixShape(left);
        const right_matrix = valueNumericMatrixShape(right);
        const left_vector_len = numericVectorLen(left);
        const right_vector_len = numericVectorLen(right);

        if (left_matrix == null and left_vector_len == null) return null;
        if (right_matrix == null and right_vector_len == null) return null;

        const left_rank: u8 = if (left_matrix != null) 2 else 1;
        const right_rank: u8 = if (right_matrix != null) 2 else 1;
        const left_rows = if (left_matrix) |shape| shape.rows else 1;
        const left_cols = if (left_matrix) |shape| shape.cols else left_vector_len.?;
        const right_rows = if (right_matrix) |shape| shape.rows else right_vector_len.?;
        const right_cols = if (right_matrix) |shape| shape.cols else 1;
        if (left_cols != right_rows) return error.Type;

        const result_rank: u8 = if (left_rank == 1 and right_rank == 1) 0 else if (left_rank == 2 and right_rank == 2) 2 else 1;
        const result_rows = if (left_rank == 2) left_rows else 1;
        const result_cols = if (right_rank == 2) right_cols else 1;
        return .{
            .left_rank = left_rank,
            .right_rank = right_rank,
            .result_rank = result_rank,
            .left_rows = left_rows,
            .left_cols = left_cols,
            .right_rows = right_rows,
            .right_cols = right_cols,
            .result_rows = result_rows,
            .result_cols = result_cols,
            .result_len = result_rows * result_cols,
            .result_mode = if (left_mode == .float or right_mode == .float) .float else .int,
        };
    }

    fn hostDenseViewFloatItem(view: HostDenseView, idx: usize) KError!f64 {
        return switch (view) {
            .scalar_int => |value| @floatFromInt(value),
            .scalar_float => |value| value,
            .int_array => |items| @floatFromInt(try hostIntDenseViewItem(items, idx)),
            .float_array => |items| try hostFloatDenseViewItem(items, idx),
        };
    }

    fn hostDenseViewIntItem(view: HostDenseView, idx: usize) KError!i64 {
        return switch (view) {
            .scalar_int => |value| value,
            .int_array => |items| try hostIntDenseViewItem(items, idx),
            else => error.Type,
        };
    }

    fn finishHostMatmulFloatResult(self: *Session, shape: MatmulShape, out: HostFloatResult) KError!Value {
        if (shape.result_rank == 0) return try self.floatValue(out.items[0]);
        const value = out.value();
        hostDenseSetFlags(try mutableNumericHostArrayValue(self, value), hostMatmulFloatResultFlags(out.items.len));
        if (shape.result_rank == 2) {
            defer self.releaseValue(value);
            return try newReshapeViewValue(self, value, numericShapeSnapshotMatrix(shape.result_rows, shape.result_cols));
        }
        return value;
    }

    fn finishHostMatmulFloat32Result(self: *Session, shape: MatmulShape, out: HostFloat32Result) KError!Value {
        if (shape.result_rank == 0) return try self.float32Value(out.items[0]);
        const value = out.value();
        hostDenseSetFlags(try mutableNumericHostArrayValue(self, value), hostMatmulFloatResultFlags(out.items.len));
        if (shape.result_rank == 2) {
            defer self.releaseValue(value);
            return try newReshapeViewValue(self, value, numericShapeSnapshotMatrix(shape.result_rows, shape.result_cols));
        }
        return value;
    }

    fn hostMatmulFloatResultFlags(len: usize) u8 {
        // Matmul outputs have no useful ordering guarantee. Keep the dense
        // normalization flag but avoid an O(result) monotonicity scan after BLAS.
        return host_dense_flag_normalized |
            (if (len <= 1) host_dense_flag_asc | host_dense_flag_dsc else 0);
    }

    fn finishHostMatmulIntResult(self: *Session, shape: MatmulShape, items: []const i64) KError!Value {
        if (shape.result_rank == 0) return try self.intValue(items[0]);
        const value = try self.createManagedHostIntArray(items);
        if (shape.result_rank == 2) {
            defer self.releaseValue(value);
            return try newReshapeViewValue(self, value, numericShapeSnapshotMatrix(shape.result_rows, shape.result_cols));
        }
        return value;
    }

    fn transposeDenseFloatMatrixBlocked(out: []f64, input: []const f64, rows: usize, cols: usize) void {
        const tile: usize = 32;
        var row0: usize = 0;
        while (row0 < rows) : (row0 += tile) {
            const row_end = @min(row0 + tile, rows);
            var col0: usize = 0;
            while (col0 < cols) : (col0 += tile) {
                const col_end = @min(col0 + tile, cols);
                var row_idx = row0;
                while (row_idx < row_end) : (row_idx += 1) {
                    const input_row = input[row_idx * cols ..][0..cols];
                    var col_idx = col0;
                    while (col_idx < col_end) : (col_idx += 1) {
                        out[col_idx * rows + row_idx] = input_row[col_idx];
                    }
                }
            }
        }
    }

    fn transposeDenseFloat32MatrixBlocked(out: []f32, input: []const f32, rows: usize, cols: usize) void {
        const tile: usize = 32;
        var row0: usize = 0;
        while (row0 < rows) : (row0 += tile) {
            const row_end = @min(row0 + tile, rows);
            var col0: usize = 0;
            while (col0 < cols) : (col0 += tile) {
                const col_end = @min(col0 + tile, cols);
                var row_idx = row0;
                while (row_idx < row_end) : (row_idx += 1) {
                    const input_row = input[row_idx * cols ..][0..cols];
                    var col_idx = col0;
                    while (col_idx < col_end) : (col_idx += 1) {
                        out[col_idx * rows + row_idx] = input_row[col_idx];
                    }
                }
            }
        }
    }

    fn denseFloatDot(lhs: []const f64, rhs: []const f64) f64 {
        const lane_count = 4;
        const Vec = @Vector(lane_count, f64);
        var acc_vec: Vec = @splat(0.0);
        var idx: usize = 0;
        const vector_limit = lhs.len - (lhs.len % lane_count);
        while (idx < vector_limit) : (idx += lane_count) {
            const lhs_vec: Vec = lhs[idx..][0..lane_count].*;
            const rhs_vec: Vec = rhs[idx..][0..lane_count].*;
            acc_vec += lhs_vec * rhs_vec;
        }
        var acc = @reduce(.Add, acc_vec);
        while (idx < lhs.len) : (idx += 1) acc += lhs[idx] * rhs[idx];
        return acc;
    }

    fn denseFloat32Dot(lhs: []const f32, rhs: []const f32) f32 {
        const lane_count = 8;
        const Vec = @Vector(lane_count, f32);
        var acc_vec: Vec = @splat(0.0);
        var idx: usize = 0;
        const vector_limit = lhs.len - (lhs.len % lane_count);
        while (idx < vector_limit) : (idx += lane_count) {
            const lhs_vec: Vec = lhs[idx..][0..lane_count].*;
            const rhs_vec: Vec = rhs[idx..][0..lane_count].*;
            acc_vec += lhs_vec * rhs_vec;
        }
        var acc = @reduce(.Add, acc_vec);
        while (idx < lhs.len) : (idx += 1) acc += lhs[idx] * rhs[idx];
        return acc;
    }

    fn denseFloat32Float64Dot(lhs: []const f32, rhs: []const f64) f64 {
        const lane_count = 4;
        const VecF32 = @Vector(lane_count, f32);
        const VecF64 = @Vector(lane_count, f64);
        var acc_vec: VecF64 = @splat(0.0);
        var idx: usize = 0;
        const vector_limit = lhs.len - (lhs.len % lane_count);
        while (idx < vector_limit) : (idx += lane_count) {
            const lhs_vec32: VecF32 = lhs[idx..][0..lane_count].*;
            const lhs_vec64: VecF64 = @floatCast(lhs_vec32);
            const rhs_vec: VecF64 = rhs[idx..][0..lane_count].*;
            acc_vec += lhs_vec64 * rhs_vec;
        }
        var acc = @reduce(.Add, acc_vec);
        while (idx < lhs.len) : (idx += 1) acc += @as(f64, @floatCast(lhs[idx])) * rhs[idx];
        return acc;
    }

    fn denseFloat64Float32Dot(lhs: []const f64, rhs: []const f32) f64 {
        const lane_count = 4;
        const VecF32 = @Vector(lane_count, f32);
        const VecF64 = @Vector(lane_count, f64);
        var acc_vec: VecF64 = @splat(0.0);
        var idx: usize = 0;
        const vector_limit = lhs.len - (lhs.len % lane_count);
        while (idx < vector_limit) : (idx += lane_count) {
            const lhs_vec: VecF64 = lhs[idx..][0..lane_count].*;
            const rhs_vec32: VecF32 = rhs[idx..][0..lane_count].*;
            const rhs_vec64: VecF64 = @floatCast(rhs_vec32);
            acc_vec += lhs_vec * rhs_vec64;
        }
        var acc = @reduce(.Add, acc_vec);
        while (idx < lhs.len) : (idx += 1) acc += lhs[idx] * @as(f64, @floatCast(rhs[idx]));
        return acc;
    }

    fn hostFloatDenseViewContiguousFloat32(view: HostFloatDenseView) ?[]const f32 {
        return hostFloatDenseViewDirectFloat32Slice(view);
    }

    fn hostFloatDenseViewContiguousFloat64(view: HostFloatDenseView) ?[]const f64 {
        return hostFloatDenseViewDirectFloat64Slice(view);
    }

    const HostBlasFloat32Operand = struct {
        items: []const f32,
        transpose: bool,
    };

    const HostBlasFloat64Operand = struct {
        items: []const f64,
        transpose: bool,
    };

    fn hostFloatDenseViewBlasFloat32(view: HostFloatDenseView) ?HostBlasFloat32Operand {
        switch (view) {
            .flat_slice => |slice| {
                const array = slice.source_host orelse return null;
                return switch (array.storage) {
                    .float32 => |items| blk: {
                        const logical_items = hostDenseLogicalItems(f32, array, items);
                        if (slice.start > logical_items.len or slice.len > logical_items.len - slice.start) return null;
                        break :blk .{ .items = logical_items[slice.start..][0..slice.len], .transpose = false };
                    },
                    else => null,
                };
            },
            .transpose => |transpose| {
                const array = transpose.source_host orelse return null;
                const total_len = std.math.mul(usize, transpose.source_rows, transpose.source_cols) catch return null;
                return switch (array.storage) {
                    .float32 => |items| blk: {
                        const logical_items = hostDenseLogicalItems(f32, array, items);
                        if (logical_items.len != total_len) return null;
                        break :blk .{ .items = logical_items, .transpose = true };
                    },
                    else => null,
                };
            },
            else => return null,
        }
    }

    fn hostFloatDenseViewBlasFloat64(view: HostFloatDenseView) ?HostBlasFloat64Operand {
        return switch (view) {
            .dense => |items| .{ .items = items, .transpose = false },
            .transpose => |transpose| blk: {
                const array = transpose.source_host orelse return null;
                const total_len = std.math.mul(usize, transpose.source_rows, transpose.source_cols) catch return null;
                break :blk switch (array.storage) {
                    .float64 => |items| inner: {
                        const logical_items = hostDenseLogicalItems(f64, array, items);
                        if (logical_items.len != total_len) return null;
                        break :inner .{ .items = logical_items, .transpose = true };
                    },
                    else => null,
                };
            },
            else => null,
        };
    }

    fn hostBlasMatmulShapeSupported(shape: MatmulShape) bool {
        if (comptime !enable_host_accelerate_blas) return false;
        if (shape.result_rank != 2) return false;
        if (shape.left_rows == 0 or shape.result_cols == 0 or shape.left_cols == 0) return false;
        if (shape.left_rows > host_accelerate_blas_max_dim) return false;
        if (shape.result_cols > host_accelerate_blas_max_dim) return false;
        if (shape.left_cols > host_accelerate_blas_max_dim) return false;
        return true;
    }

    fn hostBlasDotLenSupported(len: usize) bool {
        if (comptime !enable_host_accelerate_blas) return false;
        if (len < host_accelerate_dot_min_len) return false;
        return len <= host_accelerate_blas_max_dim;
    }

    fn tryHostBlasDotFloatDense(self: *Session, left_items: []const f64, right_items: []const f64, len: usize) KError!?Value {
        if (!hostBlasDotLenSupported(len)) return null;
        var out: f64 = 0.0;
        if (kiwi_host_blas_ddot(&out, left_items.ptr, right_items.ptr, len) == 0) return null;
        return try self.floatValue(out);
    }

    fn tryHostBlasDotFloat32Dense(self: *Session, left_items: []const f32, right_items: []const f32, len: usize) KError!?Value {
        if (!hostBlasDotLenSupported(len)) return null;
        var out: f32 = 0.0;
        if (kiwi_host_blas_sdot(&out, left_items.ptr, right_items.ptr, len) == 0) return null;
        return try self.float32Value(out);
    }

    fn tryHostBlasMatmulFloatOperand(self: *Session, left: HostBlasFloat64Operand, right: HostBlasFloat64Operand, shape: MatmulShape) KError!?Value {
        if (!hostBlasMatmulShapeSupported(shape)) return null;
        const out = try self.allocManagedHostFloatResult(shape.result_len);
        if (kiwi_host_blas_dgemm_rowmajor_ex(out.items.ptr, left.items.ptr, @intFromBool(left.transpose), right.items.ptr, @intFromBool(right.transpose), shape.left_rows, shape.result_cols, shape.left_cols) == 0) {
            return error.Unsupported;
        }
        return try self.finishHostMatmulFloatResult(shape, out);
    }

    fn tryHostBlasMatmulFloat32Operand(self: *Session, left: HostBlasFloat32Operand, right: HostBlasFloat32Operand, shape: MatmulShape) KError!?Value {
        if (!hostBlasMatmulShapeSupported(shape)) return null;
        const out = try self.allocManagedHostFloat32Result(shape.result_len);
        if (kiwi_host_blas_sgemm_rowmajor_ex(out.items.ptr, left.items.ptr, @intFromBool(left.transpose), right.items.ptr, @intFromBool(right.transpose), shape.left_rows, shape.result_cols, shape.left_cols) == 0) {
            return error.Unsupported;
        }
        return try self.finishHostMatmulFloat32Result(shape, out);
    }

    fn tryHostBlasMatmulFloatDense(self: *Session, left_items: []const f64, right_items: []const f64, shape: MatmulShape) KError!?Value {
        return try self.tryHostBlasMatmulFloatOperand(
            .{ .items = left_items, .transpose = false },
            .{ .items = right_items, .transpose = false },
            shape,
        );
    }

    fn tryHostBlasMatmulFloat32Dense(self: *Session, left_items: []const f32, right_items: []const f32, shape: MatmulShape) KError!?Value {
        return try self.tryHostBlasMatmulFloat32Operand(
            .{ .items = left_items, .transpose = false },
            .{ .items = right_items, .transpose = false },
            shape,
        );
    }

    fn applyHostMatmulFloatDense(self: *Session, left_items: []const f64, right_items: []const f64, shape: MatmulShape) KError!Value {
        if (shape.result_rank == 0) {
            if (try self.tryHostBlasDotFloatDense(left_items, right_items, shape.left_cols)) |value| return value;
            return try self.floatValue(denseFloatDot(left_items[0..shape.left_cols], right_items[0..shape.left_cols]));
        }
        if (try self.tryHostBlasMatmulFloatDense(left_items, right_items, shape)) |value| return value;

        const right_t = try self.allocator.alloc(f64, right_items.len);
        defer self.allocator.free(right_t);
        transposeDenseFloatMatrixBlocked(right_t, right_items, shape.right_rows, shape.right_cols);

        const out = try self.allocManagedHostFloatResult(shape.result_len);
        for (0..shape.result_rows) |row_idx| {
            const out_row = out.items[row_idx * shape.result_cols ..][0..shape.result_cols];
            const left_row = left_items[row_idx * shape.left_cols ..][0..shape.left_cols];
            for (0..shape.result_cols) |col_idx| {
                const right_col = right_t[col_idx * shape.left_cols ..][0..shape.left_cols];
                out_row[col_idx] = denseFloatDot(left_row, right_col);
            }
        }
        return try self.finishHostMatmulFloatResult(shape, out);
    }

    fn applyHostMatmulFloat32Dense(self: *Session, left_items: []const f32, right_items: []const f32, shape: MatmulShape) KError!Value {
        if (shape.result_rank == 0) {
            if (try self.tryHostBlasDotFloat32Dense(left_items, right_items, shape.left_cols)) |value| return value;
            return try self.float32Value(denseFloat32Dot(left_items[0..shape.left_cols], right_items[0..shape.left_cols]));
        }
        if (try self.tryHostBlasMatmulFloat32Dense(left_items, right_items, shape)) |value| return value;

        const right_t = try self.allocator.alloc(f32, right_items.len);
        defer self.allocator.free(right_t);
        transposeDenseFloat32MatrixBlocked(right_t, right_items, shape.right_rows, shape.right_cols);

        const out = try self.allocManagedHostFloat32Result(shape.result_len);
        for (0..shape.result_rows) |row_idx| {
            const out_row = out.items[row_idx * shape.result_cols ..][0..shape.result_cols];
            const left_row = left_items[row_idx * shape.left_cols ..][0..shape.left_cols];
            for (0..shape.result_cols) |col_idx| {
                const right_col = right_t[col_idx * shape.left_cols ..][0..shape.left_cols];
                out_row[col_idx] = denseFloat32Dot(left_row, right_col);
            }
        }
        return try self.finishHostMatmulFloat32Result(shape, out);
    }

    fn applyHostMatmulFloat32Float64Dense(self: *Session, left_items: []const f32, right_items: []const f64, shape: MatmulShape) KError!Value {
        if (shape.result_rank == 0) {
            return try self.floatValue(denseFloat32Float64Dot(left_items[0..shape.left_cols], right_items[0..shape.left_cols]));
        }

        const right_t = try self.allocator.alloc(f64, right_items.len);
        defer self.allocator.free(right_t);
        transposeDenseFloatMatrixBlocked(right_t, right_items, shape.right_rows, shape.right_cols);

        const out = try self.allocManagedHostFloatResult(shape.result_len);
        for (0..shape.result_rows) |row_idx| {
            const out_row = out.items[row_idx * shape.result_cols ..][0..shape.result_cols];
            const left_row = left_items[row_idx * shape.left_cols ..][0..shape.left_cols];
            for (0..shape.result_cols) |col_idx| {
                const right_col = right_t[col_idx * shape.left_cols ..][0..shape.left_cols];
                out_row[col_idx] = denseFloat32Float64Dot(left_row, right_col);
            }
        }
        return try self.finishHostMatmulFloatResult(shape, out);
    }

    fn applyHostMatmulFloat64Float32Dense(self: *Session, left_items: []const f64, right_items: []const f32, shape: MatmulShape) KError!Value {
        if (shape.result_rank == 0) {
            return try self.floatValue(denseFloat64Float32Dot(left_items[0..shape.left_cols], right_items[0..shape.left_cols]));
        }

        const right_t = try self.allocator.alloc(f32, right_items.len);
        defer self.allocator.free(right_t);
        transposeDenseFloat32MatrixBlocked(right_t, right_items, shape.right_rows, shape.right_cols);

        const out = try self.allocManagedHostFloatResult(shape.result_len);
        for (0..shape.result_rows) |row_idx| {
            const out_row = out.items[row_idx * shape.result_cols ..][0..shape.result_cols];
            const left_row = left_items[row_idx * shape.left_cols ..][0..shape.left_cols];
            for (0..shape.result_cols) |col_idx| {
                const right_col = right_t[col_idx * shape.left_cols ..][0..shape.left_cols];
                out_row[col_idx] = denseFloat64Float32Dot(left_row, right_col);
            }
        }
        return try self.finishHostMatmulFloatResult(shape, out);
    }

    fn applyHostMatmulGeneric(self: *Session, left: Value, right: Value, shape: MatmulShape) KError!Value {
        const left_view = try hostDenseView(self, left);
        const right_view = try hostDenseView(self, right);

        if (shape.result_mode == .float) {
            if (left_view == .float_array and right_view == .float_array) {
                const left_blas_f32 = hostFloatDenseViewBlasFloat32(left_view.float_array);
                const right_blas_f32 = hostFloatDenseViewBlasFloat32(right_view.float_array);
                const left_blas_f64 = hostFloatDenseViewBlasFloat64(left_view.float_array);
                const right_blas_f64 = hostFloatDenseViewBlasFloat64(right_view.float_array);

                if (left_blas_f32 != null and right_blas_f32 != null and (left_blas_f32.?.transpose or right_blas_f32.?.transpose)) {
                    if (try self.tryHostBlasMatmulFloat32Operand(left_blas_f32.?, right_blas_f32.?, shape)) |value| return value;
                }
                if (left_blas_f64 != null and right_blas_f64 != null and (left_blas_f64.?.transpose or right_blas_f64.?.transpose)) {
                    if (try self.tryHostBlasMatmulFloatOperand(left_blas_f64.?, right_blas_f64.?, shape)) |value| return value;
                }

                const left_f32 = hostFloatDenseViewContiguousFloat32(left_view.float_array);
                const right_f32 = hostFloatDenseViewContiguousFloat32(right_view.float_array);
                const left_f64 = hostFloatDenseViewContiguousFloat64(left_view.float_array);
                const right_f64 = hostFloatDenseViewContiguousFloat64(right_view.float_array);

                if (left_f32 != null and right_f32 != null) {
                    return try self.applyHostMatmulFloat32Dense(left_f32.?, right_f32.?, shape);
                }
                if (left_f64 != null and right_f64 != null) {
                    return try self.applyHostMatmulFloatDense(left_f64.?, right_f64.?, shape);
                }
                if (left_f32 != null and right_f64 != null) {
                    return try self.applyHostMatmulFloat32Float64Dense(left_f32.?, right_f64.?, shape);
                }
                if (left_f64 != null and right_f32 != null) {
                    return try self.applyHostMatmulFloat64Float32Dense(left_f64.?, right_f32.?, shape);
                }
            }

            if (shape.result_rank == 0) {
                var acc: f64 = 0.0;
                for (0..shape.left_cols) |inner_idx| {
                    acc += (try hostDenseViewFloatItem(left_view, inner_idx)) *
                        (try hostDenseViewFloatItem(right_view, inner_idx));
                }
                return try self.floatValue(acc);
            }

            const out = try self.allocManagedHostFloatResult(shape.result_len);
            @memset(out.items, 0.0);
            for (0..shape.result_rows) |row_idx| {
                const out_row = out.items[row_idx * shape.result_cols ..][0..shape.result_cols];
                for (0..shape.left_cols) |inner_idx| {
                    const left_value = try hostDenseViewFloatItem(left_view, row_idx * shape.left_cols + inner_idx);
                    const right_base = inner_idx * shape.right_cols;
                    for (0..shape.result_cols) |col_idx| {
                        out_row[col_idx] += left_value * (try hostDenseViewFloatItem(right_view, right_base + col_idx));
                    }
                }
            }
            return try self.finishHostMatmulFloatResult(shape, out);
        }

        var out_items = try self.allocator.alloc(i64, shape.result_len);
        defer self.allocator.free(out_items);

        if (shape.result_rank == 0) {
            var acc: i128 = 0;
            for (0..shape.left_cols) |inner_idx| {
                acc += @as(i128, try hostDenseViewIntItem(left_view, inner_idx)) *
                    @as(i128, try hostDenseViewIntItem(right_view, inner_idx));
            }
            out_items[0] = std.math.cast(i64, acc) orelse return error.Unsupported;
            return try self.finishHostMatmulIntResult(shape, out_items);
        }

        for (0..shape.result_rows) |row_idx| {
            for (0..shape.result_cols) |col_idx| {
                var acc: i128 = 0;
                for (0..shape.left_cols) |inner_idx| {
                    const left_value = @as(i128, try hostDenseViewIntItem(left_view, row_idx * shape.left_cols + inner_idx));
                    const right_value = @as(i128, try hostDenseViewIntItem(right_view, inner_idx * shape.right_cols + col_idx));
                    acc += left_value * right_value;
                }
                out_items[row_idx * shape.result_cols + col_idx] = std.math.cast(i64, acc) orelse return error.Unsupported;
            }
        }
        return try self.finishHostMatmulIntResult(shape, out_items);
    }

    fn promoteRenderableMatrixValue(self: *Session, value: Value) KError!?Value {
        if (valueNumericMatrixShape(value) != null) return value;
        _ = self;
        return null;
    }

    fn promoteTextNumericDyadOperand(self: *Session, value: Value, other: Value) KError!?Value {
        if (stringBytes(value) == null) return null;
        if (valueNumericMode(other) == null) return null;
        return try self.castValueToInt(value);
    }

    const NumericDyadOperands = struct {
        left: Value,
        right: Value,
    };

    fn promoteRenderableNumericDyadOperands(self: *Session, left: Value, right: Value) KError!?NumericDyadOperands {
        var promoted_left = left;
        var promoted_right = right;
        var changed = false;

        if (try self.promoteRenderableMatrixValue(left)) |value| {
            if (value.raw != left.raw) {
                promoted_left = value;
                changed = true;
            }
        }
        if (try self.promoteRenderableMatrixValue(right)) |value| {
            if (value.raw != right.raw) {
                promoted_right = value;
                changed = true;
            }
        }
        if (try self.promoteTextNumericDyadOperand(promoted_left, promoted_right)) |value| {
            promoted_left = value;
            changed = true;
        }
        if (try self.promoteTextNumericDyadOperand(promoted_right, promoted_left)) |value| {
            promoted_right = value;
            changed = true;
        }
        if (!changed) return null;
        return .{ .left = promoted_left, .right = promoted_right };
    }

    fn applyBackendMatmulValues(self: *Session, left: Value, right: Value) KError!Value {
        if (comptime runtime_has_mlx) {
            return runtime_backend_exec.applyBackendMatmulValues(backend_exec_api, self, left, right);
        }
        return error.Unsupported;
    }

    fn applyMatmulValues(self: *Session, left: Value, right: Value) KError!Value {
        const promoted_left = (try self.promoteRenderableMatrixValue(left)) orelse left;
        const promoted_right = (try self.promoteRenderableMatrixValue(right)) orelse right;
        const shape = (try matmulShapeForValues(promoted_left, promoted_right)) orelse return error.Type;
        return switch (planMatmulBackend(self, promoted_left, promoted_right)) {
            .host => try self.applyHostMatmulGeneric(promoted_left, promoted_right, shape),
            .mlx => try self.applyBackendMatmulValues(promoted_left, promoted_right),
        };
    }

    fn denseFloatScalarValue(value: Value) ?f64 {
        return switch (value.tag()) {
            .float => value.asFloat(),
            .float32 => @floatCast(value.asFloat32()),
            .int => @floatFromInt(value.asInt()),
            .bool => @floatFromInt(@intFromBool(value.asBool())),
            else => null,
        };
    }

    fn denseFloat32ScalarValue(value: Value) ?f32 {
        return switch (value.tag()) {
            .float32 => value.asFloat32(),
            .int => @floatFromInt(value.asInt()),
            .bool => @floatFromInt(@intFromBool(value.asBool())),
            else => null,
        };
    }

    fn compactDenseProducerSourceValue(self: *Session, args: []const Value, source: CompactDenseProducerSource) KError!?Value {
        return switch (source.kind) {
            .scalar => source.scalar,
            .global_scalar => self.loadGlobalSlot(source.global_slot) catch |err| switch (err) {
                error.Name, error.Type => return null,
                else => return err,
            },
            .local => blk: {
                if (source.slot >= args.len) return null;
                break :blk args[source.slot];
            },
        };
    }

    fn denseFloat64ResolvedSourceFromCompact(self: *Session, args: []const Value, source: CompactDenseProducerSource) KError!?DenseFloat64ResolvedSource {
        const value = (try self.compactDenseProducerSourceValue(args, source)) orelse return null;
        if (denseFloatScalarValue(value)) |scalar| return .{ .scalar = scalar };
        if (source.kind != .local) return null;

        const view = hostDenseView(self, value) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        if (view != .float_array) return null;
        const items = hostFloatDenseViewContiguousFloat64(view.float_array) orelse return null;
        return if (source.reverse) .{ .reverse_array = items } else .{ .array = items };
    }

    fn denseFloat32ResolvedSourceFromCompact(self: *Session, args: []const Value, source: CompactDenseProducerSource) KError!?DenseFloat32ResolvedSource {
        const value = (try self.compactDenseProducerSourceValue(args, source)) orelse return null;
        if (denseFloat32ScalarValue(value)) |scalar| return .{ .scalar = scalar };
        if (source.kind != .local) return null;

        const view = hostDenseView(self, value) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        if (view != .float_array) return null;
        const items = hostFloatDenseViewContiguousFloat32(view.float_array) orelse return null;
        return if (source.reverse) .{ .reverse_array = items } else .{ .array = items };
    }

    fn denseFloat64PromotedSourceFromCompact(self: *Session, args: []const Value, source: CompactDenseProducerSource) KError!?DenseFloat64PromotedSource {
        const value = (try self.compactDenseProducerSourceValue(args, source)) orelse return null;
        if (denseFloatScalarValue(value)) |scalar| return .{ .scalar = scalar };
        if (source.kind != .local) return null;

        const view = hostDenseView(self, value) catch |err| switch (err) {
            error.Type => return null,
            else => return err,
        };
        if (view != .float_array) return null;
        if (hostFloatDenseViewContiguousFloat64(view.float_array)) |items| {
            return if (source.reverse) .{ .reverse_array64 = items } else .{ .array64 = items };
        }
        if (hostFloatDenseViewContiguousFloat32(view.float_array)) |items| {
            return if (source.reverse) .{ .reverse_array32 = items } else .{ .array32 = items };
        }
        return null;
    }

    fn denseFloatResultValue(self: *Session, comptime T: type, total: T) KError!Value {
        if (comptime T == f64) return try self.floatValue(total);
        if (comptime T == f32) return try self.float32Value(total);
        @compileError("unsupported dense float type");
    }

    fn foldAddMapFloatSourcesResult(self: *Session, comptime T: type, op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) KError!Value {
        const total = if (self.morselWorkersForDenseFusedReduction(len)) |workers|
            try foldAddMapFloatSourcesMorselOp(self, T, op, left, right, len, workers)
        else
            foldAddMapFloatSources(T, op, left, right, len);
        return try self.denseFloatResultValue(T, total);
    }

    fn foldAddUnaryFloatSourceResult(self: *Session, comptime T: type, op: BuiltinId, source: DenseResolvedSource(T), len: usize) KError!Value {
        const total = if (self.morselWorkersForDenseFusedReduction(len)) |workers|
            try foldAddUnaryFloatSourceMorselOp(self, T, op, source, len, workers)
        else
            foldAddUnaryFloatSource(T, op, source, len);
        return try self.denseFloatResultValue(T, total);
    }

    fn foldAddSquaredDiffFloatSourcesResult(self: *Session, comptime T: type, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) KError!Value {
        const total = if (self.morselWorkersForDenseFusedReduction(len)) |workers|
            try foldAddSquaredDiffFloatSourcesMorselOp(self, T, left, right, len, workers)
        else
            foldAddSquaredDiffFloatSources(T, left, right, len);
        return try self.denseFloatResultValue(T, total);
    }

    fn foldAddMapFloat64PromotedSourcesResult(self: *Session, op: BuiltinId, left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource, len: usize) KError!Value {
        const total = if (self.morselWorkersForDenseFusedReduction(len)) |workers|
            try foldAddMapFloat64PromotedSourcesMorselOp(self, op, left, right, len, workers)
        else
            foldAddMapFloat64PromotedSources(op, left, right, len);
        return try self.floatValue(total);
    }

    fn foldAddSquaredDiffFloat64PromotedSourcesResult(self: *Session, left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource, len: usize) KError!Value {
        const total = if (self.morselWorkersForDenseFusedReduction(len)) |workers|
            try foldAddSquaredDiffFloat64PromotedSourcesMorselOp(self, left, right, len, workers)
        else
            foldAddSquaredDiffFloat64PromotedSources(left, right, len);
        return try self.floatValue(total);
    }

    fn countCompareFloat64PromotedSourcesResult(self: *Session, op: BuiltinId, left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource, len: usize) KError!Value {
        const total = if (self.morselWorkersForDenseFusedReduction(len)) |workers|
            try countCompareFloat64PromotedSourcesMorselOp(self, op, left, right, len, workers)
        else
            countCompareFloat64PromotedSources(op, left, right, len);
        return try self.intValue(total);
    }

    fn tryFastDenseFloat32AddFoldMapSources(self: *Session, info: DenseAddFoldMapInfo, args: []const Value) KError!?Value {
        if (info.kind == .compare_count) return null;
        const left = (try self.denseFloat32ResolvedSourceFromCompact(args, info.left)) orelse return null;
        if (info.kind == .unary_map) {
            const len = denseFloatResolvedSourceLen(f32, left) orelse return null;
            if (len == 0) return null;
            return try self.foldAddUnaryFloatSourceResult(f32, info.map, left, len);
        }
        const right = (try self.denseFloat32ResolvedSourceFromCompact(args, info.right)) orelse return null;
        const len = denseFloatResolvedSourcesLen(f32, left, right) orelse return null;
        if (len == 0) return null;
        return switch (info.kind) {
            .map => try self.foldAddMapFloatSourcesResult(f32, info.map, left, right, len),
            .unary_map => unreachable,
            .squared_diff => try self.foldAddSquaredDiffFloatSourcesResult(f32, left, right, len),
            .compare_count => unreachable,
        };
    }

    fn tryFastDenseFloat64PromotedAddFoldMapSources(self: *Session, info: DenseAddFoldMapInfo, args: []const Value) KError!?Value {
        if (info.kind == .unary_map) return null;
        const left = (try self.denseFloat64PromotedSourceFromCompact(args, info.left)) orelse return null;
        const right = (try self.denseFloat64PromotedSourceFromCompact(args, info.right)) orelse return null;
        const len = denseFloat64PromotedSourcesLen(left, right) orelse return null;
        if (len == 0) return null;
        return switch (info.kind) {
            .map => try self.foldAddMapFloat64PromotedSourcesResult(info.map, left, right, len),
            .unary_map => unreachable,
            .squared_diff => try self.foldAddSquaredDiffFloat64PromotedSourcesResult(left, right, len),
            .compare_count => try self.countCompareFloat64PromotedSourcesResult(info.map, left, right, len),
        };
    }

    fn tryFastDenseFloatAddFoldMapSources(self: *Session, info: DenseAddFoldMapInfo, args: []const Value) KError!?Value {
        if (try self.tryFastDenseFloat32AddFoldMapSources(info, args)) |value| return value;

        if (info.kind != .compare_count) {
            const left_opt = try self.denseFloat64ResolvedSourceFromCompact(args, info.left);
            if (left_opt != null and info.kind == .unary_map) {
                const left = left_opt.?;
                const len = denseFloatResolvedSourceLen(f64, left) orelse return null;
                if (len == 0) return null;
                return try self.foldAddUnaryFloatSourceResult(f64, info.map, left, len);
            }
            const right_opt = try self.denseFloat64ResolvedSourceFromCompact(args, info.right);
            if (left_opt != null and right_opt != null) {
                const left = left_opt.?;
                const right = right_opt.?;
                const len = denseFloatResolvedSourcesLen(f64, left, right) orelse return null;
                if (len == 0) return null;
                return switch (info.kind) {
                    .map => try self.foldAddMapFloatSourcesResult(f64, info.map, left, right, len),
                    .unary_map => unreachable,
                    .squared_diff => try self.foldAddSquaredDiffFloatSourcesResult(f64, left, right, len),
                    .compare_count => unreachable,
                };
            }
        }

        return try self.tryFastDenseFloat64PromotedAddFoldMapSources(info, args);
    }

    fn tryFastDenseFloatInnerAddMap(self: *Session, info: InnerProductInfo, args: []const Value) KError!?Value {
        if (args.len != 2 or info.reduce != .add or !denseFloatSimdSupported(info.map)) return null;
        const left_len = numericVectorLen(args[0]) orelse return null;
        const right_len = numericVectorLen(args[1]) orelse return null;
        if (left_len != right_len) return error.Type;
        if (left_len == 0) return null;

        const left_view = try hostDenseView(self, args[0]);
        const right_view = try hostDenseView(self, args[1]);
        if (left_view != .float_array or right_view != .float_array) return null;

        const left_f32 = hostFloatDenseViewContiguousFloat32(left_view.float_array);
        const right_f32 = hostFloatDenseViewContiguousFloat32(right_view.float_array);
        const left_f64 = hostFloatDenseViewContiguousFloat64(left_view.float_array);
        const right_f64 = hostFloatDenseViewContiguousFloat64(right_view.float_array);

        if (left_f32 != null and right_f32 != null) {
            return try self.foldAddMapFloatSourcesResult(f32, info.map, .{ .array = left_f32.? }, .{ .array = right_f32.? }, left_len);
        }
        if (left_f64 != null and right_f64 != null) {
            return try self.foldAddMapFloatSourcesResult(f64, info.map, .{ .array = left_f64.? }, .{ .array = right_f64.? }, left_len);
        }
        if (left_f32 != null and right_f64 != null) {
            return try self.foldAddMapFloat64PromotedSourcesResult(info.map, .{ .array32 = left_f32.? }, .{ .array64 = right_f64.? }, left_len);
        }
        if (left_f64 != null and right_f32 != null) {
            return try self.foldAddMapFloat64PromotedSourcesResult(info.map, .{ .array64 = left_f64.? }, .{ .array32 = right_f32.? }, left_len);
        }
        return null;
    }

    fn tryFastCompactCodeDenseAddFoldMap(self: *Session, code: *const Code, args: []const Value) KError!?Value {
        if (args.len == 0 or args.len > 2) return null;
        const info = classifyCompactDenseAddFoldMapCode(code) orelse return null;
        if (comptime enable_probe_instrumentation) {
            self.debug.dense_fusion_compact_add_fold_map_candidate_count += 1;
            if (self.debug.disable_dense_fusion) {
                self.debug.dense_fusion_compact_add_fold_map_disabled_count += 1;
                return null;
            }
        }
        const value = switch (info.kind) {
            .unary_map => (try self.tryFastDenseFloatAddFoldMapSources(info, args)) orelse return null,
            .map => blk: {
                if (info.left.kind == .local and info.right.kind == .local and !info.left.reverse and !info.right.reverse) {
                    const left = args[info.left.slot];
                    const right = args[info.right.slot];
                    if (try self.tryFastDenseFloatInnerAddMap(.{ .reduce = .add, .map = info.map }, &.{ left, right })) |result| {
                        break :blk result;
                    }
                }
                break :blk (try self.tryFastDenseFloatAddFoldMapSources(info, args)) orelse return null;
            },
            .squared_diff => (try self.tryFastDenseFloatAddFoldMapSources(info, args)) orelse return null,
            .compare_count => (try self.tryFastDenseFloatAddFoldMapSources(info, args)) orelse return null,
        };
        if (comptime enable_probe_instrumentation) self.debug.dense_fusion_compact_add_fold_map_hit_count += 1;
        return value;
    }

    fn applyInnerProductClosure(self: *Session, info: InnerProductInfo, args: []const Value) KError!Value {
        if (args.len != 2) return error.Arity;
        if (info.reduce == .add and info.map == .mul and
            numericVectorLen(args[0]) != null and numericVectorLen(args[1]) != null)
        {
            return try self.applyMatmulValues(args[0], args[1]);
        }
        if (try self.tryFastDenseFloatInnerAddMap(info, args)) |value| return value;

        const mapped = try self.applyBuiltinCall(info.map, args);
        defer self.releaseValue(mapped);
        return try self.applyFoldDerived(Value.builtin(info.reduce), &[_]Value{mapped}, false);
    }

    const BatchedMatmulShape = struct {
        batch_len: usize,
        left_rows: usize,
        inner_len: usize,
        right_cols: usize,
    };

    const LeadingBatchedMatmulShape = struct {
        left_flat_shape: NumericShapeSnapshot,
        right_flat_shape: NumericShapeSnapshot,
        result_shape: NumericShapeSnapshot,
    };

    const BatchedMatmulLens = struct {
        left: usize,
        right: usize,
        result: usize,
    };

    fn batchedMatmulShapeForValues(left: Value, right: Value) KError!?BatchedMatmulShape {
        _ = valueNumericMode(left) orelse return null;
        _ = valueNumericMode(right) orelse return null;

        const left_handle = shapedNumericHandle(left) orelse return null;
        const right_handle = shapedNumericHandle(right) orelse return null;
        if (left_handle.rank != 3 or right_handle.rank != 3) return null;

        const batch_len: usize = @intCast(left_handle.shape[0]);
        if (batch_len == 0) return null;
        if (batch_len != @as(usize, @intCast(right_handle.shape[0]))) return error.Type;

        const left_rows: usize = @intCast(left_handle.shape[1]);
        const inner_len: usize = @intCast(left_handle.shape[2]);
        if (inner_len != @as(usize, @intCast(right_handle.shape[1]))) return error.Type;

        return .{
            .batch_len = batch_len,
            .left_rows = left_rows,
            .inner_len = inner_len,
            .right_cols = @intCast(right_handle.shape[2]),
        };
    }

    fn leadingBatchedMatmulShapeForValues(left: Value, right: Value) KError!?LeadingBatchedMatmulShape {
        _ = valueNumericMode(left) orelse return null;
        _ = valueNumericMode(right) orelse return null;

        const left_handle = shapedNumericHandle(left) orelse return null;
        const right_handle = shapedNumericHandle(right) orelse return null;
        if (left_handle.rank < 4 or right_handle.rank < 4) return null;
        if (left_handle.rank != right_handle.rank) return error.Type;

        const rank = left_handle.rank;
        var flat_batch_len: usize = 1;
        var result_shape = NumericShapeSnapshot{};
        result_shape.rank = rank;
        for (0..rank - 2) |idx| {
            const left_dim = left_handle.shape[idx];
            const right_dim = right_handle.shape[idx];
            if (left_dim != right_dim) return error.Type;
            const dim: usize = @intCast(left_dim);
            if (dim == 0) return null;
            flat_batch_len = std.math.mul(usize, flat_batch_len, dim) catch return error.Unsupported;
            result_shape.shape[idx] = left_dim;
        }

        const left_rows: usize = @intCast(left_handle.shape[rank - 2]);
        const inner_len: usize = @intCast(left_handle.shape[rank - 1]);
        if (inner_len != @as(usize, @intCast(right_handle.shape[rank - 2]))) return error.Type;
        const right_cols: usize = @intCast(right_handle.shape[rank - 1]);

        result_shape.shape[rank - 2] = std.math.cast(i32, left_rows) orelse return error.Unsupported;
        result_shape.shape[rank - 1] = std.math.cast(i32, right_cols) orelse return error.Unsupported;

        var left_flat_shape = NumericShapeSnapshot{};
        left_flat_shape.rank = 3;
        left_flat_shape.shape[0] = std.math.cast(i32, flat_batch_len) orelse return error.Unsupported;
        left_flat_shape.shape[1] = std.math.cast(i32, left_rows) orelse return error.Unsupported;
        left_flat_shape.shape[2] = std.math.cast(i32, inner_len) orelse return error.Unsupported;

        var right_flat_shape = NumericShapeSnapshot{};
        right_flat_shape.rank = 3;
        right_flat_shape.shape[0] = left_flat_shape.shape[0];
        right_flat_shape.shape[1] = std.math.cast(i32, inner_len) orelse return error.Unsupported;
        right_flat_shape.shape[2] = std.math.cast(i32, right_cols) orelse return error.Unsupported;

        return .{
            .left_flat_shape = left_flat_shape,
            .right_flat_shape = right_flat_shape,
            .result_shape = result_shape,
        };
    }

    fn planBatchedMatmulBackend(self: *Session, left: Value, right: Value, shape: BatchedMatmulShape) DenseExecBackend {
        const left_facts = denseValuePlanFacts(left);
        const right_facts = denseValuePlanFacts(right);
        return chooseDenseRegionBackend(self, .matmul, .{
            .elem_count = shape.batch_len * shape.left_rows * shape.inner_len * shape.right_cols,
            .matrix_rows = shape.batch_len * shape.left_rows,
            .matrix_cols = shape.right_cols,
            .has_backend_residency = left_facts.has_backend_residency or right_facts.has_backend_residency,
            .supports_backend = backendSupportsMatmulDtypes(self, left, right),
        });
    }

    fn batchedMatmulLens(shape: BatchedMatmulShape) ?BatchedMatmulLens {
        const left_mats = std.math.mul(usize, shape.batch_len, shape.left_rows) catch return null;
        const left_len = std.math.mul(usize, left_mats, shape.inner_len) catch return null;
        const right_mats = std.math.mul(usize, shape.batch_len, shape.inner_len) catch return null;
        const right_len = std.math.mul(usize, right_mats, shape.right_cols) catch return null;
        const result_mats = std.math.mul(usize, shape.batch_len, shape.left_rows) catch return null;
        const result_len = std.math.mul(usize, result_mats, shape.right_cols) catch return null;
        return .{ .left = left_len, .right = right_len, .result = result_len };
    }

    fn batchedMatmulResultShapeSnapshot(shape: BatchedMatmulShape) NumericShapeSnapshot {
        var snapshot = NumericShapeSnapshot{};
        snapshot.rank = 3;
        snapshot.shape[0] = @intCast(shape.batch_len);
        snapshot.shape[1] = @intCast(shape.left_rows);
        snapshot.shape[2] = @intCast(shape.right_cols);
        return snapshot;
    }

    fn finishHostBatchedMatmulFloatResult(self: *Session, shape: BatchedMatmulShape, out: HostFloatResult) KError!Value {
        const value = out.value();
        hostDenseSetFlags(try mutableNumericHostArrayValue(self, value), hostMatmulFloatResultFlags(out.items.len));
        defer self.releaseValue(value);
        return try newReshapeViewValue(self, value, batchedMatmulResultShapeSnapshot(shape));
    }

    fn finishHostBatchedMatmulFloat32Result(self: *Session, shape: BatchedMatmulShape, out: HostFloat32Result) KError!Value {
        const value = out.value();
        hostDenseSetFlags(try mutableNumericHostArrayValue(self, value), hostMatmulFloatResultFlags(out.items.len));
        defer self.releaseValue(value);
        return try newReshapeViewValue(self, value, batchedMatmulResultShapeSnapshot(shape));
    }

    fn hostBlasBatchedMatmulShapeSupported(shape: BatchedMatmulShape) bool {
        if (comptime !enable_host_accelerate_blas) return false;
        if (shape.batch_len == 0 or shape.left_rows == 0 or shape.right_cols == 0 or shape.inner_len == 0) return false;
        if (shape.left_rows > host_accelerate_blas_max_dim) return false;
        if (shape.right_cols > host_accelerate_blas_max_dim) return false;
        if (shape.inner_len > host_accelerate_blas_max_dim) return false;
        return true;
    }

    fn hostBatchedMatmulFloat32Items(value: Value, expected_len: usize) ?[]const f32 {
        const array = contiguousHostDenseIfPresentThroughReshape(value) orelse return null;
        return switch (array.storage) {
            .float32 => |items| blk: {
                const logical_items = hostDenseLogicalItems(f32, array, items);
                if (logical_items.len != expected_len) return null;
                break :blk logical_items;
            },
            else => null,
        };
    }

    fn hostBatchedMatmulFloat64Items(value: Value, expected_len: usize) ?[]const f64 {
        const array = contiguousHostDenseIfPresentThroughReshape(value) orelse return null;
        return switch (array.storage) {
            .float64 => |items| blk: {
                const logical_items = hostDenseLogicalItems(f64, array, items);
                if (logical_items.len != expected_len) return null;
                break :blk logical_items;
            },
            else => null,
        };
    }

    fn tryHostBlasBatchedMatmulFloat32(self: *Session, left: Value, right: Value, shape: BatchedMatmulShape) KError!?Value {
        if (!hostBlasBatchedMatmulShapeSupported(shape)) return null;
        const lens = batchedMatmulLens(shape) orelse return null;
        const left_items = hostBatchedMatmulFloat32Items(left, lens.left) orelse return null;
        const right_items = hostBatchedMatmulFloat32Items(right, lens.right) orelse return null;

        const out = try self.allocManagedHostFloat32Result(lens.result);
        if (kiwi_host_blas_sgemm_rowmajor_batched(out.items.ptr, left_items.ptr, right_items.ptr, shape.batch_len, shape.left_rows, shape.right_cols, shape.inner_len) == 0) {
            return error.Unsupported;
        }
        return try self.finishHostBatchedMatmulFloat32Result(shape, out);
    }

    fn tryHostBlasBatchedMatmulFloat(self: *Session, left: Value, right: Value, shape: BatchedMatmulShape) KError!?Value {
        if (!hostBlasBatchedMatmulShapeSupported(shape)) return null;
        const lens = batchedMatmulLens(shape) orelse return null;
        const left_items = hostBatchedMatmulFloat64Items(left, lens.left) orelse return null;
        const right_items = hostBatchedMatmulFloat64Items(right, lens.right) orelse return null;

        const out = try self.allocManagedHostFloatResult(lens.result);
        if (kiwi_host_blas_dgemm_rowmajor_batched(out.items.ptr, left_items.ptr, right_items.ptr, shape.batch_len, shape.left_rows, shape.right_cols, shape.inner_len) == 0) {
            return error.Unsupported;
        }
        return try self.finishHostBatchedMatmulFloatResult(shape, out);
    }

    fn applyHostBatchedMatmulValues(self: *Session, left: Value, right: Value, shape: BatchedMatmulShape) KError!Value {
        if (try self.tryHostBlasBatchedMatmulFloat32(left, right, shape)) |value| return value;
        if (try self.tryHostBlasBatchedMatmulFloat(left, right, shape)) |value| return value;

        const left_handle = shapedNumericHandle(left) orelse return error.Type;
        const right_handle = shapedNumericHandle(right) orelse return error.Type;

        var results = std.ArrayList(Value).empty;
        defer {
            for (results.items) |value| self.releaseValue(value);
            results.deinit(self.allocator);
        }
        try results.ensureTotalCapacity(self.allocator, shape.batch_len);

        for (0..shape.batch_len) |idx| {
            const left_item = try numericValueFirstAxisCellValue(self, left, left_handle, @intCast(idx));
            defer self.releaseValue(left_item);
            const right_item = try numericValueFirstAxisCellValue(self, right, right_handle, @intCast(idx));
            defer self.releaseValue(right_item);

            const item_shape = (try matmulShapeForValues(left_item, right_item)) orelse return error.Type;
            if (item_shape.result_rank != 2) return error.Type;
            const result = try self.applyHostMatmulGeneric(left_item, right_item, item_shape);
            try results.append(self.allocator, result);
        }
        return try self.createManagedArrayLikeFromValues(results.items);
    }

    fn applyLeadingBatchedMatmulValues(self: *Session, left: Value, right: Value, shape: LeadingBatchedMatmulShape) KError!Value {
        const flat_left = try newReshapeViewValue(self, left, shape.left_flat_shape);
        defer self.releaseValue(flat_left);
        const flat_right = try newReshapeViewValue(self, right, shape.right_flat_shape);
        defer self.releaseValue(flat_right);

        const flat_result = (try self.applyBatchedMatmulValues(flat_left, flat_right)) orelse return error.Type;
        defer self.releaseValue(flat_result);
        return try newReshapeViewValue(self, flat_result, shape.result_shape);
    }

    fn applyBatchedMatmulValues(self: *Session, left: Value, right: Value) KError!?Value {
        const shape = (try batchedMatmulShapeForValues(left, right)) orelse return null;
        return switch (self.planBatchedMatmulBackend(left, right, shape)) {
            .host => try self.applyHostBatchedMatmulValues(left, right, shape),
            .mlx => try self.applyBackendMatmulValues(left, right),
        };
    }

    fn dotValues(self: *Session, left: Value, right: Value) KError!Value {
        return try self.applyDot(left, right);
    }

    fn applyNumericMonad(self: *Session, op: BuiltinId, value: Value) KError!Value {
        if (NumericStructuralView.init(value)) |structural| {
            if (try numericStructuralDenseMonadValue(self, value, structural, op)) |result| return result;
        }
        const handle = mutableNumericHandle(value) orelse return error.Type;
        if (supportsBackendMonad(op) and !numericHasHostAttachment(handle) and hasBackendRealization(value)) {
            return try self.applyBackendArrayMonad(op, value);
        }
        if (!numericHasHostAttachment(handle) and numericArrayStructuralTag(handle) != .materialized) {
            const view = try hostDenseView(self, value);
            return try self.applyHostDenseViewMonad(op, value, view);
        }
        return self.applyHostArrayMonad(op, value, try hostStructuralArrayForHandle(self, handle));
    }

    fn applyHostDenseViewMonad(self: *Session, op: BuiltinId, source_value: Value, view: HostDenseView) KError!Value {
        return switch (view) {
            .int_array => |items| switch (op) {
                .add, .mul => self.shareValue(source_value),
                .sub => blk: {
                    const input_kind = hostIntDenseViewKind(items);
                    const input_range = hostIntDenseValueRange(source_value, items);
                    const input_flags = hostIntDenseValueFlags(source_value, items);
                    const len = hostIntDenseViewLen(items);
                    if (hostIntNegRange(input_range)) |result_range| {
                        const result_kind = hostIntStorageKindForRange(result_range.min, result_range.max);
                        var plan = try self.planHostIntUnaryOutput(source_value, input_kind, result_kind, len, false, true);
                        try fillIntNegDenseResult(&plan.output, items, plan.unchecked_safe);
                        break :blk try self.finishHostIntOutput(plan, intNegResultFlags(input_flags));
                    }
                    var attempt_kind = hostNegInitialResultKind(input_kind);
                    while (true) {
                        var plan = try self.planHostIntUnaryOutput(
                            source_value,
                            input_kind,
                            attempt_kind,
                            len,
                            false,
                            hostNegUncheckedSafeForOutput(input_kind, attempt_kind),
                        );
                        fillIntNegDenseResult(&plan.output, items, plan.unchecked_safe) catch |err| switch (err) {
                            error.Unsupported => {
                                try retryWiderHostIntKind(&attempt_kind);
                                continue;
                            },
                            else => return err,
                        };
                        break :blk try self.finishHostIntOutput(plan, intNegResultFlags(input_flags));
                    }
                },
                .div => blk: {
                    const plan = try self.planHostFloatUnaryOutput(source_value, hostIntDenseViewLen(items), false);
                    fillFloatUnaryIntDenseView(plan.output.items, op, items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .exp, .log, .sin, .cos, .tanh, .sigmoid => blk: {
                    const plan = try self.planHostFloatUnaryOutput(source_value, hostIntDenseViewLen(items), false);
                    fillFloatUnaryIntDenseView(plan.output.items, op, items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                else => error.Type,
            },
            .float_array => |items| switch (op) {
                .add, .mul => self.shareValue(source_value),
                .sub => blk: {
                    if (hostFloatDenseViewStorageKind(items) == .float32) {
                        const plan = try self.planHostFloat32UnaryOutput(source_value, hostFloatDenseViewLen(items), false);
                        fillFloat32NegDenseView(plan.output.items, items);
                        break :blk try self.finishHostFloat32Output(plan, 0);
                    }
                    const plan = try self.planHostFloatUnaryOutput(source_value, hostFloatDenseViewLen(items), false);
                    fillFloatNegDenseView(plan.output.items, items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .div => blk: {
                    if (hostFloatDenseViewStorageKind(items) == .float32) {
                        const plan = try self.planHostFloat32UnaryOutput(source_value, hostFloatDenseViewLen(items), false);
                        fillFloat32UnaryDenseView(plan.output.items, op, items);
                        break :blk try self.finishHostFloat32Output(plan, 0);
                    }
                    const plan = try self.planHostFloatUnaryOutput(source_value, hostFloatDenseViewLen(items), false);
                    fillFloatUnaryDenseView(plan.output.items, op, items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .exp, .log, .sin, .cos, .tanh, .sigmoid => blk: {
                    if (hostFloatDenseViewStorageKind(items) == .float32) {
                        const plan = try self.planHostFloat32UnaryOutput(source_value, hostFloatDenseViewLen(items), false);
                        fillFloat32UnaryDenseView(plan.output.items, op, items);
                        break :blk try self.finishHostFloat32Output(plan, 0);
                    }
                    const plan = try self.planHostFloatUnaryOutput(source_value, hostFloatDenseViewLen(items), false);
                    fillFloatUnaryDenseView(plan.output.items, op, items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                else => error.Type,
            },
            else => error.Type,
        };
    }

    fn applyNumericDyad(self: *Session, op: BuiltinId, left: Value, right: Value) KError!Value {
        const promoted_left = if (try self.promoteRenderableMatrixValue(left)) |value| value else left;
        const promoted_right = if (try self.promoteRenderableMatrixValue(right)) |value| value else right;
        if (planDenseNumericDyadBackend(self, op, promoted_left, promoted_right) == .mlx) {
            self.noteHostDenseDyadMiss(.planner_backend);
            return self.applyBackendArrayDyad(op, promoted_left, promoted_right);
        }
        return self.applyHostArrayDyad(op, promoted_left, promoted_right);
    }

    fn hasArrayOperand(left: Value, right: Value) bool {
        return left.tag() == .array or right.tag() == .array;
    }

    fn canApplyNumericDyad(left: Value, right: Value) bool {
        return valueNumericMode(left) != null and valueNumericMode(right) != null;
    }

    fn genericDyadDefaultEmptyPrototype(self: *Session) KError!Value {
        return try self.createManagedHostIntArray(&.{});
    }

    fn genericDyadEmptyPrototypeOperand(self: *Session, value: Value, array: ?*const HostBoxedArray) KError!Value {
        if (array) |items| {
            std.debug.assert(items.len() == 0);
            if (items.prototype) |prototype| return try self.retainEscapedValue(prototype);
            return try self.genericDyadDefaultEmptyPrototype();
        }
        return try self.retainEscapedValue(value);
    }

    fn applyGenericArrayDyadToPrototypes(self: *Session, op: BuiltinId, left: Value, right: Value, left_boxed: ?*const HostBoxedArray, right_boxed: ?*const HostBoxedArray) KError!?Value {
        if ((left_boxed == null or left_boxed.?.len() != 0) and (right_boxed == null or right_boxed.?.len() != 0)) return null;

        const lhs = try self.genericDyadEmptyPrototypeOperand(left, if (left_boxed != null and left_boxed.?.len() == 0) left_boxed else null);
        defer self.releaseValue(lhs);
        const rhs = try self.genericDyadEmptyPrototypeOperand(right, if (right_boxed != null and right_boxed.?.len() == 0) right_boxed else null);
        defer self.releaseValue(rhs);

        const prototype = switch (op) {
            .add => try self.addValues(lhs, rhs),
            .sub => try self.subValues(lhs, rhs),
            .mul => try self.mulValues(lhs, rhs),
            .div => try self.divValues(lhs, rhs),
            .pow => try self.powValues(lhs, rhs),
            .minimum => try self.minimumValues(lhs, rhs),
            .maximum => try self.maximumValues(lhs, rhs),
            .less => try self.lessValues(lhs, rhs),
            .more => try self.moreValues(lhs, rhs),
            .equal => try self.equalValues(lhs, rhs),
            else => return error.Unsupported,
        };
        defer self.releaseValue(prototype);
        return try self.emptySequenceForBoxedItem(.managed, prototype);
    }

    fn applyGenericArrayDyad(self: *Session, op: BuiltinId, left: Value, right: Value) KError!Value {
        const len = try arrayResultLen(left, right);
        const left_dense = if (left.tag() == .array and valueNumericMode(left) != null) try numericHostArrayValue(self, left) else null;
        const right_dense = if (right.tag() == .array and valueNumericMode(right) != null) try numericHostArrayValue(self, right) else null;
        const left_boxed = if (left.tag() == .array and left.arraySubkind() == .host_boxed_array) left.asHostBoxedArray() else null;
        const right_boxed = if (right.tag() == .array and right.arraySubkind() == .host_boxed_array) right.asHostBoxedArray() else null;
        if (len == 0) {
            if (try self.applyGenericArrayDyadToPrototypes(op, left, right, left_boxed, right_boxed)) |result| return result;
        }
        var out = std.ArrayList(Value).empty;
        defer {
            for (out.items) |value| self.releaseValue(value);
            out.deinit(self.allocator);
        }
        try out.ensureTotalCapacity(self.allocator, len);
        for (0..len) |idx| {
            const lhs = if (left_dense) |array|
                try self.hostDenseIndexScalar(left, array, @intCast(idx))
            else if (left_boxed) |array|
                try self.hostBoxedArrayIndexScalar(array, @intCast(idx))
            else
                left;
            defer if (left_dense != null or left_boxed != null) self.releaseValue(lhs);
            const rhs = if (right_dense) |array|
                try self.hostDenseIndexScalar(right, array, @intCast(idx))
            else if (right_boxed) |array|
                try self.hostBoxedArrayIndexScalar(array, @intCast(idx))
            else
                right;
            defer if (right_dense != null or right_boxed != null) self.releaseValue(rhs);
            try out.append(self.allocator, switch (op) {
                .add => try self.addValues(lhs, rhs),
                .sub => try self.subValues(lhs, rhs),
                .mul => try self.mulValues(lhs, rhs),
                .div => try self.divValues(lhs, rhs),
                .pow => try self.powValues(lhs, rhs),
                .minimum => try self.minimumValues(lhs, rhs),
                .maximum => try self.maximumValues(lhs, rhs),
                .less => try self.lessValues(lhs, rhs),
                .more => try self.moreValues(lhs, rhs),
                .equal => try self.equalValues(lhs, rhs),
                else => return error.Unsupported,
            });
        }
        return try self.makeArrayFromValues(out.items);
    }

    fn applyHostArrayMonad(self: *Session, op: BuiltinId, source_value: Value, array: *const HostDenseArray) KError!Value {
        return switch (op) {
            .add => self.shareValue(source_value),
            .sub => switch (array.storage) {
                .bit, .int8, .int16, .int32, .int64 => blk: {
                    const items = hostIntArrayView(array).?;
                    const input_kind = hostIntArrayViewKind(items);
                    const len = hostIntArrayViewLen(items);
                    if (hostIntNegRange(hostDenseCachedIntRange(array) orelse hostIntArrayViewEndpointRange(items, array.flags) orelse hostIntArrayViewRange(items))) |result_range| {
                        const result_kind = hostIntStorageKindForRange(result_range.min, result_range.max);
                        var plan = try self.planHostIntUnaryOutput(source_value, input_kind, result_kind, len, true, true);
                        try fillIntNegArrayResult(&plan.output, items, plan.unchecked_safe);
                        break :blk try self.finishHostIntOutput(plan, intNegResultFlags(array.flags));
                    }
                    var attempt_kind = hostNegInitialResultKind(input_kind);
                    while (true) {
                        var plan = try self.planHostIntUnaryOutput(
                            source_value,
                            input_kind,
                            attempt_kind,
                            len,
                            false,
                            hostNegUncheckedSafeForOutput(input_kind, attempt_kind),
                        );
                        fillIntNegArrayResult(&plan.output, items, plan.unchecked_safe) catch |err| switch (err) {
                            error.Unsupported => {
                                try retryWiderHostIntKind(&attempt_kind);
                                continue;
                            },
                            else => return err,
                        };
                        break :blk try self.finishHostIntOutput(plan, intNegResultFlags(array.flags));
                    }
                },
                .float64 => |items| blk: {
                    var plan = try self.planHostFloatUnaryOutput(source_value, items.len, true);
                    for (items, 0..) |item, idx| plan.output.items[idx] = -item;
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .float32 => |items| blk: {
                    const logical_items = hostDenseLogicalItems(f32, array, items);
                    var plan = try self.planHostFloat32UnaryOutput(source_value, logical_items.len, true);
                    for (logical_items, 0..) |item, idx| plan.output.items[idx] = -item;
                    break :blk try self.finishHostFloat32Output(plan, 0);
                },
            },
            .mul => self.shareValue(source_value),
            .div, .exp, .log, .sin, .cos, .tanh, .sigmoid => switch (array.storage) {
                .bit => |words| blk: {
                    const plan = try self.planHostFloatUnaryOutput(source_value, array.logical_len, false);
                    fillFloatUnaryBitArray(plan.output.items, op, .{ .words = words, .len = array.logical_len });
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .int8 => |items| blk: {
                    const plan = try self.planHostFloatUnaryOutput(source_value, items.len, false);
                    fillFloatUnaryArray(i8, plan.output.items, op, items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .int16 => |items| blk: {
                    const plan = try self.planHostFloatUnaryOutput(source_value, items.len, false);
                    fillFloatUnaryArray(i16, plan.output.items, op, items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .int32 => |items| blk: {
                    const plan = try self.planHostFloatUnaryOutput(source_value, items.len, false);
                    fillFloatUnaryArray(i32, plan.output.items, op, items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .int64 => |items| blk: {
                    const plan = try self.planHostFloatUnaryOutput(source_value, items.len, false);
                    fillFloatUnaryArray(i64, plan.output.items, op, items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .float64 => |items| blk: {
                    const plan = try self.planHostFloatUnaryOutput(source_value, items.len, true);
                    fillFloatUnaryArray(f64, plan.output.items, op, items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .float32 => |items| blk: {
                    const logical_items = hostDenseLogicalItems(f32, array, items);
                    const plan = try self.planHostFloat32UnaryOutput(source_value, logical_items.len, true);
                    for (logical_items, 0..) |item, idx| plan.output.items[idx] = @floatCast(applyFloatMonadOp(op, @as(f64, item)));
                    break :blk try self.finishHostFloat32Output(plan, 0);
                },
            },
            else => error.Type,
        };
    }

    fn applyHostArrayDyad(self: *Session, op: BuiltinId, left: Value, right: Value) KError!Value {
        const mode = arrayResultMode(op, left, right) orelse {
            self.noteHostDenseDyadMiss(.mode);
            return error.Type;
        };
        const len = try arrayResultLen(left, right);
        if (rowwiseMatrixVectorDyad(left, right)) |rowwise| {
            self.noteHostDenseDyadHost(op, left, right, len, true);
            return switch (mode) {
                .int => try self.applyHostArrayDyadRowwiseInt(op, left, right, rowwise, len),
                .float => try self.applyHostArrayDyadRowwiseFloat(op, left, right, rowwise, len),
            };
        }
        const left_view = hostDenseView(self, left) catch |err| {
            self.noteHostDenseDyadMiss(.view);
            return err;
        };
        const right_view = hostDenseView(self, right) catch |err| {
            self.noteHostDenseDyadMiss(.view);
            return err;
        };
        self.noteHostDenseDyadHost(op, left, right, len, false);
        return switch (mode) {
            .int => try self.applyHostArrayDyadInt(op, left, right, left_view, right_view, len),
            .float => try self.applyHostArrayDyadFloat(op, left, right, left_view, right_view, len),
        };
    }

    fn applyHostArrayDyadRowwiseInt(self: *Session, op: BuiltinId, left: Value, right: Value, rowwise: RowwiseMatrixVectorDyad, len: usize) KError!Value {
        var profile_scope = self.beginSamplingProfileScope(.dense_host);
        defer profile_scope.end();

        var out = std.ArrayList(i64).empty;
        defer out.deinit(self.allocator);
        try out.ensureTotalCapacity(self.allocator, len);
        for (0..len) |idx| {
            const lhs = try numericIntAt(left, rowwise.operandIndex(true, idx));
            const rhs = try numericIntAt(right, rowwise.operandIndex(false, idx));
            try out.append(self.allocator, switch (op) {
                .add => try checkedIntOp(.add, lhs, rhs),
                .sub => try checkedIntOp(.sub, lhs, rhs),
                .mul => try checkedIntOp(.mul, lhs, rhs),
                .pow => try checkedIntOp(.pow, lhs, rhs),
                .minimum => @min(lhs, rhs),
                .maximum => @max(lhs, rhs),
                else => return error.Type,
            });
        }
        const result = try self.createManagedHostIntArray(out.items);
        return try applyNonVectorNumericShapeToValue(self, result, numericShapeSnapshotMatrix(rowwise.rows, rowwise.cols));
    }

    fn applyHostArrayDyadRowwiseFloat(self: *Session, op: BuiltinId, left: Value, right: Value, rowwise: RowwiseMatrixVectorDyad, len: usize) KError!Value {
        var profile_scope = self.beginSamplingProfileScope(.dense_host);
        defer profile_scope.end();

        const left_view = try hostDenseView(self, left);
        const right_view = try hostDenseView(self, right);
        if (hostFloatDyadResultStorageKindForValues(left, right, left_view, right_view) == .float32) {
            const out = try self.allocManagedHostFloat32Result(len);
            for (0..len) |idx| {
                const lhs = try numericFloatAt(left, rowwise.operandIndex(true, idx));
                const rhs = try numericFloatAt(right, rowwise.operandIndex(false, idx));
                out.items[idx] = @floatCast(switch (op) {
                    .add => lhs + rhs,
                    .sub => lhs - rhs,
                    .mul => lhs * rhs,
                    .div => lhs / rhs,
                    .pow => std.math.pow(f64, lhs, rhs),
                    .minimum => @min(lhs, rhs),
                    .maximum => @max(lhs, rhs),
                    else => return error.Type,
                });
            }
            const result = out.value();
            return try applyNonVectorNumericShapeToValue(self, result, numericShapeSnapshotMatrix(rowwise.rows, rowwise.cols));
        }

        var out = std.ArrayList(f64).empty;
        defer out.deinit(self.allocator);
        try out.ensureTotalCapacity(self.allocator, len);
        for (0..len) |idx| {
            const lhs = try numericFloatAt(left, rowwise.operandIndex(true, idx));
            const rhs = try numericFloatAt(right, rowwise.operandIndex(false, idx));
            try out.append(self.allocator, switch (op) {
                .add => lhs + rhs,
                .sub => lhs - rhs,
                .mul => lhs * rhs,
                .div => lhs / rhs,
                .pow => std.math.pow(f64, lhs, rhs),
                .minimum => @min(lhs, rhs),
                .maximum => @max(lhs, rhs),
                else => return error.Type,
            });
        }
        const result = try self.createManagedHostFloatArray(out.items);
        return try applyNonVectorNumericShapeToValue(self, result, numericShapeSnapshotMatrix(rowwise.rows, rowwise.cols));
    }

    fn tryRangeIotaScalarIntDyad(self: *Session, op: BuiltinId, view: HostIntDenseView, scalar: i64, scalar_left: bool) KError!?Value {
        const range_view = switch (view) {
            .range_iota => |items| items,
            else => return null,
        };
        const range = numericArrayRangeIota(range_view.handle);
        const len = numericArrayRangeLen(range_view.handle);
        const shape = numericShapeSnapshotFromHandle(range_view.handle);
        const RangeParams = struct { start: i64, step: i64 };
        const params: RangeParams = switch (op) {
            .add => .{
                .start = try checkedIntOp(.add, range.start, scalar),
                .step = range.step,
            },
            .sub => if (scalar_left) .{
                .start = try checkedIntOp(.sub, scalar, range.start),
                .step = try checkedIntOp(.sub, 0, range.step),
            } else .{
                .start = try checkedIntOp(.sub, range.start, scalar),
                .step = range.step,
            },
            .mul => .{
                .start = try checkedIntOp(.mul, range.start, scalar),
                .step = try checkedIntOp(.mul, range.step, scalar),
            },
            else => return null,
        };
        return try newRangeIotaValueWithShape(self, .managed, len, params.start, params.step, shape);
    }

    fn fillDenseIntCastResolvedSourcesResult(
        self: *Session,
        comptime OutT: type,
        comptime LeftT: type,
        comptime RightT: type,
        out: []OutT,
        op: BuiltinId,
        left: DenseResolvedSource(LeftT),
        right: DenseResolvedSource(RightT),
        len: usize,
    ) void {
        if (self.morselWorkersForDenseMap(len)) |workers| {
            fillDenseIntCastSourcesStoreMorsel(self, OutT, LeftT, RightT, out, op, left, right, len, workers);
        } else {
            fillDenseIntCastSourcesStore(OutT, LeftT, RightT, out, op, left, right, len);
        }
    }

    fn tryFillIntDenseDenseResultSourcesTyped(self: *Session, comptime OutT: type, out: []OutT, op: BuiltinId, left_items: HostIntDenseView, right_items: HostIntDenseView, len: usize) bool {
        const out_kind = comptime hostIntStorageKindForDenseType(OutT);
        inline for (.{ i8, i16, i32, i64 }) |LeftT| {
            if (comptime hostIntStorageRank(hostIntStorageKindForDenseType(LeftT)) <= hostIntStorageRank(out_kind)) {
                if (denseIntDenseViewResolvedSource(LeftT, left_items)) |left_source| {
                    inline for (.{ i8, i16, i32, i64 }) |RightT| {
                        if (comptime hostIntStorageRank(hostIntStorageKindForDenseType(RightT)) <= hostIntStorageRank(out_kind)) {
                            if (denseIntDenseViewResolvedSource(RightT, right_items)) |right_source| {
                                self.fillDenseIntCastResolvedSourcesResult(OutT, LeftT, RightT, out, op, left_source, right_source, len);
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    fn tryFillIntDenseDenseResultSources(self: *Session, out: *HostIntResult, op: BuiltinId, left_items: HostIntDenseView, right_items: HostIntDenseView, unchecked_safe: bool) bool {
        if (!unchecked_safe or !denseIntSimdSupported(op)) return false;
        const len = hostIntDenseViewLen(left_items);
        if (hostIntDenseViewLen(right_items) != len) return false;
        switch (out.*) {
            .bit => return false,
            .int8 => |*dest| return self.tryFillIntDenseDenseResultSourcesTyped(i8, dest.items, op, left_items, right_items, len),
            .int16 => |*dest| return self.tryFillIntDenseDenseResultSourcesTyped(i16, dest.items, op, left_items, right_items, len),
            .int32 => |*dest| return self.tryFillIntDenseDenseResultSourcesTyped(i32, dest.items, op, left_items, right_items, len),
            .int64 => |*dest| return self.tryFillIntDenseDenseResultSourcesTyped(i64, dest.items, op, left_items, right_items, len),
        }
    }

    fn fillIntDenseDenseResultMorsel(self: *Session, out: *HostIntResult, op: BuiltinId, left_items: HostIntDenseView, right_items: HostIntDenseView, unchecked_safe: bool) KError!void {
        if (self.tryFillIntDenseDenseResultSources(out, op, left_items, right_items, unchecked_safe)) return;
        try fillIntDenseDenseResult(out, op, left_items, right_items, unchecked_safe);
    }

    fn tryFillIntScalarDenseResultSourcesTyped(self: *Session, comptime OutT: type, out: []OutT, op: BuiltinId, scalar: i64, items: HostIntDenseView, scalar_left: bool, len: usize) bool {
        const out_kind = comptime hostIntStorageKindForDenseType(OutT);
        const scalar_value = std.math.cast(OutT, scalar) orelse return false;
        const scalar_source = DenseResolvedSource(OutT){ .scalar = scalar_value };
        inline for (.{ i8, i16, i32, i64 }) |InT| {
            if (comptime hostIntStorageRank(hostIntStorageKindForDenseType(InT)) <= hostIntStorageRank(out_kind)) {
                if (denseIntDenseViewResolvedSource(InT, items)) |item_source| {
                    if (scalar_left) {
                        self.fillDenseIntCastResolvedSourcesResult(OutT, OutT, InT, out, op, scalar_source, item_source, len);
                    } else {
                        self.fillDenseIntCastResolvedSourcesResult(OutT, InT, OutT, out, op, item_source, scalar_source, len);
                    }
                    return true;
                }
            }
        }
        return false;
    }

    fn tryFillIntScalarDenseResultSources(self: *Session, out: *HostIntResult, op: BuiltinId, scalar: i64, items: HostIntDenseView, scalar_left: bool, unchecked_safe: bool) bool {
        if (!unchecked_safe or !denseIntSimdSupported(op)) return false;
        const len = hostIntDenseViewLen(items);
        switch (out.*) {
            .bit => return false,
            .int8 => |*dest| return self.tryFillIntScalarDenseResultSourcesTyped(i8, dest.items, op, scalar, items, scalar_left, len),
            .int16 => |*dest| return self.tryFillIntScalarDenseResultSourcesTyped(i16, dest.items, op, scalar, items, scalar_left, len),
            .int32 => |*dest| return self.tryFillIntScalarDenseResultSourcesTyped(i32, dest.items, op, scalar, items, scalar_left, len),
            .int64 => |*dest| return self.tryFillIntScalarDenseResultSourcesTyped(i64, dest.items, op, scalar, items, scalar_left, len),
        }
    }

    fn fillIntScalarDenseResultMorsel(self: *Session, out: *HostIntResult, op: BuiltinId, scalar: i64, items: HostIntDenseView, scalar_left: bool, unchecked_safe: bool) KError!void {
        if (self.tryFillIntScalarDenseResultSources(out, op, scalar, items, scalar_left, unchecked_safe)) return;
        try fillIntScalarDenseResult(out, op, scalar, items, scalar_left, unchecked_safe);
    }

    fn applyHostArrayDyadInt(self: *Session, op: BuiltinId, left_value: Value, right_value: Value, left: HostDenseView, right: HostDenseView, len: usize) KError!Value {
        var profile_scope = self.beginSamplingProfileScope(.dense_host);
        defer profile_scope.end();
        return switch (left) {
            .scalar_int => |li| switch (right) {
                .scalar_int => |ri| blk: {
                    const result = try checkedIntOp(op, li, ri);
                    break :blk try self.intValue(result);
                },
                .int_array => |items| blk: {
                    if (try self.tryRangeIotaScalarIntDyad(op, items, li, true)) |result| break :blk result;
                    const left_kind = hostIntStorageKindForValue(li);
                    const right_kind = hostIntDenseViewKind(items);
                    const left_range = hostIntRangeForValue(li);
                    const right_range = hostIntDenseValueRange(right_value, items);
                    const right_flags = hostIntDenseValueFlags(right_value, items);
                    if (hostIntDyadRange(op, left_range, right_range)) |result_range| {
                        const result_kind = hostIntDyadResultKindForRange(op, left_kind, right_kind, result_range);
                        var plan = try self.planHostIntDyadOutput(left_value, right_value, left_kind, right_kind, result_kind, len, true, true);
                        if (hostIntDenseScalarDyadUsesSimd(op, items, left_kind, result_kind, plan.unchecked_safe)) self.noteSimdKernel(.dense_dyad);
                        try self.fillIntScalarDenseResultMorsel(&plan.output, op, li, items, true, plan.unchecked_safe);
                        break :blk try self.finishHostIntOutput(plan, intArrayScalarResultFlags(op, right_flags, li, true));
                    }
                    var attempt_kind = hostIntInitialResultKind(op, left_kind, right_kind);
                    while (true) {
                        var plan = try self.planHostIntDyadOutput(
                            left_value,
                            right_value,
                            left_kind,
                            right_kind,
                            attempt_kind,
                            len,
                            false,
                            hostIntUncheckedSafeForOutput(left_kind, right_kind, attempt_kind),
                        );
                        if (hostIntDenseScalarDyadUsesSimd(op, items, left_kind, attempt_kind, plan.unchecked_safe)) self.noteSimdKernel(.dense_dyad);
                        self.fillIntScalarDenseResultMorsel(&plan.output, op, li, items, true, plan.unchecked_safe) catch |err| switch (err) {
                            error.Unsupported => {
                                try retryWiderHostIntKind(&attempt_kind);
                                continue;
                            },
                            else => return err,
                        };
                        break :blk try self.finishHostIntOutput(plan, intArrayScalarResultFlags(op, right_flags, li, true));
                    }
                },
                else => error.Type,
            },
            .int_array => |items| switch (right) {
                .scalar_int => |ri| blk: {
                    if (try self.tryRangeIotaScalarIntDyad(op, items, ri, false)) |result| break :blk result;
                    const left_kind = hostIntDenseViewKind(items);
                    const right_kind = hostIntStorageKindForValue(ri);
                    const left_range = hostIntDenseValueRange(left_value, items);
                    const left_flags = hostIntDenseValueFlags(left_value, items);
                    const right_range = hostIntRangeForValue(ri);
                    if (hostIntDyadRange(op, left_range, right_range)) |result_range| {
                        const result_kind = hostIntDyadResultKindForRange(op, left_kind, right_kind, result_range);
                        var plan = try self.planHostIntDyadOutput(left_value, right_value, left_kind, right_kind, result_kind, len, true, true);
                        if (hostIntDenseScalarDyadUsesSimd(op, items, right_kind, result_kind, plan.unchecked_safe)) self.noteSimdKernel(.dense_dyad);
                        try self.fillIntScalarDenseResultMorsel(&plan.output, op, ri, items, false, plan.unchecked_safe);
                        break :blk try self.finishHostIntOutput(plan, intArrayScalarResultFlags(op, left_flags, ri, false));
                    }
                    var attempt_kind = hostIntInitialResultKind(op, left_kind, right_kind);
                    while (true) {
                        var plan = try self.planHostIntDyadOutput(
                            left_value,
                            right_value,
                            left_kind,
                            right_kind,
                            attempt_kind,
                            len,
                            false,
                            hostIntUncheckedSafeForOutput(left_kind, right_kind, attempt_kind),
                        );
                        if (hostIntDenseScalarDyadUsesSimd(op, items, right_kind, attempt_kind, plan.unchecked_safe)) self.noteSimdKernel(.dense_dyad);
                        self.fillIntScalarDenseResultMorsel(&plan.output, op, ri, items, false, plan.unchecked_safe) catch |err| switch (err) {
                            error.Unsupported => {
                                try retryWiderHostIntKind(&attempt_kind);
                                continue;
                            },
                            else => return err,
                        };
                        break :blk try self.finishHostIntOutput(plan, intArrayScalarResultFlags(op, left_flags, ri, false));
                    }
                },
                .int_array => |right_items| blk: {
                    const left_kind = hostIntDenseViewKind(items);
                    const right_kind = hostIntDenseViewKind(right_items);
                    const left_range = hostIntDenseValueRange(left_value, items);
                    const right_range = hostIntDenseValueRange(right_value, right_items);
                    const left_flags = hostIntDenseValueFlags(left_value, items);
                    const right_flags = hostIntDenseValueFlags(right_value, right_items);
                    if (hostIntDyadRange(op, left_range, right_range)) |result_range| {
                        const result_kind = hostIntDyadResultKindForRange(op, left_kind, right_kind, result_range);
                        var plan = try self.planHostIntDyadOutput(left_value, right_value, left_kind, right_kind, result_kind, len, true, true);
                        if (hostIntDenseDenseDyadUsesSimd(op, items, right_items, result_kind, plan.unchecked_safe)) self.noteSimdKernel(.dense_dyad);
                        try self.fillIntDenseDenseResultMorsel(&plan.output, op, items, right_items, plan.unchecked_safe);
                        break :blk try self.finishHostIntOutput(plan, intArrayArrayResultFlags(op, left_flags, right_flags));
                    }
                    var attempt_kind = hostIntInitialResultKind(op, left_kind, right_kind);
                    while (true) {
                        var plan = try self.planHostIntDyadOutput(
                            left_value,
                            right_value,
                            left_kind,
                            right_kind,
                            attempt_kind,
                            len,
                            false,
                            hostIntUncheckedSafeForOutput(left_kind, right_kind, attempt_kind),
                        );
                        if (hostIntDenseDenseDyadUsesSimd(op, items, right_items, attempt_kind, plan.unchecked_safe)) self.noteSimdKernel(.dense_dyad);
                        self.fillIntDenseDenseResultMorsel(&plan.output, op, items, right_items, plan.unchecked_safe) catch |err| switch (err) {
                            error.Unsupported => {
                                try retryWiderHostIntKind(&attempt_kind);
                                continue;
                            },
                            else => return err,
                        };
                        break :blk try self.finishHostIntOutput(plan, intArrayArrayResultFlags(op, left_flags, right_flags));
                    }
                },
                else => error.Type,
            },
            else => error.Type,
        };
    }

    fn denseFloat32StoreSourceFromHostDenseView(self: *Session, view: HostDenseView) ?DenseFloat32ResolvedSource {
        _ = self;
        return switch (view) {
            .scalar_int => |value| .{ .scalar = @floatFromInt(value) },
            .scalar_float => |value| .{ .scalar = @floatCast(value) },
            .float_array => |items| blk: {
                if (hostFloatDenseViewContiguousFloat32(items)) |source| break :blk .{ .array = source };
                if (fullReverseFloatDenseViewSource32(items)) |source| break :blk .{ .reverse_array = source };
                break :blk null;
            },
            else => null,
        };
    }

    fn denseFloat64StoreSourceFromHostDenseView(self: *Session, view: HostDenseView) ?DenseFloat64ResolvedSource {
        _ = self;
        return switch (view) {
            .scalar_int => |value| .{ .scalar = @floatFromInt(value) },
            .scalar_float => |value| .{ .scalar = value },
            .float_array => |items| blk: {
                if (hostFloatDenseViewContiguousFloat64(items)) |source| break :blk .{ .array = source };
                if (fullReverseFloatDenseViewSource64(items)) |source| break :blk .{ .reverse_array = source };
                break :blk null;
            },
            else => null,
        };
    }

    fn denseFloat64PromotedStoreSourceFromHostDenseView(self: *Session, view: HostDenseView) ?DenseFloat64PromotedSource {
        _ = self;
        return switch (view) {
            .scalar_int => |value| .{ .scalar = @floatFromInt(value) },
            .scalar_float => |value| .{ .scalar = value },
            .float_array => |items| blk: {
                if (hostFloatDenseViewContiguousFloat64(items)) |source| break :blk .{ .array64 = source };
                if (fullReverseFloatDenseViewSource64(items)) |source| break :blk .{ .reverse_array64 = source };
                if (hostFloatDenseViewContiguousFloat32(items)) |source| break :blk .{ .array32 = source };
                if (fullReverseFloatDenseViewSource32(items)) |source| break :blk .{ .reverse_array32 = source };
                break :blk null;
            },
            else => null,
        };
    }

    fn fillHostArrayDyadFloat64Resolved(self: *Session, out: []f64, op: BuiltinId, left_source: DenseFloat64ResolvedSource, right_source: DenseFloat64ResolvedSource, len: usize) void {
        if (self.morselWorkersForDenseMap(len)) |workers| {
            fillDenseFloatSourcesStoreMorsel(self, f64, out, op, left_source, right_source, len, workers);
        } else {
            fillDenseFloatSourcesStore(f64, out, op, left_source, right_source, len);
        }
        self.noteSimdKernel(.dense_dyad);
    }

    fn fillHostArrayDyadFloat64PromotedResolved(self: *Session, out: []f64, op: BuiltinId, left_source: DenseFloat64PromotedSource, right_source: DenseFloat64PromotedSource, len: usize) void {
        if (self.morselWorkersForDenseMap(len)) |workers| {
            fillDenseFloat64PromotedSourcesStoreMorsel(self, out, op, left_source, right_source, len, workers);
        } else {
            fillDenseFloat64PromotedSourcesStore(out, op, left_source, right_source, len);
        }
        self.noteSimdKernel(.dense_dyad);
    }

    fn fillHostArrayDyadIntFloatResolved(
        self: *Session,
        comptime T: type,
        comptime int_left: bool,
        out: []f64,
        op: BuiltinId,
        int_source: DenseResolvedSource(T),
        float_source: DenseFloat64PromotedSource,
        len: usize,
    ) void {
        if (self.morselWorkersForDenseMap(len)) |workers| {
            fillDenseIntFloatSourcesStoreMorsel(self, T, int_left, out, op, int_source, float_source, len, workers);
        } else {
            fillDenseIntFloatSourcesStore(T, int_left, out, op, int_source, float_source, len);
        }
        self.noteSimdKernel(.dense_dyad);
    }

    fn fillHostArrayDyadIntFloat32Resolved(
        self: *Session,
        comptime T: type,
        comptime int_left: bool,
        out: []f32,
        op: BuiltinId,
        int_source: DenseResolvedSource(T),
        float_source: DenseFloat32ResolvedSource,
        len: usize,
    ) void {
        if (self.morselWorkersForDenseMap(len)) |workers| {
            fillDenseIntResolvedFloatSourcesStoreMorsel(self, T, f32, int_left, out, op, int_source, float_source, len, workers);
        } else {
            fillDenseIntResolvedFloatSourcesStore(T, f32, int_left, out, op, int_source, float_source, len);
        }
        self.noteSimdKernel(.dense_dyad);
    }

    fn fillHostArrayDyadIntFloat32Direct(
        self: *Session,
        comptime int_left: bool,
        out: []f32,
        op: BuiltinId,
        int_items: HostIntDenseView,
        float_source: DenseFloat32ResolvedSource,
        len: usize,
    ) bool {
        if (!denseFloatSimdSupported(op)) return false;
        inline for (.{ i8, i16, i32, i64 }) |T| {
            if (denseIntDenseViewResolvedSource(T, int_items)) |int_source| {
                const source_len = denseIntResolvedFloatSourcesLen(T, f32, int_source, float_source) orelse return false;
                if (source_len != len or out.len != len) return false;
                self.fillHostArrayDyadIntFloat32Resolved(T, int_left, out, op, int_source, float_source, len);
                return true;
            }
        }
        return false;
    }

    fn tryFastHostArrayDyadIntFloat(
        self: *Session,
        comptime int_left: bool,
        op: BuiltinId,
        left_value: Value,
        right_value: Value,
        int_items: HostIntDenseView,
        float_source: DenseFloat64PromotedSource,
        len: usize,
        allow_reuse: bool,
    ) KError!?Value {
        if (!denseFloatSimdSupported(op)) return null;
        inline for (.{ i8, i16, i32, i64 }) |T| {
            if (denseIntDenseViewResolvedSource(T, int_items)) |int_source| {
                const source_len = denseIntFloatSourcesLen(T, int_source, float_source) orelse return null;
                if (source_len != len) return null;
                const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, allow_reuse);
                self.fillHostArrayDyadIntFloatResolved(T, int_left, plan.output.items, op, int_source, float_source, len);
                return try self.finishHostFloatOutput(plan, 0);
            }
        }
        return null;
    }

    fn fillHostArrayDyadFloat32Direct(self: *Session, out: []f32, op: BuiltinId, left: HostDenseView, right: HostDenseView) bool {
        if (!denseFloatSimdSupported(op)) return false;
        if (left == .float_array and left.float_array == .transpose) {
            switch (right) {
                .scalar_int => |value| return fillFloat32ScalarTransposeDenseView(out, op, @floatFromInt(value), left.float_array.transpose, false),
                .scalar_float => |value| return fillFloat32ScalarTransposeDenseView(out, op, @floatCast(value), left.float_array.transpose, false),
                else => {},
            }
        }
        if (right == .float_array and right.float_array == .transpose) {
            switch (left) {
                .scalar_int => |value| return fillFloat32ScalarTransposeDenseView(out, op, @floatFromInt(value), right.float_array.transpose, true),
                .scalar_float => |value| return fillFloat32ScalarTransposeDenseView(out, op, @floatCast(value), right.float_array.transpose, true),
                else => {},
            }
        }

        const left_source = self.denseFloat32StoreSourceFromHostDenseView(left) orelse return false;
        const right_source = self.denseFloat32StoreSourceFromHostDenseView(right) orelse return false;
        const len = denseFloatResolvedSourcesLen(f32, left_source, right_source) orelse return false;
        if (len != out.len) return false;

        if (self.morselWorkersForDenseMap(out.len)) |workers| {
            fillDenseFloatSourcesStoreMorsel(self, f32, out, op, left_source, right_source, out.len, workers);
        } else {
            fillDenseFloatSourcesStore(f32, out, op, left_source, right_source, out.len);
        }
        self.noteSimdKernel(.dense_dyad);
        return true;
    }

    fn applyHostArrayDyadFloat(self: *Session, op: BuiltinId, left_value: Value, right_value: Value, left: HostDenseView, right: HostDenseView, len: usize) KError!Value {
        var profile_scope = self.beginSamplingProfileScope(.dense_host);
        defer profile_scope.end();
        if (hostFloatDyadResultStorageKindForValues(left_value, right_value, left, right) == .float32) {
            const plan = try self.planHostFloat32DyadOutput(left_value, right_value, len, true);
            var filled_direct = self.fillHostArrayDyadFloat32Direct(plan.output.items, op, left, right);
            if (!filled_direct) {
                if (left == .int_array) {
                    if (self.denseFloat32StoreSourceFromHostDenseView(right)) |float_source| {
                        filled_direct = self.fillHostArrayDyadIntFloat32Direct(true, plan.output.items, op, left.int_array, float_source, len);
                    }
                }
                if (!filled_direct and right == .int_array) {
                    if (self.denseFloat32StoreSourceFromHostDenseView(left)) |float_source| {
                        filled_direct = self.fillHostArrayDyadIntFloat32Direct(false, plan.output.items, op, right.int_array, float_source, len);
                    }
                }
            }
            if (!filled_direct) {
                for (0..len) |idx| {
                    plan.output.items[idx] = applyFloat32Op(
                        op,
                        @floatCast(try hostDenseViewFloatItem(left, idx)),
                        @floatCast(try hostDenseViewFloatItem(right, idx)),
                    );
                }
            }
            return try self.finishHostFloat32Output(plan, 0);
        }
        if (denseFloatSimdSupported(op)) {
            if (self.denseFloat64StoreSourceFromHostDenseView(left)) |left_source| {
                if (self.denseFloat64StoreSourceFromHostDenseView(right)) |right_source| {
                    if (denseFloatResolvedSourcesLen(f64, left_source, right_source)) |source_len| {
                        if (source_len == len) {
                            const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, true);
                            self.fillHostArrayDyadFloat64Resolved(plan.output.items, op, left_source, right_source, len);
                            return try self.finishHostFloatOutput(plan, 0);
                        }
                    }
                }
            }
        }
        if (denseFloatSimdSupported(op)) {
            if (self.denseFloat64PromotedStoreSourceFromHostDenseView(left)) |left_source| {
                if (self.denseFloat64PromotedStoreSourceFromHostDenseView(right)) |right_source| {
                    if (denseFloat64PromotedSourcesLen(left_source, right_source)) |source_len| {
                        if (source_len == len) {
                            const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, true);
                            self.fillHostArrayDyadFloat64PromotedResolved(plan.output.items, op, left_source, right_source, len);
                            return try self.finishHostFloatOutput(plan, 0);
                        }
                    }
                }
            }
        }
        if (left == .int_array) {
            if (self.denseFloat64PromotedStoreSourceFromHostDenseView(right)) |float_source| {
                if (try self.tryFastHostArrayDyadIntFloat(true, op, left_value, right_value, left.int_array, float_source, len, right == .float_array)) |result| return result;
            }
        }
        if (right == .int_array) {
            if (self.denseFloat64PromotedStoreSourceFromHostDenseView(left)) |float_source| {
                if (try self.tryFastHostArrayDyadIntFloat(false, op, left_value, right_value, right.int_array, float_source, len, left == .float_array)) |result| return result;
            }
        }
        return switch (left) {
            .scalar_int => |li| switch (right) {
                .scalar_int => |ri| blk: {
                    const result = applyFloatOp(op, @floatFromInt(li), @floatFromInt(ri));
                    break :blk try self.floatValue(result);
                },
                .scalar_float => |rf| blk: {
                    const result = applyFloatOp(op, @floatFromInt(li), rf);
                    break :blk try self.floatValue(result);
                },
                .int_array => |right_items| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, false);
                    fillFloatScalarIntDenseView(plan.output.items, op, @floatFromInt(li), right_items, true);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .float_array => |right_items| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, true);
                    fillFloatScalarDenseView(plan.output.items, op, @floatFromInt(li), right_items, true);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
            },
            .scalar_float => |lf| switch (right) {
                .scalar_int => |ri| blk: {
                    const result = applyFloatOp(op, lf, @floatFromInt(ri));
                    break :blk try self.floatValue(result);
                },
                .scalar_float => |rf| blk: {
                    const result = applyFloatOp(op, lf, rf);
                    break :blk try self.floatValue(result);
                },
                .int_array => |right_items| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, false);
                    fillFloatScalarIntDenseView(plan.output.items, op, lf, right_items, true);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .float_array => |right_items| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, true);
                    fillFloatScalarDenseView(plan.output.items, op, lf, right_items, true);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
            },
            .int_array => |items| switch (right) {
                .scalar_int => |ri| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, false);
                    fillFloatScalarIntDenseView(plan.output.items, op, @floatFromInt(ri), items, false);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .scalar_float => |rf| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, false);
                    fillFloatScalarIntDenseView(plan.output.items, op, rf, items, false);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .int_array => |right_items| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, false);
                    fillFloatIntDenseViewIntDenseView(plan.output.items, op, items, right_items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .float_array => |right_items| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, true);
                    fillFloatIntDenseViewDenseView(plan.output.items, op, items, right_items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
            },
            .float_array => |items| switch (right) {
                .scalar_int => |ri| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, true);
                    fillFloatScalarDenseView(plan.output.items, op, @floatFromInt(ri), items, false);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .scalar_float => |rf| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, true);
                    fillFloatScalarDenseView(plan.output.items, op, rf, items, false);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .int_array => |right_items| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, true);
                    fillFloatDenseViewIntDenseView(plan.output.items, op, items, right_items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
                .float_array => |right_items| blk: {
                    const plan = try self.planHostFloatDyadOutput(left_value, right_value, len, true);
                    fillFloatDenseViewDenseView(plan.output.items, op, items, right_items);
                    break :blk try self.finishHostFloatOutput(plan, 0);
                },
            },
        };
    }

    fn applyBackendArrayMonad(self: *Session, op: BuiltinId, value: Value) KError!Value {
        if (comptime runtime_has_mlx) {
            return runtime_backend_exec.applyBackendArrayMonad(backend_exec_api, self, op, value);
        }
        return error.Unsupported;
    }

    fn applyBackendArrayDyad(self: *Session, op: BuiltinId, left: Value, right: Value) KError!Value {
        if (comptime runtime_has_mlx) {
            var profile_scope = self.beginSamplingProfileScope(.dense_mlx);
            defer profile_scope.end();
            return runtime_backend_exec.applyBackendArrayDyad(backend_exec_api, self, op, left, right);
        }
        return error.Unsupported;
    }

    fn materializeBackendArrayFromHandle(self: *Session, handle: *NumericArray) KError!mlx.Array {
        if (comptime runtime_has_mlx) {
            var profile_scope = self.beginSamplingProfileScope(.mlx_realization);
            defer profile_scope.end();
            if (try tryEnsureManagedBackendRealizationForHandle(self, handle)) |owned| {
                return owned.array.clone() catch |err| return mapMlxError(err);
            }
            if (numericArrayIsRangeIota(handle)) return try createBackendArrayFromRangeIota(self, handle);
            if (numericArrayIsFlatSlice(handle)) return try createBackendArrayFromFlatSlice(self, handle);
            if (numericArrayIsFlatConcat(handle)) return try createBackendArrayFromFlatConcat(self, handle);
            if (numericArrayIsFlatSegments(handle)) return try createBackendArrayFromFlatSegments(self, handle);
            if (numericArrayIsFirstAxisSlice(handle)) return try createBackendArrayFromFirstAxisSlice(self, handle);
            if (numericArrayIsFirstAxisIndex(handle)) return try createBackendArrayFromFirstAxisIndex(self, handle);
            if (numericArrayIsFirstAxisConcat(handle)) return try createBackendArrayFromFirstAxisConcat(self, handle);
            if (numericArrayIsReshapeView(handle)) return try createBackendArrayFromReshapeView(self, handle);
            if (numericArrayIsTransposeView(handle)) return try createBackendArrayFromTransposeView(self, handle);
            return try createBackendArrayFromHostArray(self, Value.numericArray(handle), try hostStructuralArrayForHandle(self, handle));
        }
        return error.Unsupported;
    }

    fn materializeBackendArray(self: *Session, value: Value) KError!mlx.Array {
        return switch (value.tag()) {
            .int => blk: {
                const item = std.math.cast(i32, value.asInt()) orelse return error.Unsupported;
                break :blk mlx.Array.fromInt(item);
            },
            .float32 => mlx.Array.fromFloat(value.asFloat32()),
            .float => mlx.Array.fromFloat64(value.asFloat()),
            .bool => mlx.Array.fromInt(@intFromBool(value.asBool())),
            .array => blk: {
                const handle = mutableNumericHandle(value) orelse return error.Internal;
                break :blk try self.materializeBackendArrayFromHandle(handle);
            },
            else => error.Type,
        };
    }

    fn negateIntValue(self: *Session, value: i64) KError!Value {
        const result = @subWithOverflow(@as(i64, 0), value);
        if (result[1] != 0) return error.Unsupported;
        return try self.intValue(result[0]);
    }

    fn addIntValue(self: *Session, left: i64, right: i64) KError!Value {
        const result = @addWithOverflow(left, right);
        if (result[1] != 0) return error.Unsupported;
        return try self.intValue(result[0]);
    }

    fn subIntValue(self: *Session, left: i64, right: i64) KError!Value {
        const result = @subWithOverflow(left, right);
        if (result[1] != 0) return error.Unsupported;
        return try self.intValue(result[0]);
    }

    fn mulIntValue(self: *Session, left: i64, right: i64) KError!Value {
        const result = @mulWithOverflow(left, right);
        if (result[1] != 0) return error.Unsupported;
        return try self.intValue(result[0]);
    }

    fn classifyGlobalValue(value: Value) GlobalValueClass {
        return switch (value.tag()) {
            .int, .float, .float32, .bool => .scalar,
            .builtin => .builtin,
            .closure => .closure,
            .array => blk: {
                if (valueNonVectorNumericShape(value) == null) {
                    if (hostDenseIfPresent(value)) |host| {
                        break :blk switch (hostDenseNumericMode(host)) {
                            .int => .dense_int_vector,
                            .float => .dense_float_vector,
                        };
                    }
                }
                break :blk .array;
            },
        };
    }

    fn codeForStoredGlobal(value: Value) ?*const Code {
        if (value.tag() != .closure) return null;
        const closure = value.asClosure();
        if (closure.kind != .plain or closure.captures.len != 0) return null;
        return closure.code;
    }

    fn internGlobalSlot(self: *Session, name: []const u8) !u16 {
        if (self.global_slots.get(name)) |slot| return slot;

        const slot = std.math.cast(u16, self.global_cells.items.len) orelse return error.Unsupported;
        const owned_name = try self.arena.allocator().dupe(u8, name);
        try self.global_cells.append(self.allocator, .{});
        try self.global_names.append(self.allocator, owned_name);
        try self.global_slots.put(owned_name, slot);
        return slot;
    }

    fn storeGlobalSlot(self: *Session, slot: u16, value: Value) !void {
        if (slot >= self.global_cells.items.len) return error.Internal;
        const cell = &self.global_cells.items[slot];
        if (cell.initialized) self.releaseValue(cell.value);
        const stored = try self.retainGlobalStoredValue(value);
        const code = codeForStoredGlobal(stored);
        cell.* = .{
            .value = stored,
            .initialized = true,
            .class = classifyGlobalValue(stored),
            .code = code,
        };
    }

    pub fn debugGlobalIsFrozenClosure(self: *Session, name: []const u8) !bool {
        const slot = self.global_slots.get(name) orelse return error.Name;
        const value = try self.loadGlobalSlot(slot);
        return value.tag() == .closure and value.asClosure().header.owner == .frozen;
    }

    pub fn debugGlobalValue(self: *Session, name: []const u8) !Value {
        const slot = self.global_slots.get(name) orelse return error.Name;
        return try self.loadGlobalSlot(slot);
    }

    pub fn debugMakeManagedHostIntVector(self: *Session, data: []const i64) !Value {
        var min_value: i64 = 0;
        var max_value: i64 = 0;
        if (data.len != 0) {
            min_value = data[0];
            max_value = data[0];
            for (data[1..]) |item| {
                min_value = @min(min_value, item);
                max_value = @max(max_value, item);
            }
        }
        var out = try self.allocManagedHostIntResult(hostIntStorageKindForRange(min_value, max_value), data.len);
        for (data, 0..) |item, idx| try out.set(idx, item);
        return out.value();
    }

    pub fn debugMaterializeBackendArrayValue(self: *Session, value: Value) !void {
        var array = try self.materializeBackendArray(value);
        array.deinit();
    }

    pub fn debugEnsureHostRealizationValue(self: *Session, value: Value) !void {
        _ = try tryEnsureHostRealization(self, value) orelse return error.Unsupported;
    }

    fn loadGlobalSlot(self: *Session, slot: u16) KError!Value {
        return (try self.loadGlobalCell(slot)).value;
    }

    fn loadGlobalCell(self: *Session, slot: u16) KError!*GlobalCell {
        if (slot >= self.global_cells.items.len) return error.Internal;
        const cell = &self.global_cells.items[slot];
        if (!cell.initialized) return error.Name;
        return cell;
    }

    fn takeGlobalSlot(self: *Session, slot: u16) KError!Value {
        const cell = try self.loadGlobalCell(slot);
        const value = cell.value;
        cell.value = Value.fromBool(false);
        cell.class = classifyGlobalValue(cell.value);
        cell.code = null;
        return value;
    }

    fn createOwnedHostIntArray(self: *Session, owner: HeapOwner, items: []const i64) !Value {
        const analysis = analyzeIntSlice(items);
        var out = try self.allocOwnedHostIntResult(owner, analysis.kind, items.len);
        for (items, 0..) |item, idx| try out.set(idx, item);
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, analysis.flags);
        hostDenseSetCachedIntRange(host, analysis.range);
        return value;
    }

    fn createManagedHostIntArray(self: *Session, items: []const i64) !Value {
        return try self.createOwnedHostIntArray(.managed, items);
    }

    fn createOwnedHostBitArray(self: *Session, owner: HeapOwner, items: []const bool) !Value {
        var asc = true;
        var dsc = true;
        var saw_zero = items.len == 0;
        var saw_one = false;
        if (items.len != 0) {
            if (items[0]) saw_one = true else saw_zero = true;
            var prev = items[0];
            for (items[1..]) |item| {
                if (item) saw_one = true else saw_zero = true;
                if (@intFromBool(prev) > @intFromBool(item)) asc = false;
                if (@intFromBool(prev) < @intFromBool(item)) dsc = false;
                prev = item;
            }
        }

        var out = try self.allocOwnedHostIntResult(owner, .bit, items.len);
        for (items, 0..) |item, idx| try out.set(idx, @intFromBool(item));
        const value = out.value();
        const host = try mutableNumericHostArrayValue(self, value);
        hostDenseSetFlags(host, host_dense_flag_normalized | orderFlagsFromMonotonic(asc, dsc));
        hostDenseSetCachedIntRange(host, .{
            .min = if (saw_zero) 0 else 1,
            .max = if (saw_one) 1 else 0,
        });
        return value;
    }

    fn createManagedHostBitArray(self: *Session, items: []const bool) !Value {
        return try self.createOwnedHostBitArray(.managed, items);
    }

    fn createOwnedHostFloatArray(self: *Session, owner: HeapOwner, items: []const f64) !Value {
        const analysis = analyzeFloatSlice(items);
        const out = try self.allocOwnedHostFloatResult(owner, items.len);
        @memcpy(out.items, items);
        const value = out.value();
        hostDenseSetFlags(try mutableNumericHostArrayValue(self, value), analysis.flags);
        return value;
    }

