}

fn foldAddFloat32SlicePromotedMorsel(session: *Session, items: []const f32, seed: f64, workers_requested: usize) KError!f64 {
    if (items.len == 0) return seed;
    const grain = normalizeMorselGrain(items.len, default_morsel_grain);
    const morsel_count = countMorsels(items.len, grain);
    if (morsel_count == 0) return seed;
    const partials = try session.morselF64Partials(morsel_count);

    const Kernel = foldAddFloat32PromotedMorselKernel();
    session.runMorselRange(
        .{
            .len = items.len,
            .grain = grain,
            .workers_requested = workers_requested,
        },
        Kernel.Ctx{
            .items = items,
            .partials = partials,
            .grain = grain,
        },
        Kernel.run,
    ) catch return error.Internal;

    var total = seed;
    for (partials) |partial| total += partial;
    return total;
}

fn tryFoldAddFloatSliceMorsel(session: *Session, items: []const f64, seed: ?f64) KError!?f64 {
    const workers = session.morselWorkersForDenseReduction(items.len) orelse return null;
    return try foldAddFloatSliceMorsel(session, items, seed, workers);
}

fn tryFoldAddFloat32SliceMorsel(session: *Session, items: []const f32, seed: ?f32) KError!?f32 {
    const workers = session.morselWorkersForDenseReduction(items.len) orelse return null;
    return try foldAddFloat32SliceMorsel(session, items, seed, workers);
}

fn tryFoldAddFloat32SlicePromotedMorsel(session: *Session, items: []const f32, seed: f64) KError!?f64 {
    const workers = session.morselWorkersForDenseReduction(items.len) orelse return null;
    return try foldAddFloat32SlicePromotedMorsel(session, items, seed, workers);
}

const HostDenseIntArraySourceView = struct {
    array: *const HostDenseArray,
    view: HostIntArrayView,
};

fn fullFirstAxisSliceSourceIntView(view: HostFirstAxisSliceView) ?HostDenseIntArraySourceView {
    if (view.row_width != 1) return null;
    const array = view.source_host orelse return null;
    const source_view = hostIntArrayView(array) orelse return null;
    const source_len = hostIntArrayViewLen(source_view);
    if (view.len != source_len) return null;
    if (source_len == 0) return .{ .array = array, .view = source_view };

    const full_forward = view.row_step == 1 and view.start_row == 0;
    const full_reverse = view.row_step == -1 and view.start_row == source_len - 1;
    if (!full_forward and !full_reverse) return null;
    return .{ .array = array, .view = source_view };
}

fn fullFirstAxisSliceIntRange(view: HostFirstAxisSliceView) ?HostIntRange {
    const source = fullFirstAxisSliceSourceIntView(view) orelse return null;
    return hostDenseCachedIntRange(source.array) orelse
        hostIntArrayViewEndpointRange(source.view, source.array.flags) orelse
        hostIntArrayViewRange(source.view);
}

fn fullReverseFirstAxisSliceSourceHost(view: HostFirstAxisSliceView) ?*const HostDenseArray {
    if (view.row_width != 1) return null;
    const array = view.source_host orelse return null;
    if (view.len != array.logical_len) return null;
    if (array.logical_len == 0) return array;
    if (view.row_step != -1 or view.start_row != array.logical_len - 1) return null;
    return array;
}

fn fullReverseFirstAxisSliceSourceFloat64(view: HostFirstAxisSliceView) ?[]const f64 {
    const array = fullReverseFirstAxisSliceSourceHost(view) orelse return null;
    return switch (array.storage) {
        .float64 => |items| hostDenseLogicalItems(f64, array, items),
        else => null,
    };
}

fn fullReverseFirstAxisSliceSourceFloat32(view: HostFirstAxisSliceView) ?[]const f32 {
    const array = fullReverseFirstAxisSliceSourceHost(view) orelse return null;
    return switch (array.storage) {
        .float32 => |items| hostDenseLogicalItems(f32, array, items),
        else => null,
    };
}

fn fullReverseFirstAxisSliceSourceIntView(view: HostFirstAxisSliceView) ?HostIntArrayView {
    const array = fullReverseFirstAxisSliceSourceHost(view) orelse return null;
    return hostIntArrayView(array);
}

fn fullReverseIntDenseViewSource(view: HostIntDenseView) ?HostIntArrayView {
    if (view != .first_axis_slice) return null;
    return fullReverseFirstAxisSliceSourceIntView(view.first_axis_slice);
}

fn fullReverseFloatDenseViewSource64(view: HostFloatDenseView) ?[]const f64 {
    if (view != .first_axis_slice) return null;
    return fullReverseFirstAxisSliceSourceFloat64(view.first_axis_slice);
}

fn fullReverseFloatDenseViewSource32(view: HostFloatDenseView) ?[]const f32 {
    if (view != .first_axis_slice) return null;
    return fullReverseFirstAxisSliceSourceFloat32(view.first_axis_slice);
}

fn denseFloatViewMorselFoldSource64(view: HostFloatDenseView) ?[]const f64 {
    if (hostFloatDenseViewDirectFloat64Slice(view)) |source| return source;
    return fullReverseFloatDenseViewSource64(view);
}

fn denseFloatViewMorselFoldSource32(view: HostFloatDenseView) ?[]const f32 {
    if (hostFloatDenseViewDirectFloat32Slice(view)) |source| return source;
    return fullReverseFloatDenseViewSource32(view);
}

fn tryFoldAddFloatViewMorsel(session: *Session, view: HostFloatDenseView, seed: ?f64) KError!?f64 {
    const items = denseFloatViewMorselFoldSource64(view) orelse return null;
    return try tryFoldAddFloatSliceMorsel(session, items, seed);
}

fn tryFoldAddFloat32ViewMorsel(session: *Session, view: HostFloatDenseView, seed: ?f32) KError!?f32 {
    const items = denseFloatViewMorselFoldSource32(view) orelse return null;
    return try tryFoldAddFloat32SliceMorsel(session, items, seed);
}

fn hostAddFloatFoldUsesSimd(items: []const f64, seed: ?f64) bool {
    if (comptime !enable_dense_float_simd) return false;
    if (seed != null) return false;
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    return items.len >= lane_count * 4;
}

fn hostAddFloat32FoldUsesSimd(items: []const f32, seed: ?f32) bool {
    if (comptime !enable_dense_float_simd) return false;
    if (seed != null) return false;
    const lane_count = dense_host_simd_bytes / @sizeOf(f32);
    return items.len >= lane_count * 4;
}

fn foldAddFloatSliceScalar(items: []const f64, seed: ?f64) f64 {
    var total = seed orelse items[0];
    const start_idx: usize = if (seed == null) 1 else 0;
    for (items[start_idx..]) |item| total += item;
    return total;
}

fn foldAddFloatSliceVectorized(items: []const f64) f64 {
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    const Vec = @Vector(lane_count, f64);
    const step = lane_count * 4;
    var acc0: Vec = @splat(0);
    var acc1: Vec = @splat(0);
    var acc2: Vec = @splat(0);
    var acc3: Vec = @splat(0);
    var idx: usize = 0;
    while (idx + step <= items.len) : (idx += step) {
        const v0: Vec = items[idx..][0..lane_count].*;
        const v1: Vec = items[idx + lane_count ..][0..lane_count].*;
        const v2: Vec = items[idx + lane_count * 2 ..][0..lane_count].*;
        const v3: Vec = items[idx + lane_count * 3 ..][0..lane_count].*;
        acc0 += v0;
        acc1 += v1;
        acc2 += v2;
        acc3 += v3;
    }
    var acc = (acc0 + acc1) + (acc2 + acc3);
    while (idx + lane_count <= items.len) : (idx += lane_count) {
        const values: Vec = items[idx..][0..lane_count].*;
        acc += values;
    }
    var total = @reduce(.Add, acc);
    while (idx < items.len) : (idx += 1) total += items[idx];
    return total;
}

fn foldAddFloatSlice(items: []const f64, seed: ?f64) f64 {
    if (hostAddFloatFoldUsesSimd(items, seed)) return foldAddFloatSliceVectorized(items);
    return foldAddFloatSliceScalar(items, seed);
}

fn foldAddFloat32SliceScalar(items: []const f32, seed: ?f32) f32 {
    var total = seed orelse items[0];
    const start_idx: usize = if (seed == null) 1 else 0;
    for (items[start_idx..]) |item| total += item;
    return total;
}

