    var acc3: Vec = @splat(0);
    var idx: usize = 0;
    while (idx + step <= items.len) : (idx += step) {
        const v0: Vec = items[idx..][0..lane_count].*;
        const v1: Vec = items[idx + lane_count ..][0..lane_count].*;
        const v2: Vec = items[idx + lane_count * 2 ..][0..lane_count].*;
        const v3: Vec = items[idx + lane_count * 3 ..][0..lane_count].*;
        acc0 += v0;
        acc1 += v1;
        acc2 += v2;
        acc3 += v3;
    }
    var acc = (acc0 + acc1) + (acc2 + acc3);
    while (idx + lane_count <= items.len) : (idx += lane_count) {
        const values: Vec = items[idx..][0..lane_count].*;
        acc += values;
    }
    var total = @reduce(.Add, acc);
    while (idx < items.len) : (idx += 1) total += items[idx];
    return total;
}

fn foldAddFloat32Slice(items: []const f32, seed: ?f32) f32 {
    if (hostAddFloat32FoldUsesSimd(items, seed)) return foldAddFloat32SliceVectorized(items);
    return foldAddFloat32SliceScalar(items, seed);
}

fn foldAddFloat32SlicePromoted(items: []const f32, seed: f64) f64 {
    var total = seed;
    for (items) |item| total += @floatCast(item);
    return total;
}

fn foldSubFloatSlice(items: []const f64, seed: ?f64) f64 {
    var total = seed orelse items[0];
    const start_idx: usize = if (seed == null) 1 else 0;
    for (items[start_idx..]) |item| total -= item;
    return total;
}

fn foldSubFloat32Slice(items: []const f32, seed: ?f32) f32 {
    var total = seed orelse items[0];
    const start_idx: usize = if (seed == null) 1 else 0;
    for (items[start_idx..]) |item| total -= item;
    return total;
}

fn foldSubFloat32SlicePromoted(items: []const f32, seed: f64) f64 {
    var total = seed;
    for (items) |item| total -= @floatCast(item);
    return total;
}

fn foldMulFloatSlice(items: []const f64, seed: ?f64) f64 {
    var total = seed orelse items[0];
    const start_idx: usize = if (seed == null) 1 else 0;
    for (items[start_idx..]) |item| total *= item;
    return total;
