fn foldAddIntDenseView(view: HostIntDenseView, seed: ?i64) KError!i64 {
    if (hostIntDenseViewContiguousArrayView(view)) |source| return try foldAddIntViewMaybeUnchecked(source, null, seed);
    var total = seed orelse try hostIntDenseViewItem(view, 0);
    const start_idx: usize = if (seed == null) 1 else 0;
    for (start_idx..hostIntDenseViewLen(view)) |idx| try checkedAddAcc(&total, try hostIntDenseViewItem(view, idx));
    return total;
}

fn foldAddFloatView(view: HostFloatDenseView, seed: ?f64) KError!f64 {
    if (hostFloatDenseViewDirectFloat64Slice(view)) |source| return foldAddFloatSlice(source, seed);
    if (fullReverseFloatDenseViewSource64(view)) |source| return foldAddFloatSlice(source, seed);
    var total = seed orelse try hostFloatDenseViewItem(view, 0);
    const start_idx: usize = if (seed == null) 1 else 0;
    for (start_idx..hostFloatDenseViewLen(view)) |idx| total += try hostFloatDenseViewItem(view, idx);
    return total;
}

fn foldAddFloat32View(view: HostFloatDenseView, seed: ?f32) KError!f32 {
    if (hostFloatDenseViewDirectFloat32Slice(view)) |source| return foldAddFloat32Slice(source, seed);
    if (fullReverseFloatDenseViewSource32(view)) |source| return foldAddFloat32Slice(source, seed);
    var total = seed orelse @as(f32, @floatCast(try hostFloatDenseViewItem(view, 0)));
    const start_idx: usize = if (seed == null) 1 else 0;
    for (start_idx..hostFloatDenseViewLen(view)) |idx| total += @floatCast(try hostFloatDenseViewItem(view, idx));
    return total;
}

fn foldAddFloatIntDenseView(view: HostIntDenseView, seed: f64) KError!f64 {
    var total = seed;
    for (0..hostIntDenseViewLen(view)) |idx| total += @floatFromInt(try hostIntDenseViewItem(view, idx));
    return total;
}

fn foldAddFloatIntView(view: HostIntArrayView, seed: f64) f64 {
    var total = seed;
    switch (view) {
        .bit => |items| {
            total += @floatFromInt(bitCountTrue(items));
        },
        .int8 => |items| for (items) |item| {
            total += @floatFromInt(item);
        },
        .int16 => |items| for (items) |item| {
            total += @floatFromInt(item);
        },
        .int32 => |items| for (items) |item| {
            total += @floatFromInt(item);
        },
        .int64 => |items| for (items) |item| {
            total += @floatFromInt(item);
        },
    }
    return total;
}

const HostFloatBounds = struct {
    min: f64,
    max: f64,
};

fn hostFloatSliceBoundsScalar(items: []const f64) HostFloatBounds {
    var min_value = items[0];
    var max_value = items[0];
    for (items[1..]) |item| {
        min_value = @min(min_value, item);
        max_value = @max(max_value, item);
    }
    return .{ .min = min_value, .max = max_value };
}

fn hostFloatSliceBoundsZigVectorized(items: []const f64) HostFloatBounds {
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    if (items.len < lane_count * 4) return hostFloatSliceBoundsScalar(items);

    const Vec = @Vector(lane_count, f64);
    var min_vec: Vec = items[0..lane_count].*;
    var max_vec = min_vec;
    var idx: usize = lane_count;
    const vector_limit = items.len - (items.len % lane_count);
    while (idx < vector_limit) : (idx += lane_count) {
        const values: Vec = items[idx..][0..lane_count].*;
        min_vec = @min(min_vec, values);
        max_vec = @max(max_vec, values);
    }

    var min_value = @reduce(.Min, min_vec);
    var max_value = @reduce(.Max, max_vec);
    while (idx < items.len) : (idx += 1) {
        min_value = @min(min_value, items[idx]);
        max_value = @max(max_value, items[idx]);
    }
    return .{ .min = min_value, .max = max_value };
}

fn hostFloatSliceBounds(items: []const f64) HostFloatBounds {
    if (comptime enable_dense_float_simd) {
        return hostFloatSliceBoundsZigVectorized(items);
    }
    return hostFloatSliceBoundsScalar(items);
}

fn hostFloatDenseViewBounds(view: HostFloatDenseView) KError!HostFloatBounds {
    return switch (view) {
        .dense => |items| hostFloatSliceBounds(items),
        else => blk: {
            const len = hostFloatDenseViewLen(view);
            var min_value = try hostFloatDenseViewItem(view, 0);
            var max_value = min_value;
            for (1..len) |idx| {
                const item = try hostFloatDenseViewItem(view, idx);
                min_value = @min(min_value, item);
                max_value = @max(max_value, item);
            }
            break :blk .{ .min = min_value, .max = max_value };
        },
    };
}

fn combineHostIntRanges(partials: []const HostIntRange) HostIntRange {
    std.debug.assert(partials.len > 0);
    var bounds = partials[0];
    for (partials[1..]) |partial| {
        bounds.min = @min(bounds.min, partial.min);
        bounds.max = @max(bounds.max, partial.max);
    }
    return bounds;
}

fn hostIntRangeMorselKernel(comptime T: type) type {
    return struct {
        const Ctx = struct {
            items: []const T,
            partials: []HostIntRange,
            grain: usize,
        };

        fn run(ctx: Ctx, range: MorselRange) void {
            const partial_idx = range.start / ctx.grain;
            ctx.partials[partial_idx] = hostIntSliceRange(T, ctx.items[range.start..range.end]);
        }
    };
}

fn hostIntSliceRangeMorsel(session: *Session, comptime T: type, items: []const T, workers_requested: usize) KError!HostIntRange {
    const grain = normalizeMorselGrain(items.len, default_morsel_grain);
    const morsel_count = countMorsels(items.len, grain);
    if (morsel_count == 0) return .{ .min = 0, .max = 0 };
    const partials = try session.morselIntRangePartials(morsel_count);

    const Kernel = hostIntRangeMorselKernel(T);
    session.runMorselRange(
        .{
            .len = items.len,
            .grain = grain,
            .workers_requested = workers_requested,
        },
        Kernel.Ctx{
            .items = items,
            .partials = partials,
            .grain = grain,
        },
        Kernel.run,
    ) catch return error.Internal;

    return combineHostIntRanges(partials);
}

fn tryHostIntDenseViewRangeMorsel(session: *Session, view: HostIntDenseView) KError!?HostIntRange {
    const source = switch (view) {
        .dense => |items| items,
        else => fullReverseIntDenseViewSource(view) orelse return null,
    };
    const len = hostIntArrayViewLen(source);
    const workers = session.morselWorkersForDenseReduction(len) orelse return null;
    return switch (source) {
        .bit => null,
        .int8 => |items| try hostIntSliceRangeMorsel(session, i8, items, workers),
        .int16 => |items| try hostIntSliceRangeMorsel(session, i16, items, workers),
        .int32 => |items| try hostIntSliceRangeMorsel(session, i32, items, workers),
        .int64 => |items| try hostIntSliceRangeMorsel(session, i64, items, workers),
    };
}

fn combineHostFloatBounds(partials: []const HostFloatBounds) HostFloatBounds {
    std.debug.assert(partials.len > 0);
    var bounds = partials[0];
    for (partials[1..]) |partial| {
        bounds.min = @min(bounds.min, partial.min);
        bounds.max = @max(bounds.max, partial.max);
    }
    return bounds;
}

fn hostFloat32SliceBoundsScalar(items: []const f32) HostFloatBounds {
    var min_value = items[0];
    var max_value = items[0];
    for (items[1..]) |item| {
        min_value = @min(min_value, item);
        max_value = @max(max_value, item);
    }
    return .{
        .min = @floatCast(min_value),
        .max = @floatCast(max_value),
    };
}

fn hostFloat32SliceBoundsZigVectorized(items: []const f32) HostFloatBounds {
    const lane_count = dense_host_simd_bytes / @sizeOf(f32);
    if (items.len < lane_count * 4) return hostFloat32SliceBoundsScalar(items);

    const Vec = @Vector(lane_count, f32);
    var min_vec: Vec = items[0..lane_count].*;
    var max_vec = min_vec;
    var idx: usize = lane_count;
    const vector_limit = items.len - (items.len % lane_count);
    while (idx < vector_limit) : (idx += lane_count) {
        const values: Vec = items[idx..][0..lane_count].*;
        min_vec = @min(min_vec, values);
        max_vec = @max(max_vec, values);
    }

    var min_value = @reduce(.Min, min_vec);
    var max_value = @reduce(.Max, max_vec);
    while (idx < items.len) : (idx += 1) {
        min_value = @min(min_value, items[idx]);
        max_value = @max(max_value, items[idx]);
    }
    return .{
        .min = @floatCast(min_value),
        .max = @floatCast(max_value),
    };
}

fn hostFloat32SliceBounds(items: []const f32) HostFloatBounds {
    if (comptime enable_dense_float_simd) {
        return hostFloat32SliceBoundsZigVectorized(items);
    }
    return hostFloat32SliceBoundsScalar(items);
}

fn hostFloatBoundsMorselKernel(comptime T: type) type {
    return struct {
        const Ctx = struct {
            items: []const T,
            partials: []HostFloatBounds,
            grain: usize,
        };

        fn run(ctx: Ctx, range: MorselRange) void {
            const partial_idx = range.start / ctx.grain;
            ctx.partials[partial_idx] = if (comptime T == f64)
                hostFloatSliceBounds(ctx.items[range.start..range.end])
            else
                hostFloat32SliceBounds(ctx.items[range.start..range.end]);
        }
    };
}

fn hostFloatSliceBoundsMorsel(session: *Session, comptime T: type, items: []const T, workers_requested: usize) KError!HostFloatBounds {
    const grain = normalizeMorselGrain(items.len, default_morsel_grain);
    const morsel_count = countMorsels(items.len, grain);
    if (morsel_count == 0) return .{ .min = 0.0, .max = 0.0 };
    const partials = try session.morselFloatBoundsPartials(morsel_count);

    const Kernel = hostFloatBoundsMorselKernel(T);
    session.runMorselRange(
        .{
            .len = items.len,
            .grain = grain,
            .workers_requested = workers_requested,
        },
        Kernel.Ctx{
            .items = items,
            .partials = partials,
            .grain = grain,
        },
        Kernel.run,
    ) catch return error.Internal;

    return combineHostFloatBounds(partials);
}

fn tryHostFloatDenseViewBoundsMorsel(session: *Session, view: HostFloatDenseView) KError!?HostFloatBounds {
    if (denseFloatViewMorselFoldSource64(view)) |items| {
        const workers = session.morselWorkersForDenseReduction(items.len) orelse return null;
        return try hostFloatSliceBoundsMorsel(session, f64, items, workers);
    }
    if (denseFloatViewMorselFoldSource32(view)) |items| {
        const workers = session.morselWorkersForDenseReduction(items.len) orelse return null;
        return try hostFloatSliceBoundsMorsel(session, f32, items, workers);
    }
    return null;
}

fn analyzeAddScanIntView(view: HostIntArrayView, seed: ?i64) KError!HostAddScanIntAnalysis {
    const len = hostIntArrayViewLen(view);
    std.debug.assert(len > 1);

    const first_item = hostIntViewItem(view, 0);
    var item_min = first_item;
    var item_max = first_item;
    var acc = if (seed) |seed_value|
        try checkedIntOp(.add, seed_value, first_item)
    else
        first_item;
    var min_value = acc;
    var max_value = acc;

    for (1..len) |idx| {
        const item = hostIntViewItem(view, idx);
        item_min = @min(item_min, item);
        item_max = @max(item_max, item);
        try checkedAddAcc(&acc, item);
        min_value = @min(min_value, acc);
        max_value = @max(max_value, acc);
    }

    const input_range: HostIntRange = .{ .min = item_min, .max = item_max };
    return .{
        .range = .{ .min = min_value, .max = max_value },
        .kind = hostIntStorageKindForRange(min_value, max_value),
        .flags = addScanIntFlags(input_range),
    };
}

fn analyzeAddScanIntDenseView(view: HostIntDenseView, seed: ?i64) KError!HostAddScanIntAnalysis {
    if (view == .dense) return analyzeAddScanIntView(view.dense, seed);

    const len = hostIntDenseViewLen(view);
    std.debug.assert(len > 1);

    const first_item = try hostIntDenseViewItem(view, 0);
    var item_min = first_item;
    var item_max = first_item;
    var acc = if (seed) |seed_value|
        try checkedIntOp(.add, seed_value, first_item)
    else
        first_item;
    var min_value = acc;
    var max_value = acc;

    for (1..len) |idx| {
        const item = try hostIntDenseViewItem(view, idx);
        item_min = @min(item_min, item);
        item_max = @max(item_max, item);
        try checkedAddAcc(&acc, item);
        min_value = @min(min_value, acc);
        max_value = @max(max_value, acc);
    }

    const input_range: HostIntRange = .{ .min = item_min, .max = item_max };
    return .{
        .range = .{ .min = min_value, .max = max_value },
        .kind = hostIntStorageKindForRange(min_value, max_value),
        .flags = addScanIntFlags(input_range),
    };
}

fn hostIntDenseViewBitSlice(view: HostIntDenseView) ?HostBitSlice {
    return switch (view) {
        .dense => |items| switch (items) {
            .bit => |bits| bits,
            else => null,
        },
        else => null,
    };
}

fn bitMinMaxScanResultIsBit(op: BuiltinId, seed: i64) bool {
    return switch (op) {
        .minimum => seed >= 0,
        .maximum => seed <= 1,
        else => false,
    };
}

fn minMaxScanIntOp(op: BuiltinId, left: i64, right: i64) i64 {
    return switch (op) {
        .minimum => @min(left, right),
        .maximum => @max(left, right),
        else => unreachable,
    };
}

fn minMaxScanFloatOp(op: BuiltinId, left: f64, right: f64) f64 {
    return switch (op) {
        .minimum => @min(left, right),
        .maximum => @max(left, right),
        else => unreachable,
    };
}

fn minMaxScanFloat32Op(op: BuiltinId, left: f32, right: f32) f32 {
    return switch (op) {
        .minimum => @min(left, right),
        .maximum => @max(left, right),
        else => unreachable,
    };
}

fn writeMinMaxScanIntValue(comptime OutT: type, out: []OutT, idx: usize, value: i64) KError!void {
    out[idx] = std.math.cast(OutT, value) orelse return error.Unsupported;
}

fn fillMinMaxScanIntTail(comptime OutT: type, out: []OutT, start_idx: usize, value: i64) KError!void {
    if (start_idx >= out.len) return;
    const casted = std.math.cast(OutT, value) orelse return error.Unsupported;
    @memset(out[start_idx..], casted);
}

fn fillMinMaxScanIntItemsTo(comptime OutT: type, comptime InT: type, out: []OutT, items: []const InT, op: BuiltinId, seed: ?i64, terminal: i64) KError!void {
    std.debug.assert(out.len == items.len);
    std.debug.assert(out.len > 0);

    var acc: i64 = undefined;
    const start_idx: usize = if (seed) |seed_value| blk: {
        acc = seed_value;
        break :blk 0;
    } else blk: {
        acc = @intCast(items[0]);
        try writeMinMaxScanIntValue(OutT, out, 0, acc);
        if (acc == terminal) {
            try fillMinMaxScanIntTail(OutT, out, 1, acc);
            return;
        }
        break :blk 1;
    };

    for (items[start_idx..], start_idx..) |item, idx| {
        acc = minMaxScanIntOp(op, acc, @intCast(item));
        try writeMinMaxScanIntValue(OutT, out, idx, acc);
        if (acc == terminal) {
            try fillMinMaxScanIntTail(OutT, out, idx + 1, acc);
            return;
        }
    }
}

fn fillMinMaxScanIntBitItemsTo(comptime OutT: type, out: []OutT, items: HostBitSlice, op: BuiltinId, seed: ?i64, terminal: i64) KError!void {
    std.debug.assert(out.len == items.len);
    std.debug.assert(out.len > 0);

    var acc: i64 = undefined;
    var out_idx: usize = 0;
    if (seed) |seed_value| {
        acc = seed_value;
    } else {
        acc = @intFromBool(bitGet(items.words, 0));
        try writeMinMaxScanIntValue(OutT, out, 0, acc);
        if (acc == terminal) {
            try fillMinMaxScanIntTail(OutT, out, 1, acc);
            return;
        }
        out_idx = 1;
    }

    while (out_idx < out.len) : (out_idx += 1) {
        acc = minMaxScanIntOp(op, acc, @intFromBool(bitGet(items.words, out_idx)));
        try writeMinMaxScanIntValue(OutT, out, out_idx, acc);
        if (acc == terminal) {
            try fillMinMaxScanIntTail(OutT, out, out_idx + 1, acc);
            return;
        }
    }
}

fn fillMinMaxScanIntViewTo(comptime OutT: type, out: []OutT, view: HostIntDenseView, op: BuiltinId, seed: ?i64, terminal: i64) KError!void {
    std.debug.assert(out.len == hostIntDenseViewLen(view));
    std.debug.assert(out.len > 0);

    var acc: i64 = undefined;
    const start_idx: usize = if (seed) |seed_value| blk: {
        acc = seed_value;
        break :blk 0;
    } else blk: {
        acc = try hostIntDenseViewItem(view, 0);
        try writeMinMaxScanIntValue(OutT, out, 0, acc);
        if (acc == terminal) {
            try fillMinMaxScanIntTail(OutT, out, 1, acc);
            return;
        }
        break :blk 1;
    };

    for (start_idx..out.len) |idx| {
        acc = minMaxScanIntOp(op, acc, try hostIntDenseViewItem(view, idx));
        try writeMinMaxScanIntValue(OutT, out, idx, acc);
        if (acc == terminal) {
            try fillMinMaxScanIntTail(OutT, out, idx + 1, acc);
            return;
        }
    }
}

fn fillMinMaxScanIntTypedResult(comptime OutT: type, out: []OutT, view: HostIntDenseView, op: BuiltinId, seed: ?i64, terminal: i64) KError!void {
    switch (view) {
        .dense => |items| switch (items) {
            .bit => |bits| try fillMinMaxScanIntBitItemsTo(OutT, out, bits, op, seed, terminal),
            .int8 => |items_slice| try fillMinMaxScanIntItemsTo(OutT, i8, out, items_slice, op, seed, terminal),
            .int16 => |items_slice| try fillMinMaxScanIntItemsTo(OutT, i16, out, items_slice, op, seed, terminal),
            .int32 => |items_slice| try fillMinMaxScanIntItemsTo(OutT, i32, out, items_slice, op, seed, terminal),
            .int64 => |items_slice| try fillMinMaxScanIntItemsTo(OutT, i64, out, items_slice, op, seed, terminal),
        },
        else => try fillMinMaxScanIntViewTo(OutT, out, view, op, seed, terminal),
    }
}

fn scanIntBitValue(value: i64) KError!bool {
    return switch (value) {
        0 => false,
        1 => true,
        else => error.Unsupported,
    };
}

fn fillMinMaxScanIntBitTail(out: HostBitAlloc, start_idx: usize, value: i64) KError!void {
    if (start_idx >= out.len) return;
    bitFillRange(out.words, start_idx, out.len - start_idx, try scanIntBitValue(value));
}

fn fillMinMaxScanIntBitOutput(out: HostBitAlloc, view: HostIntDenseView, op: BuiltinId, seed: ?i64, terminal: i64) KError!void {
    std.debug.assert(out.len == hostIntDenseViewLen(view));
    std.debug.assert(out.len > 0);

    var acc: i64 = undefined;
    const start_idx: usize = if (seed) |seed_value| blk: {
        acc = seed_value;
        break :blk 0;
    } else blk: {
        acc = try hostIntDenseViewItem(view, 0);
        bitSet(out.words, 0, try scanIntBitValue(acc));
        if (acc == terminal) {
            try fillMinMaxScanIntBitTail(out, 1, acc);
            return;
        }
        break :blk 1;
    };

    for (start_idx..out.len) |idx| {
        acc = minMaxScanIntOp(op, acc, try hostIntDenseViewItem(view, idx));
        bitSet(out.words, idx, try scanIntBitValue(acc));
        if (acc == terminal) {
            try fillMinMaxScanIntBitTail(out, idx + 1, acc);
            return;
        }
    }
}

fn fillMinMaxScanIntResult(out: *HostIntResult, view: HostIntDenseView, op: BuiltinId, seed: ?i64, terminal: i64) KError!void {
    switch (out.*) {
        .bit => |dest| try fillMinMaxScanIntBitOutput(dest, view, op, seed, terminal),
        .int8 => |*dest| try fillMinMaxScanIntTypedResult(i8, dest.items, view, op, seed, terminal),
        .int16 => |*dest| try fillMinMaxScanIntTypedResult(i16, dest.items, view, op, seed, terminal),
        .int32 => |*dest| try fillMinMaxScanIntTypedResult(i32, dest.items, view, op, seed, terminal),
        .int64 => |*dest| try fillMinMaxScanIntTypedResult(i64, dest.items, view, op, seed, terminal),
    }
}

fn fillMinMaxScanFloatFromInt(out: []f64, view: HostIntDenseView, op: BuiltinId, seed: f64) KError!void {
    std.debug.assert(out.len == hostIntDenseViewLen(view));
    var acc = seed;
    for (0..out.len) |idx| {
        acc = minMaxScanFloatOp(op, acc, @floatFromInt(try hostIntDenseViewItem(view, idx)));
        out[idx] = acc;
    }
}

fn fillMinMaxScanFloatSlice(out: []f64, items: []const f64, op: BuiltinId, seed: ?f64) void {
    std.debug.assert(out.len == items.len);
    std.debug.assert(out.len > 0);

    var acc: f64 = undefined;
    const start_idx: usize = if (seed) |seed_value| blk: {
        acc = seed_value;
        break :blk 0;
    } else blk: {
        acc = items[0];
        out[0] = acc;
        break :blk 1;
    };

    for (items[start_idx..], start_idx..) |item, idx| {
        acc = minMaxScanFloatOp(op, acc, item);
        out[idx] = acc;
    }
}

fn fillMinMaxScanFloat(out: []f64, view: HostFloatDenseView, op: BuiltinId, seed: ?f64) KError!void {
    std.debug.assert(out.len == hostFloatDenseViewLen(view));
    std.debug.assert(out.len > 0);

    switch (view) {
        .dense => |items| {
            fillMinMaxScanFloatSlice(out, items, op, seed);
            return;
        },
        else => {},
    }

    var acc: f64 = undefined;
    const start_idx: usize = if (seed) |seed_value| blk: {
        acc = seed_value;
        break :blk 0;
    } else blk: {
        acc = try hostFloatDenseViewItem(view, 0);
        out[0] = acc;
        break :blk 1;
    };

    for (start_idx..out.len) |idx| {
        acc = minMaxScanFloatOp(op, acc, try hostFloatDenseViewItem(view, idx));
        out[idx] = acc;
    }
}

fn hostFloatDenseViewDirectFloat64Slice(view: HostFloatDenseView) ?[]const f64 {
    return switch (view) {
        .dense => |items| items,
        .flat_slice => |slice| blk: {
            const array = slice.source_host orelse break :blk null;
            break :blk switch (array.storage) {
                .float64 => |items| items_blk: {
                    const logical_items = hostDenseLogicalItems(f64, array, items);
                    if (slice.start > logical_items.len or slice.len > logical_items.len - slice.start) break :items_blk null;
                    break :items_blk logical_items[slice.start..][0..slice.len];
                },
                else => null,
            };
        },
        else => null,
    };
}

fn hostFloatDenseViewDirectFloat32Slice(view: HostFloatDenseView) ?[]const f32 {
    if (view != .flat_slice) return null;
    const slice = view.flat_slice;
    const array = slice.source_host orelse return null;
    return switch (array.storage) {
        .float32 => |items| blk: {
            const logical_items = hostDenseLogicalItems(f32, array, items);
            if (slice.start > logical_items.len or slice.len > logical_items.len - slice.start) return null;
            break :blk logical_items[slice.start..][0..slice.len];
        },
        else => null,
    };
}

fn fillMinMaxScanFloat32Slice(out: []f32, items: []const f32, op: BuiltinId, seed: ?f32) void {
    std.debug.assert(out.len == items.len);
    std.debug.assert(out.len > 0);

    var acc: f32 = undefined;
    const start_idx: usize = if (seed) |seed_value| blk: {
        acc = seed_value;
        break :blk 0;
    } else blk: {
        acc = items[0];
        out[0] = acc;
        break :blk 1;
    };

    for (items[start_idx..], start_idx..) |item, idx| {
        acc = minMaxScanFloat32Op(op, acc, item);
        out[idx] = acc;
    }
}

fn fillMinMaxScanFloat32(out: []f32, view: HostFloatDenseView, op: BuiltinId, seed: ?f32) KError!void {
    std.debug.assert(out.len == hostFloatDenseViewLen(view));
    std.debug.assert(out.len > 0);

    if (hostFloatDenseViewDirectFloat32Slice(view)) |items| {
        fillMinMaxScanFloat32Slice(out, items, op, seed);
        return;
    }

    var acc: f32 = undefined;
    const start_idx: usize = if (seed) |seed_value| blk: {
        acc = seed_value;
        break :blk 0;
    } else blk: {
        acc = @floatCast(try hostFloatDenseViewItem(view, 0));
        out[0] = acc;
        break :blk 1;
    };

    for (start_idx..out.len) |idx| {
        acc = minMaxScanFloat32Op(op, acc, @floatCast(try hostFloatDenseViewItem(view, idx)));
        out[idx] = acc;
    }
}

fn minMaxScanInitialBit(op: BuiltinId) bool {
    return switch (op) {
        .minimum => true,
        .maximum => false,
        else => unreachable,
    };
}

fn minMaxScanBitOp(op: BuiltinId, left: bool, right: bool) bool {
    return switch (op) {
        .minimum => left and right,
        .maximum => left or right,
        else => unreachable,
    };
}

fn fillFirstAxisBitMinMaxScan(out: []u64, bits: HostBitSlice, op: BuiltinId, block_len: usize, outer_len: usize) BitDenseMetadata {
    std.debug.assert(bits.len == block_len * outer_len);
    bitFill(out, bits.len, false);
    var stats = BitSequenceStats{};
    for (0..block_len) |inner_idx| {
        var acc = minMaxScanInitialBit(op);
        for (0..outer_len) |outer_idx| {
            const idx = outer_idx * block_len + inner_idx;
            acc = minMaxScanBitOp(op, acc, bitGet(bits.words, idx));
            bitSet(out, idx, acc);
            stats.note(acc);
        }
    }
    return stats.metadata();
}

fn fillFirstAxisBitLikeMinMaxScan(out: []u64, view: HostIntDenseView, op: BuiltinId, block_len: usize, outer_len: usize) KError!BitDenseMetadata {
    std.debug.assert(hostIntDenseViewLen(view) == block_len * outer_len);
    bitFill(out, hostIntDenseViewLen(view), false);
    var stats = BitSequenceStats{};
    for (0..block_len) |inner_idx| {
        var acc = minMaxScanInitialBit(op);
        for (0..outer_len) |outer_idx| {
            const idx = outer_idx * block_len + inner_idx;
            acc = minMaxScanBitOp(op, acc, try hostIntDenseViewItem(view, idx) != 0);
            bitSet(out, idx, acc);
            stats.note(acc);
        }
    }
    return stats.metadata();
}

fn fillRowBitMinMaxScan(out: []u64, bits: HostBitSlice, op: BuiltinId, rows: usize, cols: usize) BitDenseMetadata {
    std.debug.assert(bits.len == rows * cols);
    bitFill(out, bits.len, false);
    var stats = BitSequenceStats{};
    for (0..rows) |row_idx| {
        var acc = minMaxScanInitialBit(op);
        const row_base = row_idx * cols;
        for (0..cols) |col_idx| {
            const idx = row_base + col_idx;
            acc = minMaxScanBitOp(op, acc, bitGet(bits.words, idx));
            bitSet(out, idx, acc);
            stats.note(acc);
        }
    }
    return stats.metadata();
}

fn fillRowMinMaxScanInt(out: *HostIntResult, view: HostIntDenseView, op: BuiltinId, rows: usize, cols: usize) KError!void {
    std.debug.assert(hostIntDenseViewLen(view) == rows * cols);
    for (0..rows) |row_idx| {
        const row_base = row_idx * cols;
        var acc = try hostIntDenseViewItem(view, row_base);
        try out.set(row_base, acc);
        for (1..cols) |col_idx| {
            const idx = row_base + col_idx;
            acc = minMaxScanIntOp(op, acc, try hostIntDenseViewItem(view, idx));
            try out.set(idx, acc);
        }
    }
}

