fn fillAddScanFloat32View(out: []f32, view: HostFloatDenseView, seed: ?f32) KError!u8 {
    var acc = seed orelse @as(f32, @floatCast(try hostFloatDenseViewItem(view, 0)));
    var asc = true;
    var dsc = true;
    const start_idx: usize = if (seed == null) 1 else 0;
    if (seed == null) {
        noteAddScanFloatItem(acc, &asc, &dsc);
