fn fillAddScanFloat32SlicePromoted(out: []f64, items: []const f32, seed: f64, start_idx: usize) u8 {
    var acc = seed;
    var asc = true;
    var dsc = true;
    if (start_idx == 1) {
        noteAddScanFloatItem(items[0], &asc, &dsc);
        out[0] = acc;
    }
    for (items[start_idx..], start_idx..) |item, idx| {
        noteAddScanFloatItem(item, &asc, &dsc);
        acc += @floatCast(item);
        out[idx] = acc;
    }
    return addScanFloatFlagsFromOrder(asc, dsc);
