fn fillAddScanFloatBitView(out: []f64, items: HostBitSlice, seed: f64) void {
    var acc = seed;
    var out_idx: usize = 0;
    for (items.words, 0..) |_, word_idx| {
        var bits = bitWordMasked(items.words, items.len, word_idx);
        const active = bitWordActiveLen(items.len, word_idx, items.words.len);
        var bit_idx: usize = 0;
        while (bit_idx < active) : (bit_idx += 1) {
            acc += @floatFromInt(bits & 1);
            out[out_idx] = acc;
            bits >>= 1;
            out_idx += 1;
        }
    }
}

fn fillAddScanFloatIntTo(comptime InT: type, out: []f64, items: []const InT, seed: f64) void {
    var acc = seed;
    for (items, 0..) |item, idx| {
        acc += @floatFromInt(item);
        out[idx] = acc;
    }
}

fn fillAddScanFloatIntView(out: []f64, view: HostIntArrayView, seed: f64) void {
    switch (view) {
        .bit => |items| fillAddScanFloatBitView(out, items, seed),
        .int8 => |items| fillAddScanFloatIntTo(i8, out, items, seed),
        .int16 => |items| fillAddScanFloatIntTo(i16, out, items, seed),
        .int32 => |items| fillAddScanFloatIntTo(i32, out, items, seed),
        .int64 => |items| fillAddScanFloatIntTo(i64, out, items, seed),
    }
}

fn fillAddScanFloatIntDenseView(out: []f64, view: HostIntDenseView, seed: f64) KError!void {
    if (view == .dense) {
        fillAddScanFloatIntView(out, view.dense, seed);
        return;
    }
    var acc = seed;
    for (0..out.len) |idx| {
        acc += @floatFromInt(try hostIntDenseViewItem(view, idx));
        out[idx] = acc;
    }
}

fn castDenseInt(comptime T: type, value: anytype) T {
    return @as(T, @intCast(value));
}

fn castCheckedDenseInt(comptime T: type, value: i64) KError!T {
    return std.math.cast(T, value) orelse return error.Unsupported;
}

fn applyIntOpUncheckedTyped(comptime T: type, op: BuiltinId, left: anytype, right: anytype) T {
    const lhs: T = castDenseInt(T, left);
    const rhs: T = castDenseInt(T, right);
    return switch (op) {
        .add => lhs + rhs,
        .sub => lhs - rhs,
        .iota => castDenseInt(T, bangIntOp(@as(i64, @intCast(lhs)), @as(i64, @intCast(rhs)))),
        .minimum => @min(lhs, rhs),
        .maximum => @max(lhs, rhs),
        .mul => lhs * rhs,
        .pow => castDenseInt(T, @as(i64, @intFromFloat(@trunc(std.math.pow(f64, @floatFromInt(lhs), @floatFromInt(rhs)))))),
        .div => unreachable,
        else => unreachable,
    };
}

fn WiderDenseInt(comptime T: type) type {
    return switch (T) {
        i8 => i16,
        i16 => i32,
        i32 => i64,
        i64 => i64,
        else => @compileError("unsupported dense int type"),
    };
}

fn applyIntOpCheckedNarrow(comptime OutT: type, op: BuiltinId, left: anytype, right: anytype) KError!OutT {
    if (OutT == i64) {
        return castDenseInt(OutT, try checkedIntOp(op, @as(i64, @intCast(left)), @as(i64, @intCast(right))));
    }

    const WideT = WiderDenseInt(OutT);
    const lhs: WideT = castDenseInt(WideT, left);
    const rhs: WideT = castDenseInt(WideT, right);
    const result: WideT = switch (op) {
        .add => lhs + rhs,
        .sub => lhs - rhs,
        .iota => return castCheckedDenseInt(OutT, bangIntOp(@as(i64, @intCast(lhs)), @as(i64, @intCast(rhs)))),
        .mul => lhs * rhs,
        .div => unreachable,
        else => unreachable,
    };
    return std.math.cast(OutT, result) orelse error.Unsupported;
}

fn applyIntOpCheckedCast(comptime OutT: type, op: BuiltinId, left: i64, right: i64) KError!OutT {
    return castCheckedDenseInt(OutT, try checkedIntOp(op, left, right));
}

fn negateCheckedCast(comptime OutT: type, value: i64) KError!OutT {
    return castCheckedDenseInt(OutT, try checkedIntOp(.sub, 0, value));
}

fn toDenseFloat(value: anytype) f64 {
    return switch (@typeInfo(@TypeOf(value))) {
        .float, .comptime_float => value,
        .int, .comptime_int => @floatFromInt(value),
        else => @compileError("unsupported dense numeric type"),
    };
}

const dense_host_simd_bytes = 32;
const enable_dense_float_simd = true;
const enable_packed_bit_simd = true;
const enable_string_byte_simd = true;
const enable_mixed_bit_float_simd = true;
const enable_dense_int_simd = true;
const enable_dense_dyad_i8_mul_wasm_vectorized =
    zig_builtin.target.cpu.arch == .wasm32 and std.Target.wasm.featureSetHas(zig_builtin.target.cpu.features, .simd128);
const dense_i8_mul_wasm_lanes = 16;
const dense_i8_mul_wasm_half_lanes = 8;
const DenseI8MulWasmVec = @Vector(dense_i8_mul_wasm_lanes, i8);
const DenseI8MulWasmHalfVec = @Vector(dense_i8_mul_wasm_half_lanes, i8);
const DenseI8MulWasmWideVec = @Vector(dense_i8_mul_wasm_half_lanes, i16);
const dense_i8_mul_wasm_lo_shuffle: @Vector(dense_i8_mul_wasm_half_lanes, i32) = .{ 0, 1, 2, 3, 4, 5, 6, 7 };
const dense_i8_mul_wasm_hi_shuffle: @Vector(dense_i8_mul_wasm_half_lanes, i32) = .{ 8, 9, 10, 11, 12, 13, 14, 15 };

fn denseFloatSimdSupported(op: BuiltinId) bool {
    return switch (op) {
        .add, .sub, .minimum, .maximum, .mul, .div => true,
        else => false,
    };
}

fn denseFloatUnarySimdSupported(op: BuiltinId) bool {
    return switch (op) {
        .add, .sub, .div => true,
        else => false,
    };
}

fn denseCompareSupported(op: BuiltinId) bool {
    return switch (op) {
        .less, .more, .equal => true,
        else => false,
    };
}

fn denseIntSimdSupported(op: BuiltinId) bool {
    return switch (op) {
        .add, .sub, .minimum, .maximum, .mul => true,
        else => false,
    };
}

fn denseFloatBinaryVec(comptime op: BuiltinId, lhs: anytype, rhs: @TypeOf(lhs)) @TypeOf(lhs) {
    return switch (op) {
        .add => lhs + rhs,
        .sub => lhs - rhs,
        .minimum => @min(lhs, rhs),
        .maximum => @max(lhs, rhs),
        .mul => lhs * rhs,
        .div => lhs / rhs,
        else => unreachable,
    };
}

fn denseFloat32BinaryVec(comptime op: BuiltinId, lhs: anytype, rhs: @TypeOf(lhs)) @TypeOf(lhs) {
    return switch (op) {
        .add => lhs + rhs,
        .sub => lhs - rhs,
        .minimum => @min(lhs, rhs),
        .maximum => @max(lhs, rhs),
        .mul => lhs * rhs,
        .div => lhs / rhs,
        else => unreachable,
    };
}

fn denseFloatTypedBinaryVec(comptime T: type, comptime op: BuiltinId, lhs: anytype, rhs: @TypeOf(lhs)) @TypeOf(lhs) {
    return switch (T) {
        f64 => denseFloatBinaryVec(op, lhs, rhs),
        f32 => denseFloat32BinaryVec(op, lhs, rhs),
        else => @compileError("unsupported dense float SIMD type"),
    };
}

fn denseFloatTypedUnaryVec(comptime T: type, comptime op: BuiltinId, value: anytype) @TypeOf(value) {
    _ = T;
    return switch (op) {
        .add => value,
        .sub => -value,
        .div => @sqrt(value),
        else => unreachable,
    };
}

fn applyDenseFloatTypedOp(comptime T: type, comptime op: BuiltinId, lhs: T, rhs: T) T {
    return switch (T) {
        f64 => applyFloatOp(op, lhs, rhs),
        f32 => applyFloat32Op(op, lhs, rhs),
        else => @compileError("unsupported dense float type"),
    };
}

fn applyDenseFloatTypedUnaryOp(comptime T: type, comptime op: BuiltinId, value: T) T {
    return switch (op) {
        .add => value,
        .sub => -value,
        .div => @sqrt(value),
        else => unreachable,
    };
}

fn DenseProducerContext(comptime T: type) type {
    return struct {
        left_items: []const T,
        right_items: []const T,
        left_scalar: T = 0,
        right_scalar: T = 0,
    };
}

const DenseSourceRole = enum {
    left_array,
    right_array,
    left_reverse_array,
    right_reverse_array,
    left_scalar,
    right_scalar,
};

fn DenseSourceProducer(comptime T: type, comptime lane_count: usize, comptime role: DenseSourceRole) type {
    const Vec = @Vector(lane_count, T);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            return switch (role) {
                .left_array => ctx.left_items[idx..][0..lane_count].*,
                .right_array => ctx.right_items[idx..][0..lane_count].*,
                .left_reverse_array => blk: {
                    const reverse_base = ctx.left_items.len - idx - lane_count;
                    const chunk: Vec = ctx.left_items[reverse_base..][0..lane_count].*;
                    break :blk reversedDenseVector(T, lane_count, chunk);
                },
                .right_reverse_array => blk: {
                    const reverse_base = ctx.right_items.len - idx - lane_count;
                    const chunk: Vec = ctx.right_items[reverse_base..][0..lane_count].*;
                    break :blk reversedDenseVector(T, lane_count, chunk);
                },
                .left_scalar => @splat(ctx.left_scalar),
                .right_scalar => @splat(ctx.right_scalar),
            };
        }

        fn evalScalar(ctx: anytype, idx: usize) T {
            return switch (role) {
                .left_array => ctx.left_items[idx],
                .right_array => ctx.right_items[idx],
                .left_reverse_array => ctx.left_items[ctx.left_items.len - 1 - idx],
                .right_reverse_array => ctx.right_items[ctx.right_items.len - 1 - idx],
                .left_scalar => ctx.left_scalar,
                .right_scalar => ctx.right_scalar,
            };
        }
    };
}

fn DenseFloatUnaryProducer(comptime T: type, comptime lane_count: usize, comptime op: BuiltinId, comptime Child: type) type {
    const Vec = @Vector(lane_count, T);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            return denseFloatTypedUnaryVec(T, op, Child.evalVec(ctx, idx));
        }

        fn evalScalar(ctx: anytype, idx: usize) T {
            return applyDenseFloatTypedUnaryOp(T, op, Child.evalScalar(ctx, idx));
        }
    };
}

fn DenseFloatBinaryProducer(comptime T: type, comptime lane_count: usize, comptime op: BuiltinId, comptime Left: type, comptime Right: type) type {
    const Vec = @Vector(lane_count, T);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            return denseFloatTypedBinaryVec(T, op, Left.evalVec(ctx, idx), Right.evalVec(ctx, idx));
        }

        fn evalScalar(ctx: anytype, idx: usize) T {
            return applyDenseFloatTypedOp(T, op, Left.evalScalar(ctx, idx), Right.evalScalar(ctx, idx));
        }
    };
}

fn DenseCompareProducer(comptime T: type, comptime lane_count: usize, comptime op: BuiltinId, comptime Left: type, comptime Right: type) type {
    const Mask = @Int(.unsigned, lane_count);
    return struct {
        fn evalMask(ctx: anytype, idx: usize) Mask {
            return hostCompareVectorMaskOp(T, lane_count, op, Left.evalVec(ctx, idx), Right.evalVec(ctx, idx));
        }

        fn evalScalar(ctx: anytype, idx: usize) bool {
            return hostCompareScalarValueOp(T, op, Left.evalScalar(ctx, idx), Right.evalScalar(ctx, idx));
        }
    };
}

fn DenseFloatSquareProducer(comptime T: type, comptime lane_count: usize, comptime Child: type) type {
    const Vec = @Vector(lane_count, T);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            const value: Vec = Child.evalVec(ctx, idx);
            return value * value;
        }

        fn evalScalar(ctx: anytype, idx: usize) T {
            const value = Child.evalScalar(ctx, idx);
            return value * value;
        }
    };
}

fn runDenseFloatProducerSink(comptime lane_count: usize, comptime Producer: type, len: usize, ctx: anytype, sink: anytype) void {
    var idx: usize = 0;
    const vector_limit = len - (len % lane_count);
    while (idx < vector_limit) : (idx += lane_count) {
        sink.consumeVec(idx, Producer.evalVec(ctx, idx));
    }
    while (idx < len) : (idx += 1) {
        sink.consumeScalar(idx, Producer.evalScalar(ctx, idx));
    }
}

fn DenseFloatStoreSink(comptime T: type, comptime lane_count: usize) type {
    const Vec = @Vector(lane_count, T);
    return struct {
        out: []T,

        fn consumeVec(self: *@This(), idx: usize, value: Vec) void {
            self.out[idx..][0..lane_count].* = value;
        }

        fn consumeScalar(self: *@This(), idx: usize, value: T) void {
            self.out[idx] = value;
        }
    };
}

fn DenseFloatAddReduceSink(comptime T: type, comptime lane_count: usize) type {
    const Vec = @Vector(lane_count, T);
    return struct {
        acc_vec: Vec = @splat(0),
        tail_total: T = 0,

        fn consumeVec(self: *@This(), _: usize, value: Vec) void {
            self.acc_vec += value;
        }

        fn consumeScalar(self: *@This(), _: usize, value: T) void {
            self.tail_total += value;
        }

        fn finish(self: *const @This()) T {
            return @reduce(.Add, self.acc_vec) + self.tail_total;
        }
    };
}

fn runDenseFloatArrayArrayProducerSink(comptime T: type, comptime op: BuiltinId, left_items: []const T, right_items: []const T, sink: anytype) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    const LoadLeft = DenseSourceProducer(T, lane_count, .left_array);
    const LoadRight = DenseSourceProducer(T, lane_count, .right_array);
    const Producer = DenseFloatBinaryProducer(T, lane_count, op, LoadLeft, LoadRight);
    const ctx = DenseProducerContext(T){ .left_items = left_items, .right_items = right_items };
    runDenseFloatProducerSink(lane_count, Producer, left_items.len, &ctx, sink);
}

fn DenseResolvedSource(comptime T: type) type {
    return union(enum) {
        array: []const T,
        reverse_array: []const T,
        scalar: T,
    };
}

const DenseFloat64ResolvedSource = DenseResolvedSource(f64);
const DenseFloat32ResolvedSource = DenseResolvedSource(f32);

const DenseFloat64PromotedSource = union(enum) {
    array64: []const f64,
    reverse_array64: []const f64,
    array32: []const f32,
    reverse_array32: []const f32,
    scalar: f64,
};

fn denseFloat64PromotedSourceLen(source: DenseFloat64PromotedSource) ?usize {
    return switch (source) {
        .array64 => |items| items.len,
        .reverse_array64 => |items| items.len,
        .array32 => |items| items.len,
        .reverse_array32 => |items| items.len,
        .scalar => null,
    };
}

fn denseFloat64PromotedSourcesLen(left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource) ?usize {
    const left_len = denseFloat64PromotedSourceLen(left);
    const right_len = denseFloat64PromotedSourceLen(right);
    if (left_len == null and right_len == null) return null;
    if (left_len) |len| {
        if (right_len) |other_len| {
            if (len != other_len) return null;
        }
        return len;
    }
    return right_len.?;
}

fn denseFloat64PromotedSliceSource(source: DenseFloat64PromotedSource, range: MorselRange, full_len: usize) DenseFloat64PromotedSource {
    return switch (source) {
        .array64 => |items| .{ .array64 = items[range.start..range.end] },
        .reverse_array64 => |items| .{ .reverse_array64 = items[full_len - range.end .. full_len - range.start] },
        .array32 => |items| .{ .array32 = items[range.start..range.end] },
        .reverse_array32 => |items| .{ .reverse_array32 = items[full_len - range.end .. full_len - range.start] },
        .scalar => |value| .{ .scalar = value },
    };
}

fn denseFloat64PromotedSourceUsesFloat32(source: DenseFloat64PromotedSource) bool {
    return switch (source) {
        .array32, .reverse_array32 => true,
        .array64, .reverse_array64, .scalar => false,
    };
}

fn denseFloat64PromotedSourcesUseMixedStorage(left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource) bool {
    return denseFloat64PromotedSourceUsesFloat32(left) != denseFloat64PromotedSourceUsesFloat32(right);
}

const DenseIntFloatIntSourceRole = enum {
    array,
    reverse_array,
    scalar,
};

const DenseFloat64PromotedSourceSide = enum {
    left,
    right,
};

const DenseFloat64PromotedSourceRole = enum {
    array64,
    reverse_array64,
    array32,
    reverse_array32,
    scalar,
};

const dense_int_float_int_roles = [_]DenseIntFloatIntSourceRole{
    .array,
    .reverse_array,
    .scalar,
};

const dense_float64_promoted_source_roles = [_]DenseFloat64PromotedSourceRole{
    .array64,
    .reverse_array64,
    .array32,
    .reverse_array32,
    .scalar,
};

const DenseFloat64PromotedSourceRolePair = struct {
    left: DenseFloat64PromotedSourceRole,
    right: DenseFloat64PromotedSourceRole,
};

const dense_float64_promoted_source_role_pairs = blk: {
    var pairs: [dense_float64_promoted_source_roles.len * dense_float64_promoted_source_roles.len]DenseFloat64PromotedSourceRolePair = undefined;
    var idx: usize = 0;
    for (dense_float64_promoted_source_roles) |left_role| {
        for (dense_float64_promoted_source_roles) |right_role| {
            pairs[idx] = .{ .left = left_role, .right = right_role };
            idx += 1;
        }
    }
    break :blk pairs;
};

fn denseFloat64PromotedSourceRole(source: DenseFloat64PromotedSource) DenseFloat64PromotedSourceRole {
    return switch (source) {
        .array64 => .array64,
        .reverse_array64 => .reverse_array64,
        .array32 => .array32,
        .reverse_array32 => .reverse_array32,
        .scalar => .scalar,
    };
}

fn denseFloat64PromotedSourceRolePair(left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource) DenseFloat64PromotedSourceRolePair {
    return .{
        .left = denseFloat64PromotedSourceRole(left),
        .right = denseFloat64PromotedSourceRole(right),
    };
}

fn dispatchDenseFloat64PromotedSourceRolePair(comptime Return: type, role_pair: DenseFloat64PromotedSourceRolePair, payload: anytype, comptime Dispatch: type) Return {
    inline for (dense_float64_promoted_source_role_pairs) |Pair| {
        if (role_pair.left == Pair.left and role_pair.right == Pair.right) {
            return Dispatch.call(Pair.left, Pair.right, payload);
        }
    }
    unreachable;
}

fn denseIntFloatSourcesLen(comptime T: type, int_source: DenseResolvedSource(T), float_source: DenseFloat64PromotedSource) ?usize {
    const int_len = denseIntResolvedSourceLen(T, int_source);
    const float_len = denseFloat64PromotedSourceLen(float_source);
    if (int_len == null and float_len == null) return null;
    if (int_len) |len| {
        if (float_len) |other_len| {
            if (len != other_len) return null;
        }
        return len;
    }
    return float_len.?;
}

fn DenseIntFloatProducerContext(comptime T: type) type {
    return struct {
        int_items: []const T = &.{},
        int_scalar: T = 0,
        float64_items: []const f64 = &.{},
        float32_items: []const f32 = &.{},
        float_scalar: f64 = 0,
    };
}

fn denseIntFloatSourceContext(comptime T: type, int_source: DenseResolvedSource(T), float_source: DenseFloat64PromotedSource) DenseIntFloatProducerContext(T) {
    var ctx = DenseIntFloatProducerContext(T){};
    switch (int_source) {
        .array => |items| ctx.int_items = items,
        .reverse_array => |items| ctx.int_items = items,
        .scalar => |value| ctx.int_scalar = value,
    }
    switch (float_source) {
        .array64 => |items| ctx.float64_items = items,
        .reverse_array64 => |items| ctx.float64_items = items,
        .array32 => |items| ctx.float32_items = items,
        .reverse_array32 => |items| ctx.float32_items = items,
        .scalar => |value| ctx.float_scalar = value,
    }
    return ctx;
}

fn DenseIntAsFloat64SourceProducer(comptime T: type, comptime lane_count: usize, comptime role: DenseIntFloatIntSourceRole) type {
    const Vec = @Vector(lane_count, f64);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            return switch (role) {
                .array => hostCompareIntFloatVecFast(T, lane_count, ctx.int_items, idx),
                .reverse_array => blk: {
                    const reverse_base = ctx.int_items.len - idx - lane_count;
                    const chunk = hostCompareIntFloatVecFast(T, lane_count, ctx.int_items, reverse_base);
                    break :blk reversedDenseVector(f64, lane_count, chunk);
                },
                .scalar => @splat(@as(f64, @floatFromInt(ctx.int_scalar))),
            };
        }

        fn evalScalar(ctx: anytype, idx: usize) f64 {
            return switch (role) {
                .array => @floatFromInt(ctx.int_items[idx]),
                .reverse_array => @floatFromInt(ctx.int_items[ctx.int_items.len - 1 - idx]),
                .scalar => @floatFromInt(ctx.int_scalar),
            };
        }
    };
}

fn DenseIntFloatPromotedSourceProducer(comptime lane_count: usize, comptime role: DenseFloat64PromotedSourceRole) type {
    const Vec = @Vector(lane_count, f64);
    const Vec32 = @Vector(lane_count, f32);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            return switch (role) {
                .array64 => ctx.float64_items[idx..][0..lane_count].*,
                .reverse_array64 => blk: {
                    const reverse_base = ctx.float64_items.len - idx - lane_count;
                    const chunk: Vec = ctx.float64_items[reverse_base..][0..lane_count].*;
                    break :blk reversedDenseVector(f64, lane_count, chunk);
                },
                .array32 => blk: {
                    const chunk: Vec32 = ctx.float32_items[idx..][0..lane_count].*;
                    break :blk @floatCast(chunk);
                },
                .reverse_array32 => blk: {
                    const reverse_base = ctx.float32_items.len - idx - lane_count;
                    const chunk: Vec32 = ctx.float32_items[reverse_base..][0..lane_count].*;
                    break :blk @floatCast(reversedDenseVector(f32, lane_count, chunk));
                },
                .scalar => @splat(ctx.float_scalar),
            };
        }

        fn evalScalar(ctx: anytype, idx: usize) f64 {
            return switch (role) {
                .array64 => ctx.float64_items[idx],
                .reverse_array64 => ctx.float64_items[ctx.float64_items.len - 1 - idx],
                .array32 => @floatCast(ctx.float32_items[idx]),
                .reverse_array32 => @floatCast(ctx.float32_items[ctx.float32_items.len - 1 - idx]),
                .scalar => ctx.float_scalar,
            };
        }
    };
}

fn denseIntFloatCompareSourceRolesWord(
    comptime T: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    comptime int_role: DenseIntFloatIntSourceRole,
    comptime float_role: DenseFloat64PromotedSourceRole,
    ctx: *const DenseIntFloatProducerContext(T),
    base: usize,
    active: usize,
) u64 {
    const lane_count = host_compare_zig_vector_bytes / @sizeOf(f64);
    const Int = DenseIntAsFloat64SourceProducer(T, lane_count, int_role);
    const Float = DenseIntFloatPromotedSourceProducer(lane_count, float_role);
    const Producer = if (int_left)
        DenseCompareProducer(f64, lane_count, op, Int, Float)
    else
        DenseCompareProducer(f64, lane_count, op, Float, Int);

    var word: u64 = 0;
    var bit: usize = 0;
    const vector_limit = active - (active % lane_count);
    while (bit < vector_limit) : (bit += lane_count) {
        const mask = Producer.evalMask(ctx, base + bit);
        word |= @as(u64, mask) << @intCast(bit);
    }
    while (bit < active) : (bit += 1) {
        if (Producer.evalScalar(ctx, base + bit)) {
            word |= @as(u64, 1) << @intCast(bit);
        }
    }
    return word;
}

fn runDenseIntFloatMapSourceRolesSink(
    comptime T: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    comptime int_role: DenseIntFloatIntSourceRole,
    comptime float_role: DenseFloat64PromotedSourceRole,
    len: usize,
    ctx: *const DenseIntFloatProducerContext(T),
    sink: anytype,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    const Int = DenseIntAsFloat64SourceProducer(T, lane_count, int_role);
    const Float = DenseIntFloatPromotedSourceProducer(lane_count, float_role);
    const Producer = if (int_left)
        DenseFloatBinaryProducer(f64, lane_count, op, Int, Float)
    else
        DenseFloatBinaryProducer(f64, lane_count, op, Float, Int);
    runDenseFloatProducerSink(lane_count, Producer, len, ctx, sink);
}

fn fillDenseIntFloatCompareSourceRolesOp(
    comptime T: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    comptime int_role: DenseIntFloatIntSourceRole,
    comptime float_role: DenseFloat64PromotedSourceRole,
    out: *HostBitAlloc,
    len: usize,
    ctx: *const DenseIntFloatProducerContext(T),
) HostCompareSummary {
    var summary = hostCompareSummaryEmpty();
    for (out.words, 0..) |*out_word, word_idx| {
        const active = bitWordActiveLen(len, word_idx, out.words.len);
        const base = word_idx * host_bit_word_bits;
        const word = denseIntFloatCompareSourceRolesWord(T, op, int_left, int_role, float_role, ctx, base, active);
        out_word.* = word;
        hostCompareSummaryNoteWord(&summary, word, active);
    }
    return summary;
}

fn fillDenseIntFloatCompareSourcesOp(
    comptime T: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    out: *HostBitAlloc,
    int_source: DenseResolvedSource(T),
    float_source: DenseFloat64PromotedSource,
    len: usize,
) ?HostCompareSummary {
    if (out.len != len) return null;
    const source_len = denseIntFloatSourcesLen(T, int_source, float_source) orelse return null;
    if (source_len != len) return null;

    var ctx = denseIntFloatSourceContext(T, int_source, float_source);
    const int_role: DenseIntFloatIntSourceRole = switch (int_source) {
        .array => .array,
        .reverse_array => .reverse_array,
        .scalar => .scalar,
    };
    const float_role = denseFloat64PromotedSourceRole(float_source);
    inline for (dense_int_float_int_roles) |IntRole| {
        if (int_role == IntRole) {
            inline for (dense_float64_promoted_source_roles) |FloatRole| {
                if (float_role == FloatRole) {
                    return fillDenseIntFloatCompareSourceRolesOp(T, op, int_left, IntRole, FloatRole, out, len, &ctx);
                }
            }
        }
    }
    unreachable;
}

fn runDenseIntFloatSourceMapSinkOp(
    comptime T: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    int_source: DenseResolvedSource(T),
    float_source: DenseFloat64PromotedSource,
    len: usize,
    sink: anytype,
) void {
    var ctx = denseIntFloatSourceContext(T, int_source, float_source);
    const int_role: DenseIntFloatIntSourceRole = switch (int_source) {
        .array => .array,
        .reverse_array => .reverse_array,
        .scalar => .scalar,
    };
    const float_role = denseFloat64PromotedSourceRole(float_source);
    inline for (dense_int_float_int_roles) |IntRole| {
        if (int_role == IntRole) {
            inline for (dense_float64_promoted_source_roles) |FloatRole| {
                if (float_role == FloatRole) {
                    runDenseIntFloatMapSourceRolesSink(T, op, int_left, IntRole, FloatRole, len, &ctx, sink);
                    return;
                }
            }
        }
    }
    unreachable;
}

fn fillDenseIntFloatSourcesStoreOp(
    comptime T: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    out: []f64,
    int_source: DenseResolvedSource(T),
    float_source: DenseFloat64PromotedSource,
    len: usize,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    var sink = DenseFloatStoreSink(f64, lane_count){ .out = out };
    runDenseIntFloatSourceMapSinkOp(T, op, int_left, int_source, float_source, len, &sink);
}

fn fillDenseIntFloatSourcesStore(
    comptime T: type,
    comptime int_left: bool,
    out: []f64,
    op: BuiltinId,
    int_source: DenseResolvedSource(T),
    float_source: DenseFloat64PromotedSource,
    len: usize,
) void {
    switch (op) {
        .add => fillDenseIntFloatSourcesStoreOp(T, .add, int_left, out, int_source, float_source, len),
        .sub => fillDenseIntFloatSourcesStoreOp(T, .sub, int_left, out, int_source, float_source, len),
        .minimum => fillDenseIntFloatSourcesStoreOp(T, .minimum, int_left, out, int_source, float_source, len),
        .maximum => fillDenseIntFloatSourcesStoreOp(T, .maximum, int_left, out, int_source, float_source, len),
        .mul => fillDenseIntFloatSourcesStoreOp(T, .mul, int_left, out, int_source, float_source, len),
        .div => fillDenseIntFloatSourcesStoreOp(T, .div, int_left, out, int_source, float_source, len),
        else => unreachable,
    }
}

fn fillDenseIntFloatSourcesStoreMorselKernel(comptime T: type, comptime op: BuiltinId, comptime int_left: bool) type {
    return struct {
        const Ctx = struct {
            out: []f64,
            int_source: DenseResolvedSource(T),
            float_source: DenseFloat64PromotedSource,
            len: usize,
        };

        fn run(ctx: Ctx, range: MorselRange) void {
            const int_source = denseIntSliceResolvedSource(T, ctx.int_source, range, ctx.len);
            const float_source = denseFloat64PromotedSliceSource(ctx.float_source, range, ctx.len);
            fillDenseIntFloatSourcesStoreOp(T, op, int_left, ctx.out[range.start..range.end], int_source, float_source, range.end - range.start);
        }
    };
}

fn runDenseIntFloatSourcesStoreMorselOp(
    session: *Session,
    comptime T: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    out: []f64,
    int_source: DenseResolvedSource(T),
    float_source: DenseFloat64PromotedSource,
    len: usize,
    workers_requested: usize,
) void {
    const grain = normalizeMorselGrain(len, default_morsel_grain);
    const Kernel = fillDenseIntFloatSourcesStoreMorselKernel(T, op, int_left);
    session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .out = out, .int_source = int_source, .float_source = float_source, .len = len }, Kernel.run) catch unreachable;
}

fn fillDenseIntFloatSourcesStoreMorsel(
    session: *Session,
    comptime T: type,
    comptime int_left: bool,
    out: []f64,
    op: BuiltinId,
    int_source: DenseResolvedSource(T),
    float_source: DenseFloat64PromotedSource,
    len: usize,
    workers_requested: usize,
) void {
    switch (op) {
        .add => runDenseIntFloatSourcesStoreMorselOp(session, T, .add, int_left, out, int_source, float_source, len, workers_requested),
        .sub => runDenseIntFloatSourcesStoreMorselOp(session, T, .sub, int_left, out, int_source, float_source, len, workers_requested),
        .minimum => runDenseIntFloatSourcesStoreMorselOp(session, T, .minimum, int_left, out, int_source, float_source, len, workers_requested),
        .maximum => runDenseIntFloatSourcesStoreMorselOp(session, T, .maximum, int_left, out, int_source, float_source, len, workers_requested),
        .mul => runDenseIntFloatSourcesStoreMorselOp(session, T, .mul, int_left, out, int_source, float_source, len, workers_requested),
        .div => runDenseIntFloatSourcesStoreMorselOp(session, T, .div, int_left, out, int_source, float_source, len, workers_requested),
        else => unreachable,
    }
}

fn DenseIntResolvedFloatProducerContext(comptime IntT: type, comptime FloatT: type) type {
    return struct {
        int_items: []const IntT = &.{},
        int_scalar: IntT = 0,
        float_items: []const FloatT = &.{},
        float_scalar: FloatT = 0,
    };
}

fn denseIntResolvedFloatSourcesLen(comptime IntT: type, comptime FloatT: type, int_source: DenseResolvedSource(IntT), float_source: DenseResolvedSource(FloatT)) ?usize {
    const int_len = denseIntResolvedSourceLen(IntT, int_source);
    const float_len = denseFloatResolvedSourceLen(FloatT, float_source);
    if (int_len == null and float_len == null) return null;
    if (int_len) |len| {
        if (float_len) |other_len| {
            if (len != other_len) return null;
        }
        return len;
    }
    return float_len.?;
}

fn denseIntResolvedFloatSourceContext(comptime IntT: type, comptime FloatT: type, int_source: DenseResolvedSource(IntT), float_source: DenseResolvedSource(FloatT)) DenseIntResolvedFloatProducerContext(IntT, FloatT) {
    var ctx = DenseIntResolvedFloatProducerContext(IntT, FloatT){};
    switch (int_source) {
        .array => |items| ctx.int_items = items,
        .reverse_array => |items| ctx.int_items = items,
        .scalar => |value| ctx.int_scalar = value,
    }
    switch (float_source) {
        .array => |items| ctx.float_items = items,
        .reverse_array => |items| ctx.float_items = items,
        .scalar => |value| ctx.float_scalar = value,
    }
    return ctx;
}

fn denseResolvedFloatSourceRole(comptime T: type, source: DenseResolvedSource(T)) DenseIntFloatIntSourceRole {
    return switch (source) {
        .array => .array,
        .reverse_array => .reverse_array,
        .scalar => .scalar,
    };
}

fn denseIntResolvedSourceRole(comptime T: type, source: DenseResolvedSource(T)) DenseIntFloatIntSourceRole {
    return switch (source) {
        .array => .array,
        .reverse_array => .reverse_array,
        .scalar => .scalar,
    };
}

fn DenseIntAsResolvedFloatSourceProducer(comptime IntT: type, comptime FloatT: type, comptime lane_count: usize, comptime role: DenseIntFloatIntSourceRole) type {
    const Vec = @Vector(lane_count, FloatT);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            return switch (role) {
                .array => denseIntLoadAsFloatVec(IntT, FloatT, lane_count, ctx.int_items, idx),
                .reverse_array => blk: {
                    const reverse_base = ctx.int_items.len - idx - lane_count;
                    const chunk = denseIntLoadAsFloatVec(IntT, FloatT, lane_count, ctx.int_items, reverse_base);
                    break :blk reversedDenseVector(FloatT, lane_count, chunk);
                },
                .scalar => @splat(@as(FloatT, @floatFromInt(ctx.int_scalar))),
            };
        }

        fn evalScalar(ctx: anytype, idx: usize) FloatT {
            return switch (role) {
                .array => @floatFromInt(ctx.int_items[idx]),
                .reverse_array => @floatFromInt(ctx.int_items[ctx.int_items.len - 1 - idx]),
                .scalar => @floatFromInt(ctx.int_scalar),
            };
        }
    };
}

fn DenseResolvedFloatSourceProducer(comptime FloatT: type, comptime lane_count: usize, comptime role: DenseIntFloatIntSourceRole) type {
    const Vec = @Vector(lane_count, FloatT);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            return switch (role) {
                .array => ctx.float_items[idx..][0..lane_count].*,
                .reverse_array => blk: {
                    const reverse_base = ctx.float_items.len - idx - lane_count;
                    const chunk: Vec = ctx.float_items[reverse_base..][0..lane_count].*;
                    break :blk reversedDenseVector(FloatT, lane_count, chunk);
                },
                .scalar => @splat(ctx.float_scalar),
            };
        }

        fn evalScalar(ctx: anytype, idx: usize) FloatT {
            return switch (role) {
                .array => ctx.float_items[idx],
                .reverse_array => ctx.float_items[ctx.float_items.len - 1 - idx],
                .scalar => ctx.float_scalar,
            };
        }
    };
}

fn runDenseIntResolvedFloatMapSourceRolesSink(
    comptime IntT: type,
    comptime FloatT: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    comptime int_role: DenseIntFloatIntSourceRole,
    comptime float_role: DenseIntFloatIntSourceRole,
    len: usize,
    ctx: *const DenseIntResolvedFloatProducerContext(IntT, FloatT),
    sink: anytype,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(FloatT);
    const Int = DenseIntAsResolvedFloatSourceProducer(IntT, FloatT, lane_count, int_role);
    const Float = DenseResolvedFloatSourceProducer(FloatT, lane_count, float_role);
    const Producer = if (int_left)
        DenseFloatBinaryProducer(FloatT, lane_count, op, Int, Float)
    else
        DenseFloatBinaryProducer(FloatT, lane_count, op, Float, Int);
    runDenseFloatProducerSink(lane_count, Producer, len, ctx, sink);
}

fn runDenseIntResolvedFloatSourceMapSinkOp(
    comptime IntT: type,
    comptime FloatT: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    int_source: DenseResolvedSource(IntT),
    float_source: DenseResolvedSource(FloatT),
    len: usize,
    sink: anytype,
) void {
    var ctx = denseIntResolvedFloatSourceContext(IntT, FloatT, int_source, float_source);
    const int_role = denseIntResolvedSourceRole(IntT, int_source);
    const float_role = denseResolvedFloatSourceRole(FloatT, float_source);
    inline for (dense_int_float_int_roles) |IntRole| {
        if (int_role == IntRole) {
            inline for (dense_int_float_int_roles) |FloatRole| {
                if (float_role == FloatRole) {
                    runDenseIntResolvedFloatMapSourceRolesSink(IntT, FloatT, op, int_left, IntRole, FloatRole, len, &ctx, sink);
                    return;
                }
            }
        }
    }
    unreachable;
}

fn denseIntResolvedSourceFloatScalarItem(comptime IntT: type, comptime FloatT: type, source: DenseResolvedSource(IntT), idx: usize) FloatT {
    return @floatFromInt(denseIntResolvedSourceScalarItem(IntT, source, idx));
}

fn fillDenseIntResolvedFloatSourcesStoreScalarOp(
    comptime IntT: type,
    comptime FloatT: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    out: []FloatT,
    int_source: DenseResolvedSource(IntT),
    float_source: DenseResolvedSource(FloatT),
    len: usize,
) void {
    for (out[0..len], 0..) |*dest, idx| {
        const int_value = denseIntResolvedSourceFloatScalarItem(IntT, FloatT, int_source, idx);
        const float_value = denseFloatResolvedSourceScalarItem(FloatT, float_source, idx);
        dest.* = if (int_left)
            applyDenseFloatTypedOp(FloatT, op, int_value, float_value)
        else
            applyDenseFloatTypedOp(FloatT, op, float_value, int_value);
    }
}

fn fillDenseIntResolvedFloatSourcesStoreScalar(
    comptime IntT: type,
    comptime FloatT: type,
    comptime int_left: bool,
    out: []FloatT,
    op: BuiltinId,
    int_source: DenseResolvedSource(IntT),
    float_source: DenseResolvedSource(FloatT),
    len: usize,
) void {
    switch (op) {
        .add => fillDenseIntResolvedFloatSourcesStoreScalarOp(IntT, FloatT, .add, int_left, out, int_source, float_source, len),
        .sub => fillDenseIntResolvedFloatSourcesStoreScalarOp(IntT, FloatT, .sub, int_left, out, int_source, float_source, len),
        .minimum => fillDenseIntResolvedFloatSourcesStoreScalarOp(IntT, FloatT, .minimum, int_left, out, int_source, float_source, len),
        .maximum => fillDenseIntResolvedFloatSourcesStoreScalarOp(IntT, FloatT, .maximum, int_left, out, int_source, float_source, len),
        .mul => fillDenseIntResolvedFloatSourcesStoreScalarOp(IntT, FloatT, .mul, int_left, out, int_source, float_source, len),
        .div => fillDenseIntResolvedFloatSourcesStoreScalarOp(IntT, FloatT, .div, int_left, out, int_source, float_source, len),
        else => unreachable,
    }
}

fn fillDenseIntResolvedFloatSourcesStoreOp(
    comptime IntT: type,
    comptime FloatT: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    out: []FloatT,
    int_source: DenseResolvedSource(IntT),
    float_source: DenseResolvedSource(FloatT),
    len: usize,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(FloatT);
    var sink = DenseFloatStoreSink(FloatT, lane_count){ .out = out };
    runDenseIntResolvedFloatSourceMapSinkOp(IntT, FloatT, op, int_left, int_source, float_source, len, &sink);
}

fn fillDenseIntResolvedFloatSourcesStore(
    comptime IntT: type,
    comptime FloatT: type,
    comptime int_left: bool,
    out: []FloatT,
    op: BuiltinId,
    int_source: DenseResolvedSource(IntT),
    float_source: DenseResolvedSource(FloatT),
