        .minimum => fillDenseIntResolvedFloatSourcesStoreOp(IntT, FloatT, .minimum, int_left, out, int_source, float_source, len),
        .maximum => fillDenseIntResolvedFloatSourcesStoreOp(IntT, FloatT, .maximum, int_left, out, int_source, float_source, len),
