fn fillDenseIntResolvedFloatSourcesStoreMorselKernel(comptime IntT: type, comptime FloatT: type, comptime op: BuiltinId, comptime int_left: bool) type {
    return struct {
        const Ctx = struct {
            out: []FloatT,
            int_source: DenseResolvedSource(IntT),
            float_source: DenseResolvedSource(FloatT),
            len: usize,
        };

        fn run(ctx: Ctx, range: MorselRange) void {
            const int_source = denseIntSliceResolvedSource(IntT, ctx.int_source, range, ctx.len);
            const float_source = denseFloatSliceResolvedSource(FloatT, ctx.float_source, range, ctx.len);
            fillDenseIntResolvedFloatSourcesStoreOp(IntT, FloatT, op, int_left, ctx.out[range.start..range.end], int_source, float_source, range.end - range.start);
        }
    };
}

fn runDenseIntResolvedFloatSourcesStoreMorselOp(
    session: *Session,
    comptime IntT: type,
    comptime FloatT: type,
    comptime op: BuiltinId,
    comptime int_left: bool,
    out: []FloatT,
    int_source: DenseResolvedSource(IntT),
    float_source: DenseResolvedSource(FloatT),
    len: usize,
    workers_requested: usize,
) void {
    const grain = normalizeMorselGrain(len, default_morsel_grain);
    const Kernel = fillDenseIntResolvedFloatSourcesStoreMorselKernel(IntT, FloatT, op, int_left);
    session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .out = out, .int_source = int_source, .float_source = float_source, .len = len }, Kernel.run) catch unreachable;
}

fn fillDenseIntResolvedFloatSourcesStoreMorsel(
