        .maximum => runDenseIntResolvedFloatSourcesStoreMorselOp(session, IntT, FloatT, .maximum, int_left, out, int_source, float_source, len, workers_requested),
        .mul => runDenseIntResolvedFloatSourcesStoreMorselOp(session, IntT, FloatT, .mul, int_left, out, int_source, float_source, len, workers_requested),
        .div => runDenseIntResolvedFloatSourcesStoreMorselOp(session, IntT, FloatT, .div, int_left, out, int_source, float_source, len, workers_requested),
