    return switch (op) {
        .equal => fillDenseIntFloatCompareSourcesOp(T, .equal, int_left, out, int_source, float_source, len),
        .less => fillDenseIntFloatCompareSourcesOp(T, .less, int_left, out, int_source, float_source, len),
        .more => fillDenseIntFloatCompareSourcesOp(T, .more, int_left, out, int_source, float_source, len),
