const DenseFloat64PromotedProducerContext = struct {
    left_f64_items: []const f64 = &.{},
    right_f64_items: []const f64 = &.{},
    left_f32_items: []const f32 = &.{},
    right_f32_items: []const f32 = &.{},
    left_scalar: f64 = 0,
    right_scalar: f64 = 0,
};

fn denseFloat64PromotedSourceContext(left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource) DenseFloat64PromotedProducerContext {
    var ctx = DenseFloat64PromotedProducerContext{};
    switch (left) {
        .array64 => |items| ctx.left_f64_items = items,
        .reverse_array64 => |items| ctx.left_f64_items = items,
        .array32 => |items| ctx.left_f32_items = items,
        .reverse_array32 => |items| ctx.left_f32_items = items,
        .scalar => |value| ctx.left_scalar = value,
    }
    switch (right) {
        .array64 => |items| ctx.right_f64_items = items,
        .reverse_array64 => |items| ctx.right_f64_items = items,
        .array32 => |items| ctx.right_f32_items = items,
        .reverse_array32 => |items| ctx.right_f32_items = items,
        .scalar => |value| ctx.right_scalar = value,
    }
    return ctx;
}

fn DenseFloat64PromotedSourceProducer(comptime lane_count: usize, comptime side: DenseFloat64PromotedSourceSide, comptime role: DenseFloat64PromotedSourceRole) type {
    const Vec = @Vector(lane_count, f64);
    const Vec32 = @Vector(lane_count, f32);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            const f64_items = switch (side) {
                .left => ctx.left_f64_items,
                .right => ctx.right_f64_items,
            };
            const f32_items = switch (side) {
                .left => ctx.left_f32_items,
                .right => ctx.right_f32_items,
            };
            const scalar = switch (side) {
                .left => ctx.left_scalar,
                .right => ctx.right_scalar,
            };
            return switch (role) {
                .array64 => f64_items[idx..][0..lane_count].*,
                .reverse_array64 => blk: {
                    const reverse_base = f64_items.len - idx - lane_count;
                    const chunk: Vec = f64_items[reverse_base..][0..lane_count].*;
                    break :blk reversedDenseVector(f64, lane_count, chunk);
                },
                .array32 => blk: {
                    const chunk: Vec32 = f32_items[idx..][0..lane_count].*;
                    break :blk @floatCast(chunk);
                },
                .reverse_array32 => blk: {
                    const reverse_base = f32_items.len - idx - lane_count;
                    const chunk: Vec32 = f32_items[reverse_base..][0..lane_count].*;
                    break :blk @floatCast(reversedDenseVector(f32, lane_count, chunk));
                },
                .scalar => @splat(scalar),
            };
        }

        fn evalScalar(ctx: anytype, idx: usize) f64 {
            const f64_items = switch (side) {
                .left => ctx.left_f64_items,
                .right => ctx.right_f64_items,
            };
            const f32_items = switch (side) {
                .left => ctx.left_f32_items,
                .right => ctx.right_f32_items,
            };
            const scalar = switch (side) {
                .left => ctx.left_scalar,
                .right => ctx.right_scalar,
            };
            return switch (role) {
                .array64 => f64_items[idx],
                .reverse_array64 => f64_items[f64_items.len - 1 - idx],
                .array32 => @floatCast(f32_items[idx]),
                .reverse_array32 => @floatCast(f32_items[f32_items.len - 1 - idx]),
                .scalar => scalar,
            };
        }
    };
}

fn runDenseFloat64PromotedMapSourceRolesSink(
    comptime op: BuiltinId,
    comptime left_role: DenseFloat64PromotedSourceRole,
    comptime right_role: DenseFloat64PromotedSourceRole,
    len: usize,
    ctx: *const DenseFloat64PromotedProducerContext,
    sink: anytype,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    const Left = DenseFloat64PromotedSourceProducer(lane_count, .left, left_role);
    const Right = DenseFloat64PromotedSourceProducer(lane_count, .right, right_role);
    const Producer = DenseFloatBinaryProducer(f64, lane_count, op, Left, Right);
    runDenseFloatProducerSink(lane_count, Producer, len, ctx, sink);
}

fn runDenseFloat64PromotedSquaredDiffSourceRolesSink(
    comptime left_role: DenseFloat64PromotedSourceRole,
    comptime right_role: DenseFloat64PromotedSourceRole,
    len: usize,
    ctx: *const DenseFloat64PromotedProducerContext,
    sink: anytype,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    const Left = DenseFloat64PromotedSourceProducer(lane_count, .left, left_role);
    const Right = DenseFloat64PromotedSourceProducer(lane_count, .right, right_role);
    const Diff = DenseFloatBinaryProducer(f64, lane_count, .sub, Left, Right);
    const Producer = DenseFloatSquareProducer(f64, lane_count, Diff);
    runDenseFloatProducerSink(lane_count, Producer, len, ctx, sink);
}

fn countCompareFloat64PromotedSourceRoles(
    comptime op: BuiltinId,
    comptime left_role: DenseFloat64PromotedSourceRole,
    comptime right_role: DenseFloat64PromotedSourceRole,
    len: usize,
    ctx: *const DenseFloat64PromotedProducerContext,
) i64 {
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    const Left = DenseFloat64PromotedSourceProducer(lane_count, .left, left_role);
    const Right = DenseFloat64PromotedSourceProducer(lane_count, .right, right_role);
    var idx: usize = 0;
    var total: i64 = 0;
    const vector_limit = len - (len % lane_count);
    while (idx < vector_limit) : (idx += lane_count) {
        const mask = hostCompareVectorMaskOp(f64, lane_count, op, Left.evalVec(ctx, idx), Right.evalVec(ctx, idx));
        total += @intCast(@popCount(mask));
    }
    while (idx < len) : (idx += 1) {
        if (hostCompareScalarValueOp(f64, op, Left.evalScalar(ctx, idx), Right.evalScalar(ctx, idx))) total += 1;
    }
    return total;
}

fn denseFloat64PromotedCompareSourceRolesWord(
    comptime op: BuiltinId,
    comptime left_role: DenseFloat64PromotedSourceRole,
    comptime right_role: DenseFloat64PromotedSourceRole,
    ctx: *const DenseFloat64PromotedProducerContext,
    base: usize,
    active: usize,
) u64 {
    const lane_count = host_compare_zig_vector_bytes / @sizeOf(f64);
    const Left = DenseFloat64PromotedSourceProducer(lane_count, .left, left_role);
    const Right = DenseFloat64PromotedSourceProducer(lane_count, .right, right_role);
    const Producer = DenseCompareProducer(f64, lane_count, op, Left, Right);

    var word: u64 = 0;
    var bit: usize = 0;
    const vector_limit = active - (active % lane_count);
    while (bit < vector_limit) : (bit += lane_count) {
        const mask = Producer.evalMask(ctx, base + bit);
        word |= @as(u64, mask) << @intCast(bit);
    }
    while (bit < active) : (bit += 1) {
        if (Producer.evalScalar(ctx, base + bit)) {
            word |= @as(u64, 1) << @intCast(bit);
        }
    }
    return word;
}

fn fillDenseFloat64PromotedCompareSourceRolesOp(
    comptime op: BuiltinId,
    comptime left_role: DenseFloat64PromotedSourceRole,
    comptime right_role: DenseFloat64PromotedSourceRole,
    out: *HostBitAlloc,
    len: usize,
    ctx: *const DenseFloat64PromotedProducerContext,
) HostCompareSummary {
    var summary = hostCompareSummaryEmpty();
    for (out.words, 0..) |*out_word, word_idx| {
        const active = bitWordActiveLen(len, word_idx, out.words.len);
        const base = word_idx * host_bit_word_bits;
        const word = denseFloat64PromotedCompareSourceRolesWord(op, left_role, right_role, ctx, base, active);
        out_word.* = word;
        hostCompareSummaryNoteWord(&summary, word, active);
    }
    return summary;
}

fn runDenseFloat64PromotedSourceMapSinkOp(comptime op: BuiltinId, left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource, len: usize, sink: anytype) void {
    var ctx = denseFloat64PromotedSourceContext(left, right);
    const Payload = struct {
        len: usize,
        ctx: *const DenseFloat64PromotedProducerContext,
        sink: @TypeOf(sink),
    };
    const Dispatch = struct {
        fn call(comptime LeftRole: DenseFloat64PromotedSourceRole, comptime RightRole: DenseFloat64PromotedSourceRole, payload: *Payload) void {
            runDenseFloat64PromotedMapSourceRolesSink(op, LeftRole, RightRole, payload.len, payload.ctx, payload.sink);
        }
    };
    var payload = Payload{ .len = len, .ctx = &ctx, .sink = sink };
    dispatchDenseFloat64PromotedSourceRolePair(void, denseFloat64PromotedSourceRolePair(left, right), &payload, Dispatch);
}

fn runDenseFloat64PromotedSquaredDiffSourceSink(left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource, len: usize, sink: anytype) void {
    var ctx = denseFloat64PromotedSourceContext(left, right);
    const Payload = struct {
        len: usize,
        ctx: *const DenseFloat64PromotedProducerContext,
        sink: @TypeOf(sink),
    };
    const Dispatch = struct {
        fn call(comptime LeftRole: DenseFloat64PromotedSourceRole, comptime RightRole: DenseFloat64PromotedSourceRole, payload: *Payload) void {
            runDenseFloat64PromotedSquaredDiffSourceRolesSink(LeftRole, RightRole, payload.len, payload.ctx, payload.sink);
        }
    };
    var payload = Payload{ .len = len, .ctx = &ctx, .sink = sink };
    dispatchDenseFloat64PromotedSourceRolePair(void, denseFloat64PromotedSourceRolePair(left, right), &payload, Dispatch);
}

fn fillDenseFloat64PromotedCompareSourcesOp(comptime op: BuiltinId, out: *HostBitAlloc, left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource, len: usize) ?HostCompareSummary {
    if (out.len != len) return null;
    const source_len = denseFloat64PromotedSourcesLen(left, right) orelse return null;
    if (source_len != len) return null;

    var ctx = denseFloat64PromotedSourceContext(left, right);
    const Payload = struct {
        out: *HostBitAlloc,
        len: usize,
        ctx: *const DenseFloat64PromotedProducerContext,
    };
    const Dispatch = struct {
        fn call(comptime LeftRole: DenseFloat64PromotedSourceRole, comptime RightRole: DenseFloat64PromotedSourceRole, payload: *Payload) HostCompareSummary {
            return fillDenseFloat64PromotedCompareSourceRolesOp(op, LeftRole, RightRole, payload.out, payload.len, payload.ctx);
        }
    };
    var payload = Payload{ .out = out, .len = len, .ctx = &ctx };
    return dispatchDenseFloat64PromotedSourceRolePair(HostCompareSummary, denseFloat64PromotedSourceRolePair(left, right), &payload, Dispatch);
}

fn countCompareFloat64PromotedSourcesOp(comptime op: BuiltinId, left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource, len: usize) i64 {
