    };
    const Dispatch = struct {
        fn call(comptime LeftRole: DenseFloat64PromotedSourceRole, comptime RightRole: DenseFloat64PromotedSourceRole, payload: *Payload) i64 {
            return countCompareFloat64PromotedSourceRoles(op, LeftRole, RightRole, payload.len, payload.ctx);
        }
    };
    var payload = Payload{ .len = len, .ctx = &ctx };
    return dispatchDenseFloat64PromotedSourceRolePair(i64, denseFloat64PromotedSourceRolePair(left, right), &payload, Dispatch);
}

