fn foldAddMapFloat64PromotedSourcesMorselKernel(comptime op: BuiltinId) type {
    return struct {
        const Ctx = struct {
            left: DenseFloat64PromotedSource,
            right: DenseFloat64PromotedSource,
            partials: []f64,
            grain: usize,
            len: usize,
        };

        fn run(ctx: Ctx, range: MorselRange) void {
            const partial_idx = range.start / ctx.grain;
            const left = denseFloat64PromotedSliceSource(ctx.left, range, ctx.len);
            const right = denseFloat64PromotedSliceSource(ctx.right, range, ctx.len);
            ctx.partials[partial_idx] = foldAddMapFloat64PromotedSources(op, left, right, range.end - range.start);
        }
    };
}

