fn foldAddMapFloat64PromotedSourcesMorselOp(session: *Session, op: BuiltinId, left: DenseFloat64PromotedSource, right: DenseFloat64PromotedSource, len: usize, workers_requested: usize) KError!f64 {
    if (len == 0) return error.Type;
    const grain = normalizeMorselGrain(len, default_morsel_grain);
    const morsel_count = countMorsels(len, grain);
    const partials = try session.morselF64Partials(morsel_count);

    switch (op) {
        .add => {
            const Kernel = foldAddMapFloat64PromotedSourcesMorselKernel(.add);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .sub => {
            const Kernel = foldAddMapFloat64PromotedSourcesMorselKernel(.sub);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .minimum => {
            const Kernel = foldAddMapFloat64PromotedSourcesMorselKernel(.minimum);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .maximum => {
            const Kernel = foldAddMapFloat64PromotedSourcesMorselKernel(.maximum);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .mul => {
            const Kernel = foldAddMapFloat64PromotedSourcesMorselKernel(.mul);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .div => {
            const Kernel = foldAddMapFloat64PromotedSourcesMorselKernel(.div);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        else => unreachable,
    }

    var total: f64 = 0.0;
    for (partials) |partial| total += partial;
    return total;
}

