fn denseFloatResolvedSourceLen(comptime T: type, source: DenseResolvedSource(T)) ?usize {
    return switch (source) {
        .array => |items| items.len,
        .reverse_array => |items| items.len,
        .scalar => null,
    };
}

fn denseFloatResolvedSourcesLen(comptime T: type, left: DenseResolvedSource(T), right: DenseResolvedSource(T)) ?usize {
    const left_len = denseFloatResolvedSourceLen(T, left);
    const right_len = denseFloatResolvedSourceLen(T, right);
    if (left_len == null and right_len == null) return null;
    if (left_len) |len| {
        if (right_len) |other_len| {
            if (len != other_len) return null;
        }
        return len;
    }
    return right_len.?;
}

fn denseFloatSliceResolvedSource(comptime T: type, source: DenseResolvedSource(T), range: MorselRange, full_len: usize) DenseResolvedSource(T) {
    return switch (source) {
        .array => |items| .{ .array = items[range.start..range.end] },
        .reverse_array => |items| .{ .reverse_array = items[full_len - range.end .. full_len - range.start] },
        .scalar => |value| .{ .scalar = value },
    };
}

fn denseFloatSourceContext(comptime T: type, left: DenseResolvedSource(T), right: DenseResolvedSource(T)) DenseProducerContext(T) {
    var ctx = DenseProducerContext(T){
        .left_items = &.{},
        .right_items = &.{},
    };
    switch (left) {
        .array => |items| ctx.left_items = items,
        .reverse_array => |items| ctx.left_items = items,
        .scalar => |value| ctx.left_scalar = value,
    }
    switch (right) {
        .array => |items| ctx.right_items = items,
        .reverse_array => |items| ctx.right_items = items,
        .scalar => |value| ctx.right_scalar = value,
    }
    return ctx;
}

fn denseFloatResolvedSourceScalarItem(comptime T: type, source: DenseResolvedSource(T), idx: usize) T {
    return switch (source) {
        .array => |items| items[idx],
        .reverse_array => |items| items[items.len - 1 - idx],
        .scalar => |value| value,
    };
}

fn runDenseFloatMapSourceRolesSink(
    comptime T: type,
    comptime op: BuiltinId,
    comptime left_role: DenseSourceRole,
    comptime right_role: DenseSourceRole,
    len: usize,
    ctx: *const DenseProducerContext(T),
    sink: anytype,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    const Left = DenseSourceProducer(T, lane_count, left_role);
    const Right = DenseSourceProducer(T, lane_count, right_role);
    const Producer = DenseFloatBinaryProducer(T, lane_count, op, Left, Right);
    runDenseFloatProducerSink(lane_count, Producer, len, ctx, sink);
}

fn runDenseFloatUnarySourceRolesSink(
    comptime T: type,
    comptime op: BuiltinId,
    comptime source_role: DenseSourceRole,
    len: usize,
    ctx: *const DenseProducerContext(T),
    sink: anytype,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    const Source = DenseSourceProducer(T, lane_count, source_role);
    const Producer = DenseFloatUnaryProducer(T, lane_count, op, Source);
    runDenseFloatProducerSink(lane_count, Producer, len, ctx, sink);
}

fn runDenseFloatSquaredDiffSourceRolesSink(
    comptime T: type,
    comptime left_role: DenseSourceRole,
    comptime right_role: DenseSourceRole,
    len: usize,
    ctx: *const DenseProducerContext(T),
    sink: anytype,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    const Left = DenseSourceProducer(T, lane_count, left_role);
    const Right = DenseSourceProducer(T, lane_count, right_role);
    const Diff = DenseFloatBinaryProducer(T, lane_count, .sub, Left, Right);
    const Producer = DenseFloatSquareProducer(T, lane_count, Diff);
    runDenseFloatProducerSink(lane_count, Producer, len, ctx, sink);
}

fn runDenseFloatSourceMapSinkOp(comptime T: type, comptime op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize, sink: anytype) void {
    var ctx = denseFloatSourceContext(T, left, right);
    switch (left) {
        .array => switch (right) {
            .array => runDenseFloatMapSourceRolesSink(T, op, .left_array, .right_array, len, &ctx, sink),
            .reverse_array => runDenseFloatMapSourceRolesSink(T, op, .left_array, .right_reverse_array, len, &ctx, sink),
            .scalar => runDenseFloatMapSourceRolesSink(T, op, .left_array, .right_scalar, len, &ctx, sink),
        },
        .reverse_array => switch (right) {
            .array => runDenseFloatMapSourceRolesSink(T, op, .left_reverse_array, .right_array, len, &ctx, sink),
            .reverse_array => runDenseFloatMapSourceRolesSink(T, op, .left_reverse_array, .right_reverse_array, len, &ctx, sink),
            .scalar => runDenseFloatMapSourceRolesSink(T, op, .left_reverse_array, .right_scalar, len, &ctx, sink),
        },
        .scalar => switch (right) {
            .array => runDenseFloatMapSourceRolesSink(T, op, .left_scalar, .right_array, len, &ctx, sink),
            .reverse_array => runDenseFloatMapSourceRolesSink(T, op, .left_scalar, .right_reverse_array, len, &ctx, sink),
            .scalar => unreachable,
        },
    }
}

fn denseFloatCompareSourceRolesWord(
    comptime T: type,
    comptime op: BuiltinId,
    comptime left_role: DenseSourceRole,
    comptime right_role: DenseSourceRole,
    ctx: *const DenseProducerContext(T),
    base: usize,
    active: usize,
) u64 {
    const lane_count = host_compare_zig_vector_bytes / @sizeOf(T);
    const Left = DenseSourceProducer(T, lane_count, left_role);
    const Right = DenseSourceProducer(T, lane_count, right_role);
    const Producer = DenseCompareProducer(T, lane_count, op, Left, Right);

    var word: u64 = 0;
    var bit: usize = 0;
    const vector_limit = active - (active % lane_count);
    while (bit < vector_limit) : (bit += lane_count) {
        const mask = Producer.evalMask(ctx, base + bit);
        word |= @as(u64, mask) << @intCast(bit);
    }
    while (bit < active) : (bit += 1) {
        if (Producer.evalScalar(ctx, base + bit)) {
            word |= @as(u64, 1) << @intCast(bit);
        }
    }
    return word;
}

fn fillDenseFloatCompareSourceRolesOp(
    comptime T: type,
    comptime op: BuiltinId,
    comptime left_role: DenseSourceRole,
    comptime right_role: DenseSourceRole,
    out: *HostBitAlloc,
    len: usize,
    ctx: *const DenseProducerContext(T),
) HostCompareSummary {
    var summary = hostCompareSummaryEmpty();
    for (out.words, 0..) |*out_word, word_idx| {
        const active = bitWordActiveLen(len, word_idx, out.words.len);
        const base = word_idx * host_bit_word_bits;
        const word = denseFloatCompareSourceRolesWord(T, op, left_role, right_role, ctx, base, active);
        out_word.* = word;
        hostCompareSummaryNoteWord(&summary, word, active);
    }
    return summary;
}

fn fillDenseFloatCompareSourcesOp(comptime T: type, comptime op: BuiltinId, out: *HostBitAlloc, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) ?HostCompareSummary {
    if (out.len != len) return null;
    const source_len = denseFloatResolvedSourcesLen(T, left, right) orelse return null;
    if (source_len != len) return null;

    var ctx = denseFloatSourceContext(T, left, right);
    return switch (left) {
        .array => switch (right) {
            .array => fillDenseFloatCompareSourceRolesOp(T, op, .left_array, .right_array, out, len, &ctx),
            .reverse_array => fillDenseFloatCompareSourceRolesOp(T, op, .left_array, .right_reverse_array, out, len, &ctx),
            .scalar => fillDenseFloatCompareSourceRolesOp(T, op, .left_array, .right_scalar, out, len, &ctx),
        },
        .reverse_array => switch (right) {
            .array => fillDenseFloatCompareSourceRolesOp(T, op, .left_reverse_array, .right_array, out, len, &ctx),
            .reverse_array => fillDenseFloatCompareSourceRolesOp(T, op, .left_reverse_array, .right_reverse_array, out, len, &ctx),
            .scalar => fillDenseFloatCompareSourceRolesOp(T, op, .left_reverse_array, .right_scalar, out, len, &ctx),
        },
        .scalar => switch (right) {
            .array => fillDenseFloatCompareSourceRolesOp(T, op, .left_scalar, .right_array, out, len, &ctx),
            .reverse_array => fillDenseFloatCompareSourceRolesOp(T, op, .left_scalar, .right_reverse_array, out, len, &ctx),
            .scalar => null,
        },
    };
}

fn fillDenseFloatCompareSources(comptime T: type, out: *HostBitAlloc, op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) ?HostCompareSummary {
    return switch (op) {
        .equal => fillDenseFloatCompareSourcesOp(T, .equal, out, left, right, len),
        .less => fillDenseFloatCompareSourcesOp(T, .less, out, left, right, len),
        .more => fillDenseFloatCompareSourcesOp(T, .more, out, left, right, len),
        else => null,
    };
}

fn runDenseFloatSourceUnarySinkOp(comptime T: type, comptime op: BuiltinId, source: DenseResolvedSource(T), len: usize, sink: anytype) void {
    var ctx = denseFloatSourceContext(T, source, .{ .scalar = @as(T, 0) });
    switch (source) {
        .array => runDenseFloatUnarySourceRolesSink(T, op, .left_array, len, &ctx, sink),
        .reverse_array => runDenseFloatUnarySourceRolesSink(T, op, .left_reverse_array, len, &ctx, sink),
        .scalar => unreachable,
    }
}

fn runDenseFloatSquaredDiffSourceSink(comptime T: type, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize, sink: anytype) void {
    var ctx = denseFloatSourceContext(T, left, right);
    switch (left) {
        .array => switch (right) {
            .array => runDenseFloatSquaredDiffSourceRolesSink(T, .left_array, .right_array, len, &ctx, sink),
            .reverse_array => runDenseFloatSquaredDiffSourceRolesSink(T, .left_array, .right_reverse_array, len, &ctx, sink),
            .scalar => runDenseFloatSquaredDiffSourceRolesSink(T, .left_array, .right_scalar, len, &ctx, sink),
        },
        .reverse_array => switch (right) {
            .array => runDenseFloatSquaredDiffSourceRolesSink(T, .left_reverse_array, .right_array, len, &ctx, sink),
            .reverse_array => runDenseFloatSquaredDiffSourceRolesSink(T, .left_reverse_array, .right_reverse_array, len, &ctx, sink),
            .scalar => runDenseFloatSquaredDiffSourceRolesSink(T, .left_reverse_array, .right_scalar, len, &ctx, sink),
        },
        .scalar => switch (right) {
            .array => runDenseFloatSquaredDiffSourceRolesSink(T, .left_scalar, .right_array, len, &ctx, sink),
            .reverse_array => runDenseFloatSquaredDiffSourceRolesSink(T, .left_scalar, .right_reverse_array, len, &ctx, sink),
            .scalar => unreachable,
        },
    }
}

fn foldAddMapFloatSourcesOp(comptime T: type, comptime op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) T {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    var sink = DenseFloatAddReduceSink(T, lane_count){};
    runDenseFloatSourceMapSinkOp(T, op, left, right, len, &sink);
    return sink.finish();
}

fn foldAddUnaryFloatSourceOp(comptime T: type, comptime op: BuiltinId, source: DenseResolvedSource(T), len: usize) T {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    var sink = DenseFloatAddReduceSink(T, lane_count){};
    runDenseFloatSourceUnarySinkOp(T, op, source, len, &sink);
    return sink.finish();
}

fn foldAddMapFloatSources(comptime T: type, op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) T {
    return switch (op) {
        .add => foldAddMapFloatSourcesOp(T, .add, left, right, len),
        .sub => foldAddMapFloatSourcesOp(T, .sub, left, right, len),
        .minimum => foldAddMapFloatSourcesOp(T, .minimum, left, right, len),
        .maximum => foldAddMapFloatSourcesOp(T, .maximum, left, right, len),
        .mul => foldAddMapFloatSourcesOp(T, .mul, left, right, len),
        .div => foldAddMapFloatSourcesOp(T, .div, left, right, len),
        else => unreachable,
    };
}

fn foldAddUnaryFloatSource(comptime T: type, op: BuiltinId, source: DenseResolvedSource(T), len: usize) T {
    return switch (op) {
        .add => foldAddUnaryFloatSourceOp(T, .add, source, len),
        .sub => foldAddUnaryFloatSourceOp(T, .sub, source, len),
        .div => foldAddUnaryFloatSourceOp(T, .div, source, len),
        else => unreachable,
    };
}

fn foldAddSquaredDiffFloatSources(comptime T: type, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) T {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    var sink = DenseFloatAddReduceSink(T, lane_count){};
    runDenseFloatSquaredDiffSourceSink(T, left, right, len, &sink);
    return sink.finish();
}

fn foldAddMapFloatSourcesMorselKernel(comptime T: type, comptime op: BuiltinId) type {
    return struct {
        const Ctx = struct {
            left: DenseResolvedSource(T),
            right: DenseResolvedSource(T),
            partials: []T,
            grain: usize,
            len: usize,
        };

        fn run(ctx: Ctx, range: MorselRange) void {
            const partial_idx = range.start / ctx.grain;
            const left = denseFloatSliceResolvedSource(T, ctx.left, range, ctx.len);
            const right = denseFloatSliceResolvedSource(T, ctx.right, range, ctx.len);
            ctx.partials[partial_idx] = foldAddMapFloatSources(T, op, left, right, range.end - range.start);
        }
    };
}

fn foldAddUnaryFloatSourceMorselKernel(comptime T: type, comptime op: BuiltinId) type {
    return struct {
        const Ctx = struct {
            source: DenseResolvedSource(T),
            partials: []T,
            grain: usize,
            len: usize,
        };

        fn run(ctx: Ctx, range: MorselRange) void {
            const partial_idx = range.start / ctx.grain;
            const source = denseFloatSliceResolvedSource(T, ctx.source, range, ctx.len);
            ctx.partials[partial_idx] = foldAddUnaryFloatSource(T, op, source, range.end - range.start);
        }
    };
}

fn foldAddSquaredDiffFloatSourcesMorselKernel(comptime T: type) type {
    return struct {
        const Ctx = struct {
            left: DenseResolvedSource(T),
            right: DenseResolvedSource(T),
            partials: []T,
            grain: usize,
            len: usize,
        };

        fn run(ctx: Ctx, range: MorselRange) void {
            const partial_idx = range.start / ctx.grain;
            const left = denseFloatSliceResolvedSource(T, ctx.left, range, ctx.len);
            const right = denseFloatSliceResolvedSource(T, ctx.right, range, ctx.len);
            ctx.partials[partial_idx] = foldAddSquaredDiffFloatSources(T, left, right, range.end - range.start);
        }
    };
}

fn denseFloatMorselPartials(session: *Session, comptime T: type, count: usize) KError![]T {
    if (comptime T == f64) return try session.morselF64Partials(count);
    if (comptime T == f32) return try session.morselF32Partials(count);
    @compileError("unsupported dense float type");
}

fn foldAddMapFloatSourcesMorselOp(session: *Session, comptime T: type, op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize, workers_requested: usize) KError!T {
    if (len == 0) return error.Type;
    const grain = normalizeMorselGrain(len, default_morsel_grain);
    const morsel_count = countMorsels(len, grain);
    const partials = try denseFloatMorselPartials(session, T, morsel_count);

    switch (op) {
        .add => {
            const Kernel = foldAddMapFloatSourcesMorselKernel(T, .add);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .sub => {
            const Kernel = foldAddMapFloatSourcesMorselKernel(T, .sub);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .minimum => {
            const Kernel = foldAddMapFloatSourcesMorselKernel(T, .minimum);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .maximum => {
            const Kernel = foldAddMapFloatSourcesMorselKernel(T, .maximum);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .mul => {
            const Kernel = foldAddMapFloatSourcesMorselKernel(T, .mul);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .div => {
            const Kernel = foldAddMapFloatSourcesMorselKernel(T, .div);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        else => unreachable,
    }

    var total: T = 0;
    for (partials) |partial| total += partial;
    return total;
}

fn foldAddUnaryFloatSourceMorselOp(session: *Session, comptime T: type, op: BuiltinId, source: DenseResolvedSource(T), len: usize, workers_requested: usize) KError!T {
    if (len == 0) return error.Type;
    const grain = normalizeMorselGrain(len, default_morsel_grain);
    const morsel_count = countMorsels(len, grain);
    const partials = try denseFloatMorselPartials(session, T, morsel_count);

    switch (op) {
        .add => {
            const Kernel = foldAddUnaryFloatSourceMorselKernel(T, .add);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .source = source, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .sub => {
            const Kernel = foldAddUnaryFloatSourceMorselKernel(T, .sub);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .source = source, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        .div => {
            const Kernel = foldAddUnaryFloatSourceMorselKernel(T, .div);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .source = source, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;
        },
        else => unreachable,
    }

    var total: T = 0;
    for (partials) |partial| total += partial;
    return total;
}

fn foldAddSquaredDiffFloatSourcesMorselOp(session: *Session, comptime T: type, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize, workers_requested: usize) KError!T {
    if (len == 0) return error.Type;
    const grain = normalizeMorselGrain(len, default_morsel_grain);
    const morsel_count = countMorsels(len, grain);
    const partials = try denseFloatMorselPartials(session, T, morsel_count);

    const Kernel = foldAddSquaredDiffFloatSourcesMorselKernel(T);
    session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .left = left, .right = right, .partials = partials, .grain = grain, .len = len }, Kernel.run) catch return error.Internal;

    var total: T = 0;
    for (partials) |partial| total += partial;
    return total;
}

fn fillDenseFloatSourcesStoreOp(comptime T: type, comptime op: BuiltinId, out: []T, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    var sink = DenseFloatStoreSink(T, lane_count){ .out = out };
    switch (left) {
        .array => |left_items| switch (right) {
            .array => |right_items| {
                runDenseFloatArrayArrayProducerSink(T, op, left_items, right_items, &sink);
                return;
            },
            else => {},
        },
        else => {},
    }
    runDenseFloatSourceMapSinkOp(T, op, left, right, len, &sink);
}

fn fillDenseFloatSourcesStoreScalarOp(comptime T: type, comptime op: BuiltinId, out: []T, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) void {
    for (out[0..len], 0..) |*dest, idx| {
        dest.* = applyDenseFloatTypedOp(
            T,
            op,
            denseFloatResolvedSourceScalarItem(T, left, idx),
            denseFloatResolvedSourceScalarItem(T, right, idx),
        );
    }
}

fn fillDenseFloatSourcesStoreScalar(comptime T: type, out: []T, op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) void {
    switch (op) {
        .add => fillDenseFloatSourcesStoreScalarOp(T, .add, out, left, right, len),
        .sub => fillDenseFloatSourcesStoreScalarOp(T, .sub, out, left, right, len),
        .minimum => fillDenseFloatSourcesStoreScalarOp(T, .minimum, out, left, right, len),
        .maximum => fillDenseFloatSourcesStoreScalarOp(T, .maximum, out, left, right, len),
        .mul => fillDenseFloatSourcesStoreScalarOp(T, .mul, out, left, right, len),
        .div => fillDenseFloatSourcesStoreScalarOp(T, .div, out, left, right, len),
        else => unreachable,
    }
}

fn fillDenseFloatSourcesStore(comptime T: type, out: []T, op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) void {
    switch (op) {
        .add => fillDenseFloatSourcesStoreOp(T, .add, out, left, right, len),
        .sub => fillDenseFloatSourcesStoreOp(T, .sub, out, left, right, len),
        .minimum => fillDenseFloatSourcesStoreOp(T, .minimum, out, left, right, len),
        .maximum => fillDenseFloatSourcesStoreOp(T, .maximum, out, left, right, len),
        .mul => fillDenseFloatSourcesStoreOp(T, .mul, out, left, right, len),
        .div => fillDenseFloatSourcesStoreOp(T, .div, out, left, right, len),
        else => unreachable,
    }
}

fn fillDenseFloatSourceUnaryStoreOp(comptime T: type, comptime op: BuiltinId, out: []T, source: DenseResolvedSource(T), len: usize) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    var sink = DenseFloatStoreSink(T, lane_count){ .out = out };
    runDenseFloatSourceUnarySinkOp(T, op, source, len, &sink);
}

fn applyDenseFloatTypedUnaryFallbackOp(comptime T: type, comptime op: BuiltinId, value: T) T {
    return switch (op) {
        .add, .sub, .div => applyDenseFloatTypedUnaryOp(T, op, value),
        .exp, .log, .sin, .cos, .tanh, .sigmoid => @floatCast(applyFloatMonadOp(op, @as(f64, @floatCast(value)))),
        else => unreachable,
    };
}

fn fillDenseFloatSourceUnaryStoreScalarOp(comptime T: type, comptime op: BuiltinId, out: []T, source: DenseResolvedSource(T), len: usize) void {
    for (out[0..len], 0..) |*dest, idx| {
        dest.* = applyDenseFloatTypedUnaryFallbackOp(T, op, denseFloatResolvedSourceScalarItem(T, source, idx));
    }
}

fn fillDenseFloatSourceUnaryStoreAny(comptime T: type, out: []T, op: BuiltinId, source: DenseResolvedSource(T), len: usize) void {
    switch (op) {
        .add => fillDenseFloatSourceUnaryStoreOp(T, .add, out, source, len),
        .sub => fillDenseFloatSourceUnaryStoreOp(T, .sub, out, source, len),
        .div => fillDenseFloatSourceUnaryStoreOp(T, .div, out, source, len),
        .exp => fillDenseFloatSourceUnaryStoreScalarOp(T, .exp, out, source, len),
        .log => fillDenseFloatSourceUnaryStoreScalarOp(T, .log, out, source, len),
        .sin => fillDenseFloatSourceUnaryStoreScalarOp(T, .sin, out, source, len),
        .cos => fillDenseFloatSourceUnaryStoreScalarOp(T, .cos, out, source, len),
        .tanh => fillDenseFloatSourceUnaryStoreScalarOp(T, .tanh, out, source, len),
        .sigmoid => fillDenseFloatSourceUnaryStoreScalarOp(T, .sigmoid, out, source, len),
        else => unreachable,
    }
}

fn fillDenseFloatSourcesStoreMorselKernel(comptime T: type, comptime op: BuiltinId) type {
    return struct {
        const Ctx = struct {
            out: []T,
            left: DenseResolvedSource(T),
            right: DenseResolvedSource(T),
            len: usize,
        };

        fn run(ctx: Ctx, range: MorselRange) void {
            const left = denseFloatSliceResolvedSource(T, ctx.left, range, ctx.len);
            const right = denseFloatSliceResolvedSource(T, ctx.right, range, ctx.len);
            fillDenseFloatSourcesStoreOp(T, op, ctx.out[range.start..range.end], left, right, range.end - range.start);
        }
    };
}

fn fillDenseFloatSourcesStoreMorsel(session: *Session, comptime T: type, out: []T, op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize, workers_requested: usize) void {
    const grain = normalizeMorselGrain(len, default_morsel_grain);
    switch (op) {
        .add => {
            const Kernel = fillDenseFloatSourcesStoreMorselKernel(T, .add);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .out = out, .left = left, .right = right, .len = len }, Kernel.run) catch unreachable;
        },
        .sub => {
            const Kernel = fillDenseFloatSourcesStoreMorselKernel(T, .sub);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .out = out, .left = left, .right = right, .len = len }, Kernel.run) catch unreachable;
        },
        .minimum => {
            const Kernel = fillDenseFloatSourcesStoreMorselKernel(T, .minimum);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .out = out, .left = left, .right = right, .len = len }, Kernel.run) catch unreachable;
        },
        .maximum => {
            const Kernel = fillDenseFloatSourcesStoreMorselKernel(T, .maximum);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .out = out, .left = left, .right = right, .len = len }, Kernel.run) catch unreachable;
        },
        .mul => {
            const Kernel = fillDenseFloatSourcesStoreMorselKernel(T, .mul);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .out = out, .left = left, .right = right, .len = len }, Kernel.run) catch unreachable;
        },
        .div => {
            const Kernel = fillDenseFloatSourcesStoreMorselKernel(T, .div);
            session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .out = out, .left = left, .right = right, .len = len }, Kernel.run) catch unreachable;
        },
        else => unreachable,
    }
}

fn denseIntBinaryVec(comptime op: BuiltinId, lhs: anytype, rhs: @TypeOf(lhs)) @TypeOf(lhs) {
    return switch (op) {
        .add => lhs + rhs,
        .sub => lhs - rhs,
        .minimum => @min(lhs, rhs),
        .maximum => @max(lhs, rhs),
        .mul => lhs * rhs,
        else => unreachable,
    };
}

fn denseIntResolvedSourceLen(comptime T: type, source: DenseResolvedSource(T)) ?usize {
    return switch (source) {
        .array => |items| items.len,
        .reverse_array => |items| items.len,
        .scalar => null,
    };
}

fn denseIntResolvedSourcesLen(comptime T: type, left: DenseResolvedSource(T), right: DenseResolvedSource(T)) ?usize {
    const left_len = denseIntResolvedSourceLen(T, left);
    const right_len = denseIntResolvedSourceLen(T, right);
    if (left_len == null and right_len == null) return null;
    if (left_len) |len| {
        if (right_len) |other_len| {
            if (len != other_len) return null;
        }
        return len;
    }
    return right_len.?;
}

fn denseIntSliceResolvedSource(comptime T: type, source: DenseResolvedSource(T), range: MorselRange, full_len: usize) DenseResolvedSource(T) {
    return switch (source) {
        .array => |items| .{ .array = items[range.start..range.end] },
        .reverse_array => |items| .{ .reverse_array = items[full_len - range.end .. full_len - range.start] },
        .scalar => |value| .{ .scalar = value },
    };
}

fn denseIntResolvedSourceScalarItem(comptime T: type, source: DenseResolvedSource(T), idx: usize) T {
    return switch (source) {
        .array => |items| items[idx],
        .reverse_array => |items| items[items.len - 1 - idx],
        .scalar => |value| value,
    };
}

fn denseIntSourceStoreCanVectorize(comptime T: type, comptime op: BuiltinId) bool {
    if (!denseIntSimdSupported(op)) return false;
    if (comptime op == .mul and T == i64) return false;
    if (comptime enable_dense_dyad_i8_mul_wasm_vectorized and T == i8 and op == .mul) return false;
    return true;
}

fn denseIntSourceContext(comptime T: type, left: DenseResolvedSource(T), right: DenseResolvedSource(T)) DenseProducerContext(T) {
    var ctx = DenseProducerContext(T){
        .left_items = &.{},
        .right_items = &.{},
    };
    switch (left) {
        .array => |items| ctx.left_items = items,
        .reverse_array => |items| ctx.left_items = items,
        .scalar => |value| ctx.left_scalar = value,
    }
    switch (right) {
        .array => |items| ctx.right_items = items,
        .reverse_array => |items| ctx.right_items = items,
        .scalar => |value| ctx.right_scalar = value,
    }
    return ctx;
}

fn DenseIntBinaryProducer(comptime T: type, comptime lane_count: usize, comptime op: BuiltinId, comptime Left: type, comptime Right: type) type {
    const Vec = @Vector(lane_count, T);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            return denseIntBinaryVec(op, Left.evalVec(ctx, idx), Right.evalVec(ctx, idx));
        }

        fn evalScalar(ctx: anytype, idx: usize) T {
            return applyIntOpUncheckedTyped(T, op, Left.evalScalar(ctx, idx), Right.evalScalar(ctx, idx));
        }
    };
}

fn DenseMixedIntResolvedSource(comptime T: type) type {
    return union(enum) {
        array: []const T,
        reverse_array: []const T,
    };
}

fn denseMixedIntSourceFromResolved(comptime T: type, source: DenseResolvedSource(T)) ?DenseMixedIntResolvedSource(T) {
    return switch (source) {
        .array => |items| .{ .array = items },
        .reverse_array => |items| .{ .reverse_array = items },
        .scalar => null,
    };
}

const DenseMixedIntSourceRole = enum {
    array,
    reverse_array,
};

fn denseMixedIntResolvedSourceLen(comptime T: type, source: DenseMixedIntResolvedSource(T)) usize {
    return switch (source) {
        .array => |items| items.len,
        .reverse_array => |items| items.len,
    };
}

fn DenseMixedIntProducerContext(comptime LeftT: type, comptime RightT: type) type {
    return struct {
        left_items: []const LeftT,
        right_items: []const RightT,
    };
}

fn denseMixedIntSourceContext(comptime LeftT: type, comptime RightT: type, left: DenseMixedIntResolvedSource(LeftT), right: DenseMixedIntResolvedSource(RightT)) DenseMixedIntProducerContext(LeftT, RightT) {
    return .{
        .left_items = switch (left) {
            .array => |items| items,
            .reverse_array => |items| items,
        },
        .right_items = switch (right) {
            .array => |items| items,
            .reverse_array => |items| items,
        },
    };
}

fn DenseMixedIntLeftSourceProducer(comptime LeftT: type, comptime WideT: type, comptime lane_count: usize, comptime role: DenseMixedIntSourceRole) type {
    const Vec = @Vector(lane_count, WideT);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            return switch (role) {
                .array => hostCompareIntLoadAs(LeftT, WideT, lane_count, ctx.left_items, idx),
                .reverse_array => blk: {
                    const reverse_base = ctx.left_items.len - idx - lane_count;
                    const chunk = hostCompareIntLoadAs(LeftT, WideT, lane_count, ctx.left_items, reverse_base);
                    break :blk reversedDenseVector(WideT, lane_count, chunk);
                },
            };
        }

        fn evalScalar(ctx: anytype, idx: usize) WideT {
            return switch (role) {
                .array => @intCast(ctx.left_items[idx]),
                .reverse_array => @intCast(ctx.left_items[ctx.left_items.len - 1 - idx]),
            };
        }
    };
}

fn DenseMixedIntRightSourceProducer(comptime RightT: type, comptime WideT: type, comptime lane_count: usize, comptime role: DenseMixedIntSourceRole) type {
    const Vec = @Vector(lane_count, WideT);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            return switch (role) {
                .array => hostCompareIntLoadAs(RightT, WideT, lane_count, ctx.right_items, idx),
                .reverse_array => blk: {
                    const reverse_base = ctx.right_items.len - idx - lane_count;
                    const chunk = hostCompareIntLoadAs(RightT, WideT, lane_count, ctx.right_items, reverse_base);
                    break :blk reversedDenseVector(WideT, lane_count, chunk);
                },
            };
        }

        fn evalScalar(ctx: anytype, idx: usize) WideT {
            return switch (role) {
                .array => @intCast(ctx.right_items[idx]),
                .reverse_array => @intCast(ctx.right_items[ctx.right_items.len - 1 - idx]),
            };
        }
    };
}

fn runDenseIntProducerSink(comptime lane_count: usize, comptime Producer: type, len: usize, ctx: anytype, sink: anytype) void {
    var idx: usize = 0;
    const vector_limit = len - (len % lane_count);
    while (idx < vector_limit) : (idx += lane_count) {
        sink.consumeVec(idx, Producer.evalVec(ctx, idx));
    }
    while (idx < len) : (idx += 1) {
        sink.consumeScalar(idx, Producer.evalScalar(ctx, idx));
    }
}

fn denseIntCompareSourceRolesWord(
    comptime T: type,
    comptime op: BuiltinId,
    comptime left_role: DenseSourceRole,
    comptime right_role: DenseSourceRole,
    ctx: *const DenseProducerContext(T),
    base: usize,
    active: usize,
) u64 {
    const lane_count = host_compare_zig_vector_bytes / @sizeOf(T);
    const Left = DenseSourceProducer(T, lane_count, left_role);
    const Right = DenseSourceProducer(T, lane_count, right_role);
    const Producer = DenseCompareProducer(T, lane_count, op, Left, Right);

    var word: u64 = 0;
    var bit: usize = 0;
    const vector_limit = active - (active % lane_count);
    while (bit < vector_limit) : (bit += lane_count) {
        const mask = Producer.evalMask(ctx, base + bit);
        word |= @as(u64, mask) << @intCast(bit);
    }
    while (bit < active) : (bit += 1) {
        if (Producer.evalScalar(ctx, base + bit)) {
            word |= @as(u64, 1) << @intCast(bit);
        }
    }
    return word;
}

fn denseMixedIntCompareSourceRolesWord(
    comptime LeftT: type,
    comptime RightT: type,
    comptime op: BuiltinId,
    comptime left_role: DenseMixedIntSourceRole,
    comptime right_role: DenseMixedIntSourceRole,
    ctx: *const DenseMixedIntProducerContext(LeftT, RightT),
    base: usize,
    active: usize,
) u64 {
    const WideT = hostCompareIntWideType(LeftT, RightT);
    const lane_count = host_compare_zig_vector_bytes / @sizeOf(WideT);
    const Left = DenseMixedIntLeftSourceProducer(LeftT, WideT, lane_count, left_role);
    const Right = DenseMixedIntRightSourceProducer(RightT, WideT, lane_count, right_role);
    const Producer = DenseCompareProducer(WideT, lane_count, op, Left, Right);

    var word: u64 = 0;
    var bit: usize = 0;
    const vector_limit = active - (active % lane_count);
    while (bit < vector_limit) : (bit += lane_count) {
        const mask = Producer.evalMask(ctx, base + bit);
        word |= @as(u64, mask) << @intCast(bit);
    }
    while (bit < active) : (bit += 1) {
        if (Producer.evalScalar(ctx, base + bit)) {
            word |= @as(u64, 1) << @intCast(bit);
        }
    }
    return word;
}

fn fillDenseMixedIntCompareSourceRolesOp(
    comptime LeftT: type,
    comptime RightT: type,
    comptime op: BuiltinId,
    comptime left_role: DenseMixedIntSourceRole,
    comptime right_role: DenseMixedIntSourceRole,
    out: *HostBitAlloc,
    len: usize,
    ctx: *const DenseMixedIntProducerContext(LeftT, RightT),
) HostCompareSummary {
    var summary = hostCompareSummaryEmpty();
    for (out.words, 0..) |*out_word, word_idx| {
        const active = bitWordActiveLen(len, word_idx, out.words.len);
        const base = word_idx * host_bit_word_bits;
        const word = denseMixedIntCompareSourceRolesWord(LeftT, RightT, op, left_role, right_role, ctx, base, active);
        out_word.* = word;
        hostCompareSummaryNoteWord(&summary, word, active);
    }
    return summary;
}

fn fillDenseMixedIntCompareSourcesOp(comptime LeftT: type, comptime RightT: type, comptime op: BuiltinId, out: *HostBitAlloc, left: DenseMixedIntResolvedSource(LeftT), right: DenseMixedIntResolvedSource(RightT), len: usize) ?HostCompareSummary {
    if (out.len != len) return null;
    if (denseMixedIntResolvedSourceLen(LeftT, left) != len or denseMixedIntResolvedSourceLen(RightT, right) != len) return null;

    var ctx = denseMixedIntSourceContext(LeftT, RightT, left, right);
    return switch (left) {
        .array => switch (right) {
            .array => fillDenseMixedIntCompareSourceRolesOp(LeftT, RightT, op, .array, .array, out, len, &ctx),
            .reverse_array => fillDenseMixedIntCompareSourceRolesOp(LeftT, RightT, op, .array, .reverse_array, out, len, &ctx),
        },
        .reverse_array => switch (right) {
            .array => fillDenseMixedIntCompareSourceRolesOp(LeftT, RightT, op, .reverse_array, .array, out, len, &ctx),
            .reverse_array => fillDenseMixedIntCompareSourceRolesOp(LeftT, RightT, op, .reverse_array, .reverse_array, out, len, &ctx),
        },
    };
}

fn fillDenseMixedIntCompareSources(comptime LeftT: type, comptime RightT: type, out: *HostBitAlloc, op: BuiltinId, left: DenseMixedIntResolvedSource(LeftT), right: DenseMixedIntResolvedSource(RightT), len: usize) ?HostCompareSummary {
    return switch (op) {
        .equal => fillDenseMixedIntCompareSourcesOp(LeftT, RightT, .equal, out, left, right, len),
        .less => fillDenseMixedIntCompareSourcesOp(LeftT, RightT, .less, out, left, right, len),
        .more => fillDenseMixedIntCompareSourcesOp(LeftT, RightT, .more, out, left, right, len),
        else => null,
    };
}

fn DenseIntCastProducerContext(comptime LeftT: type, comptime RightT: type) type {
    return struct {
        left_items: []const LeftT = &.{},
        right_items: []const RightT = &.{},
        left_scalar: LeftT = 0,
        right_scalar: RightT = 0,
    };
}

fn denseIntCastSourceContext(comptime LeftT: type, comptime RightT: type, left: DenseResolvedSource(LeftT), right: DenseResolvedSource(RightT)) DenseIntCastProducerContext(LeftT, RightT) {
    var ctx = DenseIntCastProducerContext(LeftT, RightT){};
    switch (left) {
        .array => |items| ctx.left_items = items,
        .reverse_array => |items| ctx.left_items = items,
        .scalar => |value| ctx.left_scalar = value,
    }
    switch (right) {
        .array => |items| ctx.right_items = items,
        .reverse_array => |items| ctx.right_items = items,
        .scalar => |value| ctx.right_scalar = value,
    }
    return ctx;
}

const DenseIntCastSourceSide = enum { left, right };

fn DenseIntCastSourceProducer(comptime InT: type, comptime OutT: type, comptime lane_count: usize, comptime role: DenseSourceRole, comptime side: DenseIntCastSourceSide) type {
    comptime {
        switch (side) {
            .left => switch (role) {
                .left_array, .left_reverse_array, .left_scalar => {},
                else => @compileError("left cast producer requires a left role"),
            },
            .right => switch (role) {
                .right_array, .right_reverse_array, .right_scalar => {},
                else => @compileError("right cast producer requires a right role"),
            },
        }
    }
    const Vec = @Vector(lane_count, OutT);
    return struct {
        fn evalVec(ctx: anytype, idx: usize) Vec {
            const source_items = if (comptime side == .left) ctx.left_items else ctx.right_items;
            return switch (role) {
                .left_array, .right_array => hostCompareIntLoadAs(InT, OutT, lane_count, source_items, idx),
                .left_reverse_array, .right_reverse_array => blk: {
                    const reverse_base = source_items.len - idx - lane_count;
                    const chunk = hostCompareIntLoadAs(InT, OutT, lane_count, source_items, reverse_base);
                    break :blk reversedDenseVector(OutT, lane_count, chunk);
                },
                .left_scalar, .right_scalar => @splat(@as(OutT, @intCast(if (comptime side == .left) ctx.left_scalar else ctx.right_scalar))),
            };
        }

        fn evalScalar(ctx: anytype, idx: usize) OutT {
            const source_items = if (comptime side == .left) ctx.left_items else ctx.right_items;
            return switch (role) {
                .left_array, .right_array => @intCast(source_items[idx]),
                .left_reverse_array, .right_reverse_array => @intCast(source_items[source_items.len - 1 - idx]),
                .left_scalar, .right_scalar => @intCast(if (comptime side == .left) ctx.left_scalar else ctx.right_scalar),
            };
        }
    };
}

fn denseIntCastSourceRole(comptime T: type, source: DenseResolvedSource(T), comptime side: DenseIntCastSourceSide) DenseSourceRole {
    return switch (side) {
        .left => switch (source) {
            .array => .left_array,
            .reverse_array => .left_reverse_array,
            .scalar => .left_scalar,
        },
        .right => switch (source) {
            .array => .right_array,
            .reverse_array => .right_reverse_array,
            .scalar => .right_scalar,
        },
    };
}

fn runDenseIntCastMapSourceRolesSink(
    comptime OutT: type,
    comptime LeftT: type,
    comptime RightT: type,
    comptime op: BuiltinId,
    comptime left_role: DenseSourceRole,
    comptime right_role: DenseSourceRole,
    len: usize,
    ctx: *const DenseIntCastProducerContext(LeftT, RightT),
    sink: anytype,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(OutT);
    const Left = DenseIntCastSourceProducer(LeftT, OutT, lane_count, left_role, .left);
    const Right = DenseIntCastSourceProducer(RightT, OutT, lane_count, right_role, .right);
    const Producer = DenseIntBinaryProducer(OutT, lane_count, op, Left, Right);
    runDenseIntProducerSink(lane_count, Producer, len, ctx, sink);
}

fn runDenseIntCastSourceMapSinkOp(
    comptime OutT: type,
    comptime LeftT: type,
    comptime RightT: type,
    comptime op: BuiltinId,
    left: DenseResolvedSource(LeftT),
    right: DenseResolvedSource(RightT),
    len: usize,
    sink: anytype,
) void {
    var ctx = denseIntCastSourceContext(LeftT, RightT, left, right);
    const left_role = denseIntCastSourceRole(LeftT, left, .left);
    const right_role = denseIntCastSourceRole(RightT, right, .right);
    inline for (.{ .left_array, .left_reverse_array, .left_scalar }) |LeftRole| {
        if (left_role == LeftRole) {
            inline for (.{ .right_array, .right_reverse_array, .right_scalar }) |RightRole| {
                if (right_role == RightRole) {
                    runDenseIntCastMapSourceRolesSink(OutT, LeftT, RightT, op, LeftRole, RightRole, len, &ctx, sink);
                    return;
                }
            }
        }
    }
    unreachable;
}

fn denseIntCastSourceScalarItem(comptime InT: type, comptime OutT: type, source: DenseResolvedSource(InT), idx: usize) OutT {
    return @intCast(denseIntResolvedSourceScalarItem(InT, source, idx));
}

fn fillDenseIntCastSourcesStoreScalarOp(comptime OutT: type, comptime LeftT: type, comptime RightT: type, comptime op: BuiltinId, out: []OutT, left: DenseResolvedSource(LeftT), right: DenseResolvedSource(RightT), len: usize) void {
    for (out[0..len], 0..) |*dest, idx| {
        dest.* = applyIntOpUncheckedTyped(
            OutT,
            op,
            denseIntCastSourceScalarItem(LeftT, OutT, left, idx),
            denseIntCastSourceScalarItem(RightT, OutT, right, idx),
        );
    }
}

fn fillDenseIntCastSourcesStoreOp(comptime OutT: type, comptime LeftT: type, comptime RightT: type, comptime op: BuiltinId, out: []OutT, left: DenseResolvedSource(LeftT), right: DenseResolvedSource(RightT), len: usize) void {
    if (comptime !denseIntSourceStoreCanVectorize(OutT, op)) {
        fillDenseIntCastSourcesStoreScalarOp(OutT, LeftT, RightT, op, out, left, right, len);
        return;
    }

    const lane_count = dense_host_simd_bytes / @sizeOf(OutT);
    var sink = DenseIntStoreSink(OutT, lane_count){ .out = out };
    runDenseIntCastSourceMapSinkOp(OutT, LeftT, RightT, op, left, right, len, &sink);
}

fn fillDenseIntCastSourcesStore(comptime OutT: type, comptime LeftT: type, comptime RightT: type, out: []OutT, op: BuiltinId, left: DenseResolvedSource(LeftT), right: DenseResolvedSource(RightT), len: usize) void {
    switch (op) {
        .add => fillDenseIntCastSourcesStoreOp(OutT, LeftT, RightT, .add, out, left, right, len),
        .sub => fillDenseIntCastSourcesStoreOp(OutT, LeftT, RightT, .sub, out, left, right, len),
        .minimum => fillDenseIntCastSourcesStoreOp(OutT, LeftT, RightT, .minimum, out, left, right, len),
        .maximum => fillDenseIntCastSourcesStoreOp(OutT, LeftT, RightT, .maximum, out, left, right, len),
        .mul => fillDenseIntCastSourcesStoreOp(OutT, LeftT, RightT, .mul, out, left, right, len),
        else => unreachable,
    }
}

fn fillDenseIntCastSourcesStoreMorselKernel(comptime OutT: type, comptime LeftT: type, comptime RightT: type, comptime op: BuiltinId) type {
    return struct {
        const Ctx = struct {
            out: []OutT,
            left: DenseResolvedSource(LeftT),
            right: DenseResolvedSource(RightT),
            len: usize,
        };

        fn run(ctx: Ctx, range: MorselRange) void {
            const left = denseIntSliceResolvedSource(LeftT, ctx.left, range, ctx.len);
            const right = denseIntSliceResolvedSource(RightT, ctx.right, range, ctx.len);
            fillDenseIntCastSourcesStoreOp(OutT, LeftT, RightT, op, ctx.out[range.start..range.end], left, right, range.end - range.start);
        }
    };
}

fn runDenseIntCastSourcesStoreMorselOp(session: *Session, comptime OutT: type, comptime LeftT: type, comptime RightT: type, comptime op: BuiltinId, out: []OutT, left: DenseResolvedSource(LeftT), right: DenseResolvedSource(RightT), len: usize, workers_requested: usize) void {
    const grain = normalizeMorselGrain(len, default_morsel_grain);
    const Kernel = fillDenseIntCastSourcesStoreMorselKernel(OutT, LeftT, RightT, op);
    session.runMorselRange(.{ .len = len, .grain = grain, .workers_requested = workers_requested }, Kernel.Ctx{ .out = out, .left = left, .right = right, .len = len }, Kernel.run) catch unreachable;
}

fn fillDenseIntCastSourcesStoreMorsel(session: *Session, comptime OutT: type, comptime LeftT: type, comptime RightT: type, out: []OutT, op: BuiltinId, left: DenseResolvedSource(LeftT), right: DenseResolvedSource(RightT), len: usize, workers_requested: usize) void {
    switch (op) {
        .add => runDenseIntCastSourcesStoreMorselOp(session, OutT, LeftT, RightT, .add, out, left, right, len, workers_requested),
        .sub => runDenseIntCastSourcesStoreMorselOp(session, OutT, LeftT, RightT, .sub, out, left, right, len, workers_requested),
        .minimum => runDenseIntCastSourcesStoreMorselOp(session, OutT, LeftT, RightT, .minimum, out, left, right, len, workers_requested),
        .maximum => runDenseIntCastSourcesStoreMorselOp(session, OutT, LeftT, RightT, .maximum, out, left, right, len, workers_requested),
        .mul => runDenseIntCastSourcesStoreMorselOp(session, OutT, LeftT, RightT, .mul, out, left, right, len, workers_requested),
        else => unreachable,
    }
}

fn fillDenseIntCompareSourceRolesOp(
    comptime T: type,
    comptime op: BuiltinId,
    comptime left_role: DenseSourceRole,
    comptime right_role: DenseSourceRole,
    out: *HostBitAlloc,
    len: usize,
    ctx: *const DenseProducerContext(T),
) HostCompareSummary {
    var summary = hostCompareSummaryEmpty();
    for (out.words, 0..) |*out_word, word_idx| {
        const active = bitWordActiveLen(len, word_idx, out.words.len);
        const base = word_idx * host_bit_word_bits;
        const word = denseIntCompareSourceRolesWord(T, op, left_role, right_role, ctx, base, active);
        out_word.* = word;
        hostCompareSummaryNoteWord(&summary, word, active);
    }
    return summary;
}

fn fillDenseIntCompareSourcesOp(comptime T: type, comptime op: BuiltinId, out: *HostBitAlloc, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) ?HostCompareSummary {
    if (out.len != len) return null;
    const source_len = denseIntResolvedSourcesLen(T, left, right) orelse return null;
    if (source_len != len) return null;

    var ctx = denseIntSourceContext(T, left, right);
    return switch (left) {
        .array => switch (right) {
            .array => fillDenseIntCompareSourceRolesOp(T, op, .left_array, .right_array, out, len, &ctx),
            .reverse_array => fillDenseIntCompareSourceRolesOp(T, op, .left_array, .right_reverse_array, out, len, &ctx),
            .scalar => fillDenseIntCompareSourceRolesOp(T, op, .left_array, .right_scalar, out, len, &ctx),
        },
        .reverse_array => switch (right) {
            .array => fillDenseIntCompareSourceRolesOp(T, op, .left_reverse_array, .right_array, out, len, &ctx),
            .reverse_array => fillDenseIntCompareSourceRolesOp(T, op, .left_reverse_array, .right_reverse_array, out, len, &ctx),
            .scalar => fillDenseIntCompareSourceRolesOp(T, op, .left_reverse_array, .right_scalar, out, len, &ctx),
        },
        .scalar => switch (right) {
            .array => fillDenseIntCompareSourceRolesOp(T, op, .left_scalar, .right_array, out, len, &ctx),
            .reverse_array => fillDenseIntCompareSourceRolesOp(T, op, .left_scalar, .right_reverse_array, out, len, &ctx),
            .scalar => null,
        },
    };
}

fn fillDenseIntCompareSources(comptime T: type, out: *HostBitAlloc, op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) ?HostCompareSummary {
    return switch (op) {
        .equal => fillDenseIntCompareSourcesOp(T, .equal, out, left, right, len),
        .less => fillDenseIntCompareSourcesOp(T, .less, out, left, right, len),
        .more => fillDenseIntCompareSourcesOp(T, .more, out, left, right, len),
        else => null,
    };
}

fn DenseIntStoreSink(comptime T: type, comptime lane_count: usize) type {
    const Vec = @Vector(lane_count, T);
    return struct {
        out: []T,

        fn consumeVec(self: *@This(), idx: usize, value: Vec) void {
            self.out[idx..][0..lane_count].* = value;
        }

        fn consumeScalar(self: *@This(), idx: usize, value: T) void {
            self.out[idx] = value;
        }
    };
}

fn runDenseIntMapSourceRolesSink(
    comptime T: type,
    comptime op: BuiltinId,
    comptime left_role: DenseSourceRole,
    comptime right_role: DenseSourceRole,
    len: usize,
    ctx: *const DenseProducerContext(T),
    sink: anytype,
) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    const Left = DenseSourceProducer(T, lane_count, left_role);
    const Right = DenseSourceProducer(T, lane_count, right_role);
    const Producer = DenseIntBinaryProducer(T, lane_count, op, Left, Right);
    runDenseIntProducerSink(lane_count, Producer, len, ctx, sink);
}

fn runDenseIntArrayArrayProducerSink(comptime T: type, comptime op: BuiltinId, left_items: []const T, right_items: []const T, sink: anytype) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    const LoadLeft = DenseSourceProducer(T, lane_count, .left_array);
    const LoadRight = DenseSourceProducer(T, lane_count, .right_array);
    const Producer = DenseIntBinaryProducer(T, lane_count, op, LoadLeft, LoadRight);
    const ctx = DenseProducerContext(T){ .left_items = left_items, .right_items = right_items };
    runDenseIntProducerSink(lane_count, Producer, left_items.len, &ctx, sink);
}

fn runDenseIntSourceMapSinkOp(comptime T: type, comptime op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize, sink: anytype) void {
    var ctx = denseIntSourceContext(T, left, right);
    switch (left) {
        .array => switch (right) {
            .array => runDenseIntMapSourceRolesSink(T, op, .left_array, .right_array, len, &ctx, sink),
            .reverse_array => runDenseIntMapSourceRolesSink(T, op, .left_array, .right_reverse_array, len, &ctx, sink),
            .scalar => runDenseIntMapSourceRolesSink(T, op, .left_array, .right_scalar, len, &ctx, sink),
        },
        .reverse_array => switch (right) {
            .array => runDenseIntMapSourceRolesSink(T, op, .left_reverse_array, .right_array, len, &ctx, sink),
            .reverse_array => runDenseIntMapSourceRolesSink(T, op, .left_reverse_array, .right_reverse_array, len, &ctx, sink),
            .scalar => runDenseIntMapSourceRolesSink(T, op, .left_reverse_array, .right_scalar, len, &ctx, sink),
        },
        .scalar => switch (right) {
            .array => runDenseIntMapSourceRolesSink(T, op, .left_scalar, .right_array, len, &ctx, sink),
            .reverse_array => runDenseIntMapSourceRolesSink(T, op, .left_scalar, .right_reverse_array, len, &ctx, sink),
            .scalar => unreachable,
        },
    }
}

fn fillDenseIntSourcesStoreScalarOp(comptime T: type, comptime op: BuiltinId, out: []T, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) void {
    for (out[0..len], 0..) |*dest, idx| {
        dest.* = applyIntOpUncheckedTyped(
            T,
            op,
            denseIntResolvedSourceScalarItem(T, left, idx),
            denseIntResolvedSourceScalarItem(T, right, idx),
        );
    }
}

fn fillDenseIntSourcesStoreOp(comptime T: type, comptime op: BuiltinId, out: []T, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) void {
    if (comptime enable_dense_dyad_i8_mul_wasm_vectorized and T == i8 and op == .mul) {
        switch (left) {
            .array => |left_items| switch (right) {
                .array => |right_items| {
                    fillInt8DenseArrayArrayMulWasmSimd(out, left_items, right_items);
                    return;
                },
                .scalar => |scalar| {
                    fillInt8DenseScalarArrayMulWasmSimd(out, scalar, left_items);
                    return;
                },
                else => {},
            },
            .scalar => |scalar| switch (right) {
                .array => |right_items| {
                    fillInt8DenseScalarArrayMulWasmSimd(out, scalar, right_items);
                    return;
                },
                else => {},
            },
            else => {},
        }
    }

    if (comptime !denseIntSourceStoreCanVectorize(T, op)) {
        fillDenseIntSourcesStoreScalarOp(T, op, out, left, right, len);
        return;
    }

    const lane_count = dense_host_simd_bytes / @sizeOf(T);
    var sink = DenseIntStoreSink(T, lane_count){ .out = out };
    switch (left) {
        .array => |left_items| switch (right) {
            .array => |right_items| {
                runDenseIntArrayArrayProducerSink(T, op, left_items, right_items, &sink);
                return;
            },
            else => {},
        },
        else => {},
    }
    runDenseIntSourceMapSinkOp(T, op, left, right, len, &sink);
}

fn fillDenseIntSourcesStore(comptime T: type, out: []T, op: BuiltinId, left: DenseResolvedSource(T), right: DenseResolvedSource(T), len: usize) void {
    switch (op) {
        .add => fillDenseIntSourcesStoreOp(T, .add, out, left, right, len),
        .sub => fillDenseIntSourcesStoreOp(T, .sub, out, left, right, len),
        .minimum => fillDenseIntSourcesStoreOp(T, .minimum, out, left, right, len),
        .maximum => fillDenseIntSourcesStoreOp(T, .maximum, out, left, right, len),
        .mul => fillDenseIntSourcesStoreOp(T, .mul, out, left, right, len),
        else => unreachable,
    }
}

fn denseI8MulWasmHalfVec(vec: DenseI8MulWasmVec, comptime high: bool) DenseI8MulWasmHalfVec {
    const shuffle = if (high) dense_i8_mul_wasm_hi_shuffle else dense_i8_mul_wasm_lo_shuffle;
    return @shuffle(i8, vec, @as(DenseI8MulWasmVec, undefined), shuffle);
}

fn denseI8MulWasmStore(out: []i8, idx: usize, product: DenseI8MulWasmWideVec) void {
    const narrowed: DenseI8MulWasmHalfVec = @intCast(product);
    out[idx..][0..dense_i8_mul_wasm_half_lanes].* = narrowed;
}

fn fillInt8DenseArrayArrayMulWasmSimd(out: []i8, left_items: []const i8, right_items: []const i8) void {
    var idx: usize = 0;
    const vector_limit = left_items.len - (left_items.len % dense_i8_mul_wasm_lanes);
    while (idx < vector_limit) : (idx += dense_i8_mul_wasm_lanes) {
        const lhs: DenseI8MulWasmVec = left_items[idx..][0..dense_i8_mul_wasm_lanes].*;
        const rhs: DenseI8MulWasmVec = right_items[idx..][0..dense_i8_mul_wasm_lanes].*;
        const lhs_lo: DenseI8MulWasmWideVec = @intCast(denseI8MulWasmHalfVec(lhs, false));
        const rhs_lo: DenseI8MulWasmWideVec = @intCast(denseI8MulWasmHalfVec(rhs, false));
        const lhs_hi: DenseI8MulWasmWideVec = @intCast(denseI8MulWasmHalfVec(lhs, true));
        const rhs_hi: DenseI8MulWasmWideVec = @intCast(denseI8MulWasmHalfVec(rhs, true));
        denseI8MulWasmStore(out, idx, lhs_lo * rhs_lo);
        denseI8MulWasmStore(out, idx + dense_i8_mul_wasm_half_lanes, lhs_hi * rhs_hi);
    }
    while (idx < left_items.len) : (idx += 1) {
        out[idx] = applyIntOpUncheckedTyped(i8, .mul, left_items[idx], right_items[idx]);
    }
}

fn fillInt8DenseScalarArrayMulWasmSimd(out: []i8, scalar: i8, items: []const i8) void {
    const scalar_wide: DenseI8MulWasmWideVec = @splat(scalar);
    var idx: usize = 0;
    const vector_limit = items.len - (items.len % dense_i8_mul_wasm_lanes);
    while (idx < vector_limit) : (idx += dense_i8_mul_wasm_lanes) {
        const item_vec: DenseI8MulWasmVec = items[idx..][0..dense_i8_mul_wasm_lanes].*;
        const item_lo: DenseI8MulWasmWideVec = @intCast(denseI8MulWasmHalfVec(item_vec, false));
        const item_hi: DenseI8MulWasmWideVec = @intCast(denseI8MulWasmHalfVec(item_vec, true));
        denseI8MulWasmStore(out, idx, item_lo * scalar_wide);
        denseI8MulWasmStore(out, idx + dense_i8_mul_wasm_half_lanes, item_hi * scalar_wide);
    }
    while (idx < items.len) : (idx += 1) {
        out[idx] = applyIntOpUncheckedTyped(i8, .mul, items[idx], scalar);
    }
}

fn hostDenseIntWidth(comptime T: type) i32 {
    return switch (@sizeOf(T)) {
        1 => 1,
        2 => 2,
        4 => 4,
        8 => 8,
        else => @compileError("unsupported dense host integer width"),
    };
}

fn denseBitWordSimdSupported(op: BuiltinId) bool {
    return switch (op) {
        .mul, .minimum, .maximum, .equal, .less, .more => true,
        else => false,
    };
}

fn denseBitWordBinaryVec(comptime op: BuiltinId, lhs: anytype, rhs: @TypeOf(lhs)) @TypeOf(lhs) {
    return switch (op) {
        .mul, .minimum => lhs & rhs,
        .maximum => lhs | rhs,
        .equal => ~(lhs ^ rhs),
        .less => (~lhs) & rhs,
        .more => lhs & (~rhs),
        else => unreachable,
    };
}

fn fillBitWordsBinarySimd(comptime op: BuiltinId, out: []u64, left_words: []const u64, right_words: []const u64) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(u64);
    const Vec = @Vector(lane_count, u64);
    var idx: usize = 0;
    const vector_limit = left_words.len - (left_words.len % lane_count);
    while (idx < vector_limit) : (idx += lane_count) {
        const lhs: Vec = left_words[idx..][0..lane_count].*;
        const rhs: Vec = right_words[idx..][0..lane_count].*;
        out[idx..][0..lane_count].* = denseBitWordBinaryVec(op, lhs, rhs);
    }
    while (idx < left_words.len) : (idx += 1) {
        out[idx] = switch (op) {
            .mul, .minimum => left_words[idx] & right_words[idx],
            .maximum => left_words[idx] | right_words[idx],
            .equal => ~(left_words[idx] ^ right_words[idx]),
            .less => (~left_words[idx]) & right_words[idx],
            .more => left_words[idx] & (~right_words[idx]),
            else => unreachable,
        };
    }
}

fn fillBitWordsBinary(out: []u64, op: BuiltinId, left_words: []const u64, right_words: []const u64) void {
    return switch (op) {
        .mul => fillBitWordsBinarySimd(.mul, out, left_words, right_words),
        .minimum => fillBitWordsBinarySimd(.minimum, out, left_words, right_words),
        .maximum => fillBitWordsBinarySimd(.maximum, out, left_words, right_words),
        .equal => fillBitWordsBinarySimd(.equal, out, left_words, right_words),
        .less => fillBitWordsBinarySimd(.less, out, left_words, right_words),
        .more => fillBitWordsBinarySimd(.more, out, left_words, right_words),
        else => unreachable,
    };
}

const DenseBitResolvedSource = struct {
    bits: HostBitSlice,
    reverse: bool = false,
};

fn bitResolvedSourceWord(source: DenseBitResolvedSource, word_idx: usize, active: usize) u64 {
    if (!source.reverse) return bitWordMasked(source.bits.words, source.bits.len, word_idx) & bitLowMask(active);
    const base = word_idx * host_bit_word_bits;
    var word: u64 = 0;
    var bit_idx: usize = 0;
    while (bit_idx < active) : (bit_idx += 1) {
        const source_idx = source.bits.len - 1 - (base + bit_idx);
        if (bitGet(source.bits.words, source_idx)) word |= @as(u64, 1) << @intCast(bit_idx);
    }
    return word;
}

fn fillBitWordsBinaryResolved(out: *HostBitAlloc, op: BuiltinId, left: DenseBitResolvedSource, right: DenseBitResolvedSource) void {
    if (!left.reverse and !right.reverse) {
        fillBitWordsBinary(out.words, op, left.bits.words, right.bits.words);
        bitClearUnusedTail(out.words, out.len);
        return;
    }
    for (out.words, 0..) |*out_word, word_idx| {
        const active = bitWordActiveLen(out.len, word_idx, out.words.len);
        const lhs = bitResolvedSourceWord(left, word_idx, active);
        const rhs = bitResolvedSourceWord(right, word_idx, active);
        out_word.* = switch (op) {
            .mul => denseBitWordBinaryVec(.mul, lhs, rhs),
            .minimum => denseBitWordBinaryVec(.minimum, lhs, rhs),
            .maximum => denseBitWordBinaryVec(.maximum, lhs, rhs),
            .equal => denseBitWordBinaryVec(.equal, lhs, rhs),
            .less => denseBitWordBinaryVec(.less, lhs, rhs),
            .more => denseBitWordBinaryVec(.more, lhs, rhs),
            else => unreachable,
        } & bitLowMask(active);
    }
    bitClearUnusedTail(out.words, out.len);
}

fn denseBitFirstAxisSliceResolvedSource(view: HostFirstAxisSliceView) ?DenseBitResolvedSource {
    const array = fullReverseFirstAxisSliceSourceHost(view) orelse return null;
    return switch (array.storage) {
        .bit => |words| .{
            .bits = .{ .words = hostDenseLogicalBitWords(array, words), .len = array.logical_len },
            .reverse = true,
        },
        else => null,
    };
}

fn denseBitFlatSliceResolvedSource(view: HostFlatSliceView) ?DenseBitResolvedSource {
    return switch (hostIntFlatSliceArrayView(view) orelse return null) {
        .bit => |bits| .{ .bits = bits },
        else => null,
    };
}

fn denseBitDenseViewResolvedSource(view: HostIntDenseView) ?DenseBitResolvedSource {
    return switch (view) {
        .dense => |items| switch (items) {
            .bit => |bits| .{ .bits = bits },
            else => null,
        },
        .flat_slice => |items| denseBitFlatSliceResolvedSource(items),
        .first_axis_slice => |items| denseBitFirstAxisSliceResolvedSource(items),
        else => null,
    };
}

fn fillBitDenseDenseSourceResult(out: *HostBitAlloc, op: BuiltinId, left_items: HostIntDenseView, right_items: HostIntDenseView) bool {
    if (!enable_packed_bit_simd or !denseBitWordSimdSupported(op)) return false;
    const left = denseBitDenseViewResolvedSource(left_items) orelse return false;
    const right = denseBitDenseViewResolvedSource(right_items) orelse return false;
    if (left.bits.len != out.len or right.bits.len != out.len) return false;
    fillBitWordsBinaryResolved(out, op, left, right);
    return true;
}

fn fillInt32ArrayArrayMulToInt64Simd(out: []i64, left_items: []const i32, right_items: []const i32) void {
    const lane_count = dense_host_simd_bytes / @sizeOf(i64);
    const block_count = lane_count * 4;
    const InVec = @Vector(lane_count, i32);
    const OutVec = @Vector(lane_count, i64);
    var idx: usize = 0;
    const block_limit = left_items.len - (left_items.len % block_count);
    while (idx < block_limit) : (idx += block_count) {
        inline for (0..4) |block| {
            const base = idx + block * lane_count;
            const lhs_i32: InVec = left_items[base..][0..lane_count].*;
            const rhs_i32: InVec = right_items[base..][0..lane_count].*;
            const lhs_i64: OutVec = @intCast(lhs_i32);
            const rhs_i64: OutVec = @intCast(rhs_i32);
            out[base..][0..lane_count].* = lhs_i64 * rhs_i64;
        }
    }
    const vector_limit = left_items.len - (left_items.len % lane_count);
    while (idx < vector_limit) : (idx += lane_count) {
        const lhs_i32: InVec = left_items[idx..][0..lane_count].*;
        const rhs_i32: InVec = right_items[idx..][0..lane_count].*;
        const lhs_i64: OutVec = @intCast(lhs_i32);
        const rhs_i64: OutVec = @intCast(rhs_i32);
        out[idx..][0..lane_count].* = lhs_i64 * rhs_i64;
    }
    while (idx < left_items.len) : (idx += 1) {
        out[idx] = applyIntOpUncheckedTyped(i64, .mul, left_items[idx], right_items[idx]);
    }
}

fn bitWordFloatVec(comptime lane_count: usize, bits: u64) @Vector(lane_count, f64) {
    var values: [lane_count]f64 = undefined;
    inline for (0..lane_count) |lane| {
        values[lane] = @floatFromInt((bits >> lane) & 1);
    }
    return values;
}

fn fillFloatScalarBitArraySimd(comptime op: BuiltinId, out: []f64, scalar: f64, items: HostBitSlice, scalar_left: bool) void {
    if (items.len == 0) return;
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    const Vec = @Vector(lane_count, f64);
    const scalar_vec: Vec = @splat(scalar);
    var out_idx: usize = 0;
    for (items.words, 0..) |_, word_idx| {
        var bits = bitWordMasked(items.words, items.len, word_idx);
        var active = bitWordActiveLen(items.len, word_idx, items.words.len);
        while (active >= lane_count) : (active -= lane_count) {
            const bit_vec = bitWordFloatVec(lane_count, bits);
            out[out_idx..][0..lane_count].* = if (scalar_left)
                denseFloatBinaryVec(op, scalar_vec, bit_vec)
            else
                denseFloatBinaryVec(op, bit_vec, scalar_vec);
            bits >>= lane_count;
            out_idx += lane_count;
        }
        var tail_idx: usize = 0;
        while (tail_idx < active) : (tail_idx += 1) {
            const item = @as(f64, @floatFromInt(@as(u8, @intCast(bits & 1))));
            out[out_idx] = if (scalar_left) applyFloatOp(op, scalar, item) else applyFloatOp(op, item, scalar);
            bits >>= 1;
            out_idx += 1;
        }
    }
}

fn fillFloatBitViewsSimd(comptime op: BuiltinId, out: []f64, left_items: HostBitSlice, right_items: HostBitSlice) void {
    if (left_items.len == 0) return;
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    var out_idx: usize = 0;
    for (left_items.words, 0..) |_, word_idx| {
        var left_bits = bitWordMasked(left_items.words, left_items.len, word_idx);
        var right_bits = bitWordMasked(right_items.words, right_items.len, word_idx);
        var active = bitWordActiveLen(left_items.len, word_idx, left_items.words.len);
        while (active >= lane_count) : (active -= lane_count) {
            const left_vec = bitWordFloatVec(lane_count, left_bits);
            const right_vec = bitWordFloatVec(lane_count, right_bits);
            out[out_idx..][0..lane_count].* = denseFloatBinaryVec(op, left_vec, right_vec);
            left_bits >>= lane_count;
            right_bits >>= lane_count;
            out_idx += lane_count;
        }
        var tail_idx: usize = 0;
        while (tail_idx < active) : (tail_idx += 1) {
            out[out_idx] = applyFloatOp(
                op,
                @as(f64, @floatFromInt(@as(u8, @intCast(left_bits & 1)))),
                @as(f64, @floatFromInt(@as(u8, @intCast(right_bits & 1)))),
            );
            left_bits >>= 1;
            right_bits >>= 1;
            out_idx += 1;
        }
    }
}

fn fillFloatBitViewArraySimd(comptime LeftBit: bool, comptime op: BuiltinId, out: []f64, bit_items: HostBitSlice, other_items: []const f64) void {
    if (bit_items.len == 0) return;
    const lane_count = dense_host_simd_bytes / @sizeOf(f64);
    const Vec = @Vector(lane_count, f64);
    const zero: Vec = @splat(0.0);
    var out_idx: usize = 0;
    for (bit_items.words, 0..) |_, word_idx| {
        var bits = bitWordMasked(bit_items.words, bit_items.len, word_idx);
        var active = bitWordActiveLen(bit_items.len, word_idx, bit_items.words.len);
        while (active >= lane_count) : (active -= lane_count) {
            const bit_vec = bitWordFloatVec(lane_count, bits);
            const other_vec: Vec = other_items[out_idx..][0..lane_count].*;
            out[out_idx..][0..lane_count].* = if (op == .mul)
                @select(f64, bit_vec != zero, other_vec, zero)
            else if (LeftBit)
                denseFloatBinaryVec(op, bit_vec, other_vec)
            else
                denseFloatBinaryVec(op, other_vec, bit_vec);
            bits >>= lane_count;
            out_idx += lane_count;
        }
        var tail_idx: usize = 0;
        while (tail_idx < active) : (tail_idx += 1) {
            const bit_value = @as(f64, @floatFromInt(@as(u8, @intCast(bits & 1))));
            out[out_idx] = if (LeftBit) applyFloatOp(op, bit_value, other_items[out_idx]) else applyFloatOp(op, other_items[out_idx], bit_value);
            bits >>= 1;
            out_idx += 1;
        }
    }
}

fn fillBitScalarArrayResultGeneric(out: *HostBitAlloc, op: BuiltinId, scalar: i64, items: HostIntArrayView, scalar_left: bool, unchecked_safe: bool) KError!void {
    if (enable_packed_bit_simd and (op == .mul or op == .minimum or op == .maximum) and scalar >= 0 and scalar <= 1 and std.meta.activeTag(items) == .bit) {
        const bit_items = items.bit;
        switch (op) {
            .mul, .minimum => {
                if (scalar == 0) {
                    bitFill(out.words, out.len, false);
                    return;
                }
                if (out.words.ptr != bit_items.words.ptr) @memcpy(out.words, bit_items.words);
                bitClearUnusedTail(out.words, out.len);
                return;
            },
            .maximum => {
                if (scalar == 1) {
                    bitFill(out.words, out.len, true);
                    return;
                }
                if (out.words.ptr != bit_items.words.ptr) @memcpy(out.words, bit_items.words);
                bitClearUnusedTail(out.words, out.len);
                return;
            },
            else => unreachable,
        }
    }

    var generic_out = HostIntResult{ .bit = out.* };
    for (0..hostIntArrayViewLen(items)) |idx| {
        const item = hostIntViewItem(items, idx);
        const result = if (unchecked_safe)
            if (scalar_left) applyIntOpUnchecked(op, scalar, item) else applyIntOpUnchecked(op, item, scalar)
        else
            try checkedIntOp(op, if (scalar_left) scalar else item, if (scalar_left) item else scalar);
        try generic_out.set(idx, result);
    }
}

fn fillBitArrayArrayResultGeneric(out: *HostBitAlloc, op: BuiltinId, left_items: HostIntArrayView, right_items: HostIntArrayView, unchecked_safe: bool) KError!void {
    if (enable_packed_bit_simd and denseBitWordSimdSupported(op) and std.meta.activeTag(left_items) == .bit and std.meta.activeTag(right_items) == .bit) {
        const left_bits = left_items.bit;
        const right_bits = right_items.bit;
        fillBitWordsBinary(out.words, op, left_bits.words, right_bits.words);
        bitClearUnusedTail(out.words, out.len);
        return;
    }

    var generic_out = HostIntResult{ .bit = out.* };
    for (0..hostIntArrayViewLen(left_items)) |idx| {
        const left = hostIntViewItem(left_items, idx);
        const right = hostIntViewItem(right_items, idx);
        const result = if (unchecked_safe)
            applyIntOpUnchecked(op, left, right)
        else
            try checkedIntOp(op, left, right);
        try generic_out.set(idx, result);
    }
}

fn fillBitTransposeDenseBitResult(out: *HostBitAlloc, op: BuiltinId, transpose_view: HostTransposeView, other_bits: HostBitSlice, transpose_left: bool) bool {
    if (!enable_packed_bit_simd or !denseBitWordSimdSupported(op)) return false;
    if (other_bits.len != out.len) return false;
    if (!fillBitTransposeResult(out, transpose_view)) return false;
    if (transpose_left) {
        fillBitWordsBinary(out.words, op, out.words, other_bits.words);
    } else {
        fillBitWordsBinary(out.words, op, other_bits.words, out.words);
    }
    bitClearUnusedTail(out.words, out.len);
    return true;
}

fn fillBitDenseDenseTransposeResult(out: *HostBitAlloc, op: BuiltinId, left_items: HostIntDenseView, right_items: HostIntDenseView) bool {
    switch (left_items) {
        .transpose => |view| {
            const right_bits = hostIntDenseViewBitSlice(right_items) orelse return false;
            return fillBitTransposeDenseBitResult(out, op, view, right_bits, true);
        },
        else => {},
    }
    switch (right_items) {
        .transpose => |view| {
            const left_bits = hostIntDenseViewBitSlice(left_items) orelse return false;
            return fillBitTransposeDenseBitResult(out, op, view, left_bits, false);
        },
        else => return false,
    }
}

fn denseIntArrayViewResolvedSource(comptime T: type, view: HostIntArrayView, comptime reverse: bool) ?DenseResolvedSource(T) {
    return switch (view) {
        .bit => null,
        .int8 => |items| if (T == i8) (if (reverse) .{ .reverse_array = items } else .{ .array = items }) else null,
        .int16 => |items| if (T == i16) (if (reverse) .{ .reverse_array = items } else .{ .array = items }) else null,
        .int32 => |items| if (T == i32) (if (reverse) .{ .reverse_array = items } else .{ .array = items }) else null,
        .int64 => |items| if (T == i64) (if (reverse) .{ .reverse_array = items } else .{ .array = items }) else null,
    };
}

fn hostIntFlatSliceArrayView(view: HostFlatSliceView) ?HostIntArrayView {
    const array = view.source_host orelse return null;
    return switch (array.storage) {
        .bit => |words| blk: {
            if (view.start % host_bit_word_bits != 0) break :blk null;
            const logical_words = hostDenseLogicalBitWords(array, words);
            const start_word = view.start / host_bit_word_bits;
            const word_count = bitWordCount(view.len);
            if (start_word > logical_words.len or word_count > logical_words.len - start_word) break :blk null;
            break :blk .{ .bit = .{ .words = logical_words[start_word..][0..word_count], .len = view.len } };
        },
        .int8 => |items| blk: {
            const logical_items = hostDenseLogicalItems(i8, array, items);
            if (view.start > logical_items.len or view.len > logical_items.len - view.start) break :blk null;
            break :blk .{ .int8 = logical_items[view.start..][0..view.len] };
        },
        .int16 => |items| blk: {
            const logical_items = hostDenseLogicalItems(i16, array, items);
            if (view.start > logical_items.len or view.len > logical_items.len - view.start) break :blk null;
            break :blk .{ .int16 = logical_items[view.start..][0..view.len] };
        },
        .int32 => |items| blk: {
            const logical_items = hostDenseLogicalItems(i32, array, items);
            if (view.start > logical_items.len or view.len > logical_items.len - view.start) break :blk null;
            break :blk .{ .int32 = logical_items[view.start..][0..view.len] };
        },
        .int64 => |items| blk: {
            const logical_items = hostDenseLogicalItems(i64, array, items);
            if (view.start > logical_items.len or view.len > logical_items.len - view.start) break :blk null;
            break :blk .{ .int64 = logical_items[view.start..][0..view.len] };
        },
        else => null,
    };
}

fn hostIntDenseViewContiguousArrayView(view: HostIntDenseView) ?HostIntArrayView {
    return switch (view) {
        .dense => |items| items,
        .flat_slice => |items| hostIntFlatSliceArrayView(items),
        .first_axis_slice => |items| blk: {
            const source = fullFirstAxisSliceSourceIntView(items) orelse break :blk null;
            break :blk source.view;
        },
        else => null,
    };
}

fn denseIntFlatSliceResolvedSource(comptime T: type, view: HostFlatSliceView) ?DenseResolvedSource(T) {
    return denseIntArrayViewResolvedSource(T, hostIntFlatSliceArrayView(view) orelse return null, false);
}

fn denseIntFirstAxisSliceResolvedSource(comptime T: type, view: HostFirstAxisSliceView) ?DenseResolvedSource(T) {
    const source = fullFirstAxisSliceSourceIntView(view) orelse return null;
    if (view.row_step == 1) return denseIntArrayViewResolvedSource(T, source.view, false);
    if (view.row_step == -1) return denseIntArrayViewResolvedSource(T, source.view, true);
    return null;
}

fn denseIntDenseViewResolvedSource(comptime T: type, view: HostIntDenseView) ?DenseResolvedSource(T) {
    return switch (view) {
        .dense => |items| denseIntArrayViewResolvedSource(T, items, false),
        .flat_slice => |items| denseIntFlatSliceResolvedSource(T, items),
        .first_axis_slice => |items| denseIntFirstAxisSliceResolvedSource(T, items),
        else => null,
    };
}

fn fillIntScalarBitArrayTo(comptime OutT: type, out: []OutT, op: BuiltinId, scalar: i64, items: HostBitSlice, scalar_left: bool, unchecked_safe: bool) KError!void {
    if (items.len == 0) return;
    const scalar_value: OutT = if (unchecked_safe) castDenseInt(OutT, scalar) else undefined;
    var out_idx: usize = 0;
    for (items.words, 0..) |_, word_idx| {
        var bits = bitWordMasked(items.words, items.len, word_idx);
        const active = bitWordActiveLen(items.len, word_idx, items.words.len);
        var bit_idx: usize = 0;
        while (bit_idx < active) : (bit_idx += 1) {
            const item_value: OutT = @intCast(bits & 1);
            out[out_idx] = if (unchecked_safe)
                if (scalar_left) applyIntOpUncheckedTyped(OutT, op, scalar_value, item_value) else applyIntOpUncheckedTyped(OutT, op, item_value, scalar_value)
            else
                try applyIntOpCheckedNarrow(OutT, op, if (scalar_left) scalar else @as(i64, @intCast(item_value)), if (scalar_left) @as(i64, @intCast(item_value)) else scalar);
            bits >>= 1;
            out_idx += 1;
        }
    }
}

fn fillIntBitArrayArrayTo(comptime OutT: type, out: []OutT, op: BuiltinId, left_items: HostBitSlice, right_items: HostBitSlice, unchecked_safe: bool) KError!void {
    if (left_items.len == 0) return;
    var out_idx: usize = 0;
    for (left_items.words, 0..) |_, word_idx| {
        var left_bits = bitWordMasked(left_items.words, left_items.len, word_idx);
        var right_bits = bitWordMasked(right_items.words, right_items.len, word_idx);
        const active = bitWordActiveLen(left_items.len, word_idx, left_items.words.len);
        var bit_idx: usize = 0;
        while (bit_idx < active) : (bit_idx += 1) {
            const left_value: OutT = @intCast(left_bits & 1);
            const right_value: OutT = @intCast(right_bits & 1);
            out[out_idx] = if (unchecked_safe)
                applyIntOpUncheckedTyped(OutT, op, left_value, right_value)
            else
                try applyIntOpCheckedNarrow(OutT, op, @as(i64, @intCast(left_value)), @as(i64, @intCast(right_value)));
            left_bits >>= 1;
            right_bits >>= 1;
            out_idx += 1;
        }
    }
}

fn fillIntBitArrayMixedTo(
    comptime OutT: type,
    comptime OtherT: type,
    out: []OutT,
    op: BuiltinId,
    bit_items: HostBitSlice,
    other_items: []const OtherT,
    bit_left: bool,
    unchecked_safe: bool,
) KError!void {
    if (bit_items.len == 0) return;
    var out_idx: usize = 0;
    for (bit_items.words, 0..) |_, word_idx| {
        var bits = bitWordMasked(bit_items.words, bit_items.len, word_idx);
        const active = bitWordActiveLen(bit_items.len, word_idx, bit_items.words.len);
        var bit_idx: usize = 0;
        while (bit_idx < active) : (bit_idx += 1) {
            const bit_value: OutT = @intCast(bits & 1);
            const other_value: OutT = castDenseInt(OutT, other_items[out_idx]);
            out[out_idx] = if (unchecked_safe)
                if (bit_left) applyIntOpUncheckedTyped(OutT, op, bit_value, other_value) else applyIntOpUncheckedTyped(OutT, op, other_value, bit_value)
            else
                try applyIntOpCheckedNarrow(OutT, op, if (bit_left) @as(i64, @intCast(bit_value)) else @as(i64, @intCast(other_items[out_idx])), if (bit_left) @as(i64, @intCast(other_items[out_idx])) else @as(i64, @intCast(bit_value)));
            bits >>= 1;
            out_idx += 1;
        }
    }
}

fn fillIntNegBitArrayTo(comptime OutT: type, out: []OutT, items: HostBitSlice) void {
    if (items.len == 0) return;
    var out_idx: usize = 0;
    for (items.words, 0..) |_, word_idx| {
        var bits = bitWordMasked(items.words, items.len, word_idx);
        const active = bitWordActiveLen(items.len, word_idx, items.words.len);
        var bit_idx: usize = 0;
        while (bit_idx < active) : (bit_idx += 1) {
            out[out_idx] = -@as(OutT, @intCast(bits & 1));
            bits >>= 1;
            out_idx += 1;
        }
    }
}

fn hostIntKindDenseDyadUsesSimd(op: BuiltinId, kind: HostIntStorageKind, unchecked_safe: bool) bool {
    if (comptime !enable_dense_int_simd) return false;
    if (!unchecked_safe or !denseIntSimdSupported(op)) return false;
    if (kind == .bit) return false;
    if (kind == .int64 and op == .mul) return false;
    return true;
}

fn hostIntDenseScalarDyadUsesSimd(op: BuiltinId, items: HostIntDenseView, scalar_kind: HostIntStorageKind, result_kind: HostIntStorageKind, unchecked_safe: bool) bool {
    if (!hostIntKindDenseDyadUsesSimd(op, result_kind, unchecked_safe)) return false;
    if (scalar_kind != result_kind) return false;
    if (items != .dense) return false;
    return hostIntArrayViewKind(items.dense) == result_kind;
}

fn hostIntDenseDenseDyadUsesSimd(op: BuiltinId, left_items: HostIntDenseView, right_items: HostIntDenseView, result_kind: HostIntStorageKind, unchecked_safe: bool) bool {
    if (!hostIntKindDenseDyadUsesSimd(op, result_kind, unchecked_safe)) return false;
    if (left_items != .dense or right_items != .dense) return false;
    return hostIntArrayViewKind(left_items.dense) == result_kind and hostIntArrayViewKind(right_items.dense) == result_kind;
}

fn fillIntScalarArrayTo(comptime OutT: type, comptime InT: type, out: []OutT, op: BuiltinId, scalar: i64, items: []const InT, scalar_left: bool, unchecked_safe: bool) KError!void {
    if (unchecked_safe) {
        if (std.math.cast(OutT, scalar)) |scalar_value| {
            if (comptime hostIntStorageRank(hostIntStorageKindForDenseType(InT)) <= hostIntStorageRank(hostIntStorageKindForDenseType(OutT))) {
                if (enable_dense_int_simd and comptime InT == OutT) {
                    if (denseIntSimdSupported(op)) {
                        const scalar_source = DenseResolvedSource(OutT){ .scalar = scalar_value };
                        const item_source = DenseResolvedSource(OutT){ .array = items };
                        fillDenseIntSourcesStore(
                            OutT,
                            out,
                            op,
                            if (scalar_left) scalar_source else item_source,
                            if (scalar_left) item_source else scalar_source,
                            out.len,
                        );
                        return;
                    }
                }
                for (items, 0..) |item, idx| {
                    const item_value: OutT = castDenseInt(OutT, item);
                    out[idx] = if (scalar_left)
                        applyIntOpUncheckedTyped(OutT, op, scalar_value, item_value)
                    else
                        applyIntOpUncheckedTyped(OutT, op, item_value, scalar_value);
                }
                return;
            }
        }
    }

    for (items, 0..) |item, idx| {
        const lhs = if (scalar_left) scalar else @as(i64, @intCast(item));
        const rhs = if (scalar_left) @as(i64, @intCast(item)) else scalar;
        out[idx] = try applyIntOpCheckedCast(OutT, op, lhs, rhs);
    }
}

fn fillIntScalarReverseArrayTo(comptime OutT: type, comptime InT: type, out: []OutT, op: BuiltinId, scalar: i64, items: []const InT, scalar_left: bool, unchecked_safe: bool) KError!void {
    if (unchecked_safe) {
        if (std.math.cast(OutT, scalar)) |scalar_value| {
            if (comptime hostIntStorageRank(hostIntStorageKindForDenseType(InT)) <= hostIntStorageRank(hostIntStorageKindForDenseType(OutT))) {
                for (out, 0..) |*dest, idx| {
                    const item_value: OutT = castDenseInt(OutT, items[items.len - 1 - idx]);
                    dest.* = if (scalar_left)
                        applyIntOpUncheckedTyped(OutT, op, scalar_value, item_value)
                    else
                        applyIntOpUncheckedTyped(OutT, op, item_value, scalar_value);
                }
                return;
            }
        }
    }

    for (out, 0..) |*dest, idx| {
        const item = items[items.len - 1 - idx];
        const lhs = if (scalar_left) scalar else @as(i64, @intCast(item));
        const rhs = if (scalar_left) @as(i64, @intCast(item)) else scalar;
        dest.* = try applyIntOpCheckedCast(OutT, op, lhs, rhs);
    }
}

fn fillIntArrayArrayTo(comptime OutT: type, comptime LT: type, comptime RT: type, out: []OutT, op: BuiltinId, left_items: []const LT, right_items: []const RT, unchecked_safe: bool) KError!void {
    if (unchecked_safe) {
        if (comptime hostIntStorageRank(hostIntStorageKindForDenseType(LT)) <= hostIntStorageRank(hostIntStorageKindForDenseType(OutT)) and
            hostIntStorageRank(hostIntStorageKindForDenseType(RT)) <= hostIntStorageRank(hostIntStorageKindForDenseType(OutT)))
        {
            if (enable_dense_int_simd and comptime OutT == i64 and LT == i32 and RT == i32) {
                if (op == .mul) {
                    fillInt32ArrayArrayMulToInt64Simd(out, left_items, right_items);
                    return;
                }
            }
            if (enable_dense_int_simd and comptime LT == OutT and RT == OutT) {
                if (denseIntSimdSupported(op)) {
                    fillDenseIntSourcesStore(
                        OutT,
                        out,
                        op,
                        .{ .array = left_items },
                        .{ .array = right_items },
                        out.len,
                    );
                    return;
                }
            }
            for (left_items, 0..) |left_item, idx| {
                out[idx] = applyIntOpUncheckedTyped(OutT, op, left_item, right_items[idx]);
            }
            return;
        }
    }

    for (left_items, 0..) |left_item, idx| {
        out[idx] = try applyIntOpCheckedCast(
            OutT,
            op,
            @as(i64, @intCast(left_item)),
            @as(i64, @intCast(right_items[idx])),
        );
    }
}

fn fillIntNegArrayTo(comptime OutT: type, comptime InT: type, out: []OutT, items: []const InT, unchecked_safe: bool) KError!void {
    const input_fits_output = comptime hostIntStorageRank(hostIntStorageKindForDenseType(InT)) <= hostIntStorageRank(hostIntStorageKindForDenseType(OutT));
    if ((comptime @bitSizeOf(OutT) > @bitSizeOf(InT)) or (unchecked_safe and input_fits_output)) {
        for (items, 0..) |item, idx| out[idx] = -castDenseInt(OutT, item);
        return;
    }

    for (items, 0..) |item, idx| {
        out[idx] = try negateCheckedCast(OutT, @as(i64, @intCast(item)));
    }
}

fn fillIntNegReverseArrayTo(comptime OutT: type, comptime InT: type, out: []OutT, items: []const InT, unchecked_safe: bool) KError!void {
    const input_fits_output = comptime hostIntStorageRank(hostIntStorageKindForDenseType(InT)) <= hostIntStorageRank(hostIntStorageKindForDenseType(OutT));
    if ((comptime @bitSizeOf(OutT) > @bitSizeOf(InT)) or (unchecked_safe and input_fits_output)) {
        for (out, 0..) |*dest, idx| dest.* = -castDenseInt(OutT, items[items.len - 1 - idx]);
        return;
    }

    for (out, 0..) |*dest, idx| {
        dest.* = try negateCheckedCast(OutT, @as(i64, @intCast(items[items.len - 1 - idx])));
    }
}

fn fillIntScalarDenseResult(out: *HostIntResult, op: BuiltinId, scalar: i64, items: HostIntDenseView, scalar_left: bool, unchecked_safe: bool) KError!void {
    switch (items) {
        .dense => |view| try fillIntScalarArrayResult(out, op, scalar, view, scalar_left, unchecked_safe),
        .transpose => |view| {
            if (try fillIntScalarTransposeDenseResult(out, op, scalar, view, scalar_left, unchecked_safe)) return;
            for (0..hostIntDenseViewLen(items)) |idx| {
                const item = try hostIntDenseViewItem(items, idx);
                const lhs = if (scalar_left) scalar else item;
                const rhs = if (scalar_left) item else scalar;
                try out.set(idx, if (unchecked_safe) applyIntOpUnchecked(op, lhs, rhs) else try checkedIntOp(op, lhs, rhs));
            }
        },
        .range_iota, .flat_slice, .flat_stride, .flat_concat, .flat_segments, .first_axis_slice, .first_axis_index, .first_axis_concat => {
            if (fullReverseIntDenseViewSource(items)) |source| {
                try fillIntScalarReverseArrayResult(out, op, scalar, source, scalar_left, unchecked_safe);
                return;
            }
            for (0..hostIntDenseViewLen(items)) |idx| {
                const item = try hostIntDenseViewItem(items, idx);
                const lhs = if (scalar_left) scalar else item;
                const rhs = if (scalar_left) item else scalar;
                try out.set(idx, if (unchecked_safe) applyIntOpUnchecked(op, lhs, rhs) else try checkedIntOp(op, lhs, rhs));
            }
        },
    }
}

fn fillIntScalarReverseArrayResult(out: *HostIntResult, op: BuiltinId, scalar: i64, items: HostIntArrayView, scalar_left: bool, unchecked_safe: bool) KError!void {
    if (std.meta.activeTag(out.*) == .bit or std.meta.activeTag(items) == .bit) {
        const len = hostIntArrayViewLen(items);
        for (0..hostIntArrayViewLen(items)) |idx| {
            const item = hostIntViewItem(items, len - 1 - idx);
            const lhs = if (scalar_left) scalar else item;
            const rhs = if (scalar_left) item else scalar;
            try out.set(idx, if (unchecked_safe) applyIntOpUnchecked(op, lhs, rhs) else try checkedIntOp(op, lhs, rhs));
        }
        return;
    }
    switch (out.*) {
        .bit => unreachable,
        .int8 => |*dest| switch (items) {
            .int8 => |slice| try fillIntScalarReverseArrayTo(i8, i8, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int16 => |slice| try fillIntScalarReverseArrayTo(i8, i16, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int32 => |slice| try fillIntScalarReverseArrayTo(i8, i32, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int64 => |slice| try fillIntScalarReverseArrayTo(i8, i64, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .bit => unreachable,
        },
        .int16 => |*dest| switch (items) {
            .int8 => |slice| try fillIntScalarReverseArrayTo(i16, i8, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int16 => |slice| try fillIntScalarReverseArrayTo(i16, i16, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int32 => |slice| try fillIntScalarReverseArrayTo(i16, i32, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int64 => |slice| try fillIntScalarReverseArrayTo(i16, i64, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .bit => unreachable,
        },
        .int32 => |*dest| switch (items) {
            .int8 => |slice| try fillIntScalarReverseArrayTo(i32, i8, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int16 => |slice| try fillIntScalarReverseArrayTo(i32, i16, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int32 => |slice| try fillIntScalarReverseArrayTo(i32, i32, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int64 => |slice| try fillIntScalarReverseArrayTo(i32, i64, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .bit => unreachable,
        },
        .int64 => |*dest| switch (items) {
            .int8 => |slice| try fillIntScalarReverseArrayTo(i64, i8, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int16 => |slice| try fillIntScalarReverseArrayTo(i64, i16, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int32 => |slice| try fillIntScalarReverseArrayTo(i64, i32, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int64 => |slice| try fillIntScalarReverseArrayTo(i64, i64, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .bit => unreachable,
        },
    }
}

fn fillIntDenseReverseDenseResult(out: *HostIntResult, op: BuiltinId, forward: HostIntArrayView, reverse_source: HostIntArrayView, reverse_left: bool, unchecked_safe: bool) KError!void {
    const len = hostIntArrayViewLen(forward);
    if (hostIntArrayViewLen(reverse_source) != len) return error.Type;
    for (0..len) |idx| {
        const forward_value = hostIntViewItem(forward, idx);
        const reverse_value = hostIntViewItem(reverse_source, len - 1 - idx);
        const left_value = if (reverse_left) reverse_value else forward_value;
        const right_value = if (reverse_left) forward_value else reverse_value;
        try out.set(idx, if (unchecked_safe)
            applyIntOpUnchecked(op, left_value, right_value)
        else
            try checkedIntOp(op, left_value, right_value));
    }
}

fn reversedDenseVector(comptime T: type, comptime lane_count: usize, vec: @Vector(lane_count, T)) @Vector(lane_count, T) {
    const mask = comptime blk: {
        var values: [lane_count]i32 = undefined;
        for (0..lane_count) |idx| values[idx] = @intCast(lane_count - 1 - idx);
        break :blk @as(@Vector(lane_count, i32), values);
    };
    return @shuffle(T, vec, @as(@Vector(lane_count, T), undefined), mask);
}

fn fillIntDenseDenseResult(out: *HostIntResult, op: BuiltinId, left_items: HostIntDenseView, right_items: HostIntDenseView, unchecked_safe: bool) KError!void {
    if (std.meta.activeTag(out.*) == .bit and fillBitDenseDenseTransposeResult(&out.bit, op, left_items, right_items)) return;
    if (std.meta.activeTag(out.*) == .bit and fillBitDenseDenseSourceResult(&out.bit, op, left_items, right_items)) return;
    switch (left_items) {
        .dense => |left_view| switch (right_items) {
            .dense => |right_view| try fillIntArrayArrayResult(out, op, left_view, right_view, unchecked_safe),
            .range_iota, .flat_slice, .flat_stride, .flat_concat, .flat_segments, .first_axis_slice, .first_axis_index, .first_axis_concat, .transpose => {
                if (right_items == .first_axis_slice and right_items.first_axis_slice.row_step == -1) {
                    if (fullFirstAxisSliceSourceIntView(right_items.first_axis_slice)) |right_source| {
                        try fillIntDenseReverseDenseResult(out, op, left_view, right_source.view, false, unchecked_safe);
                        return;
                    }
                }
                for (0..hostIntDenseViewLen(left_items)) |idx| {
                    const left_value = try hostIntDenseViewItem(left_items, idx);
                    const right_value = try hostIntDenseViewItem(right_items, idx);
                    try out.set(idx, if (unchecked_safe) applyIntOpUnchecked(op, left_value, right_value) else try checkedIntOp(op, left_value, right_value));
                }
            },
        },
        .range_iota, .flat_slice, .flat_stride, .flat_concat, .flat_segments, .first_axis_slice, .first_axis_index, .first_axis_concat, .transpose => {
            if (left_items == .first_axis_slice and left_items.first_axis_slice.row_step == -1 and right_items == .dense) {
                if (fullFirstAxisSliceSourceIntView(left_items.first_axis_slice)) |left_source| {
                    try fillIntDenseReverseDenseResult(out, op, right_items.dense, left_source.view, true, unchecked_safe);
                    return;
                }
            }
            for (0..hostIntDenseViewLen(left_items)) |idx| {
                const left_value = try hostIntDenseViewItem(left_items, idx);
                const right_value = try hostIntDenseViewItem(right_items, idx);
                try out.set(idx, if (unchecked_safe) applyIntOpUnchecked(op, left_value, right_value) else try checkedIntOp(op, left_value, right_value));
            }
        },
    }
}

fn fillIntScalarArrayResult(out: *HostIntResult, op: BuiltinId, scalar: i64, items: HostIntArrayView, scalar_left: bool, unchecked_safe: bool) KError!void {
    if (std.meta.activeTag(out.*) == .bit) {
        return fillBitScalarArrayResultGeneric(&out.bit, op, scalar, items, scalar_left, unchecked_safe);
    }
    if (std.meta.activeTag(items) == .bit) {
        return switch (out.*) {
            .bit => unreachable,
            .int8 => |*dest| fillIntScalarBitArrayTo(i8, dest.items, op, scalar, items.bit, scalar_left, unchecked_safe),
            .int16 => |*dest| fillIntScalarBitArrayTo(i16, dest.items, op, scalar, items.bit, scalar_left, unchecked_safe),
            .int32 => |*dest| fillIntScalarBitArrayTo(i32, dest.items, op, scalar, items.bit, scalar_left, unchecked_safe),
            .int64 => |*dest| fillIntScalarBitArrayTo(i64, dest.items, op, scalar, items.bit, scalar_left, unchecked_safe),
        };
    }
    switch (out.*) {
        .bit => |*dest| try fillBitScalarArrayResultGeneric(dest, op, scalar, items, scalar_left, unchecked_safe),
        .int8 => |*dest| switch (items) {
            .int8 => |slice| try fillIntScalarArrayTo(i8, i8, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int16 => |slice| try fillIntScalarArrayTo(i8, i16, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int32 => |slice| try fillIntScalarArrayTo(i8, i32, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int64 => |slice| try fillIntScalarArrayTo(i8, i64, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .bit => unreachable,
        },
        .int16 => |*dest| switch (items) {
            .int8 => |slice| try fillIntScalarArrayTo(i16, i8, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int16 => |slice| try fillIntScalarArrayTo(i16, i16, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int32 => |slice| try fillIntScalarArrayTo(i16, i32, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int64 => |slice| try fillIntScalarArrayTo(i16, i64, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .bit => unreachable,
        },
        .int32 => |*dest| switch (items) {
            .int8 => |slice| try fillIntScalarArrayTo(i32, i8, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int16 => |slice| try fillIntScalarArrayTo(i32, i16, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int32 => |slice| try fillIntScalarArrayTo(i32, i32, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int64 => |slice| try fillIntScalarArrayTo(i32, i64, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .bit => unreachable,
        },
        .int64 => |*dest| switch (items) {
            .int8 => |slice| try fillIntScalarArrayTo(i64, i8, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int16 => |slice| try fillIntScalarArrayTo(i64, i16, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int32 => |slice| try fillIntScalarArrayTo(i64, i32, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .int64 => |slice| try fillIntScalarArrayTo(i64, i64, dest.items, op, scalar, slice, scalar_left, unchecked_safe),
            .bit => unreachable,
        },
    }
}

fn fillIntArrayArrayResult(out: *HostIntResult, op: BuiltinId, left_items: HostIntArrayView, right_items: HostIntArrayView, unchecked_safe: bool) KError!void {
    if (std.meta.activeTag(out.*) == .bit) {
        return fillBitArrayArrayResultGeneric(&out.bit, op, left_items, right_items, unchecked_safe);
    }
    if (std.meta.activeTag(left_items) == .bit or std.meta.activeTag(right_items) == .bit) {
        return switch (out.*) {
            .bit => unreachable,
            .int8 => |*dest| fillIntArrayArrayResultFromBit(i8, dest.items, op, left_items, right_items, unchecked_safe),
