const ProducedValue = union(enum) {
    const_int: struct {
        start: usize,
        end: usize,
        value: i64,
    },
    const_value: struct {
        start: usize,
        end: usize,
        value: Value,
    },
    load_local: struct {
        start: usize,
        end: usize,
        slot: u8,
    },
    local_const_op: struct {
        start: usize,
        end: usize,
        slot: u8,
        op: BuiltinId,
        const_value: i64,
    },
    local_local_op: struct {
        start: usize,
        end: usize,
        left_slot: u8,
        right_slot: u8,
        op: BuiltinId,
    },
    local_local_const_op: struct {
        start: usize,
        end: usize,
        left_slot: u8,
        right_slot: u8,
        op: BuiltinId,
        const_op: BuiltinId,
        const_value: i64,
    },
    scalar_dyad_op: struct {
        start: usize,
        end: usize,
        shape: u8,
        op: BuiltinId,
        left_slot: u8,
        right_slot: u8,
        const_value: i64,
    },
    scalar_dyad_const_op: struct {
        start: usize,
        end: usize,
        shape: u8,
        op: BuiltinId,
        left_slot: u8,
        right_slot: u8,
        const_value: i64,
        const_op: BuiltinId,
        compare_value: i64,
    },
    derived_global: struct {
        start: usize,
        end: usize,
        slot: u16,
        kind: DerivedVerbKind,
    },

    fn start(self: ProducedValue) usize {
        return switch (self) {
            .const_int => |inst| inst.start,
            .const_value => |inst| inst.start,
            .load_local => |inst| inst.start,
            .local_const_op => |inst| inst.start,
            .local_local_op => |inst| inst.start,
            .local_local_const_op => |inst| inst.start,
            .scalar_dyad_op => |inst| inst.start,
            .scalar_dyad_const_op => |inst| inst.start,
            .derived_global => |inst| inst.start,
        };
    }

    fn end(self: ProducedValue) usize {
        return switch (self) {
            .const_int => |inst| inst.end,
            .const_value => |inst| inst.end,
            .load_local => |inst| inst.end,
            .local_const_op => |inst| inst.end,
            .local_local_op => |inst| inst.end,
            .local_local_const_op => |inst| inst.end,
            .scalar_dyad_op => |inst| inst.end,
            .scalar_dyad_const_op => |inst| inst.end,
            .derived_global => |inst| inst.end,
        };
    }

    fn compactSpan(self: ProducedValue) ?CompactSpan {
        return .{
            .start = std.math.cast(u16, self.start()) orelse return null,
            .end = std.math.cast(u16, self.end()) orelse return null,
        };
    }

    fn compactStart(self: ProducedValue) ?u16 {
        return if (self.compactSpan()) |span| span.start else null;
    }
};

