    inline fn emitDyadBuiltinCall(self: *CodeEmitter, builtin: BuiltinId) KError!void {
        const id = compactDyadIdForBuiltinCall(builtin) orelse return error.Unsupported;
        try self.emitRawCompactOp(ckDyad(id), 2, 1);
