    fn appendAmend(self: *CodeEmitter, mode: AmendMode, deep: bool) KError!void {
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.compactAppendAmend(start, mode, deep);
    }

    fn appendCallBuiltinDerived2(self: *CodeEmitter, builtin: BuiltinId, kind: DerivedVerbKind) KError!void {
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.compactAppendCallBuiltinDerived2(start, builtin, kind);
    }

    fn emitConstInt(self: *CodeEmitter, value: i64) KError!void {
        const start = try self.beginCompactPayload(.none);
        self.compactAppendConstInt(start, value);
        self.noteSimple(.{ .const_int = .{ .start = start, .end = self.compact_len, .value = value } });
    }

    fn emitLoadLocal(self: *CodeEmitter, slot: u16) KError!void {
        const pooled = std.math.cast(u8, slot) orelse return error.Unsupported;
        const start = try self.beginCompactPayload(.none);
        self.compactAppendLoadLocal(start, pooled);
        self.noteSimple(.{ .load_local = .{ .start = start, .end = self.compact_len, .slot = pooled } });
    }

    fn emitStoreLocal(self: *CodeEmitter, slot: u16) KError!void {
        const pooled = std.math.cast(u8, slot) orelse return error.Unsupported;
        if (try self.tryShapeStoreLocalLocalConst(pooled)) return;
        if (try self.tryShapeStoreLocalGlobalCallSlots(pooled)) return;
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.compactAppendStoreLocal(start, pooled);
    }

    fn emitLoadGlobal(self: *CodeEmitter, slot: u16) KError!void {
        const start = try self.beginCompactPayload(.none);
        self.references_globals = true;
        self.compactAppendLoadGlobal(start, slot);
    }

    fn emitStoreGlobal(self: *CodeEmitter, slot: u16, want_result: bool) KError!void {
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.references_globals = true;
        self.compactAppendStoreGlobal(start, slot);
        if (!want_result) try self.appendDiscard();
    }

    fn tryShapeModifiedAssignConst(
        self: *CodeEmitter,
        target: ModifiedAssignTarget,
        slot: u16,
        builtin: BuiltinId,
        want_result: bool,
        rhs: ProducedValue,
    ) KError!bool {
        if (!self.simpleEndsAtCurrent(rhs)) return false;
        const rhs_value = switch (rhs) {
            .const_int => |inst| inst.value,
            .const_value => |inst| switch (inst.value.tag()) {
                .bool => @as(i64, @intFromBool(inst.value.asBool())),
                else => return false,
            },
            else => return false,
        };

        if (!self.truncateCompactToOffset(rhs.start())) return false;
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        switch (target) {
            .global => self.references_globals = true,
            .local => {},
        }
        switch (target) {
            .global => self.compactAppendModifyGlobalConst(start, slot, builtin, want_result, rhs_value),
            .local => self.compactAppendModifyLocalConst(start, std.math.cast(u8, slot) orelse return error.Unsupported, builtin, want_result, rhs_value),
        }
        return true;
    }

    fn emitModifiedAssignGlobal(self: *CodeEmitter, slot: u16, builtin: BuiltinId, want_result: bool, rhs: ?ProducedValue) KError!void {
        if (rhs) |simple| {
            if (try self.tryShapeModifiedAssignConst(.global, slot, builtin, want_result, simple)) return;
        }
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.references_globals = true;
        self.compactAppendModifyGlobalStack(start, slot, builtin, want_result);
    }

    fn emitModifiedAssignLocal(self: *CodeEmitter, slot: u16, builtin: BuiltinId, want_result: bool, rhs: ?ProducedValue) KError!void {
        const pooled = std.math.cast(u8, slot) orelse return error.Unsupported;
        if (rhs) |simple| {
            if (try self.tryShapeModifiedAssignConst(.local, slot, builtin, want_result, simple)) return;
        }
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.compactAppendModifyLocalStack(start, pooled, builtin, want_result);
    }

    fn emitIndexedAssignGlobal(self: *CodeEmitter, slot: u16, mode: AmendMode, builtin: BuiltinId, want_result: bool) KError!void {
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.references_globals = true;
        self.compactAppendAssignIndexGlobalStack(start, slot, mode, builtin, want_result);
    }

    fn tryShapeIndexedAssignGlobalSources(
        self: *CodeEmitter,
        slot: u16,
        mode: AmendMode,
        builtin: BuiltinId,
        want_result: bool,
        selector: ProducedValue,
        rhs: ProducedValue,
    ) KError!bool {
        if (!self.simpleIsAdjacent(rhs, selector) or !self.simpleEndsAtCurrent(selector)) return false;
        const selector_source = simpleGlobalCallArg(selector) orelse return false;
        const rhs_source = simpleGlobalCallArg(rhs) orelse return false;

        if (!self.truncateCompactToOffset(rhs.start())) return false;
        self.invalidateSimple();
        const compact_start = try self.beginCompactPayload(.none);
        self.references_globals = true;
        self.compactAppendAssignIndexGlobalSources(compact_start, slot, mode, builtin, want_result, selector_source, rhs_source);
        return true;
    }

    fn emitIndexedAssignLocal(self: *CodeEmitter, slot: u16, mode: AmendMode, builtin: BuiltinId, want_result: bool) KError!void {
        const pooled = std.math.cast(u8, slot) orelse return error.Unsupported;
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.compactAppendAssignIndexLocalStack(start, pooled, mode, builtin, want_result);
    }

    fn tryShapeIndexedAssignLocalSources(
        self: *CodeEmitter,
        slot: u16,
        mode: AmendMode,
        builtin: BuiltinId,
        want_result: bool,
        selector: ProducedValue,
        rhs: ProducedValue,
    ) KError!bool {
        if (!self.simpleIsAdjacent(rhs, selector) or !self.simpleEndsAtCurrent(selector)) return false;
        const selector_source = simpleGlobalCallArg(selector) orelse return false;
        const rhs_source = simpleGlobalCallArg(rhs) orelse return false;
        const pooled = std.math.cast(u8, slot) orelse return error.Unsupported;

        if (!self.truncateCompactToOffset(rhs.start())) return false;
        self.invalidateSimple();
        const compact_start = try self.beginCompactPayload(.none);
        self.compactAppendAssignIndexLocalSources(compact_start, pooled, mode, builtin, want_result, selector_source, rhs_source);
        return true;
    }

    fn patchLoadLocalToTake(self: *CodeEmitter, source: CompactLocalSourceRef) void {
        _ = self.patchCompactLoadLocalToTake(source);
    }

    fn patchGlobalCallArgConsumeBit(self: *CodeEmitter, compact_offset: u16) void {
        if (self.compact_valid and compact_offset < self.compact_len) {
            self.compact_bytes.items[compact_offset] |= global_call_arg_consume_bit;
        }
    }

    fn patchSourceStoreLocalDirect(self: *CodeEmitter, inst: LastInstruction, dst_slot: u8) KError!bool {
        const kind = inst.kind;
        const shaped: struct { kind: PatchableInstructionKind, compact_op: u8 } = switch (kind) {
            .index_global_source => .{
                .kind = .index_global_source_store_local,
                .compact_op = ck_index_global_source_store_local_u8,
            },
            .call_global_slots => .{
                .kind = .call_global_slots_store_local,
                .compact_op = ck_call_global_slots_u8,
            },
            else => return false,
        };
        const compact_start: usize = inst.compact_start;
        switch (kind) {
            .index_global_source => {
                if (self.compact_bytes.items[compact_start] != ck_index_global_source_u8) return false;
            },
            .call_global_slots => {
                if (compact_start + 2 >= self.compact_len or self.compact_bytes.items[compact_start] != ck_call_global_slots_u8) return false;
                const flags = self.compact_bytes.items[compact_start + 2];
                if (compactCallIsTail(flags) or compactCallStoresLocal(flags)) return false;
            },
            else => unreachable,
        }

        if (kind == .index_global_source) {
            self.compact_bytes.items[compact_start] = shaped.compact_op;
        } else {
            self.compact_bytes.items[compact_start + 2] |= compact_call_store_local_bit;
        }
        if (!self.compactAppendByte(dst_slot)) return error.Unsupported;
        if (self.compact_stack_depth != 0) self.compact_stack_depth -= 1;
        self.last_instruction = .{
            .kind = shaped.kind,
            .compact_start = @intCast(compact_start),
        };
        return true;
    }

    fn patchSourceTailDirect(self: *CodeEmitter, inst: LastInstruction, shaped: PatchableInstructionKind) bool {
        const kind = inst.kind;
        const compact_start: usize = inst.compact_start;
        switch (kind) {
            .index_global_source => {
                if (shaped != .tail_index_global_source or self.compact_bytes.items[compact_start] != ck_index_global_source_u8) return false;
                self.compact_bytes.items[compact_start] = ck_tail_index_global_source_u8;
            },
            .call_global_slots => {
                if (shaped != .tail_call_global_slots or compact_start + 2 >= self.compact_len or self.compact_bytes.items[compact_start] != ck_call_global_slots_u8) return false;
                const flags = self.compact_bytes.items[compact_start + 2];
                if (compactCallStoresLocal(flags) or compactCallIsTail(flags)) return false;
                self.compact_bytes.items[compact_start + 2] = flags | compact_call_tail_bit;
            },
            else => return false,
        }
        if (self.compact_stack_depth != 0) self.compact_stack_depth -= 1;
        self.last_instruction = .{
            .kind = shaped,
            .compact_start = @intCast(compact_start),
        };
        return true;
    }

    fn patchCallTailDirect(self: *CodeEmitter, inst: LastInstruction, shaped: PatchableInstructionKind) bool {
        const kind = inst.kind;
        const compact_start: usize = inst.compact_start;
        switch (kind) {
            .call_stack => {
                if (shaped != .tail_call_stack or compact_start + 1 >= self.compact_len or self.compact_bytes.items[compact_start] != ck_call_stack_u8) return false;
                const flags = self.compact_bytes.items[compact_start + 1];
                if (compactCallStoresLocal(flags) or compactCallIsTail(flags)) return false;
                self.compact_bytes.items[compact_start + 1] = flags | compact_call_tail_bit;
            },
            .call_global_stack => {
                if (shaped != .tail_call_global_stack or compact_start + 2 >= self.compact_len or self.compact_bytes.items[compact_start] != ck_call_global_stack_u8) return false;
                const flags = self.compact_bytes.items[compact_start + 2];
                if (compactCallStoresLocal(flags) or compactCallIsTail(flags)) return false;
                self.compact_bytes.items[compact_start + 2] = flags | compact_call_tail_bit;
            },
            .index_local_source,
            => {
                if (shaped != .tail_index_local_source or self.compact_bytes.items[compact_start] != ck_index_local_source_u8) return false;
                self.compact_bytes.items[compact_start] = ck_tail_index_local_source_u8;
            },
            else => return false,
        }
        if (self.compact_stack_depth != 0) self.compact_stack_depth -= 1;
        self.last_instruction = .{
            .kind = shaped,
            .compact_start = @intCast(compact_start),
        };
        return true;
    }

    fn patchBranchTarget(self: *CodeEmitter, patch: BranchPatch, target: InstructionPosition) KError!void {
        if (self.compact_valid) {
            if (patch.compact_payload_offset) |compact_payload_offset| {
                const target_label = target.branchLabel();
                if (compact_payload_offset < self.compact_len and self.compactRecordBranchPatch(target_label, compact_payload_offset)) {
                    self.compact_bytes.items[compact_payload_offset] = @intCast(target_label.compact_offset & 0xff);
                    self.compact_bytes.items[compact_payload_offset + 1] = @intCast(target_label.compact_offset >> 8);
                    return;
                }
            }
        }
        self.invalidateCompact();
    }

    fn emitJumpIfFalsePlaceholder(self: *CodeEmitter) KError!BranchPatch {
        if (try self.tryShapeJumpIfFalseScalarDyadConst()) |patch| return patch;
        if (try self.tryShapeJumpIfFalseLocalLocal()) |patch| return patch;
        if (try self.tryShapeJumpIfFalseLocalConst()) |patch| return patch;
        self.invalidateSimple();
        const compact_start = try self.beginControlCompactPayload();
        const compact_payload_offset = self.compactAppendJumpIfFalsePlaceholder(compact_start);
        return .{
            .compact_payload_offset = compact_payload_offset,
        };
    }

    fn tryShapeJumpIfFalseScalarDyadConst(self: *CodeEmitter) KError!?BranchPatch {
        const value = self.last_simple orelse return null;
        if (!self.simpleEndsAtCurrent(value)) return null;
        const inst = switch (value) {
            .scalar_dyad_const_op => |op_inst| op_inst,
            else => return null,
        };
        if (!self.truncateCompactToOffset(inst.start)) return null;
        self.invalidateSimple();
        const compact_start = try self.beginControlCompactPayload();
        const compact_payload_offset = self.compactAppendJumpIfFalseScalarDyadConstPlaceholder(compact_start, inst);
        return .{
            .compact_payload_offset = compact_payload_offset,
        };
    }

    fn emitJumpPlaceholder(self: *CodeEmitter) KError!BranchPatch {
        self.invalidateSimple();
        const compact_start = try self.beginControlCompactPayload();
        const compact_payload_offset = self.compactAppendJumpPlaceholder(compact_start);
        return .{
            .compact_payload_offset = compact_payload_offset,
        };
    }

    fn tryShapeJumpIfFalseLocalLocal(self: *CodeEmitter) KError!?BranchPatch {
        const shaped: struct {
            op: BuiltinId,
            left_slot: u8,
            right_slot: u8,
            start: usize,
        } = if (self.last_simple) |value| blk: {
            if (!self.simpleEndsAtCurrent(value)) return null;
            const inst = switch (value) {
                .local_local_op => |op_inst| op_inst,
                else => return null,
            };
            break :blk .{
                .op = switch (inst.op) {
                    .equal => .equal,
                    .less => .less,
                    .more => .more,
                    else => return null,
                },
                .left_slot = inst.left_slot,
                .right_slot = inst.right_slot,
                .start = inst.start,
            };
        } else blk: {
            const inst = self.lastCompactInstruction() orelse return null;
            const start: usize = inst.compact_start;
            if (start + 3 != self.compact_len) return null;
            const raw = self.compact_bytes.items[start];
            break :blk .{
                .op = switch (raw) {
                    ck_equal_local_local => .equal,
                    ck_less_local_local => .less,
                    ck_more_local_local => .more,
                    else => return null,
                },
                .left_slot = self.compact_bytes.items[start + 1],
                .right_slot = self.compact_bytes.items[start + 2],
                .start = start,
            };
        };

        if (!self.truncateCompactToOffset(shaped.start)) return null;
        self.invalidateSimple();
        const compact_start = try self.beginControlCompactPayload();
        const compact_payload_offset = self.compactAppendJumpIfFalseLocalLocalPlaceholder(compact_start, shaped.op, shaped.left_slot, shaped.right_slot);
        return .{
            .compact_payload_offset = compact_payload_offset,
        };
    }

    fn tryShapeJumpIfFalseLocalConst(self: *CodeEmitter) KError!?BranchPatch {
        const value = self.last_simple orelse return null;
        if (!self.simpleEndsAtCurrent(value)) return null;
        const inst = switch (value) {
            .local_const_op => |op_inst| op_inst,
            else => return null,
        };
        const shaped: struct {
            op: BuiltinId,
            slot: u8,
            const_value: i64,
        } = .{
            .op = switch (inst.op) {
                .equal => .equal,
                .less => .less,
                .more => .more,
                else => return null,
            },
            .slot = inst.slot,
            .const_value = inst.const_value,
        };

        if (!self.truncateCompactToOffset(inst.start)) return null;
        self.invalidateSimple();
        const compact_start = try self.beginControlCompactPayload();
        const compact_payload_offset = self.compactAppendJumpIfFalseLocalConstPlaceholder(compact_start, shaped.op, shaped.slot, shaped.const_value);
        return .{
            .compact_payload_offset = compact_payload_offset,
        };
    }

    fn enrichSimple(self: *const CodeEmitter, simple: ProducedValue) ProducedValue {
        _ = self;
        return simple;
    }

    fn simpleEndsAtCurrent(self: *const CodeEmitter, simple: ProducedValue) bool {
        if (self.compact_valid) {
            if (simple.compactSpan()) |span| return span.end == self.compact_len;
        }
        return simple.end() == self.compact_len;
    }

    fn simpleStartsAtOrAfterPosition(self: *const CodeEmitter, simple: ProducedValue, pos: InstructionPosition) bool {
        if (self.compact_valid) {
            if (simple.compactSpan()) |span| return span.start >= pos.compact_offset;
        }
        return simple.start() >= pos.compact_offset;
    }

    fn simpleIsAdjacent(self: *const CodeEmitter, left: ProducedValue, right: ProducedValue) bool {
        if (self.compact_valid) {
            if (left.compactSpan()) |left_span| {
                if (right.compactSpan()) |right_span| return left_span.end == right_span.start;
            }
        }
        return left.end() == right.start();
    }

    fn simpleNumericInt(simple: ProducedValue) ?i64 {
        return switch (simple) {
            .const_int => |inst| inst.value,
            .const_value => |inst| switch (inst.value.tag()) {
                .int => inst.value.asInt(),
                .bool => @intFromBool(inst.value.asBool()),
                else => null,
            },
            else => null,
        };
    }

    fn internConstant(self: *CodeEmitter, value: Value) KError!u16 {
        var idx: usize = 0;
        while (idx < self.constant_len) : (idx += 1) {
            if (constantMatches(self.constants.items[idx], value)) return std.math.cast(u16, idx) orelse return error.Unsupported;
        }
        const allocator = self.allocator orelse return error.Unsupported;
        if (self.constant_len > std.math.maxInt(u16)) return error.Unsupported;
        try self.constants.append(allocator, value);
        self.constant_len += 1;
        return std.math.cast(u16, self.constant_len - 1) orelse return error.Unsupported;
    }

    fn tryFoldConstIntDyad(self: *CodeEmitter, op: BuiltinId) KError!bool {
        const left = self.last_simple orelse return false;
        const right = self.previous_simple orelse return false;
        if (!self.simpleIsAdjacent(right, left) or !self.simpleEndsAtCurrent(left)) return false;
        const left_value = simpleNumericInt(left) orelse return false;
        const right_value = simpleNumericInt(right) orelse return false;

        const result = switch (op) {
            .add => @addWithOverflow(left_value, right_value),
            .sub => @subWithOverflow(left_value, right_value),
            .mul => @mulWithOverflow(left_value, right_value),
            .iota => .{ bangIntOp(left_value, right_value), @as(u1, 0) },
            .div => return false,
            else => return false,
        };
        if (result[1] != 0 or !Value.fitsInlineInt(result[0])) return false;

        if (!self.truncateCompactToOffset(right.start())) return false;
        self.invalidateSimple();
        try self.emitConstInt(result[0]);
        return true;
    }

    fn tryFoldConstIntUnaryNegate(self: *CodeEmitter) KError!bool {
        const value = self.last_simple orelse return false;
        if (!self.simpleEndsAtCurrent(value)) return false;
        const int_value = simpleNumericInt(value) orelse return false;
        const result = @subWithOverflow(@as(i64, 0), int_value);
        if (result[1] != 0 or !Value.fitsInlineInt(result[0])) return false;

        if (!self.truncateCompactToOffset(value.start())) return false;
        self.invalidateSimple();
        try self.emitConstInt(result[0]);
        return true;
    }

    fn tryShapeDyad(self: *CodeEmitter, op: BuiltinId) KError!bool {
        const left = self.last_simple orelse return false;
        const right = self.previous_simple orelse return false;
        if (!self.simpleIsAdjacent(right, left) or !self.simpleEndsAtCurrent(left)) return false;

        const shaped: ?struct { op: BuiltinId, left_slot: u8, right_slot: u8 } = switch (left) {
            .load_local => |left_inst| switch (right) {
                .load_local => |right_inst| .{ .op = switch (op) {
                    .add, .sub, .mul, .iota, .minimum, .maximum, .less, .more, .equal => op,
                    .div => return false,
                    else => return false,
                }, .left_slot = left_inst.slot, .right_slot = right_inst.slot },
                else => null,
            },
            else => null,
        };
        if (shaped == null) return false;

        if (!self.truncateCompactToOffset(right.start())) return false;
        const selector_shape: ?struct { left_slot: u8, right_slot: u8, op: BuiltinId } = switch (left) {
            .load_local => |left_inst| switch (right) {
                .load_local => |right_inst| switch (op) {
                    .add, .sub => .{ .left_slot = left_inst.slot, .right_slot = right_inst.slot, .op = op },
                    else => null,
                },
                else => null,
            },
            else => null,
        };
        if (selector_shape) |selector| {
            const start = try self.beginCompactPayload(.none);
            self.compactAppendLocalLocalOp(start, shaped.?.op, shaped.?.left_slot, shaped.?.right_slot);
            self.replaceSimpleTail(2, .{
                .local_local_op = .{
                    .start = right.start(),
                    .end = self.compact_len,
                    .left_slot = selector.left_slot,
                    .right_slot = selector.right_slot,
                    .op = selector.op,
                },
            });
            return true;
        }

        if (shaped.?.op == .iota) {
            const start = try self.beginCompactPayload(.none);
            self.compactAppendLocalLocalOp(start, shaped.?.op, shaped.?.left_slot, shaped.?.right_slot);
            self.replaceSimpleTail(2, .{
                .scalar_dyad_op = .{
                    .start = right.start(),
                    .end = self.compact_len,
                    .shape = compact_scalar_dyad_local_local,
                    .op = shaped.?.op,
                    .left_slot = shaped.?.left_slot,
                    .right_slot = shaped.?.right_slot,
                    .const_value = 0,
                },
            });
            return true;
        }

        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.compactAppendLocalLocalOp(start, shaped.?.op, shaped.?.left_slot, shaped.?.right_slot);
        return true;
    }

    fn tryShapeConstDyad(self: *CodeEmitter, op: BuiltinId) KError!bool {
        const left = self.last_simple orelse return false;
        const right = self.previous_simple orelse return false;
        if (!self.simpleIsAdjacent(right, left) or !self.simpleEndsAtCurrent(left)) return false;

        if (switch (left) {
            .scalar_dyad_op => true,
            else => false,
        } and switch (right) {
            .const_int => true,
            else => false,
        }) {
            const left_inst = switch (left) {
                .scalar_dyad_op => |inst| inst,
                else => unreachable,
            };
            const right_inst = switch (right) {
                .const_int => |inst| inst,
                else => unreachable,
            };
            switch (op) {
                .equal, .less, .more => {},
                else => return false,
            }
            try self.emitDyadBuiltinCall(op);
            self.replaceSimpleTail(2, .{
                .scalar_dyad_const_op = .{
                    .start = right_inst.start,
                    .end = self.compact_len,
                    .shape = left_inst.shape,
                    .op = left_inst.op,
                    .left_slot = left_inst.left_slot,
                    .right_slot = left_inst.right_slot,
                    .const_value = left_inst.const_value,
                    .const_op = op,
                    .compare_value = right_inst.value,
                },
            });
            return true;
        }

        if (switch (left) {
            .local_const_op => true,
            else => false,
        } and switch (right) {
            .const_int => true,
            else => false,
        }) {
            const left_inst = switch (left) {
                .local_const_op => |inst| inst,
                else => unreachable,
            };
            const right_inst = switch (right) {
                .const_int => |inst| inst,
                else => unreachable,
            };
            switch (left_inst.op) {
                .add, .sub, .mul, .minimum, .maximum, .iota => {},
                else => return false,
            }
            switch (op) {
                .equal, .less, .more => {},
                else => return false,
            }
            try self.emitDyadBuiltinCall(op);
            self.replaceSimpleTail(2, .{
                .scalar_dyad_const_op = .{
                    .start = right_inst.start,
                    .end = self.compact_len,
                    .shape = compact_scalar_dyad_local_const_i64,
                    .op = left_inst.op,
                    .left_slot = left_inst.slot,
                    .right_slot = 0,
                    .const_value = left_inst.const_value,
                    .const_op = op,
                    .compare_value = right_inst.value,
                },
            });
            return true;
        }

        if (switch (left) {
            .local_local_op => true,
            else => false,
        } and switch (right) {
            .const_int => true,
            else => false,
        }) {
            const left_inst = switch (left) {
                .local_local_op => |inst| inst,
                else => unreachable,
            };
            const right_inst = switch (right) {
                .const_int => |inst| inst,
                else => unreachable,
            };
            switch (op) {
                .equal, .less, .more => {
                    try self.emitDyadBuiltinCall(op);
                    self.replaceSimpleTail(2, .{
                        .scalar_dyad_const_op = .{
                            .start = right_inst.start,
                            .end = self.compact_len,
                            .shape = compact_scalar_dyad_local_local,
                            .op = left_inst.op,
                            .left_slot = left_inst.left_slot,
                            .right_slot = left_inst.right_slot,
                            .const_value = 0,
                            .const_op = op,
                            .compare_value = right_inst.value,
                        },
                    });
                    return true;
                },
                .add, .sub => {},
                else => return false,
            }
            try self.emitDyadBuiltinCall(op);
            self.replaceSimpleTail(2, .{
                .local_local_const_op = .{
                    .start = right_inst.start,
                    .end = self.compact_len,
                    .left_slot = left_inst.left_slot,
                    .right_slot = left_inst.right_slot,
                    .op = left_inst.op,
                    .const_op = op,
                    .const_value = right_inst.value,
                },
            });
            return true;
        }

        const shaped: ?struct { op: BuiltinId, const_value: i64, slot: u8, const_first: bool } = switch (left) {
            .const_int => |left_inst| switch (right) {
                .load_local => |right_inst| .{
                    .op = switch (op) {
                        .add, .sub, .mul, .iota, .minimum, .maximum, .less, .more, .equal => op,
                        .div => return false,
                        else => return false,
                    },
                    .const_value = left_inst.value,
                    .slot = right_inst.slot,
                    .const_first = true,
                },
                else => null,
            },
            .load_local => |left_inst| switch (right) {
                .const_int => |right_inst| .{
                    .op = switch (op) {
                        .add, .sub, .mul, .iota, .minimum, .maximum, .less, .more, .equal => op,
                        .div => return false,
                        else => return false,
                    },
                    .const_value = right_inst.value,
                    .slot = left_inst.slot,
                    .const_first = false,
                },
                else => null,
            },
            else => null,
        };
        if (shaped == null) return false;

        if (!self.truncateCompactToOffset(right.start())) return false;
        const local_const_shape: ?struct { slot: u8, op: BuiltinId, const_value: i64 } = if (!shaped.?.const_first) switch (left) {
            .load_local => |left_inst| .{
                .slot = left_inst.slot,
                .op = op,
                .const_value = shaped.?.const_value,
            },
            else => null,
        } else null;
        if (local_const_shape) |local_const| {
            const start = try self.beginCompactPayload(.none);
            self.compactAppendLocalConstOp(start, shaped.?.op, shaped.?.slot, shaped.?.const_value);
            if (shaped.?.op == .iota) {
                self.replaceSimpleTail(2, .{
                    .scalar_dyad_op = .{
                        .start = right.start(),
                        .end = self.compact_len,
                        .shape = compact_scalar_dyad_local_const_i64,
                        .op = local_const.op,
                        .left_slot = local_const.slot,
                        .right_slot = 0,
                        .const_value = local_const.const_value,
                    },
                });
            } else {
                self.replaceSimpleTail(2, .{
                    .local_const_op = .{
                        .start = right.start(),
                        .end = self.compact_len,
                        .slot = local_const.slot,
                        .op = local_const.op,
                        .const_value = local_const.const_value,
                    },
                });
            }
            return true;
        }

        const const_first_comparison_shape: ?struct { slot: u8, op: BuiltinId, const_value: i64 } = if (shaped.?.const_first) switch (op) {
            .equal => .{
                .slot = shaped.?.slot,
                .op = .equal,
                .const_value = shaped.?.const_value,
            },
            .less => .{
                .slot = shaped.?.slot,
                .op = .more,
                .const_value = shaped.?.const_value,
            },
            .more => .{
                .slot = shaped.?.slot,
                .op = .less,
                .const_value = shaped.?.const_value,
            },
            else => null,
        } else null;
        if (const_first_comparison_shape) |local_const| {
            const start = try self.beginCompactPayload(.none);
            self.compactAppendConstLocalOp(start, shaped.?.op, shaped.?.const_value, shaped.?.slot);
            self.replaceSimpleTail(2, .{
                .local_const_op = .{
                    .start = right.start(),
                    .end = self.compact_len,
                    .slot = local_const.slot,
                    .op = local_const.op,
                    .const_value = local_const.const_value,
                },
            });
            return true;
        }

        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        if (shaped.?.const_first) {
            self.compactAppendConstLocalOp(start, shaped.?.op, shaped.?.const_value, shaped.?.slot);
            if (shaped.?.op == .iota) {
                self.noteSimple(.{
                    .scalar_dyad_op = .{
                        .start = right.start(),
                        .end = self.compact_len,
                        .shape = compact_scalar_dyad_const_local_i64,
                        .op = shaped.?.op,
                        .left_slot = 0,
                        .right_slot = shaped.?.slot,
                        .const_value = shaped.?.const_value,
                    },
                });
            }
        } else {
            self.compactAppendLocalConstOp(start, shaped.?.op, shaped.?.slot, shaped.?.const_value);
            if (shaped.?.op == .iota) {
                self.noteSimple(.{
                    .scalar_dyad_op = .{
                        .start = right.start(),
                        .end = self.compact_len,
                        .shape = compact_scalar_dyad_local_const_i64,
                        .op = shaped.?.op,
                        .left_slot = shaped.?.slot,
                        .right_slot = 0,
                        .const_value = shaped.?.const_value,
                    },
                });
            }
        }
        return true;
    }

    fn tryShapeStoreLocalLocalConst(self: *CodeEmitter, dst_slot: u8) KError!bool {
        const value = self.last_simple orelse return false;
        if (!self.simpleEndsAtCurrent(value)) return false;
        const inst = switch (value) {
            .local_const_op => |op_inst| op_inst,
            else => return false,
        };
        const op: BuiltinId = switch (inst.op) {
            .add => .add,
            .sub => .sub,
            .mul => .mul,
            else => return false,
        };

        if (!self.truncateCompactToOffset(inst.start)) return false;
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.compactAppendStoreLocalLocalConst(start, op, dst_slot, inst.slot, inst.const_value);
        return true;
    }

    fn tryShapeStoreLocalGlobalCallSlots(self: *CodeEmitter, dst_slot: u8) KError!bool {
        const last = self.lastCompactInstruction() orelse return false;
        switch (last.kind) {
            .call_global_slots, .index_global_source => {
                if (!(try self.patchSourceStoreLocalDirect(last, dst_slot))) {
                    return false;
                }
            },
            else => return false,
        }
        self.invalidateSimple();
        return true;
    }

    fn tryShapeCall1(self: *CodeEmitter) KError!bool {
        const callee = self.last_simple orelse return false;
        const arg = self.previous_simple orelse return false;
        if (!self.simpleIsAdjacent(arg, callee) or !self.simpleEndsAtCurrent(callee)) return false;

        switch (callee) {
            .load_local => |callee_inst| {
                const source = simpleGlobalCallArg(arg) orelse return false;
                if (!self.truncateCompactToOffset(arg.start())) return false;
                self.invalidateSimple();
                const start = try self.beginCompactPayload(.index_local_source);
                self.compactAppendIndexLocalSource(start, callee_inst.slot, source);
                return true;
            },
            else => return false,
        }
    }

    fn simpleGlobalCallArg(simple: ProducedValue) ?GlobalCallArgSource {
        const source: ?GlobalCallArgSource = switch (simple) {
            .load_local => |inst| .{
                .local = .{
                    .slot = inst.slot,
                    .consume = false,
                },
            },
            .const_int => |inst| .{ .const_int = inst.value },
            .const_value => |inst| switch (inst.value.tag()) {
                .bool => .{ .const_bool = inst.value.asBool() },
                else => null,
            },
            .local_const_op => |inst| .{
                .local_const_op = .{
                    .slot = inst.slot,
                    .consume = false,
                    .op = inst.op,
                    .const_value = inst.const_value,
                },
            },
            .local_local_op => |inst| .{
                .local_local_op = .{
                    .left_slot = inst.left_slot,
                    .right_slot = inst.right_slot,
                    .op = inst.op,
                },
            },
            .local_local_const_op => |inst| .{
                .local_local_const_op = .{
                    .left_slot = inst.left_slot,
                    .right_slot = inst.right_slot,
                    .op = inst.op,
                    .const_op = inst.const_op,
                    .const_value = inst.const_value,
                },
            },
            .scalar_dyad_op => |inst| .{
                .scalar_dyad_op = .{
                    .shape = inst.shape,
                    .op = inst.op,
                    .left_slot = inst.left_slot,
                    .right_slot = inst.right_slot,
                    .const_value = inst.const_value,
                },
            },
            else => null,
        };
        return supportedGlobalCallArgSource(source orelse return null);
    }

    fn appendGlobalDerivedStackCall(self: *CodeEmitter, slot: u16, kind: DerivedVerbKind, argc: u8) KError!void {
        if (argc == 0) return error.Unsupported;
        if (argc > max_direct_apply_args) return error.Unsupported;
        self.invalidateSimple();
        const start = try self.beginCompactPayload(.none);
        self.references_globals = true;
        self.compactAppendGlobalDerivedStackCall(start, slot, kind, argc);
    }

    fn tryRewriteTailCall(self: *CodeEmitter) bool {
        const last = self.lastCompactInstruction() orelse return false;
        const kind = last.kind;
        const shaped: ?PatchableInstructionKind = switch (kind) {
            .index_local_source => .tail_index_local_source,
            .call_stack => .tail_call_stack,
            .call_global_stack => .tail_call_global_stack,
            .call_global_slots => .tail_call_global_slots,
            .index_global_source => .tail_index_global_source,
            else => null,
        };
        if (shaped == null) return false;
        const source_ok = self.patchSourceTailDirect(last, shaped.?);
        const call_ok = if (!source_ok) self.patchCallTailDirect(last, shaped.?) else false;
        if (!source_ok and !call_ok) return false;
        self.invalidateSimple();
        return true;
    }

    fn applyPostCompile(self: *CodeEmitter, mode: PostCompileMode) void {
        switch (mode) {
            .top_level => {},
            .tail_position => _ = self.tryRewriteTailCall(),
        }
    }

    fn invalidateSimple(self: *CodeEmitter) void {
        self.previous_simple = null;
        self.last_simple = null;
        self.simple_history_len = 0;
    }

    fn refreshSimplePointers(self: *CodeEmitter) void {
        self.last_simple = if (self.simple_history_len >= 1) self.simple_history[self.simple_history_len - 1] else null;
        self.previous_simple = if (self.simple_history_len >= 2) self.simple_history[self.simple_history_len - 2] else null;
    }

    fn replaceSimpleTail(self: *CodeEmitter, count: usize, simple: ProducedValue) void {
        const enriched = self.enrichSimple(simple);
        if (count > self.simple_history_len) {
            self.invalidateSimple();
            self.noteSimple(enriched);
            return;
        }
        self.simple_history_len -= count;
        if (self.simple_history_len == self.simple_history.len) {
            std.mem.copyForwards(ProducedValue, self.simple_history[0 .. self.simple_history.len - 1], self.simple_history[1..]);
            self.simple_history_len -= 1;
        }
        self.simple_history[self.simple_history_len] = enriched;
        self.simple_history_len += 1;
        self.refreshSimplePointers();
    }

    fn noteSimple(self: *CodeEmitter, simple: ProducedValue) void {
        const enriched = self.enrichSimple(simple);
        if (self.simple_history_len == self.simple_history.len) {
            std.mem.copyForwards(ProducedValue, self.simple_history[0 .. self.simple_history.len - 1], self.simple_history[1..]);
            self.simple_history_len -= 1;
        }
        self.simple_history[self.simple_history_len] = enriched;
        self.simple_history_len += 1;
        self.refreshSimplePointers();
    }
};

fn identMatches(stored: IdentRef, query: IdentRef) bool {
    if (stored.key.len != query.key.len) return false;
    if (stored.key.prefix != query.key.prefix) return false;
    if (stored.key.len <= 8) return true;
    return std.mem.eql(u8, stored.text, query.text);
}

fn identRefFromText(text: []const u8) IdentRef {
    return .{
        .text = text,
        .key = IdentKey.fromText(text),
    };
}

fn identIsDottedPath(ident: IdentRef) bool {
    return std.mem.indexOfScalar(u8, ident.text, '.') != null;
}

fn scanIdentifierTextEnd(source: []const u8, start: usize) ?usize {
    if (start >= source.len or !isIdentStart(source[start])) return null;
    var end = start + 1;
    while (end < source.len and isIdentContinue(source[end])) : (end += 1) {}
    return end;
}

fn scanIdentifierPathTextEnd(source: []const u8, start: usize) ?usize {
    var end = scanIdentifierTextEnd(source, start) orelse return null;
    while (end < source.len and source[end] == '.' and end + 1 < source.len and isIdentStart(source[end + 1])) {
        end = scanIdentifierTextEnd(source, end + 1) orelse return null;
    }
    return end;
}

fn sourceReferencesIdentCurrentLambda(source: []const u8, ident: IdentRef) bool {
    var index: usize = 0;
    var brace_depth: usize = 0;
    while (index < source.len) {
        const ch = source[index];
        if (ch == '"') {
            const end = scanStringLiteralEnd(source, index) orelse break;
            index = end + 1;
            continue;
        }
        if (ch == '`') {
            index += 1;
            while (index < source.len and isIdentContinue(source[index])) : (index += 1) {}
            continue;
        }
        if (ch == '{') {
            brace_depth += 1;
            index += 1;
            continue;
        }
        if (ch == '}') {
            if (brace_depth != 0) brace_depth -= 1;
            index += 1;
            continue;
        }
        if (brace_depth == 0 and isIdentStart(ch)) {
            const start = index;
            index = scanIdentifierPathTextEnd(source, start) orelse return false;
            if (identMatches(identRefFromText(source[start..index]), ident)) return true;
            continue;
        }
        index += 1;
    }
    return false;
}

fn optionalNumericShapeMatches(left: Value, right: Value) bool {
    const left_shape = valueNonVectorNumericShape(left);
    const right_shape = valueNonVectorNumericShape(right);
    if (left_shape == null or right_shape == null) return left_shape == null and right_shape == null;
    return numericShapeSnapshotEqual(left_shape.?, right_shape.?);
}

fn hostDenseConstantMatches(left: Value, right: Value) bool {
    if (!optionalNumericShapeMatches(left, right)) return false;
    const left_host = hostDenseIfPresent(left) orelse return false;
    const right_host = hostDenseIfPresent(right) orelse return false;
    if (left_host.len() != right_host.len()) return false;
    const left_mode = hostDenseNumericMode(left_host);
    if (left_mode != hostDenseNumericMode(right_host)) return false;
    return switch (left_mode) {
        .int => blk: {
            const left_view = hostIntArrayView(left_host) orelse return false;
            const right_view = hostIntArrayView(right_host) orelse return false;
            if (hostIntArrayViewLen(left_view) != hostIntArrayViewLen(right_view)) break :blk false;
            for (0..hostIntArrayViewLen(left_view)) |idx| {
                if (hostIntViewItem(left_view, idx) != hostIntViewItem(right_view, idx)) break :blk false;
            }
            break :blk true;
        },
        .float => blk: {
            const left_items = switch (left_host.storage) {
                .float64 => |items| hostDenseLogicalItems(f64, left_host, items),
                else => return false,
            };
            const right_items = switch (right_host.storage) {
                .float64 => |items| hostDenseLogicalItems(f64, right_host, items),
                else => return false,
            };
            if (left_items.len != right_items.len) break :blk false;
            for (left_items, right_items) |left_item, right_item| {
                if (@as(u64, @bitCast(left_item)) != @as(u64, @bitCast(right_item))) break :blk false;
            }
            break :blk true;
        },
    };
}

fn hostBoxedConstantMatches(left: *const HostBoxedArray, right: *const HostBoxedArray) bool {
    if (left.items.len != right.items.len) return false;
    for (left.items, right.items) |left_item, right_item| {
        if (!constantMatches(left_item, right_item)) return false;
    }
    return true;
}

fn hostTextConstantMatches(left: Value, right: Value, kind: HeapKind) bool {
    return switch (kind) {
        .host_string => std.mem.eql(u8, hostTextBytes(left.asHostString()), hostTextBytes(right.asHostString())),
        .host_symbol => std.mem.eql(u8, hostTextBytes(left.asHostSymbol()), hostTextBytes(right.asHostSymbol())),
        else => false,
    };
}

fn hostStringListConstantMatches(left: *const HostStringList, right: *const HostStringList) bool {
    if (left.len != right.len) return false;
    for (0..left.len) |idx| {
        const left_bytes = hostStringListItemBytes(left, idx) catch return false;
        const right_bytes = hostStringListItemBytes(right, idx) catch return false;
        if (!std.mem.eql(u8, left_bytes, right_bytes)) return false;
    }
    return true;
}

fn arrayConstantMatches(stored: Value, query: Value) bool {
    if (stored.raw == query.raw) return true;
    const stored_numeric = valueNumericHandle(stored);
    const query_numeric = valueNumericHandle(query);
    if (stored_numeric != null or query_numeric != null) {
        if (stored_numeric == null or query_numeric == null) return false;
        if (stored_numeric.?.activeAttachment() != .host or query_numeric.?.activeAttachment() != .host) return false;
        return hostDenseConstantMatches(stored, query);
    }
    const stored_kind = stored.arrayKind();
    const query_kind = query.arrayKind();
    if (stored_kind != query_kind) return false;
    return switch (stored_kind) {
        .host_boxed_array => hostBoxedConstantMatches(stored.asHostBoxedArray(), query.asHostBoxedArray()),
        .host_string, .host_symbol => hostTextConstantMatches(stored, query, stored_kind),
        .host_string_list, .host_symbol_list => hostStringListConstantMatches(stored.asHostStringList(), query.asHostStringList()),
        else => false,
    };
}

fn constantMatches(stored: Value, query: Value) bool {
    if (stored.tag() != query.tag()) return false;
    return switch (stored.tag()) {
        .int => stored.asInt() == query.asInt(),
        .float32 => @as(u32, @bitCast(stored.asFloat32())) == @as(u32, @bitCast(query.asFloat32())),
        .float => @as(u64, @bitCast(stored.asFloat())) == @as(u64, @bitCast(query.asFloat())),
        .bool => stored.asBool() == query.asBool(),
        .builtin => stored.asBuiltin() == query.asBuiltin(),
        .closure => stored.asClosure() == query.asClosure(),
        .array => arrayConstantMatches(stored, query),
    };
}

const Scope = struct {
    explicit_names: [max_explicit_params]IdentRef = undefined,
    explicit_count: u8 = 0,
    local_names: [max_lambda_locals]IdentRef = undefined,
    local_slots: [max_lambda_locals]u16 = undefined,
    local_count: u8 = 0,
    allow_implicit_params: bool = false,
    arity: u8 = 0,
    required_arity: u8 = 0,
    frame_slot_count: u8 = 0,

    fn deinit(self: *Scope, allocator: std.mem.Allocator) void {
        _ = self;
        _ = allocator;
    }

    fn declareParam(self: *Scope, ident: IdentRef) !void {
        if (self.lookupExplicit(ident) != null) return error.Parse;
        if (self.explicit_count >= max_explicit_params) return error.Unsupported;
        const slot: u16 = self.arity;
        self.arity += 1;
        self.frame_slot_count = self.arity;
        self.explicit_names[self.explicit_count] = ident;
        self.explicit_count += 1;
        if (slot != self.explicit_count - 1) return error.Internal;
    }

    fn declareLocal(self: *Scope, ident: IdentRef) !u16 {
        if (self.lookupExplicit(ident)) |slot| return slot;
        var idx: u8 = 0;
        while (idx < self.local_count) : (idx += 1) {
            if (identMatches(self.local_names[idx], ident)) return self.local_slots[idx];
        }
        if (self.local_count >= max_lambda_locals) return error.Unsupported;
        self.ensureLocalSlotFloor();
        if (self.frame_slot_count >= max_code_frame_slots) return error.Unsupported;
        const slot: u16 = self.frame_slot_count;
        self.local_names[self.local_count] = ident;
        self.local_slots[self.local_count] = slot;
        self.local_count += 1;
        self.frame_slot_count += 1;
        return slot;
    }

    fn ensureLocalSlotFloor(self: *Scope) void {
        if (self.allow_implicit_params and self.explicit_count == 0 and self.frame_slot_count < 3) {
            self.frame_slot_count = 3;
        }
    }

    fn markParamRequired(self: *Scope, slot: u16) void {
        if (slot >= self.arity) return;
        const required = std.math.cast(u8, slot + 1) orelse return;
        if (self.required_arity < required) self.required_arity = required;
    }

    fn resolveLoad(self: *Scope, ident: IdentRef) !ResolveResult {
        if (self.lookupResolvedHere(ident)) |resolved| return resolved;
        return .global;
    }

    fn lookupLocal(self: *Scope, ident: IdentRef) ?u16 {
        if (identIsDottedPath(ident)) return null;
        var local_idx = self.local_count;
        while (local_idx > 0) {
            local_idx -= 1;
            if (identMatches(self.local_names[local_idx], ident)) return self.local_slots[local_idx];
        }
        if (self.lookupExplicit(ident)) |slot| return slot;
        if (!self.allow_implicit_params) return null;
        if (ident.text.len == 1) {
            switch (ident.text[0]) {
                'x' => {
                    if (self.arity < 1) self.arity = 1;
                    if (self.frame_slot_count < 1) self.frame_slot_count = 1;
                    return 0;
                },
                'y' => {
                    if (self.arity < 2) self.arity = 2;
                    if (self.frame_slot_count < 2) self.frame_slot_count = 2;
                    return 1;
                },
                'z' => {
                    if (self.arity < 3) self.arity = 3;
                    if (self.frame_slot_count < 3) self.frame_slot_count = 3;
                    return 2;
                },
                else => {},
            }
        }

        return null;
    }

    fn resolveLocal(self: *const Scope, slot: u16) ResolveResult {
        _ = self;
        return .{ .local = slot };
    }

    fn lookupResolvedHere(self: *Scope, ident: IdentRef) ?ResolveResult {
        if (self.lookupLocal(ident)) |slot| return self.resolveLocal(slot);
        return null;
    }

    fn lookupExplicit(self: *const Scope, ident: IdentRef) ?u16 {
        var idx: u8 = 0;
        while (idx < self.explicit_count) : (idx += 1) {
            if (identMatches(self.explicit_names[idx], ident)) return idx;
        }
        return null;
    }

    fn isPureGlobalScope(self: *const Scope) bool {
        return self.explicit_count == 0 and
            !self.allow_implicit_params;
    }
};

const Compiler = struct {
    session: *Session,
    source: []const u8,
    code_allocator: std.mem.Allocator,
    compile_mode: CompileMode,
    index: usize = 0,
    consume_candidates: ConsumeCandidates = .{},

    fn init(session: *Session, source: []const u8, code_allocator: std.mem.Allocator, compile_mode: CompileMode) KError!Compiler {
        return .{
            .session = session,
            .source = source,
            .code_allocator = code_allocator,
            .compile_mode = compile_mode,
            .index = skipSpacesInSource(source, 0),
        };
    }

    fn compileTopLevel(self: *Compiler) KError!*const Code {
        var scope = Scope{};
        defer scope.deinit(self.session.allocator);

        var instructions = CodeEmitter.init(self.code_allocator);
        try self.compileTopLevelInto(&instructions, &scope);
        return try self.finalizeCode(scope.arity, scope.required_arity, scope.frame_slot_count, &instructions, .top_level, self.source);
    }

    fn compileTopLevelScratch(self: *Compiler, scratch: *ScratchCode) KError!*const Code {
        var scope = Scope{};
        defer scope.deinit(self.session.allocator);

        try self.compileTopLevelInto(&scratch.instructions, &scope);
        const code = try scratch.finalize(scope.arity, scope.required_arity, scope.frame_slot_count);
        self.assignCodeProfile(code, .top_level, self.source);
        return code;
    }

    fn compileTopLevelInto(self: *Compiler, instructions: *CodeEmitter, scope: *Scope) KError!void {
        var statement_start: usize = 0;
        var compiled_any = false;

        while (nextTopLevelStatement(self.source, &statement_start)) |statement| {
            if (compiled_any) try instructions.appendDiscard();

            var statement_compiler = try Compiler.init(
                self.session,
                statement,
                self.code_allocator,
                self.compile_mode,
            );
            try statement_compiler.compileSingleTopLevelStatementInto(instructions, scope);
            compiled_any = true;
        }

        if (!compiled_any) return error.Parse;
        self.index = self.source.len;
        try finishCodeEmitter(instructions, .top_level);
    }

    fn compileSingleTopLevelStatementInto(self: *Compiler, instructions: *CodeEmitter, scope: *Scope) KError!void {
        try self.compileExprSliceInto(instructions, scope, self.source);
        self.index = self.source.len;
    }

    fn compileExprSliceInto(self: *Compiler, out: *CodeEmitter, scope: *Scope, source_slice: []const u8) KError!void {
        const updated_candidates = try self.compileExprSliceIntoWithConsumeCandidates(out, scope, source_slice, self.consume_candidates);
        self.consume_candidates = updated_candidates;
    }

    fn compileExprSliceIntoWithConsumeCandidates(
        self: *Compiler,
        out: *CodeEmitter,
        scope: *Scope,
        source_slice: []const u8,
        candidates: ConsumeCandidates,
    ) KError!ConsumeCandidates {
        if (try self.tryCompileLiteralExprSlice(out, source_slice)) return candidates;
        if (try self.tryCompileWholeCondExprSlice(out, scope, source_slice, candidates)) |updated| return updated;

        var expr_compiler = try Compiler.init(
            self.session,
            source_slice,
            self.code_allocator,
            self.compile_mode,
        );
        expr_compiler.consume_candidates = candidates;
        if (try expr_compiler.tryCompileTinyExprSlice(out, scope, source_slice)) {
            expr_compiler.index = expr_compiler.source.len;
            return expr_compiler.consume_candidates;
        }
        _ = try expr_compiler.parseExpr(out, scope);
        if (!expr_compiler.atEnd()) return error.Parse;
        return expr_compiler.consume_candidates;
    }

    fn tryCompileWholeCondExprSlice(
        self: *Compiler,
        out: *CodeEmitter,
        scope: *Scope,
        source_slice: []const u8,
        candidates: ConsumeCandidates,
    ) KError!?ConsumeCandidates {
        const split = splitWholeCondSpecialForm(source_slice) orelse return null;

        _ = try self.compileExprSliceIntoWithConsumeCandidates(out, scope, split.condition, .{});
        const false_jump_patch = try out.emitJumpIfFalsePlaceholder();

        const branch_candidates = candidates.withoutRecordedUses();
        const then_candidates = try self.compileExprSliceIntoWithConsumeCandidates(out, scope, split.then_branch, branch_candidates);
        patchConsumeCandidates(out, then_candidates);

        const end_jump_patch = try out.emitJumpPlaceholder();

        try out.patchBranchTarget(false_jump_patch, out.position());
        const else_candidates = try self.compileExprSliceIntoWithConsumeCandidates(out, scope, split.else_branch, branch_candidates);
        patchConsumeCandidates(out, else_candidates);
        try out.patchBranchTarget(end_jump_patch, out.position());
        return .{};
    }

    fn compileTopLevelBlockInto(self: *Compiler, out: *CodeEmitter, scope: *Scope, body_source: []const u8) KError!void {
        var statement_start: usize = 0;
        var compiled_any = false;

        while (nextTopLevelStatement(body_source, &statement_start)) |statement| {
            if (compiled_any) try out.appendDiscard();

            var statement_compiler = try Compiler.init(
                self.session,
                statement,
                self.code_allocator,
                self.compile_mode,
            );
            try statement_compiler.compileSingleTopLevelStatementInto(out, scope);
            compiled_any = true;
        }

        if (!compiled_any) try self.emitLiteralValue(out, Value.builtin(.identity));
    }

    fn compileStatementBlockInto(self: *Compiler, out: *CodeEmitter, scope: *Scope, body_source: []const u8) KError!void {
        const trimmed = std.mem.trim(u8, body_source, " \t\r\n");
        if (trimmed.len == 0) {
            try self.emitLiteralValue(out, Value.builtin(.identity));
            return;
        }
        if (scope.isPureGlobalScope()) {
            try self.compileTopLevelBlockInto(out, scope, trimmed);
        } else {
            try self.compileLambdaBodyInto(out, scope, trimmed);
        }
    }

    fn emitResolvedLoad(self: *Compiler, out: *CodeEmitter, resolved: ResolveResult) KError!void {
        switch (resolved) {
            .local => |slot| try out.emitLoadLocal(slot),
            .global => return error.Internal,
        }
        const last = out.lastInstruction() orelse return error.Internal;
        self.consume_candidates.noteLoad(resolved, last.compact_start);
    }

    fn patchConsumeCandidates(out: *CodeEmitter, candidates: ConsumeCandidates) void {
        candidates.patchInto(out);
    }

    fn addStatementConsumeCandidates(
        candidates: *ConsumeCandidates,
        scope: *Scope,
        rhs_source: []const u8,
        body_source: []const u8,
    ) KError!void {
        var explicit_idx: u8 = 0;
        while (explicit_idx < scope.explicit_count) : (explicit_idx += 1) {
            const ident = scope.explicit_names[explicit_idx];
            if (sourceReferencesIdentCurrentLambda(rhs_source, ident) and
                !sourceReferencesIdentCurrentLambda(body_source, ident))
            {
                try candidates.addResolved(scope.resolveLocal(explicit_idx));
            }
        }

        var local_idx: u8 = 0;
        while (local_idx < scope.local_count) : (local_idx += 1) {
            const ident = scope.local_names[local_idx];
            if (sourceReferencesIdentCurrentLambda(rhs_source, ident) and
                !sourceReferencesIdentCurrentLambda(body_source, ident))
            {
                try candidates.addResolved(scope.resolveLocal(scope.local_slots[local_idx]));
            }
        }

        if (scope.allow_implicit_params and scope.explicit_count == 0) {
            const implicit_names = [_][]const u8{ "x", "y", "z" };
            for (implicit_names, 0..) |name, slot| {
                const ident = identRefFromText(name);
                if (sourceReferencesIdentCurrentLambda(rhs_source, ident) and
                    !sourceReferencesIdentCurrentLambda(body_source, ident))
                {
                    if (scope.arity < slot + 1) scope.arity = @intCast(slot + 1);
                    if (scope.frame_slot_count < slot + 1) scope.frame_slot_count = @intCast(slot + 1);
                    try candidates.addResolved(scope.resolveLocal(@intCast(slot)));
                }
            }
        }
    }

    fn compileLambdaBodyInto(self: *Compiler, out: *CodeEmitter, scope: *Scope, body_source: []const u8) KError!void {
        const split = splitLambdaBodyHead(body_source) orelse return error.Parse;
        var candidates = self.consume_candidates.withoutRecordedUses();
        try addStatementConsumeCandidates(&candidates, scope, split.head, split.tail orelse "");
        var expr_compiler = try Compiler.init(self.session, split.head, self.code_allocator, self.compile_mode);
        expr_compiler.consume_candidates = candidates;
        var arena = AstArena.init(self.code_allocator);
        const root = try expr_compiler.parseAstExpr(&arena);
        if (!expr_compiler.atEnd()) return error.Parse;
        const control_before = out.control_flow_op_count;
        try expr_compiler.lowerAstResult(&arena, root.node, out, scope, split.tail == null);
        if (out.control_flow_op_count == control_before) patchConsumeCandidates(out, expr_compiler.consume_candidates);
        self.consume_candidates = .{};
        if (split.tail) |tail| try self.compileLambdaBodyInto(out, scope, tail);
    }

    fn lowerAstAssignment(self: *Compiler, arena: *const AstArena, assignment: AstAssignment, out: *CodeEmitter, scope: *Scope, want_result: bool) KError!void {
        var rhs = assignment.rhs;
        var mode: AmendMode = if (assignment.mode == .modified) .binary else .assign;
        var builtin = assignment.builtin;
        if (assignment.selector) |selector| {
            if (mode == .assign) {
                if (self.indexedReadModifyRewrite(arena, rhs, arena, selector, assignment.ident)) |rewrite| {
                    rhs = rewrite.rhs_node;
                    mode = .binary;
                    builtin = rewrite.builtin;
                }
            }
        }
        // An overwritten local's old value dies at the end of its RHS, even
        // when the new binding is used by following statements.
        const overwritten = if (!want_result and assignment.selector == null and assignment.mode == .bind and !scope.isPureGlobalScope())
            scope.lookupLocal(assignment.ident)
        else
            null;
        if (overwritten) |slot| try self.consume_candidates.addLocal(slot);
        const rhs_control_before = out.control_flow_op_count;
        const rhs_start = out.position();
        _ = try self.lowerAstExpr(arena, rhs, out, scope);
        if (overwritten) |slot| {
            if (out.control_flow_op_count == rhs_control_before) self.consume_candidates.patchOverwrittenLocal(out, slot);
        }
        const rhs_simple = if (out.last_simple) |simple|
            if (out.simpleStartsAtOrAfterPosition(simple, rhs_start) and out.simpleEndsAtCurrent(simple)) simple else null
        else
            null;
        if (assignment.selector) |selector| {
            const selector_start = out.position();
            _ = try self.lowerAstExpr(arena, selector, out, scope);
            const selector_simple = if (out.last_simple) |simple|
                if (out.simpleStartsAtOrAfterPosition(simple, selector_start) and out.simpleEndsAtCurrent(simple)) simple else null
            else
                null;
            const resolved = if (assignment.mode == .explicit_global) ResolveResult.global else try scope.resolveLoad(assignment.ident);
            switch (resolved) {
                .local => |slot| {
                    scope.markParamRequired(slot);
                    self.consume_candidates.noteBorrow(slot);
                    if (selector_simple) |sel| {
                        if (rhs_simple) |value| {
                            if (try out.tryShapeIndexedAssignLocalSources(slot, mode, builtin, want_result, sel, value)) return;
                        }
                    }
                    try out.emitIndexedAssignLocal(slot, mode, builtin, want_result);
                },
                .global => {
                    const slot = try self.globalSlot(assignment.ident.text);
                    if (selector_simple) |sel| {
                        if (rhs_simple) |value| {
                            if (try out.tryShapeIndexedAssignGlobalSources(slot, mode, builtin, want_result, sel, value)) return;
                        }
                    }
                    try out.emitIndexedAssignGlobal(slot, mode, builtin, want_result);
                },
            }
            return;
        }
        if (assignment.mode == .modified) {
            switch (try scope.resolveLoad(assignment.ident)) {
                .local => |slot| {
                    scope.markParamRequired(slot);
                    self.consume_candidates.noteBorrow(slot);
                    try out.emitModifiedAssignLocal(slot, builtin, want_result, rhs_simple);
                },
                .global => try out.emitModifiedAssignGlobal(try self.globalSlot(assignment.ident.text), builtin, want_result, rhs_simple),
            }
        } else if (assignment.mode == .explicit_global or scope.isPureGlobalScope() or identIsDottedPath(assignment.ident)) {
            try out.emitStoreGlobal(try self.globalSlot(assignment.ident.text), want_result);
        } else {
            const slot = try scope.declareLocal(assignment.ident);
            try out.emitStoreLocal(slot);
            if (want_result) try self.emitResolvedLoad(out, .{ .local = slot });
        }
    }

    const IndexedReadModifyRewrite = struct {
        builtin: BuiltinId,
        rhs_node: AstNodeId,
    };

    fn astReadOnly(arena: *const AstArena, node_id: AstNodeId) bool {
        return switch (arena.node(node_id).data) {
            .value, .ident, .global, .builtin => true,
            .monad => |m| switch (m.builtin) {
                .sub, .div, .count, .floor, .not, .type_of, .stringify, .grade_up, .grade_down, .reverse => astReadOnly(arena, m.arg),
                else => false,
            },
            .dyad => |d| d.derived == null and switch (d.op) {
                '+', '-', '*', '%', '&', '|', '=', '<', '>', '#', '_', ',' => astReadOnly(arena, d.left) and astReadOnly(arena, d.right),
                else => false,
            },
            else => false,
        };
    }

    fn indexedReadModifyRewrite(
        self: *Compiler,
        rhs_arena: *const AstArena,
        rhs_node: AstNodeId,
        selector_arena: *const AstArena,
        selector_node: AstNodeId,
        assignment_ident: IdentRef,
    ) ?IndexedReadModifyRewrite {
        if (!astReadOnly(selector_arena, selector_node)) return null;
        const node = rhs_arena.node(rhs_node);
        const dyad = switch (node.data) {
            .dyad => |value| value,
            else => return null,
        };
        if (dyad.derived != null) return null;
        const builtin = builtinFromDyadChar(dyad.op) orelse return null;
        switch (builtin) {
            .add, .sub, .mul, .minimum, .maximum => {},
            else => return null,
        }

        if (astReadOnly(rhs_arena, dyad.right) and self.astIsSameIndexedSelector(rhs_arena, dyad.left, selector_arena, selector_node, assignment_ident)) {
            return .{
                .builtin = builtin,
                .rhs_node = dyad.right,
            };
        }
        switch (builtin) {
            .add, .mul, .minimum, .maximum => {
                if (astReadOnly(rhs_arena, dyad.left) and self.astIsSameIndexedSelector(rhs_arena, dyad.right, selector_arena, selector_node, assignment_ident)) {
                    return .{
                        .builtin = builtin,
                        .rhs_node = dyad.left,
                    };
                }
            },
            else => {},
        }
        return null;
    }

    fn astIsSameIndexedSelector(
        self: *Compiler,
        rhs_arena: *const AstArena,
        candidate: AstNodeId,
        selector_arena: *const AstArena,
        selector_node: AstNodeId,
        assignment_ident: IdentRef,
    ) bool {
        _ = self;
        const node = rhs_arena.node(candidate);
        const call = switch (node.data) {
            .call => |value| value,
            else => return false,
        };
        if (call.argc != 1) return false;
        const callee = rhs_arena.node(call.callee);
        switch (callee.data) {
            .ident => |ident| if (!identMatches(ident, assignment_ident)) return false,
            else => return false,
        }
        const arg = rhs_arena.extraSlice(call.first_arg, 1)[0];
        return astNodesEquivalent(rhs_arena, arg, selector_arena, selector_node);
    }

    fn astNodesEquivalent(left_arena: *const AstArena, left_id: AstNodeId, right_arena: *const AstArena, right_id: AstNodeId) bool {
        const left = left_arena.node(left_id);
        const right = right_arena.node(right_id);
        if (left.form != right.form) return false;
        return switch (left.data) {
            .value => |left_value| switch (right.data) {
                .value => |right_value| constantMatches(left_value, right_value),
                else => false,
            },
            .ident => |left_ident| switch (right.data) {
                .ident => |right_ident| identMatches(left_ident, right_ident),
                else => false,
            },
            .builtin => |left_builtin| switch (right.data) {
                .builtin => |right_builtin| left_builtin == right_builtin,
                else => false,
            },
            .dyad => |left_dyad| switch (right.data) {
                .dyad => |right_dyad| left_dyad.op == right_dyad.op and
                    left_dyad.derived == right_dyad.derived and
                    astNodesEquivalent(left_arena, left_dyad.left, right_arena, right_dyad.left) and
                    astNodesEquivalent(left_arena, left_dyad.right, right_arena, right_dyad.right),
                else => false,
            },
            .monad => |left_monad| switch (right.data) {
                .monad => |right_monad| left_monad.builtin == right_monad.builtin and
                    astNodesEquivalent(left_arena, left_monad.arg, right_arena, right_monad.arg),
                else => false,
            },
            .call => |left_call| switch (right.data) {
                .call => |right_call| blk: {
                    if (left_call.argc != right_call.argc) break :blk false;
                    if (!astNodesEquivalent(left_arena, left_call.callee, right_arena, right_call.callee)) break :blk false;
                    const left_args = left_arena.extraSlice(left_call.first_arg, left_call.argc);
                    const right_args = right_arena.extraSlice(right_call.first_arg, right_call.argc);
                    for (left_args, right_args) |left_arg, right_arg| {
                        if (!astNodesEquivalent(left_arena, left_arg, right_arena, right_arg)) break :blk false;
                    }
                    break :blk true;
                },
                else => false,
            },
            else => false,
        };
    }

    fn parseSelectorPathVectorAst(self: *Compiler, arena: *AstArena, selector_source: []const u8) KError!AstNodeId {
        var items: [max_body_instructions]AstNodeId = undefined;
        var count: u8 = 1;
        items[0] = try self.selectorPathMarkerAstNode(arena);
        var item_start = skipSpacesInSource(selector_source, 0);
        var index = item_start;
        var paren_depth: usize = 0;
        var bracket_depth: usize = 0;
        var brace_depth: usize = 0;

        while (index <= selector_source.len) {
            if (index == selector_source.len or (selector_source[index] == ';' and paren_depth == 0 and bracket_depth == 0 and brace_depth == 0)) {
                if (count >= items.len) return error.Unsupported;
                const item = std.mem.trim(u8, selector_source[item_start..index], " \t\r\n");
                items[count] = if (item.len == 0)
                    try self.allAxisSelectorAstNode(arena)
                else
                    try self.parseAstListItem(arena, item);
                count = std.math.add(u8, count, 1) catch return error.Unsupported;
                if (index == selector_source.len) break;
                item_start = skipSpacesInSource(selector_source, index + 1);
                index = item_start;
                continue;
            }

            switch (selector_source[index]) {
                '"' => {
                    index = scanStringLiteralEnd(selector_source, index) orelse return error.Parse;
                },
                '(' => paren_depth += 1,
                ')' => {
                    if (paren_depth == 0) return error.Parse;
                    paren_depth -= 1;
                },
                '[' => bracket_depth += 1,
                ']' => {
                    if (bracket_depth == 0) return error.Parse;
                    bracket_depth -= 1;
                },
                '{' => brace_depth += 1,
                '}' => {
                    if (brace_depth == 0) return error.Parse;
                    brace_depth -= 1;
                },
                else => {},
            }
            index += 1;
        }

        const first_item = try arena.appendExtra(items[0..count]);
        return try arena.add(.nounish, .{ .start = 0, .end = selector_source.len }, .{
            .vector = .{
                .first_item = first_item,
                .count = count,
            },
        });
    }

    fn findIndexedAssignmentClose(source_slice: []const u8, open_index: usize) ?usize {
        if (open_index >= source_slice.len or source_slice[open_index] != '[') return null;
        var index = open_index + 1;
        var bracket_depth: usize = 1;
        var paren_depth: usize = 0;
        var brace_depth: usize = 0;
        while (index < source_slice.len) : (index += 1) {
            switch (source_slice[index]) {
                '"' => {
                    index = scanStringLiteralEnd(source_slice, index) orelse return null;
                },
                '[' => bracket_depth += 1,
                ']' => {
                    if (bracket_depth == 0) return null;
                    bracket_depth -= 1;
                    if (bracket_depth == 0 and paren_depth == 0 and brace_depth == 0) return index;
                },
                '(' => paren_depth += 1,
                ')' => {
                    if (paren_depth == 0) return null;
                    paren_depth -= 1;
                },
                '{' => brace_depth += 1,
                '}' => {
                    if (brace_depth == 0) return null;
                    brace_depth -= 1;
                },
                else => {},
            }
        }
        return null;
    }

    fn selectorSourceHasTopLevelSeparator(selector_source: []const u8) bool {
        var index: usize = 0;
        var paren_depth: usize = 0;
        var bracket_depth: usize = 0;
        var brace_depth: usize = 0;
        while (index < selector_source.len) : (index += 1) {
            switch (selector_source[index]) {
                '"' => {
                    index = scanStringLiteralEnd(selector_source, index) orelse return false;
                },
                '(' => paren_depth += 1,
                ')' => {
                    if (paren_depth != 0) paren_depth -= 1;
                },
                '[' => bracket_depth += 1,
                ']' => {
                    if (bracket_depth != 0) bracket_depth -= 1;
                },
                '{' => brace_depth += 1,
                '}' => {
                    if (brace_depth != 0) brace_depth -= 1;
                },
                ';' => {
                    if (paren_depth == 0 and bracket_depth == 0 and brace_depth == 0) return true;
                },
                else => {},
            }
        }
        return false;
    }

    fn indexedAssignmentBuiltin(ch: u8) ?BuiltinId {
        return switch (ch) {
            '+', '-', '*', '%', '&', '|' => builtinFromChar(ch),
            else => null,
        };
    }

    fn tryParseAstAssignment(self: *Compiler, arena: *AstArena) KError!?AstParseResult {
        const start = self.index;
        const scanned = self.scanIdentifierPathAt(start) orelse return null;
        var after = skipSpacesInSource(self.source, scanned.next_index);
        var selector_source: ?[]const u8 = null;
        if (after < self.source.len and self.source[after] == '[') {
            const close = findIndexedAssignmentClose(self.source, after) orelse return error.Parse;
            selector_source = self.source[after + 1 .. close];
            after = skipSpacesInSource(self.source, close + 1);
        }
        if (after >= self.source.len) return null;
        var mode: NameAssignmentMode = .bind;
        var builtin: BuiltinId = .add;
        if (self.source[after] == ':') {
            after += 1;
            if (after < self.source.len and self.source[after] == ':') {
                mode = .explicit_global;
                after += 1;
            }
        } else if (indexedAssignmentBuiltin(self.source[after])) |id| {
            builtin = id;
            mode = .modified;
            after = skipSpacesInSource(self.source, after + 1);
            if (after >= self.source.len or self.source[after] != ':') return null;
            after += 1;
            // A monadic verb with an adverb is not modified assignment.
            if (self.startsDerivedVerbAt(skipSpacesInSource(self.source, after))) return null;
        } else return null;
        self.index = skipSpacesInSource(self.source, after);
        const selector = if (selector_source) |source| blk: {
            break :blk if (selectorSourceHasTopLevelSeparator(source) or std.mem.trim(u8, source, " \t\r\n").len == 0)
                try self.parseSelectorPathVectorAst(arena, source)
            else
                try self.parseAstListItem(arena, source);
        } else null;
        const rhs = try self.parseAstDyadExpr(arena);
        const node = try arena.add(.nounish, .{ .start = start, .end = self.index }, .{
            .assignment = .{ .ident = scanned.ident, .selector = selector, .rhs = rhs.node, .mode = mode, .builtin = builtin },
        });
        return .{ .node = node, .form = .nounish };
    }

    fn emitSimpleAtom(self: *Compiler, out: *CodeEmitter, scope: *Scope, atom: SimpleAtom) KError!void {
        switch (atom) {
            .int => |value| try out.emitConstInt(value),
            .float => |value| try self.emitConstFloat(out, value),
            .float32 => |value| try self.emitConstFloat32(out, value),
            .bool => |value| try self.emitConstBool(out, value),
            .ident => |ident| try self.lowerAstIdent(out, scope, ident),
        }
    }

    fn isHexLiteralChar(ch: u8) bool {
        return std.ascii.isAlphanumeric(ch);
    }

    fn hexNibble(ch: u8) ?u8 {
        if (ch >= '0' and ch <= '9') return ch - '0';
        const lower = std.ascii.toLower(ch);
        if (lower >= 'a' and lower <= 'f') return 10 + lower - 'a';
        return null;
    }

    fn sourceStartsHexLiteral(text: []const u8, index: usize) bool {
        return index + 1 < text.len and text[index] == '0' and text[index + 1] == 'x';
    }

    fn scanNumericLiteral(text: []const u8, start: usize) ?struct { literal: NumericLiteral, next: usize } {
        var index = skipSpacesInSource(text, start);
        if (index >= text.len or !std.ascii.isDigit(text[index])) return null;
        if (sourceStartsHexLiteral(text, index)) return null;

        const begin = index;
        while (index < text.len and std.ascii.isDigit(text[index])) : (index += 1) {}
        const int_end = index;

        if (int_end == begin + 1 and text[begin] == '0' and index < text.len) {
            if (text[index] == 'N') {
                return .{
                    .literal = .{ .int = kiwi_int_null },
                    .next = skipSpacesInSource(text, index + 1),
                };
            }
            if (text[index] == 'n') {
                if (index + 1 < text.len and text[index + 1] == 'e') {
                    return .{
                        .literal = .{ .float32 = kiwiFloat32Null() },
                        .next = skipSpacesInSource(text, index + 2),
                    };
                }
                return .{
                    .literal = .{ .float = kiwiFloatNull() },
                    .next = skipSpacesInSource(text, index + 1),
                };
            }
            if (text[index] == 'w') {
                if (index + 1 < text.len and text[index + 1] == 'e') {
                    return .{
                        .literal = .{ .float32 = std.math.inf(f32) },
                        .next = skipSpacesInSource(text, index + 2),
                    };
                }
                return .{
                    .literal = .{ .float = std.math.inf(f64) },
                    .next = skipSpacesInSource(text, index + 1),
                };
            }
        }

        if (index < text.len and (text[index] == 'b' or text[index] == 'B')) {
            if (int_end != begin + 1) return null;
            const ch = text[begin];
            if (ch != '0' and ch != '1') return null;
            return .{
                .literal = .{ .bool = ch == '1' },
                .next = skipSpacesInSource(text, index + 1),
            };
        }

        var is_float = false;
        if (index < text.len and text[index] == '.') {
            is_float = true;
            index += 1;
            while (index < text.len and std.ascii.isDigit(text[index])) : (index += 1) {}
        }

        var parse_end = index;
        if (index < text.len and (text[index] == 'e' or text[index] == 'E')) {
            var exponent_index = index + 1;
            if (exponent_index < text.len and (text[exponent_index] == '-' or text[exponent_index] == '+')) exponent_index += 1;
            const exponent_begin = exponent_index;
            while (exponent_index < text.len and std.ascii.isDigit(text[exponent_index])) : (exponent_index += 1) {}
            if (exponent_index != exponent_begin) {
                is_float = true;
                index = exponent_index;
                parse_end = index;
            }
        }

        var is_float32 = false;
        if (index < text.len and text[index] == 'f') {
            is_float = true;
            index += 1;
        } else if (index < text.len and text[index] == 'e') {
            is_float = true;
            is_float32 = true;
            index += 1;
        }

        if (is_float) {
            if (is_float32) {
                return .{
                    .literal = .{
                        .float32 = std.fmt.parseFloat(f32, text[begin..parse_end]) catch return null,
                    },
                    .next = skipSpacesInSource(text, index),
                };
            }
            return .{
                .literal = .{
                    .float = std.fmt.parseFloat(f64, text[begin..parse_end]) catch return null,
                },
                .next = skipSpacesInSource(text, index),
            };
        }

        return .{
            .literal = .{
                .int = std.fmt.parseInt(i64, text[begin..index], 10) catch return null,
            },
            .next = skipSpacesInSource(text, index),
        };
    }

    fn scanSimpleAtom(text: []const u8, start: usize) ?struct { atom: SimpleAtom, next: usize } {
        var index = skipSpacesInSource(text, start);
        if (index >= text.len) return null;

        if (std.ascii.isDigit(text[index])) {
            const scanned = scanNumericLiteral(text, index) orelse return null;
            return .{
                .atom = switch (scanned.literal) {
                    .int => |value| .{ .int = value },
                    .float => |value| .{ .float = value },
                    .float32 => |value| .{ .float32 = value },
                    .bool => |value| .{ .bool = value },
                },
                .next = scanned.next,
            };
        }

        if (isIdentStart(text[index])) {
            const begin = index;
            index = scanIdentifierPathTextEnd(text, begin) orelse return null;
            const ident_text = text[begin..index];
            return .{
                .atom = .{
                    .ident = .{
                        .text = ident_text,
                        .key = IdentKey.fromText(ident_text),
                    },
                },
                .next = skipSpacesInSource(text, index),
            };
        }

        return null;
    }

    fn tryCompileTinyExprSlice(self: *Compiler, out: *CodeEmitter, scope: *Scope, source_slice: []const u8) KError!bool {
        const text = std.mem.trim(u8, source_slice, " \t\r\n");
        if (text.len == 0) return false;

        if (text[0] == '-' or text[0] == '%') {
            const atom = scanSimpleAtom(text, 1) orelse return false;
            if (atom.next != text.len) return false;
            try self.emitSimpleAtom(out, scope, atom.atom);
            try out.appendShapedMonad(if (text[0] == '-') .sub else .div);
            return true;
        }

        const first = scanSimpleAtom(text, 0) orelse return false;
        if (first.next >= text.len) {
            try self.emitSimpleAtom(out, scope, first.atom);
            return true;
        }

        if (text[first.next] == '[') {
            const callee_ident = switch (first.atom) {
                .ident => |ident| ident,
                else => return false,
            };
            const arg0 = scanSimpleAtom(text, first.next + 1) orelse return false;
            if (arg0.next >= text.len or text[arg0.next] != ';') return false;
            const arg1 = scanSimpleAtom(text, arg0.next + 1) orelse return false;
            if (arg1.next >= text.len or text[arg1.next] != ']') return false;
            if (skipSpacesInSource(text, arg1.next + 1) != text.len) return false;

            if (builtinFromName(callee_ident.text)) |builtin| {
                if (builtinCanEmitDirectCall(builtin, 2)) {
                    try self.emitSimpleAtom(out, scope, arg1.atom);
                    try self.emitSimpleAtom(out, scope, arg0.atom);
                    if (!(try self.tryEmitBuiltinCall(out, builtin, 2))) return error.Unsupported;
                    return true;
                }
                try self.emitSimpleAtom(out, scope, arg1.atom);
                try self.emitSimpleAtom(out, scope, arg0.atom);
                try self.emitPendingPrimary(out, scope, .{ .builtin = builtin });
                try out.appendStackCall(2);
                return true;
            }

            return false;
        }

        const op = switch (text[first.next]) {
            '+' => BuiltinId.add,
            '-' => BuiltinId.sub,
            '*' => BuiltinId.mul,
            else => return false,
        };
        const second = scanSimpleAtom(text, first.next + 1) orelse return false;
        if (second.next != text.len) return false;
        try self.emitSimpleAtom(out, scope, second.atom);
        try self.emitSimpleAtom(out, scope, first.atom);
        try out.appendShapedDyad(op);
        return true;
    }

    fn astFromPendingPrimary(self: *Compiler, arena: *AstArena, pending: PendingPrimary, form: ExprForm, start: usize) KError!AstParseResult {
        const data: AstNodeData = switch (pending) {
            .none => return error.Internal,
            .global => |slot| .{ .global = slot },
            .builtin => |id| .{ .builtin = id },
            .const_value => |value| .{ .value = value },
            .lambda_source => |lambda| .{ .lambda_source = lambda },
        };
        const node = try arena.add(form, .{ .start = start, .end = self.index }, data);
        return .{ .node = node, .form = form };
    }

    fn parseAstExpr(self: *Compiler, arena: *AstArena) KError!AstParseResult {
        return try self.parseAstDyadExpr(arena);
    }

    fn astRightHoleProjection(self: *Compiler, arena: *AstArena, left: AstParseResult, callee: AstParseResult) KError!AstParseResult {
        _ = self;
        var bound = [_]AstNodeId{left.node};
        const first_bound = try arena.appendExtra(bound[0..]);
        const node = try arena.add(.verbial, .{ .start = arena.node(left.node).span.start, .end = arena.node(callee.node).span.end }, .{
            .projection = .{
                .callee = callee.node,
                .first_bound = first_bound,
                .bound_count = 1,
                .slot_count = 2,
                .hole_mask = @as(u64, 1) << 1,
            },
        });
        return .{ .node = node, .form = .verbial };
    }

    fn parseAstDyadExpr(self: *Compiler, arena: *AstArena) KError!AstParseResult {
        if (try self.tryParseAstAssignment(arena)) |assignment| return assignment;
        const left = try self.parseAstApply(arena);
        const op = self.peekDyadOp() orelse return left;
        const op_start = self.index;
        _ = self.consumeByte();
        if (self.atTrailingDyadProjectionHole()) {
            const builtin = builtinFromDyadChar(op) orelse return error.Parse;
            const callee = try arena.add(.verbial, .{ .start = op_start, .end = self.index }, .{ .builtin = builtin });
            return try self.astRightHoleProjection(arena, left, .{ .node = callee, .form = .verbial });
        }
        if (op != '.') {
            const colon = skipSpacesInSource(self.source, self.index);
            if (colon < self.source.len and self.source[colon] == ':') {
                const adverb = skipSpacesInSource(self.source, colon + 1);
                if (self.startsDerivedVerbAt(adverb)) {
                    const builtin = builtinFromDyadChar(op) orelse return error.Parse;
                    self.index = adverb;
                    const value = try self.session.allocFrozenMonadicBuiltinClosure(builtin);
                    const initial = try arena.add(.verbial, .{ .start = op_start, .end = self.index }, .{ .value = value });
                    const initial_result = AstParseResult{ .node = initial, .form = .verbial };
                    const callee = try self.parseAstPostfixTail(arena, initial_result);
                    if (self.atTrailingDyadProjectionHole()) {
                        return try self.astRightHoleProjection(arena, left, callee);
                    }
                    const right = try self.parseAstDyadExpr(arena);
                    var args = [_]AstNodeId{ left.node, right.node };
                    const first_arg = try arena.appendExtra(args[0..]);
                    const node = try arena.add(.nounish, .{ .start = arena.node(left.node).span.start, .end = arena.node(right.node).span.end }, .{
                        .call = .{
                            .callee = callee.node,
                            .first_arg = first_arg,
                            .argc = 2,
                        },
                    });
                    return .{ .node = node, .form = .nounish };
                }
            }
        }
        if (op != '.' and self.startsDerivedVerb()) {
            const builtin = builtinFromDyadChar(op) orelse return error.Parse;
            const initial = try arena.add(.verbial, .{ .start = arena.node(left.node).span.end, .end = self.index }, .{ .builtin = builtin });
            const initial_result = AstParseResult{ .node = initial, .form = .verbial };
            const callee = try self.parseAstPostfixTail(arena, initial_result);
            if (self.atTrailingDyadProjectionHole()) {
                return try self.astRightHoleProjection(arena, left, callee);
            }
            const right = try self.parseAstDyadExpr(arena);
            var args = [_]AstNodeId{ left.node, right.node };
            const first_arg = try arena.appendExtra(args[0..]);
            const node = try arena.add(.nounish, .{ .start = arena.node(left.node).span.start, .end = arena.node(right.node).span.end }, .{
                .call = .{
                    .callee = callee.node,
                    .first_arg = first_arg,
                    .argc = 2,
                },
            });
            return .{ .node = node, .form = .nounish };
        }
        const derived = if (op != '.') self.matchDerivedVerb() else null;
        const right = try self.parseAstDyadExpr(arena);
        const node = try arena.add(.nounish, .{ .start = arena.node(left.node).span.start, .end = arena.node(right.node).span.end }, .{
            .dyad = .{
                .op = op,
                .derived = derived,
                .left = left.node,
                .right = right.node,
            },
        });
        return .{ .node = node, .form = .nounish };
    }

    fn parseAstApply(self: *Compiler, arena: *AstArena) KError!AstParseResult {
        var left = try self.parseAstUnary(arena);
        while (try self.tryParseAstVerbialComposition(arena, left)) |composed| {
            left = composed;
        }
        if (left.parenthesized and left.form == .verbial and self.peekDyadOp() != null) return left;
        if (self.callableLeftShouldBindFilterDyad(arena, left)) return left;
        if (try self.tryParseAstParenthesizedVerbialDyad(arena, left)) |applied| return applied;
        if (try self.tryParseAstUnparenthesizedVerbialDyad(arena, left)) |applied| return applied;
        if (self.startsJuxtapositionOperand(left.form)) {
            const arg = try self.parseAstExpr(arena);
            var args = [_]AstNodeId{arg.node};
            const first_arg = try arena.appendExtra(args[0..]);
            const node = try arena.add(.nounish, .{ .start = arena.node(left.node).span.start, .end = arena.node(arg.node).span.end }, .{
                .call = .{
                    .callee = left.node,
                    .first_arg = first_arg,
                    .argc = 1,
                },
            });
            return .{ .node = node, .form = .nounish };
        }
        return left;
    }

    fn callableLeftShouldBindFilterDyad(self: *const Compiler, arena: *const AstArena, left: AstParseResult) bool {
        const ch = self.peekByte() orelse return false;
        if (left.form != .verbial or (ch != '#' and ch != '_')) return false;
        if (left.parenthesized) return true;
        return switch (arena.node(left.node).data) {
            .lambda_source, .projection => true,
            else => false,
        };
    }

    fn astStaticValue(self: *Compiler, arena: *const AstArena, node_id: AstNodeId) KError!?Value {
        const node = arena.node(node_id);
        return switch (node.data) {
            .value => |value| value,
            .builtin => |id| Value.builtin(id),
            .adverb, .projection => try self.astStaticVerbialValue(arena, node_id),
            .vector => |vector| blk: {
                var values: [max_body_instructions]Value = undefined;
                const items = arena.extraSlice(vector.first_item, vector.count);
                for (items, 0..) |item, idx| {
                    values[idx] = (try self.astStaticValue(arena, item)) orelse break :blk null;
                }
                break :blk (try self.session.makeConstantArrayFromValues(.frozen, values[0..items.len])) orelse
                    try self.session.createOwnedHostBoxedArray(.frozen, values[0..items.len]);
            },
            else => null,
        };
    }

    fn astStaticProjectionValue(self: *Compiler, arena: *const AstArena, projection: AstProjection) KError!?Value {
        if (projection.slot_count > 63) return error.Unsupported;
        const callee = (try self.astStaticVerbialValue(arena, projection.callee)) orelse return null;
        const total_slots: usize = projection.slot_count;
        if ((projection.hole_mask >> @intCast(total_slots)) != 0) return error.Internal;

        var slot_values: [64]Value = undefined;
        const bound_nodes = arena.extraSlice(projection.first_bound, projection.bound_count);
        var bound_idx: usize = 0;
        for (0..total_slots) |slot_idx| {
            if (((projection.hole_mask >> @intCast(slot_idx)) & 1) != 0) {
                slot_values[slot_idx] = Value.fromBool(false);
            } else {
                if (bound_idx >= bound_nodes.len) return error.Internal;
                slot_values[slot_idx] = (try self.astStaticValue(arena, bound_nodes[bound_idx])) orelse return null;
                bound_idx += 1;
            }
        }
        if (bound_idx != bound_nodes.len) return error.Internal;
        return try self.session.allocFrozenProjectionClosure(callee, projection.slot_count, projection.hole_mask, slot_values[0..total_slots]);
    }

    fn astStaticVerbialValue(self: *Compiler, arena: *const AstArena, node_id: AstNodeId) KError!?Value {
        const node = arena.node(node_id);
        return switch (node.data) {
            .value => |value| switch (value.tag()) {
                .builtin, .closure => value,
                else => null,
            },
            .builtin => |id| Value.builtin(id),
            .projection => |projection| try self.astStaticProjectionValue(arena, projection),
            .adverb => |adverb| blk: {
                const base = (try self.astStaticVerbialValue(arena, adverb.base)) orelse break :blk null;
                break :blk Value.closure(try self.session.allocFrozenDerivedClosure(adverb.kind, base));
            },
            else => null,
        };
    }

    fn startsComposableVerbialAt(self: *const Compiler, index: usize) bool {
        const start = skipSpacesInSource(self.source, index);
        if (start >= self.source.len) return false;
        const ch = self.source[start];
        if (builtinFromChar(ch) == null) return false;
        const next = skipSpacesInSource(self.source, start + 1);
        if (next >= self.source.len) return false;
        return switch (self.source[next]) {
            ':', '\'', '/', '\\' => true,
            else => false,
        };
    }

    fn startsDotAdverbPrimaryAt(self: *const Compiler, index: usize) bool {
        const start = skipSpacesInSource(self.source, index);
        if (start >= self.source.len or self.source[start] != '.') return false;
        const adverb_index = skipSpacesInSource(self.source, start + 1);
        if (adverb_index >= self.source.len) return false;
        return switch (self.source[adverb_index]) {
            '\'', '/', '\\' => true,
            else => false,
        };
    }

    fn tryParseAstVerbialComposition(self: *Compiler, arena: *AstArena, left: AstParseResult) KError!?AstParseResult {
        if (left.form != .verbial) return null;
        const start = skipSpacesInSource(self.source, self.index);
        const starts_parenthesized = start < self.source.len and self.source[start] == '(';
        if (!starts_parenthesized and !self.startsComposableVerbialAt(self.index)) return null;

        const saved_index = self.index;
        const saved_arena = arena.mark();
        const right = if (starts_parenthesized)
            try self.parseAstDyadExpr(arena)
        else
            try self.parseAstUnary(arena);
        if (right.form != .verbial) {
            self.index = saved_index;
            arena.restore(saved_arena);
            return null;
        }

        const outer = (try self.astStaticVerbialValue(arena, left.node)) orelse {
            self.index = saved_index;
            arena.restore(saved_arena);
            return null;
        };
        const inner = (try self.astStaticVerbialValue(arena, right.node)) orelse {
            self.index = saved_index;
            arena.restore(saved_arena);
            return null;
        };
        const composed = Value.closure(try self.session.allocFrozenCompositionClosure(outer, inner));
        const node = try arena.add(.verbial, .{ .start = arena.node(left.node).span.start, .end = arena.node(right.node).span.end }, .{ .value = composed });
        return .{ .node = node, .form = .verbial };
    }

    fn astNodeIsAdverb(arena: *const AstArena, node_id: AstNodeId) bool {
        return switch (arena.node(node_id).data) {
            .adverb => true,
            else => false,
        };
    }

    fn astNodeIsProjection(arena: *const AstArena, node_id: AstNodeId) bool {
        return switch (arena.node(node_id).data) {
            .projection => true,
            else => false,
        };
    }

    fn tryParseAstParenthesizedVerbialDyad(self: *Compiler, arena: *AstArena, left: AstParseResult) KError!?AstParseResult {
        if (left.form != .nounish and left.form != .verbial) return null;
        if (self.peekByte() != '(') return null;

        const saved_index = self.index;
        const saved_arena = arena.mark();
        const callee = try self.parseAstUnary(arena);
        const has_right_operand = self.startsJuxtapositionOperand(callee.form);

        if (callee.form != .verbial or
            (left.form == .verbial and (!astNodeIsProjection(arena, left.node) or !astNodeIsAdverb(arena, callee.node))))
        {
            self.index = saved_index;
            arena.restore(saved_arena);
            return null;
        }
        if (!has_right_operand) {
            if (self.atTrailingDyadProjectionHole()) return try self.astRightHoleProjection(arena, left, callee);
            self.index = saved_index;
            arena.restore(saved_arena);
            return null;
        }

        const right = try self.parseAstExpr(arena);
        var args = [_]AstNodeId{ left.node, right.node };
        const first_arg = try arena.appendExtra(args[0..]);
        const node = try arena.add(.nounish, .{ .start = arena.node(left.node).span.start, .end = arena.node(right.node).span.end }, .{
            .call = .{
                .callee = callee.node,
                .first_arg = first_arg,
                .argc = 2,
            },
        });
        return .{ .node = node, .form = .nounish };
    }

    fn tryParseAstUnparenthesizedVerbialDyad(self: *Compiler, arena: *AstArena, left: AstParseResult) KError!?AstParseResult {
        if (left.form != .nounish and left.form != .verbial) return null;
        const ch = self.peekByte() orelse return null;
        if (ch != '{' and !(isIdentStart(ch) and builtinFromChar(ch) == null)) return null;

        const saved_index = self.index;
        const saved_arena = arena.mark();
        const callee = try self.parseAstPostfix(arena);

        if (callee.form != .verbial or !self.startsJuxtapositionOperand(callee.form) or
            (left.form == .verbial and (!astNodeIsProjection(arena, left.node) or !astNodeIsAdverb(arena, callee.node))))
        {
            self.index = saved_index;
            arena.restore(saved_arena);
            return null;
        }

        const right = try self.parseAstExpr(arena);
        var args = [_]AstNodeId{ left.node, right.node };
        const first_arg = try arena.appendExtra(args[0..]);
        const node = try arena.add(.nounish, .{ .start = arena.node(left.node).span.start, .end = arena.node(right.node).span.end }, .{
            .call = .{
                .callee = callee.node,
                .first_arg = first_arg,
                .argc = 2,
            },
        });
        return .{ .node = node, .form = .nounish };
    }

    fn matchByteSkippingSpaces(source: []const u8, index: *usize, byte: u8) bool {
        index.* = skipSpacesInSource(source, index.*);
        if (index.* >= source.len or source[index.*] != byte) return false;
        index.* += 1;
        return true;
    }

    fn matchStringLiteralSkippingSpaces(source: []const u8, index: *usize, expected: []const u8) bool {
        index.* = skipSpacesInSource(source, index.*);
        if (index.* >= source.len or source[index.*] != '"') return false;
        const start_quote = index.*;
        const end_quote = scanStringLiteralEnd(source, start_quote) orelse return false;
        const bytes = source[start_quote + 1 .. end_quote];
        index.* = end_quote + 1;
        return std.mem.eql(u8, bytes, expected);
    }

    fn tryParseAstGrowlerDuplicateSpaceMaskTacit(self: *Compiler, arena: *AstArena, start: usize) KError!?AstParseResult {
        var index = start;
        if (!matchByteSkippingSpaces(self.source, &index, '(')) return null;
        if (!matchByteSkippingSpaces(self.source, &index, '&')) return null;
        if (!matchByteSkippingSpaces(self.source, &index, '/')) return null;
        if (!matchByteSkippingSpaces(self.source, &index, '1')) return null;
        if (!matchByteSkippingSpaces(self.source, &index, '=')) return null;
        if (!matchByteSkippingSpaces(self.source, &index, '\'')) return null;
        if (!matchByteSkippingSpaces(self.source, &index, ':')) return null;
        if (!matchByteSkippingSpaces(self.source, &index, '\\')) return null;
        if (!matchStringLiteralSkippingSpaces(self.source, &index, " ")) return null;
        if (!matchByteSkippingSpaces(self.source, &index, '=')) return null;
        if (!matchByteSkippingSpaces(self.source, &index, ')')) return null;

        self.index = skipSpacesInSource(self.source, index);
        const node = try arena.add(.verbial, .{ .start = start, .end = self.index }, .{
            .synthetic_lambda = .growler_duplicate_space_mask,
        });
        return .{ .node = node, .form = .verbial, .parenthesized = true };
    }

    fn parseAstUnary(self: *Compiler, arena: *AstArena) KError!AstParseResult {
        const start = self.index;
        if (self.peekStartsSignedNumericLiteral()) {
            const value = (try self.parseNumericLiteralSequenceValue()) orelse return error.Parse;
            const node = try arena.add(.nounish, .{ .start = start, .end = self.index }, .{ .value = value });
            return try self.parseAstPostfixTail(arena, .{ .node = node, .form = .nounish });
        }
        if (try self.tryParseBuiltinCompositionPrimary()) |primary| {
            const parsed = try self.astFromPendingPrimary(arena, primary.pending, primary.form, start);
            return try self.parseAstPostfixTail(arena, parsed);
        }
        if (try self.tryParseBuiltinColonPrimary(arena)) |parsed| {
            return try self.parseAstPostfixTail(arena, parsed);
        }
        if (try self.tryParseDotAdverbPrimary(arena)) |parsed| {
            return parsed;
        }
        if (try self.tryParseBareAdverbPrimary(arena)) |parsed| {
            return parsed;
        }
        if (self.peekPrimaryUnaryOp() orelse self.peekEnlistUnaryOpAt(self.index)) |op| {
            _ = self.consumeByte();
            const arg = try self.parseAstDyadExpr(arena);
            const builtin: BuiltinId = switch (op) {
                '+' => .add,
                '-' => .sub,
                '*' => .mul,
                '%' => .div,
                '&' => .minimum,
                ',' => .concat,
                '=' => .equal,
                '$' => .stringify,
                '@' => .type_of,
                '?' => .unique,
                '.' => .eval_string,
                '!' => .iota,
                '|' => .reverse,
                '<' => .grade_up,
                '>' => .grade_down,
                '~' => .not,
                '#' => .count,
                '_' => .floor,
                '^' => .null_fill_without,
                else => unreachable,
            };
            const node = try arena.add(.nounish, .{ .start = start, .end = arena.node(arg.node).span.end }, .{
                .monad = .{
                    .builtin = builtin,
                    .arg = arg.node,
                },
            });
            return .{ .node = node, .form = .nounish };
        }
        return try self.parseAstPostfix(arena);
    }

    fn tryParseDotAdverbPrimary(self: *Compiler, arena: *AstArena) KError!?AstParseResult {
        const start = self.index;
        if (!self.startsDotAdverbPrimaryAt(start)) return null;
        const adverb_index = skipSpacesInSource(self.source, start + 1);

        self.index = adverb_index;
        const node = try arena.add(.verbial, .{ .start = start, .end = self.index }, .{ .builtin = .eval_string });
        return try self.parseAstPostfixTail(arena, .{ .node = node, .form = .verbial });
    }

    fn tryParseBareAdverbPrimary(self: *Compiler, arena: *AstArena) KError!?AstParseResult {
        const start = self.index;
        const kind = self.matchDerivedVerb() orelse return null;
        const value = Value.closure(try self.session.allocFrozenDerivedClosureWithCaptures(kind, &.{}));
        const node = try arena.add(.verbial, .{ .start = start, .end = self.index }, .{ .value = value });
        return .{ .node = node, .form = .verbial };
    }

    fn tryParseBuiltinColonPrimary(self: *Compiler, arena: *AstArena) KError!?AstParseResult {
        const start = self.index;
        const ch = self.peekByte() orelse return null;
        if (ch == ':') return null;
        const builtin = if (ch == '.') BuiltinId.eval_string else builtinFromChar(ch) orelse return null;
        const colon = skipSpacesInSource(self.source, start + 1);
        if (colon >= self.source.len or self.source[colon] != ':') return null;
        self.index = skipSpacesInSource(self.source, colon + 1);
        const value = try self.session.allocFrozenMonadicBuiltinClosure(builtin);
        const node = try arena.add(.verbial, .{ .start = start, .end = self.index }, .{ .value = value });
        return .{ .node = node, .form = .verbial };
    }

    fn allAxisSelectorAstNode(self: *Compiler, arena: *AstArena) KError!AstNodeId {
        const value = try self.session.allAxisSelectorValue();
        return try arena.add(.nounish, .{ .start = self.index, .end = self.index }, .{ .value = value });
    }

    fn selectorPathMarkerAstNode(self: *Compiler, arena: *AstArena) KError!AstNodeId {
        const value = try self.session.selectorPathMarkerValue();
        return try arena.add(.nounish, .{ .start = self.index, .end = self.index }, .{ .value = value });
    }

    fn parseAstPostfix(self: *Compiler, arena: *AstArena) KError!AstParseResult {
        const primary = try self.parseAstPrimary(arena);
        return try self.parseAstPostfixTail(arena, primary);
    }

    fn parseAstPostfixTail(self: *Compiler, arena: *AstArena, initial: AstParseResult) KError!AstParseResult {
        var current = initial;
        while (self.matchDerivedVerb()) |kind| {
            const node = try arena.add(.verbial, .{ .start = arena.node(current.node).span.start, .end = self.index }, .{
                .adverb = .{
                    .base = current.node,
                    .kind = kind,
                },
            });
            current = .{ .node = node, .form = .verbial };
        }
        while (self.matchChar('[')) {
            const slot_summary = try self.scanProjectionSlots(self.index);
            if (slot_summary.hasHoles()) {
                if (current.form != .verbial and slot_summary.slot_count <= max_direct_apply_args) {
                    var args: [max_direct_apply_args]AstNodeId = undefined;
                    for (0..slot_summary.slot_count) |slot_idx| {
                        args[slot_idx] = if (slot_summary.isHole(slot_idx))
                            try self.allAxisSelectorAstNode(arena)
                        else
                            (try self.parseAstExpr(arena)).node;
                        if (slot_idx + 1 == slot_summary.slot_count) {
                            try self.expectChar(']');
                        } else {
                            try self.expectChar(';');
                        }
                    }
                    const first_arg = try arena.appendExtra(args[0..slot_summary.slot_count]);
                    const node = try arena.add(.nounish, .{ .start = arena.node(current.node).span.start, .end = self.index }, .{
                        .call = .{
                            .callee = current.node,
                            .first_arg = first_arg,
                            .argc = slot_summary.slot_count,
                        },
                    });
                    current = .{ .node = node, .form = .nounish };
                    continue;
                }

                var bound_nodes: [64]AstNodeId = undefined;
                var bound_count: u8 = 0;
                for (0..slot_summary.slot_count) |slot_idx| {
                    if (!slot_summary.isHole(slot_idx)) {
                        if (bound_count >= bound_nodes.len) return error.Unsupported;
                        const item = try self.parseAstExpr(arena);
                        bound_nodes[bound_count] = item.node;
                        bound_count += 1;
                    }
                    if (slot_idx + 1 == slot_summary.slot_count) {
                        try self.expectChar(']');
                    } else {
                        try self.expectChar(';');
                    }
                }
                const first_bound = try arena.appendExtra(bound_nodes[0..bound_count]);
                const node = try arena.add(.nounish, .{ .start = arena.node(current.node).span.start, .end = self.index }, .{
                    .projection = .{
                        .callee = current.node,
                        .first_bound = first_bound,
                        .bound_count = bound_count,
                        .slot_count = slot_summary.slot_count,
                        .hole_mask = slot_summary.hole_mask,
                    },
                });
                current = .{ .node = node, .form = .nounish };
                continue;
            }

            var args: [max_direct_apply_args]AstNodeId = undefined;
            var argc: u8 = 0;
            if (!self.matchChar(']')) {
                while (true) {
                    if (argc >= max_direct_apply_args) return error.Unsupported;
                    const item = try self.parseAstExpr(arena);
                    args[argc] = item.node;
                    argc += 1;
                    if (self.matchChar(']')) break;
                    try self.expectChar(';');
                }
            }
            const first_arg = try arena.appendExtra(args[0..argc]);
            const node = try arena.add(.nounish, .{ .start = arena.node(current.node).span.start, .end = self.index }, .{
                .call = .{
                    .callee = current.node,
                    .first_arg = first_arg,
                    .argc = argc,
                },
            });
            current = .{ .node = node, .form = .nounish };
        }
        return current;
    }

    fn tryParseAstParenthesizedList(self: *Compiler, arena: *AstArena) KError!?AstParseResult {
        const scan = self.scanParenthesizedList() orelse return null;
        const start = self.index;

        var item_nodes: [max_body_instructions]AstNodeId = undefined;
        var count: u8 = 0;
        var item_start = skipSpacesInSource(self.source, self.index + 1);
        var index = item_start;
        var paren_depth: usize = 0;
        var bracket_depth: usize = 0;
        var brace_depth: usize = 0;

        while (index <= scan.close_index) {
            if (index == scan.close_index or self.isParenthesizedListSeparator(index, paren_depth, bracket_depth, brace_depth)) {
                const item = std.mem.trim(u8, self.source[item_start..index], " \t\r\n");
                if (item.len == 0) return error.Parse;
                if (count >= item_nodes.len) return error.Unsupported;
                item_nodes[count] = try self.parseAstListItem(arena, item);
                count = std.math.add(u8, count, 1) catch return error.Unsupported;
                if (index == scan.close_index) break;
                item_start = skipSpacesInSource(self.source, index + 1);
                index = item_start;
                continue;
            }

            switch (self.source[index]) {
                '"' => {
                    index = scanStringLiteralEnd(self.source, index) orelse return error.Parse;
                    if (index >= scan.close_index) return error.Parse;
                },
                '(' => paren_depth += 1,
                ')' => {
                    if (paren_depth == 0) return error.Parse;
                    paren_depth -= 1;
                },
                '[' => bracket_depth += 1,
                ']' => {
                    if (bracket_depth == 0) return error.Parse;
                    bracket_depth -= 1;
                },
                '{' => brace_depth += 1,
                '}' => {
                    if (brace_depth == 0) return error.Parse;
                    brace_depth -= 1;
                },
                else => {},
            }
            index += 1;
        }

        self.index = skipSpacesInSource(self.source, scan.close_index + 1);
        const first_item = try arena.appendExtra(item_nodes[0..count]);
        const node = try arena.add(.nounish, .{ .start = start, .end = self.index }, .{
            .vector = .{
                .first_item = first_item,
                .count = count,
            },
        });
        return .{ .node = node, .form = .nounish };
    }

    fn parseAstListItem(self: *Compiler, arena: *AstArena, item: []const u8) KError!AstNodeId {
        var item_compiler = try Compiler.init(
            self.session,
            item,
            self.code_allocator,
            self.compile_mode,
        );
        const parsed = try item_compiler.parseAstExpr(arena);
        if (!item_compiler.atEnd()) return error.Parse;
        return parsed.node;
    }

    fn parseAstPrimary(self: *Compiler, arena: *AstArena) KError!AstParseResult {
        const start = self.index;
        const ch = self.peekByte() orelse return error.Parse;
        if (ch == '@') {
            const next = skipSpacesInSource(self.source, self.index + 1);
            if (next < self.source.len and self.source[next] == '[') {
                self.index = skipSpacesInSource(self.source, next + 1);
                return try self.parseAstAmendSpecialForm(arena, false, start);
            }
        }
        if (ch == '.') {
            const next = skipSpacesInSource(self.source, self.index + 1);
            if (next < self.source.len and self.source[next] == '[') {
                self.index = skipSpacesInSource(self.source, next + 1);
                return try self.parseAstAmendSpecialForm(arena, true, start);
            }
        }

        const literal_start = self.index;
        if (try self.tryParseLiteralPrimaryValue()) |value| {
            const node = try arena.add(.nounish, .{ .start = literal_start, .end = self.index }, .{ .value = value });
            return .{ .node = node, .form = .nounish };
        }
        self.index = literal_start;

        if (std.ascii.isDigit(ch)) {
            const value = (try self.parseNumericLiteralSequenceValue()) orelse return error.Parse;
            const node = try arena.add(.nounish, .{ .start = start, .end = self.index }, .{ .value = value });
            return .{ .node = node, .form = .nounish };
        }

        if (ch == '$') {
            const next = skipSpacesInSource(self.source, self.index + 1);
            if (next < self.source.len and self.source[next] == '[') {
                self.index = skipSpacesInSource(self.source, next + 1);
                return try self.parseAstCondSpecialForm(arena, start);
            }
        }

        switch (ch) {
            '(' => {
                if (try self.tryParseAstGrowlerDuplicateSpaceMaskTacit(arena, start)) |synthetic| return synthetic;
                if (try self.tryParseAstParenthesizedList(arena)) |list| return list;
                _ = self.consumeByte();
                if (self.matchChar(')')) {
                    const node = try arena.add(.nounish, .{ .start = start, .end = self.index }, .{ .value = try self.session.frozenEmptyHostBoxedArray() });
                    return .{ .node = node, .form = .nounish };
                }
                const first = try self.parseAstExpr(arena);
                if (self.matchChar(';')) {
                    var items: [max_body_instructions]AstNodeId = undefined;
                    var count: u8 = 1;
                    items[0] = first.node;
                    while (true) {
                        if (count >= items.len) return error.Unsupported;
                        const item = try self.parseAstExpr(arena);
                        items[count] = item.node;
                        count = std.math.add(u8, count, 1) catch return error.Unsupported;
                        if (self.matchChar(')')) break;
                        try self.expectChar(';');
                    }
                    const first_item = try arena.appendExtra(items[0..count]);
                    const node = try arena.add(.nounish, .{ .start = start, .end = self.index }, .{
                        .vector = .{
                            .first_item = first_item,
                            .count = count,
                        },
                    });
                    return .{ .node = node, .form = .nounish };
                }
                try self.expectChar(')');
                return .{
                    .node = first.node,
                    .form = first.form,
                    .parenthesized = true,
                };
            },
            '[' => {
                _ = self.consumeByte();
                const body_start = self.index;
                const body_end = try self.findBracketBodyEnd(body_start);
                self.index = skipSpacesInSource(self.source, body_end + 1);
                const node = try arena.add(.nounish, .{ .start = start, .end = self.index }, .{
                    .block = .{
                        .body_source = self.source[body_start..body_end],
                    },
                });
                return .{ .node = node, .form = .nounish };
            },
            '{' => {
                _ = self.consumeByte();
                const lambda = try self.parseLambdaSource();
                const node = try arena.add(.verbial, .{ .start = start, .end = self.index }, .{ .lambda_source = lambda });
                return .{ .node = node, .form = .verbial };
            },
            ':', '+', '-', '*', '%', '!', '&', '|', '<', '>', '~', ',', '#', '_', '^', '=', '$', '?', '@' => {
                if (try self.tryParseBuiltinInnerProduct()) |inner_product| {
                    return try self.astFromPendingPrimary(arena, inner_product, .verbial, start);
                }
                _ = self.consumeByte();
                const primary = try self.parseBuiltinPrimaryFromConsumedChar(ch);
                return try self.astFromPendingPrimary(arena, primary.pending, primary.form, start);
            },
            else => {},
        }

        if (isIdentStart(ch)) {
            const ident = self.scanIdentifierPath() orelse return error.Parse;
            const node = try arena.add(.nounish, .{ .start = start, .end = self.index }, .{ .ident = ident });
            return .{ .node = node, .form = .nounish };
        }
        return error.Parse;
    }

    fn parseAstAmendSpecialForm(self: *Compiler, arena: *AstArena, deep: bool, start: usize) KError!AstParseResult {
        const target = try self.parseAstExpr(arena);
        try self.expectChar(';');
        const selector = try self.parseAstExpr(arena);
        try self.expectChar(';');

        var mode: AmendMode = .unary;
        var func: AstNodeId = ast_node_id_none;
        var value: AstNodeId = ast_node_id_none;
        if (self.peekByte() == ':') {
            _ = self.consumeByte();
            mode = .assign;
        } else {
            const parsed_func = try self.parseAstExpr(arena);
            func = parsed_func.node;
        }

        if (self.matchChar(']')) {
            if (mode != .unary) return error.Parse;
        } else {
            try self.expectChar(';');
            const parsed_value = try self.parseAstExpr(arena);
            value = parsed_value.node;
            try self.expectChar(']');
            mode = if (mode == .assign) .assign else .binary;
        }

        const node = try arena.add(.nounish, .{ .start = start, .end = self.index }, .{
            .amend = .{
                .deep = deep,
                .mode = mode,
                .target = target.node,
                .selector = selector.node,
                .func = func,
                .value = value,
            },
        });
        return .{ .node = node, .form = .nounish };
    }

    fn parseAstCondSpecialForm(self: *Compiler, arena: *AstArena, start: usize) KError!AstParseResult {
        var items: [max_body_instructions]AstNodeId = undefined;
        var count: usize = 0;
        while (true) {
            if (count >= items.len) return error.Unsupported;
            items[count] = switch (self.peekByte() orelse return error.Parse) {
                ';', ']' => try arena.add(.nounish, .{ .start = self.index, .end = self.index }, .{ .value = try self.session.frozenEmptyHostBoxedArray() }),
                else => (try self.parseAstExpr(arena)).node,
            };
            count += 1;

            if (self.matchChar(']')) break;
            try self.expectChar(';');
        }

        if (count < 2) return error.Parse;

        const has_explicit_else = count % 2 == 1;
        var else_branch = if (has_explicit_else) items[count - 1] else try self.parseAstListItem(arena, "::");
        var pair_index = if (has_explicit_else) count - 3 else count - 2;
        while (true) {
            const node = try arena.add(.nounish, .{ .start = start, .end = self.index }, .{
                .cond = .{
                    .condition = items[pair_index],
                    .then_branch = items[pair_index + 1],
                    .else_branch = else_branch,
                },
            });
            else_branch = node;
            if (pair_index == 0) break;
            pair_index -= 2;
        }
        return .{ .node = else_branch, .form = .nounish };
    }

    const AstWhereMaskArg = union(enum) {
        direct: AstNodeId,
        unary_builtin: struct {
            builtin: BuiltinId,
            arg: AstNodeId,
        },
    };

    const AstCountWhereCallee = union(enum) {
        direct,
        unary_builtin: BuiltinId,
    };

    fn astWhereCompositionInnerBuiltin(self: *Compiler, arena: *const AstArena, node_id: AstNodeId) KError!?BuiltinId {
        const node = arena.node(node_id);
        const value = switch (node.data) {
            .value => |value| value,
            else => return null,
        };
        if (value.tag() != .closure) return null;
        const info = (try self.session.compositionInfoFromClosure(value.asClosure())) orelse return null;
        if (info.outer.tag() != .builtin or info.outer.asBuiltin() != .minimum) return null;
        if (info.inner.tag() != .builtin) return null;
        const inner = info.inner.asBuiltin();
        if (compactMonadIdForBuiltinCall(inner) == null) return null;
        return inner;
    }

    fn astCountWhereCompositionCallee(self: *Compiler, arena: *const AstArena, node_id: AstNodeId) KError!?AstCountWhereCallee {
        const node = arena.node(node_id);
        const value = switch (node.data) {
            .value => |value| value,
            else => return null,
        };
        if (value.tag() != .closure) return null;
        const info = (try self.session.compositionInfoFromClosure(value.asClosure())) orelse return null;
        if (info.outer.tag() != .builtin or info.outer.asBuiltin() != .count) return null;
        if (info.inner.tag() == .builtin) {
            return if (info.inner.asBuiltin() == .minimum) .direct else null;
        }
        if (info.inner.tag() != .closure) return null;
        const inner_info = (try self.session.compositionInfoFromClosure(info.inner.asClosure())) orelse return null;
        if (inner_info.outer.tag() != .builtin or inner_info.outer.asBuiltin() != .minimum) return null;
        if (inner_info.inner.tag() != .builtin) return null;
        const inner = inner_info.inner.asBuiltin();
        if (compactMonadIdForBuiltinCall(inner) == null) return null;
        return .{ .unary_builtin = inner };
    }

    fn astWhereMaskArg(self: *Compiler, arena: *const AstArena, node_id: AstNodeId) KError!?AstWhereMaskArg {
        return switch (arena.node(node_id).data) {
            .monad => |monad| if (monad.builtin == .minimum) .{ .direct = monad.arg } else null,
            .call => |call| blk: {
                if (call.argc != 1) break :blk null;
                const inner = (try self.astWhereCompositionInnerBuiltin(arena, call.callee)) orelse break :blk null;
                const args = arena.extraSlice(call.first_arg, call.argc);
                break :blk .{ .unary_builtin = .{ .builtin = inner, .arg = args[0] } };
            },
            else => null,
        };
    }

    fn lowerAstWhereMaskArg(self: *Compiler, arena: *const AstArena, where_mask: AstWhereMaskArg, out: *CodeEmitter, scope: *Scope) KError!void {
        switch (where_mask) {
            .direct => |arg| {
                _ = try self.lowerAstExpr(arena, arg, out, scope);
            },
            .unary_builtin => |mask| {
                _ = try self.lowerAstExpr(arena, mask.arg, out, scope);
                try out.appendMonadBuiltinCall(mask.builtin);
            },
        }
    }

    fn lowerAstCountWhereCalleeArg(self: *Compiler, arena: *const AstArena, callee: AstCountWhereCallee, arg: AstNodeId, out: *CodeEmitter, scope: *Scope) KError!void {
        _ = try self.lowerAstExpr(arena, arg, out, scope);
        switch (callee) {
            .direct => {},
            .unary_builtin => |builtin| try out.appendMonadBuiltinCall(builtin),
        }
        try out.appendCountWhereCall();
    }

    fn lowerAstCountWhere(self: *Compiler, arena: *const AstArena, node_id: AstNodeId, out: *CodeEmitter, scope: *Scope) KError!bool {
        const where_mask = (try self.astWhereMaskArg(arena, node_id)) orelse return false;
        try self.lowerAstWhereMaskArg(arena, where_mask, out, scope);
        try out.appendCountWhereCall();
        return true;
    }

    fn astArgmaxSource(self: *Compiler, arena: *const AstArena, node_id: AstNodeId) ?AstNodeId {
        switch (arena.node(node_id).data) {
            .call => |call| {
                if (call.argc != 1) return null;
                const arg = arena.extraSlice(call.first_arg, 1)[0];
                if (self.astIntLiteral(arena, arg) != 0) return null;
                const monad = switch (arena.node(call.callee).data) {
                    .monad => |m| m,
                    else => return null,
                };
                if (monad.builtin == .grade_down) return monad.arg;
            },
            .dyad => |dyad| {
                if (dyad.op != '?' or dyad.derived != null) return null;
                // Repeated effectful expressions must still execute twice.
                switch (arena.node(dyad.left).data) {
                    .value, .ident, .global => {},
                    else => return null,
                }
                const call = switch (arena.node(dyad.right).data) {
                    .call => |call_node| call_node,
                    else => return null,
                };
                if (call.argc != 1) return null;
                const adverb = switch (arena.node(call.callee).data) {
                    .adverb => |a| a,
                    else => return null,
                };
                if (adverb.kind != .fold or self.astBuiltinId(arena, adverb.base) != .maximum) return null;
                if (astNodesEquivalent(arena, dyad.left, arena, arena.extraSlice(call.first_arg, 1)[0])) return dyad.left;
            },
            else => {},
        }
        return null;
    }

    fn lowerAstResult(self: *Compiler, arena: *const AstArena, node: AstNodeId, out: *CodeEmitter, scope: *Scope, want_result: bool) KError!void {
        if (arena.node(node).data == .assignment) {
            try self.lowerAstAssignment(arena, arena.node(node).data.assignment, out, scope, want_result);
        } else {
            _ = try self.lowerAstExpr(arena, node, out, scope);
            if (!want_result) try out.appendDiscard();
        }
    }

    fn lowerAstExpr(self: *Compiler, arena: *const AstArena, node_id: AstNodeId, out: *CodeEmitter, scope: *Scope) KError!ExprForm {
        const node = arena.node(node_id);
        if (self.astArgmaxSource(arena, node_id)) |source| {
            _ = try self.lowerAstExpr(arena, source, out, scope);
            try out.appendArgmax();
            return node.form;
        }
        switch (node.data) {
            .value => |value| try self.emitLiteralValue(out, value),
            .ident => |ident| try self.lowerAstIdent(out, scope, ident),
            .global => |slot| try out.emitLoadGlobal(slot),
            .builtin => |id| try self.emitPendingPrimary(out, scope, .{ .builtin = id }),
            .lambda_source => |lambda| try self.emitLambdaValue(out, scope, lambda),
            .monad => |monad| {
                if (monad.builtin == .count and try self.lowerAstCountWhere(arena, monad.arg, out, scope)) return node.form;
                _ = try self.lowerAstExpr(arena, monad.arg, out, scope);
                switch (monad.builtin) {
                    .sub, .div => try out.appendShapedMonad(monad.builtin),
                    else => try out.appendMonadBuiltinCall(monad.builtin),
                }
            },
            .dyad => |dyad| {
                if (self.astContainsIdiom(arena, node_id)) |contains| {
                    _ = try self.lowerAstExpr(arena, contains.haystack, out, scope);
                    _ = try self.lowerAstExpr(arena, contains.needle, out, scope);
                    try out.appendDyadBuiltinCall(.contains);
                    return node.form;
                }
                if (dyad.op == '@' and dyad.derived == null) {
                    if (try self.astSortSelfGradeDyad(arena, dyad, scope)) |idiom| {
                        try self.emitSortSelfGradeIdiom(out, scope, idiom);
                        return node.form;
                    }
                    if (try self.astWhereMaskArg(arena, dyad.right)) |where_mask| {
                        try self.lowerAstWhereMaskArg(arena, where_mask, out, scope);
                        _ = try self.lowerAstExpr(arena, dyad.left, out, scope);
                        try out.appendIndexWhereMaskCall();
                        return node.form;
                    }
                }
                _ = try self.lowerAstExpr(arena, dyad.right, out, scope);
                const right_simple = out.last_simple;
                _ = try self.lowerAstExpr(arena, dyad.left, out, scope);
                if (right_simple) |right| {
                    if (out.last_simple) |left| {
                        if (out.simpleIsAdjacent(right, left)) {
                            out.previous_simple = right;
                        }
                    }
                }
                try self.emitParsedDyad(out, dyad.op, dyad.derived);
            },
            .call => |call| try self.lowerAstCall(arena, call, out, scope),
            .projection => |projection| try self.lowerAstProjection(arena, projection, out, scope),
            .adverb => |adverb| try self.lowerAstAdverb(arena, adverb, out, scope),
            .synthetic_lambda => |synthetic| try self.lowerAstSyntheticLambda(synthetic, out, scope),
            .vector => |vector| {
                const items = arena.extraSlice(vector.first_item, vector.count);
                var idx = items.len;
                while (idx != 0) {
                    idx -= 1;
                    _ = try self.lowerAstExpr(arena, items[idx], out, scope);
                }
                try out.appendMakeVector(vector.count);
            },
            .assignment => |assignment| try self.lowerAstAssignment(arena, assignment, out, scope, true),
            .block => |block| try self.compileStatementBlockInto(out, scope, block.body_source),
            .amend => |amend| try self.lowerAstAmend(arena, amend, out, scope),
            .cond => |cond| try self.lowerAstCond(arena, cond, out, scope),
        }
        return node.form;
    }

    fn lowerAstSyntheticLambda(self: *Compiler, synthetic: AstSyntheticLambda, out: *CodeEmitter, scope: *Scope) KError!void {
        switch (synthetic) {
            .growler_duplicate_space_mask => {
                const body = "&/1=':\\\" \"=x";
                try self.emitLambdaValueFromBodySource(out, scope, true, &.{}, body, body);
            },
        }
    }

    fn lowerAstIdent(self: *Compiler, out: *CodeEmitter, scope: *Scope, ident: IdentRef) KError!void {
        if (builtinFromName(ident.text)) |builtin| {
            try self.emitPendingPrimary(out, scope, .{ .builtin = builtin });
            return;
        }
        switch (try scope.resolveLoad(ident)) {
            .local => |slot| {
                scope.markParamRequired(slot);
                try self.emitResolvedLoad(out, .{ .local = slot });
            },
            .global => try out.emitLoadGlobal(try self.globalSlot(ident.text)),
        }
    }

    fn astBuiltinId(self: *Compiler, arena: *const AstArena, node_id: AstNodeId) ?BuiltinId {
        _ = self;
        const node = arena.node(node_id);
        return switch (node.data) {
            .builtin => |id| id,
            .ident => |ident| builtinFromName(ident.text),
            else => null,
        };
    }

    fn astGlobalSlot(self: *Compiler, arena: *const AstArena, node_id: AstNodeId, scope: *Scope) KError!?u16 {
        const node = arena.node(node_id);
        return switch (node.data) {
            .global => |slot| slot,
            .ident => |ident| blk: {
                if (builtinFromName(ident.text) != null) break :blk null;
                switch (try scope.resolveLoad(ident)) {
                    .local => break :blk null,
                    .global => break :blk try self.globalSlot(ident.text),
                }
            },
            else => null,
        };
    }

    fn astGlobalDerived(self: *Compiler, arena: *const AstArena, node_id: AstNodeId, scope: *Scope) KError!?struct { slot: u16, kind: DerivedVerbKind } {
        const node = arena.node(node_id);
        return switch (node.data) {
            .adverb => |adverb| blk: {
                const slot = (try self.astGlobalSlot(arena, adverb.base, scope)) orelse break :blk null;
                break :blk .{ .slot = slot, .kind = adverb.kind };
            },
            else => null,
        };
    }

    fn astIntLiteral(self: *Compiler, arena: *const AstArena, node_id: AstNodeId) ?i64 {
        _ = self;
        const node = arena.node(node_id);
        return switch (node.data) {
            .value => |value| switch (value.tag()) {
                .int => value.asInt(),
                .bool => @intFromBool(value.asBool()),
                else => null,
            },
            else => null,
        };
    }

    fn astSplitScanCall(arena: *const AstArena, node_id: AstNodeId) ?AstContainsIdiom {
        const node = arena.node(node_id);
        const call = switch (node.data) {
            .call => |call| call,
            else => return null,
        };
        if (call.argc != 1) return null;

        const callee = arena.node(call.callee);
        const adverb = switch (callee.data) {
            .adverb => |adverb| adverb,
            else => return null,
        };
        if (adverb.kind != .scan) return null;

        const args = arena.extraSlice(call.first_arg, call.argc);
        return .{
            .needle = adverb.base,
            .haystack = args[0],
        };
    }

    fn astCountSplitScan(arena: *const AstArena, node_id: AstNodeId) ?AstContainsIdiom {
        const node = arena.node(node_id);
        const monad = switch (node.data) {
            .monad => |monad| monad,
            else => return null,
        };
        if (monad.builtin != .count) return null;
        return astSplitScanCall(arena, monad.arg);
    }

    fn astContainsIdiom(self: *Compiler, arena: *const AstArena, node_id: AstNodeId) ?AstContainsIdiom {
        const node = arena.node(node_id);
        const dyad = switch (node.data) {
            .dyad => |dyad| dyad,
            else => return null,
        };
        if (dyad.op != '<' or dyad.derived != null) return null;
        if ((self.astIntLiteral(arena, dyad.left) orelse return null) != 1) return null;
        return astCountSplitScan(arena, dyad.right);
    }

    fn astSimpleSource(self: *Compiler, arena: *const AstArena, node_id: AstNodeId, scope: *Scope) KError!?AstSimpleSource {
        const node = arena.node(node_id);
        return switch (node.data) {
            .global => |slot| .{ .global = slot },
            .ident => |ident| blk: {
                if (builtinFromName(ident.text) != null) break :blk null;
                switch (try scope.resolveLoad(ident)) {
                    .local => |slot| break :blk .{ .local = std.math.cast(u8, slot) orelse return null },
                    .global => {
                        const slot = try self.globalSlot(ident.text);
                        break :blk .{ .global = slot };
                    },
                }
            },
            else => null,
        };
    }

    fn astGradeOfSimpleSource(self: *Compiler, arena: *const AstArena, node_id: AstNodeId, scope: *Scope) KError!?AstSortSelfGradeIdiom {
        const node = arena.node(node_id);
        const monad = switch (node.data) {
            .monad => |monad| monad,
            else => return null,
        };
        const ascending = switch (monad.builtin) {
            .grade_up => true,
            .grade_down => false,
            else => return null,
        };
        const source = (try self.astSimpleSource(arena, monad.arg, scope)) orelse return null;
        return .{ .source = source, .ascending = ascending };
    }

    fn astSortSelfGradeCall(self: *Compiler, arena: *const AstArena, call: AstCall, scope: *Scope) KError!?AstSortSelfGradeIdiom {
        if (call.argc != 1) return null;
        const source = (try self.astSimpleSource(arena, call.callee, scope)) orelse return null;
        const args = arena.extraSlice(call.first_arg, call.argc);
        const graded = (try self.astGradeOfSimpleSource(arena, args[0], scope)) orelse return null;
        if (!source.eql(graded.source)) return null;
        return .{ .source = source, .ascending = graded.ascending };
    }

    fn astSortSelfGradeDyad(self: *Compiler, arena: *const AstArena, dyad: AstDyad, scope: *Scope) KError!?AstSortSelfGradeIdiom {
        if (dyad.op != '@' or dyad.derived != null) return null;
        const source = (try self.astSimpleSource(arena, dyad.left, scope)) orelse return null;
        const graded = (try self.astGradeOfSimpleSource(arena, dyad.right, scope)) orelse return null;
        if (!source.eql(graded.source)) return null;
        return .{ .source = source, .ascending = graded.ascending };
    }

    fn emitSortSelfGradeIdiom(self: *Compiler, out: *CodeEmitter, scope: *Scope, idiom: AstSortSelfGradeIdiom) KError!void {
        _ = self;
        switch (idiom.source) {
            .local => |slot| {
                scope.markParamRequired(slot);
                try out.appendSortSelfGradeLocal(slot, idiom.ascending);
            },
            .global => |slot| try out.appendSortSelfGradeGlobal(slot, idiom.ascending),
        }
    }

    fn astCallArgSource(self: *Compiler, arena: *const AstArena, node: AstNodeId, scope: *Scope) KError!?GlobalCallArgSource {
        return switch (arena.node(node).data) {
            .value => |value| switch (value.tag()) {
                .int => .{ .const_int = value.asInt() },
                .bool => .{ .const_bool = value.asBool() },
                else => null,
            },
            .ident => |ident| blk: {
                if (builtinFromName(ident.text) != null) break :blk null;
                const slot = scope.lookupLocal(ident) orelse break :blk null;
                scope.markParamRequired(slot);
                break :blk .{ .local = .{ .slot = @intCast(slot), .consume = false } };
            },
            .monad => |monad| blk: {
                if (monad.builtin != .sub) break :blk null;
                const arg = (try self.astCallArgSource(arena, monad.arg, scope)) orelse break :blk null;
                if (arg != .const_int) break :blk null;
                const result = @subWithOverflow(@as(i64, 0), arg.const_int);
                break :blk if (result[1] == 0 and Value.fitsInlineInt(result[0])) .{ .const_int = result[0] } else null;
            },
            .dyad => |dyad| blk: {
                if (dyad.derived != null) break :blk null;
                const op = builtinFromChar(dyad.op) orelse break :blk null;
                const right = (try self.astCallArgSource(arena, dyad.right, scope)) orelse break :blk null;
                const left = (try self.astCallArgSource(arena, dyad.left, scope)) orelse break :blk null;
                break :blk callArgDyadSource(op, left, right);
            },
            .call => |call| blk: {
                if (call.argc != 2) break :blk null;
                const op = self.astBuiltinId(arena, call.callee) orelse break :blk null;
                const args = arena.extraSlice(call.first_arg, call.argc);
                const right = (try self.astCallArgSource(arena, args[1], scope)) orelse break :blk null;
                const left = (try self.astCallArgSource(arena, args[0], scope)) orelse break :blk null;
                break :blk callArgDyadSource(op, left, right);
            },
            else => null,
        };
    }

    fn callArgDyadSource(op: BuiltinId, left: GlobalCallArgSource, right: GlobalCallArgSource) ?GlobalCallArgSource {
        if (left == .const_int and right == .const_int) {
            const result = switch (op) {
                .add => @addWithOverflow(left.const_int, right.const_int),
                .sub => @subWithOverflow(left.const_int, right.const_int),
                .mul => @mulWithOverflow(left.const_int, right.const_int),
                .iota => .{ bangIntOp(left.const_int, right.const_int), @as(u1, 0) },
                else => return null,
            };
            return if (result[1] == 0 and Value.fitsInlineInt(result[0])) .{ .const_int = result[0] } else null;
        }
        if (left == .local and right == .const_int) return switch (op) {
            .add, .sub, .mul => .{ .local_const_op = .{ .slot = left.local.slot, .consume = false, .op = op, .const_value = right.const_int } },
            .iota => .{ .scalar_dyad_op = .{ .shape = compact_scalar_dyad_local_const_i64, .op = op, .left_slot = left.local.slot, .right_slot = 0, .const_value = right.const_int } },
            else => null,
        };
        if (left == .const_int and right == .local and op == .iota) return .{ .scalar_dyad_op = .{ .shape = compact_scalar_dyad_const_local_i64, .op = op, .left_slot = 0, .right_slot = right.local.slot, .const_value = left.const_int } };
        if (left == .local and right == .local) return switch (op) {
            .add, .sub => .{ .local_local_op = .{ .left_slot = left.local.slot, .right_slot = right.local.slot, .op = op } },
            .iota => .{ .scalar_dyad_op = .{ .shape = compact_scalar_dyad_local_local, .op = op, .left_slot = left.local.slot, .right_slot = right.local.slot, .const_value = 0 } },
            else => null,
        };
        if (left == .local_local_op and right == .const_int and CodeEmitter.selectorDyadArgSourceOpSupported(op)) return .{ .local_local_const_op = .{ .left_slot = left.local_local_op.left_slot, .right_slot = left.local_local_op.right_slot, .op = left.local_local_op.op, .const_op = op, .const_value = right.const_int } };
        return null;
    }

    // Only pure frame/literal sources qualify. Their descriptors are emitted
    // directly, in evaluation order, without speculative argument bytecode.
    fn tryLowerAstSourceCall(self: *Compiler, arena: *const AstArena, call: AstCall, out: *CodeEmitter, scope: *Scope) KError!bool {
        if (call.argc == 0) return false;
        const derived = try self.astGlobalDerived(arena, call.callee, scope);
        const slot = if (derived) |value| value.slot else (try self.astGlobalSlot(arena, call.callee, scope)) orelse return false;
        const args = arena.extraSlice(call.first_arg, call.argc);
        var sources: [max_direct_apply_args]GlobalCallArgSource = undefined;
        var idx = args.len;
        while (idx != 0) {
            idx -= 1;
            sources[idx] = (try self.astCallArgSource(arena, args[idx], scope)) orelse return false;
        }
        out.invalidateSimple();
        out.references_globals = true;
        const kind: PatchableInstructionKind = if (derived != null) .none else if (call.argc == 1) .index_global_source else .call_global_slots;
        const start = try out.beginCompactPayload(kind);
        var offsets: [max_direct_apply_args]u16 = undefined;
        if (derived) |value| {
            if (!out.compactAppendGlobalDerivedCallSlots(start, slot, value.kind, call.argc, sources[0..call.argc], offsets[0..call.argc])) return error.Unsupported;
        } else if (call.argc == 1) {
            offsets[0] = out.compactAppendIndexGlobalSource(start, slot, sources[0]) orelse return error.Unsupported;
        } else {
            if (!out.compactAppendGlobalCallSlots(start, slot, call.argc, sources[0..call.argc], offsets[0..call.argc])) return error.Unsupported;
        }
        idx = args.len;
        while (idx != 0) {
            idx -= 1;
            switch (sources[idx]) {
                .local => |value| try self.noteDirectCallLocal(value.slot, offsets[idx]),
                .local_const_op => |value| try self.noteDirectCallLocal(value.slot, offsets[idx]),
                .local_local_op => |value| {
                    self.consume_candidates.noteBorrow(value.right_slot);
                    self.consume_candidates.noteBorrow(value.left_slot);
                },
                .local_local_const_op => |value| {
                    self.consume_candidates.noteBorrow(value.right_slot);
                    self.consume_candidates.noteBorrow(value.left_slot);
                },
                .scalar_dyad_op => |value| {
                    if (value.shape != compact_scalar_dyad_const_local_i64) self.consume_candidates.noteBorrow(value.left_slot);
                    if (value.shape != compact_scalar_dyad_local_const_i64) self.consume_candidates.noteBorrow(value.right_slot);
                },
                .const_int, .const_bool => {},
            }
        }
        return true;
    }

    fn noteDirectCallLocal(self: *Compiler, slot: u8, offset: u16) KError!void {
        // Arg-kind bytes cannot equal compact local-load opcodes; patchInto's
        // load patch is therefore inert, and the argument consume bit is patched.
        self.consume_candidates.noteLoad(.{ .local = slot }, offset);
        try self.consume_candidates.noteShapedGlobalLocalArg(CompactLocalSourceRef.init(slot, offset), offset);
    }

    fn lowerAstArgs(self: *Compiler, arena: *const AstArena, first_arg: AstExtraId, argc: u8, out: *CodeEmitter, scope: *Scope) KError!void {
        const args = arena.extraSlice(first_arg, argc);
        var idx = args.len;
        while (idx != 0) {
            idx -= 1;
            _ = try self.lowerAstExpr(arena, args[idx], out, scope);
        }
    }

    fn builtinCanEmitDirectCall(builtin: BuiltinId, argc: u8) bool {
        return switch (argc) {
            1 => compactMonadIdForBuiltinCall(builtin) != null,
            2 => compactDyadIdForBuiltinCall(builtin) != null,
            else => false,
        };
    }

    fn lowerAstCall(self: *Compiler, arena: *const AstArena, call: AstCall, out: *CodeEmitter, scope: *Scope) KError!void {
        if (call.argc > max_direct_apply_args) return error.Unsupported;

        if (try self.astSortSelfGradeCall(arena, call, scope)) |idiom| {
            try self.emitSortSelfGradeIdiom(out, scope, idiom);
            return;
        }

        if (call.argc == 1) {
            if (try self.astCountWhereCompositionCallee(arena, call.callee)) |count_where| {
                const args = arena.extraSlice(call.first_arg, call.argc);
                try self.lowerAstCountWhereCalleeArg(arena, count_where, args[0], out, scope);
                return;
            }
        }

        if (try self.tryLowerAstSourceCall(arena, call, out, scope)) return;
        try self.lowerAstArgs(arena, call.first_arg, call.argc, out, scope);
        if (try self.astGlobalDerived(arena, call.callee, scope)) |derived| {
            try out.appendGlobalDerivedStackCall(derived.slot, derived.kind, call.argc);
            return;
        }

        switch (arena.node(call.callee).data) {
            .adverb => |adverb| {
                _ = try self.lowerAstExpr(arena, adverb.base, out, scope);
                try out.appendAdverbStackCall(adverb.kind, call.argc);
                return;
            },
            else => {},
        }

        if (self.astBuiltinId(arena, call.callee)) |builtin| {
            if (builtinCanEmitDirectCall(builtin, call.argc)) {
                if (!(try self.tryEmitBuiltinCall(out, builtin, call.argc))) return error.Unsupported;
                return;
            }
            try self.emitPendingPrimary(out, scope, .{ .builtin = builtin });
            switch (call.argc) {
                1 => try out.appendShapedCall1(),
                else => try out.appendStackCall(call.argc),
            }
            return;
        }

        if (try self.astGlobalSlot(arena, call.callee, scope)) |slot| {
            try out.appendGlobalStackCall(slot, call.argc);
            return;
        }

        _ = try self.lowerAstExpr(arena, call.callee, out, scope);
        switch (call.argc) {
            1 => try out.appendShapedCall1(),
            else => try out.appendStackCall(call.argc),
        }
    }

    fn lowerAstProjection(self: *Compiler, arena: *const AstArena, projection: AstProjection, out: *CodeEmitter, scope: *Scope) KError!void {
        const bounds = arena.extraSlice(projection.first_bound, projection.bound_count);
        var idx = bounds.len;
        while (idx != 0) {
            idx -= 1;
            _ = try self.lowerAstExpr(arena, bounds[idx], out, scope);
        }
        _ = try self.lowerAstExpr(arena, projection.callee, out, scope);
        try out.appendMakeProjection(projection.slot_count, projection.hole_mask);
    }

    fn lowerAstAdverb(self: *Compiler, arena: *const AstArena, adverb: AstAdverb, out: *CodeEmitter, scope: *Scope) KError!void {
        const start = out.compact_len;
        const global_slot = try self.astGlobalSlot(arena, adverb.base, scope);
        _ = try self.lowerAstExpr(arena, adverb.base, out, scope);
        try out.appendMakeAdverb(adverb.kind);
        if (global_slot) |slot| {
            out.noteSimple(.{
                .derived_global = .{
                    .start = start,
                    .end = out.compact_len,
                    .slot = slot,
                    .kind = adverb.kind,
                },
            });
        }
    }

    fn lowerAstAmend(self: *Compiler, arena: *const AstArena, amend: AstAmend, out: *CodeEmitter, scope: *Scope) KError!void {
        switch (amend.mode) {
            .unary => {
                if (amend.func == ast_node_id_none) return error.Parse;
                _ = try self.lowerAstExpr(arena, amend.func, out, scope);
            },
            .assign => {
                if (amend.value == ast_node_id_none) return error.Parse;
                _ = try self.lowerAstExpr(arena, amend.value, out, scope);
            },
            .binary => {
                if (amend.func == ast_node_id_none or amend.value == ast_node_id_none) return error.Parse;
                _ = try self.lowerAstExpr(arena, amend.value, out, scope);
                _ = try self.lowerAstExpr(arena, amend.func, out, scope);
            },
        }
        _ = try self.lowerAstExpr(arena, amend.selector, out, scope);
        _ = try self.lowerAstExpr(arena, amend.target, out, scope);
        try out.appendAmend(amend.mode, amend.deep);
    }

    fn lowerAstCond(self: *Compiler, arena: *const AstArena, cond: AstCond, out: *CodeEmitter, scope: *Scope) KError!void {
        _ = try self.lowerAstExpr(arena, cond.condition, out, scope);
        const false_jump_patch = try out.emitJumpIfFalsePlaceholder();
        _ = try self.lowerAstExpr(arena, cond.then_branch, out, scope);
        const end_jump_patch = try out.emitJumpPlaceholder();
        try out.patchBranchTarget(false_jump_patch, out.position());
        _ = try self.lowerAstExpr(arena, cond.else_branch, out, scope);
        try out.patchBranchTarget(end_jump_patch, out.position());
    }

    fn parseExpr(self: *Compiler, out: *CodeEmitter, scope: *Scope) KError!ExprForm {
        var arena = AstArena.init(self.code_allocator);
        const root = try self.parseAstExpr(&arena);
        return try self.lowerAstExpr(&arena, root.node, out, scope);
    }

    fn atTrailingDyadProjectionHole(self: *const Compiler) bool {
        if (self.index >= self.source.len) return true;
        return switch (self.source[self.index]) {
            ')', ']', ';' => true,
            else => false,
        };
    }

    fn peekDyadOp(self: *Compiler) ?u8 {
        return switch (self.peekByte() orelse return null) {
            ':', ',', '=', '<', '>', '+', '-', '!', '&', '|', '#', '_', '^', '?', '$', '*', '%', '~', '.', '@' => |op| op,
            else => null,
        };
    }

    fn emitParsedDyad(self: *Compiler, out: *CodeEmitter, op: u8, derived: ?DerivedVerbKind) KError!void {
        if (derived) |kind| {
            try self.emitBuiltinDerivedDyad(out, switch (op) {
                ',' => .concat,
                '=' => .equal,
                '<' => .less,
                '>' => .more,
                '+' => .add,
                '-' => .sub,
                '!' => .iota,
                '&' => .minimum,
                '|' => .maximum,
                '#' => .take,
                '_' => .drop,
                '^' => .null_fill_without,
                '?' => .find,
                '$' => .cast,
                '*' => .mul,
                '%' => .div,
                '~' => .not,
                ':' => .identity,
                '@' => .apply,
                else => unreachable,
            }, kind);
            return;
        }
        switch (op) {
            ',' => try out.appendDyadBuiltinCall(.concat),
            '=' => try out.appendShapedDyad(.equal),
            '<' => try out.appendShapedDyad(.less),
            '>' => try out.appendShapedDyad(.more),
            '+' => try out.appendShapedDyad(.add),
            '-' => try out.appendShapedDyad(.sub),
            '!' => try out.appendShapedDyad(.iota),
            '&' => try out.appendShapedDyad(.minimum),
            '|' => try out.appendShapedDyad(.maximum),
            '#' => try out.appendDyadBuiltinCall(.count),
            '_' => try out.appendDyadBuiltinCall(.floor),
            '^' => try out.appendDyadBuiltinCall(.null_fill_without),
            '~' => try out.appendDyadBuiltinCall(.not),
            '?' => {
                try out.appendDyadBuiltinCall(.find);
            },
            '$' => try out.appendDyadBuiltinCall(.cast),
            '*' => try out.appendShapedDyad(.mul),
            '%' => try out.appendShapedDyad(.div),
            '.' => try out.appendDot(),
            '@' => try out.appendShapedCall1(),
            ':' => try out.appendDiscard(),
            else => unreachable,
        }
    }

    fn tryParseBuiltinCompositionPrimary(self: *Compiler) KError!?ParsedPrimary {
        var builtins: [16]BuiltinId = undefined;
        var count: usize = 0;
        var index = self.index;

        while (true) {
            index = skipSpacesInSource(self.source, index);
            if (index >= self.source.len) break;
            const ch = self.source[index];
            if (ch == ':') {
                const next = skipSpacesInSource(self.source, index + 1);
                if (count == 0 or next >= self.source.len) break;
                if (self.source[next] == '-' and next + 1 < self.source.len and std.ascii.isDigit(self.source[next + 1])) break;
                if (builtinFromChar(self.source[next]) == null) break;
                index = next;
                continue;
            }
            if (ch == '-' and index + 1 < self.source.len and std.ascii.isDigit(self.source[index + 1])) break;
            const builtin = builtinFromChar(ch) orelse break;
            if (count >= builtins.len) return error.Unsupported;
            builtins[count] = builtin;
            count += 1;
            index += 1;
        }

        if (count < 2) return null;
        const end = skipSpacesInSource(self.source, index);
        if (end < self.source.len) {
            switch (self.source[end]) {
                '\'', '/', '\\', ':' => return null,
                else => {},
            }
        }
        self.index = end;

        var value = Value.builtin(builtins[count - 1]);
        var idx = count - 1;
        while (idx > 0) {
            idx -= 1;
            value = Value.closure(try self.session.allocFrozenCompositionClosure(Value.builtin(builtins[idx]), value));
        }

        return .{ .pending = .{ .const_value = value }, .form = .verbial };
    }

    fn scanParenthesizedList(self: *const Compiler) ?ParenthesizedListScan {
        if (self.index >= self.source.len or self.source[self.index] != '(') return null;

        var index = self.index + 1;
        var paren_depth: usize = 0;
        var bracket_depth: usize = 0;
        var brace_depth: usize = 0;
        var has_separator = false;
        while (index < self.source.len) : (index += 1) {
            switch (self.source[index]) {
                '"' => {
                    index = scanStringLiteralEnd(self.source, index) orelse return null;
                },
                '(' => paren_depth += 1,
                ')' => {
                    if (paren_depth != 0) {
                        paren_depth -= 1;
                        continue;
                    }
                    if (!has_separator) return null;
                    return .{ .close_index = index };
                },
                '[' => bracket_depth += 1,
                ']' => {
                    if (bracket_depth == 0) return null;
                    bracket_depth -= 1;
                },
                '{' => brace_depth += 1,
                '}' => {
                    if (brace_depth == 0) return null;
                    brace_depth -= 1;
                },
                '\n' => {
                    if (paren_depth == 0 and bracket_depth == 0 and brace_depth == 0) {
                        const next = skipSpacesInSource(self.source, index + 1);
                        if (next < self.source.len and self.source[next] != ')' and self.source[next] != ';') {
                            has_separator = true;
                        }
                    }
                },
                else => {},
            }
        }
        return null;
    }

    fn isParenthesizedListSeparator(self: *const Compiler, index: usize, paren_depth: usize, bracket_depth: usize, brace_depth: usize) bool {
        if (paren_depth != 0 or bracket_depth != 0 or brace_depth != 0) return false;
        return switch (self.source[index]) {
            '\n' => blk: {
                const next = skipSpacesInSource(self.source, index + 1);
                break :blk next < self.source.len and self.source[next] != ')' and self.source[next] != ';';
            },
            else => false,
        };
    }

    fn scanProjectionSlots(self: *const Compiler, start_index: usize) KError!ProjectionSlotSummary {
        var index = skipSpacesInSource(self.source, start_index);
        if (index >= self.source.len) return error.Parse;
        if (self.source[index] == ']') {
            return .{ .slot_count = 0, .hole_count = 0, .hole_mask = 0 };
        }

        var summary = ProjectionSlotSummary{
            .slot_count = 0,
            .hole_count = 0,
            .hole_mask = 0,
        };
        var bracket_depth: usize = 0;
        var paren_depth: usize = 0;
        var brace_depth: usize = 0;
        var slot_has_content = false;

        while (index < self.source.len) : (index += 1) {
            const ch = self.source[index];
            switch (ch) {
                '"' => {
                    slot_has_content = true;
                    index = scanStringLiteralEnd(self.source, index) orelse return error.Parse;
                },
                '[' => {
                    bracket_depth += 1;
                    slot_has_content = true;
                },
                '(' => {
                    paren_depth += 1;
                    slot_has_content = true;
                },
                '{' => {
                    brace_depth += 1;
                    slot_has_content = true;
                },
                ']' => {
                    if (bracket_depth != 0) {
                        bracket_depth -= 1;
                        slot_has_content = true;
                        continue;
                    }
                    if (summary.slot_count >= 63) return error.Unsupported;
                    if (!slot_has_content) {
                        summary.hole_mask |= (@as(u64, 1) << @intCast(summary.slot_count));
                        summary.hole_count += 1;
                    }
                    summary.slot_count += 1;
                    return summary;
                },
                ')' => {
                    if (paren_depth == 0) return error.Parse;
                    paren_depth -= 1;
                    slot_has_content = true;
                },
                '}' => {
                    if (brace_depth == 0) return error.Parse;
                    brace_depth -= 1;
                    slot_has_content = true;
                },
                ';' => {
                    if (bracket_depth == 0 and paren_depth == 0 and brace_depth == 0) {
                        if (summary.slot_count >= 63) return error.Unsupported;
                        if (!slot_has_content) {
                            summary.hole_mask |= (@as(u64, 1) << @intCast(summary.slot_count));
                            summary.hole_count += 1;
                        }
                        summary.slot_count += 1;
                        slot_has_content = false;
                        index = skipSpacesInSource(self.source, index + 1);
                        if (index >= self.source.len) return error.Parse;
                        index -= 1;
                    } else {
                        slot_has_content = true;
                    }
                },
                ' ', '\n', '\t', '\r' => {},
                else => slot_has_content = true,
            }
        }

        return error.Parse;
    }

    fn findBracketBodyEnd(self: *const Compiler, start: usize) KError!usize {
        var index = start;
        var bracket_depth: usize = 0;
        var paren_depth: usize = 0;
        var brace_depth: usize = 0;
        while (index < self.source.len) : (index += 1) {
            switch (self.source[index]) {
                '"' => {
                    index = scanStringLiteralEnd(self.source, index) orelse return error.Parse;
                },
                '[' => bracket_depth += 1,
                ']' => {
                    if (bracket_depth == 0 and paren_depth == 0 and brace_depth == 0) return index;
                    if (bracket_depth == 0) return error.Parse;
                    bracket_depth -= 1;
                },
                '(' => paren_depth += 1,
                ')' => {
                    if (paren_depth == 0) return error.Parse;
                    paren_depth -= 1;
                },
                '{' => brace_depth += 1,
                '}' => {
                    if (brace_depth == 0) return error.Parse;
                    brace_depth -= 1;
                },
                else => {},
            }
        }
        return error.Parse;
    }

    fn startsDerivedVerb(self: *const Compiler) bool {
        if (self.index >= self.source.len) return false;
        return switch (self.source[self.index]) {
            '\'', '/', '\\' => true,
            else => false,
        };
    }

    fn startsDerivedVerbAt(self: *const Compiler, index: usize) bool {
        const start = skipSpacesInSource(self.source, index);
        if (start >= self.source.len) return false;
        return switch (self.source[start]) {
            '\'', '/', '\\' => true,
            else => false,
        };
    }

    fn startsBuiltinDerivedPrimaryAt(self: *const Compiler, index: usize) bool {
        if (index >= self.source.len) return false;
        if (builtinFromChar(self.source[index]) == null) return false;
        const next = skipSpacesInSource(self.source, index + 1);
        if (next >= self.source.len) return false;
        return switch (self.source[next]) {
            '\'', '/', '\\' => true,
            else => false,
        };
    }

    fn matchDerivedVerb(self: *Compiler) ?DerivedVerbKind {
        if (self.index >= self.source.len) return null;
        return switch (self.source[self.index]) {
            '\'' => blk: {
                self.index += 1;
                self.skipSpaces();
                if (self.matchChar(':')) break :blk .each_prior;
                break :blk .each;
            },
            '/' => blk: {
                self.index += 1;
                self.skipSpaces();
                if (self.matchChar(':')) break :blk .each_right;
                break :blk .fold;
            },
            '\\' => blk: {
                self.index += 1;
                self.skipSpaces();
                if (self.matchChar(':')) break :blk .each_left;
                break :blk .scan;
            },
            else => null,
        };
    }

    fn emitBuiltinDerivedDyad(self: *Compiler, out: *CodeEmitter, builtin: BuiltinId, kind: DerivedVerbKind) KError!void {
        _ = self;
        try out.appendCallBuiltinDerived2(builtin, kind);
    }

    fn tryEmitBuiltinCall(self: *Compiler, out: *CodeEmitter, builtin: BuiltinId, argc: u8) KError!bool {
        _ = self;
        switch (argc) {
            1 => {
                if (compactMonadIdForBuiltinCall(builtin) == null) return false;
                try out.appendMonadBuiltinCall(builtin);
                return true;
            },
            2 => {
                if (compactDyadIdForBuiltinCall(builtin) == null) return false;
                try out.appendDyadBuiltinCall(builtin);
                return true;
            },
            else => return false,
        }
    }

    fn tryParseBuiltinInnerProduct(self: *Compiler) KError!?PendingPrimary {
        const reduce_ch = self.peekByte() orelse return null;
        const reduce = builtinFromChar(reduce_ch) orelse return null;
        if (!builtinSupportsInnerProductVerb(reduce)) return null;
        var next = skipSpacesInSource(self.source, self.index + 1);
        if (next >= self.source.len or self.source[next] != '/') return null;
        next = skipSpacesInSource(self.source, next + 1);
        if (next >= self.source.len) return null;
        const map_ch = self.source[next];
        const map = builtinFromChar(map_ch) orelse return null;
        if (!builtinSupportsInnerProductVerb(map)) return null;
        if (self.startsBuiltinDerivedPrimaryAt(next)) return null;
        if (self.peekPrimaryUnaryOpAt(next) != null) return null;
        self.index = skipSpacesInSource(self.source, next + 1);
        return .{ .const_value = Value.closure(try self.session.allocFrozenInnerProductClosure(reduce, map)) };
    }

    fn parseBuiltinPrimaryFromConsumedChar(self: *Compiler, ch: u8) KError!ParsedPrimary {
        _ = self;
        const builtin = builtinFromChar(ch) orelse return error.Unsupported;
        return .{ .pending = .{ .builtin = builtin }, .form = .verbial };
    }

    fn parseStringLiteralBytes(self: *Compiler) KError![]const u8 {
        if (self.peekByte() != '"') return error.Parse;
        const quote_start = self.index;
        const quote_end = scanStringLiteralEnd(self.source, quote_start) orelse return error.Parse;
        const raw = self.source[quote_start + 1 .. quote_end];
        self.index = quote_end + 1;

        if (std.mem.indexOfScalar(u8, raw, '\\') == null) return raw;

        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(self.code_allocator);
        try out.ensureTotalCapacity(self.code_allocator, raw.len);
        var idx: usize = 0;
        while (idx < raw.len) : (idx += 1) {
            const ch = raw[idx];
            if (ch != '\\') {
                try out.append(self.code_allocator, ch);
                continue;
            }
            idx += 1;
            if (idx >= raw.len) return error.Parse;
            if (raw[idx] == '"') {
                try out.append(self.code_allocator, '"');
            } else if (raw[idx] == '\\') {
                try out.append(self.code_allocator, '\\');
            } else if (raw[idx] == '0') {
                try out.append(self.code_allocator, 0);
            } else if (raw[idx] == 'n') {
                try out.append(self.code_allocator, '\n');
            } else if (raw[idx] == 'r') {
                try out.append(self.code_allocator, '\r');
            } else if (raw[idx] == 't') {
                try out.append(self.code_allocator, '\t');
            } else {
                try out.append(self.code_allocator, '\\');
                try out.append(self.code_allocator, raw[idx]);
            }
        }
        return try out.toOwnedSlice(self.code_allocator);
    }

    fn parseStringLiteralValue(self: *Compiler) KError!Value {
        const bytes = try self.parseStringLiteralBytes();
        return try self.session.frozenHostString(bytes);
    }

    fn parseSymbolLiteralValue(self: *Compiler) KError!Value {
        if (!self.matchChar('`')) return error.Parse;
        if (self.peekByte() == '"') {
            const bytes = try self.parseStringLiteralBytes();
            return try self.session.frozenHostSymbol(bytes);
        }
        const ident = self.scanIdentifier() orelse return try self.session.frozenHostSymbol("");
        return try self.session.frozenHostSymbol(ident.text);
    }

    fn parseHexLiteralValue(self: *Compiler) KError!?Value {
        if (!sourceStartsHexLiteral(self.source, self.index)) return null;

        var index = self.index + 2;
        const digits_begin = index;
        while (index < self.source.len and isHexLiteralChar(self.source[index])) : (index += 1) {}
        const digit_count = index - digits_begin;
        if (digit_count % 2 != 0) return error.Parse;

        const bytes = try self.session.allocator.alloc(u8, digit_count / 2);
        defer self.session.allocator.free(bytes);
        var out_idx: usize = 0;
        var digit_idx = digits_begin;
        while (digit_idx < index) : ({
            digit_idx += 2;
            out_idx += 1;
        }) {
            const high = hexNibble(self.source[digit_idx]) orelse return error.Parse;
            const low = hexNibble(self.source[digit_idx + 1]) orelse return error.Parse;
            bytes[out_idx] = (high << 4) | low;
        }

        self.index = skipSpacesInSource(self.source, index);
        return try self.session.frozenHostString(bytes);
    }

    fn parseLambdaSource(self: *Compiler) KError!ParsedLambda {
        var lambda = ParsedLambda{};
        lambda.source_start = self.index;
        if (self.matchChar('[')) {
            lambda.allow_implicit_params = false;
            if (!self.matchChar(']')) {
                while (true) {
                    const ident = self.scanIdentifier() orelse return error.Parse;
                    try lambda.declareParam(ident);
                    if (self.matchChar(']')) break;
                    try self.expectChar(';');
                }
            }
        }
        lambda.body_start = self.index;
        lambda.body_end = try self.findLambdaBodyEnd(lambda.body_start);
        lambda.source_end = lambda.body_end;
        self.index = skipSpacesInSource(self.source, lambda.body_end + 1);
        return lambda;
    }

    fn emitLambdaValueFromBodySource(
        self: *Compiler,
        out: *CodeEmitter,
        parent: *Scope,
        allow_implicit_params: bool,
        explicit_names: []const IdentRef,
        body_source: []const u8,
        display_source: []const u8,
    ) KError!void {
        _ = parent;
        var scope = Scope{
            .allow_implicit_params = allow_implicit_params,
        };
        defer scope.deinit(self.session.allocator);
        for (explicit_names) |ident| try scope.declareParam(ident);

        var body_storage = CodeEmitter.init(self.code_allocator);
        var lambda_scratch: ?*ScratchCode = null;
        const body: *CodeEmitter = if (self.compile_mode == .scratch) blk: {
            const scratch = try self.code_allocator.create(ScratchCode);
            scratch.reset(self.code_allocator);
            lambda_scratch = scratch;
            break :blk &scratch.instructions;
        } else blk: {
            break :blk &body_storage;
        };

        var body_compiler = try Compiler.init(self.session, body_source, self.code_allocator, self.compile_mode);
        try body_compiler.compileLambdaBodyInto(body, &scope, body_source);
        try finishCodeEmitter(body, .tail_position);

        const code = if (self.compile_mode == .scratch) blk: {
            const scratch_code = try lambda_scratch.?.finalize(scope.arity, scope.required_arity, scope.frame_slot_count);
            self.assignCodeProfile(scratch_code, .lambda, display_source);
            break :blk scratch_code;
        } else try self.finalizeCode(scope.arity, scope.required_arity, scope.frame_slot_count, body, .lambda, display_source);
        const closure = try self.code_allocator.create(Closure);
        closure.* = .{
            .header = HeapHeader.init(.closure, switch (self.compile_mode) {
                .frozen => .frozen,
                .scratch => .scratch,
            }),
            .kind = .plain,
            .code = code,
            .captures = &[_]Value{},
        };
        try self.emitConstValue(out, Value.closure(closure));
    }

    fn emitLambdaValue(self: *Compiler, out: *CodeEmitter, parent: *Scope, lambda: ParsedLambda) KError!void {
        return try self.emitLambdaValueFromBodySource(
            out,
            parent,
            lambda.allow_implicit_params,
            lambda.explicit_names[0..lambda.explicit_count],
            self.source[lambda.body_start..lambda.body_end],
            self.source[lambda.source_start..lambda.source_end],
        );
    }

    fn findLambdaBodyEnd(self: *const Compiler, start: usize) KError!usize {
        var index = start;
        var nested: usize = 0;
        while (index < self.source.len) : (index += 1) {
            switch (self.source[index]) {
                '{' => nested += 1,
                '}' => {
                    if (nested == 0) return index;
                    nested -= 1;
                },
                else => {},
            }
        }
        return error.Parse;
    }

    fn finalizeCode(
        self: *Compiler,
        arity: u8,
        required_arity: u8,
        frame_slot_count: u8,
        instructions: *const CodeEmitter,
        kind: SamplingProfileCodeKind,
        source: []const u8,
    ) !*const Code {
        const code = try duplicateCodeFromEmitter(self.code_allocator, arity, required_arity, frame_slot_count, instructions);
        self.assignCodeProfile(code, kind, source);
        return code;
    }

    fn assignCodeProfile(self: *Compiler, code: *Code, kind: SamplingProfileCodeKind, source: []const u8) void {
        const trimmed = std.mem.trim(u8, source, " \t\r\n");
        if (comptime !enable_sampling_profile) {
            code.profile_kind = if (kind == .lambda) .lambda else .none;
            code.profile_source = if (kind == .lambda) trimmed else "";
            code.profile_id = sampling_profile_no_code;
            self.session.noteCodeCompile(code);
            return;
        }
        code.profile_kind = kind;
        code.profile_source = trimmed;
        if (self.compile_mode != .frozen) {
            code.profile_id = sampling_profile_no_code;
            self.session.noteCodeCompile(code);
            return;
        }
        if (code.profile_id != sampling_profile_no_code) {
            self.session.rememberSamplingProfileCodeInfo(code.profile_id, code.profile_kind, code.profile_source);
            self.session.noteCodeCompile(code);
            return;
        }
        const id = self.session.nextSamplingProfileCodeId();
        code.profile_id = id;
        self.session.noteCodeCompile(code);
        self.session.rememberSamplingProfileCodeInfo(id, code.profile_kind, code.profile_source);
    }

    fn skipSpaces(self: *Compiler) void {
        self.index = skipSpacesInSource(self.source, self.index);
    }

    fn peekByte(self: *const Compiler) ?u8 {
        if (self.index >= self.source.len) return null;
        return self.source[self.index];
    }

    fn consumeByte(self: *Compiler) ?u8 {
        if (self.index >= self.source.len) return null;
        const ch = self.source[self.index];
        self.index += 1;
        self.skipSpaces();
        return ch;
    }

    fn matchChar(self: *Compiler, expected: u8) bool {
        if (self.index >= self.source.len or self.source[self.index] != expected) return false;
        self.index += 1;
        self.skipSpaces();
        return true;
    }

    fn expectChar(self: *Compiler, expected: u8) KError!void {
        if (!self.matchChar(expected)) return error.Parse;
    }

    fn atEnd(self: *const Compiler) bool {
        return self.index >= self.source.len;
    }

    fn globalSlot(self: *Compiler, name: []const u8) KError!u16 {
        return try self.session.internGlobalSlot(name);
    }

    fn emitPendingPrimary(self: *Compiler, out: *CodeEmitter, scope: *Scope, pending: PendingPrimary) KError!void {
        switch (pending) {
            .none => {},
            .global => |slot| try out.emitLoadGlobal(slot),
            .builtin => |id| {
                const start = try out.beginCompactPayload(.none);
                out.compactAppendConstBuiltin(start, id);
            },
            .const_value => |value| try self.emitConstValue(out, value),
            .lambda_source => |lambda| try self.emitLambdaValue(out, scope, lambda),
        }
    }

    fn compileConstantOwner(self: *const Compiler) HeapOwner {
        return switch (self.compile_mode) {
            .frozen => .frozen,
            .scratch => .scratch,
        };
    }

    fn emitConstValue(self: *Compiler, out: *CodeEmitter, value: Value) KError!void {
        _ = self;
        const start = try out.beginCompactPayload(.none);
        const pool_slot = try out.internConstant(value);
        out.compactAppendConstValueSlot(start, pool_slot);
        out.noteSimple(.{
            .const_value = .{
                .start = start,
                .end = out.compact_len,
                .value = value,
            },
        });
    }

    fn emitLiteralValue(self: *Compiler, out: *CodeEmitter, value: Value) KError!void {
        switch (value.tag()) {
            .bool => return try self.emitConstBool(out, value.asBool()),
            .float => return try self.emitConstFloat(out, value.asFloat()),
            .float32 => return try self.emitConstFloat32(out, value.asFloat32()),
            .int => {
                const int_value = value.asInt();
                if (Value.fitsInlineInt(int_value)) return try out.emitConstInt(int_value);
                return try self.emitConstValue(out, value);
            },
            else => return try self.emitConstValue(out, value),
        }
    }

    fn likelyStartsLiteralExprAt(self: *const Compiler, start: usize) bool {
        const index = skipSpacesInSource(self.source, start);
        if (index >= self.source.len) return false;
        return switch (self.source[index]) {
            '0'...'9', '"', '`' => true,
            '-' => index + 1 < self.source.len and std.ascii.isDigit(self.source[index + 1]),
            '(' => blk: {
                const inner = skipSpacesInSource(self.source, index + 1);
                if (inner >= self.source.len) break :blk false;
                if (self.source[inner] == ')') break :blk true;
                break :blk self.likelyStartsLiteralExprAt(inner);
            },
            else => false,
        };
    }

    fn tryCompileLiteralExprSlice(self: *Compiler, out: *CodeEmitter, source_slice: []const u8) KError!bool {
        var literal_compiler = try Compiler.init(
            self.session,
            source_slice,
            self.code_allocator,
            self.compile_mode,
        );
        if (!literal_compiler.likelyStartsLiteralExprAt(literal_compiler.index)) return false;
        const value = (try literal_compiler.tryParseLiteralExprValue()) orelse return false;
        if (!literal_compiler.atEnd()) return false;
        try self.emitLiteralValue(out, value);
        return true;
    }

    fn tryParseLiteralExprValue(self: *Compiler) KError!?Value {
        return try self.tryParseLiteralExprValueAllowScalarTake(false);
    }

    fn tryParseLiteralExprValueAllowScalarTake(self: *Compiler, allow_scalar_take: bool) KError!?Value {
        var left = (try self.tryParseLiteralPrimaryValue()) orelse return null;
        while (self.peekByte() == '#') {
            const saved_index = self.index;
            _ = self.consumeByte();
            const right = (try self.tryParseLiteralExprValueAllowScalarTake(true)) orelse {
                self.index = saved_index;
                return left;
            };
            const shape = (try Session.reshapeShapeSnapshotValue(left)) orelse {
                if (!allow_scalar_take or Session.scalarIntLikeValue(left) == null) {
                    self.index = saved_index;
                    return left;
                }
                left = try self.session.takeValueWithOwner(self.compileConstantOwner(), left, right);
                continue;
            };
            left = try self.session.reshapeValueWithShape(self.compileConstantOwner(), shape, right);
        }
        return left;
    }

    fn tryParseLiteralPrimaryValue(self: *Compiler) KError!?Value {
        const ch = self.peekByte() orelse return null;
        if (ch == '(') {
            if (try self.tryParseLiteralParenthesizedListValue()) |value| return value;
            const saved_index = self.index;
            _ = self.consumeByte();
            if (self.matchChar(')')) return try self.session.createOwnedHostBoxedArray(self.compileConstantOwner(), &.{});
            const first = (try self.tryParseLiteralExprValue()) orelse {
                self.index = saved_index;
                return null;
            };
            if (self.matchChar(';')) {
                var values = std.ArrayList(Value).empty;
                defer values.deinit(self.session.allocator);
                try values.append(self.session.allocator, first);
                while (true) {
                    const item = (try self.tryParseLiteralExprValue()) orelse {
                        self.index = saved_index;
                        return null;
                    };
                    try values.append(self.session.allocator, item);
                    if (self.matchChar(')')) break;
                    if (!self.matchChar(';')) {
                        self.index = saved_index;
                        return null;
                    }
                }
                return (try self.session.makeConstantArrayFromValues(self.compileConstantOwner(), values.items)) orelse {
                    self.index = saved_index;
                    return null;
                };
            }
            if (!self.matchChar(')')) {
                self.index = saved_index;
                return null;
            }
            return first;
        }
        if (ch == '"') return try self.parseStringLiteralValue();
        if (ch == '`') {
            const saved_index = self.index;
            var values = std.ArrayList(Value).empty;
            defer values.deinit(self.session.allocator);
            const first = try self.parseSymbolLiteralValue();
            try values.append(self.session.allocator, first);
            while (self.peekByte() == '`') {
                try values.append(self.session.allocator, try self.parseSymbolLiteralValue());
            }
            if (values.items.len == 1) {
                self.index = skipSpacesInSource(self.source, self.index);
                return first;
            }
            const slices = try self.session.allocator.alloc([]const u8, values.items.len);
            defer self.session.allocator.free(slices);
            for (values.items, 0..) |value, idx| slices[idx] = Session.symbolBytes(value) orelse {
                self.index = saved_index;
                return null;
            };
            return try self.session.createOwnedHostSymbolListFromSlices(self.compileConstantOwner(), slices);
        }
        if (try self.parseHexLiteralValue()) |value| return value;
        if (std.ascii.isDigit(ch) or self.peekStartsSignedNumericLiteral()) {
            return try self.parseNumericLiteralSequenceValue();
        }
        return null;
    }

    fn tryParseLiteralParenthesizedListValue(self: *Compiler) KError!?Value {
        const scan = self.scanParenthesizedList() orelse return null;
        const saved_index = self.index;
        var values = std.ArrayList(Value).empty;
        defer values.deinit(self.session.allocator);

        var item_start = skipSpacesInSource(self.source, self.index + 1);
        var index = item_start;
        var paren_depth: usize = 0;
        var bracket_depth: usize = 0;
        var brace_depth: usize = 0;

        while (index <= scan.close_index) {
            if (index == scan.close_index or self.isParenthesizedListSeparator(index, paren_depth, bracket_depth, brace_depth)) {
                const item = std.mem.trim(u8, self.source[item_start..index], " \t\r\n");
                if (item.len == 0) {
                    self.index = saved_index;
                    return null;
                }
                var item_compiler = try Compiler.init(self.session, item, self.code_allocator, self.compile_mode);
                const value = (try item_compiler.tryParseLiteralExprValue()) orelse {
                    self.index = saved_index;
                    return null;
                };
                if (!item_compiler.atEnd()) {
                    self.index = saved_index;
                    return null;
                }
                try values.append(self.session.allocator, value);
                if (index == scan.close_index) break;
                item_start = skipSpacesInSource(self.source, index + 1);
                index = item_start;
                continue;
            }

            switch (self.source[index]) {
                '"' => {
                    index = scanStringLiteralEnd(self.source, index) orelse {
                        self.index = saved_index;
                        return null;
                    };
                    if (index >= scan.close_index) {
                        self.index = saved_index;
                        return null;
                    }
                },
                '(' => paren_depth += 1,
                ')' => {
                    if (paren_depth == 0) {
                        self.index = saved_index;
                        return null;
                    }
                    paren_depth -= 1;
                },
                '[' => bracket_depth += 1,
                ']' => {
                    if (bracket_depth == 0) {
                        self.index = saved_index;
                        return null;
                    }
                    bracket_depth -= 1;
                },
                '{' => brace_depth += 1,
                '}' => {
                    if (brace_depth == 0) {
                        self.index = saved_index;
                        return null;
                    }
                    brace_depth -= 1;
                },
                else => {},
            }
            index += 1;
        }

        self.index = skipSpacesInSource(self.source, scan.close_index + 1);
        return (try self.session.makeConstantArrayFromValues(self.compileConstantOwner(), values.items)) orelse {
            self.index = saved_index;
            return null;
        };
    }

    fn peekPrimaryUnaryOp(self: *const Compiler) ?u8 {
        return self.peekPrimaryUnaryOpAt(self.index);
    }

    fn peekPrimaryUnaryOpAt(self: *const Compiler, index: usize) ?u8 {
        if (index >= self.source.len) return null;
        const ch = self.source[index];
        if (ch != '+' and ch != '-' and ch != '*' and ch != '%' and ch != '!' and ch != '&' and ch != '|' and ch != '<' and ch != '>' and ch != '~' and ch != '#' and ch != '_' and ch != '^' and ch != '=' and ch != '$' and ch != '?' and ch != '@' and ch != '.') return null;
        const next = skipSpacesInSource(self.source, index + 1);
        if (next >= self.source.len) return null;
        const follower = self.source[next];
        if (!isIdentStart(follower) and !std.ascii.isDigit(follower) and follower != '(' and follower != '{' and follower != '"' and follower != '`' and builtinFromChar(follower) == null) {
            return null;
        }
        return ch;
    }

    fn peekEnlistUnaryOpAt(self: *const Compiler, index: usize) ?u8 {
        if (index >= self.source.len or self.source[index] != ',') return null;
        const next = skipSpacesInSource(self.source, index + 1);
        if (next >= self.source.len) return null;
        const follower = self.source[next];
        if (follower == ',' or self.peekPrimaryUnaryOpAt(next) != null) return ',';
        if (follower == '$') {
            const after = skipSpacesInSource(self.source, next + 1);
            if (after < self.source.len and self.source[after] == '[') return ',';
        }
        return switch (follower) {
            '0'...'9', '(', '{', '"', '`' => ',',
            else => if (isIdentStart(follower) and builtinFromChar(follower) == null) ',' else null,
        };
    }

    fn startsJuxtapositionOperand(self: *const Compiler, left_form: ExprForm) bool {
        if (self.index >= self.source.len) return false;
        if (self.source[self.index] == '$') {
            const next = skipSpacesInSource(self.source, self.index + 1);
            if (next < self.source.len and self.source[next] == '[') return true;
        }
        if (switch (self.source[self.index]) {
            '0'...'9', '(', '{', '[', '"', '`' => true,
            else => isIdentStart(self.source[self.index]) and builtinFromChar(self.source[self.index]) == null,
        }) return true;
        if (left_form != .verbial) return false;
        if (self.startsDotAdverbPrimaryAt(self.index)) return true;
        if (self.source[self.index] == '@') {
            const next = skipSpacesInSource(self.source, self.index + 1);
            if (next < self.source.len) {
                switch (self.source[next]) {
                    '\'', '/', '\\' => return false,
                    else => {},
                }
            }
        }
        if (self.startsBuiltinDerivedPrimaryAt(self.index)) return true;
        const op = self.peekPrimaryUnaryOp() orelse self.peekEnlistUnaryOpAt(self.index) orelse return false;
        return op != '.' and op != '@';
    }

    fn scanIdentifierAt(self: *const Compiler, start: usize) ?ScannedIdent {
        const end = scanIdentifierTextEnd(self.source, start) orelse return null;
        const text = self.source[start..end];
        return .{
            .ident = identRefFromText(text),
            .next_index = end,
        };
    }

    fn scanIdentifierPathAt(self: *const Compiler, start: usize) ?ScannedIdent {
        const end = scanIdentifierPathTextEnd(self.source, start) orelse return null;
        const text = self.source[start..end];
        return .{
            .ident = identRefFromText(text),
            .next_index = end,
        };
    }

    fn scanIdentifier(self: *Compiler) ?IdentRef {
        const scanned = self.scanIdentifierAt(self.index) orelse return null;
        self.index = skipSpacesInSource(self.source, scanned.next_index);
        return scanned.ident;
    }

    fn scanIdentifierPath(self: *Compiler) ?IdentRef {
        const scanned = self.scanIdentifierPathAt(self.index) orelse return null;
        self.index = skipSpacesInSource(self.source, scanned.next_index);
        return scanned.ident;
    }

    fn peekStartsSignedNumericLiteral(self: *const Compiler) bool {
        if (self.index >= self.source.len or self.source[self.index] != '-') return false;
        const next = self.index + 1;
        return next < self.source.len and std.ascii.isDigit(self.source[next]);
    }

    fn emitConstFloat(self: *Compiler, out: *CodeEmitter, value: f64) KError!void {
        const start = try out.beginCompactPayload(.none);
        const pool_slot = try out.internConstant(try self.session.ownedConstantFloat(
            self.code_allocator,
            switch (self.compile_mode) {
                .frozen => .frozen,
                .scratch => .scratch,
            },
            value,
        ));
        out.compactAppendConstValueSlot(start, pool_slot);
        out.noteSimple(.{
            .const_value = .{
                .start = start,
                .end = out.compact_len,
                .value = out.constantAt(pool_slot),
            },
        });
    }

    fn emitConstFloat32(self: *Compiler, out: *CodeEmitter, value: f32) KError!void {
        const start = try out.beginCompactPayload(.none);
        const pool_slot = try out.internConstant(try self.session.ownedConstantFloat32(
            self.code_allocator,
            switch (self.compile_mode) {
                .frozen => .frozen,
                .scratch => .scratch,
            },
            value,
        ));
        out.compactAppendConstValueSlot(start, pool_slot);
        out.noteSimple(.{
            .const_value = .{
                .start = start,
                .end = out.compact_len,
                .value = out.constantAt(pool_slot),
            },
        });
    }

    fn emitConstBool(self: *Compiler, out: *CodeEmitter, value: bool) KError!void {
        _ = self;
        const start = out.compact_len;
        try out.emitConstBoolRaw(value);
        out.noteSimple(.{
            .const_value = .{
                .start = start,
                .end = out.compact_len,
                .value = Value.fromBool(value),
            },
        });
    }

    fn numericLiteralValue(self: *Compiler, literal: NumericLiteral) KError!Value {
        return switch (literal) {
            .bool => |value| Value.fromBool(value),
            .float => |value| try self.session.ownedConstantFloat(self.code_allocator, self.compileConstantOwner(), value),
            .float32 => |value| try self.session.ownedConstantFloat32(self.code_allocator, self.compileConstantOwner(), value),
            .int => |value| try self.session.ownedConstantInt(self.code_allocator, self.compileConstantOwner(), value),
        };
    }

    fn numericLiteralSequenceToValue(self: *Compiler, literals: []const NumericLiteral) KError!Value {
        if (literals.len == 0) return error.Parse;
        if (literals.len == 1) return try self.numericLiteralValue(literals[0]);

        var values = try self.session.allocator.alloc(Value, literals.len);
        defer self.session.allocator.free(values);

        var saw_float32 = false;
        var saw_float64 = false;
        for (literals, 0..) |literal, idx| {
            switch (literal) {
                .float => saw_float64 = true,
                .float32 => saw_float32 = true,
                else => {},
            }
            values[idx] = try self.numericLiteralValue(literal);
        }

        const owner = self.compileConstantOwner();
        if (saw_float64) return try self.session.createOwnedHostFloatArrayFromValues(owner, values);
        if (saw_float32) return try self.session.createOwnedHostFloat32ArrayFromValues(owner, values);
        return try self.session.createOwnedHostIntArrayFromValues(owner, values);
    }

    fn parseNumericLiteralSequenceValue(self: *Compiler) KError!?Value {
        var literals = std.ArrayList(NumericLiteral).empty;
        defer literals.deinit(self.session.allocator);

        var index = self.index;
        while (true) {
            index = skipSpacesInSource(self.source, index);
            if (index >= self.source.len) break;

            const signed_continuation = literals.items.len == 0 or (index > 0 and std.ascii.isWhitespace(self.source[index - 1]));
            if (signed_continuation and index + 1 < self.source.len and self.source[index] == '-' and std.ascii.isDigit(self.source[index + 1])) {
                const scanned = scanNumericLiteral(self.source, index + 1) orelse break;
                switch (scanned.literal) {
                    .bool => break,
                    .float => |value| try literals.append(self.session.allocator, .{ .float = -value }),
                    .float32 => |value| try literals.append(self.session.allocator, .{ .float32 = -value }),
                    .int => |value| try literals.append(self.session.allocator, .{ .int = try checkedIntOp(.sub, 0, value) }),
                }
                index = scanned.next;
                continue;
            }

            if (scanBoolDigitVectorLiteral(self.source, index)) |bool_scan| {
                for (self.source[index..bool_scan.digits_end]) |digit| {
                    try literals.append(self.session.allocator, .{ .bool = digit == '1' });
                }
                index = skipSpacesInSource(self.source, bool_scan.next);
                continue;
            }

            const scanned = scanNumericLiteral(self.source, index) orelse break;
            try literals.append(self.session.allocator, scanned.literal);
            index = scanned.next;
        }

        if (literals.items.len == 0) return null;
        self.index = skipSpacesInSource(self.source, index);
        return try self.numericLiteralSequenceToValue(literals.items);
    }
};

fn scanBoolDigitVectorLiteral(source: []const u8, start: usize) ?struct { digits_end: usize, next: usize } {
    if (start >= source.len or !std.ascii.isDigit(source[start])) return null;

    var index = start;
    var digit_count: usize = 0;
    while (index < source.len and std.ascii.isDigit(source[index])) : (index += 1) {
        const ch = source[index];
        if (ch != '0' and ch != '1') return null;
        digit_count += 1;
    }
    if (digit_count <= 1 or index >= source.len or std.ascii.toLower(source[index]) != 'b') return null;
    return .{
        .digits_end = index,
        .next = index + 1,
    };
}

fn nextTopLevelStatement(source: []const u8, cursor: *usize) ?[]const u8 {
    var start = cursor.*;
    while (start < source.len and (source[start] == ' ' or source[start] == '\t' or source[start] == '\r' or source[start] == '\n')) : (start += 1) {}
    if (start >= source.len) {
        cursor.* = start;
        return null;
    }

    var index = start;
    var paren_depth: usize = 0;
    var bracket_depth: usize = 0;
    var brace_depth: usize = 0;
    while (index < source.len) : (index += 1) {
        switch (source[index]) {
            '"' => {
                index = scanStringLiteralEnd(source, index) orelse break;
            },
            '(' => paren_depth += 1,
            ')' => {
                if (paren_depth != 0) paren_depth -= 1;
            },
            '[' => bracket_depth += 1,
            ']' => {
                if (bracket_depth != 0) bracket_depth -= 1;
            },
            '{' => brace_depth += 1,
            '}' => {
                if (brace_depth != 0) brace_depth -= 1;
            },
            '\n', ';' => {
                if (paren_depth == 0 and bracket_depth == 0 and brace_depth == 0) {
                    const statement = std.mem.trim(u8, source[start..index], " \t\r\n");
                    cursor.* = index + 1;
                    if (statement.len == 0) return nextTopLevelStatement(source, cursor);
                    return statement;
                }
            },
            else => {},
        }
    }

    cursor.* = index;
    const statement = std.mem.trim(u8, source[start..index], " \t\r\n");
    if (statement.len == 0) return null;
    return statement;
}

fn splitLambdaBodyHead(source: []const u8) ?BodyStatementSplit {
    const start = skipSpacesInSource(source, 0);
    if (start >= source.len) return null;

    var index = start;
    var paren_depth: usize = 0;
    var bracket_depth: usize = 0;
    var brace_depth: usize = 0;
    while (index < source.len) : (index += 1) {
        switch (source[index]) {
            '"' => {
                index = scanStringLiteralEnd(source, index) orelse return null;
            },
            '(' => paren_depth += 1,
            ')' => {
                if (paren_depth == 0) return null;
                paren_depth -= 1;
            },
            '[' => bracket_depth += 1,
            ']' => {
                if (bracket_depth == 0) return null;
                bracket_depth -= 1;
            },
            '{' => brace_depth += 1,
            '}' => {
                if (brace_depth == 0) return null;
                brace_depth -= 1;
            },
            ';' => {
                if (paren_depth == 0 and bracket_depth == 0 and brace_depth == 0) {
                    const head = std.mem.trim(u8, source[start..index], " \t\r\n");
                    if (head.len == 0) return null;
                    const tail_start = skipSpacesInSource(source, index + 1);
                    if (tail_start >= source.len) return null;
                    const tail = std.mem.trim(u8, source[tail_start..], " \t\r\n");
                    if (tail.len == 0) return null;
                    return .{
                        .head = head,
                        .tail = tail,
                    };
                }
            },
            else => {},
        }
    }

    const head = std.mem.trim(u8, source[start..], " \t\r\n");
    if (head.len == 0) return null;
    return .{
        .head = head,
        .tail = null,
    };
}

fn splitWholeCondSpecialForm(source: []const u8) ?ConditionalSlices {
    const text = std.mem.trim(u8, source, " \t\r\n");
    if (text.len < 4 or text[0] != '$' or text[1] != '[') return null;

    var part_start = skipSpacesInSource(text, 2);
    var part_index: u8 = 0;
    var parts: [3][]const u8 = undefined;
    var index = part_start;
    var paren_depth: usize = 0;
    var bracket_depth: usize = 0;
    var brace_depth: usize = 0;

    while (index < text.len) : (index += 1) {
        switch (text[index]) {
            '"' => {
                index = scanStringLiteralEnd(text, index) orelse return null;
            },
            '(' => paren_depth += 1,
            ')' => {
                if (paren_depth == 0) return null;
                paren_depth -= 1;
            },
            '[' => bracket_depth += 1,
            ']' => {
                if (bracket_depth != 0) {
                    bracket_depth -= 1;
                    continue;
                }
                if (paren_depth != 0 or brace_depth != 0 or part_index != 2) return null;
                const part = std.mem.trim(u8, text[part_start..index], " \t\r\n");
                if (part.len == 0) return null;
                parts[part_index] = part;
                if (skipSpacesInSource(text, index + 1) != text.len) return null;
                return .{
                    .condition = parts[0],
                    .then_branch = parts[1],
                    .else_branch = parts[2],
                };
            },
            '{' => brace_depth += 1,
            '}' => {
                if (brace_depth == 0) return null;
                brace_depth -= 1;
            },
            ';' => {
                if (paren_depth == 0 and bracket_depth == 0 and brace_depth == 0) {
                    if (part_index >= 2) return null;
                    const part = std.mem.trim(u8, text[part_start..index], " \t\r\n");
                    if (part.len == 0) return null;
                    parts[part_index] = part;
                    part_index += 1;
                    part_start = skipSpacesInSource(text, index + 1);
                    index = part_start;
                    if (index >= text.len) return null;
                    index -= 1;
                }
            },
            else => {},
        }
    }

    return null;
}

fn builtinFromChar(ch: u8) ?BuiltinId {
    return switch (ch) {
        ':' => .identity,
        '+' => .add,
        '-' => .sub,
        '*' => .mul,
        '%' => .div,
        '!' => .iota,
        '&' => .minimum,
        '|' => .maximum,
        '<' => .less,
        '>' => .more,
        '~' => .not,
        ',' => .concat,
        '#' => .count,
        '_' => .floor,
        '^' => .null_fill_without,
        '=' => .equal,
        '$' => .stringify,
        '@' => .type_of,
        '?' => .unique,
        else => null,
    };
}

fn builtinFromDyadChar(ch: u8) ?BuiltinId {
    return switch (ch) {
        ':' => .identity,
        '+' => .add,
        '-' => .sub,
        '*' => .mul,
        '%' => .div,
        '!' => .iota,
        '&' => .minimum,
        '|' => .maximum,
        '<' => .less,
        '>' => .more,
        '~' => .not,
        ',' => .concat,
        '#' => .take,
        '_' => .drop,
        '^' => .null_fill_without,
        '=' => .equal,
        '$' => .cast,
        '?' => .find,
        '@' => .apply,
        else => null,
    };
}

fn builtinSupportsInnerProductVerb(builtin: BuiltinId) bool {
    return switch (builtin) {
        .add, .sub, .mul, .div, .minimum, .maximum, .less, .more, .concat, .count, .floor, .equal => true,
        .identity, .apply, .iota, .not, .reverse, .grade_up, .grade_down, .stringify, .type_of, .bytes, .utf8, .char, .unique, .eval_string, .cast, .contains, .split, .join, .find, .grad, .valuegrad, .prng, .open, .close, .read, .write, .flush, .run, .stat, .load, .save, .sql, .exec, .register, .rotcache, .rotcacheupdate, .rotcacheview, .rope, .ropeflat, .ropecisflat, .rmsnorm, .layernorm, .gelu, .geluapprox, .mlpdense, .conv2d, .convtranspose2d, .upsamplenearest2d, .groupnorm, .softmax, .sdpa, .sam3boxrpb, .sdpamask, .sdpaflat, .exp, .log, .sin, .cos, .tanh, .sigmoid, .take, .drop, .reshape, .null_fill_without, .pow => false,
    };
}

fn builtinAvailable(op: BuiltinId) bool {
    return switch (op) {
        .load => runtime_has_load_builtin,
        .save => runtime_has_save_builtin,
        .sql => runtime_has_sql_builtin,
        .exec => runtime_has_exec_builtin,
        .register => runtime_has_register_builtin,
        .rotcache,
        .rotcacheupdate,
        .rotcacheview,
        .rope,
        .ropeflat,
        .ropecisflat,
        .rmsnorm,
        .layernorm,
        .gelu,
        .geluapprox,
        .mlpdense,
        .conv2d,
        .convtranspose2d,
        .upsamplenearest2d,
        .groupnorm,
        .softmax,
        .sdpa,
        .sam3boxrpb,
        .sdpamask,
        .sdpaflat,
        => runtime_has_mlx_builtin_surface,
        else => true,
    };
}

fn builtinFromName(name: []const u8) ?BuiltinId {
    if (std.mem.eql(u8, name, "sqrt")) return .div;
    if (std.mem.eql(u8, name, "pow")) return .pow;
    if (std.mem.eql(u8, name, "exp")) return .exp;
    if (std.mem.eql(u8, name, "log")) return .log;
    if (std.mem.eql(u8, name, "sin")) return .sin;
    if (std.mem.eql(u8, name, "cos")) return .cos;
    if (std.mem.eql(u8, name, "tanh")) return .tanh;
    if (std.mem.eql(u8, name, "sigmoid")) return .sigmoid;
    if (std.mem.eql(u8, name, "bytes")) return .bytes;
    if (std.mem.eql(u8, name, "utf8")) return .utf8;
    if (std.mem.eql(u8, name, "char")) return .char;
    if (std.mem.eql(u8, name, "null")) return .null_fill_without;
    if (std.mem.eql(u8, name, "fill")) return .null_fill_without;
    if (std.mem.eql(u8, name, "without")) return .null_fill_without;
    if (std.mem.eql(u8, name, "except")) return .null_fill_without;
    if (std.mem.eql(u8, name, "grad")) return .grad;
    if (std.mem.eql(u8, name, "valuegrad")) return .valuegrad;
    if (std.mem.eql(u8, name, "prng")) return .prng;
    if (std.mem.eql(u8, name, "open")) return .open;
    if (std.mem.eql(u8, name, "close")) return .close;
    if (std.mem.eql(u8, name, "read")) return .read;
    if (std.mem.eql(u8, name, "write")) return .write;
    if (std.mem.eql(u8, name, "flush")) return .flush;
    if (std.mem.eql(u8, name, "run")) return .run;
    if (std.mem.eql(u8, name, "stat")) return .stat;
    if (comptime runtime_has_load_builtin) {
        if (std.mem.eql(u8, name, "load")) return .load;
    }
    if (comptime runtime_has_save_builtin) {
        if (std.mem.eql(u8, name, "save")) return .save;
    }
    if (comptime runtime_has_sql_builtin) {
        if (std.mem.eql(u8, name, "sql")) return .sql;
    }
    if (comptime runtime_has_exec_builtin) {
        if (std.mem.eql(u8, name, "exec")) return .exec;
    }
    if (comptime runtime_has_register_builtin) {
        if (std.mem.eql(u8, name, "register")) return .register;
    }
    if (comptime runtime_has_mlx_builtin_surface) {
        if (std.mem.eql(u8, name, "rotcache")) return .rotcache;
        if (std.mem.eql(u8, name, "rotcacheupdate")) return .rotcacheupdate;
        if (std.mem.eql(u8, name, "rotcacheview")) return .rotcacheview;
        if (std.mem.eql(u8, name, "rope")) return .rope;
        if (std.mem.eql(u8, name, "ropeflat")) return .ropeflat;
        if (std.mem.eql(u8, name, "ropecisflat")) return .ropecisflat;
        if (std.mem.eql(u8, name, "rmsnorm")) return .rmsnorm;
        if (std.mem.eql(u8, name, "layernorm")) return .layernorm;
        if (std.mem.eql(u8, name, "gelu")) return .gelu;
        if (std.mem.eql(u8, name, "geluapprox")) return .geluapprox;
        if (std.mem.eql(u8, name, "mlpdense")) return .mlpdense;
        if (std.mem.eql(u8, name, "conv2d")) return .conv2d;
        if (std.mem.eql(u8, name, "convtranspose2d")) return .convtranspose2d;
        if (std.mem.eql(u8, name, "upsamplenearest2d")) return .upsamplenearest2d;
        if (std.mem.eql(u8, name, "groupnorm")) return .groupnorm;
        if (std.mem.eql(u8, name, "softmax")) return .softmax;
        if (std.mem.eql(u8, name, "sdpa")) return .sdpa;
        if (std.mem.eql(u8, name, "sam3boxrpb")) return .sam3boxrpb;
        if (std.mem.eql(u8, name, "sdpamask")) return .sdpamask;
        if (std.mem.eql(u8, name, "sdpaflat")) return .sdpaflat;
    }
    return null;
}
